  'profit': Color(0xFFD0453A), // 利润 红
  'revenue': Color(0xFFE8A23A), // 收入 琥珀
  'gmv': Color(0xFF22A699), // GMV 青
  'totalCost': Color(0xFF9A93B0), // 成本 灰紫
  'costTotal': Color(0xFF9A93B0),
};
