/// 一级宽屏（≥ 960）：日周月季年并进顶栏同一行；窄屏仍是第二行。
const double lighthouseTopBandInlinePeriodMinWidth = 960;

/// 顶部日周月季年那条胶囊的描边：和底部 App 金刚位胶囊同一道渐变
/// （浅紫 → 品牌紫 → 深紫 → 淡紫，1.5px）。一上一下两颗同款胶囊，把整屏框起来。
// ignore: unused_element
class _LhCapsuleGradientBorder extends CustomPainter {
  const _LhCapsuleGradientBorder();

  static const double width = 1.5;
  static const _gradient = LinearGradient(
    begin: Alignment.topLeft,
    end: Alignment.bottomRight,
    colors: [
      Color(0xFFD4C4F5),
      DunesColors.brandPurple,
      DunesColors.brandPurpleDeep,
      DunesColors.brandPurpleLine,
    ],
    stops: [0.0, 0.38, 0.72, 1.0],
  );

  @override
  void paint(Canvas canvas, Size size) {
    const inset = width / 2;
    final rect = Rect.fromLTWH(inset, inset, size.width - width, size.height - width);
    final rrect = RRect.fromRectAndRadius(rect, Radius.circular(rect.height / 2));
    canvas.drawRRect(
      rrect,
      Paint()
        ..style = PaintingStyle.stroke
        ..strokeWidth = width
        ..shader = _gradient.createShader(Offset.zero & size),
    );
  }

  @override
  bool shouldRepaint(covariant _LhCapsuleGradientBorder oldDelegate) => false;
}

class _LhAppBrandMark extends StatelessWidget {
  const _LhAppBrandMark({this.size = 24});

  final double size;

  @override
  Widget build(BuildContext context) {
    return Container(
      width: size,
      height: size,
      clipBehavior: Clip.antiAlias,
      decoration: BoxDecoration(
        borderRadius: BorderRadius.circular(size * 0.3),
        gradient: LinearGradient(
          begin: Alignment.topLeft,
          end: Alignment.bottomRight,
          colors: [
            DunesColors.resolve(
              context,
              _LhPlum.deep,
              role: DunesColorRole.surface,
            ),
            DunesColors.resolve(
              context,
              _LhPlum.primary,
              role: DunesColorRole.surface,
            ),
          ],
        ),
        boxShadow: [
          BoxShadow(
            color: _LhPlum.deep.withAlpha(60),
            blurRadius: 6,
            spreadRadius: -1,
            offset: const Offset(0, 2),
          ),
        ],
      ),
      child: const CustomPaint(painter: _LhBrandMarkPainter()),
    );
  }
}

class _LhBrandMarkPainter extends CustomPainter {
  const _LhBrandMarkPainter();

  @override
  void paint(Canvas canvas, Size size) {
    // 所有坐标按 24 单位的设计稿写，再等比缩放 —— 换尺寸不用重调数字。
    final s = math.min(size.width, size.height);
    double u(double v) => v / 24 * s;

    // ① 顶部高光：实色面不至于是一块平板漆
    // 本文件只 show 了 dart:ui 的 FontFeature，用 painting 层的
    // LinearGradient.createShader 拿 shader，不为一处高光去改顶部 import。
    final sheenRect = Rect.fromLTWH(0, 0, size.width, size.height * 0.55);
    canvas.drawRect(
      sheenRect,
      Paint()
        ..shader = LinearGradient(
          begin: Alignment.topCenter,
          end: Alignment.bottomCenter,
          colors: [
            Colors.white.withValues(alpha: 0.20),
            Colors.white.withValues(alpha: 0.0),
          ],
        ).createShader(sheenRect),
    );

    // ② 光束：从灯位向右张开的楔形，靠透明度分出内芯和外缘
    final lamp = Offset(u(5.9), u(5.9));
    final beam = Path()
      ..moveTo(lamp.dx, lamp.dy)
      ..lineTo(u(23), u(2.2))
      ..lineTo(u(23), u(10.4))
      ..close();
    canvas.drawPath(
      beam,
      Paint()..color = Colors.white.withValues(alpha: 0.22),
    );
    final core = Path()
      ..moveTo(lamp.dx, lamp.dy)
      ..lineTo(u(23), u(4.4))
      ..lineTo(u(23), u(7.0))
      ..close();
    canvas.drawPath(
      core,
      Paint()..color = Colors.white.withValues(alpha: 0.34),
    );

    // ③ 灯：柔光 + 实心点
    canvas.drawCircle(
      lamp,
      u(2.9),
      Paint()
        ..color = Colors.white.withValues(alpha: 0.30)
        ..maskFilter = MaskFilter.blur(BlurStyle.normal, u(1.8)),
    );
    canvas.drawCircle(lamp, u(1.75), Paint()..color = Colors.white);

    // ④ 被照亮的数据：三根递增的柱，最高那根正好探进光束里
    final bar = Paint()..color = Colors.white;
    void column(double left, double height) {
      canvas.drawRRect(
        RRect.fromRectAndRadius(
          Rect.fromLTWH(u(left), u(18.6) - u(height), u(3.0), u(height)),
          Radius.circular(u(1.5)),
        ),
        bar,
      );
    }

    column(5.0, 5.0);
    column(9.8, 8.2);
    column(14.6, 11.6);
  }

  @override
  bool shouldRepaint(covariant _LhBrandMarkPainter oldDelegate) => false;
}

// ═════════════════════════════════════════════════════════════════════════════
// 利润恒等式三主角色板 —— 收入 = 成本合计 + 净利润
//
//   三个指标是同一条恒等式上的三个角色，不是三个并列指标，所以用
//   「进项 / 支出 / 结果」三色编码，其余指标一律保持墨色。
//   收入 = 冷蓝（钱进来）· 成本合计 = 琥珀（钱出去）· 净利润 = 深紫（剩下的）。
//   净利润落在页面主色族上，视觉上它就是链路终点。
//
//   ROI 保持铜色不动 —— 它是效率结论，不在这条加法链上，不能混进来。
// ═════════════════════════════════════════════════════════════════════════════
class _LhPnlAccent {
  const _LhPnlAccent(this.bar, this.label, this.number);
  final Color bar;
  final Color label;
  final Color number;
}

class _LhPnl {
  _LhPnl._();

  // 收入 = 进项
  static const Color revenueBar = Color(0xFF185FA5);
  static const Color revenueNum = Color(0xFF0C447C);
  static const Color revenueFill = Color(0xFFE6F1FB);
  static const Color revenueEdge = Color(0xFF85B7EB);

  // 成本合计 = 支出
  static const Color costBar = Color(0xFF854F0B);
  static const Color costNum = Color(0xFF633806);
  static const Color costFill = Color(0xFFFAEEDA);
  static const Color costEdge = Color(0xFFEF9F27);

  // 净利润 = 结果
  static const Color netBar = Color(0xFF534AB7);
  static const Color netNum = Color(0xFF3C3489);
  static const Color netFill = Color(0xFFEEEDFE);
  static const Color netEdge = Color(0xFFAFA9EC);

  static const _LhPnlAccent revenue = _LhPnlAccent(
    revenueBar,
    revenueBar,
    revenueNum,
  );
  static const _LhPnlAccent cost = _LhPnlAccent(costBar, costBar, costNum);
  static const _LhPnlAccent net = _LhPnlAccent(netBar, netBar, netNum);

  /// keyId → accent；不在恒等式上的指标返回 null。
  /// totalCost / costTotal 是同一口径的两个 key 名，都要认。
  static _LhPnlAccent? accentFor(String keyId) {
    switch (keyId) {
      case 'revenue':
        return revenue;
      case 'totalCost':
      case 'costTotal':
        return cost;
      case 'netProfit':
        return net;
      default:
        return null;
    }
  }

  static bool isIdentityKey(String k) => accentFor(k) != null;
}

// ═════════════════════════════════════════════════════════════════════════════
// AI 解读 —— 一级页面 hero 与列表之间的「这些数说明什么」
//
//   设计前提：每条结论必须带证据数字 + 下钻入口。
//   指标产品里的 AI 总结最常见的死法是「整体表现良好，建议关注成本」——
//   没数字、点不动，看两次就没人看了。所以模型层强制每条都带 evidence 和 drill。
//
//   spans 里带色的片段 = 指标名或数字，一律走 mono + w600，色沿用 _LhPnl 三色，
//   不再发明第二套编码。tone 只编码严重度，走左侧 2px 竖条。
// ═════════════════════════════════════════════════════════════════════════════
enum _LhAiTone { risk, watch, opportunity, neutral }

Color _lhAiToneBar(_LhAiTone t) {
  switch (t) {
    case _LhAiTone.risk:
      return const Color(0xFFA32D2D);
    case _LhAiTone.watch:
      return _LhPnl.costBar;
    case _LhAiTone.opportunity:
      return _LhPnl.revenueBar;
    case _LhAiTone.neutral:
      return const Color(0xFFB4B2A9);
  }
}

class _LhAiEvidence {
  const _LhAiEvidence(this.label, this.value);
  final String label;
  final String value;
}

class _LhAiInsight {
  const _LhAiInsight({
    required this.tone,
    required this.spans,
    this.evidence = const <_LhAiEvidence>[],
    this.drill,
  });

  final _LhAiTone tone;

  /// 富文本片段。color == null → 正文墨色 sans；color != null → 语义色 mono w600。
  /// 后端接进来时把 text 里的 {metric} 占位按 _LhPnl.accentFor 展开成同样结构。
  final List<({String text, Color? color})> spans;
  final List<_LhAiEvidence> evidence;
  final VoidCallback? drill;
}

class _LhAiSummary {
  const _LhAiSummary({
    required this.items,
    required this.generatedAt,
    this.degraded = false,
  });

  final List<_LhAiInsight> items;
  final DateTime generatedAt;

  /// true = 后端 LLM 未出结果，走的规则模板。前端据此把标题从「AI 解读」换成「要点」。
  final bool degraded;
}

/// 主分段条单元格语气：维度切换 / 板块态左侧锚点 / 右侧板块筛选
enum _SegmentTone { dim, anchor, group, subgroup }

/// Row 1 = large (dim tabs), Row 2 = medium (groups).
/// Row 3 / Row 4 用独立的 chip widgets, 不走 _segmentCell.
enum _SegmentSize { large, medium }

// Hero 语义色：核销规模 / 已核销利差 全页统一
const String _kHeroTermVerifiedScale = '核销规模';
const String _kHeroTermVerifiedSpread = '已核销利差';
const Color _kHeroVerifiedScaleColor = LhColors.product;
const Color _kHeroVerifiedSpreadColor = LhColors.ink;

TextStyle _heroSemanticStyle({
  BuildContext? context,
  required Color color,
  double size = 7.5,
  FontWeight weight = FontWeight.w500,
  double letterSpacing = 0.3,
  double? height,
}) => LhTypography.mono(
  context: context,
  size: size,
  color: color,
  weight: weight,
  letterSpacing: letterSpacing,
  height: height,
);

List<InlineSpan> _heroSemanticSpans(
  String text, {
  Color baseColor = LhColors.mute2,
  double size = 7.5,
  FontWeight baseWeight = FontWeight.w500,
  FontWeight termWeight = FontWeight.w600,
  double letterSpacing = 0.3,
  double? height,
}) {
  final spans = <InlineSpan>[];
  var i = 0;
  while (i < text.length) {
    final scaleAt = text.indexOf(_kHeroTermVerifiedScale, i);
    final spreadAt = text.indexOf(_kHeroTermVerifiedSpread, i);

    int? nextAt;
    String? term;
    Color? termColor;
    void consider(int at, String t, Color c) {
      if (at < 0) return;
      if (nextAt == null ||
          at < nextAt! ||
          (at == nextAt && t.length > term!.length)) {
        nextAt = at;
        term = t;
        termColor = c;
      }
    }

    consider(scaleAt, _kHeroTermVerifiedScale, _kHeroVerifiedScaleColor);
    consider(spreadAt, _kHeroTermVerifiedSpread, _kHeroVerifiedSpreadColor);

    if (nextAt == null) {
      spans.add(
        TextSpan(
          text: text.substring(i),
          style: _heroSemanticStyle(
            color: baseColor,
            size: size,
            weight: baseWeight,
            letterSpacing: letterSpacing,
            height: height,
          ),
        ),
      );
      break;
    }

    if (nextAt! > i) {
      spans.add(
        TextSpan(
          text: text.substring(i, nextAt),
          style: _heroSemanticStyle(
            color: baseColor,
            size: size,
            weight: baseWeight,
            letterSpacing: letterSpacing,
            height: height,
          ),
        ),
      );
    }

    spans.add(
      TextSpan(
        text: term,
        style: _heroSemanticStyle(
          color: termColor!,
          size: size,
          weight: termWeight,
          letterSpacing: letterSpacing,
          height: height,
        ),
      ),
    );
    i = nextAt! + term!.length;
  }
  return spans;
}

Widget _heroSemanticText(
  String text, {
  Key? key,
  Color baseColor = LhColors.mute2,
  double size = 7.5,
  FontWeight baseWeight = FontWeight.w500,
  FontWeight termWeight = FontWeight.w600,
  double letterSpacing = 0.3,
  double? height,
  int maxLines = 1,
  TextOverflow overflow = TextOverflow.ellipsis,
}) {
  return LhScrollRichText(
    key: key,
    text: TextSpan(
      children: _heroSemanticSpans(
        text,
        baseColor: baseColor,
        size: size,
        baseWeight: baseWeight,
        termWeight: termWeight,
        letterSpacing: letterSpacing,
        height: height,
      ),
    ),
    maxLines: maxLines,
    overflow: overflow,
  );
}

// ═════════════════════════════════════════════════════════════════════════════
// _FlowRole — 损益推演流里节点的三种角色
//   anchor       起点 (核销规模): 深色左边框, 白底
//   intermediate 中间态 (收入 / 利润): 铜色左边框, copperSoft 底
//   result       终点 (效率): 3px 违背色左边框, 白底
// ═════════════════════════════════════════════════════════════════════════════
enum _FlowRole { anchor, intermediate, result }

// ═════════════════════════════════════════════════════════════════════════════
// _LhBiz — 业务口径静态方法 (对齐老板会议定义 + 穆穆整理的公式)
//   销售规模 = 下单张数 × 面值
//   核销规模 = 核销张数 × 面值
//   预收    = 销售规模 − 核销规模
//   收入    = 核销规模 × 利差率
//   经营成本 = 业务成本（账单三级 BUSINESS_COST）
//   成本合计 = 库字段 total_cost
//   项目成本 = 库字段 cost_gross_profit（利润对应的成本）
//   利润    = 库字段 gross_profit（JSON: profit）
//   净利    = 库字段 profit（JSON: netProfit）
//   效率    = 利润 ÷ 锚点(优先核销)
// ═════════════════════════════════════════════════════════════════════════════
class _LhBiz {
  const _LhBiz._();

  /// 拿到"锚点值": 核销口径读 verifiedSales(=verify_amount)；销售口径读 sales
  static double anchorValue(
    Map<String, dynamic> row, {
    _LhAnchor pref = _LhAnchor.verified,
  }) {
    final v =
        (row['verifiedSales'] as num?)?.toDouble() ??
        (row['woa'] as num?)?.toDouble() ??
        0;
    final s = (row['sales'] as num?)?.toDouble() ?? 0;
    if (pref == _LhAnchor.verified) return v;
    return s > 0 ? s : v;
  }

  /// 效率(毛利率) = 利润 ÷ 锚点 × 100%
  static double efficiency(
    Map<String, dynamic> row, {
    _LhAnchor pref = _LhAnchor.verified,
  }) {
    final anchor = anchorValue(row, pref: pref);
    if (anchor <= 0) return 0;
    final profit = (row['profit'] as num?)?.toDouble() ?? 0;
    return profit / anchor * 100;
  }
}

