// ─────────────────────────────────────────────────────────────────────────────
// Trend chart — 3-series (收入/成本/利润), period-aware, tap+drag to locate
// Performance: data + bounds cached in State; lines painter is RepaintBoundary'd
// so drag only repaints the cheap overlay (dashed guideline + 3 markers).
// ─────────────────────────────────────────────────────────────────────────────
class _TrendSeries {
  const _TrendSeries({
    required this.revenue,
    required this.cost,
    required this.profit,
    this.scale = const <double>[],
    this.scaleAlt = const <double>[],
    this.costAlt = const <double>[],
    this.stock = const <double>[],
  });
  final List<double> revenue;
  final List<double> cost;
  final List<double> profit;

  /// 另一口径的规模（anchor 是核销时这里是销售，反之亦然）。
  /// 与 [scale] 共用一个 Y 值域 —— 两者同单位、可直接比，中间的带宽就是
  /// 「销售了但还没核销」的部分，核销率一眼可读。
  final List<double> scaleAlt;

  /// 规模（核销 / 销售，跟当前 anchor 口径走）。
  /// 2026-08 运营会："在这个走势图里面，如果只能显示一个，我更希望显示规模。"
  /// 规模能推导利润，监测先看规模 —— 所以规模是 hero 线，利润降为次线。
  final List<double> scale;

  /// 第六条：净TA 业务成本。与 [cost] / [profit] 各自值域，不共用 Y。
  final List<double> costAlt;

  /// 第七条：银行余额存量。各自值域，图例用时点不是加总。
  final List<double> stock;
}

// ============================================================================
// 折扣与返点 — supply 行级 discount：底表金额 + 规则表类型/档位
// ============================================================================

class _DiscountRow {
  const _DiscountRow({
    required this.province,
    required this.cur,
    required this.rebate,
    this.effectivePermille,
    this.ruleType,
    this.base,
    this.mode,
    this.contractRate,
    this.tierLabel,
    this.tierLevel,
    this.tierCount,
    this.nextRate,
    this.nextThreshold,
    this.progress,
    this.gapToNext,
    this.status,
    this.discountRate,
    this.calcMode,
    this.periodStartTime,
    this.periodEndTime,
    this.segmentStartTime,
    this.segmentEndTime,
    this.reachTime,
    this.profitGain,
    this.tiersRaw,
  });

  final String province;
  final double cur;
  final double rebate;
  final double? effectivePermille;
  final String? ruleType;
  final String? base;
  final String? mode;
  final double? contractRate;
  final String? tierLabel;
  final int? tierLevel;
  final int? tierCount;
  final double? nextRate;
  final double? nextThreshold;
  final double? progress;
  final double? gapToNext;
  final String? status;
  final double? discountRate;
  final int? calcMode;
  final String? periodStartTime;
  final String? periodEndTime;
  final String? segmentStartTime;
  final String? segmentEndTime;

  /// 这一档的达成时间。有值 = 这一档已经到了，没值 = 还在爬。
  final String? reachTime;

  bool get isReached => reachTime != null && reachTime!.trim().isNotEmpty;

  /// 后端算的「过档多赚」（元）。只有全额累进会给，超额累进后端不给。
  final double? profitGain;

  /// `/lighthouse/discounts` 下发的完整阶梯（tiers）。老后端没有这个字段，
  /// 那时 [ladder] 会退成占位阶梯 —— 格子数按 tierCount 画，门槛费率画「—」。
  final Object? tiersRaw;

  /// 展开区「折扣档位」卡用的阶梯。固定折扣没有档位这回事，返回 null。
  LighthouseDiscountLadder? get ladder {
    if (isFixed) return null;
    final level = tierLevel ?? 1;
    final full = LighthouseDiscountLadder.fromApi(
      tiersRaw,
      currentLevel: level,
    );
    if (full != null) return full;
    return LighthouseDiscountLadder.placeholder(
          tierCount: lighthouseDiscountPlaceholderTierCount(
            tierCount: tierCount,
            currentLevel: level,
            hasNext: nextRate != null || nextThreshold != null,
          ),
          currentLevel: level,
          currentPermille: discountRate != null
              ? discountRate! * 1000
              : contractRate,
          nextPermille: nextRate,
          // 当前档门槛后端没单发，用累计基数兜底只为了让指针有个落点，
          // 不当成门槛显示（占位格一律画「—」）。
          currentMin: 0,
          nextThreshold: nextThreshold,
        ) ??
        // 兜到底：连档位数都推不出来时，至少画出当前档和下一档。
        // 条子可点而卡片返回 null，就是「点了没反应」的根。
        LighthouseDiscountLadder.minimal(
          currentLevel: level,
          currentPermille: discountRate != null
              ? discountRate! * 1000
              : contractRate,
          nextPermille: nextRate,
          nextThreshold: nextThreshold,
        );
  }

  bool get isFixed => ruleType == '固定' || status == 'fixed';
  bool get isLadder => ruleType == '月阶梯' || ruleType == '年阶梯';
  bool get isExcessProgressive => calcMode == 1;
  bool get isFullProgressive => calcMode == 2;
  bool get hasNext => nextRate != null && gapToNext != null && gapToNext! > 0;
  bool get isCapped => status == 'capped';

  /// 距下一档还差多少。后端只给门槛不给缺口时自己减，两者都没有就是 null。
  double? get gapToNextAmount {
    final g = gapToNext;
    if (g != null && g > 0) return g;
    final t = nextThreshold;
    if (t != null && t > cur) return t - cur;
    return null;
  }

  /// 冻结列进度条：优先「累计 / 下一档门槛」，其次后端算好的 currentProgress，
  /// 最后用「累计 / (累计 + 缺口)」倒推。三者都没有返回 null —— 调用方退回档位刻度，
  /// 不拿档位序号硬凑成百分比，那是假进度。
  double? get progressToNext {
    final t = nextThreshold;
    if (t != null && t > 0) return (cur / t).clamp(0.0, 1.0).toDouble();
    final p = progress;
    if (p != null && p > 0) return p > 1 ? 1.0 : p;
    final g = gapToNext;
    if (g != null && g > 0 && cur > 0) {
      return (cur / (cur + g)).clamp(0.0, 1.0).toDouble();
    }
    return null;
  }

  String? get dateRange =>
      lighthouseDiscountDateRange(segmentStartTime, segmentEndTime) ??
      lighthouseDiscountDateRange(periodStartTime, periodEndTime);

  static _DiscountRow? fromApi(Map<String, dynamic> d, String supplyName) {
    final cur =
        (d['currentCumSales'] as num?)?.toDouble() ??
        (d['cur'] as num?)?.toDouble();
    if (cur == null || cur <= 0) return null;

    final rebate =
        (d['rebate'] as num?)?.toDouble() ??
        (d['estimated_rebate'] as num?)?.toDouble() ??
        0.0;
    final effectivePermille = (d['effectivePermille'] as num?)?.toDouble();
    final contractRate =
        (d['contractRatePermille'] as num?)?.toDouble() ??
        (d['currentTier'] as num?)?.toDouble() ??
        (d['curRate'] as num?)?.toDouble();
    final nextRate =
        (d['nextTier'] as num?)?.toDouble() ??
        (d['nextRate'] as num?)?.toDouble();
    final gapToNext =
        (d['salesToNextTier'] as num?)?.toDouble() ??
        (d['gap_to_next'] as num?)?.toDouble();
    final progress = (d['currentProgress'] as num?)?.toDouble();
    final nextThreshold =
        (d['next_threshold'] as num?)?.toDouble() ??
        (d['nextThreshold'] as num?)?.toDouble() ??
        (d['target'] as num?)?.toDouble();

    final province = d['province']?.toString().trim().isNotEmpty == true
        ? d['province'].toString()
        : supplyName.replaceAll(RegExp(r'省$|市$'), '');

    return _DiscountRow(
      province: province,
      cur: cur,
      rebate: rebate,
      effectivePermille:
          effectivePermille ?? (rebate > 0 ? rebate / cur * 1000 : null),
      ruleType: d['ruleType']?.toString() ?? d['rule_type']?.toString(),
      base: d['base']?.toString(),
      mode: d['mode']?.toString(),
      contractRate: contractRate,
      tierLabel: d['tierLabel']?.toString(),
      tierLevel:
          (d['tierLevel'] as num?)?.toInt() ??
          (d['current_tier_idx'] as num?)?.toInt(),
      tierCount: (d['tierCount'] as num?)?.toInt(),
      nextRate: nextRate,
      nextThreshold: nextThreshold,
      progress: progress,
      gapToNext: gapToNext,
      status: d['status']?.toString(),
      discountRate: (d['discountRate'] as num?)?.toDouble(),
      calcMode: (d['calcMode'] as num?)?.toInt(),
      periodStartTime: d['periodStartTime']?.toString(),
      periodEndTime: d['periodEndTime']?.toString(),
      tiersRaw: d['tiers'],
      segmentStartTime: d['segmentStartTime']?.toString(),
      segmentEndTime: d['segmentEndTime']?.toString(),
      reachTime: d['reachTime']?.toString(),
      profitGain: (d['profitGainAtNextTier'] as num?)?.toDouble(),
    );
  }
}

Color _discountTypeColor(_DiscountRow r) {
  if (r.isExcessProgressive) return LhColors.cnpc;
  if (r.isFullProgressive) return _LhPlum.primary;
  switch (r.ruleType) {
    case '固定':
      return _LhPlum.primary;
    case '月阶梯':
      return LhColors.cnpc;
    case '年阶梯':
      return LhColors.sinopec;
    default:
      return LhColors.mute;
  }
}

String _discountRateLine(_DiscountRow r) {
  if (r.discountRate != null) {
    final actualRate = r.cur > 0 ? r.rebate / r.cur : null;
    return '折扣 ${lighthouseDiscountRateLabel(r.discountRate)}'
        ' · 实际返点率 ${lighthouseDiscountRateLabel(actualRate)}';
  }
  final parts = <String>[];
  if (r.contractRate != null && r.contractRate! > 0) {
    parts.add('合约 ${_fmtPermille(r.contractRate)}');
  }
  if (r.effectivePermille != null) {
    parts.add('实收 ${_fmtPermille(r.effectivePermille)}');
  }
  return parts.isEmpty ? '—' : parts.join(' · ');
}

class _SeriesRange {
  const _SeriesRange(this.min, this.max);
  final double min;
  final double max;
  double get span {
    final s = max - min;
    return s.abs() < 1e-9 ? 1.0 : s;
  }
}

class _TrendBounds {
  const _TrendBounds(
    this.revenue,
    this.cost,
    this.profit,
    this.scale,
    this.scaleAlt,
    this.costAlt,
    this.stock, {
    this.shareScaleRange = true,
  });
  final _SeriesRange revenue;
  final _SeriesRange cost;
  final _SeriesRange profit;
  final _SeriesRange scale;
  final _SeriesRange scaleAlt;
  final _SeriesRange costAlt;
  final _SeriesRange stock;
  final bool shareScaleRange;
}

/// 历史值域只看已完成月份；月末预测超出时把端点收在图顶，不压扁历史曲线。
_TrendBounds _computeBounds(
  _TrendSeries s, {
  double? scaleForecast,
  double? profitForecast,
  bool shareScaleRange = true,
}) {
  _SeriesRange computeOne(List<double> v) {
    final r = lighthouseTrendSeriesRange(v);
    return _SeriesRange(r.min, r.max);
  }

  // v16 · 有月末预测 = 最后一期没走完。那半个月的实际值画成进度胶囊、不上线，
  //   也就不该参与值域 —— 否则 1.7 亿的半月值会把轴底拉下去，整条线被压扁。
  List<double> complete(List<double> v) =>
      scaleForecast != null && v.length >= 2 ? v.sublist(0, v.length - 1) : v;
  // v18 · 当月那一列（已发生实柱 + 预测虚框）也要落在轴里：只看历史的话，
  //   当月比历史都高 / 都低时两个点会被夹到图顶 / 图底，实柱和虚框挤成一根。
  //   预测值 ≈ 整月量级，总是纳入；已发生只在走过 4 成天数后纳入
  //   （月初的已发生只有一小截，纳入会把历史压扁 —— 那是 v16 修掉的问题）。
  List<double> withPace(List<double> done, List<double> raw, double? fc) {
    if (fc == null || !fc.isFinite || raw.isEmpty) return done;
    final a = raw.last;
    final out = <double>[...done, fc];
    if (a.isFinite && fc.abs() > 1e-9 && a / fc >= 0.4) out.add(a);
    return out;
  }

  final scaleFull = withPace(complete(s.scale), s.scale, scaleForecast);
  final scaleAltFull = complete(s.scaleAlt);
  var scaleRange = shareScaleRange
      ? computeOne(
          scaleAltFull.isEmpty
              ? scaleFull
              : <double>[...scaleFull, ...scaleAltFull],
        )
      : computeOne(scaleFull);
  final scaleAltRange = shareScaleRange ? scaleRange : computeOne(scaleAltFull);
  if (lighthouseTrendForecastExpandsRange &&
      scaleForecast != null &&
      s.scale.isNotEmpty) {
    if (scaleForecast > scaleRange.max) {
      final pad = (scaleForecast - scaleRange.min).abs() * 0.08;
      scaleRange = _SeriesRange(scaleRange.min, scaleForecast + pad);
    } else if (scaleForecast < scaleRange.min) {
      final pad = (scaleRange.max - scaleForecast).abs() * 0.08;
      scaleRange = _SeriesRange(scaleForecast - pad, scaleRange.max);
    }
  }

  return _TrendBounds(
    computeOne(s.revenue),
    computeOne(s.cost),
    // 利润当月没走完（有月末外推）时同规模：半个月的值不进值域。
    computeOne(
      profitForecast != null && s.profit.length >= 2
          ? withPace(
              s.profit.sublist(0, s.profit.length - 1),
              s.profit,
              profitForecast,
            )
          : s.profit,
    ),
    scaleRange,
    shareScaleRange ? scaleRange : scaleAltRange,
    computeOne(s.costAlt),
    computeOne(s.stock),
    shareScaleRange: shareScaleRange,
  );
}

/// 走势大图「削峰」：每月 1 号那种一次性到账会把整条线压成一根地平线。
/// 超过常态上沿 T（85 分位 × 1.35）的部分线性压缩，最高那一下只到 1.8T：
/// 峰还在、谁高谁低的顺序不变，但不再独霸纵轴。只改画法，读数永远是原值。
/// 一组共用一个 T（核销 / 销售那一对共轴，中间的带不能被压歪）。
typedef _TameParams = ({double t, double k});

/// K 线纵轴：线性刻度（高低比例是真的），但值域只看「绝大多数」——
/// 视窗里最极端的约 1.5% 天数如果远远甩出去，就让它们冲出图沿（图上画个
/// ▲ / ▼ 标记，最高 / 最低标注仍写真值），不让一两天把整段趋势压扁。
/// 点数太少（< 15）时不裁，直接用真实最小 / 最大。
_SeriesRange? _robustCandleRange(List<double> pts, int a, int b) {
  final v = <double>[
    for (var i = math.max(0, a); i <= math.min(b, pts.length - 1); i++)
      if (pts[i].isFinite) pts[i],
  ]..sort();
  if (v.length < 2) return null;
  var lo = v.first;
  var hi = v.last;
  if (v.length >= 15) {
    double q(double p) => v[((v.length - 1) * p).round()];
    final qLo = q(0.015);
    final qHi = q(0.985);
    final core = math.max(qHi - qLo, 1e-9);
    // 只裁「真的离谱」的那一两天（甩出大多数 1.5 倍以上）；普通的高点照常画全。
    if (hi > qHi + core * 1.5) hi = qHi + core * 0.5;
    if (lo < qLo - core * 1.5) lo = qLo - core * 0.5;
  }
  final span = math.max(hi - lo, hi.abs() * 0.1 + 1e-9);
  // 上面多留 22% 的空：最高那根蜡烛停在图高八成左右，不顶到天花板。
  return _SeriesRange(lo - span * 0.10, hi + span * 0.22);
}

/// 只换掉主线那一条（核销 / 销售共轴时一对一起换）的值域。
_TrendBounds _boundsWithHero(_TrendBounds b, int hero, _SeriesRange r) {
  final pair = b.shareScaleRange && (hero == 3 || hero == 4);
  return _TrendBounds(
    hero == 0 ? r : b.revenue,
    hero == 1 ? r : b.cost,
    hero == 2 ? r : b.profit,
    (hero == 3 || pair) ? r : b.scale,
    (hero == 4 || pair) ? r : b.scaleAlt,
    hero == 5 ? r : b.costAlt,
    hero == 6 ? r : b.stock,
    shareScaleRange: b.shareScaleRange,
  );
}

/// 日 K 背后浅灰刻度线的位置（占主图高度的比例，顶 → 底）。
const List<double> lighthouseCandleGridFractions = [0.0, 0.25, 0.5, 0.75];

/// 这一组要不要削峰、怎么削：超过 t 的部分乘 k。null = 不用削。
_TameParams? _tameParamsFor(List<List<double>> group) {
  final mags = <double>[
    for (final l in group)
      for (final v in l)
        if (v.isFinite && v.abs() > 1e-9) v.abs(),
  ]..sort();
  if (mags.length < 8) return null;
  final t = mags[((mags.length - 1) * 0.85).round()] * 1.35;
  final peak = mags.last;
  if (t <= 1e-9 || peak <= t * 1.8) return null;
  return (t: t, k: (t * 0.8) / (peak - t));
}

/// 削过峰的画面值 → 真实值（纵轴刻度要写真数）。
double _untameValue(_TameParams? q, double p) {
  if (q == null || !p.isFinite) return p;
  final a = p.abs();
  if (a <= q.t) return p;
  final r = q.t + (a - q.t) / q.k;
  return p < 0 ? -r : r;
}

List<List<double>> _tameSpikesGroup(List<List<double>> group) {
  final q = _tameParamsFor(group);
  if (q == null) return group;
  final t = q.t;
  final k = q.k;
  double warp(double v) {
    if (!v.isFinite) return v;
    final a = v.abs();
    if (a <= t) return v;
    final w = t + (a - t) * k;
    return v < 0 ? -w : w;
  }

  return [
    for (final l in group) [for (final v in l) warp(v)],
  ];
}

/// 指数移动平均（K 线的 NX 牛熊带、MACD 都用它）。开头从第一个值起算。
List<double> _trendEma(List<double> v, int n) {
  final out = List<double>.filled(v.length, double.nan);
  if (v.isEmpty || n <= 0) return out;
  final k = 2 / (n + 1);
  double? prev;
  for (var i = 0; i < v.length; i++) {
    final x = v[i];
    if (!x.isFinite) {
      if (prev != null) out[i] = prev;
      continue;
    }
    prev = prev == null ? x : k * x + (1 - k) * prev;
    out[i] = prev;
  }
  return out;
}

/// MACD(12,26,9)：DIF = EMA12 − EMA26，DEA = DIF 的 EMA9。
({List<double> dif, List<double> dea}) _trendMacd(List<double> v) {
  final e12 = _trendEma(v, 12);
  final e26 = _trendEma(v, 26);
  final dif = <double>[
    for (var i = 0; i < v.length; i++)
      (e12[i].isFinite && e26[i].isFinite) ? e12[i] - e26[i] : double.nan,
  ];
  return (dif: dif, dea: _trendEma(dif, 9));
}

/// K 线配色 —— 一套色，全部不透明。
///
/// 之前不和谐的三个原因：
///   1. 两套红绿：蜡烛是灯塔的珊瑚红 / 橄榄绿，MACD 是亮粉 / 青绿 ——
///      同一个「涨跌」用了两种红、两种绿；
///   2. 透明度各不相同（带子 18%、MACD 柱 70%、蜡烛 88%、当天 15%），
///      叠在一起颜色被底下的东西染偏，同一种颜色在不同地方看起来不一样；
///   3. 色相太多、饱和度不齐：品牌紫、珊瑚、橄榄、亮蓝、亮黄、粉、青七种，
///      有的是哑光土色、有的是荧光色。
/// 现在只有两组语义色：
///   · 涨 / 跌 = 灯塔自己的赚红亏绿（蜡烛、MACD 柱、涨跌胶囊、现价牌）；
///   · 快 / 慢 = 蓝紫（靠品牌紫）/ 琥珀（靠灯塔铜色）——NX快 带和 DIF 同色，
///     NX慢 带和 DEA 同色，上下两张图读的是同一对「快慢」。
/// 带子的面用预先跟白色混好的浅色，不用透明度。
abstract final class LhKColors {
  // 跟看盘软件一样的「清楚的红绿」：饱和度、明度跟蓝 / 琥珀带子同一档，
  // 不再一边哑光土色、一边荧光色。
  static const up = Color(0xFFE0362C);
  static const down = Color(0xFF0E9A57);
  static const fast = Color(0xFF3F78E0);
  static const slow = Color(0xFFE39A1F);

  /// 主线（7 日均线 = 走势线）：灯塔品牌紫，压在蜡烛上。
  static const trend = Color(0xFF7565C7);

  /// 实际值线：深墨灰，跟红绿蜡烛、紫均线、蓝黄带都分得开。
  static const actual = Color(0xFF3B4150);
  static const nxFast = fast;
  static const nxSlow = slow;
  static const dif = fast;
  static const dea = slow;
  static const barUp = up;
  static const barDown = down;

  /// 跟白色按比例混好的实色（不透明的「浅」）。
  static Color tint(Color c, double t) => Color.lerp(c, Colors.white, t)!;
}

/// 简单移动平均；不足一个窗口的前几位是 NaN（画的时候跳过）。
List<double> _trendMovingAverage(List<double> v, int window) {
  final out = List<double>.filled(v.length, double.nan);
  if (window <= 0) return out;
  var sum = 0.0;
  for (var i = 0; i < v.length; i++) {
    sum += v[i].isFinite ? v[i] : 0.0;
    if (i >= window) sum -= v[i - window].isFinite ? v[i - window] : 0.0;
    if (i >= window - 1) out[i] = sum / window;
  }
  return out;
}

/// 每条序列的削峰参数，下标同 lighthouseTrendSeriesKeys。
Map<int, _TameParams> _tameTrendParams(_TrendSeries s) {
  final pair = _tameParamsFor([s.scale, s.scaleAlt]);
  final out = <int, _TameParams>{};
  void put(int i, _TameParams? q) {
    if (q != null) out[i] = q;
  }

  put(0, _tameParamsFor([s.revenue]));
  put(1, _tameParamsFor([s.cost]));
  put(2, _tameParamsFor([s.profit]));
  put(3, pair);
  put(4, pair);
  put(5, _tameParamsFor([s.costAlt]));
  put(6, _tameParamsFor([s.stock]));
  return out;
}

_TrendSeries _tameTrendSeries(_TrendSeries s) {
  List<double> one(List<double> l) => _tameSpikesGroup([l]).first;
  final pair = _tameSpikesGroup([s.scale, s.scaleAlt]);
  return _TrendSeries(
    revenue: one(s.revenue),
    cost: one(s.cost),
    profit: one(s.profit),
    scale: pair[0],
    scaleAlt: pair[1],
    costAlt: one(s.costAlt),
    stock: one(s.stock),
  );
}

({List<double> pts, _SeriesRange range, Color color}) _trendPaintSpec({
  required _TrendSeries series,
  required _TrendBounds bounds,
  required List<Color> colors,
  required int index,
}) {
  final scaleColor = colors.length > 3 ? colors[3] : colors[2];
  final costAltColor = colors.length > 4 ? colors[4] : colors[1];
  switch (index) {
    case 0:
      return (pts: series.revenue, range: bounds.revenue, color: colors[0]);
    case 1:
      return (pts: series.cost, range: bounds.cost, color: colors[1]);
    case 2:
      return (pts: series.profit, range: bounds.profit, color: colors[2]);
    case 4:
      return (pts: series.scaleAlt, range: bounds.scaleAlt, color: scaleColor);
    case 5:
      return (pts: series.costAlt, range: bounds.costAlt, color: costAltColor);
    case 6:
      final stockColor = colors.length > 5
          ? colors[5]
          : const Color(lighthouseStockAccentValue);
      return (pts: series.stock, range: bounds.stock, color: stockColor);
    default:
      return (pts: series.scale, range: bounds.scale, color: scaleColor);
  }
}

// ═════════════════════════════════════════════════════════════════════════════
// 平滑折线 helper (v2.8 · Chart smoothing → v16 单调三次)
//   全灯塔的趋势线都走这一个入口；切线由 lighthouseMonotoneTangents 算
//   （纯函数，有单测），这里只负责 Hermite → Bezier 换算。
// ═════════════════════════════════════════════════════════════════════════════
void _addSmoothPath(Path path, List<Offset> points, {double tension = 1.0}) {
  if (points.isEmpty) return;
  path.moveTo(points[0].dx, points[0].dy);
  _monotoneCubicTo(path, points);
}

/// v16 · 平滑从 Catmull-Rom 换成单调三次（Fritsch–Carlson）。
///   Catmull-Rom 在拐点处会过冲：两点之间画出比两端都低的凹陷，读者会当成
///   真实数据。单调三次保证每段曲线落在两端值之间，呼吸感还在，假数据没了。
///   [tension] 参数保留只为兼容旧调用，不再生效。
void _monotoneCubicTo(Path path, List<Offset> points) {
  final n = points.length;
  if (n < 2) return;
  if (n == 2) {
    path.lineTo(points[1].dx, points[1].dy);
    return;
  }
  final m = lighthouseMonotoneTangents(
    [for (final p in points) p.dx],
    [for (final p in points) p.dy],
  );
  for (var i = 0; i < n - 1; i++) {
    final p1 = points[i];
    final p2 = points[i + 1];
    final h = (p2.dx - p1.dx) / 3;
    path.cubicTo(
      p1.dx + h,
      p1.dy + m[i] * h,
      p2.dx - h,
      p2.dy - m[i + 1] * h,
      p2.dx,
      p2.dy,
    );
  }
}

// appendSmoothPath —— 把点序以同样的单调三次续接到已有 path 上
//   (_addSmoothPath 会 moveTo 起点, 画闭合带的回程需要 lineTo 起点再续)。
//   两处必须用同一套控制点算法, 否则带的边缘和画出来的线会错开。
void appendSmoothPath(Path path, List<Offset> points, {double tension = 1.0}) {
  if (points.isEmpty) return;
  path.lineTo(points[0].dx, points[0].dy);
  _monotoneCubicTo(path, points);
}

// ═════════════════════════════════════════════════════════════════════════════
// _addMonotonePath —— 单调三次插值 (Fritsch–Carlson)
//
//   为什么不接着用上面的 Catmull-Rom：Catmull-Rom 的控制点只看邻居的位差，
//   在拐点处会 overshoot —— 画出数据里根本不存在的峰和谷。折线是装饰图时这
//   只是风格，是财务折线时它就是把假数据画进了图里（8.26 那道断崖之前的小
//   起伏，有一部分就是它 overshoot 出来的，不全是真数据）。
//
//   Fritsch–Carlson 的做法：先给每个点算一条切线，再逐段把切线夹回「不越过
//   相邻数据点」的范围（α² + β² ≤ 9 判据），保证曲线在每个单调区间内保持
//   单调 —— 两点之间既不会高过较高的那点，也不会低过较低的那点。
//   代价是拐点附近略显生硬，但那正是数据本来的样子。
// ═════════════════════════════════════════════════════════════════════════════
void _addMonotonePath(Path path, List<Offset> points) =>
    _addSmoothPath(path, points);

// ═════════════════════════════════════════════════════════════════════════════
// _niceStep —— 人能心算的刻度步长
//   span / target 落到 {1, 2, 2.5, 5} × 10^k 里最接近的一档。target = 3 是因为
//   小尺寸图上水平网格最多给 3 条，步长按 3 格算才不会算出一格都放不下的数。
// ═════════════════════════════════════════════════════════════════════════════
double _niceStep(double span, {int target = 3}) {
  if (!span.isFinite || span <= 0) return 1;
  final raw = span / target;
  final mag = math.pow(10, (math.log(raw) / math.ln10).floor()).toDouble();
  final norm = raw / mag;
  final mult = norm <= 1
      ? 1.0
      : norm <= 2
      ? 2.0
      : norm <= 2.5
      ? 2.5
      : norm <= 5
      ? 5.0
      : 10.0;
  return mult * mag;
}

// ═════════════════════════════════════════════════════════════════════════════
// _LhAurora · Hero 淡紫极光底层 (v2.9)
//   双层 RadialGradient 交叠,右上主紫入射光 + 左下深紫墨 grounding,
//   给雾紫 mist canvas 加"能量源"深度感。alpha 都极淡 (≤40/255),
//   不抢 typography 层级,只是让 hero 从"扁平雾底"变成"有光的空间"。
//   静态无动画,零耗电。IgnorePointer 永不吃事件。
// ═════════════════════════════════════════════════════════════════════════════
// ═════════════════════════════════════════════════════════════════════════════
// _StatDivider —— hero stat rail 列间细竖线, 极淡 (透明度 90 line2).
//   仅在 IntrinsicHeight Row 里生效, 高度自动跟兄弟等高.
// ═════════════════════════════════════════════════════════════════════════════
class _StatDivider extends StatelessWidget {
  const _StatDivider();

  @override
  Widget build(BuildContext context) {
    return Padding(
      padding: const EdgeInsets.symmetric(vertical: 8, horizontal: 1),
      child: Container(
        width: 0.5,
        color: DunesColors.resolve(
          context,
          LhColors.line2,
          role: DunesColorRole.surface,
        ).withAlpha(180),
      ),
    );
  }
}

// ═════════════════════════════════════════════════════════════════════════════
// _LhAurora · 呼吸/游走的极光背景 + 粒子星尘
//   v12.4 · 用户反馈"v12.3 太克制、感觉没改" —— 提速+加幅度+加粒子:
//     · 层 1 (右上主紫): 7s 周期 (原 12s), Lissajous 幅度 ±0.20/±0.16
//                       (原 ±0.08/±0.06), alpha 呼吸 44↔78 (原 30↔48);
//     · 层 2 (左下深紫): 8s 反相, 幅度 ±0.22/±0.16, alpha 24↔52;
//     · 层 3 (pearl 光斑): 16s 一圈, alpha 28↔56 呼吸;
//     · 层 4 (新增粒子): 9 颗 1.6–2.4px 的小紫点在卡内 Lissajous 漂,
//                     每颗有自己相位 + 呼吸 alpha, 编辑体星尘感.
//   幅度显著放大, 但依旧保持在"背景语言"—— 不抢主数字的戏.
// ═════════════════════════════════════════════════════════════════════════════
class _LhAurora extends StatefulWidget {
  const _LhAurora();

  @override
  State<_LhAurora> createState() => _LhAuroraState();
}

class _LhAuroraState extends State<_LhAurora> with TickerProviderStateMixin {
  late final AnimationController _c1; // 主紫呼吸 · 7s
  late final AnimationController _c2; // 深紫反相 · 8s
  late final AnimationController _c3; // pearl 转动 · 16s
  late final AnimationController _cp; // 粒子基座 · 11s

  // 粒子固定参数 (相位/频率/位置基点) —— 一次生成, 保证每次 build 位置一致
  static const _kParticles = <_LhAuroraParticle>[
    _LhAuroraParticle(
      base: Offset(-0.6, -0.3),
      amp: Offset(0.18, 0.14),
      freq: Offset(1.0, 1.3),
      phase: 0.00,
      size: 2.2,
    ),
    _LhAuroraParticle(
      base: Offset(0.35, 0.5),
      amp: Offset(0.14, 0.18),
      freq: Offset(1.1, 0.9),
      phase: 0.22,
      size: 1.8,
    ),
    _LhAuroraParticle(
      base: Offset(0.7, -0.2),
      amp: Offset(0.10, 0.20),
      freq: Offset(0.8, 1.2),
      phase: 0.55,
      size: 2.6,
    ),
    _LhAuroraParticle(
      base: Offset(-0.2, 0.6),
      amp: Offset(0.20, 0.12),
      freq: Offset(1.3, 1.0),
      phase: 0.71,
      size: 1.6,
    ),
    _LhAuroraParticle(
      base: Offset(0.55, -0.6),
      amp: Offset(0.12, 0.14),
      freq: Offset(0.9, 1.4),
      phase: 0.33,
      size: 2.0,
    ),
    _LhAuroraParticle(
      base: Offset(-0.5, 0.15),
      amp: Offset(0.16, 0.16),
      freq: Offset(1.2, 1.1),
      phase: 0.87,
      size: 2.4,
    ),
    _LhAuroraParticle(
      base: Offset(0.15, -0.5),
      amp: Offset(0.14, 0.10),
      freq: Offset(1.0, 1.5),
      phase: 0.11,
      size: 1.7,
    ),
    _LhAuroraParticle(
      base: Offset(0.05, 0.2),
      amp: Offset(0.22, 0.16),
      freq: Offset(1.4, 0.8),
      phase: 0.48,
      size: 2.1,
    ),
    _LhAuroraParticle(
      base: Offset(-0.75, 0.7),
      amp: Offset(0.10, 0.12),
      freq: Offset(1.1, 1.3),
      phase: 0.63,
      size: 1.9,
    ),
  ];

  @override
  void initState() {
    super.initState();
    _c1 = AnimationController(vsync: this, duration: const Duration(seconds: 7))
      ..repeat();
    _c2 = AnimationController(vsync: this, duration: const Duration(seconds: 8))
      ..repeat();
    _c3 = AnimationController(
      vsync: this,
      duration: const Duration(seconds: 16),
    )..repeat();
    _cp = AnimationController(
      vsync: this,
      duration: const Duration(seconds: 11),
    )..repeat();
  }

  @override
  void dispose() {
    _c1.dispose();
    _c2.dispose();
    _c3.dispose();
    _cp.dispose();
    super.dispose();
  }

  double _breathe(double t) {
    final s = math.sin(t * 2 * math.pi);
    return 0.5 + 0.5 * s;
  }

  @override
  Widget build(BuildContext context) {
    return IgnorePointer(
      child: AnimatedBuilder(
        animation: Listenable.merge([_c1, _c2, _c3, _cp]),
        builder: (ctx, _) {
          final b1 = _breathe(_c1.value);
          final b2 = _breathe(_c2.value + 0.5);
          final b3 = _breathe(_c3.value);
          final theta = _c3.value * 2 * math.pi;

          // 层 1: 主紫沿右上做 Lissajous 漂 (幅度放大)
          final c1x = 0.9 + 0.20 * math.sin(_c1.value * 2 * math.pi);
          final c1y = -0.85 + 0.16 * math.cos(_c1.value * 2 * math.pi * 1.3);
          final r1 = 1.05 + 0.25 * b1;
          final a1 = (44 + 34 * b1).round(); // 44..78

          // 层 2: 深紫在左下反相飘 (幅度放大)
          final c2x = -0.85 + 0.22 * math.cos(_c2.value * 2 * math.pi * 0.8);
          final c2y = 0.95 - 0.16 * math.sin(_c2.value * 2 * math.pi);
          final r2 = 0.80 + 0.25 * b2;
          final a2 = (24 + 28 * b2).round(); // 24..52

          // 层 3: pearl 光斑绕圈 + alpha 呼吸
          final c3x = 0.4 * math.cos(theta);
          final c3y = 0.15 + 0.25 * math.sin(theta);
          final a3 = (28 + 28 * b3).round(); // 28..56

          return Stack(
            fit: StackFit.expand,
            children: [
              // 层 1: 右上主紫入射光
              DecoratedBox(
                decoration: BoxDecoration(
                  gradient: RadialGradient(
                    center: Alignment(c1x, c1y),
                    radius: r1,
                    colors: [
                      DunesColors.resolve(
                        ctx,
                        _LhPlum.primary,
                        role: DunesColorRole.surface,
                      ).withAlpha(a1),
                      DunesColors.resolve(
                        ctx,
                        _LhPlum.primary,
                        role: DunesColorRole.surface,
                      ).withAlpha(0),
                    ],
                    stops: const [0.0, 0.7],
                  ),
                ),
              ),
              // 层 2: 左下深紫墨光晕
              DecoratedBox(
                decoration: BoxDecoration(
                  gradient: RadialGradient(
                    center: Alignment(c2x, c2y),
                    radius: r2,
                    colors: [
                      DunesColors.resolve(
                        ctx,
                        _LhPlum.deep,
                        role: DunesColorRole.surface,
                      ).withAlpha(a2),
                      DunesColors.resolve(
                        ctx,
                        _LhPlum.deep,
                        role: DunesColorRole.surface,
                      ).withAlpha(0),
                    ],
                    stops: const [0.0, 0.75],
                  ),
                ),
              ),
              // 层 3: 中央 pearl 光斑
              DecoratedBox(
                decoration: BoxDecoration(
                  gradient: RadialGradient(
                    center: Alignment(c3x, c3y),
                    radius: 0.55,
                    colors: [
                      DunesColors.resolve(
                        ctx,
                        Colors.white,
                        role: DunesColorRole.surface,
                      ).withAlpha(a3),
                      DunesColors.resolve(
                        ctx,
                        Colors.white,
                        role: DunesColorRole.surface,
                      ).withAlpha(0),
                    ],
                    stops: const [0.0, 0.7],
                  ),
                ),
              ),
              // 层 4: 粒子星尘
              CustomPaint(
                painter: _LhAuroraParticlePainter(
                  t: _cp.value,
                  particles: _kParticles,
                ),
              ),
            ],
          );
        },
      ),
    );
  }
}

/// _LhAurora 的粒子固定参数。每颗独立 Lissajous 路径 + 呼吸 alpha。
class _LhAuroraParticle {
  const _LhAuroraParticle({
    required this.base,
    required this.amp,
    required this.freq,
    required this.phase,
    required this.size,
  });
  final Offset base; // 归一化坐标 (-1..1)
  final Offset amp; // 漂移幅度
  final Offset freq; // Lissajous 频率
  final double phase; // 0..1
  final double size; // 像素半径
}

class _LhAuroraParticlePainter extends CustomPainter {
  const _LhAuroraParticlePainter({required this.t, required this.particles});
  final double t; // 0..1 全局时间
  final List<_LhAuroraParticle> particles;

  @override
  void paint(Canvas canvas, Size size) {
    final w = size.width;
    final h = size.height;
    for (final p in particles) {
      final u = ((t + p.phase) % 1.0) * 2 * math.pi;
      final nx = p.base.dx + p.amp.dx * math.sin(u * p.freq.dx);
      final ny = p.base.dy + p.amp.dy * math.cos(u * p.freq.dy);
      // 归一化 -1..1 → 像素坐标, 留 8px 边距避免贴到卡边
      final px = (nx * 0.5 + 0.5) * (w - 16) + 8;
      final py = (ny * 0.5 + 0.5) * (h - 16) + 8;
      // 每颗自呼吸 (相位偏移的 sin 平方 -> 亮暗更明显)
      final breathe = math.pow(math.sin(u * 0.5).abs(), 1.2).toDouble();
      final coreAlpha = (60 + 90 * breathe).round().clamp(0, 255);
      final haloAlpha = (18 + 32 * breathe).round().clamp(0, 255);
      // Halo
      canvas.drawCircle(
        Offset(px, py),
        p.size * 2.2,
        Paint()..color = _LhPlum.primary.withAlpha(haloAlpha),
      );
      // Core
      canvas.drawCircle(
        Offset(px, py),
        p.size,
        Paint()..color = _LhPlum.deep.withAlpha(coreAlpha),
      );
      // 亮心
      canvas.drawCircle(
        Offset(px, py),
        p.size * 0.4,
        Paint()..color = Colors.white.withAlpha(coreAlpha),
      );
    }
  }

  @override
  bool shouldRepaint(covariant _LhAuroraParticlePainter old) => old.t != t;
}

// ═════════════════════════════════════════════════════════════════════════════
// _LhSheen · 金属光泽扫过效果
//   v12.3 · L1 hero 大数字用: 每 ~8s 一道柔和高光斜扫而过, 让数字有"金属活体"
//   的高级感 —— 但只是短暂的一次 pass, 不打断阅读节奏。
//   实现: ShaderMask + LinearGradient (透明→白亮点→透明), 位置沿 x 从 -1.5 →
//   +1.5 单向平移; 未 pass 的时间保持完全透明的 mask (对孩子无影响).
// ═════════════════════════════════════════════════════════════════════════════
class _LhSheen extends StatefulWidget {
  const _LhSheen({
    required this.child,
    this.period = const Duration(seconds: 5),
    this.sweepFraction = 0.30,
  });
  final Widget child;
  final Duration period;

  /// 单次 sweep 占整个 period 的比例 (0.15–0.30). 其余时间保持静默.
  final double sweepFraction;

  @override
  State<_LhSheen> createState() => _LhSheenState();
}

class _LhSheenState extends State<_LhSheen>
    with SingleTickerProviderStateMixin {
  late final AnimationController _c;

  @override
  void initState() {
    super.initState();
    _c = AnimationController(vsync: this, duration: widget.period)..repeat();
  }

  @override
  void dispose() {
    _c.dispose();
    super.dispose();
  }

  @override
  Widget build(BuildContext context) {
    return AnimatedBuilder(
      animation: _c,
      builder: (ctx, child) {
        final t = _c.value;
        final sf = widget.sweepFraction;
        // 大部分时间 (t > sf) 不叠 ShaderMask —— 避免 save-layer 白开销,
        // 也避免退化 stops 触发 Flutter 的 degenerate-gradient 警告.
        if (t > sf) return child!;

        final progress = (t / sf).clamp(0.0, 1.0);
        // 中段 alpha 最亮, 头尾淡入淡出 —— 更像"光带真的滑过"而不是硬开硬关
        final peakEnv = math.sin(progress * math.pi); // 0..1..0
        final peakAlpha = (140 * peakEnv).round().clamp(0, 255);
        // 光带 -0.4 → 1.4 (从左外扫到右外), easeInOutSine 平滑加减速
        final eased = Curves.easeInOutSine.transform(progress);
        final band = -0.4 + 1.8 * eased;

        return ShaderMask(
          blendMode: BlendMode.srcATop,
          shaderCallback: (bounds) {
            return LinearGradient(
              begin: const Alignment(-1.0, -0.3),
              end: const Alignment(1.0, 0.3),
              colors: [
                DunesColors.resolve(
                  ctx,
                  Colors.white,
                  role: DunesColorRole.surface,
                ).withAlpha(0),
                DunesColors.resolve(
                  ctx,
                  Colors.white,
                  role: DunesColorRole.surface,
                ).withAlpha(0),
                DunesColors.resolve(
                  ctx,
                  Colors.white,
                  role: DunesColorRole.surface,
                ).withAlpha(peakAlpha),
                DunesColors.resolve(
                  ctx,
                  Colors.white,
                  role: DunesColorRole.surface,
                ).withAlpha(0),
                DunesColors.resolve(
                  ctx,
                  Colors.white,
                  role: DunesColorRole.surface,
                ).withAlpha(0),
              ],
              stops: [
                (band - 0.30).clamp(0.0, 1.0),
                (band - 0.08).clamp(0.0, 1.0),
                band.clamp(0.0, 1.0),
                (band + 0.08).clamp(0.0, 1.0),
                (band + 0.30).clamp(0.0, 1.0),
              ],
            ).createShader(bounds);
          },
          child: child,
        );
      },
      child: widget.child,
    );
  }
}

// ═════════════════════════════════════════════════════════════════════════════
// _LhNumberHalo · 数字后景脉动光晕
//   v12.4 · Hero 大数字背后铺一层脉动的紫色 (或负利润时的绿色) 径向光晕,
//   3.5s 一次呼吸 (半径 0.6↔1.1, alpha 0↔62). 数字始终"发着光", 是编辑体
//   里最接近"炫酷" 的一层 — 但因为在数字背后, 不会抢字型的可读性.
// ═════════════════════════════════════════════════════════════════════════════
class _LhNumberHalo extends StatefulWidget {
  const _LhNumberHalo({
    required this.color,
    this.period = const Duration(milliseconds: 3500),
  });
  final Color color;
  final Duration period;

  @override
  State<_LhNumberHalo> createState() => _LhNumberHaloState();
}

class _LhNumberHaloState extends State<_LhNumberHalo>
    with SingleTickerProviderStateMixin {
  late final AnimationController _c;

  @override
  void initState() {
    super.initState();
    _c = AnimationController(vsync: this, duration: widget.period)..repeat();
  }

  @override
  void dispose() {
    _c.dispose();
    super.dispose();
  }

  @override
  Widget build(BuildContext context) {
    return AnimatedBuilder(
      animation: _c,
      builder: (ctx, _) {
        final b = 0.5 + 0.5 * math.sin(_c.value * 2 * math.pi);
        final r = 0.55 + 0.55 * b;
        final a = (32 + 30 * b).round().clamp(0, 255);
        return DecoratedBox(
          decoration: BoxDecoration(
            gradient: RadialGradient(
              // 数字通常左对齐 —— 把光晕核心稍偏左, 匹配视觉重心
              center: const Alignment(-0.35, 0.0),
              radius: r,
              colors: [widget.color.withAlpha(a), widget.color.withAlpha(0)],
              stops: const [0.0, 0.7],
            ),
          ),
        );
      },
    );
  }
}

// ═════════════════════════════════════════════════════════════════════════════
// _LhPulseDot · 呼吸扩散圆点 (v2.9)
//   核心实心圆 (size) + 外围呼吸环 (0 → size·2.4 扩散,alpha 90→0 淡出)
//   周期 1600ms,easeOut。表意"数据实时/活体"—— 跟 Twitter live / Bloomberg
//   terminal 的 live indicator 一个语言。淡紫色,不打扰但有生命。
// ═════════════════════════════════════════════════════════════════════════════
class _LhPulseDot extends StatefulWidget {
  const _LhPulseDot({
    required this.color,
    this.size = 5,
    this.period = const Duration(milliseconds: 1600),
  });
  final Color color;
  final double size;
  final Duration period;

  @override
  State<_LhPulseDot> createState() => _LhPulseDotState();
}

class _LhPulseDotState extends State<_LhPulseDot>
    with SingleTickerProviderStateMixin {
  late final AnimationController _c;

  @override
  void initState() {
    super.initState();
    _c = AnimationController(vsync: this, duration: widget.period)..repeat();
  }

  @override
  void dispose() {
    _c.dispose();
    super.dispose();
  }

  @override
  Widget build(BuildContext context) {
    final ringMax = widget.size * 2.4;
    return SizedBox(
      width: ringMax,
      height: ringMax,
      child: AnimatedBuilder(
        animation: _c,
        builder: (ctx, _) {
          // easeOut: 快速扩散,末端缓和
          final t = Curves.easeOutCubic.transform(_c.value);
          final ringSize = widget.size + (ringMax - widget.size) * t;
          final ringAlpha = ((1.0 - t) * 90).round().clamp(0, 255);
          return Stack(
            alignment: Alignment.center,
            children: [
              // 呼吸环
              Container(
                width: ringSize,
                height: ringSize,
                decoration: BoxDecoration(
                  color: DunesColors.resolveNullable(
                    ctx,
                    widget.color.withAlpha(ringAlpha),
                    role: DunesColorRole.surface,
                  ),
                  shape: BoxShape.circle,
                ),
              ),
              // 核心实心圆 + 微弱 glow
              Container(
                width: widget.size,
                height: widget.size,
                decoration: BoxDecoration(
                  color: DunesColors.resolveNullable(
                    ctx,
                    widget.color,
                    role: DunesColorRole.surface,
                  ),
                  shape: BoxShape.circle,
                  boxShadow: [
                    BoxShadow(
                      color: widget.color.withAlpha(120),
                      blurRadius: 3,
                      spreadRadius: 0.5,
                    ),
                  ],
                ),
              ),
            ],
          );
        },
      ),
    );
  }
}

// ═════════════════════════════════════════════════════════════════════════════
// _LhAnimatedNumber · 数字 count-up 动画 (v2.9)
//   切换 period/tab/anchor 时,数字从上一个显示值 tween 到新值,
//   easeOutQuart 曲线 · 900ms · 给"数据正在计算"的科技感。
//   builder(ctx, currentValue) 允许调用方自定义格式化 + 单位组合。
//   didUpdateWidget 里以当前 tween 位置作为下一段起点,
//   避免用户连续切换时的"回弹"感。
// ═════════════════════════════════════════════════════════════════════════════
class _LhAnimatedNumber extends StatefulWidget {
  const _LhAnimatedNumber({
    required this.value,
    required this.builder,
    this.duration = const Duration(milliseconds: 900),
    this.curve = Curves.easeOutQuart,
    this.immediate = false,
  });
  final double value;
  final Widget Function(BuildContext, double) builder;
  final Duration duration;
  final Curve curve;

  /// true 时数字直接显示,不 tween。用于高频 setState 场景 (如拖动选点),
  /// 避免 tween 追着手指跑造成"永远在追赶"的观感。
  final bool immediate;

  @override
  State<_LhAnimatedNumber> createState() => _LhAnimatedNumberState();
}

class _LhAnimatedNumberState extends State<_LhAnimatedNumber>
    with SingleTickerProviderStateMixin {
  late final AnimationController _c;
  late double _from;
  late double _to;

  @override
  void initState() {
    super.initState();
    _from = widget.value;
    _to = widget.value;
    _c = AnimationController(vsync: this, duration: widget.duration)
      ..value = 1.0;
  }

  @override
  void didUpdateWidget(_LhAnimatedNumber old) {
    super.didUpdateWidget(old);
    if (old.value != widget.value) {
      if (widget.immediate) {
        _from = widget.value;
        _to = widget.value;
        _c.value = 1.0;
        return;
      }
      // 用当前 tween 位置作为起点,避免连续切换回弹
      final curved = widget.curve.transform(_c.value);
      _from = _from + (_to - _from) * curved;
      _to = widget.value;
      _c
        ..duration = widget.duration
        ..forward(from: 0);
    }
  }

  @override
  void dispose() {
    _c.dispose();
    super.dispose();
  }

  @override
  Widget build(BuildContext context) {
    if (widget.immediate) {
      return widget.builder(context, widget.value);
    }
    return AnimatedBuilder(
      animation: _c,
      builder: (ctx, _) {
        final t = widget.curve.transform(_c.value);
        final v = _from + (_to - _from) * t;
        return widget.builder(ctx, v);
      },
    );
  }
}

// ── Trend canvas shared geometry (v16) ───────────────────────────────────────
//   Lines / Overlay / 外层 MAX·MIN 标注三处必须用同一套判定，否则标注会挂歪。

/// 主线下标：solo 覆盖优先，否则按固定优先级挑。
int _trendResolveHero(List<bool> flags, int? override) =>
    override != null &&
        override >= 0 &&
        override < flags.length &&
        flags[override]
    ? override
    : lighthouseTrendHeroIndex(flags);

List<bool> _trendNormalizeFlags(List<bool> available) => available.length >= 6
    ? available
    : <bool>[for (var i = 0; i < 6; i++) i < available.length && available[i]];

/// 最后一期没走完（有月末预测、主线是规模）：最后一列画进度胶囊，不上线。
bool _trendIsPartial({
  required double? forecast,
  required List<bool> flags,
  required int heroIndex,
  required List<double> heroPts,
}) =>
    forecast != null &&
    (heroIndex == 3 || heroIndex == lighthouseTrendProfitIndex) &&
    flags[heroIndex] &&
    heroPts.length >= 2;

/// 核销 ↔ 销售共用真轴时才画差额带和第二条规模线。
bool _trendAltDrawable({
  required _TrendSeries series,
  required _TrendBounds bounds,
  required List<bool> flags,
  required int heroIndex,
}) =>
    bounds.shareScaleRange &&
    // 主线必须就是规模那条：带子的上下缘共用 heroBounds，主线换成利润
    // 或收入之后，197 万的销售规模会被压进 6 万的利润尺，带子直接铺满全屏。
    heroIndex == 3 &&
    flags.length > 4 &&
    flags[3] &&
    flags[4] &&
    series.scale.length >= 2 &&
    series.scaleAlt.length >= 2;

/// 底部小柱层的值域（含 0，未走完那期不参与）。
({double lo, double hi}) _trendLaneRange(
  List<double> pts, {
  required bool partial,
}) {
  var lo = 0.0;
  var hi = 0.0;
  final rangeN = partial && pts.length >= 2 ? pts.length - 1 : pts.length;
  for (var i = 0; i < rangeN; i++) {
    lo = math.min(lo, pts[i]);
    hi = math.max(hi, pts[i]);
  }
  if ((hi - lo).abs() < 1e-9) hi = lo + 1;
  return (lo: lo, hi: hi);
}

/// 进度胶囊的实心顶 y：胶囊从 plotBottom 到预测点，按 已发生/预测 填充。
double _trendPaceFillTop({
  required double actual,
  required double forecast,
  required double forecastY,
  required double plotBottom,
}) =>
    plotBottom -
    (plotBottom - forecastY) * lighthouseTrendPaceRatio(actual, forecast);

void _trendDashedLine(
  Canvas canvas,
  Offset from,
  Offset to,
  Paint paint, {
  double dash = 4,
  double gap = 3,
}) {
  final dx = to.dx - from.dx;
  final dy = to.dy - from.dy;
  final len = math.sqrt(dx * dx + dy * dy);
  if (len < 1) return;
  final ux = dx / len;
  final uy = dy / len;
  var t = 0.0;
  while (t < len) {
    final e = math.min(t + dash, len);
    canvas.drawLine(
      Offset(from.dx + ux * t, from.dy + uy * t),
      Offset(from.dx + ux * e, from.dy + uy * e),
      paint,
    );
    t += dash + gap;
  }
}

/// K 线入口那张迷你卡的「皮」：白卡 + 淡紫发丝边 + 紫色柔投影。
/// 大图里的控件（周期选中格、下拉、统计条、明细牌…）都用这一套，跟入口呼应。
BoxDecoration _lhKCardDeco(
  BuildContext ctx, {
  double radius = 6,
  bool strong = false,
}) {
  return BoxDecoration(
    color: DunesColors.resolve(ctx, Colors.white, role: DunesColorRole.surface),
    borderRadius: BorderRadius.circular(radius),
    border: Border.all(
      color: DunesColors.resolve(
        ctx,
        const Color(0xFFE2D8F0),
        role: DunesColorRole.border,
      ),
      width: 0.7,
    ),
    boxShadow: [
      BoxShadow(
        color: _LhPlum.deep.withAlpha(strong ? 40 : 30),
        blurRadius: strong ? 12 : 6,
        spreadRadius: -1,
        offset: Offset(0, strong ? 4 : 2),
      ),
      BoxShadow(
        color: _LhPlum.deep.withAlpha(16),
        blurRadius: 1.5,
        offset: const Offset(0, 0.5),
      ),
    ],
  );
}

/// 入口卡后面那张淡紫卡的渐变。
const LinearGradient _lhKBackGradient = LinearGradient(
  begin: Alignment.topLeft,
  end: Alignment.bottomRight,
  colors: [Color(0xFFF1ECFB), Color(0xFFE6DEF6)],
);

/// 后面叠一张淡紫卡（往右上错开、微微转一点），跟入口那张一样 ——
/// 「能翻 / 能切」的控件（下拉、明细牌）都用它，表示后面还有一叠。
class _LhKStack extends StatelessWidget {
  const _LhKStack({
    required this.child,
    this.radius = 6,
    this.dx = 2.5,
    this.dy = -2.5,
    this.angle = 0.05,
  });

  final Widget child;
  final double radius;
  final double dx;
  final double dy;
  final double angle;

  @override
  Widget build(BuildContext context) {
    return Stack(
      clipBehavior: Clip.none,
      children: [
        Positioned.fill(
          child: IgnorePointer(
            child: Transform(
              alignment: Alignment.bottomLeft,
              transform: Matrix4.translationValues(dx, dy, 0)..rotateZ(angle),
              child: DecoratedBox(
                decoration: BoxDecoration(
                  gradient: _lhKBackGradient,
                  borderRadius: BorderRadius.circular(radius),
                  border: Border.all(
                    color: const Color(0xFFDCD0F0),
                    width: 0.7,
                  ),
                ),
              ),
            ),
          ),
        ),
        child,
      ],
    );
  }
}

/// 入口卡右下角那颗「四分之一圆」角标。放在卡片右下角（Positioned
/// right: 0 / bottom: 0），按 [cardRadius] 自己裁成卡片的圆角。
class _LhKCorner extends StatelessWidget {
  const _LhKCorner({
    this.size = 10,
    this.cardRadius = 6,
    this.color = _LhPlum.primary,
  });

  final double size;
  final double cardRadius;
  final Color color;

  @override
  Widget build(BuildContext context) {
    return IgnorePointer(
      child: CustomPaint(
        size: Size.square(size),
        painter: _LhKCornerPainter(color: color, cardRadius: cardRadius),
      ),
    );
  }
}

class _LhKCornerPainter extends CustomPainter {
  const _LhKCornerPainter({required this.color, required this.cardRadius});

  final Color color;
  final double cardRadius;

  @override
  void paint(Canvas canvas, Size size) {
    final r = size.width;
    canvas.save();
    canvas.clipRRect(
      RRect.fromLTRBAndCorners(
        -r,
        -r,
        r,
        r,
        bottomRight: Radius.circular(cardRadius),
      ),
    );
    final disc = Path()
      ..moveTo(r, 0)
      ..arcToPoint(Offset(0, r), radius: Radius.circular(r), clockwise: false)
      ..lineTo(r, r)
      ..close();
    canvas.drawPath(disc, Paint()..color = color);
    final rim = Path()
      ..moveTo(r, r * 0.1)
      ..arcToPoint(
        Offset(r * 0.1, r),
        radius: Radius.circular(r * 0.9),
        clockwise: false,
      );
    canvas.drawPath(
      rim,
      Paint()
        ..style = PaintingStyle.stroke
        ..strokeWidth = 0.6
        ..color = Color.lerp(color, Colors.white, 0.3)!,
    );
    canvas.restore();
  }

  @override
  bool shouldRepaint(covariant _LhKCornerPainter old) =>
      old.color != color || old.cardRadius != cardRadius;
}

/// 一根小蜡烛（影线 + 实体），代替 ▲ / ▼：涨红跌绿。
class _LhKCandleGlyph extends StatelessWidget {
  const _LhKCandleGlyph({required this.up, required this.color});

  final bool up;
  final Color color;

  @override
  Widget build(BuildContext context) {
    return CustomPaint(
      size: const Size(5, 11),
      painter: _LhKCandleGlyphPainter(up: up, color: color),
    );
  }
}

class _LhKCandleGlyphPainter extends CustomPainter {
  const _LhKCandleGlyphPainter({required this.up, required this.color});

  final bool up;
  final Color color;

  @override
  void paint(Canvas canvas, Size size) {
    final p = Paint()
      ..color = color
      ..strokeWidth = 0.9;
    final cx = size.width / 2;
    canvas.drawLine(Offset(cx, 0.5), Offset(cx, size.height - 0.5), p);
    final top = up ? 2.0 : 3.5;
    canvas.drawRRect(
      RRect.fromRectAndRadius(
        Rect.fromLTRB(0.4, top, size.width - 0.4, top + 5.5),
        const Radius.circular(0.7),
      ),
      p,
    );
  }

  @override
  bool shouldRepaint(covariant _LhKCandleGlyphPainter old) =>
      old.up != up || old.color != color;
}

/// 大图右上角的「收起」：跟入口同一张迷你卡，蜡烛变成淡紫占位，
/// 角标箭头朝里（↙）—— 从哪张卡出来，就收回哪张卡。
class _LhKCollapseButton extends StatelessWidget {
  const _LhKCollapseButton({required this.onTap});

  final VoidCallback onTap;

  @override
  Widget build(BuildContext context) {
    return Semantics(
      button: true,
      label: '收起 K 线大图',
      child: GestureDetector(
        behavior: HitTestBehavior.opaque,
        onTap: onTap,
        child: Padding(
          padding: const EdgeInsets.fromLTRB(8, 5, 4, 5),
          child: _LhKStack(
            radius: 5,
            dx: 2.5,
            dy: -2.5,
            child: Container(
              width: 32,
              height: 15,
              decoration: _lhKCardDeco(context, radius: 5),
              child: ClipRRect(
                borderRadius: BorderRadius.circular(4.4),
                child: const CustomPaint(
                  size: Size(32, 15),
                  painter: _LhMiniKPainter(
                    values: [],
                    loading: true,
                    inward: true,
                  ),
                ),
              ),
            ),
          ),
        ),
      ),
    );
  }
}

/// 「本期合计」行右侧的 K 线入口：一张会动的迷你 K 线卡。
///   · 蜡烛是最近几天的真实利润（开 = 前一天，收 = 当天），最后一根按今天比
///     昨天涨红跌绿；紫色趋势线 + 浅蓝 NX 带跟大图同一套元素；
///   · 后面叠一张淡紫卡，暗示「能抽出来」；按下时前卡往里压、后卡扇开；
///   · 右下角四分之一圆角标贴边，带 ↗。
class _LhMiniKButton extends StatefulWidget {
  const _LhMiniKButton({
    required this.values,
    required this.loading,
    required this.onTap,
  });

  final List<double> values;
  final bool loading;
  final ValueChanged<Rect?> onTap;

  @override
  State<_LhMiniKButton> createState() => _LhMiniKButtonState();
}

class _LhMiniKButtonState extends State<_LhMiniKButton> {
  // 只剩几根小蜡烛：没有卡片、没有边框、没有角标。
  static const double _w = 26;
  static const double _h = 15;
  bool _down = false;

  void _setDown(bool v) {
    if (_down == v) return;
    setState(() => _down = v);
  }

  void _fire() {
    LighthouseFeedback.instance.play(LighthouseFeedbackKind.expand);
    final ro = context.findRenderObject();
    Rect? r;
    if (ro is RenderBox && ro.hasSize && ro.attached) {
      r = ro.localToGlobal(Offset.zero) & ro.size;
    }
    widget.onTap(r);
  }

  @override
  Widget build(BuildContext context) {
    return Semantics(
      button: true,
      label: '打开 K 线大图',
      child: GestureDetector(
        behavior: HitTestBehavior.opaque,
        onTapDown: (_) => _setDown(true),
        onTapUp: (_) => _setDown(false),
        onTapCancel: () => _setDown(false),
        onTap: _fire,
        child: AnimatedScale(
          scale: _down ? 0.86 : 1.0,
          duration: const Duration(milliseconds: 120),
          curve: Curves.easeOut,
          child: AnimatedOpacity(
            opacity: _down ? 0.7 : 1.0,
            duration: const Duration(milliseconds: 120),
            child: CustomPaint(
              size: const Size(_w, _h),
              painter: _LhMiniCandlesPainter(
                values: widget.values,
                loading: widget.loading,
              ),
            ),
          ),
        ),
      ),
    );
  }
}

/// 入口用的极简小蜡烛：最近 6 根（开 = 前一天，收 = 当天），涨红跌绿，
/// 没有底、没有网格、没有均线。26×15 的设计坐标。
class _LhMiniCandlesPainter extends CustomPainter {
  const _LhMiniCandlesPainter({required this.values, required this.loading});

  final List<double> values;
  final bool loading;

  static const int _count = 6;
  static const double _step = 4.4;
  static const double _bodyW = 2.6;

  @override
  void paint(Canvas canvas, Size size) {
    canvas.save();
    canvas.scale(size.width / 26, size.height / 15);
    final wick = Paint()
      ..strokeWidth = 0.8
      ..strokeCap = StrokeCap.round;
    final body = Paint();
    double x(int i, int k) => 26 - 1.6 - (k - 1 - i) * _step;

    void candle(double cx, double top, double bot, Color col) {
      wick.color = col;
      body.color = col;
      canvas.drawLine(
        Offset(cx, math.max(0.6, top - 1.5)),
        Offset(cx, math.min(14.4, bot + 1.5)),
        wick,
      );
      canvas.drawRRect(
        RRect.fromRectAndRadius(
          Rect.fromLTRB(cx - _bodyW / 2, top, cx + _bodyW / 2, bot),
          const Radius.circular(0.6),
        ),
        body,
      );
    }

    if (loading || values.length < 3) {
      const ghost = Color(0xFFDCD3EE);
      for (var i = 0; i < _count; i++) {
        final top = 9.2 - i * 1.15;
        candle(x(i, _count), top, top + 3.2, ghost);
      }
    } else {
      final closes = values.length > _count + 1
          ? values.sublist(values.length - _count - 1)
          : values;
      final k = closes.length - 1;
      var lo = closes.reduce(math.min);
      var hi = closes.reduce(math.max);
      if ((hi - lo).abs() < 1e-9) {
        lo -= 1;
        hi += 1;
      }
      double y(double v) => 12.6 - (v - lo) / (hi - lo) * 10.2;
      for (var i = 0; i < k; i++) {
        final o = closes[i];
        final c = closes[i + 1];
        // 入口图标不承担涨跌信息（点开的大图才是），走单色紫：涨深、跌浅，
        // 免得一块灰白区域里跳出一小撮红绿。
        final col = c >= o ? const Color(0xFF7B5CD8) : const Color(0xFFC3B6EA);
        var top = math.min(y(o), y(c));
        var bot = math.max(y(o), y(c));
        if (bot - top < 1.2) {
          final m = (top + bot) / 2;
          top = m - 0.6;
          bot = m + 0.6;
        }
        candle(x(i, k), top, bot, col);
      }
    }
    canvas.restore();
  }

  @override
  bool shouldRepaint(covariant _LhMiniCandlesPainter old) =>
      old.loading != loading || !listEquals(old.values, values);
}

/// 迷你 K 线：在 64×30 的设计坐标里画，再整体缩到实际尺寸。
class _LhMiniKPainter extends CustomPainter {
  const _LhMiniKPainter({
    required this.values,
    required this.loading,
    this.inward = false,
  });

  final List<double> values;
  final bool loading;

  /// 收起钮：角标箭头朝里（↙），占位蜡烛用淡紫。
  final bool inward;

  // 加载中的灰色占位（x, 影线上, 影线下, 实体上, 实体高）。
  static const List<List<double>> _ghost = [
    [5, 19, 26, 21, 4],
    [10, 17, 25, 18.5, 5],
    [15, 18, 24, 19, 3],
    [20, 14, 22, 15.5, 5],
    [25, 12, 19, 13, 4],
    [30, 13, 19, 14, 3.5],
    [35, 9, 17, 10.5, 5],
    [40, 7, 14, 8, 4],
    [45, 5, 11, 6, 3.5],
  ];

  @override
  void paint(Canvas canvas, Size size) {
    canvas.save();
    canvas.scale(size.width / 64, size.height / 30);

    final grid = Paint()
      ..color = const Color(0xFFF1EFF4)
      ..strokeWidth = 0.6;
    canvas.drawLine(const Offset(0, 10.5), const Offset(64, 10.5), grid);
    canvas.drawLine(const Offset(0, 20.5), const Offset(64, 20.5), grid);

    final wick = Paint()..strokeWidth = 0.8;
    final body = Paint();

    if (loading || values.length < 3) {
      final ghost = inward ? const Color(0xFFDCD3EE) : const Color(0xFFE9E5F0);
      wick.color = ghost;
      body.color = ghost;
      for (final c in _ghost) {
        canvas.drawLine(Offset(c[0], c[1]), Offset(c[0], c[2]), wick);
        canvas.drawRRect(
          RRect.fromRectAndRadius(
            Rect.fromLTWH(c[0] - 1.5, c[3], 3, c[4]),
            const Radius.circular(0.5),
          ),
          body,
        );
      }
    } else {
      final closes = values.length > 10
          ? values.sublist(values.length - 10)
          : values;
      final k = closes.length - 1; // 蜡烛根数（第一个点只当开盘）
      var lo = closes.reduce(math.min);
      var hi = closes.reduce(math.max);
      if ((hi - lo).abs() < 1e-9) {
        lo -= 1;
        hi += 1;
      }
      double y(double v) => 26.5 - (v - lo) / (hi - lo) * 20.5;
      double x(int i) => 45 - (k - 1 - i) * 5.0;

      // 趋势：3 点均线（前面不足 3 个就用已有的）。
      final trend = <Offset>[];
      for (var i = 0; i < k; i++) {
        final j = i + 1;
        final from = math.max(0, j - 2);
        var sum = 0.0;
        for (var t = from; t <= j; t++) {
          sum += closes[t];
        }
        trend.add(Offset(x(i), y(sum / (j - from + 1))));
      }
      final tail = Offset(x(k - 1) + 2, trend.last.dy);

      // NX 带：趋势线下方一条浅蓝实色带。
      final band = Path()..moveTo(trend.first.dx - 2, trend.first.dy + 2.2);
      for (final p in trend) {
        band.lineTo(p.dx, p.dy + 2.2);
      }
      band.lineTo(tail.dx, tail.dy + 2.2);
      band.lineTo(tail.dx, tail.dy + 6.5);
      for (final p in trend.reversed) {
        band.lineTo(p.dx, p.dy + 6.5);
      }
      band.lineTo(trend.first.dx - 2, trend.first.dy + 6.5);
      band.close();
      canvas.drawPath(band, Paint()..color = const Color(0xFFEAF1FC));

      for (var i = 0; i < k; i++) {
        final o = closes[i];
        final c = closes[i + 1];
        final up = c >= o;
        final col = up ? LhKColors.up : LhKColors.down;
        wick.color = col;
        body.color = col;
        final yo = y(o);
        final yc = y(c);
        var top = math.min(yo, yc);
        var bot = math.max(yo, yc);
        if (bot - top < 1.4) {
          final m = (top + bot) / 2;
          top = m - 0.7;
          bot = m + 0.7;
        }
        final cx = x(i);
        canvas.drawLine(
          Offset(cx, math.max(1.5, top - 1.8)),
          Offset(cx, math.min(29, bot + 1.8)),
          wick,
        );
        canvas.drawRRect(
          RRect.fromRectAndRadius(
            Rect.fromLTRB(cx - 1.5, top, cx + 1.5, bot),
            const Radius.circular(0.5),
          ),
          body,
        );
      }

      final line = Path()..moveTo(trend.first.dx, trend.first.dy);
      for (final p in trend.skip(1)) {
        line.lineTo(p.dx, p.dy);
      }
      line.lineTo(tail.dx, tail.dy);
      canvas.drawPath(
        line,
        Paint()
          ..style = PaintingStyle.stroke
          ..strokeWidth = 2.6
          ..strokeJoin = StrokeJoin.round
          ..strokeCap = StrokeCap.round
          ..color = Colors.white,
      );
      canvas.drawPath(
        line,
        Paint()
          ..style = PaintingStyle.stroke
          ..strokeWidth = 1.3
          ..strokeJoin = StrokeJoin.round
          ..strokeCap = StrokeCap.round
          ..color = LhKColors.trend,
      );
      canvas.drawCircle(tail, 2.2, Paint()..color = Colors.white);
      canvas.drawCircle(tail, 1.6, Paint()..color = LhKColors.trend);
    }

    // 右下角：贴边的四分之一圆角标 + ↗。
    final corner = Path()
      ..moveTo(64, 14)
      ..arcToPoint(
        const Offset(48, 30),
        radius: const Radius.circular(16),
        clockwise: false,
      )
      ..lineTo(64, 30)
      ..close();
    canvas.drawPath(corner, Paint()..color = _LhPlum.primary);
    final rim = Path()
      ..moveTo(64, 15.6)
      ..arcToPoint(
        const Offset(49.6, 30),
        radius: const Radius.circular(14.4),
        clockwise: false,
      );
    canvas.drawPath(
      rim,
      Paint()
        ..style = PaintingStyle.stroke
        ..strokeWidth = 0.6
        ..color = const Color(0xFF9C86E8),
    );
    final arrow = Paint()
      ..style = PaintingStyle.stroke
      ..strokeWidth = inward ? 2.0 : 1.3
      ..strokeCap = StrokeCap.round
      ..strokeJoin = StrokeJoin.round
      ..color = Colors.white;
    canvas.drawLine(const Offset(55.4, 26.6), const Offset(59.6, 22.4), arrow);
    canvas.drawPath(
      inward
          ? (Path()
              ..moveTo(55.3, 23.4)
              ..lineTo(55.3, 26.7)
              ..lineTo(58.6, 26.7))
          : (Path()
              ..moveTo(56.6, 22.3)
              ..lineTo(59.7, 22.3)
              ..lineTo(59.7, 25.4)),
      arrow,
    );
    canvas.restore();
  }

  @override
  bool shouldRepaint(covariant _LhMiniKPainter old) =>
      old.loading != loading ||
      old.inward != inward ||
      !listEquals(old.values, values);
}

// ── Lines painter (heavy, but RepaintBoundary'd; only repaints on data change) ─
//   v16 · 视觉降噪（见 lighthouse_hero_metric.dart 顶部「趋势图 v16」）：
//     上层主图 —— 只放同一根真轴上的东西：规模主线 + 差额带 + 规模族另一条；
//     底部小柱 —— 利润等各自归一的上下文序列，共用横轴、永不交叉；
//     当月未走完 —— 虚线连到月末预测 + 进度胶囊，不再画半个月的假断崖；
//     每个日期默认画空心点；末端点单独加重。整宽 MAX/MIN 虚线不画。
/// 走势大图的出场舞台：卡片从「本期合计」行那张迷你 K 线卡里「抽」出来 ——
///   · 位置 / 大小：从迷你卡的位置边放大边飞到屏幕正中（跟 Hero 卡等宽），带一点过冲；
///   · 3D：绕 X 轴从后仰 60° 弹性立起（ElasticOut，落定时轻轻晃两下），
///     半路再带一点 Y 轴侧倾，像一张牌被抽出来翻到眼前；
///   · 投影随「离纸面的高度」变深变大；
///   · 落定后一道斜向高光从左扫到右。
/// 收起时反过来：缩回迷你卡的位置、淡出。
/// 卡片内容按最终尺寸排一次版，动画里只做缩放，不在每一帧重排图表。
class _LhPopStage extends StatelessWidget {
  const _LhPopStage({
    required this.animation,
    required this.fromRect,
    required this.onDismiss,
    required this.child,
    this.originRect,
  });

  final Animation<double> animation;
  final Rect? fromRect;

  /// 点的那张迷你 K 线卡的位置：大卡从这里长出来、收起时缩回这里。
  final Rect? originRect;
  final VoidCallback onDismiss;
  final Widget child;

  static const Curve _fly = Cubic(0.2, 1.22, 0.35, 1.0);
  static const Curve _flip = ElasticOutCurve(0.55);

  @override
  Widget build(BuildContext context) {
    final mq = MediaQuery.of(context);
    final screen = mq.size;
    final pad = mq.padding;
    final width = (fromRect?.width ?? screen.width - 44)
        .clamp(260.0, math.max(260.0, screen.width - 16))
        .toDouble();
    final left = (fromRect?.left ?? (screen.width - width) / 2)
        .clamp(8.0, math.max(8.0, screen.width - width - 8))
        .toDouble();
    final usableH = screen.height - pad.vertical - 24;
    // 弹层高度：半屏（340–580），手机和桌面同一个比例。
    final height = math.min(
      (screen.height * 0.5).clamp(340.0, 580.0).toDouble(),
      math.max(240.0, usableH),
    );
    final top = pad.top + 12 + (usableH - height) / 2;
    final to = Rect.fromLTWH(left, top, width, height);
    // 起点按大卡的长宽比缩小、对准迷你卡中心，缩放过程不变形。
    final origin = originRect;
    final from = origin != null
        ? Rect.fromCenter(
            center: origin.center,
            width: to.width * 0.16,
            height: to.height * 0.16,
          )
        : (fromRect ?? to.deflate(36));
    final radius = BorderRadius.circular(lighthouseHeroCardRadius + 2);
    return GestureDetector(
      behavior: HitTestBehavior.opaque,
      onTap: onDismiss,
      child: AnimatedBuilder(
        animation: animation,
        child: SizedBox.fromSize(
          size: to.size,
          child: GestureDetector(
            behavior: HitTestBehavior.opaque,
            onTap: () {},
            child: child,
          ),
        ),
        builder: (ctx, card) {
          final t = animation.value;
          final back = animation.status == AnimationStatus.reverse;
          final move = back
              ? Curves.easeInCubic.transform(t)
              : _fly.transform(t);
          final stand = back
              ? Curves.easeInCubic.transform(t)
              : _flip.transform(t);
          final rect = Rect.lerp(from, to, move)!;
          final angleX = (1 - stand) * -1.05;
          final angleY = back ? 0.0 : math.sin(t * math.pi) * 0.14;
          final fade = Curves.easeOut.transform((t / 0.3).clamp(0.0, 1.0));
          final lift = Curves.easeOut.transform(t.clamp(0.0, 1.0));
          final glare = back ? -1.0 : (t - 0.55) / 0.45;
          // 落定之后矩阵回到纯单位阵（不带透视项）：Flutter 对纯平移不建
          // 变换图层，web 上就不会把整张卡栅格化 —— 字和线不再发虚。
          final settled = !back && t >= 1.0;
          return Stack(
            children: [
              Positioned.fromRect(
                rect: rect,
                child: Opacity(
                  opacity: fade,
                  child: Transform(
                    alignment: Alignment.center,
                    transform: settled
                        ? Matrix4.identity()
                        : (Matrix4.identity()
                            ..setEntry(3, 2, 0.0012)
                            ..rotateX(angleX)
                            ..rotateY(angleY)),
                    child: DecoratedBox(
                      decoration: BoxDecoration(
                        borderRadius: radius,
                        boxShadow: [
                          BoxShadow(
                            color: _LhPlum.deep.withAlpha((64 * lift).round()),
                            blurRadius: 10 + 30 * lift,
                            spreadRadius: -4,
                            offset: Offset(0, 4 + 16 * lift),
                          ),
                          BoxShadow(
                            color: _LhPlum.deep.withAlpha((16 * lift).round()),
                            blurRadius: 3,
                            offset: const Offset(0, 1),
                          ),
                        ],
                      ),
                      child: Stack(
                        clipBehavior: Clip.none,
                        children: [
                          // 跟入口卡一样：后面叠一张淡紫卡，往右上错开一点。
                          Positioned.fill(
                            child: IgnorePointer(
                              child: Transform(
                                alignment: Alignment.bottomLeft,
                                transform: Matrix4.translationValues(6, -6, 0)
                                  ..rotateZ(0.008),
                                child: DecoratedBox(
                                  decoration: BoxDecoration(
                                    gradient: _lhKBackGradient,
                                    borderRadius: radius,
                                    border: Border.all(
                                      color: const Color(0xFFDCD0F0),
                                      width: 0.8,
                                    ),
                                  ),
                                ),
                              ),
                            ),
                          ),
                          Positioned.fill(
                            child: FittedBox(fit: BoxFit.fill, child: card),
                          ),
                          if (glare > 0 && glare < 1)
                            Positioned.fill(
                              child: IgnorePointer(
                                child: ClipRRect(
                                  borderRadius: radius,
                                  child: DecoratedBox(
                                    decoration: BoxDecoration(
                                      gradient: LinearGradient(
                                        begin: Alignment(
                                          -2.6 + 4.2 * glare,
                                          -1,
                                        ),
                                        end: Alignment(-1.6 + 4.2 * glare, 1),
                                        colors: [
                                          Colors.white.withAlpha(0),
                                          Colors.white.withAlpha(120),
                                          Colors.white.withAlpha(0),
                                        ],
                                        stops: const [0.0, 0.5, 1.0],
                                      ),
                                    ),
                                  ),
                                ),
                              ),
                            ),
                        ],
                      ),
                    ),
                  ),
                ),
              ),
            ],
          );
        },
      ),
    );
  }
}

/// 预测区底色：右边这一片都是还没发生的（主图和「之后各月」两张画布同一个色）。
const Color _kLhForecastZoneTint = Color(0x0C51418E);

/// 年末延伸：本月预测点之后的各月。局部坐标 x = 0 是本月那一列的中线
/// （主图实线末端），第 k 个月在 (k + 1) × step。
/// v2 · 去掉须线和短横（一排「工」字像误差棒，读起来像实验数据），改成
///   一张从本月张开、越往后越宽的区间扇面：
///   · [tintFrom] 往右铺预测区底色（跟主图那半格接上）；
///   · 扇面 = 本月上下沿 → 各月上下沿，极淡的填充 + 两条发丝边；
///   · 中线是细虚线，各月一个小空心点；
///   · 金额写在扇面上沿之上，点距太窄时只写最后一个月。
class _LhFutureMonthsPainter extends CustomPainter {
  const _LhFutureMonthsPainter({
    required this.step,
    required this.originY,
    this.originLo,
    this.originHi,
    required this.ys,
    required this.los,
    required this.his,
    required this.plotTop,
    required this.plotBottom,
    required this.labels,
    required this.color,
    this.tintFrom = 0,
  });
  final double step, originY, plotTop, plotBottom, tintFrom;
  final double? originLo, originHi;
  final List<double> ys;
  final List<double?> los, his;
  final List<String> labels;
  final Color color;

  @override
  void paint(Canvas canvas, Size size) {
    if (ys.isEmpty || step <= 0) return;
    double clampY(double y) => y.clamp(plotTop, plotBottom).toDouble();
    canvas.drawRect(
      Rect.fromLTRB(tintFrom, 0, size.width, plotBottom),
      Paint()..color = _kLhForecastZoneTint,
    );
    final pts = <Offset>[
      for (var k = 0; k < ys.length; k++) Offset((k + 1) * step, clampY(ys[k])),
    ];
    // 扇面：上沿从左到右，下沿从右到左。缺区间的月份按中线收口。
    final upper = <Offset>[
      Offset(0, clampY(originHi ?? originY)),
      for (var k = 0; k < pts.length; k++)
        Offset(pts[k].dx, clampY(his[k] ?? ys[k])),
    ];
    final lower = <Offset>[
      Offset(0, clampY(originLo ?? originY)),
      for (var k = 0; k < pts.length; k++)
        Offset(pts[k].dx, clampY(los[k] ?? ys[k])),
    ];
    final fan = Path()..moveTo(upper.first.dx, upper.first.dy);
    for (final o in upper.skip(1)) {
      fan.lineTo(o.dx, o.dy);
    }
    for (final o in lower.reversed) {
      fan.lineTo(o.dx, o.dy);
    }
    fan.close();
    canvas.drawPath(fan, Paint()..color = color.withAlpha(26));
    final edge = Paint()
      ..color = color.withAlpha(70)
      ..strokeWidth = 0.7
      ..style = PaintingStyle.stroke;
    for (final side in [upper, lower]) {
      final path = Path()..moveTo(side.first.dx, side.first.dy);
      for (final o in side.skip(1)) {
        path.lineTo(o.dx, o.dy);
      }
      canvas.drawPath(path, edge);
    }
    final dash = Paint()
      ..color = color.withAlpha(170)
      ..strokeWidth = 1.2
      ..strokeCap = StrokeCap.round;
    var prev = Offset(0, originY);
    for (final p in pts) {
      _trendDashedLine(canvas, prev, p, dash, dash: 3, gap: 2.6);
      prev = p;
    }
    for (var k = 0; k < pts.length; k++) {
      canvas.drawCircle(pts[k], 2.4, Paint()..color = Colors.white);
      canvas.drawCircle(
        pts[k],
        2.4,
        Paint()
          ..color = color.withAlpha(200)
          ..style = PaintingStyle.stroke
          ..strokeWidth = 1.1,
      );
      if (ys[k] < plotTop) {
        final tri = Path()
          ..moveTo(pts[k].dx, pts[k].dy - 7)
          ..lineTo(pts[k].dx - 2.4, pts[k].dy - 4)
          ..lineTo(pts[k].dx + 2.4, pts[k].dy - 4)
          ..close();
        canvas.drawPath(tri, Paint()..color = color.withAlpha(200));
      }
    }
    for (var k = 0; k < pts.length; k++) {
      if (step < 30 && k != pts.length - 1) continue;
      final tp = TextPainter(
        text: TextSpan(
          text: labels[k],
          style: LhTypography.mono(
            size: 7.5,
            color: color.withAlpha(190),
            weight: FontWeight.w600,
            letterSpacing: 0.1,
          ),
        ),
        textDirection: TextDirection.ltr,
      )..layout();
      final top = math.min(pts[k].dy, upper[k + 1].dy);
      final x = (pts[k].dx - tp.width / 2)
          .clamp(0.0, math.max(0.0, size.width - tp.width))
          .toDouble();
      final y = (top - tp.height - 3)
          .clamp(0.0, math.max(0.0, size.height - tp.height))
          .toDouble();
      tp.paint(canvas, Offset(x, y));
    }
  }

  @override
  bool shouldRepaint(covariant _LhFutureMonthsPainter old) =>
      old.step != step ||
      old.originY != originY ||
      old.originLo != originLo ||
      old.originHi != originHi ||
      old.tintFrom != tintFrom ||
      old.color != color ||
      !listEquals(old.ys, ys) ||
      !listEquals(old.los, los) ||
      !listEquals(old.his, his) ||
      !listEquals(old.labels, labels);
}

class _TrendLinesPainter extends CustomPainter {
  const _TrendLinesPainter({
    required this.series,
    required this.bounds,
    required this.colors,
    required this.padH,
    this.available = const [true, true, true, false, false, false],
    this.scaleForecast,
    this.heroIndexOverride,
    this.keepPaletteColor = false,
    this.extremeLo,
    this.extremeHi,
    this.showEndpoint = true,
    this.profitPartial = false,
    this.profitPace,
    this.forecastLo,
    this.forecastHi,
    this.dotScale = 1.0,
    this.candles = false,
    this.maFast,
    this.maSlow,
    this.nx,
    this.macdDif,
    this.macdDea,
    this.showActual = false,
  });

  /// K 线模式：把每天的真实值连成一条细线（跟蜡烛收盘对齐），压在均线下面。
  final bool showActual;

  /// 日 K：主线改画成蜡烛（昨日 → 今日，涨红跌绿），配两条均线 + 中间的带。
  /// 一天只有一个数，没有日内高低，所以不画影线 —— 不编造没有的数据。
  final bool candles;

  /// 与切片对齐的快 / 慢均线（NaN = 窗口不足）。
  final List<double>? maFast;

  /// NX 牛熊带（切片对齐）：[快带上沿, 快带下沿, 慢带上沿, 慢带下沿]。null = 关。
  final List<List<double>>? nx;

  /// MACD 的 DIF / DEA（切片对齐），副图用。
  final List<double>? macdDif;
  final List<double>? macdDea;
  final List<double>? maSlow;

  /// 点的大小倍数。全屏大图点密，缩小一圈（< 1 时逐点小圈也更晚出现）。
  final double dotScale;

  /// 月末预测的 80% 区间（v2 模型）；非空时当月那一列画须线。
  final double? forecastLo;
  final double? forecastHi;
  final _TrendSeries series;
  final _TrendBounds bounds;
  final List<Color> colors;
  final double padH;

  /// 利润主线时：最后一根柱是不是还没走完的当期（本月 / 本周截至今天）。
  final bool profitPartial;

  /// 利润当期外推倍数 = 当月天数 ÷ 已过天数（与规模月化预测同一公式）。
  /// 非空且 [profitPartial] 时，最后一根柱外面套一个虚框 = 按日均补到月底。
  final double? profitPace;

  /// 极值小圈只在 [extremeLo, extremeHi] 里找（视窗模式下切片两端各多一个画布外的点）。
  final int? extremeLo;
  final int? extremeHi;

  /// 末端点只在切片真的包含最新一期时画，否则会在视窗右沿冒出一颗假的「本期」。
  final bool showEndpoint;
  // v3.9 · [revenue, cost, profit, scale, scaleAlt, costAlt] 每条序列是否可见
  final List<bool> available;

  /// 月化预测值（仅「点月 + 当前月 + 规模类指标」给）。
  /// 非空时最后一列画进度胶囊 + 虚线连到预测点。
  final double? scaleForecast;

  /// solo 时强调线跟着被点的那条走，而不是按固定优先级挑。
  /// null = 沿用 [lighthouseTrendHeroIndex] 的优先级。
  final int? heroIndexOverride;

  /// 为 true 时主线保持 [colors] 里的强调色，利润不再改涂成赚红亏绿。
  /// 账本展开图要用上面格子的蓝 / 紫，红绿只留在环比上。
  final bool keepPaletteColor;

  @override
  void paint(Canvas canvas, Size size) {
    final n = series.revenue.length;
    final flags = _trendNormalizeFlags(available);
    final heroIndex = _trendResolveHero(flags, heroIndexOverride);
    final laneIndex = lighthouseTrendLaneIndex(flags, heroIndex);
    final geo = lighthouseTrendCanvasGeometry(
      size.height,
      wantsLane: laneIndex >= 0 || candles,
    );
    final plotTop = geo.plotTop;
    final plotBottom = geo.plotBottom;
    final usableH = plotBottom - plotTop;
    if (usableH <= 4) return;
    final usableW = size.width - padH * 2;
    final step = n <= 1 ? 0.0 : usableW / (n - 1);

    double xOf(int i) => padH + i * step;
    double yOf(double v, _SeriesRange r) =>
        plotTop + (r.max - v) / r.span * usableH;

    final heroSpec = _trendPaintSpec(
      series: series,
      bounds: bounds,
      colors: colors,
      index: heroIndex,
    );
    final heroPts = heroSpec.pts;
    final heroBounds = heroSpec.range;
    final profitHero = heroIndex == lighthouseTrendProfitIndex;
    // v18 · 只要主线是利润，就一律赚红亏绿 —— 账本展开图也不再锁家族色。
    //   其余指标（规模 / 收入 / 成本）不分红绿，保持强调紫。
    final heroColor = profitHero && heroPts.isNotEmpty
        ? (lighthouseTrendValueEarns(heroPts.last)
              ? LhColors.neg
              : LhColors.pos)
        : heroSpec.color;
    final fc = scaleForecast;
    final partial = _trendIsPartial(
      forecast: fc,
      flags: flags,
      heroIndex: heroIndex,
      heroPts: heroPts,
    );
    final solidN = partial ? heroPts.length - 1 : heroPts.length;
    final heroSolid = heroPts.sublist(0, solidN);
    final heroDrawable = flags[heroIndex] && heroSolid.isNotEmpty;
    final altDrawable = _trendAltDrawable(
      series: series,
      bounds: bounds,
      flags: flags,
      heroIndex: heroIndex,
    );

    // ── 亏绿赚红 ──────────────────────────────────────────────────────
    //   利润为正整条红、为负整条绿；跨过零轴时再按零轴裁成红绿两段。
    //   这一段在 painter 里做，所以 Hero、二级页、行展开那几张图天然同一套，
    //   区别只剩「能不能往前拖」。
    // v18 · 利润跟其他走势同一种画法，只是颜色：正红负绿，跨零按零轴裁成两段。
    final signSplit = lighthouseTrendSignSplit(
      heroIndex: heroIndex,
      min: heroBounds.min,
      max: heroBounds.max,
    );
    final zeroAxisY = signSplit ? yOf(0, heroBounds) : 0.0;
    final earnColor = LhColors.neg; // 赚 = 红
    final loseColor = LhColors.pos; // 亏 = 绿
    Color heroColorAt(double v) => signSplit
        ? (lighthouseTrendValueEarns(v) ? earnColor : loseColor)
        : heroColor;
    // 末端那一小截收深一点，让视线落在本期上。分色时不能再往紫里收。
    Color deepen(Color c) => profitHero
        ? Color.lerp(c, LhColors.ink, 0.20)!
        : Color.lerp(c, _LhPlum.deep, 0.22)!;
    final aboveZero = Rect.fromLTRB(0, 0, size.width, zeroAxisY);
    final belowZero = Rect.fromLTRB(0, zeroAxisY, size.width, size.height);

    // ── 1. 网格：三条发丝（顶 / 中 / 底），底线稍重当基线 ─────────────────
    //   v17 · 质感：顶 / 中两条改成点状发丝，只让底线实一点当基线 ——
    //   实线网格会和主线抢「线」的注意力，点线退到纸面里。
    final gridPaint = Paint()
      ..color = _LhPlum.deep.withAlpha(22)
      ..strokeWidth = 0.6
      ..strokeCap = StrokeCap.round;
    final left = padH;
    final right = size.width - padH;
    if (candles) {
      // 看盘软件那种「数据框」：主图区铺一层极浅的紫白底 + 一圈发丝框，
      // 里面横竖浅灰格子；纵轴读数贴在框外左侧（图层外画）。
      final frame = Rect.fromLTRB(0.4, plotTop, size.width - 0.4, plotBottom);
      canvas.drawRect(frame, Paint()..color = const Color(0xFFFCFBFE));
      final rule = Paint()
        ..color = const Color(0xFFEDEBF2)
        ..strokeWidth = 0.6;
      for (final f in lighthouseCandleGridFractions) {
        if (f <= 0) continue;
        final gy = plotTop + (plotBottom - plotTop) * f;
        canvas.drawLine(Offset(0, gy), Offset(size.width, gy), rule);
      }
      for (var k = 1; k < 6; k++) {
        final gx = size.width * k / 6;
        canvas.drawLine(Offset(gx, plotTop), Offset(gx, plotBottom), rule);
      }
      canvas.drawRect(
        frame,
        Paint()
          ..style = PaintingStyle.stroke
          ..strokeWidth = 0.8
          ..color = const Color(0xFFE3DEEC),
      );
    } else {
      _trendDashedLine(
        canvas,
        Offset(left, plotTop),
        Offset(right, plotTop),
        gridPaint,
        dash: 1.2,
        gap: 3.2,
      );
      final midY = (plotTop + plotBottom) / 2;
      _trendDashedLine(
        canvas,
        Offset(left, midY),
        Offset(right, midY),
        gridPaint,
        dash: 1.2,
        gap: 3.2,
      );
    }
    canvas.drawLine(
      Offset(left, plotBottom),
      Offset(right, plotBottom),
      Paint()
        ..color = _LhPlum.deep.withAlpha(30)
        ..strokeWidth = 0.7,
    );
    // 跨 0 时把零轴标出来 —— 红绿分在哪一刀上，得看得见。
    if (signSplit) {
      _trendDashedLine(
        canvas,
        Offset(left, zeroAxisY),
        Offset(right, zeroAxisY),
        Paint()
          ..color = LhColors.mute2.withAlpha(165)
          ..strokeWidth = 0.9
          ..strokeCap = StrokeCap.round,
        dash: 3.0,
        gap: 2.6,
      );
    }

    void drawLine(
      List<double> pts,
      Color color,
      _SeriesRange range, {
      double strokeWidth = 1.0,
      int alpha = 255,
    }) {
      if (pts.length < 2) return;
      final offsets = <Offset>[
        for (int i = 0; i < pts.length; i++) Offset(xOf(i), yOf(pts[i], range)),
      ];
      final path = Path();
      _addSmoothPath(path, offsets);
      canvas.drawPath(
        path,
        Paint()
          ..color = alpha == 255 ? color : color.withAlpha(alpha)
          ..strokeWidth = strokeWidth
          ..style = PaintingStyle.stroke
          ..strokeCap = StrokeCap.round
          ..strokeJoin = StrokeJoin.round,
      );
    }

    // ── K 线模式：均线带 + 蜡烛，替换下面 2～6 节的主线画法 ─────────────────
    if (candles && flags[heroIndex] && heroPts.isNotEmpty) {
      final m = heroPts.length;
      // NX 牛熊带：先画黄（慢）再画蓝（快），各是两条线夹一层半透明的面。
      final bands = nx;
      if (bands != null && bands.length == 4) {
        canvas.save();
        canvas.clipRect(
          Rect.fromLTRB(0, plotTop - 2, size.width, plotBottom + 2),
        );
        void band(List<double> upper, List<double> lower, Color c) {
          final top = <Offset>[];
          final bot = <Offset>[];
          for (
            var i = 0;
            i < math.min(math.min(upper.length, lower.length), m);
            i++
          ) {
            if (!upper[i].isFinite || !lower[i].isFinite) continue;
            top.add(Offset(xOf(i), yOf(upper[i], heroBounds)));
            bot.add(Offset(xOf(i), yOf(lower[i], heroBounds)));
          }
          if (top.length < 2) return;
          final fill = Path();
          _addSmoothPath(fill, top);
          appendSmoothPath(fill, bot.reversed.toList(growable: false));
          fill.close();
          // 面只铺一层很浅的实色（93% 白），雾感来自面太大太灰，不是线。
          canvas.drawPath(
            fill,
            Paint()..color = LhKColors.tint(c, step < 4.5 ? 0.95 : 0.93),
          );
          for (final edge in [top, bot]) {
            final path = Path();
            _addSmoothPath(path, edge);
            canvas.drawPath(
              path,
              Paint()
                ..color = c
                ..strokeWidth = step < 4.5 ? 0.8 : 1.1
                ..style = PaintingStyle.stroke
                ..strokeJoin = StrokeJoin.round,
            );
          }
        }

        band(bands[2], bands[3], LhKColors.nxSlow);
        band(bands[0], bands[1], LhKColors.nxFast);
        canvas.restore();
      }

      // 点很密（手机上一屏几个月，一天不到 4.5px）时：白衬底会把下面的蜡烛、
      // 牛熊带一层层「刷白」，整张图发雾。密的时候去掉白衬底、线细一号，
      // 实际值线垫到蜡烛下面，让红绿蜡烛自己露出来。
      final dense = step < 4.5;
      // 实际值线：每天的真实值直连（不做平滑，是几就是几），墨色细线 + 白衬底。
      void drawActual() {
        if (!showActual) return;
        final pts = <Offset>[
          for (var i = 0; i < m; i++)
            if (heroPts[i].isFinite)
              Offset(
                xOf(i),
                yOf(
                  heroPts[i],
                  heroBounds,
                ).clamp(plotTop, plotBottom).toDouble(),
              ),
        ];
        if (pts.length >= 2) {
          final path = Path()..moveTo(pts.first.dx, pts.first.dy);
          for (final p in pts.skip(1)) {
            path.lineTo(p.dx, p.dy);
          }
          if (!dense)
            canvas.drawPath(
              path,
              Paint()
                ..color = Colors.white
                ..strokeWidth = 2.4
                ..style = PaintingStyle.stroke
                ..strokeCap = StrokeCap.round
                ..strokeJoin = StrokeJoin.round,
            );
          canvas.drawPath(
            path,
            Paint()
              ..color = LhKColors.actual
              ..strokeWidth = dense ? 0.9 : 1.1
              ..style = PaintingStyle.stroke
              ..strokeCap = StrokeCap.round
              ..strokeJoin = StrokeJoin.round,
          );
          if (step >= 7) {
            final dot = Paint()..color = LhKColors.actual;
            final ring = Paint()..color = Colors.white;
            for (final p in pts) {
              canvas.drawCircle(p, 2.0, ring);
              canvas.drawCircle(p, 1.3, dot);
            }
          }
        }
      }

      if (dense) drawActual();

      // 蜡烛：开 = 前一天，收 = 当天。涨红跌绿（A 股习惯，也和利润赚红亏绿同向）。
      final bodyW = n <= 1 ? 6.0 : (step * 0.62).clamp(1.4, 10.0).toDouble();
      final unfinishedLast = (profitPartial || partial) && showEndpoint;
      for (var i = 0; i < m; i++) {
        final c = heroPts[i];
        if (!c.isFinite) continue;
        final o = i > 0 && heroPts[i - 1].isFinite ? heroPts[i - 1] : c;
        final rising = c >= o;
        final col = rising ? LhKColors.up : LhKColors.down;
        // 冲出值域的那几根（极端日）：截在图沿，外面画个小三角。
        final rawTop = yOf(math.max(o, c), heroBounds);
        final rawBot = yOf(math.min(o, c), heroBounds);
        final clipTop = rawTop < plotTop - 0.5;
        final clipBot = rawBot > plotBottom + 0.5;
        final yTop = rawTop.clamp(plotTop, plotBottom).toDouble();
        final yBot = math.max(
          rawBot.clamp(plotTop, plotBottom).toDouble(),
          yTop + 1.0,
        );
        final x = xOf(i);
        if (clipTop || clipBot) {
          final tri = Path();
          if (clipTop) {
            tri
              ..moveTo(x, plotTop - 6)
              ..lineTo(x - 3, plotTop - 1.5)
              ..lineTo(x + 3, plotTop - 1.5)
              ..close();
          }
          if (clipBot) {
            tri
              ..moveTo(x, plotBottom + 6)
              ..lineTo(x - 3, plotBottom + 1.5)
              ..lineTo(x + 3, plotBottom + 1.5)
              ..close();
          }
          canvas.drawPath(tri, Paint()..color = col);
        }
        final rect = RRect.fromLTRBR(
          x - bodyW / 2,
          yTop,
          x + bodyW / 2,
          yBot,
          Radius.circular(bodyW >= 4 ? 1.0 : 0.0),
        );
        if (unfinishedLast && i == m - 1) {
          // 今天还没过完：空心虚一点。
          // 今天还没过完：白底实色描边（不用半透明）。
          canvas.drawRRect(rect, Paint()..color = Colors.white);
          canvas.drawRRect(
            rect,
            Paint()
              ..color = col
              ..style = PaintingStyle.stroke
              ..strokeWidth = 0.8,
          );
        } else {
          canvas.drawRRect(rect, Paint()..color = col);
        }
      }

      if (!dense) drawActual();

      // 走势线（快均线，日线 = 7 日均）：白衬底切开、品牌紫实线，压在蜡烛上。
      final trend = maFast;
      if (trend != null) {
        final pts = <Offset>[
          for (var i = 0; i < math.min(trend.length, m); i++)
            if (trend[i].isFinite) Offset(xOf(i), yOf(trend[i], heroBounds)),
        ];
        if (pts.length >= 2) {
          final path = Path();
          _addSmoothPath(path, pts);
          canvas.save();
          canvas.clipRect(
            Rect.fromLTRB(0, plotTop - 2, size.width, plotBottom + 2),
          );
          if (!dense)
            canvas.drawPath(
              path,
              Paint()
                ..color = Colors.white
                ..strokeWidth = 2.6
                ..style = PaintingStyle.stroke
                ..strokeCap = StrokeCap.round
                ..strokeJoin = StrokeJoin.round,
            );
          canvas.drawPath(
            path,
            Paint()
              ..color = LhKColors.trend
              ..strokeWidth = dense ? 1.4 : 1.7
              ..style = PaintingStyle.stroke
              ..strokeCap = StrokeCap.round
              ..strokeJoin = StrokeJoin.round,
          );
          canvas.restore();
        }
      }

      // 最新一根的收盘价横虚线，贯穿全图 —— 和看盘软件的现价线一个意思。
      if (showEndpoint && heroPts.last.isFinite) {
        final ly = yOf(
          heroPts.last,
          heroBounds,
        ).clamp(plotTop, plotBottom).toDouble();
        final rising = m < 2 || heroPts.last >= heroPts[m - 2];
        _trendDashedLine(
          canvas,
          Offset(left, ly),
          Offset(right, ly),
          Paint()
            ..color = LhKColors.tint(
              rising ? LhKColors.up : LhKColors.down,
              0.35,
            )
            ..strokeWidth = 0.7,
          dash: 3.0,
          gap: 2.6,
        );
      }
    }

    if (!candles) {
      // ── 2. 主图体积：差额带（核销↔销售）或主线渐变填充 ────────────────────
      if (altDrawable) {
        // 「销售 − 核销」带：上缘销售、下缘核销，带宽 = 未核销部分。
        final alt = series.scaleAlt;
        final bandN = math.min(solidN, alt.length);
        if (bandN >= 2) {
          final top = <Offset>[
            for (int i = 0; i < bandN; i++)
              Offset(xOf(i), yOf(alt[i], heroBounds)),
          ];
          final bottom = <Offset>[
            for (int i = 0; i < bandN; i++)
              Offset(xOf(i), yOf(heroPts[i], heroBounds)),
          ];
          final band = Path();
          _addSmoothPath(band, top);
          appendSmoothPath(band, bottom.reversed.toList(growable: false));
          band.close();
          canvas.drawPath(
            band,
            Paint()
              ..color = heroColor.withAlpha(24)
              ..style = PaintingStyle.fill,
          );
          final altSpec = _trendPaintSpec(
            series: series,
            bounds: bounds,
            colors: colors,
            index: 4,
          );
          drawLine(
            alt.sublist(0, bandN),
            altSpec.color,
            altSpec.range,
            strokeWidth: 1.0,
            alpha: 130,
          );
        }
      } else if (heroDrawable && heroSolid.length >= 2) {
        final offsets = <Offset>[
          for (int i = 0; i < heroSolid.length; i++)
            Offset(xOf(i), yOf(heroSolid[i], heroBounds)),
        ];
        // 分色时面收在零轴上：赚的部分从线垂到 0，亏的部分从 0 垂到线，
        // 红绿各自贴着那条分界，而不是都拖到画布底。
        final baseY = signSplit ? zeroAxisY : plotBottom;
        final path = Path();
        _addSmoothPath(path, offsets);
        path.lineTo(offsets.last.dx, baseY);
        path.lineTo(offsets.first.dx, baseY);
        path.close();
        // v17 · 渐变从「线的最高点」起算而不是画布顶：峰下最浓、
        // 很快衰到透明，面只是托住线的一层雾，不再是一整块紫。
        var lineTop = baseY;
        var lineBottom = baseY;
        for (final o in offsets) {
          if (o.dy < lineTop) lineTop = o.dy;
          if (o.dy > lineBottom) lineBottom = o.dy;
        }
        void fillArea(
          Color c,
          Rect span, {
          Rect? clip,
          bool fadeDownward = true,
        }) {
          if (clip != null) {
            canvas.save();
            canvas.clipRect(clip);
          }
          final ramp = [c.withAlpha(30), c.withAlpha(8), c.withAlpha(0)];
          canvas.drawPath(
            path,
            Paint()
              ..shader = LinearGradient(
                begin: Alignment.topCenter,
                end: Alignment.bottomCenter,
                colors: fadeDownward ? ramp : ramp.reversed.toList(),
                stops: const [0.0, 0.55, 1.0],
              ).createShader(span)
              ..style = PaintingStyle.fill,
          );
          if (clip != null) canvas.restore();
        }

        if (!signSplit) {
          fillArea(
            heroColor,
            Rect.fromLTRB(0, lineTop, size.width, plotBottom),
          );
        } else {
          // 浓在峰 / 谷，淡到零轴。
          fillArea(
            earnColor,
            Rect.fromLTRB(0, lineTop, size.width, zeroAxisY),
            clip: aboveZero,
          );
          fillArea(
            loseColor,
            Rect.fromLTRB(0, zeroAxisY, size.width, lineBottom),
            clip: belowZero,
            fadeDownward: false,
          );
        }
      }

      // ── 3. 主线 ─────────────────────────────────────────────────────────
      //   v17 · 质感：旧版是 2.2px 纯色线 + 贴线的浓填充，边缘发虚、像马克笔。
      //   现在三层：① 往下错 2px 的柔影把线「抬」离纸面；② 白色衬底把线和
      //   填充切开，边缘利落；③ 主线本身左浅右深的横向渐变 —— 越靠近本期越实，
      //   视线自然落到末端读数上。
      if (heroDrawable && heroSolid.length >= 2) {
        final offsets = <Offset>[
          for (int i = 0; i < heroSolid.length; i++)
            Offset(xOf(i), yOf(heroSolid[i], heroBounds)),
        ];
        final linePath = Path();
        _addSmoothPath(linePath, offsets);
        final x0 = offsets.first.dx;
        final x1 = math.max(offsets.last.dx, x0 + 1);
        // 三层照旧：柔影抬起、白衬底切开填充、主线左浅右深。
        // 分色时整套用同一条路径画两遍，各自裁在零轴的一侧 ——
        // 影子和白边也跟着裁，接缝落在那条虚线上，不会互相糊。
        void strokeHero(Color c, {Rect? clip}) {
          if (clip != null) {
            canvas.save();
            canvas.clipRect(clip);
          }
          canvas.drawPath(
            linePath.shift(const Offset(0, 1.6)),
            Paint()
              ..color = c.withAlpha(28)
              ..strokeWidth = 2.8
              ..style = PaintingStyle.stroke
              ..strokeCap = StrokeCap.round
              ..strokeJoin = StrokeJoin.round
              ..maskFilter = const MaskFilter.blur(BlurStyle.normal, 2.0),
          );
          canvas.drawPath(
            linePath,
            Paint()
              ..color = Colors.white.withAlpha(188)
              ..strokeWidth = 3.0
              ..style = PaintingStyle.stroke
              ..strokeCap = StrokeCap.round
              ..strokeJoin = StrokeJoin.round,
          );
          canvas.drawPath(
            linePath,
            Paint()
              ..shader = LinearGradient(
                colors: [Color.lerp(c, Colors.white, 0.38)!, c, deepen(c)],
                stops: const [0.0, 0.6, 1.0],
              ).createShader(Rect.fromLTRB(x0, 0, x1, size.height))
              ..strokeWidth = 1.7
              ..style = PaintingStyle.stroke
              ..strokeCap = StrokeCap.round
              ..strokeJoin = StrokeJoin.round,
          );
          if (clip != null) canvas.restore();
        }

        if (!signSplit) {
          strokeHero(heroColor);
        } else {
          strokeHero(earnColor, clip: aboveZero);
          strokeHero(loseColor, clip: belowZero);
        }
      }

      // ── 4. 每个日期一个点。末端另有实心点，这里不重复画。
      final eFrom = math.max(0, extremeLo ?? 0);
      final eTo = math.min(
        heroSolid.length - 1,
        extremeHi ?? heroSolid.length - 1,
      );
      // 点距太密（全屏大图缩到几百天）时不画逐点小圈，否则糊成一条粗珠链。
      if (heroDrawable &&
          eTo >= eFrom &&
          (n <= 1 || step >= (dotScale < 1 ? 11.0 : 6.0))) {
        for (var i = eFrom; i <= eTo; i++) {
          if (showEndpoint && i == heroSolid.length - 1) continue;
          final o = Offset(xOf(i), yOf(heroSolid[i], heroBounds));
          canvas.drawCircle(o, 3.0 * dotScale, Paint()..color = Colors.white);
          canvas.drawCircle(
            o,
            3.0 * dotScale,
            Paint()
              ..color = heroColorAt(heroSolid[i])
              ..style = PaintingStyle.stroke
              ..strokeWidth = 1.4 * math.max(0.8, dotScale),
          );
        }
      }

      // ── 5. 末端点：走完的期给 halo；没走完时 halo 让给进度胶囊 ────────────
      if (heroDrawable && showEndpoint) {
        final i = heroSolid.length - 1;
        final o = Offset(xOf(i), yOf(heroSolid[i], heroBounds));
        //   v17 · 两圈半透明光晕叠在一起边缘发糊，换成「白珠 + 投影」：
        //   白环压实、下方一点柔影，点像是嵌在线上，而不是晕开的墨。
        final endColor = heroColorAt(heroSolid[i]);
        if (!partial) {
          canvas.drawCircle(
            o,
            6.8 * dotScale,
            Paint()..color = endColor.withAlpha(14),
          );
          canvas.drawCircle(
            o.translate(0, 1.0),
            4.2 * dotScale,
            Paint()
              ..color = (profitHero ? endColor : _LhPlum.deep).withAlpha(42)
              ..maskFilter = const MaskFilter.blur(BlurStyle.normal, 1.8),
          );
        }
        canvas.drawCircle(o, 4.0 * dotScale, Paint()..color = Colors.white);
        canvas.drawCircle(o, 2.5 * dotScale, Paint()..color = deepen(endColor));
      }

      // ── 6. 当月：已发生实柱 + 月末预测虚框（v18）────────────────────────
      //   v16 的胶囊是「从画布底到预测点，按 已发生/预测 填充」—— 可是
      //   已发生/预测 = 已过天数/当月天数，永远只是日历进度（22/30 就是 73%），
      //   跟生意好坏无关；实心顶也不落在纵轴的真实刻度上，所以看不懂。
      //   现在两段都贴真轴：实柱顶 = 已发生的真实位置，虚框顶 = 月末预测的
      //   真实位置，中间那截 = 按日均补到月底还要做的量。虚线从上个完整月
      //   连到预测点：往上 = 预计超上月，往下 = 预计不如上月。
      if (partial) {
        final lastI = heroPts.length - 1;
        final lastX = xOf(lastI);
        final rawFcY = yOf(fc!, heroBounds);
        final fcClipped = rawFcY < plotTop;
        final fcY = rawFcY.clamp(plotTop, plotBottom).toDouble();
        final actY = math.max(
          fcY,
          yOf(heroPts[lastI], heroBounds).clamp(plotTop, plotBottom).toDouble(),
        );
        const colW = 8.0;
        const r = Radius.circular(2.0);
        // ① 预测区：从「上个完整月和本月的中间」往右铺一层极淡的底，加一道
        //   点状竖线 —— 右边都是还没发生的。原来那只虚框去掉，交给区间扇面。
        final zoneX = solidN >= 1
            ? (xOf(solidN - 1) + lastX) / 2
            : lastX - colW;
        canvas.drawRect(
          Rect.fromLTRB(zoneX, 0, size.width, plotBottom),
          Paint()..color = _kLhForecastZoneTint,
        );
        _trendDashedLine(
          canvas,
          Offset(zoneX, math.max(0.0, plotTop - 6)),
          Offset(zoneX, plotBottom),
          Paint()
            ..color = _LhPlum.deep.withAlpha(46)
            ..strokeWidth = 0.7,
          dash: 1.6,
          gap: 2.4,
        );
        // ② 实柱：已发生
        if (plotBottom - actY > 0.5) {
          canvas.drawRRect(
            RRect.fromLTRBAndCorners(
              lastX - colW / 2,
              actY,
              lastX + colW / 2,
              plotBottom,
              topLeft: r,
              topRight: r,
            ),
            Paint()
              ..shader =
                  LinearGradient(
                    begin: Alignment.topCenter,
                    end: Alignment.bottomCenter,
                    // 已发生只是「到今天为止」，压淡一档，别抢预测点的戏。
                    colors: [heroColor.withAlpha(150), heroColor.withAlpha(60)],
                  ).createShader(
                    Rect.fromLTRB(
                      lastX - colW / 2,
                      actY,
                      lastX + colW / 2,
                      plotBottom,
                    ),
                  ),
          );
        }
        // ③ 上个完整月 → 月末预测
        if (solidN >= 1) {
          final prev = Offset(
            xOf(solidN - 1),
            yOf(heroPts[solidN - 1], heroBounds),
          );
          _trendDashedLine(
            canvas,
            prev,
            Offset(lastX, fcY),
            Paint()
              ..color = heroColor.withAlpha(170)
              ..strokeWidth = 1.2
              ..strokeCap = StrokeCap.round,
            dash: 3,
            gap: 2.6,
          );
        }
        // ③′ 80% 区间扇面：从上个完整月（已知，宽度为 0）张开到本月预测的
        //   上下沿；有之后各月时，右边那张画布（_LhFutureMonthsPainter）接着张。
        final bLo = forecastLo;
        final bHi = forecastHi;
        if (bLo != null && bHi != null && bHi > bLo && solidN >= 1) {
          final yHi = yOf(
            bHi,
            heroBounds,
          ).clamp(plotTop, plotBottom).toDouble();
          final yLo = yOf(
            bLo,
            heroBounds,
          ).clamp(plotTop, plotBottom).toDouble();
          final from = Offset(
            xOf(solidN - 1),
            yOf(heroPts[solidN - 1], heroBounds),
          );
          final cone = Path()
            ..moveTo(from.dx, from.dy)
            ..lineTo(lastX, yHi)
            ..lineTo(lastX, yLo)
            ..close();
          canvas.drawPath(cone, Paint()..color = heroColor.withAlpha(26));
          final edge = Paint()
            ..color = heroColor.withAlpha(70)
            ..strokeWidth = 0.7;
          canvas.drawLine(from, Offset(lastX, yHi), edge);
          canvas.drawLine(from, Offset(lastX, yLo), edge);
        }
        // ④ 预测点：空心圈；超出图顶时顶端加一个小三角，表示「还在上面」。
        canvas.drawCircle(
          Offset(lastX, fcY),
          2.8,
          Paint()..color = Colors.white,
        );
        canvas.drawCircle(
          Offset(lastX, fcY),
          2.8,
          Paint()
            ..color = heroColor
            ..style = PaintingStyle.stroke
            ..strokeWidth = 1.2,
        );
        if (fcClipped) {
          final tri = Path()
            ..moveTo(lastX, fcY - 8.5)
            ..lineTo(lastX - 3, fcY - 4.8)
            ..lineTo(lastX + 3, fcY - 4.8)
            ..close();
          canvas.drawPath(tri, Paint()..color = heroColor);
        }
        // ⑤ 「预测」写在预测区的左上角（原来贴着预测点，会和区间扇面打架）。
        final tp = TextPainter(
          text: TextSpan(
            text: '预测',
            style: LhTypography.mono(
              size: 7.5,
              color: _LhPlum.deep.withAlpha(150),
              weight: FontWeight.w700,
              letterSpacing: 0.4,
            ),
          ),
          textDirection: TextDirection.ltr,
        )..layout();
        tp.paint(
          canvas,
          Offset(zoneX + 3, math.max(0.0, plotTop - tp.height - 1)),
        );
      }
    }

    // ── 7. 底部小柱层（各自归一的上下文序列）──────────────────────────────
    if (geo.lane && candles) {
      // 副图：MACD(12,26,9)。柱 = 2 ×（DIF − DEA），正粉负绿；DIF 粉线、DEA 蓝线。
      final dif = macdDif;
      final dea = macdDea;
      final laneTop = geo.laneTop;
      final laneBottom = geo.laneBottom;
      final mid = (laneTop + laneBottom) / 2;
      final half = (laneBottom - laneTop) / 2;
      // 副图也套一个数据框，跟主图一样的底色、格子、发丝框。
      final laneRect = Rect.fromLTRB(
        0.4,
        laneTop,
        size.width - 0.4,
        laneBottom,
      );
      canvas.drawRect(laneRect, Paint()..color = const Color(0xFFFCFBFE));
      final laneRule = Paint()
        ..color = const Color(0xFFEDEBF2)
        ..strokeWidth = 0.6;
      for (var k = 1; k < 6; k++) {
        final gx = size.width * k / 6;
        canvas.drawLine(Offset(gx, laneTop), Offset(gx, laneBottom), laneRule);
      }
      canvas.drawRect(
        laneRect,
        Paint()
          ..style = PaintingStyle.stroke
          ..strokeWidth = 0.8
          ..color = const Color(0xFFE3DEEC),
      );
      canvas.drawLine(
        Offset(0, mid),
        Offset(size.width, mid),
        Paint()
          ..color = const Color(0xFFE4E2E8)
          ..strokeWidth = 0.6,
      );
      if (dif != null && dea != null) {
        final m = math.min(math.min(dif.length, dea.length), n);
        var maxAbs = 0.0;
        for (var i = 0; i < m; i++) {
          if (!dif[i].isFinite || !dea[i].isFinite) continue;
          final h = 2 * (dif[i] - dea[i]);
          for (final x in [dif[i], dea[i], h]) {
            if (x.abs() > maxAbs) maxAbs = x.abs();
          }
        }
        if (maxAbs > 1e-9) {
          double ly(double v) => mid - v / maxAbs * half;
          final barW = n <= 1 ? 3.0 : (step * 0.5).clamp(1.2, 5.0).toDouble();
          final difPts = <Offset>[];
          final deaPts = <Offset>[];
          for (var i = 0; i < m; i++) {
            if (!dif[i].isFinite || !dea[i].isFinite) continue;
            final h = 2 * (dif[i] - dea[i]);
            final x = xOf(i);
            final y = ly(h);
            canvas.drawRect(
              Rect.fromLTRB(
                x - barW / 2,
                math.min(y, mid),
                x + barW / 2,
                math.max(y, mid),
              ),
              Paint()..color = h >= 0 ? LhKColors.barUp : LhKColors.barDown,
            );
            difPts.add(Offset(x, ly(dif[i])));
            deaPts.add(Offset(x, ly(dea[i])));
          }
          for (final (pts, c) in [
            (difPts, LhKColors.dif),
            (deaPts, LhKColors.dea),
          ]) {
            if (pts.length < 2) continue;
            final path = Path();
            _addSmoothPath(path, pts);
            canvas.drawPath(
              path,
              Paint()
                ..color = c
                ..strokeWidth = 1.1
                ..style = PaintingStyle.stroke
                ..strokeJoin = StrokeJoin.round,
            );
          }
        }
      }
    } else if (geo.lane && laneIndex >= 0) {
      final spec = _trendPaintSpec(
        series: series,
        bounds: bounds,
        colors: colors,
        index: laneIndex,
      );
      final lp = spec.pts;
      final laneN = math.min(lp.length, n);
      if (laneN > 0) {
        final r = _trendLaneRange(lp.sublist(0, laneN), partial: partial);
        final laneTop = geo.laneTop;
        final laneBottom = geo.laneBottom;
        final laneH = laneBottom - laneTop;
        double ly(double v) => (laneTop + (r.hi - v) / (r.hi - r.lo) * laneH)
            .clamp(laneTop, laneBottom)
            .toDouble();
        final zeroY = ly(0);
        canvas.drawLine(
          Offset(left, zeroY),
          Offset(right, zeroY),
          Paint()
            ..color = _LhPlum.deep.withAlpha(26)
            ..strokeWidth = 0.6,
        );
        final barW = n <= 1 ? 4.0 : (step * 0.42).clamp(2.0, 9.0).toDouble();
        for (var i = 0; i < laneN; i++) {
          final v = lp[i];
          if (v.abs() < 1e-9) continue;
          final y = ly(v);
          final x = xOf(i);
          final t = math.min(y, zeroY);
          final b = math.max(math.max(y, zeroY), t + 1.0);
          final unfinished = partial && i == laneN - 1;
          // 利润小柱同样赚红亏绿；其余序列只有负值才走绿。
          final base = v < 0
              ? LhColors.pos
              : (laneIndex == lighthouseTrendProfitIndex
                    ? LhColors.neg
                    : spec.color);
          canvas.drawRRect(
            RRect.fromLTRBR(
              x - barW / 2,
              t,
              x + barW / 2,
              b,
              const Radius.circular(1.5),
            ),
            Paint()..color = base.withAlpha(unfinished ? 48 : 108),
          );
        }
      }
    }
  }

  @override
  bool shouldRepaint(_TrendLinesPainter old) =>
      !identical(old.series, series) ||
      !identical(old.bounds, bounds) ||
      old.padH != padH ||
      old.scaleForecast != scaleForecast ||
      old.heroIndexOverride != heroIndexOverride ||
      old.keepPaletteColor != keepPaletteColor ||
      old.extremeLo != extremeLo ||
      old.extremeHi != extremeHi ||
      old.showEndpoint != showEndpoint ||
      old.profitPartial != profitPartial ||
      old.profitPace != profitPace ||
      old.forecastLo != forecastLo ||
      old.forecastHi != forecastHi ||
      old.candles != candles ||
      old.showActual != showActual ||
      old.dotScale != dotScale ||
      !identical(old.maFast, maFast) ||
      !identical(old.nx, nx) ||
      !identical(old.macdDif, macdDif) ||
      !identical(old.maSlow, maSlow) ||
      !identical(old.colors, colors) ||
      !listEquals(old.available, available);
}

// ── Overlay painter (light; runs every drag frame) ───────────────────────────
class _TrendOverlayPainter extends CustomPainter {
  const _TrendOverlayPainter({
    required this.series,
    required this.bounds,
    required this.colors,
    required this.padH,
    required this.selectedIndex,
    this.available = const [true, true, true, false, false, false],
    this.heroIndexOverride,
    this.scaleForecast,
    this.paceForecastPicked = false,
    this.profitForecastValue,
    this.dotScale = 1.0,
    this.candles = false,
  });

  /// 日 K 模式：副图换成均线差，几何要跟 lines painter 一致（总有副图）。
  final bool candles;

  /// 游标点大小倍数（全屏大图缩小一圈）。
  final double dotScale;
  final _TrendSeries series;
  final _TrendBounds bounds;
  final List<Color> colors;
  final double padH;
  final int? selectedIndex;

  /// 当月那一列点中的是「月末预测」那个点：游标大点挪到预测点上。
  final bool paceForecastPicked;

  /// 利润主线的月末外推值（虚框顶）；点中预测时游标落在这里。
  final double? profitForecastValue;
  final List<bool> available;

  /// 与 lines painter 同一个口径：solo 时游标的实心大点跟着 solo 那条走。
  final int? heroIndexOverride;

  /// 与 lines painter 同一个口径：没走完那期的游标点落在进度胶囊的实心顶。
  final double? scaleForecast;

  @override
  void paint(Canvas canvas, Size size) {
    final si = selectedIndex;
    if (si == null) return;
    final n = series.revenue.length;
    if (si < 0 || si >= n) return;

    final flags = _trendNormalizeFlags(available);
    final heroIndex = _trendResolveHero(flags, heroIndexOverride);
    final laneIndex = lighthouseTrendLaneIndex(flags, heroIndex);
    final geo = lighthouseTrendCanvasGeometry(
      size.height,
      wantsLane: laneIndex >= 0 || candles,
    );
    final plotTop = geo.plotTop;
    final plotBottom = geo.plotBottom;
    final usableH = plotBottom - plotTop;
    if (usableH <= 4) return;
    final usableW = size.width - padH * 2;
    final step = n <= 1 ? 0.0 : usableW / (n - 1);

    final x = padH + si * step;
    double yOf(double v, _SeriesRange r) =>
        plotTop + (r.max - v) / r.span * usableH;

    // 竖游标：实线发丝，贯穿主图和小柱层
    canvas.drawLine(
      Offset(x, plotTop - 4),
      Offset(x, geo.lane ? geo.laneBottom : plotBottom),
      Paint()
        ..color = candles
            ? LhKColors.tint(_LhPlum.deep, 0.62)
            : _LhPlum.deep.withAlpha(64)
        ..strokeWidth = 0.8,
    );

    void softMarker(double cy, Color color) {
      canvas.drawCircle(
        Offset(x, cy),
        3.0 * dotScale,
        Paint()..color = Colors.white,
      );
      canvas.drawCircle(
        Offset(x, cy),
        3.0 * dotScale,
        Paint()
          ..color = color.withAlpha(200)
          ..style = PaintingStyle.stroke
          ..strokeWidth = 1.0,
      );
    }

    void heroMarker(double cy, Color color) {
      canvas.drawCircle(
        Offset(x, cy),
        7.0 * dotScale,
        Paint()..color = color.withAlpha(50),
      );
      canvas.drawCircle(
        Offset(x, cy),
        4.5 * dotScale,
        Paint()..color = Colors.white,
      );
      canvas.drawCircle(
        Offset(x, cy),
        4.5 * dotScale,
        Paint()
          ..color = color
          ..style = PaintingStyle.stroke
          ..strokeWidth = 1.6 * math.max(0.75, dotScale),
      );
      canvas.drawCircle(Offset(x, cy), 2.2 * dotScale, Paint()..color = color);
    }

    final heroSpec = _trendPaintSpec(
      series: series,
      bounds: bounds,
      colors: colors,
      index: heroIndex,
    );
    final heroPts = heroSpec.pts;
    final fc = scaleForecast;
    final partial = _trendIsPartial(
      forecast: fc,
      flags: flags,
      heroIndex: heroIndex,
      heroPts: heroPts,
    );
    final onUnfinished = partial && si == heroPts.length - 1;

    // 小柱层：选中那根换成强调色
    if (geo.lane && laneIndex >= 0 && !candles) {
      final spec = _trendPaintSpec(
        series: series,
        bounds: bounds,
        colors: colors,
        index: laneIndex,
      );
      final lp = spec.pts;
      final laneN = math.min(lp.length, n);
      if (si < laneN && lp[si].abs() >= 1e-9) {
        final r = _trendLaneRange(lp.sublist(0, laneN), partial: partial);
        final laneH = geo.laneBottom - geo.laneTop;
        double ly(double v) =>
            (geo.laneTop + (r.hi - v) / (r.hi - r.lo) * laneH)
                .clamp(geo.laneTop, geo.laneBottom)
                .toDouble();
        final zeroY = ly(0);
        final y = ly(lp[si]);
        final barW = n <= 1 ? 4.0 : (step * 0.42).clamp(2.0, 9.0).toDouble();
        final t = math.min(y, zeroY);
        final b = math.max(math.max(y, zeroY), t + 1.0);
        canvas.drawRRect(
          RRect.fromLTRBR(
            x - barW / 2,
            t,
            x + barW / 2,
            b,
            const Radius.circular(1.5),
          ),
          Paint()
            ..color = lp[si] < 0
                ? LhColors.pos
                : (laneIndex == lighthouseTrendProfitIndex
                          ? LhColors.neg
                          : _LhPlum.deep)
                      .withAlpha(onUnfinished ? 120 : 220),
        );
      }
    }

    if (_trendAltDrawable(
          series: series,
          bounds: bounds,
          flags: flags,
          heroIndex: heroIndex,
        ) &&
        !onUnfinished &&
        si < series.scaleAlt.length) {
      final altSpec = _trendPaintSpec(
        series: series,
        bounds: bounds,
        colors: colors,
        index: 4,
      );
      softMarker(yOf(series.scaleAlt[si], altSpec.range), altSpec.color);
    }

    if (flags[heroIndex] && si < heroPts.length) {
      if (onUnfinished) {
        final fcY = yOf(
          fc!,
          heroSpec.range,
        ).clamp(plotTop, plotBottom).toDouble();
        // v18 · 游标落在「已发生」实柱顶 —— 真实刻度，不再是日历进度。
        heroMarker(
          paceForecastPicked
              ? fcY
              : math.max(
                  fcY,
                  yOf(
                    heroPts[si],
                    heroSpec.range,
                  ).clamp(plotTop, plotBottom).toDouble(),
                ),
          heroSpec.color,
        );
      } else {
        final markerColor = heroIndex == lighthouseTrendProfitIndex
            ? (lighthouseTrendValueEarns(heroPts[si])
                  ? LhColors.neg
                  : LhColors.pos)
            : heroSpec.color;
        final pfv = profitForecastValue;
        final onProfitForecast =
            paceForecastPicked &&
            pfv != null &&
            heroIndex == lighthouseTrendProfitIndex &&
            si == heroPts.length - 1;
        heroMarker(
          yOf(
            onProfitForecast ? pfv : heroPts[si],
            heroSpec.range,
          ).clamp(plotTop, plotBottom).toDouble(),
          markerColor,
        );
      }
    }
  }

  @override
  bool shouldRepaint(_TrendOverlayPainter old) =>
      old.selectedIndex != selectedIndex ||
      old.paceForecastPicked != paceForecastPicked ||
      old.profitForecastValue != profitForecastValue ||
      old.heroIndexOverride != heroIndexOverride ||
      old.scaleForecast != scaleForecast ||
      !identical(old.series, series) ||
      !identical(old.bounds, bounds) ||
      old.padH != padH ||
      !listEquals(old.available, available);
}

// ═════════════════════════════════════════════════════════════════════════════
// ═════════════════════════════════════════════════════════════════════════════
// _LhHeroSparkline —— hero 大 sparkline 的 stateful wrap:
//   v3 (2026-07 · pro chart interaction):
//     · 首次 build: 900ms progress 0→1 easeOutCubic 绘出
//     · 每 1600ms 无限循环 pulse 0→1 (端点呼吸圈, 数据活体感)
//     · 每 3200ms 无限循环 shimmer 0→1 —— 高亮光点沿主线扫过 (live feed 感)
//     · Tap / 横向拖动：hit-test 到最近数据点, 显示垂直虚线 + halo + tooltip
//       - 触感反馈: HapticFeedback.selectionClick (index 变化时)
//       - 再次 tap 相同点 → 清除选中, 回到 idle shimmer 态
//       - 横向 drag 让父级 Scroll 保留垂直手势
//     · data 更换时重置绘出动画 + 清理越界 selectedIndex
// ═════════════════════════════════════════════════════════════════════════════
class _LhHeroSparkline extends StatefulWidget {
  const _LhHeroSparkline({
    required this.data,
    required this.color,
    this.labels = const [],
    this.compare,
    this.height = 60,
  });
  final List<double> data;
  final List<String> labels;
  final List<double>? compare;
  final Color color;
  final double height;

  @override
  State<_LhHeroSparkline> createState() => _LhHeroSparklineState();
}

class _LhHeroSparklineState extends State<_LhHeroSparkline>
    with TickerProviderStateMixin {
  late final AnimationController _draw;
  late final AnimationController _pulse;
  late final AnimationController _shimmer;
  late final AnimationController _selectFade; // selectedIndex halo/tooltip 淡入

  int? _selectedIndex;
  double _lastWidth = 0;

  // 与极简 painter 的无坐标轴绘图区保持一致。
  static const double _padH = 10.0;
  static const double _padRight = 10.0;

  @override
  void initState() {
    super.initState();
    _draw = AnimationController(
      vsync: this,
      duration: const Duration(milliseconds: 900),
    )..forward();
    _pulse = AnimationController(
      vsync: this,
      duration: const Duration(milliseconds: 1600),
    )..repeat();
    _shimmer = AnimationController(
      vsync: this,
      duration: const Duration(milliseconds: 3200),
    )..repeat();
    _selectFade = AnimationController(
      vsync: this,
      duration: const Duration(milliseconds: 180),
      value: 0,
    );
  }

  @override
  void didUpdateWidget(_LhHeroSparkline old) {
    super.didUpdateWidget(old);
    if (!identical(old.data, widget.data) && !_listEq(old.data, widget.data)) {
      _draw
        ..stop()
        ..forward(from: 0);
      // data 换了 → 清理越界选中, 避免 painter 抓不到
      if (_selectedIndex != null && _selectedIndex! >= widget.data.length) {
        _selectedIndex = null;
        _selectFade.value = 0;
      }
    }
  }

  bool _listEq(List<double> a, List<double> b) {
    if (a.length != b.length) return false;
    for (int i = 0; i < a.length; i++) {
      if (a[i] != b[i]) return false;
    }
    return true;
  }

  @override
  void dispose() {
    _draw.dispose();
    _pulse.dispose();
    _shimmer.dispose();
    _selectFade.dispose();
    super.dispose();
  }

  int _hitIndex(double localX, double width) {
    final n = widget.data.length;
    if (n <= 1) return 0;
    final usableW = width - _padH - _padRight;
    final step = usableW / (n - 1);
    if (step <= 0) return 0;
    final relX = localX - _padH;
    return (relX / step).round().clamp(0, n - 1);
  }

  void _setSelected(int? idx) {
    if (idx == _selectedIndex) return;
    LighthouseFeedback.instance.play(
      LighthouseFeedbackKind.select,
      sound: false,
    );
    setState(() => _selectedIndex = idx);
    if (idx == null) {
      _selectFade.reverse();
    } else {
      _selectFade.forward();
    }
  }

  void _onTap(Offset local, double width) {
    if (widget.data.length < 2) return;
    final i = _hitIndex(local.dx, width);
    // 点相同 index → toggle off
    _setSelected(_selectedIndex == i ? null : i);
  }

  void _onDrag(Offset local, double width) {
    if (widget.data.length < 2) return;
    final i = _hitIndex(local.dx, width);
    if (i != _selectedIndex) {
      _setSelected(i);
    }
  }

  @override
  Widget build(BuildContext context) {
    return LayoutBuilder(
      builder: (context, constraints) {
        if (constraints.maxWidth.isFinite && constraints.maxWidth > 0) {
          _lastWidth = constraints.maxWidth;
        }
        final w = _lastWidth;
        return GestureDetector(
          behavior: HitTestBehavior.opaque,
          // Tap: 单点选中 / 再点清除
          onTapDown: (d) => _onTap(d.localPosition, w),
          // Horizontal drag: 扫描. 垂直方向让给父级 Scrollable.
          onHorizontalDragStart: (d) => _onDrag(d.localPosition, w),
          onHorizontalDragUpdate: (d) => _onDrag(d.localPosition, w),
          child: AnimatedBuilder(
            animation: Listenable.merge([_draw, _pulse, _shimmer, _selectFade]),
            builder: (_, __) => CustomPaint(
              size: Size(double.infinity, widget.height),
              painter: _HeroBigSparkPainter(
                data: widget.data,
                labels: widget.labels,
                color: widget.color,
                compare: widget.compare,
                progress: Curves.easeOutCubic.transform(_draw.value),
                pulse: _pulse.value,
                shimmer: _shimmer.value,
                selectedIndex: _selectedIndex,
                selectAlpha: Curves.easeOutCubic.transform(_selectFade.value),
              ),
            ),
          ),
        );
      },
    );
  }
}

//   在 v1 之上：
//     · 底部虚线 baseline (avg 或 zero) —— 数据分析的锚点
//     · min / max 数据点 halo + 值标 (mono 小号) —— pro chart 语言
//     · 主线右侧末端「呼吸圈」(pulse 参数控制) —— 视觉活体感
//     · compare 参数支持 ghost 对比线 (上期同期, 虚线淡色)
//     · progress 参数继续控制左→右 tween 绘出
// ═════════════════════════════════════════════════════════════════════════════
class _HeroBigSparkPainter extends CustomPainter {
  const _HeroBigSparkPainter({
    required this.data,
    required this.color,
    this.labels = const [],
    this.compare,
    this.progress = 1.0,
    this.pulse = 0.0,
    this.shimmer = 0.0,
    this.selectedIndex,
    this.selectAlpha = 0.0,
  });
  final List<double> data;
  final List<String> labels;
  final List<double>? compare; // 上期同期 ghost 对比线
  final Color color;
  final double progress; // 0..1 tween 绘出
  final double pulse; // 0..1 无限循环 末端呼吸圈
  final double shimmer; // 0..1 无限循环 —— 沿主线扫过的高亮光点
  final int? selectedIndex; // tap/drag 选中的数据点
  final double selectAlpha; // 0..1 选中态 halo/tooltip 淡入进度

  @override
  void paint(Canvas canvas, Size size) {
    if (data.length < 2 || progress <= 0.0) return;

    // 值域计算 (data + compare 联合)，绘图区仅为标签留白，不绘制坐标轴。
    final allValues = <double>[...data, if (compare != null) ...compare!];
    final axisTicks = lighthouseHeroAxisTicks(allValues);
    final minV = axisTicks.first;
    final maxV = axisTicks.last;
    final range = maxV - minV;
    const plotLeft = 10.0;
    final plotRight = size.width - 10;
    const plotTop = 12.0;
    final plotBottom = size.height - 18;
    final usableW = math.max(1.0, plotRight - plotLeft);
    final usableH = math.max(1.0, plotBottom - plotTop);

    final step = usableW / (data.length - 1);
    double xOf(int i) => plotLeft + i * step;
    double yOf(double v) => plotTop + (maxV - v) / range * usableH;

    // 选中态时 idle 装饰淡化系数。
    final idleFade = (1.0 - selectAlpha).clamp(0.0, 1.0);
    final hasSelection =
        selectedIndex != null &&
        selectedIndex! >= 0 &&
        selectedIndex! < data.length &&
        selectAlpha > 0.001;

    // Compare ghost line (可选)。
    if (compare != null && compare!.length >= 2) {
      final n = math.min(compare!.length, data.length);
      final ghostPath = Path()..moveTo(xOf(0), yOf(compare![0]));
      for (int i = 1; i < n; i++) {
        ghostPath.lineTo(xOf(i), yOf(compare![i]));
      }
      final ghostPaint = Paint()
        ..color = LhColors.mute2.withAlpha(110)
        ..strokeWidth = 1.0
        ..style = PaintingStyle.stroke
        ..strokeCap = StrokeCap.round;
      // 虚线笔画
      _drawDashedPath(canvas, ghostPath, ghostPaint, dash: 2, gap: 2.5);
    }

    // ── § 3. 主线 (Catmull-Rom 平滑 · tween 绘出) ─────
    // v3.1 · 主线换 smooth 曲线, tween 绘出改用 PathMetric.extractPath
    //        —— shimmer 光点沿曲线跑 = 无硬转折; 主线本身也不再"崎岖".
    final offsets = <Offset>[
      for (int i = 0; i < data.length; i++) Offset(xOf(i), yOf(data[i])),
    ];
    final smoothFull = Path();
    _addSmoothPath(smoothFull, offsets);

    final metricsList = smoothFull.computeMetrics().toList(growable: false);
    Path linePath;
    Offset lastPt;
    if (metricsList.isEmpty) {
      // 极端情况: 数据 <2 已在前面短路; 兜底
      linePath = smoothFull;
      lastPt = offsets.last;
    } else {
      final m = metricsList.first;
      final drawLen = m.length * progress.clamp(0.0, 1.0);
      linePath = m.extractPath(0, drawLen);
      final tan = m.getTangentForOffset(drawLen);
      lastPt = tan?.position ?? offsets.last;
    }

    // 渐变填充 (fill under line) —— 用 extractPath 得到的 partial 曲线做上边界
    final fillPath = Path.from(linePath)
      ..lineTo(lastPt.dx, plotBottom)
      ..lineTo(offsets.first.dx, plotBottom)
      ..close();
    final rect = Rect.fromLTRB(plotLeft, plotTop, plotRight, plotBottom);
    canvas.drawPath(
      fillPath,
      Paint()
        ..shader = LinearGradient(
          begin: Alignment.topCenter,
          end: Alignment.bottomCenter,
          colors: [color.withAlpha(60), color.withAlpha(0)],
        ).createShader(rect),
    );

    // 主线 描边
    canvas.drawPath(
      linePath,
      Paint()
        ..color = color.withAlpha(230)
        ..strokeWidth = 1.8
        ..style = PaintingStyle.stroke
        ..strokeCap = StrokeCap.round
        ..strokeJoin = StrokeJoin.round,
    );

    // 每个数据点 + 数值标签 + 周期标签。
    // 标签上下交错，首尾向内收，保证所有点都有数字且不被画布裁切。
    if (progress >= 1.0) {
      var maxIndex = 0;
      for (var i = 1; i < data.length; i++) {
        if (data[i] > data[maxIndex]) maxIndex = i;
      }
      for (final i in lighthouseHeroSparkLabelIndices(data.length)) {
        final pt = Offset(xOf(i), yOf(data[i]));
        final emphasized = i == maxIndex || i == data.length - 1;
        canvas.drawCircle(
          pt,
          emphasized ? 2.4 : 1.6,
          Paint()..color = color.withAlpha(emphasized ? 245 : 190),
        );

        if (lighthouseHeroSparkShowsEveryValue || emphasized) {
          final labelPainter = TextPainter(
            text: TextSpan(
              text: _fmtExtremeShort(data[i]),
              style: TextStyle(
                fontFamily: 'monospace',
                fontSize: 7,
                color: color.withAlpha(emphasized ? 245 : 205),
                fontWeight: emphasized ? FontWeight.w800 : FontWeight.w700,
                letterSpacing: 0,
              ),
            ),
            textDirection: TextDirection.ltr,
            maxLines: 1,
          )..layout();

          final canPlaceAbove = pt.dy - labelPainter.height - 4 >= plotTop;
          final canPlaceBelow = pt.dy + labelPainter.height + 4 <= plotBottom;
          final placeAbove = canPlaceAbove && (!canPlaceBelow || i.isEven);
          var x = pt.dx - labelPainter.width / 2;
          var y = placeAbove ? pt.dy - labelPainter.height - 4 : pt.dy + 4;
          x = x.clamp(
            plotLeft,
            math.max(plotLeft, plotRight - labelPainter.width),
          );
          y = y.clamp(
            plotTop,
            math.max(plotTop, plotBottom - labelPainter.height),
          );
          labelPainter.paint(canvas, Offset(x, y));
        }

        if (lighthouseHeroSparkShowsEveryPeriodLabel ||
            i == 0 ||
            i == data.length - 1) {
          final rawPeriod = i < labels.length && labels[i].trim().isNotEmpty
              ? labels[i].trim()
              : (i == data.length - 1 ? '现' : 'T−${data.length - 1 - i}');
          final periodPainter = TextPainter(
            text: TextSpan(
              text: lighthouseHeroCompactPeriodLabel(rawPeriod),
              style: TextStyle(
                fontFamily: 'monospace',
                fontSize: 6.5,
                color: emphasized ? LhColors.ink2 : LhColors.mute2,
                fontWeight: emphasized ? FontWeight.w700 : FontWeight.w500,
                letterSpacing: 0,
              ),
            ),
            textDirection: TextDirection.ltr,
            maxLines: 1,
          )..layout(maxWidth: math.max(20, step - 2));
          final periodX = (pt.dx - periodPainter.width / 2)
              .clamp(0.0, math.max(0.0, size.width - periodPainter.width))
              .toDouble();
          periodPainter.paint(
            canvas,
            Offset(periodX, size.height - periodPainter.height - 1),
          );
        }
      }
    }

    // ── § 5. 末端 halo + pulse 呼吸圈 ─────────────────
    // 选中态时用 idleFade 淡化, 让选中点独占焦点
    final endPulseR = 4 + pulse * 8;
    final endPulseA = (60 * (1 - pulse) * idleFade).round();
    if (endPulseA > 0) {
      canvas.drawCircle(
        lastPt,
        endPulseR,
        Paint()..color = color.withAlpha(endPulseA),
      );
    }
    canvas.drawCircle(
      lastPt,
      6.0,
      Paint()..color = color.withAlpha((20 * idleFade).round()),
    );
    canvas.drawCircle(
      lastPt,
      3.2,
      Paint()..color = color.withAlpha((90 * idleFade).round()),
    );
    canvas.drawCircle(
      lastPt,
      2.0,
      Paint()..color = color.withAlpha((255 * (0.4 + idleFade * 0.6)).round()),
    );
    canvas.drawCircle(
      lastPt,
      0.9,
      Paint()
        ..color = Colors.white.withAlpha(
          (255 * (0.4 + idleFade * 0.6)).round(),
        ),
    );

    // ── § 6. Shimmer 高亮点 —— 沿主线扫过 (live feed 感) ─
    //   条件: 主线绘出完成 && 未选中 && shimmer 装饰未被 idle 淡化到 0
    if (progress >= 1.0 && idleFade > 0.05) {
      // 用 easeInOutSine 做加减速, 中段更快, 起止更从容 (不刺眼)
      final t = Curves.easeInOutSine.transform(shimmer);
      // 两端 alpha 淡入淡出 (前 12% rise, 后 12% fall) —— 避免"突现/突失"
      double alpha;
      if (t < 0.12) {
        alpha = t / 0.12;
      } else if (t > 0.88) {
        alpha = (1 - t) / 0.12;
      } else {
        alpha = 1.0;
      }
      alpha *= idleFade;
      // v3.1 · Shimmer 沿完整平滑曲线跑 (metricsList 已算过), 与主线共享同一 metric —
      // 避免 extractPath 之后 computeMetrics 重算带来的小抖动.
      if (metricsList.isNotEmpty && alpha > 0.02) {
        final metric = metricsList.first;
        final tangent = metric.getTangentForOffset(t * metric.length);
        if (tangent != null) {
          final pt = tangent.position;
          final a2 = (alpha * 255).clamp(0, 255).toInt();
          final aHalo = (alpha * 55).clamp(0, 255).toInt();
          final aCore = (alpha * 235).clamp(0, 255).toInt();
          // 外层 halo (color-tinted, blur 感靠双圆叠出)
          canvas.drawCircle(pt, 7.0, Paint()..color = color.withAlpha(aHalo));
          canvas.drawCircle(
            pt,
            4.0,
            Paint()
              ..color = color.withAlpha((aHalo * 1.4).clamp(0, 255).toInt()),
          );
          // 中心亮点 (稍带白, 制造 "光" 感)
          canvas.drawCircle(pt, 1.9, Paint()..color = color.withAlpha(aCore));
          canvas.drawCircle(
            pt,
            0.9,
            Paint()..color = Colors.white.withAlpha(a2),
          );
        }
      }
    }

    // Selection overlay —— halo + 完整周期金额 tooltip。
    if (hasSelection) {
      final i = selectedIndex!;
      final pt = Offset(xOf(i), yOf(data[i]));
      final sA = selectAlpha.clamp(0.0, 1.0);

      // 选中 halo (呼吸感靠 sA 弹入)。
      // 主色 halo + 中心圆 + 白心
      final haloOuterA = (36 * sA).round();
      final haloMidA = (80 * sA).round();
      canvas.drawCircle(
        pt,
        9.0 * sA + 4.0,
        Paint()..color = color.withAlpha(haloOuterA),
      );
      canvas.drawCircle(pt, 5.0, Paint()..color = color.withAlpha(haloMidA));
      canvas.drawCircle(
        pt,
        3.0,
        Paint()..color = color.withAlpha((255 * sA).round()),
      );
      canvas.drawCircle(
        pt,
        1.3,
        Paint()..color = Colors.white.withAlpha((255 * sA).round()),
      );

      // Tooltip (真实周期标签 + 值) —— 白底 · 轻描边。
      final n = data.length;
      final relLabel = (i < labels.length && labels[i].trim().isNotEmpty)
          ? labels[i].trim()
          : (i == n - 1 ? '现' : 'T−${n - 1 - i}');
      final valTxt = _fmtExtremeShort(data[i]);

      // 组合一行: "2026.08 · 8.2万"。
      final tt = TextPainter(
        text: TextSpan(
          children: [
            TextSpan(
              text: relLabel,
              style: TextStyle(
                fontFamily: 'monospace',
                fontSize: 8,
                color: LhColors.mute.withAlpha((235 * sA).round()),
                fontWeight: FontWeight.w700,
                letterSpacing: 0.6,
              ),
            ),
            TextSpan(text: '  ·  ', style: const TextStyle(fontSize: 8)),
            TextSpan(
              text: valTxt,
              style: TextStyle(
                fontFamily: 'monospace',
                fontSize: 9.5,
                color: color.withAlpha((255 * sA).round()),
                fontWeight: FontWeight.w800,
                letterSpacing: 0.2,
              ),
            ),
          ],
        ),
        textDirection: TextDirection.ltr,
      )..layout();

      const padX = 6.0;
      const padYt = 3.0;
      final ttW = tt.width + padX * 2;
      final ttH = tt.height + padYt * 2;

      // 位置: 选中点上方; 空间不足则下方
      double ttX = pt.dx - ttW / 2;
      double ttY = pt.dy - ttH - 8;
      final wantsBelow = ttY < 0;
      if (wantsBelow) {
        ttY = pt.dy + 8;
      }
      // 水平边界保护
      if (ttX < 0) ttX = 0;
      if (ttX + ttW > size.width) ttX = size.width - ttW;

      final ttRect = RRect.fromRectAndRadius(
        Rect.fromLTWH(ttX, ttY, ttW, ttH),
        const Radius.circular(7),
      );

      // 极淡 drop shadow (编辑体审美 · 不用 Material 大阴影)
      canvas.drawRRect(
        ttRect.shift(const Offset(0, 0.6)),
        Paint()
          ..color = Colors.black.withAlpha((14 * sA).round())
          ..maskFilter = const MaskFilter.blur(BlurStyle.normal, 1.4),
      );
      // 白底
      canvas.drawRRect(
        ttRect,
        Paint()..color = LhColors.paper.withAlpha((255 * sA).round()),
      );
      // 描边: ink hairline
      canvas.drawRRect(
        ttRect,
        Paint()
          ..color = LhColors.ink.withAlpha((90 * sA).round())
          ..strokeWidth = 0.6
          ..style = PaintingStyle.stroke,
      );

      // 文本
      tt.paint(canvas, Offset(ttX + padX, ttY + padYt));

      // 小三角连接 —— tooltip → 选中点 (方向随位置切换)
      final triPaint = Paint()
        ..color = LhColors.paper.withAlpha((255 * sA).round())
        ..style = PaintingStyle.fill;
      final triStrokePaint = Paint()
        ..color = LhColors.ink.withAlpha((90 * sA).round())
        ..strokeWidth = 0.6
        ..style = PaintingStyle.stroke;
      final tri = Path();
      if (wantsBelow) {
        // 三角朝上, 在 tooltip 顶边中央
        final apex = Offset(pt.dx.clamp(ttX + 6, ttX + ttW - 6), ttY);
        tri
          ..moveTo(apex.dx - 3, apex.dy)
          ..lineTo(apex.dx, apex.dy - 3)
          ..lineTo(apex.dx + 3, apex.dy)
          ..close();
      } else {
        // 三角朝下, 在 tooltip 底边中央
        final apex = Offset(pt.dx.clamp(ttX + 6, ttX + ttW - 6), ttY + ttH);
        tri
          ..moveTo(apex.dx - 3, apex.dy)
          ..lineTo(apex.dx, apex.dy + 3)
          ..lineTo(apex.dx + 3, apex.dy)
          ..close();
      }
      canvas.drawPath(tri, triPaint);
      canvas.drawPath(tri, triStrokePaint);
    }
  }

  static void _drawDashedPath(
    Canvas canvas,
    Path path,
    Paint paint, {
    required double dash,
    required double gap,
  }) {
    for (final metric in path.computeMetrics()) {
      double d = 0;
      while (d < metric.length) {
        final e = math.min(d + dash, metric.length);
        canvas.drawPath(metric.extractPath(d, e), paint);
        d = e + gap;
      }
    }
  }

  static String _fmtExtremeShort(double v) => _fmtChartShort(v);

  @override
  bool shouldRepaint(_HeroBigSparkPainter old) =>
      !identical(old.data, data) ||
      !identical(old.labels, labels) ||
      old.color != color ||
      old.progress != progress ||
      old.pulse != pulse ||
      old.shimmer != shimmer ||
      old.selectedIndex != selectedIndex ||
      old.selectAlpha != selectAlpha ||
      !identical(old.compare, compare);
}

// ═════════════════════════════════════════════════════════════════════════════
// Hero 走势图 (v18 · 山脊)
//
//   v15 把五条线各自归一化后叠进同一个 50pt 带子 —— 等于一张图上放了五套刻度，
//   线的高低和交叉点都不表示任何事。v16 拆成三种排版（五联 / 山脊 / 主图+副轨）
//   来给每条线自己的地盘。v18 砍到只剩山脊一种：三选一的 chip 本身要占标题行
//   的位置，而三种里只有山脊同时满足「五条一起看」和「同日事件能对齐」。
//
//   山脊的关键参数是 overlap = 振幅 / 行距：
//     overlap = 1    五条贴着排，互不相犯，但 98pt 的卡里每条只剩 12pt，
//                    折线压成一条几乎平的横杠 —— 这是 v17 的病。
//     overlap = 2.2  每条振幅 ≈ 26pt，山脊互相叠上去一截。起落回来了，
//                    而且前面的山把后面的挡掉一段，五条不会糊成一团。
//   叠加的代价说清楚：跨条比高度没有意义（每条自己一套值域），所以每条的
//   名字、基线、读数三样都常驻，颜色只是辅助。要精确读数就点右下角放大。
// ═════════════════════════════════════════════════════════════════════════════

/// 主线跑珠总开关。
///
/// 这一条是明知故犯 —— §6.27 写着「禁止无限循环的装饰动画」，理由是仪表盘被
/// 长时间盯着，永动的东西会从「有活力」变成噪音，还白耗一整块屏幕的重绘。
/// 产品明确要它，那就把代价压到最小：只有主线一颗、扫描时立刻停、系统减弱
/// 动效时不跑、CustomPaint 外面套 RepaintBoundary（重绘只烧图卡不烧整页）。
/// 想彻底关掉：把这里改成 false，其余代码不用动。
const bool _kHeroBeadEnabled = true;
const int _kHeroBeadPeriodMs = 2800;

/// Hero 走势里的一条线。
///
/// [hero] 只允许一条 —— 它拿最粗的线宽、最实的颜色，以及那颗跑珠。
class _HeroTrendLine {
  const _HeroTrendLine({
    required this.key,
    required this.name,
    required this.color,
    required this.values,
    this.total,
    this.sharedRange = false,
    this.hero = false,
  });

  final String key;

  /// 图上的短名（两个字）。全称留给 stat rail 和详情面板。
  final String name;
  final Color color;
  final List<double> values;

  /// 本期真实合计（与 hero 大数同口径）。缺省时回退序列末点 —— 走势序列覆盖
  /// 近 N 期，任何情况下都不许对序列求和冒充「本期合计」。
  final double? total;

  /// 规模族标记（核销 / 销售同单位）。两条不叠成带 —— 叠的前提是差得开，而
  /// 实测核销/销售常年只差个位数百分点，带宽画出来不到 2px。现在它只用来把
  /// 非主线的那条规模压淡一档。
  final bool sharedRange;
  final bool hero;

  /// 空序列和全 0 都算「这个维度没数据」：后端有时只下发部分字段，pad 成全 0
  /// 会在图上多出一条贴底的假线，读数里多出一个恒为 0 的数。
  bool get hasData {
    if (values.length < 2) return false;
    for (final v in values) {
      if (v.abs() > 1e-9) return true;
    }
    return false;
  }

  double get lastOrTotal => total ?? (values.isNotEmpty ? values.last : 0.0);

  _HeroTrendLine asHero() => _HeroTrendLine(
    key: key,
    name: name,
    color: color,
    values: values,
    total: total,
    sharedRange: sharedRange,
    hero: true,
  );
}

/// 一条序列的 Y 值域 —— nice-number 版。
///
/// 旧版是「min/max 各外扩 span 的百分之几」。百分比 padding 有两个毛病：
///   1. 边界落在 137.4 这种数上 —— 任何刻度、任何网格都没法心算；
///   2. padding 跟着 span 变，数据一刷新整条线就在格子里上下漂，
///      看起来像「形状变了」，其实只是留白变了。
/// 现在先求 nice step（span/3 落到 1/2/2.5/5 × 10^k），再把上下界向外取整到
/// step 的整数倍，然后上下各留 [headSteps]/[footSteps] 个 step 的空气。留白量
/// 由 step 决定，边界因此永远是整数，且只在跨过一个 step 时才动一次。
_SeriesRange _heroNiceRange(
  List<double> values, {
  double headSteps = 0.5,
  double footSteps = 0.5,
}) {
  if (values.isEmpty) return const _SeriesRange(0, 1);
  var mn = values.first;
  var mx = values.first;
  for (final v in values) {
    if (v < mn) mn = v;
    if (v > mx) mx = v;
  }
  final span = mx - mn;
  if (span.abs() < 1e-9) {
    // 全等值：给一个对称的假 span 让线居中，别让它贴在格子边上。
    final pad = math.max(mx.abs() * 0.1, 1.0);
    return _SeriesRange(mn - pad, mx + pad);
  }
  final step = _niceStep(span);
  final lo = (mn / step).floorToDouble() * step - step * footSteps;
  final hi = (mx / step).ceilToDouble() * step + step * headSteps;
  if (hi - lo < 1e-9) return _SeriesRange(lo, lo + step);
  return _SeriesRange(lo, hi);
}

_SeriesRange _heroPaneRange(Iterable<_HeroTrendLine> pane) {
  final values = <double>[for (final l in pane) ...l.values];
  var r = _heroNiceRange(values, headSteps: 0.2, footSteps: 0.15);
  if (lighthouseHeroPaneSnapsToZero(min: r.min, max: r.max)) {
    r = _SeriesRange(0, r.max);
  }
  return r;
}

/// 山脊几何 —— 小图和全屏共用同一套算法，放大只是换了 [height] 和 overlap。
///
/// [amp] / [pitch] = overlap：等于 1 时五条贴着排、互不相犯；大于 1 才叠上去。
/// 小图取 2.2（叠得狠，98pt 里才有起落），全屏取 1.15（每条要留出自己的刻度
/// 带，叠太多刻度会被前面那条山盖住）。
class _RidgeGeom {
  const _RidgeGeom({
    required this.top,
    required this.pitch,
    required this.amp,
    required this.count,
  });

  final double top;
  final double pitch;
  final double amp;
  final int count;

  factory _RidgeGeom.fit({
    required double top,
    required double height,
    required int count,
    required double overlap,
  }) {
    final c = count < 1 ? 1 : count;
    // height = pitch * (c - 1) + amp = pitch * (c - 1 + overlap)
    final denom = (c - 1) + overlap;
    final pitch = denom <= 0 ? height : height / denom;
    return _RidgeGeom(top: top, pitch: pitch, amp: pitch * overlap, count: c);
  }

  /// 第 j 条的基线 y。j 越大越靠下，也越靠前（后画，盖住前面的）。
  double baseY(int j) => top + amp + j * pitch;
}

class _LhHeroMultiTrend extends StatefulWidget {
  const _LhHeroMultiTrend({
    required this.lines,
    this.labels = const <String>[],
    this.height = lighthouseCompactHeroSparkHeight,
    this.partialLast = false,
    this.title = '走势',
    this.subtitle = '',
  });

  final List<_HeroTrendLine> lines;
  final List<String> labels;
  final double height;

  /// 末期是不是「还在进行中」（当日只跑了一部分）。
  ///
  /// 没有这个开关的话，当天的四分之一天和昨天的整天会被画成同一种实线，图上
  /// 看起来像业务崩了 —— 这是最常见的一类图表撒谎。为 true 时末段改虚线、
  /// 降到 60% 透明、末点空心、轴末标签挂「进行中」。
  final bool partialLast;

  /// 放大页的抬头（指标口径 + 区间），只在全屏里用。
  final String title;
  final String subtitle;

  @override
  State<_LhHeroMultiTrend> createState() => _LhHeroMultiTrendState();
}

class _LhHeroMultiTrendState extends State<_LhHeroMultiTrend>
    with TickerProviderStateMixin {
  late final AnimationController _draw;
  late final AnimationController _bead;
  late final AnimationController _selectFade;

  int? _selectedIndex;
  double _lastWidth = 0;
  bool _reduceMotion = false;

  int get _pointCount {
    var n = 0;
    for (final l in widget.lines) {
      if (l.values.length > n) n = l.values.length;
    }
    return n;
  }

  @override
  void initState() {
    super.initState();
    // 600ms 而不是 900：入场擦出是「告诉你这张图从哪开始读」，不是表演。
    // 超过 600ms，每次数据刷新都要等它演完（§6.26）。
    _draw = AnimationController(
      vsync: this,
      duration: const Duration(milliseconds: 600),
    )..forward();
    _bead = AnimationController(
      vsync: this,
      duration: const Duration(milliseconds: _kHeroBeadPeriodMs),
    );
    _selectFade = AnimationController(
      vsync: this,
      duration: const Duration(milliseconds: 180),
      value: 0,
    );
    _syncBead();
  }

  /// 跑珠只在「已画完 + 没在扫描 + 没开减弱动效」这三条同时成立时跑。
  /// 手指按在图上时它停住让位 —— 扫描要看的是那一期的五个数，不是一颗跑动
  /// 的点；两个动的东西同时在图上会互相抢。
  void _syncBead() {
    final wantRun =
        _kHeroBeadEnabled && !_reduceMotion && _selectedIndex == null;
    if (wantRun) {
      if (!_bead.isAnimating) _bead.repeat();
    } else if (_bead.isAnimating) {
      _bead.stop();
    }
  }

  @override
  void didChangeDependencies() {
    super.didChangeDependencies();
    // 系统开了「减弱动效」就直接渲染终态 —— 不是把时长调短，是根本不播（§6.30）。
    final reduce = MediaQuery.maybeDisableAnimationsOf(context) ?? false;
    if (reduce == _reduceMotion) return;
    _reduceMotion = reduce;
    if (reduce) {
      _draw
        ..stop()
        ..value = 1.0;
    }
    _syncBead();
  }

  @override
  void didUpdateWidget(_LhHeroMultiTrend old) {
    super.didUpdateWidget(old);
    if (_signature(old.lines) != _signature(widget.lines)) {
      _draw.stop();
      if (_reduceMotion) {
        _draw.value = 1.0;
      } else {
        _draw.forward(from: 0);
      }
      if (_selectedIndex != null && _selectedIndex! >= _pointCount) {
        _selectedIndex = null;
        _selectFade.value = 0;
        _syncBead();
      }
    }
  }

  static String _signature(List<_HeroTrendLine> lines) {
    final b = StringBuffer();
    for (final l in lines) {
      b
        ..write(l.key)
        ..write('#')
        ..write(l.values.length)
        ..write('@');
      if (l.values.isNotEmpty) {
        b
          ..write(l.values.first.toStringAsFixed(2))
          ..write('~')
          ..write(l.values.last.toStringAsFixed(2));
      }
      b.write(';');
    }
    return b.toString();
  }

  @override
  void dispose() {
    _draw.dispose();
    _bead.dispose();
    _selectFade.dispose();
    super.dispose();
  }

  int _hitIndex(double localX, double width) {
    final n = _pointCount;
    if (n <= 1 || width <= 0) return 0;
    final band = _HeroMultiTrendPainter.plotX(width);
    final usable = band.x1 - band.x0;
    if (usable <= 0) return 0;
    final step = usable / (n - 1);
    if (step <= 0) return 0;
    return ((localX - band.x0) / step).round().clamp(0, n - 1);
  }

  void _setSelected(int? idx) {
    if (idx == _selectedIndex) return;
    LighthouseFeedback.instance.play(
      LighthouseFeedbackKind.select,
      sound: false,
    );
    setState(() => _selectedIndex = idx);
    if (_reduceMotion) {
      _selectFade.value = idx == null ? 0.0 : 1.0;
    } else if (idx == null) {
      _selectFade.reverse();
    } else {
      _selectFade.forward();
    }
    _syncBead();
  }

  void _onTap(Offset local, double width) {
    if (_pointCount < 2) return;
    final i = _hitIndex(local.dx, width);
    _setSelected(_selectedIndex == i ? null : i);
  }

  void _onDrag(Offset local, double width) {
    if (_pointCount < 2) return;
    _setSelected(_hitIndex(local.dx, width));
  }

  void _openFull() {
    if (widget.lines.isEmpty) return;
    LighthouseFeedback.instance.play(LighthouseFeedbackKind.navigate);
    Navigator.of(context).push(
      PageRouteBuilder<void>(
        opaque: false,
        barrierColor: Colors.black.withAlpha(28),
        transitionDuration: const Duration(milliseconds: 260),
        reverseTransitionDuration: const Duration(milliseconds: 200),
        pageBuilder: (_, __, ___) => _LhRidgeFullPage(
          lines: widget.lines,
          labels: widget.labels,
          partialLast: widget.partialLast,
          title: widget.title,
          subtitle: widget.subtitle,
        ),
        transitionsBuilder: (_, anim, __, child) {
          // 从小图「长大」到全屏：缩放起点 0.94 而不是 0，让它读起来是同一张
          // 图放大，不是另开了一个页面。
          final t = Curves.easeOutCubic.transform(anim.value);
          return Opacity(
            opacity: t,
            child: Transform.scale(scale: 0.94 + 0.06 * t, child: child),
          );
        },
      ),
    );
  }

  @override
  Widget build(BuildContext context) {
    return LayoutBuilder(
      builder: (context, box) {
        if (box.maxWidth.isFinite && box.maxWidth > 0) {
          _lastWidth = box.maxWidth;
        }
        // hero 图卡有 0.7px 描边，Container 的可用高度比外面那个 SizedBox 少
        // 1.4px —— 按 widget.height 写死会 overflow（debug 下的黄黑斜纹）。
        final h = box.maxHeight.isFinite && box.maxHeight > 0
            ? box.maxHeight
            : widget.height;
        final w = _lastWidth;
        return Stack(
          clipBehavior: Clip.none,
          children: [
            Positioned.fill(
              child: GestureDetector(
                behavior: HitTestBehavior.opaque,
                onTapDown: (d) => _onTap(d.localPosition, w),
                // 横向拖动扫描；垂直手势留给外层 Scrollable。
                onHorizontalDragStart: (d) => _onDrag(d.localPosition, w),
                onHorizontalDragUpdate: (d) => _onDrag(d.localPosition, w),
                // 跑珠每帧都在动。没有这层边界，重绘会一路冒泡到整个 hero，
                // 连带 stat rail 和列表一起烧。
                child: RepaintBoundary(
                  child: AnimatedBuilder(
                    animation: Listenable.merge([_draw, _bead, _selectFade]),
                    builder: (_, __) => CustomPaint(
                      size: Size(double.infinity, h),
                      painter: _HeroMultiTrendPainter(
                        lines: widget.lines,
                        labels: widget.labels,
                        partialLast: widget.partialLast,
                        // hairline 要按物理像素对齐，painter 拿不到 context。
                        dpr: MediaQuery.devicePixelRatioOf(context),
                        progress: Curves.easeOutCubic.transform(_draw.value),
                        bead: _bead.value,
                        selectedIndex: _selectedIndex,
                        selectAlpha: Curves.easeOutCubic.transform(
                          _selectFade.value,
                        ),
                      ),
                    ),
                  ),
                ),
              ),
            ),
            // 右下角放大。热区 26×26（§7.31 的 24px 下限），视觉只有 15 ——
            // 图卡满打满算 98pt，按钮再大就压到末条山脊的读数上了。
            Positioned(
              right: -3,
              bottom: -3,
              child: GestureDetector(
                behavior: HitTestBehavior.opaque,
                onTap: _openFull,
                child: SizedBox(
                  width: 26,
                  height: 26,
                  child: Center(
                    child: Container(
                      width: 15,
                      height: 15,
                      decoration: BoxDecoration(
                        // 极淡的紫底而不是纯白：卡本身是 #FFFDFF，纯白按钮
                        // 只剩一圈描边，在手机上根本注意不到有这么个东西。
                        color: DunesColors.resolve(
                          context,
                          _LhPlum.primary,
                          role: DunesColorRole.surface,
                        ).withAlpha(20),
                        borderRadius: BorderRadius.circular(4),
                        border: Border.all(
                          color: DunesColors.resolve(
                            context,
                            _LhPlum.heroEdge,
                            role: DunesColorRole.border,
                          ),
                          width: 0.7,
                        ),
                      ),
                      child: Icon(
                        Icons.open_in_full_rounded,
                        size: 9,
                        color: DunesColors.resolve(
                          context,
                          _LhPlum.primary,
                        ).withAlpha(215),
                      ),
                    ),
                  ),
                ),
              ),
            ),
          ],
        );
      },
    );
  }
}

class _HeroMultiTrendPainter extends CustomPainter {
  const _HeroMultiTrendPainter({
    required this.lines,
    required this.labels,
    this.partialLast = false,
    this.dpr = 1.0,
    this.progress = 1.0,
    this.bead = 0.0,
    this.selectedIndex,
    this.selectAlpha = 0.0,
  });

  final List<_HeroTrendLine> lines;
  final List<String> labels;

  /// 末期未完成 —— 末段改虚线 + 60% 透明 + 空心末点 + 轴末「进行中」。
  final bool partialLast;

  /// devicePixelRatio。hairline 宽度取 1/dpr、坐标对齐到 (n+0.5)/dpr，
  /// 否则 1px 线会跨两个物理像素被平均成 2px 灰带（§8.36）。
  final double dpr;
  final double progress;

  /// 跑珠在主线上的位置，0..1 循环。
  final double bead;
  final int? selectedIndex;
  final double selectAlpha;

  static const double _padH = 6.0;
  static const double _nameW = 34.0;
  static const double _valW = 56.0;
  static const double _axisH = 12.0;
  static const double _topPad = 3.0;
  static const double _paneGap = 6.0;
  static const double _plotInset = 5.0;

  static const Color _hair = Color(0xFFEFEAF7);

  /// 命中区映射：扫描按绘图区的 x 区间算，两侧的名字栏和读数栏不算在内。
  static ({double x0, double x1}) plotX(double w) =>
      (x0: _padH + _nameW, x1: math.max(_padH + _nameW + 1, w - _padH - _valW));

  int get _pointCount {
    var n = 0;
    for (final l in lines) {
      if (l.values.length > n) n = l.values.length;
    }
    return n;
  }

  double get _p01 => progress.clamp(0.0, 1.0);
  double get _idleFade => (1.0 - selectAlpha).clamp(0.0, 1.0);
  double get _endFade => ((_p01 - 0.94) / 0.06).clamp(0.0, 1.0);

  bool _selectionOn(int n) =>
      selectedIndex != null &&
      selectedIndex! >= 0 &&
      selectedIndex! < n &&
      selectAlpha > 0.001;

  double _valueOf(_HeroTrendLine l) {
    final i = selectedIndex;
    if (i != null && i >= 0 && i < l.values.length && selectAlpha > 0.001) {
      return l.values[i];
    }
    return l.lastOrTotal;
  }

  // ── 共用绘制原语 ─────────────────────────────────────────────────────

  static TextStyle _mono(double size, Color color, FontWeight weight) =>
      TextStyle(
        fontFamily: 'monospace',
        // 等宽字体本来就等宽，但 monospace 在部分安卓上会 fallback 到比例字体；
        // tabularFigures 保证无论落到哪个 family，数字位宽都一致 —— 否则扫描时
        // 读数每跳一期就左右抖一下（§4.19）。
        fontFeatures: const <FontFeature>[FontFeature.tabularFigures()],
        fontSize: size,
        color: color,
        fontWeight: weight,
        height: 1.0,
      );

  /// 负号用 U+2212 而不是 ASCII '-'：后者在多数字体里只有半个数字宽，一列数里
  /// 混着正负就对不齐。[signSlot] 为 true 时给非负数补一个等宽空位（U+2007），
  /// 让 −12.3 和 12.3 的小数点落在同一列（§4.19）。
  static String _signed(double v, {bool signSlot = false}) {
    final t = _fmtChartShort(v.abs());
    // \u2212 = 数学减号，与数字等宽；ASCII '-' 只有半个数字宽。
    // \u2007 = figure space，宽度等于一个数字，用来给非负数占住符号位。
    if (v < 0) return '\u2212$t';
    return signSlot ? '\u2007$t' : t;
  }

  /// 这一组线里有没有负数 —— 有才给所有读数留符号位。没有的话每条白占一个
  /// 字符宽，56pt 的读数栏亏不起。
  bool get _needsSignSlot {
    for (final l in lines) {
      for (final v in l.values) {
        if (v < 0) return true;
      }
      if ((l.total ?? 0) < 0) return true;
    }
    return false;
  }

  /// 1 物理像素的 hairline。宽度 1/dpr、中心对齐到 (n + 0.5)/dpr —— 不这么干
  /// 的话逻辑坐标上的 1px 线会跨两个物理像素被平均成一条 2px 灰带（§8.36）。
  void _hairH(Canvas canvas, double y, double x0, double x1, Color c) {
    final w = 1 / dpr;
    final sy = ((y * dpr).floorToDouble() + 0.5) / dpr;
    canvas.drawLine(
      Offset(x0, sy),
      Offset(x1, sy),
      Paint()
        ..color = c
        ..strokeWidth = w,
    );
  }

  /// 末期未完成时，图上有几个点是「完整周期」。末点自己不算。
  int _solidCount(int n) => partialLast && n >= 2 ? n - 1 : n;

  /// [at] 是文字的左上角；align 为 right/center 时以 at.dx 为右缘/中线。
  /// 返回排版后的宽度，给需要串排的地方（轴末「进行中」）用。
  double _text(
    Canvas canvas,
    String s,
    Offset at,
    TextStyle style, {
    TextAlign align = TextAlign.left,
    double maxWidth = double.infinity,
  }) {
    if (s.isEmpty) return 0;
    final tp = TextPainter(
      text: TextSpan(text: s, style: style),
      textDirection: TextDirection.ltr,
      maxLines: 1,
    )..layout(maxWidth: maxWidth);
    var dx = at.dx;
    if (align == TextAlign.right) {
      dx -= tp.width;
    } else if (align == TextAlign.center) {
      dx -= tp.width / 2;
    }
    tp.paint(canvas, Offset(dx, at.dy));
    return tp.width;
  }

  void _dash(
    Canvas canvas,
    Offset a,
    Offset b,
    Paint paint, {
    double on = 3,
    double off = 2.5,
  }) {
    final total = (b - a).distance;
    if (total <= 0) return;
    final dir = (b - a) / total;
    var t = 0.0;
    while (t < total) {
      final e = math.min(t + on, total);
      canvas.drawLine(a + dir * t, a + dir * e, paint);
      t = e + off;
    }
  }

  /// 一条山脊：不透明底 + 极淡色染 + 基线 + 线。
  ///
  /// 这里的填充跟 §2.7 说的「面积编码量」不是一回事。值域不从 0 起，它编不了
  /// 量；它的职责是遮挡 —— 山脊互相叠着，后面那条必须被前面这条挡掉一截，
  /// 否则五条糊成一团（那正是 v15 的病）。所以底色用画布色不透明，色染只给
  /// alpha 16（≈6%），弱到不会被眼睛读成体量。
  ///
  /// [reveal] 是 0..1 的左→右擦出比例，五条同时擦（各擦各的会一条接一条地亮，
  /// 读起来像在排队）。
  /// [fill] / [stroke] 分两趟是为了让主线永远在最上面。主线在阅读顺序里排
  /// 第一条，也就是最靠后的那座山 —— 按景深它会被前面四座挡掉大半，而它恰恰
  /// 是唯一必须完整可读的一条。所以主线在自己的位置只画填充（继续负责遮挡
  /// 后面），线单独补到所有山脊之上。
  void _ridge(
    Canvas canvas,
    List<Offset> pts,
    Color color, {
    required double baseY,
    required double width,
    required double reveal,
    int alpha = 255,
    int tint = 16,
    bool fill = true,
    bool stroke = true,
  }) {
    if (pts.length < 2) return;
    final x0 = pts.first.dx, x1 = pts.last.dx;
    final solidN = _solidCount(pts.length);
    // 只有两个点、且末点还在进行中时，没有任何一段是「完整周期」——
    // 那就整条都走虚线，不要为了有条实线而把半天当成一天画。
    final hasSolid = solidN >= 2;
    final solid = hasSolid ? pts.sublist(0, solidN) : const <Offset>[];
    final sx1 = hasSolid ? solid.last.dx : x0;
    final top = math.min(baseY, pts.map((p) => p.dy).reduce(math.min)) - 2;
    canvas.save();
    canvas.clipRect(
      Rect.fromLTRB(x0 - 4, top - 8, x0 + (x1 - x0) * reveal + 0.5, baseY + 4),
    );
    if (hasSolid && fill) {
      final path = Path();
      // monotone cubic：Catmull-Rom 会在拐点 overshoot 出数据里没有的峰谷，
      // 财务折线上那是数据错误不是风格（§3.10）。
      _addMonotonePath(path, solid);
      final area = Path.from(path)
        ..lineTo(sx1, baseY)
        ..lineTo(x0, baseY)
        ..close();
      // 第一层：画布色，不透明。这一层不是「量」，是遮挡。
      canvas.drawPath(area, Paint()..color = LhColors.paper);
      // 第二层：≈6% 的色染，给山脊一点体积感，弱到读不成体量。
      canvas.drawPath(
        area,
        Paint()
          ..shader = LinearGradient(
            begin: Alignment.topCenter,
            end: Alignment.bottomCenter,
            colors: <Color>[color.withAlpha(tint), color.withAlpha(0)],
          ).createShader(Rect.fromLTRB(x0, top, sx1, baseY)),
      );
    }
    // 基线画在填充之后 —— 画在之前会被自己的不透明底盖掉。
    if (fill) _hairH(canvas, baseY, x0 - 1, x1 + 1, _hair);
    if (hasSolid && stroke) {
      final path = Path();
      _addMonotonePath(path, solid);
      canvas.drawPath(
        path,
        Paint()
          ..color = color.withAlpha(alpha.clamp(0, 255))
          ..strokeWidth = width
          ..style = PaintingStyle.stroke
          // 小尺寸下锐角会长出毛刺，round 两头都要（§3.12）。
          ..strokeCap = StrokeCap.round
          ..strokeJoin = StrokeJoin.round,
      );
    }
    if (stroke && solidN < pts.length) {
      // 未完成的那一段：直线 + 虚线 + 60% 透明。画成直线是因为这一段本来就
      // 没走完，用平滑曲线去猜它的形状等于替数据编故事（§3.15）。
      _dash(
        canvas,
        pts[solidN >= 1 ? solidN - 1 : 0],
        pts.last,
        Paint()
          ..color = color.withAlpha((alpha * 0.6).round().clamp(0, 255))
          ..strokeWidth = width
          ..strokeCap = StrokeCap.round,
        on: 2.6,
        off: 2.4,
      );
    }
    canvas.restore();
  }

  /// 末端点。直径取偶数（§8.37）。
  ///
  /// 未完成的末期画成空心圈：实心 = 这个数定了，空心 = 还在动。虚线之外再给
  /// 一层冗余编码，去掉颜色变灰度也还认得出来（§7.35 / §10.10）。
  void _endDot(Canvas canvas, Offset at, Color color, {required bool hero}) {
    final f = _endFade;
    if (f <= 0.01) return;
    final r = hero ? 3.0 : 2.0;
    final a = (255 * f).round();
    if (partialLast) {
      canvas.drawCircle(at, r, Paint()..color = Colors.white.withAlpha(a));
      canvas.drawCircle(
        at,
        r,
        Paint()
          ..color = color.withAlpha((a * 0.65).round())
          ..style = PaintingStyle.stroke
          ..strokeWidth = hero ? 1.4 : 1.2,
      );
      return;
    }
    canvas.drawCircle(at, r + 1.2, Paint()..color = Colors.white.withAlpha(a));
    canvas.drawCircle(at, r, Paint()..color = color.withAlpha(a));
  }

  /// 沿主线跑的那颗珠子 —— 一颗头 + 一截衰减拖尾。
  ///
  /// 拖尾用 8 颗等距衰减的点而不是渐变描边：Canvas 上沿路径的渐变只能拿包围盒
  /// 近似，曲线一弯就漏色。开关和代价见文件顶部 _kHeroBeadEnabled 的注释。
  void _bead(Canvas canvas, List<Offset> pts, Color color) {
    if (!_kHeroBeadEnabled || _p01 < 1.0 || _idleFade <= 0.05) return;
    final solidN = _solidCount(pts.length);
    if (solidN < 2) return;
    final path = Path();
    _addMonotonePath(path, pts.sublist(0, solidN));
    final metrics = path.computeMetrics().toList(growable: false);
    if (metrics.isEmpty) return;
    final m = metrics.first;
    if (m.length <= 1) return;
    final headD = bead.clamp(0.0, 1.0) * m.length;
    final a0 = _idleFade;
    const tailN = 8;
    const tailLen = 26.0;
    for (var t = tailN; t >= 1; t--) {
      final d = headD - tailLen * t / tailN;
      if (d < 0) continue;
      final tan = m.getTangentForOffset(d);
      if (tan == null) continue;
      final f = 1 - t / (tailN + 1.0);
      canvas.drawCircle(
        tan.position,
        0.7 + f * 1.4,
        Paint()
          ..color = color.withAlpha((a0 * f * f * 160).round().clamp(0, 255)),
      );
    }
    final head = m.getTangentForOffset(headD)?.position;
    if (head == null) return;
    canvas.drawCircle(
      head,
      5.6,
      Paint()..color = color.withAlpha((a0 * 38).round()),
    );
    canvas.drawCircle(
      head,
      3.0,
      Paint()..color = color.withAlpha((a0 * 235).round()),
    );
    canvas.drawCircle(
      head,
      1.2,
      Paint()..color = Colors.white.withAlpha((a0 * 255).round()),
    );
  }

  String _periodLabel(int i, int n) {
    final raw = (i >= 0 && i < labels.length && labels[i].trim().isNotEmpty)
        ? labels[i].trim()
        : (i == n - 1 ? '现' : 'T−${n - 1 - i}');
    return lighthouseHeroCompactPeriodLabel(raw);
  }

  /// 扫描时底部那颗期标 pill —— 数值都在图上常驻，这里只回答「哪一期」。
  void _pill(
    Canvas canvas,
    Size size,
    double cx,
    double top,
    String label,
    double sA,
  ) {
    if (label.isEmpty) return;
    final tp = TextPainter(
      text: TextSpan(
        text: label,
        style: _mono(
          7.5,
          _LhPlum.heroNum.withAlpha((255 * sA).round()),
          FontWeight.w700,
        ),
      ),
      textDirection: TextDirection.ltr,
      maxLines: 1,
    )..layout();
    const padX = 5.0, padY = 2.0;
    final w = tp.width + padX * 2, h = tp.height + padY * 2;
    final x = (cx - w / 2).clamp(0.0, math.max(0.0, size.width - w)).toDouble();
    final rr = RRect.fromRectAndRadius(
      Rect.fromLTWH(x, top, w, h),
      const Radius.circular(5),
    );
    canvas.drawRRect(
      rr,
      Paint()..color = LhColors.paper.withAlpha((255 * sA).round()),
    );
    canvas.drawRRect(
      rr,
      Paint()
        ..color = _LhPlum.heroEdge.withAlpha((255 * sA).round())
        ..strokeWidth = 0.6
        ..style = PaintingStyle.stroke,
    );
    tp.paint(canvas, Offset(x + padX, top + padY));
  }

  /// 轴末标签。末期未完成时在它左边挂一个「进行中」—— 虚线告诉眼睛「这段不
  /// 一样」，这三个字告诉大脑「不一样在哪」（§3.15）。
  void _axisEndLabel(
    Canvas canvas,
    double xRight,
    double y,
    String label,
    double fade,
  ) {
    final a = (255 * fade).round().clamp(0, 255);
    final w = _text(
      canvas,
      label,
      Offset(xRight, y),
      _mono(8, LhColors.ink2.withAlpha(a), FontWeight.w700),
      align: TextAlign.right,
    );
    if (!partialLast) return;
    // +0.5 是把 7pt 和 8pt 两段文字的视觉中线拉平，不是随手加的空隙。
    _text(
      canvas,
      '进行中',
      Offset(xRight - w - 4, y + 0.5),
      _mono(7, LhColors.mute2.withAlpha((a * 0.85).round()), FontWeight.w600),
      align: TextAlign.right,
    );
  }

  // ── 双格叠线（规模一格、损益一格）────────────────────────────────

  @override
  void paint(Canvas canvas, Size size) {
    final n = _pointCount;
    if (lines.isEmpty || n < 2 || progress <= 0.0 || size.width <= 8) return;
    final cw = size.width, ch = size.height;
    final band = plotX(cw);
    final x0 = band.x0, x1 = band.x1;
    if (x1 - x0 < 20) return;
    final panes = lighthouseHeroTrendPaneIndexes([
      for (final l in lines) l.key,
    ]);
    if (panes.isEmpty) return;

    final availableH = ch - _topPad - _axisH;
    if (availableH < 28) return;
    var flexSum = 0;
    for (var p = 0; p < panes.length; p++) {
      flexSum += lighthouseHeroTrendPaneFlex(panes[p].length);
    }
    final gapTotal = panes.length > 1 ? _paneGap * (panes.length - 1) : 0.0;
    final unit = (availableH - gapTotal) / flexSum;
    final paneRects = <Rect>[];
    var y = _topPad;
    for (var p = 0; p < panes.length; p++) {
      final h = unit * lighthouseHeroTrendPaneFlex(panes[p].length);
      paneRects.add(Rect.fromLTWH(0, y, cw, h));
      y += h + _paneGap;
    }

    double xOf(int k) => x0 + k * (x1 - x0) / (n - 1);

    final sel = _selectionOn(n);
    final i = selectedIndex ?? 0;
    final sA = selectAlpha.clamp(0.0, 1.0);
    final signSlot = _needsSignSlot;

    final allPts = List<List<Offset>>.generate(
      lines.length,
      (_) => const <Offset>[],
    );
    List<Offset>? heroPts;
    var heroColor = lines.first.color;

    for (var p = 0; p < panes.length; p++) {
      final indexes = panes[p];
      final paneLines = [for (final j in indexes) lines[j]];
      final rect = paneRects[p];
      final r = _heroPaneRange(paneLines);
      final plotTop = rect.top + _plotInset;
      final plotBot = rect.bottom - _plotInset;
      final plotH = math.max(8.0, plotBot - plotTop);
      double yOf(double v) => plotBot - (v - r.min) / r.span * plotH;

      _hairH(canvas, plotBot, x0, x1, _hair);
      if (p > 0) {
        _hairH(
          canvas,
          rect.top - _paneGap / 2,
          x0,
          x1,
          const Color(0xFFE6E0F0),
        );
      }

      var heroInPane = -1;
      for (var k = 0; k < indexes.length; k++) {
        final j = indexes[k];
        final l = lines[j];
        final pts = <Offset>[
          for (var t = 0; t < l.values.length; t++)
            Offset(xOf(t), yOf(l.values[t])),
        ];
        allPts[j] = pts;
        if (l.hero) {
          heroPts = pts;
          heroColor = l.color;
          heroInPane = j;
        }
      }

      for (var k = 0; k < indexes.length; k++) {
        final j = indexes[k];
        if (j == heroInPane) continue;
        final l = lines[j];
        _ridge(
          canvas,
          allPts[j],
          l.color,
          baseY: plotBot,
          width: l.sharedRange ? 1.35 : 1.5,
          alpha: l.sharedRange ? 165 : 220,
          reveal: _p01,
          fill: false,
        );
        if (allPts[j].isNotEmpty) {
          _endDot(canvas, allPts[j].last, l.color, hero: false);
        }
      }
      if (heroInPane >= 0) {
        _ridge(
          canvas,
          allPts[heroInPane],
          heroColor,
          baseY: plotBot,
          width: 2.15,
          reveal: _p01,
          fill: false,
        );
      }

      final rowH = math.min(14.0, rect.height / math.max(1, paneLines.length));
      var labelY = rect.center.dy - (paneLines.length * rowH) / 2 + 1.5;
      for (var k = 0; k < paneLines.length; k++) {
        final l = paneLines[k];
        canvas.drawRRect(
          RRect.fromRectAndRadius(
            Rect.fromLTWH(_padH, labelY + 3.2, l.hero ? 9.0 : 6.0, 2.4),
            const Radius.circular(1.2),
          ),
          Paint()..color = l.color.withAlpha(l.hero ? 255 : 190),
        );
        _text(
          canvas,
          l.name,
          Offset(_padH + (l.hero ? 12 : 9), labelY),
          _mono(9, LhColors.ink2, FontWeight.w600),
          maxWidth: _nameW - 12,
        );
        _text(
          canvas,
          _signed(_valueOf(l), signSlot: signSlot),
          Offset(cw - _padH, labelY - 0.6),
          _mono(10.5, l.color, l.hero ? FontWeight.w800 : FontWeight.w700),
          align: TextAlign.right,
          maxWidth: _valW,
        );
        labelY += rowH;
      }
    }

    if (heroPts != null && heroPts.isNotEmpty) {
      _endDot(canvas, heroPts.last, heroColor, hero: true);
      _bead(canvas, heroPts, heroColor);
    }

    if (sel) {
      final x = xOf(i);
      canvas.drawLine(
        Offset(x, paneRects.first.top + 1),
        Offset(x, paneRects.last.bottom - 1),
        Paint()
          ..color = _LhPlum.deep.withAlpha((88 * sA).round())
          ..strokeWidth = 1.0,
      );
      for (var j = 0; j < lines.length; j++) {
        final pts = allPts[j];
        if (i >= pts.length) continue;
        final p = pts[i];
        canvas.drawCircle(
          p,
          3.0,
          Paint()..color = Colors.white.withAlpha((255 * sA).round()),
        );
        canvas.drawCircle(
          p,
          1.9,
          Paint()..color = lines[j].color.withAlpha((255 * sA).round()),
        );
      }
    }

    final scanX = sel ? xOf(i) : double.nan;
    if (_p01 >= 1.0) {
      final axFade = (0.35 + _idleFade * 0.65).clamp(0.0, 1.0);
      if (!sel || (scanX - x0).abs() > 22) {
        _text(
          canvas,
          _periodLabel(0, n),
          Offset(x0, ch - 9),
          _mono(
            8,
            LhColors.mute2.withAlpha((255 * axFade).round()),
            FontWeight.w500,
          ),
        );
      }
      if (!sel || (scanX - x1).abs() > 34) {
        _axisEndLabel(canvas, x1, ch - 9, _periodLabel(n - 1, n), axFade);
      }
    }
    if (sel) {
      _pill(canvas, size, scanX, ch - 13, _periodLabel(i, n), sA);
    }
  }

  @override
  bool shouldRepaint(_HeroMultiTrendPainter old) =>
      !identical(old.lines, lines) ||
      !identical(old.labels, labels) ||
      old.partialLast != partialLast ||
      old.dpr != dpr ||
      old.progress != progress ||
      old.bead != bead ||
      old.selectedIndex != selectedIndex ||
      old.selectAlpha != selectAlpha;
}

// ═════════════════════════════════════════════════════════════════════════════
// 山脊放大页 (v18)
//
//   小图里被砍掉的三样东西在这里补回来，因为这里有地方：
//     · 每条山脊自己的 Y 刻度（2–3 个 nice number）和对应的横网格；
//     · 每一期的日期都标出来，不只是首末；
//     · 读数字号从 10.5 提到 18，扫描时不用眯眼。
//   刻意没做的：五条共用一根 Y 轴。核销 1152 万和利润 1.18 万差了 1000 倍，
//   共轴之后四条会压成贴底的直线 —— 放大只是给了更多像素，没有改变量级差。
// ═════════════════════════════════════════════════════════════════════════════

class _LhRidgeFullPage extends StatefulWidget {
  const _LhRidgeFullPage({
    required this.lines,
    required this.labels,
    required this.partialLast,
    required this.title,
    required this.subtitle,
  });

  final List<_HeroTrendLine> lines;
  final List<String> labels;
  final bool partialLast;
  final String title;
  final String subtitle;

  @override
  State<_LhRidgeFullPage> createState() => _LhRidgeFullPageState();
}

class _LhRidgeFullPageState extends State<_LhRidgeFullPage>
    with TickerProviderStateMixin {
  late final AnimationController _draw;
  late final AnimationController _bead;
  late final AnimationController _selectFade;

  int? _selectedIndex;
  double _lastWidth = 0;
  bool _reduceMotion = false;

  int get _pointCount {
    var n = 0;
    for (final l in widget.lines) {
      if (l.values.length > n) n = l.values.length;
    }
    return n;
  }

  @override
  void initState() {
    super.initState();
    _draw = AnimationController(
      vsync: this,
      duration: const Duration(milliseconds: 600),
    )..forward();
    _bead = AnimationController(
      vsync: this,
      duration: const Duration(milliseconds: _kHeroBeadPeriodMs),
    );
    _selectFade = AnimationController(
      vsync: this,
      duration: const Duration(milliseconds: 160),
      value: 0,
    );
    _syncBead();
  }

  void _syncBead() {
    final wantRun =
        _kHeroBeadEnabled && !_reduceMotion && _selectedIndex == null;
    if (wantRun) {
      if (!_bead.isAnimating) _bead.repeat();
    } else if (_bead.isAnimating) {
      _bead.stop();
    }
  }

  @override
  void didChangeDependencies() {
    super.didChangeDependencies();
    final reduce = MediaQuery.maybeDisableAnimationsOf(context) ?? false;
    if (reduce == _reduceMotion) return;
    _reduceMotion = reduce;
    if (reduce) {
      _draw
        ..stop()
        ..value = 1.0;
    }
    _syncBead();
  }

  @override
  void dispose() {
    _draw.dispose();
    _bead.dispose();
    _selectFade.dispose();
    super.dispose();
  }

  int _hitIndex(double localX, double width) {
    final n = _pointCount;
    if (n <= 1 || width <= 0) return 0;
    final band = _LhRidgeFullPainter.plotX(width);
    final usable = band.x1 - band.x0;
    if (usable <= 0) return 0;
    return ((localX - band.x0) / (usable / (n - 1))).round().clamp(0, n - 1);
  }

  void _setSelected(int? idx) {
    if (idx == _selectedIndex) return;
    LighthouseFeedback.instance.play(
      LighthouseFeedbackKind.select,
      sound: false,
    );
    setState(() => _selectedIndex = idx);
    if (_reduceMotion) {
      _selectFade.value = idx == null ? 0.0 : 1.0;
    } else if (idx == null) {
      _selectFade.reverse();
    } else {
      _selectFade.forward();
    }
    _syncBead();
  }

  String _periodLabel(int i) {
    final n = _pointCount;
    final raw =
        (i >= 0 &&
            i < widget.labels.length &&
            widget.labels[i].trim().isNotEmpty)
        ? widget.labels[i].trim()
        : (i == n - 1 ? '现' : 'T−${n - 1 - i}');
    return lighthouseHeroCompactPeriodLabel(raw);
  }

  @override
  Widget build(BuildContext context) {
    final n = _pointCount;
    final count = widget.lines.length;
    final scanned = _selectedIndex;
    return Scaffold(
      backgroundColor: Colors.transparent,
      body: Container(
        decoration: BoxDecoration(
          // 纵向渐变而不是纯色：全屏一整片 #FFFDFF 会显得空，往下压一点雾紫
          // 让山脊的下缘有个落脚的地。两端色差只有 8 点亮度，不会抢线。
          gradient: LinearGradient(
            begin: Alignment.topCenter,
            end: Alignment.bottomCenter,
            colors: <Color>[
              DunesColors.resolve(
                context,
                Color(0xFFFFFDFF),
                role: DunesColorRole.surface,
              ),
              DunesColors.resolve(
                context,
                Color(0xFFF4EFFA),
                role: DunesColorRole.surface,
              ),
            ],
          ),
        ),
        child: SafeArea(
          child: Column(
            crossAxisAlignment: CrossAxisAlignment.stretch,
            children: [
              _buildHeader(scanned),
              Expanded(
                child: LayoutBuilder(
                  builder: (context, box) {
                    if (box.maxWidth.isFinite && box.maxWidth > 0) {
                      _lastWidth = box.maxWidth;
                    }
                    final w = _lastWidth;
                    // 一条山脊低于 88pt 就放不下刻度了，那时候宁可让页面滚动，
                    // 也不要把刻度挤掉 —— 刻度是这一页存在的理由。
                    final needH = count * 96.0 + _LhRidgeFullPainter.axisH + 16;
                    final h = math.max(box.maxHeight, needH);
                    return SingleChildScrollView(
                      physics: h > box.maxHeight
                          ? const ClampingScrollPhysics()
                          : const NeverScrollableScrollPhysics(),
                      child: GestureDetector(
                        behavior: HitTestBehavior.opaque,
                        onTapDown: (d) {
                          if (n < 2) return;
                          final i = _hitIndex(d.localPosition.dx, w);
                          _setSelected(_selectedIndex == i ? null : i);
                        },
                        onHorizontalDragStart: (d) {
                          if (n < 2) return;
                          _setSelected(_hitIndex(d.localPosition.dx, w));
                        },
                        onHorizontalDragUpdate: (d) {
                          if (n < 2) return;
                          _setSelected(_hitIndex(d.localPosition.dx, w));
                        },
                        child: RepaintBoundary(
                          child: AnimatedBuilder(
                            animation: Listenable.merge([
                              _draw,
                              _bead,
                              _selectFade,
                            ]),
                            builder: (_, __) => CustomPaint(
                              size: Size(w, h),
                              painter: _LhRidgeFullPainter(
                                lines: widget.lines,
                                labels: widget.labels,
                                partialLast: widget.partialLast,
                                dpr: MediaQuery.devicePixelRatioOf(context),
                                progress: Curves.easeOutCubic.transform(
                                  _draw.value,
                                ),
                                bead: _bead.value,
                                selectedIndex: _selectedIndex,
                                selectAlpha: Curves.easeOutCubic.transform(
                                  _selectFade.value,
                                ),
                              ),
                            ),
                          ),
                        ),
                      ),
                    );
                  },
                ),
              ),
            ],
          ),
        ),
      ),
    );
  }

  Widget _buildHeader(int? scanned) {
    final n = _pointCount;
    // 抬头右边这块跟着扫描走：没扫时显示区间，扫到哪一期就显示哪一期。
    // 「现在看的是哪一段时间」必须一眼可见，否则读数没有归属。
    final right = scanned != null && scanned < n
        ? _periodLabel(scanned)
        : widget.subtitle;
    return Container(
      padding: const EdgeInsets.fromLTRB(14, 10, 8, 12),
      decoration: BoxDecoration(
        border: Border(
          bottom: BorderSide(
            color: DunesColors.resolve(
              context,
              Color(0xFFE4DCF4),
              role: DunesColorRole.border,
            ),
            width: 1,
          ),
        ),
      ),
      child: Row(
        children: [
          Container(
            width: 3,
            height: 26,
            decoration: BoxDecoration(
              color: DunesColors.resolve(
                context,
                _LhPlum.primary,
                role: DunesColorRole.surface,
              ),
              borderRadius: BorderRadius.circular(1.5),
            ),
          ),
          const SizedBox(width: 9),
          Expanded(
            child: Column(
              crossAxisAlignment: CrossAxisAlignment.start,
              mainAxisSize: MainAxisSize.min,
              children: [
                LhScrollText(
                  widget.title,
                  maxLines: 1,
                  overflow: TextOverflow.ellipsis,
                  style: LhTypography.sans(
                    size: 15,
                    color: DunesColors.resolve(context, LhColors.ink),
                    weight: FontWeight.w700,
                    height: 1.1,
                    context: context,
                  ),
                ),
                const SizedBox(height: 3),
                Row(
                  mainAxisSize: MainAxisSize.min,
                  children: [
                    Text(
                      right,
                      style: LhTypography.mono(
                        size: 10.5,
                        color: DunesColors.resolve(context, LhColors.mute),
                        weight: FontWeight.w600,
                        height: 1.0,
                        context: context,
                      ),
                    ),
                    if (widget.partialLast) ...[
                      const SizedBox(width: 6),
                      Container(
                        padding: const EdgeInsets.symmetric(
                          horizontal: 5,
                          vertical: 2,
                        ),
                        decoration: BoxDecoration(
                          color: DunesColors.resolve(
                            context,
                            LhColors.paper,
                            role: DunesColorRole.surface,
                          ),
                          borderRadius: BorderRadius.circular(4),
                          border: Border.all(
                            color: DunesColors.resolve(
                              context,
                              _LhPlum.heroEdge,
                              role: DunesColorRole.border,
                            ),
                            width: 0.7,
                          ),
                        ),
                        child: Text(
                          '末期进行中',
                          style: LhTypography.mono(
                            size: 8.5,
                            color: DunesColors.resolve(context, LhColors.mute2),
                            weight: FontWeight.w700,
                            height: 1.0,
                            context: context,
                          ),
                        ),
                      ),
                    ],
                  ],
                ),
              ],
            ),
          ),
          GestureDetector(
            behavior: HitTestBehavior.opaque,
            onTap: () => Navigator.of(context).maybePop(),
            child: SizedBox(
              width: 44,
              height: 44,
              child: Icon(
                Icons.close_rounded,
                size: 20,
                color: DunesColors.resolve(context, LhColors.mute),
              ),
            ),
          ),
        ],
      ),
    );
  }
}

class _LhRidgeFullPainter extends CustomPainter {
  const _LhRidgeFullPainter({
    required this.lines,
    required this.labels,
    this.partialLast = false,
    this.dpr = 1.0,
    this.progress = 1.0,
    this.bead = 0.0,
    this.selectedIndex,
    this.selectAlpha = 0.0,
  });

  final List<_HeroTrendLine> lines;
  final List<String> labels;
  final bool partialLast;
  final double dpr;
  final double progress;
  final double bead;
  final int? selectedIndex;
  final double selectAlpha;

  /// 左边留给刻度读数，右边留给「名字 + 大读数」。两块都在绘图区外面 ——
  /// 山脊互相重叠，压在图上的字一定会被前面那条山盖掉一半。
  static const double tickW = 48.0;
  static const double valW = 98.0;
  static const double padH = 12.0;
  static const double axisH = 26.0;
  static const double topPad = 10.0;

  /// 放大页的 overlap 比小图小得多：这里每条要留出自己的刻度带，叠太狠刻度
  /// 会被前面那条山盖住。1.15 是「还看得出是一片山脊、但刻度全在」的那一档。
  static const double overlap = 1.15;

  static const Color _hair = Color(0xFFEFEAF7);
  static const Color _grid = Color(0xFFF1ECF8);

  static ({double x0, double x1}) plotX(double w) =>
      (x0: padH + tickW, x1: math.max(padH + tickW + 1, w - padH - valW));

  int get _pointCount {
    var n = 0;
    for (final l in lines) {
      if (l.values.length > n) n = l.values.length;
    }
    return n;
  }

  double get _p01 => progress.clamp(0.0, 1.0);
  double get _idleFade => (1.0 - selectAlpha).clamp(0.0, 1.0);
  int _solidCount(int n) => partialLast && n >= 2 ? n - 1 : n;

  double _valueOf(_HeroTrendLine l) {
    final i = selectedIndex;
    if (i != null && i >= 0 && i < l.values.length && selectAlpha > 0.001) {
      return l.values[i];
    }
    return l.lastOrTotal;
  }

  static TextStyle _mono(double size, Color color, FontWeight weight) =>
      TextStyle(
        fontFamily: 'monospace',
        fontFeatures: const <FontFeature>[FontFeature.tabularFigures()],
        fontSize: size,
        color: color,
        fontWeight: weight,
        height: 1.0,
      );

  double _text(
    Canvas canvas,
    String s,
    Offset at,
    TextStyle style, {
    TextAlign align = TextAlign.left,
    double maxWidth = double.infinity,
  }) {
    if (s.isEmpty) return 0;
    final tp = TextPainter(
      text: TextSpan(text: s, style: style),
      textDirection: TextDirection.ltr,
      maxLines: 1,
    )..layout(maxWidth: maxWidth);
    var dx = at.dx;
    if (align == TextAlign.right) {
      dx -= tp.width;
    } else if (align == TextAlign.center) {
      dx -= tp.width / 2;
    }
    tp.paint(canvas, Offset(dx, at.dy));
    return tp.width;
  }

  void _hairH(Canvas canvas, double y, double x0, double x1, Color c) {
    final w = 1 / dpr;
    final sy = ((y * dpr).floorToDouble() + 0.5) / dpr;
    canvas.drawLine(
      Offset(x0, sy),
      Offset(x1, sy),
      Paint()
        ..color = c
        ..strokeWidth = w,
    );
  }

  void _dash(Canvas canvas, Offset a, Offset b, Paint paint) {
    final total = (b - a).distance;
    if (total <= 0) return;
    final dir = (b - a) / total;
    var t = 0.0;
    while (t < total) {
      final e = math.min(t + 4.0, total);
      canvas.drawLine(a + dir * t, a + dir * e, paint);
      t = e + 3.5;
    }
  }

  String _periodLabel(int i, int n) {
    final raw = (i >= 0 && i < labels.length && labels[i].trim().isNotEmpty)
        ? labels[i].trim()
        : (i == n - 1 ? '现' : 'T−${n - 1 - i}');
    return lighthouseHeroCompactPeriodLabel(raw);
  }

  @override
  void paint(Canvas canvas, Size size) {
    final n = _pointCount;
    if (lines.isEmpty || n < 2 || _p01 <= 0 || size.width <= 80) return;
    final cw = size.width, ch = size.height;
    final count = lines.length;
    final band = plotX(cw);
    final x0 = band.x0, x1 = band.x1;
    if (x1 - x0 < 60) return;
    final g = _RidgeGeom.fit(
      top: topPad,
      height: ch - topPad - axisH,
      count: count,
      overlap: overlap,
    );
    if (g.amp < 24) return;
    double xOf(int k) => x0 + k * (x1 - x0) / (n - 1);

    final sel =
        selectedIndex != null &&
        selectedIndex! >= 0 &&
        selectedIndex! < n &&
        selectAlpha > 0.001;
    final si = selectedIndex ?? 0;
    final sA = selectAlpha.clamp(0.0, 1.0);

    final allPts = <List<Offset>>[];
    List<Offset>? heroPts;
    var heroColor = lines.first.color;
    var heroBaseY = 0.0;

    for (var j = 0; j < count; j++) {
      final l = lines[j];
      final r = _heroNiceRange(l.values, headSteps: 0.3, footSteps: 0.15);
      final baseY = g.baseY(j);
      double yOf(double v) => baseY - (v - r.min) / r.span * g.amp;

      final pts = <Offset>[
        for (var k = 0; k < l.values.length; k++)
          Offset(xOf(k), yOf(l.values[k])),
      ];
      allPts.add(pts);
      if (l.hero) {
        heroPts = pts;
        heroColor = l.color;
        heroBaseY = baseY;
      }
      final alpha = l.hero
          ? 255
          : l.sharedRange
          ? 180
          : 225;
      final width = l.hero ? 2.6 : 1.8;

      // 每条山脊分三步画，顺序是有原因的：
      //   1. 填充 —— 不透明底，负责把它后面（上面）那座山挡掉一截；
      //   2. 刻度带 —— 必须在填充之后，画在之前会被自己那座山的不透明底盖掉
      //      一半，而刻度正是这一页存在的理由；
      //   3. 线 —— 最后压上去。
      _ridge(
        canvas,
        pts,
        l.color,
        baseY: baseY,
        width: width,
        alpha: alpha,
        reveal: _p01,
        stroke: false,
      );

      // 步长按「这一条自己的跨度 / 2」求 nice number，最多 3 条横网格。
      // 3 条以上在 150pt 的带子里就成了斑马线，而且没人会去数第 4 条。
      final step = _niceStep(r.max - r.min, target: 2);
      var drawn = 0;
      var v = (r.min / step).ceilToDouble() * step;
      // guard：step 理论上恒 > 0，但值域算错时这个循环会转不完，
      // 宁可少画刻度也不能让一帧卡死。
      for (
        var guard = 0;
        guard < 16 && v <= r.max + 1e-9 && drawn < 3;
        guard++
      ) {
        final tick = v;
        v += step;
        final gy = yOf(tick);
        if (gy < baseY - g.amp - 0.5 || gy > baseY + 0.5) continue;
        // 网格是实线。虚线在这张图里只有一个意思：未完成（§5.22）。
        _hairH(canvas, gy, x0, x1, _grid);
        _text(
          canvas,
          _fmtChartShort(tick),
          Offset(x0 - 7, gy - 4),
          _mono(9, LhColors.mute2, FontWeight.w500),
          align: TextAlign.right,
          maxWidth: tickW,
        );
        drawn++;
      }
      _hairH(canvas, baseY, x0, x1, _hair);

      if (!l.hero) {
        _ridge(
          canvas,
          pts,
          l.color,
          baseY: baseY,
          width: width,
          alpha: alpha,
          reveal: _p01,
          fill: false,
        );
        if (pts.isNotEmpty) {
          _dots(canvas, pts, l.color, hero: false);
          _endDot(canvas, pts.last, l.color, hero: false);
        }
      }

      // ── 右栏：名字 + 大读数 ──
      canvas.drawRRect(
        RRect.fromRectAndRadius(
          Rect.fromLTWH(x1 + 10, baseY - 41, l.hero ? 14.0 : 10.0, 3.0),
          const Radius.circular(1.5),
        ),
        Paint()..color = l.color.withAlpha(l.hero ? 255 : 190),
      );
      _text(
        canvas,
        l.name,
        Offset(x1 + 10 + (l.hero ? 19 : 15), baseY - 45),
        _mono(11, LhColors.ink2, FontWeight.w600),
        maxWidth: valW - 30,
      );
      _text(
        canvas,
        _signed(_valueOf(l)),
        Offset(cw - padH, baseY - 28),
        _mono(18, l.color, l.hero ? FontWeight.w800 : FontWeight.w700),
        align: TextAlign.right,
        maxWidth: valW,
      );
      // 扫描时补一行环比，闲置时不占地方 —— 放大页最值钱的信息不是「是多少」
      // （右边那个 18pt 已经回答了），是「跟上一期比动了多少」。
      if (sel && si > 0 && si < l.values.length) {
        final prev = l.values[si - 1];
        final cur = l.values[si];
        if (prev.abs() > 1e-9) {
          final pct = (cur - prev) / prev.abs() * 100;
          final up = pct >= 0;
          _text(
            canvas,
            '${up ? '+' : '−'}${pct.abs().toStringAsFixed(1)}%',
            Offset(cw - padH, baseY - 9),
            _mono(
              10,
              (up ? LhColors.neg : LhColors.pos).withAlpha((255 * sA).round()),
              FontWeight.w700,
            ),
            align: TextAlign.right,
            maxWidth: valW,
          );
        }
      }
    }

    // 主线补在最上层：线 + 数据点 + 末端点 + 跑珠。
    if (heroPts != null && heroPts.isNotEmpty) {
      _ridge(
        canvas,
        heroPts,
        heroColor,
        baseY: heroBaseY,
        width: 2.6,
        reveal: _p01,
        fill: false,
      );
      _dots(canvas, heroPts, heroColor, hero: true);
      _endDot(canvas, heroPts.last, heroColor, hero: true);
      _bead(canvas, heroPts, heroColor);
    }

    // ── 扫描：一条竖线贯穿五条 + 每条一个点 ──
    if (sel) {
      final x = xOf(si);
      canvas.drawLine(
        Offset(x, topPad),
        Offset(x, g.baseY(count - 1)),
        Paint()
          ..color = _LhPlum.deep.withAlpha((90 * sA).round())
          ..strokeWidth = 1.0,
      );
      for (var j = 0; j < count; j++) {
        final pts = allPts[j];
        if (si >= pts.length) continue;
        canvas.drawCircle(
          pts[si],
          4.4,
          Paint()..color = Colors.white.withAlpha((255 * sA).round()),
        );
        canvas.drawCircle(
          pts[si],
          2.8,
          Paint()..color = lines[j].color.withAlpha((255 * sA).round()),
        );
      }
    }

    // ── X 轴：放大了就把每一期都标出来 ──
    final axisY = ch - axisH + 7;
    _hairH(canvas, ch - axisH, x0, x1, _hair);
    final solidN = _solidCount(n);
    for (var k = 0; k < n; k++) {
      final isSel = sel && k == si;
      final isPartial = k >= solidN;
      final base = isSel
          ? _LhPlum.heroNum
          : (k == n - 1 ? LhColors.ink2 : LhColors.mute2);
      _text(
        canvas,
        _periodLabel(k, n),
        Offset(xOf(k), axisY),
        _mono(
          isSel ? 10 : 9,
          base.withAlpha(isPartial && !isSel ? 150 : 255),
          isSel || k == n - 1 ? FontWeight.w700 : FontWeight.w500,
        ),
        align: TextAlign.center,
      );
    }
    if (partialLast) {
      _text(
        canvas,
        '进行中',
        Offset(xOf(n - 1), axisY + 12),
        _mono(8, LhColors.mute2, FontWeight.w600),
        align: TextAlign.center,
      );
    }
  }

  // ── 与小图共用同一套画法，只是尺寸放大 ────────────────────────────────

  static String _signed(double v) {
    final t = _fmtChartShort(v.abs());
    return v < 0 ? '\u2212$t' : t;
  }

  /// [fill] / [stroke] 分两趟的理由同小图：主线是最靠后的那座山，它的线要补
  /// 到所有山脊之上才不会被前面的挡掉。
  void _ridge(
    Canvas canvas,
    List<Offset> pts,
    Color color, {
    required double baseY,
    required double width,
    required double reveal,
    int alpha = 255,
    bool fill = true,
    bool stroke = true,
  }) {
    if (pts.length < 2) return;
    final x0 = pts.first.dx, x1 = pts.last.dx;
    final solidN = _solidCount(pts.length);
    final hasSolid = solidN >= 2;
    final solid = hasSolid ? pts.sublist(0, solidN) : const <Offset>[];
    final sx1 = hasSolid ? solid.last.dx : x0;
    final top = math.min(baseY, pts.map((p) => p.dy).reduce(math.min)) - 2;
    canvas.save();
    canvas.clipRect(
      Rect.fromLTRB(x0 - 6, top - 12, x0 + (x1 - x0) * reveal + 0.5, baseY + 4),
    );
    if (hasSolid && fill) {
      final path = Path();
      _addMonotonePath(path, solid);
      final area = Path.from(path)
        ..lineTo(sx1, baseY)
        ..lineTo(x0, baseY)
        ..close();
      // 不透明底负责遮挡后面那条山；色染 alpha 20（≈8%）是装饰上限 ——
      // 值域不从 0 起，这块面积编码不了量，只能弱到读不成量（§2.7）。
      canvas.drawPath(area, Paint()..color = LhColors.paper);
      canvas.drawPath(
        area,
        Paint()
          ..shader = LinearGradient(
            begin: Alignment.topCenter,
            end: Alignment.bottomCenter,
            colors: <Color>[color.withAlpha(20), color.withAlpha(0)],
          ).createShader(Rect.fromLTRB(x0, top, sx1, baseY)),
      );
    }
    if (hasSolid && stroke) {
      final path = Path();
      _addMonotonePath(path, solid);
      canvas.drawPath(
        path,
        Paint()
          ..color = color.withAlpha(alpha.clamp(0, 255))
          ..strokeWidth = width
          ..style = PaintingStyle.stroke
          ..strokeCap = StrokeCap.round
          ..strokeJoin = StrokeJoin.round,
      );
    }
    if (stroke && solidN < pts.length) {
      _dash(
        canvas,
        pts[solidN >= 1 ? solidN - 1 : 0],
        pts.last,
        Paint()
          ..color = color.withAlpha((alpha * 0.6).round().clamp(0, 255))
          ..strokeWidth = width
          ..strokeCap = StrokeCap.round,
      );
    }
    canvas.restore();
  }

  /// n ≤ 10 才画数据点（§3.13）。放大页一条山脊 150pt 高、点距 35pt，
  /// 画出来「哪一天」就有了实体，不用去猜曲线上哪个位置是一期。
  void _dots(
    Canvas canvas,
    List<Offset> pts,
    Color color, {
    required bool hero,
  }) {
    final n = pts.length;
    if (n > 10 || n < 2 || _p01 < 1.0) return;
    final solidN = _solidCount(n);
    final upto = partialLast ? solidN : solidN - 1;
    var hi = 0, lo = 0;
    for (var k = 1; k < solidN; k++) {
      if (pts[k].dy < pts[hi].dy) hi = k;
      if (pts[k].dy > pts[lo].dy) lo = k;
    }
    for (var k = 0; k < upto; k++) {
      final ext = k == hi || k == lo;
      canvas.drawCircle(pts[k], ext ? 4.0 : 3.0, Paint()..color = Colors.white);
      canvas.drawCircle(
        pts[k],
        hero ? 3.0 : 2.6,
        Paint()
          ..color = color.withAlpha(ext ? 255 : 185)
          ..style = PaintingStyle.stroke
          ..strokeWidth = 1.4,
      );
    }
  }

  void _endDot(Canvas canvas, Offset at, Color color, {required bool hero}) {
    if (_p01 < 1.0) return;
    final r = hero ? 4.2 : 3.2;
    if (partialLast) {
      canvas.drawCircle(at, r, Paint()..color = Colors.white);
      canvas.drawCircle(
        at,
        r,
        Paint()
          ..color = color.withAlpha(170)
          ..style = PaintingStyle.stroke
          ..strokeWidth = 1.8,
      );
      return;
    }
    canvas.drawCircle(at, r + 1.6, Paint()..color = Colors.white);
    canvas.drawCircle(at, r, Paint()..color = color);
  }

  void _bead(Canvas canvas, List<Offset> pts, Color color) {
    if (!_kHeroBeadEnabled || _p01 < 1.0 || _idleFade <= 0.05) return;
    final solidN = _solidCount(pts.length);
    if (solidN < 2) return;
    final path = Path();
    _addMonotonePath(path, pts.sublist(0, solidN));
    final metrics = path.computeMetrics().toList(growable: false);
    if (metrics.isEmpty) return;
    final m = metrics.first;
    if (m.length <= 1) return;
    final headD = bead.clamp(0.0, 1.0) * m.length;
    final a0 = _idleFade;
    const tailN = 10;
    const tailLen = 48.0;
    for (var t = tailN; t >= 1; t--) {
      final d = headD - tailLen * t / tailN;
      if (d < 0) continue;
      final tan = m.getTangentForOffset(d);
      if (tan == null) continue;
      final f = 1 - t / (tailN + 1.0);
      canvas.drawCircle(
        tan.position,
        1.0 + f * 2.0,
        Paint()
          ..color = color.withAlpha((a0 * f * f * 170).round().clamp(0, 255)),
      );
    }
    final head = m.getTangentForOffset(headD)?.position;
    if (head == null) return;
    canvas.drawCircle(
      head,
      9.0,
      Paint()..color = color.withAlpha((a0 * 34).round()),
    );
    canvas.drawCircle(
      head,
      4.4,
      Paint()..color = color.withAlpha((a0 * 240).round()),
    );
    canvas.drawCircle(
      head,
      1.8,
      Paint()..color = Colors.white.withAlpha((a0 * 255).round()),
    );
  }

  @override
  bool shouldRepaint(_LhRidgeFullPainter old) =>
      !identical(old.lines, lines) ||
      !identical(old.labels, labels) ||
      old.partialLast != partialLast ||
      old.dpr != dpr ||
      old.progress != progress ||
      old.bead != bead ||
      old.selectedIndex != selectedIndex ||
      old.selectAlpha != selectAlpha;
}

// ═════════════════════════════════════════════════════════════════════════════
// _HeroSparkPainter — 单卡右上的微型趋势线 (40×12)
//   目的：给 hero 数字加"来路"——用户不仅看到终点，也看到形状（爬升 vs 突涨）。
//   规范：
//     · 1px polyline，圆滑 join，round cap
//     · 末端 1.5px 实心圆点（视觉锚，指向"当前"）
//     · 单色，随环比方向：pos → copper, neg → neg, flat → mute2
//     · 无网格、无坐标、无阴影 — editorial 极简
// ═════════════════════════════════════════════════════════════════════════════
class _HeroSparkPainter extends CustomPainter {
  const _HeroSparkPainter({required this.data, required this.color});
  final List<double> data;
  final Color color;

  @override
  void paint(Canvas canvas, Size size) {
    if (data.length < 2) return;
    double minV = data.first, maxV = data.first;
    for (final v in data) {
      if (v < minV) minV = v;
      if (v > maxV) maxV = v;
    }
    final range = (maxV - minV).abs() < 1e-9 ? 1.0 : (maxV - minV);
    // 顶/底留 1px 让点不贴边
    const padY = 1.5;
    final usableH = size.height - padY * 2;
    // 右侧末端点留 2px 让 dot 不被裁
    final usableW = size.width - 2.0;

    final step = usableW / (data.length - 1);
    double xOf(int i) => i * step;
    double yOf(double v) => padY + (maxV - v) / range * usableH;

    // v3 · Catmull-Rom 平滑 (跟 _TrendChart / hero big spark 一致的编辑体呼吸感)
    final offsets = <Offset>[
      for (int i = 0; i < data.length; i++) Offset(xOf(i), yOf(data[i])),
    ];
    final path = Path();
    _addSmoothPath(path, offsets);
    canvas.drawPath(
      path,
      Paint()
        ..color = color.withAlpha(190)
        ..strokeWidth = 1.0
        ..style = PaintingStyle.stroke
        ..strokeCap = StrokeCap.round
        ..strokeJoin = StrokeJoin.round,
    );

    // 末端锚点
    final lastX = xOf(data.length - 1);
    final lastY = yOf(data.last);
    canvas.drawCircle(Offset(lastX, lastY), 1.5, Paint()..color = color);
  }

  @override
  bool shouldRepaint(_HeroSparkPainter old) =>
      !identical(old.data, data) || old.color != color;
}

// ═════════════════════════════════════════════════════════════════════════════
// _LhBigTrendPainter — 折线图 (点击 hero 数字后弹出的 sheet 里用) — v2 重设计
//   v2 变化:
//     · 左侧留 28px 给 Y 轴数值刻度 (4 档: MAX / 2/3 / 1/3 / MIN)
//     · 3 条横向虚线网格 (hairline dashed) 给"高低"提供尺子感
//     · 折线下方柔和填充 (color × 0.14 → 0)  —— 读数体量感
//     · 提案 baseline 用更醒目的双段虚线, 违背区 (数据落在错误一侧) tint
//     · 末端 anchor 从"3px 圆 + 竖虚线"改为 pill badge (TODAY XX%)
//     · 底部 x 轴 4 锚点保留 (今日高亮成 ink 色)
//     · violationColor / valueUnit 由外部传入, 让 pill / 违背区跟违背等级联动
// ═════════════════════════════════════════════════════════════════════════════
class _LhBigTrendPainter extends CustomPainter {
  const _LhBigTrendPainter({
    required this.data,
    required this.color,
    this.expected,
    this.expectedColor,
    this.violationTint,
    this.warnTint,
    this.warnPct = 10,
    this.breachPct = 20,
    this.isRate = false,
    this.pillLabel,
    this.selectedIndex,
    this.xLabels,
    this.compareData,
    this.compareColor,
    this.forecast,
    this.forecastColor,
    // v2.11 · 默认参数改回编辑体铜纸墨暖调, 跟外面 hero sparkline (LhColors.mute2/line2)
    //         保持视觉统一; v2.8 短暂改冷紫是为紫气泡系统, 现已回滚.
    this.axisTextColor = const Color(0xFF9E988E), // 暖灰 · 编辑体次要文字
    this.gridColor = const Color(0xFFE1DBCC), // 暖沙 · 编辑体 hairline
  });

  final List<double> data; // 数据序列(按时间正序)
  final Color color; // 主线颜色
  final double? expected; // 提案基线值(可选)
  final Color? expectedColor; // 提案基线颜色
  final Color? violationTint; // 违背区带填充色 (>20% 偏离带)
  final Color? warnTint; // 关注区带填充色 (10~20% 偏离带)
  final double warnPct; // 关注阈值 %
  final double breachPct; // 违背阈值 %
  final bool isRate; // 是否比率类 (用来格式化 Y 轴 & pill)
  final String? pillLabel; // 末端 pill 文字 (缺则从 data.last 生成)
  final int? selectedIndex; // 拖动选中的点；非 null 时不画 TODAY pill
  final List<String>? xLabels; // 与 data 对齐的日期标签 (mm.dd)
  final List<double>? compareData; // 环比对比线（如日视图的上月）
  final Color? compareColor;

  /// 月化预测月末值 —— 仅「点月 + 当前月 + 规模/金额类指标」时给。
  /// 非空时在最后一列从实线末端向上画虚线到预测值（会议："像柱状图似的"）。
  final double? forecast;
  final Color? forecastColor;

  final Color axisTextColor;
  final Color gridColor;

  @override
  void paint(Canvas canvas, Size size) {
    if (data.length < 2) return;

    // ═════ v2.8 · 紫编辑体配色 (白底 + ink 主轴 + plum accent) ═════════
    // v1 编辑体铜纸墨已 sunset,底色跟 sheet(现在是白 or _LhPlum.mist) 无缝连接,
    // 深紫墨 accent 替代 copper,让"数据点自己说话"—— 无 gradient 无 tint block.
    const paperWhite = Colors.white; // 白底,对齐 v2.6 页面白
    const axisInk = Color(0xFF3D3A34); // ink2 深灰 (坐标轴保留中性)
    // v2.11 · axis/grid 改回编辑体铜纸墨暖调, 跟外面 hero sparkline 统一
    const axisMute = Color(0xFF9E988E); // 暖灰 (副 tick, 刻度值)
    const gridSoft = Color(0xFFE1DBCC); // 暖沙 (水平参考线)
    const plumMain = Color(
      0xFF8B7BC4,
    ); // = _LhPlum.primary (提案基线 accent, 语义色保留)
    const negMain = Color(0xFFB4443D); // neg (违背阈值线,保留业务语义)
    final lineColor = color; // 主线 (通常 _LhPlum.deep 或 primary, 外部传入)

    // ─── 1. 白底铺满 ───────────────────────────────
    canvas.drawRect(
      Rect.fromLTWH(0, 0, size.width, size.height),
      Paint()..color = paperWhite,
    );

    // ─── 2. 值域计算 (含 expected / 对比线) ────
    // v16 · 有月末预测 = 最后一期没走完：它画成进度胶囊，不上线、不进值域。
    final partial = forecast != null && data.length >= 3;
    final solidN = partial ? data.length - 1 : data.length;
    final solid = data.sublist(0, solidN);
    double minV = solid.first, maxV = solid.first;
    for (final v in solid) {
      if (v < minV) minV = v;
      if (v > maxV) maxV = v;
    }
    if (compareData != null) {
      for (final v in compareData!) {
        if (v < minV) minV = v;
        if (v > maxV) maxV = v;
      }
    }
    if (forecast != null) {
      // 预测点要落在画布里，否则虚线会顶出上边界。
      final f = forecast!;
      if (f > maxV) maxV = f;
      if (f < minV) minV = f;
    }
    if (expected != null) {
      final ex = expected!;
      final absEx = ex.abs() < 1e-9 ? 1.0 : ex.abs();
      final ub = ex + absEx * breachPct / 100;
      final lb = ex - absEx * breachPct / 100;
      if (ub > maxV) maxV = ub;
      if (lb < minV) minV = lb;
    }
    final valPad = (maxV - minV).abs() * 0.12 + 1e-9;
    minV -= valPad;
    maxV += valPad;
    final valRange = (maxV - minV).abs() < 1e-9 ? 1.0 : (maxV - minV);

    const padLeft = 38.0; // Y 轴数值区
    const padRight = 10.0;
    const padTop = 12.0;
    const padBottom = 22.0; // x 轴刻度区
    final usableW = size.width - padLeft - padRight;
    final usableH = size.height - padTop - padBottom;
    final step = usableW / (data.length - 1);
    double xOf(int i) => padLeft + i * step;
    double yOf(double v) => padTop + (maxV - v) / valRange * usableH;
    final baselineY = padTop + usableH;

    // ─── 3. 极淡水平网格 (5 档参考线) ──────────────
    final yTicks = <double>[
      maxV,
      maxV - valRange / 4,
      maxV - valRange * 2 / 4,
      maxV - valRange * 3 / 4,
      minV,
    ];
    final gridPaint = Paint()
      ..color = gridSoft
      ..strokeWidth = 0.5;
    for (int i = 1; i < yTicks.length - 1; i++) {
      final y = yOf(yTicks[i]);
      canvas.drawLine(
        Offset(padLeft, y),
        Offset(padLeft + usableW, y),
        gridPaint,
      );
    }

    // ─── 4. Y 轴刻度值 (mono, 右对齐贴 tick) ──────
    for (int i = 0; i < yTicks.length; i++) {
      final y = yOf(yTicks[i]);
      final tp = TextPainter(
        text: TextSpan(
          text: _formatAxisValue(yTicks[i]),
          style: const TextStyle(
            color: axisMute,
            fontSize: 8,
            fontWeight: FontWeight.w500,
            letterSpacing: 0.2,
          ),
        ),
        textDirection: TextDirection.ltr,
      )..layout();
      tp.paint(canvas, Offset(padLeft - 5 - tp.width, y - tp.height / 2));
    }

    // ─── 5. 提案基线 + ±20% 违背阈值线 ─────────────
    if (expected != null) {
      final ex = expected!;
      final absEx = ex.abs() < 1e-9 ? 1.0 : ex.abs();
      final ub = ex + absEx * breachPct / 100;
      final lb = ex - absEx * breachPct / 100;
      final expColor = expectedColor ?? plumMain;

      // 提案主线 (稍粗虚线)
      _drawDashedLine(
        canvas,
        Offset(padLeft, yOf(ex)),
        Offset(padLeft + usableW, yOf(ex)),
        Paint()
          ..color = expColor.withAlpha(200)
          ..strokeWidth = 0.9,
        dashW: 5,
        gapW: 3,
      );
      // 提案标签 (右上角外部)
      final expTp = TextPainter(
        text: TextSpan(
          text: '提案 ${_formatAxisValue(ex)}',
          style: TextStyle(
            color: expColor,
            fontSize: 7.5,
            fontWeight: FontWeight.w700,
            letterSpacing: 0.4,
          ),
        ),
        textDirection: TextDirection.ltr,
      )..layout();
      final expLabelY = yOf(ex) - expTp.height - 3;
      expTp.paint(
        canvas,
        Offset(
          padLeft + usableW - expTp.width,
          expLabelY < padTop ? yOf(ex) + 3 : expLabelY,
        ),
      );

      // 上/下违背阈值线 (极细虚线, neg 半透明)
      final vLinePaint = Paint()
        ..color = negMain.withAlpha(105)
        ..strokeWidth = 0.5;
      if (yOf(ub) > padTop - 1) {
        _drawDashedLine(
          canvas,
          Offset(padLeft, yOf(ub)),
          Offset(padLeft + usableW, yOf(ub)),
          vLinePaint,
          dashW: 2,
          gapW: 3,
        );
      }
      if (yOf(lb) < baselineY + 1) {
        _drawDashedLine(
          canvas,
          Offset(padLeft, yOf(lb)),
          Offset(padLeft + usableW, yOf(lb)),
          vLinePaint,
          dashW: 2,
          gapW: 3,
        );
      }
    }

    // ─── 6. 主折线 (v16 · 单调三次, 2px + 淡渐变填充给体积) ─
    final mainOffsets = <Offset>[
      for (int i = 0; i < solid.length; i++) Offset(xOf(i), yOf(solid[i])),
    ];
    final path = Path();
    _addSmoothPath(path, mainOffsets);
    if (mainOffsets.length >= 2) {
      final area = Path.from(path)
        ..lineTo(mainOffsets.last.dx, baselineY)
        ..lineTo(mainOffsets.first.dx, baselineY)
        ..close();
      canvas.drawPath(
        area,
        Paint()
          ..shader = LinearGradient(
            begin: Alignment.topCenter,
            end: Alignment.bottomCenter,
            colors: [lineColor.withAlpha(40), lineColor.withAlpha(0)],
          ).createShader(Rect.fromLTRB(0, padTop, size.width, baselineY)),
      );
    }
    canvas.drawPath(
      path,
      Paint()
        ..color = lineColor
        ..strokeWidth = 2.0
        ..style = PaintingStyle.stroke
        ..strokeCap = StrokeCap.round
        ..strokeJoin = StrokeJoin.round,
    );

    if (compareData != null && compareData!.length >= 2) {
      final compare = compareData!;
      final cmpPaint = Paint()
        ..color = (compareColor ?? axisMute).withAlpha(190)
        ..strokeWidth = 1.1
        ..style = PaintingStyle.stroke
        ..strokeCap = StrokeCap.round
        ..strokeJoin = StrokeJoin.round;
      for (int i = 1; i < compare.length; i++) {
        _drawDashedLine(
          canvas,
          Offset(xOf(i - 1), yOf(compare[i - 1])),
          Offset(xOf(i), yOf(compare[i])),
          cmpPaint,
          dashW: 4,
          gapW: 3,
        );
      }
    }

    // ─── 7. 数据点 (v16 · 只标有话要说的点) ────
    // 逐点空心圆删掉 —— 三十个一样的圈只是纹理。只留违背 / 关注的实心点和末端点。
    for (int i = 0; i < solid.length; i++) {
      final cx = xOf(i);
      final cy = yOf(data[i]);
      Color dotStroke = lineColor;
      Color dotFill = paperWhite;
      bool solidDot = false;
      double radius = 2.2;

      if (expected != null) {
        final absEx = expected!.abs() < 1e-9 ? 1.0 : expected!.abs();
        final absDev = ((data[i] - expected!) / absEx * 100).abs();
        if (absDev > breachPct) {
          dotStroke = negMain;
          dotFill = negMain;
          solidDot = true;
          radius = 2.6;
        } else if (absDev > warnPct) {
          dotStroke = plumMain;
          dotFill = plumMain;
          solidDot = true;
          radius = 2.3;
        }
      }

      // 末端 today 突出 (仅未选中时)
      if (i == solid.length - 1 && selectedIndex == null) {
        canvas.drawCircle(Offset(cx, cy), 3.6, Paint()..color = paperWhite);
        canvas.drawCircle(Offset(cx, cy), 3.0, Paint()..color = lineColor);
        continue;
      }

      if (!solidDot) continue;
      canvas.drawCircle(Offset(cx, cy), radius, Paint()..color = dotFill);
      canvas.drawCircle(Offset(cx, cy), radius, Paint()..color = dotStroke);
    }

    // ─── 7.5 月化预测虚线 (仅点月 · 当前月 · 规模/金额类) ──────────
    //   会议原话："比如说像今天中石化已经 8700 了，那么在月度上数据里面
    //   就有一个预测……像柱状图似的"。所以预测不另起一格，就在当月这一列
    //   从实线末端往上虚线延伸，端点空心圈 + 数字，一眼看出还差多少到月末。
    final fc = forecast;
    double? paceFillTop;
    if (fc != null && partial) {
      final lastX = xOf(data.length - 1);
      final toY = yOf(fc).clamp(padTop, baselineY).toDouble();
      final fColor = forecastColor ?? lineColor;
      // 虚线从上一个完整期直接连到预测点 —— 不再先掉到半个月的实际值上。
      _drawDashedLine(
        canvas,
        Offset(xOf(solidN - 1), yOf(data[solidN - 1])),
        Offset(lastX, toY),
        Paint()
          ..color = fColor.withAlpha(165)
          ..strokeWidth = 1.5
          ..strokeCap = StrokeCap.round,
        dashW: 4,
        gapW: 3,
      );
      // 进度胶囊：顶 = 月末预测，实心 = 已发生 / 预测。
      const capW = 9.0;
      final cap = RRect.fromLTRBR(
        lastX - capW / 2,
        toY,
        lastX + capW / 2,
        baselineY,
        const Radius.circular(capW / 2),
      );
      canvas.drawRRect(cap, Paint()..color = fColor.withAlpha(22));
      canvas.drawRRect(
        cap,
        Paint()
          ..color = fColor.withAlpha(90)
          ..style = PaintingStyle.stroke
          ..strokeWidth = 0.8,
      );
      final fillTop = _trendPaceFillTop(
        actual: data.last,
        forecast: fc,
        forecastY: toY,
        plotBottom: baselineY,
      );
      paceFillTop = fillTop;
      if (baselineY - fillTop > 0.5) {
        canvas.save();
        canvas.clipRRect(cap);
        canvas.drawRect(
          Rect.fromLTRB(lastX - capW / 2, fillTop, lastX + capW / 2, baselineY),
          Paint()..color = fColor.withAlpha(200),
        );
        canvas.restore();
      }
      canvas.drawCircle(Offset(lastX, toY), 3.4, Paint()..color = paperWhite);
      canvas.drawCircle(
        Offset(lastX, toY),
        3.4,
        Paint()
          ..color = fColor
          ..style = PaintingStyle.stroke
          ..strokeWidth = 1.3,
      );
      final pct = (lighthouseTrendPaceRatio(data.last, fc) * 100).round();
      final fTp = TextPainter(
        text: TextSpan(
          text: '预测 ${_formatAxisValue(fc)} · 已走 $pct%',
          style: TextStyle(
            color: fColor,
            fontSize: 7.5,
            fontWeight: FontWeight.w700,
            letterSpacing: 0.3,
          ),
        ),
        textDirection: TextDirection.ltr,
      )..layout();
      // 标签放预测点的左上方 —— 右侧只剩 padRight，放不下。
      // 窄画布下 upper 可能小于 lower，clamp 会抛，所以先取 max 兜底。
      final fxMax = math.max(padLeft, size.width - fTp.width - 1);
      final fx = (lastX - fTp.width - 7).clamp(padLeft, fxMax);
      final fyMax = math.max(0.0, size.height - fTp.height);
      final fy = (toY - fTp.height - 2).clamp(0.0, fyMax);
      fTp.paint(canvas, Offset(fx, fy));
    }

    // ─── 8. 拖动选点 crosshair ──────────────────────
    final si = selectedIndex;
    if (si != null && si >= 0 && si < data.length) {
      final cx = xOf(si);
      // 没走完那期的读数在胶囊实心顶上；它不在轴上，所以不画横向读数线。
      final onPace = partial && si == data.length - 1 && paceFillTop != null;
      final cy = onPace ? paceFillTop! : yOf(data[si]);
      final chPaint = Paint()
        ..color = axisInk.withAlpha(90)
        ..strokeWidth = 0.6;
      // 竖直虚线 (baseline → point)
      _drawDashedLine(
        canvas,
        Offset(cx, cy),
        Offset(cx, baselineY),
        chPaint,
        dashW: 2,
        gapW: 3,
      );
      // 水平虚线 (Y 轴 → point)
      if (!onPace) {
        _drawDashedLine(
          canvas,
          Offset(padLeft, cy),
          Offset(cx, cy),
          chPaint,
          dashW: 2,
          gapW: 3,
        );
      }
      // 选中点大圆 (双层: 白 halo + 主色实心)
      canvas.drawCircle(Offset(cx, cy), 4.5, Paint()..color = paperWhite);
      canvas.drawCircle(Offset(cx, cy), 3.4, Paint()..color = lineColor);
    }

    // ─── 9. 坐标轴 (v16 · 去掉 Y 轴竖线和 tick 短线，刻度值 + 发丝网格够用) ─
    final axisPaint = Paint()
      ..color = gridSoft
      ..strokeWidth = 0.8;

    // ─── 10. X 轴主轴 + 每周 tick ─────────────────
    canvas.drawLine(
      Offset(padLeft, baselineY),
      Offset(padLeft + usableW, baselineY),
      axisPaint,
    );
    if (data.length > 14) {
      final wtPaint = Paint()
        ..color = axisMute.withAlpha(180)
        ..strokeWidth = 0.5;
      for (int i = 7; i < data.length - 1; i += 7) {
        final x = xOf(i);
        canvas.drawLine(
          Offset(x, baselineY),
          Offset(x, baselineY + 2),
          wtPaint,
        );
      }
    }

    // ─── 11. X 轴 4 锚点日期标签 (无 pill, 无 today marker) ─
    final tickIndices = <int>[
      0,
      (data.length / 3).round(),
      (data.length * 2 / 3).round(),
      data.length - 1,
    ];
    for (final ti in tickIndices) {
      final x = xOf(ti);
      canvas.drawLine(
        Offset(x, baselineY),
        Offset(x, baselineY + 3.5),
        axisPaint,
      );
      final rawLabel =
          (xLabels != null &&
              ti >= 0 &&
              ti < xLabels!.length &&
              xLabels![ti].isNotEmpty)
          ? xLabels![ti]
          : (ti == data.length - 1 ? 'today' : '');
      if (rawLabel.isEmpty) continue;
      final isToday = ti == data.length - 1;
      final tp = TextPainter(
        text: TextSpan(
          text: rawLabel,
          style: TextStyle(
            color: isToday ? axisInk : axisMute,
            fontSize: 7.5,
            fontWeight: isToday ? FontWeight.w700 : FontWeight.w600,
            letterSpacing: 0.3,
          ),
        ),
        textDirection: TextDirection.ltr,
      )..layout();
      tp.paint(canvas, Offset(x - tp.width / 2, baselineY + 6));
    }
  }

  /// Helper: 画虚线段 (通用)
  void _drawDashedLine(
    Canvas canvas,
    Offset from,
    Offset to,
    Paint paint, {
    required double dashW,
    required double gapW,
  }) {
    final dx = to.dx - from.dx;
    final dy = to.dy - from.dy;
    final len = math.sqrt(dx * dx + dy * dy);
    if (len < 1e-9) return;
    final ux = dx / len;
    final uy = dy / len;
    double travelled = 0;
    while (travelled < len) {
      final segEnd = math.min(travelled + dashW, len);
      canvas.drawLine(
        Offset(from.dx + ux * travelled, from.dy + uy * travelled),
        Offset(from.dx + ux * segEnd, from.dy + uy * segEnd),
        paint,
      );
      travelled += dashW + gapW;
    }
  }

  /// Y 轴数值格式化: 比率类 → X.XX%, 金额 → 万/亿 后缀
  String _formatAxisValue(double v) {
    if (isRate) return '${v.toStringAsFixed(2)}%';
    return _fmtChartShort(v);
  }

  /// 把颜色的 alpha 拉到最少某个值, 用来把极淡的 tint 转成可见的圆点色
  static Color _boostAlpha(Color c, int minAlpha) =>
      c.alpha >= minAlpha ? c : c.withAlpha(minAlpha);

  /// 找 ticks 中离 target 最近的档位 index (给 Y 轴当前值高亮用)
  int _nearestTickIdx(List<double> ticks, double target) {
    int best = 0;
    double bestDiff = (ticks[0] - target).abs();
    for (int i = 1; i < ticks.length; i++) {
      final d = (ticks[i] - target).abs();
      if (d < bestDiff) {
        bestDiff = d;
        best = i;
      }
    }
    return best;
  }

  @override
  bool shouldRepaint(_LhBigTrendPainter old) =>
      !identical(old.data, data) ||
      old.color != color ||
      old.expected != expected ||
      old.violationTint != violationTint ||
      old.warnTint != warnTint ||
      old.warnPct != warnPct ||
      old.breachPct != breachPct ||
      old.pillLabel != pillLabel ||
      old.forecast != forecast ||
      old.selectedIndex != selectedIndex ||
      !listEquals(old.xLabels, xLabels);
}

// ═════════════════════════════════════════════════════════════════════════════
// _MetaCompareStage —— meta 指标横向比较 drawer 的内容主体（含编排动画）
//
//   编排（单一 AnimationController 780ms 驱动，postFrame 触发）：
//     · 0.00–0.55  masthead 大数字 count-up (easeOutQuart)
//     · 0.08–0.62  涨/跌/平 堆叠条从左向右 draw-in (easeOutCubic)
//     · 0.20+i·0.028  首 12 行 stagger 入场 (opacity + 6px Y translate, easeOutCubic)
//                     第 13 行起直接呈现，避免长列表 rebuild 成本
//
//   排版关键升级（相对 v1 版 _buildMetaCompareDrawer）：
//     · 关闭 × 内嵌到 masthead 顶行末端（不再占独立一行 40px）
//     · Typography-only kicker (`利润 · PROFIT`) —— 跟卡片版语言统一
//     · 涨/跌/平 从 3 段文字 → 堆叠比例条 + 内联 mono 数字
//     · 行左 2px 状态色 stripe（涨绿/跌红/平灰/无环比透明）—— FT app 手势
//     · 行内 bar 加 zero-baseline hairline，top1 加粗到 3px（其余 2px）
//     · bar 色去掉 product 紫，改 ink2 中性——语义色由 stripe 承担，避免冗余
// ═════════════════════════════════════════════════════════════════════════════
// ═════════════════════════════════════════════════════════════════════════════
// _MetaEntry / _MetaMetricCol —— 表格数据模型
//
//   v3.7 重设计: drawer 一次一列 → 表格 N 行 × M 列.
//   同一个 entry 携带所有指标值 (values Map), 用户可按任意列 tap header 换序.
//   激活列（tapped 时进入的那列）用 copper tint 高亮列, 有 ↓/↑ 指示器.
// ═════════════════════════════════════════════════════════════════════════════
class _MetaEntry {
  const _MetaEntry({
    required this.name,
    required this.group,
    required this.values,
    required this.deltas,
  });
  final String name;
  final String group;
  final Map<String, double> values; // metric key → value
  final Map<String, double>
  deltas; // metric key → delta% (vs 上期), 缺失即 null 视为无数据
}

class _MetaMetricCol {
  const _MetaMetricCol({
    required this.key,
    required this.short,
    this.isRate = false,
  });
  final String key;
  final String short;
  final bool isRate;
}

// ═════════════════════════════════════════════════════════════════════════════
// _MetaCompareStage —— meta 指标横向对比表格
//
//   v3 重做: 从 "单列 drawer + count-up 秀" → 可排序表格.
//   用户点某行的 meta chip → 打开表格, 该列默认排序 desc, 用户可 tap header 换列/换向.
//   排版:
//     · Masthead: kicker + 项数/vs · 内嵌关闭 ×
//     · 表格 header 行: [名称] [metric1] [metric2] ... (可 tap 排序, active 列 copper 高亮)
//     · 数据行: [rank] [name+group] [metric values...]  数字右对齐 mono
//   横向可滚 (metric 多时), 纵向 ListView 滚
// ═════════════════════════════════════════════════════════════════════════════
class _MetaCompareStage extends StatefulWidget {
  const _MetaCompareStage({
    required this.activeMetricKey,
    required this.metrics,
    required this.entries,
    required this.vsLabel,
    required this.onClose,
  });
  final String activeMetricKey;
  final List<_MetaMetricCol> metrics;
  final List<_MetaEntry> entries;
  final String vsLabel;
  final VoidCallback onClose;

  @override
  State<_MetaCompareStage> createState() => _MetaCompareStageState();
}

class _MetaCompareStageState extends State<_MetaCompareStage> {
  late String _sortKey;
  bool _sortDesc = true;

  // ═════════════════ 布局常量 (v3.8 editorial) ═════════════════
  static const double _rankW = 34;
  static const double _nameW = 116;
  static const double _leftW = _rankW + _nameW; // 150
  static const double _metricW = 78;
  static const double _activeMetricW = 108;
  static const double _headerH = 46;
  static const double _rowH = 58;
  static const double _footerRowH = 34;

  @override
  void initState() {
    super.initState();
    _sortKey = widget.activeMetricKey;
  }

  // ─── 数据派生 ───

  List<_MetaEntry> get _sortedEntries {
    final list = List<_MetaEntry>.from(widget.entries);
    list.sort((a, b) {
      final va = (a.values[_sortKey] ?? 0).abs();
      final vb = (b.values[_sortKey] ?? 0).abs();
      final cmp = va.compareTo(vb);
      return _sortDesc ? -cmp : cmp;
    });
    return list;
  }

  // 当前活跃列 sum abs (name 列显示 share%)
  double get _activeColSumAbs {
    double s = 0;
    for (final e in widget.entries) {
      s += (e.values[_sortKey] ?? 0).abs();
    }
    return s;
  }

  Map<String, double> get _colTotals {
    final r = <String, double>{};
    for (final m in widget.metrics) {
      double sum = 0;
      for (final e in widget.entries) {
        sum += (e.values[m.key] ?? 0);
      }
      r[m.key] = sum;
    }
    return r;
  }

  Map<String, double> get _colAvgs {
    final r = <String, double>{};
    final n = widget.entries.length;
    if (n == 0) return r;
    for (final m in widget.metrics) {
      double sum = 0;
      for (final e in widget.entries) {
        sum += (e.values[m.key] ?? 0);
      }
      r[m.key] = sum / n;
    }
    return r;
  }

  // ─── 交互 ───

  void _tapHeader(String key) {
    setState(() {
      if (_sortKey == key) {
        _sortDesc = !_sortDesc;
      } else {
        _sortKey = key;
        _sortDesc = true;
      }
    });
  }

  double _metricColWidth(String key) =>
      key == _sortKey ? _activeMetricW : _metricW;

  double get _tableW {
    return _leftW +
        widget.metrics.fold<double>(0, (s, m) => s + _metricColWidth(m.key));
  }

  // ─── 英文标签 map ───
  //
  // 小地图, 常见指标 key → UPPER 英文.没命中的直接 upper key 用兜底.
  static const Map<String, String> _kMetricEn = {
    'profit': 'PROFIT',
    'netProfit': 'NET PROFIT',
    'grossProfit': 'PROFIT',
    'revenue': 'REVENUE',
    'sales': 'SALES',
    'salesVolume': 'VOLUME',
    'cost': 'COST',
    'tax': 'TAX',
    'rate': 'RATE',
    'grossRate': 'GROSS RATE',
    'profitRate': 'PROFIT RATE',
    'spreadRate': 'SPREAD',
    'discount': 'DISCOUNT',
    'rebate': 'REBATE',
    'settlement': 'SETTLEMENT',
    'verifiedScale': 'VERIFIED',
  };

  String _metricEnKey(String k) => _kMetricEn[k] ?? k.toUpperCase();

  String _metricUnitLabel(_MetaMetricCol m) => m.isRate ? '%' : '万元';

  // ═════════════════════════════════════════════════════════════════════════
  // Build
  // ═════════════════════════════════════════════════════════════════════════

  @override
  Widget build(BuildContext context) {
    final sorted = _sortedEntries;
    final totals = _colTotals;
    final avgs = _colAvgs;
    final sumAbs = _activeColSumAbs;
    final n = sorted.length;
    final tableWidth = _tableW;

    // Editorial rule — 冷灰分隔，避免暖米色被看成「金色线」
    final ruleThick = Container(
      height: 1.5,
      width: tableWidth,
      color: DunesColors.resolve(
        context,
        LhColors.ink,
        role: DunesColorRole.surface,
      ).withAlpha(215),
    );
    final ruleThin = Container(
      height: 0.5,
      width: tableWidth,
      color: DunesColors.resolve(
        context,
        const Color(0xFFE6E2EE),
        role: DunesColorRole.surface,
      ),
    );

    return Column(
      crossAxisAlignment: CrossAxisAlignment.start,
      children: [
        // ═════════════════ Masthead ═════════════════
        _buildMasthead(n),

        // ═════════════════ 表格 (整体一个 horizontal scroll) ═════════════════
        Expanded(
          child: SingleChildScrollView(
            scrollDirection: Axis.horizontal,
            physics: const ClampingScrollPhysics(),
            padding: EdgeInsets.zero,
            child: SizedBox(
              width: tableWidth,
              child: Column(
                crossAxisAlignment: CrossAxisAlignment.start,
                children: [
                  // Top 编辑体 rule (1.5px ink)
                  ruleThick,
                  _buildHeaderRow(),
                  ruleThin,
                  // Body: ListView.builder 保留 lazy 加载
                  Expanded(
                    child: ListView.builder(
                      padding: EdgeInsets.zero,
                      itemCount: sorted.length,
                      itemExtent: _rowH,
                      itemBuilder: (ctx, i) => _buildDataRow(
                        i,
                        sorted[i],
                        sumAbs,
                        isLast: i == sorted.length - 1,
                      ),
                    ),
                  ),
                  // Footer: 1.5px rule → 合计 · Σ → 均值 · μ → 1.5px rule
                  ruleThick,
                  _buildFooterRow('合计', 'Σ', totals, isTotal: true),
                  _buildFooterRow('均值', 'μ', avgs, isTotal: false),
                  ruleThick,
                ],
              ),
            ),
          ),
        ),
      ],
    );
  }

  // ═════════════════════════════════════════════════════════════════════════
  // Masthead
  // ═════════════════════════════════════════════════════════════════════════

  Widget _buildMasthead(int n) {
    return Padding(
      padding: const EdgeInsets.fromLTRB(18, 14, 8, 12),
      child: Row(
        crossAxisAlignment: CrossAxisAlignment.center,
        children: [
          Expanded(
            child: Text.rich(
              TextSpan(
                children: [
                  TextSpan(
                    text: '$n 项',
                    style: LhTypography.sans(
                      size: 10.5,
                      color: DunesColors.resolve(context, LhColors.mute),
                      context: context,
                    ),
                  ),
                  if (widget.vsLabel.isNotEmpty)
                    TextSpan(
                      text: '  ·  ${widget.vsLabel}',
                      style: LhTypography.mono(
                        size: 9.5,
                        color: DunesColors.resolve(context, LhColors.mute2),
                        weight: FontWeight.w500,
                        letterSpacing: 0.3,
                        context: context,
                      ),
                    ),
                  TextSpan(
                    text: '  ·  tap 表头切列排序',
                    style: LhTypography.mono(
                      size: 9,
                      color: DunesColors.resolve(context, LhColors.mute2),
                      weight: FontWeight.w500,
                      letterSpacing: 0.3,
                      context: context,
                    ),
                  ),
                ],
              ),
            ),
          ),
          GestureDetector(
            behavior: HitTestBehavior.opaque,
            onTap: widget.onClose,
            child: Padding(
              padding: EdgeInsets.all(8),
              child: Icon(
                Icons.close_rounded,
                size: 16,
                color: DunesColors.resolve(context, LhColors.mute),
              ),
            ),
          ),
        ],
      ),
    );
  }

  // ═════════════════════════════════════════════════════════════════════════
  // Header Row (two-layer: sans main + mono kicker)
  // ═════════════════════════════════════════════════════════════════════════

  Widget _buildHeaderRow() {
    return SizedBox(
      height: _headerH,
      child: Row(
        children: [
          // ── Rank header ('# / RANK') ──
          SizedBox(
            width: _rankW,
            child: Padding(
              padding: const EdgeInsets.only(left: 8, right: 2),
              child: Column(
                crossAxisAlignment: CrossAxisAlignment.start,
                mainAxisAlignment: MainAxisAlignment.center,
                children: [
                  Text(
                    '#',
                    style: LhTypography.sans(
                      size: 12,
                      weight: FontWeight.w700,
                      color: DunesColors.resolve(context, LhColors.ink),
                      letterSpacing: -0.1,
                      context: context,
                    ),
                  ),
                  const SizedBox(height: 3),
                  Text(
                    'RANK',
                    style: LhTypography.mono(
                      size: 7.5,
                      color: DunesColors.resolve(context, LhColors.mute2),
                      weight: FontWeight.w700,
                      letterSpacing: 1.0,
                      context: context,
                    ),
                  ),
                ],
              ),
            ),
          ),
          // ── Name header (名称 / NAME) ──
          SizedBox(
            width: _nameW,
            child: Padding(
              padding: const EdgeInsets.symmetric(horizontal: 4),
              child: Column(
                crossAxisAlignment: CrossAxisAlignment.start,
                mainAxisAlignment: MainAxisAlignment.center,
                children: [
                  Text(
                    '名称',
                    style: LhTypography.sans(
                      size: 12,
                      weight: FontWeight.w700,
                      color: DunesColors.resolve(context, LhColors.ink),
                      letterSpacing: -0.1,
                      context: context,
                    ),
                  ),
                  const SizedBox(height: 3),
                  Text(
                    'NAME',
                    style: LhTypography.mono(
                      size: 7.5,
                      color: DunesColors.resolve(context, LhColors.mute2),
                      weight: FontWeight.w700,
                      letterSpacing: 1.0,
                      context: context,
                    ),
                  ),
                ],
              ),
            ),
          ),
          // ── Metric headers ──
          for (final m in widget.metrics) _buildMetricHeader(m),
        ],
      ),
    );
  }

  Widget _buildMetricHeader(_MetaMetricCol m) {
    final isActive = _sortKey == m.key;
    final w = _metricColWidth(m.key);
    return GestureDetector(
      behavior: HitTestBehavior.opaque,
      onTap: () => _tapHeader(m.key),
      child: Container(
        width: w,
        height: _headerH,
        color: isActive
            ? DunesColors.resolve(
                context,
                _LhPlum.mist,
                role: DunesColorRole.surface,
              )
            : Colors.transparent,
        padding: const EdgeInsets.only(right: 8, left: 4),
        child: Column(
          crossAxisAlignment: CrossAxisAlignment.end,
          mainAxisAlignment: MainAxisAlignment.center,
          children: [
            Row(
              mainAxisSize: MainAxisSize.min,
              crossAxisAlignment: CrossAxisAlignment.center,
              children: [
                Text(
                  m.short,
                  style: LhTypography.sans(
                    size: 12,
                    weight: FontWeight.w700,
                    color: isActive
                        ? DunesColors.resolve(context, _LhPlum.deep)
                        : DunesColors.resolve(context, LhColors.ink),
                    letterSpacing: -0.1,
                    context: context,
                  ),
                ),
                if (isActive) ...[
                  const SizedBox(width: 3),
                  Text(
                    _sortDesc ? '▾' : '▴',
                    style: LhTypography.mono(
                      size: 9,
                      color: DunesColors.resolve(context, _LhPlum.primary),
                      weight: FontWeight.w700,
                      context: context,
                    ),
                  ),
                ],
              ],
            ),
            const SizedBox(height: 3),
            LhScrollText(
              '${_metricEnKey(m.key)} · ${_metricUnitLabel(m)}',
              style: LhTypography.mono(
                size: 7.5,
                color: isActive
                    ? DunesColors.resolve(context, _LhPlum.primary)
                    : DunesColors.resolve(context, LhColors.mute2),
                weight: FontWeight.w700,
                letterSpacing: 1.0,
                context: context,
              ),
              overflow: TextOverflow.ellipsis,
              maxLines: 1,
            ),
          ],
        ),
      ),
    );
  }

  // ═════════════════════════════════════════════════════════════════════════
  // Data Row
  // ═════════════════════════════════════════════════════════════════════════

  Widget _buildDataRow(
    int i,
    _MetaEntry e,
    double sumAbs, {
    required bool isLast,
  }) {
    final rankSkin = lighthouseRankSkin(i);
    final isAlt = i.isOdd;
    // 微 zebra: 奇数行 mist, 偶数白, 主副对比不失彩
    final rowBg = isAlt
        ? DunesColors.resolve(
            context,
            _LhPlum.mist,
            role: DunesColorRole.surface,
          )
        : DunesColors.resolve(
            context,
            Colors.white,
            role: DunesColorRole.surface,
          );
    final shareOfActive = sumAbs > 0
        ? (e.values[_sortKey] ?? 0).abs() / sumAbs * 100
        : 0.0;

    return Container(
      decoration: BoxDecoration(
        color: DunesColors.resolveNullable(
          context,
          rowBg,
          role: DunesColorRole.surface,
        ),
        border: isLast
            ? null
            : Border(
                bottom: BorderSide(
                  color: DunesColors.resolve(
                    context,
                    Color(0xFFE6E2EE),
                    role: DunesColorRole.border,
                  ),
                  width: 0.5,
                ),
              ),
      ),
      child: Row(
        children: [
          // ── Rank cell：前三紫条大字、其余蓝条 ──
          SizedBox(
            width: _rankW,
            child: Row(
              children: [
                if (rankSkin.isRanked)
                  Container(
                    width: 2,
                    color: DunesColors.resolveNullable(
                      context,
                      rankSkin.accent,
                      role: DunesColorRole.surface,
                    ),
                  )
                else
                  const SizedBox(width: 2),
                Expanded(
                  child: Center(
                    child: rankSkin.isTop3
                        ? Text(
                            (i + 1).toString(),
                            style: LhTypography.sans(
                              size: 15,
                              weight: FontWeight.w700,
                              color: lhRankPlum,
                              letterSpacing: -0.3,
                              context: context,
                            ),
                          )
                        : Text(
                            (i + 1).toString().padLeft(2, '0'),
                            style: LhTypography.mono(
                              size: 11,
                              color: rankSkin.accent,
                              weight: rankSkin.bold
                                  ? FontWeight.w700
                                  : FontWeight.w500,
                              letterSpacing: 0.3,
                              context: context,
                            ),
                          ),
                  ),
                ),
              ],
            ),
          ),
          // ── Name cell (name + group · share%) ──
          SizedBox(
            width: _nameW,
            child: Padding(
              padding: const EdgeInsets.symmetric(horizontal: 4, vertical: 8),
              child: Column(
                crossAxisAlignment: CrossAxisAlignment.start,
                mainAxisAlignment: MainAxisAlignment.center,
                children: [
                  LhScrollText(
                    e.name,
                    style: LhTypography.sans(
                      size: 11.5,
                      weight: FontWeight.w700,
                      color: DunesColors.resolve(context, LhColors.ink),
                      letterSpacing: -0.1,
                      context: context,
                    ),
                    maxLines: 1,
                    overflow: TextOverflow.ellipsis,
                  ),
                  const SizedBox(height: 3),
                  LhScrollText(
                    _buildGroupShareText(e.group, shareOfActive),
                    style: LhTypography.mono(
                      size: 8,
                      color: DunesColors.resolve(context, LhColors.mute2),
                      weight: FontWeight.w500,
                      letterSpacing: 0.3,
                      context: context,
                    ),
                    maxLines: 1,
                    overflow: TextOverflow.ellipsis,
                  ),
                ],
              ),
            ),
          ),
          // ── Metric value cells ──
          for (final m in widget.metrics) _buildMetricCell(e, m),
        ],
      ),
    );
  }

  String _buildGroupShareText(String group, double sharePct) {
    final g = group.trim();
    final share = '${sharePct.toStringAsFixed(1)}%';
    if (g.isEmpty) return share;
    return '$g · $share';
  }

  Widget _buildMetricCell(_MetaEntry e, _MetaMetricCol m) {
    final isActive = _sortKey == m.key;
    final v = e.values[m.key] ?? 0;
    final isNeg = v < 0;
    final w = _metricColWidth(m.key);
    final valColor = isNeg
        ? DunesColors.resolve(context, LhColors.pos)
        : DunesColors.resolve(context, LhColors.ink);

    if (!isActive) {
      // ── 非活跃列: mono 单值,右对齐,简洁 ──
      return Container(
        width: w,
        alignment: Alignment.centerRight,
        padding: const EdgeInsets.only(right: 8, left: 4),
        child: m.isRate
            ? Text(
                '${v.toStringAsFixed(1)}%',
                style: LhTypography.mono(
                  size: 10.5,
                  color: valColor,
                  weight: FontWeight.w600,
                  context: context,
                ),
              )
            : RichText(
                text: TextSpan(
                  children: [
                    if (isNeg)
                      TextSpan(
                        text: '-',
                        style: LhTypography.mono(
                          size: 10.5,
                          color: DunesColors.resolve(context, LhColors.pos),
                          weight: FontWeight.w600,
                          context: context,
                        ),
                      ),
                    TextSpan(
                      text: _fmt(v.abs()),
                      style: LhTypography.mono(
                        size: 10.5,
                        color: valColor,
                        weight: FontWeight.w600,
                        context: context,
                      ),
                    ),
                    TextSpan(
                      text: _unit(v.abs()),
                      style: LhTypography.mono(
                        size: 8,
                        color: DunesColors.resolve(context, LhColors.mute),
                        weight: FontWeight.w500,
                        context: context,
                      ),
                    ),
                  ],
                ),
              ),
      );
    }

    // ── 活跃列: hero 两层 (数字 + delta)
    final rawDelta = e.deltas[m.key];
    final delta =
        rawDelta != null && lighthouseDeltaPctShown(rawDelta, isRate: m.isRate)
        ? rawDelta
        : null;
    final absV = v.abs();

    return Container(
      width: w,
      // 通用 plum 浅底,叠加在 zebra 上,视觉锁定活跃列
      color: DunesColors.resolve(
        context,
        _LhPlum.deep,
        role: DunesColorRole.surface,
      ).withAlpha(10),
      padding: const EdgeInsets.only(right: 8, left: 4),
      child: Column(
        crossAxisAlignment: CrossAxisAlignment.end,
        mainAxisAlignment: MainAxisAlignment.center,
        mainAxisSize: MainAxisSize.min,
        children: [
          // Hero 值
          m.isRate
              ? Text(
                  '${v.toStringAsFixed(1)}%',
                  style: LhTypography.sans(
                    size: 14,
                    weight: FontWeight.w700,
                    color: valColor,
                    letterSpacing: -0.2,
                    context: context,
                  ),
                )
              : RichText(
                  text: TextSpan(
                    children: [
                      if (isNeg)
                        TextSpan(
                          text: '-',
                          style: LhTypography.sans(
                            size: 14,
                            weight: FontWeight.w700,
                            color: DunesColors.resolve(context, LhColors.pos),
                            letterSpacing: -0.2,
                            context: context,
                          ),
                        ),
                      TextSpan(
                        text: _fmt(absV),
                        style: LhTypography.sans(
                          size: 14,
                          weight: FontWeight.w700,
                          color: valColor,
                          letterSpacing: -0.2,
                          context: context,
                        ),
                      ),
                      TextSpan(
                        text: _unit(absV),
                        style: LhTypography.mono(
                          size: 8.5,
                          color: DunesColors.resolve(context, LhColors.mute),
                          weight: FontWeight.w500,
                          context: context,
                        ),
                      ),
                    ],
                  ),
                ),
          const SizedBox(height: 3),
          // Delta (中国金融色: ↑ 红涨, ↓ 绿跌；数值保留正负，与二级页一致)
          if (delta != null)
            Text(
              _fmtSignedMomPct(delta, unit: m.isRate ? 'pp' : '%', digits: 1),
              style: LhTypography.mono(
                size: 8.5,
                color: delta >= 0
                    ? DunesColors.resolve(context, LhColors.neg)
                    : DunesColors.resolve(context, LhColors.pos),
                weight: FontWeight.w600,
                letterSpacing: 0.2,
                context: context,
              ),
            )
          else
            Text(
              '—',
              style: LhTypography.mono(
                size: 8.5,
                color: DunesColors.resolve(context, LhColors.mute2),
                weight: FontWeight.w500,
                context: context,
              ),
            ),
        ],
      ),
    );
  }

  // ═════════════════════════════════════════════════════════════════════════
  // Footer Row (Σ / μ)
  // ═════════════════════════════════════════════════════════════════════════

  Widget _buildFooterRow(
    String label,
    String glyph,
    Map<String, double> vals, {
    required bool isTotal,
  }) {
    return SizedBox(
      height: _footerRowH,
      child: Row(
        children: [
          // rank col: 空
          const SizedBox(width: _rankW),
          // name col: label · glyph
          SizedBox(
            width: _nameW,
            child: Padding(
              padding: const EdgeInsets.only(left: 4),
              child: Row(
                crossAxisAlignment: CrossAxisAlignment.center,
                mainAxisAlignment: MainAxisAlignment.start,
                children: [
                  Text(
                    label,
                    style: LhTypography.sans(
                      size: 11,
                      color: DunesColors.resolve(context, LhColors.mute),
                      weight: FontWeight.w600,
                      letterSpacing: 0.2,
                      context: context,
                    ),
                  ),
                  const SizedBox(width: 6),
                  Text(
                    '· $glyph',
                    style: LhTypography.mono(
                      size: 8.5,
                      color: DunesColors.resolve(context, LhColors.mute2),
                      weight: FontWeight.w700,
                      letterSpacing: 1.0,
                      context: context,
                    ),
                  ),
                ],
              ),
            ),
          ),
          // metric cells
          for (final m in widget.metrics)
            _buildFooterCell(m, vals[m.key] ?? 0, isTotal),
        ],
      ),
    );
  }

  Widget _buildFooterCell(_MetaMetricCol m, double v, bool isTotal) {
    final isActive = _sortKey == m.key;
    final w = _metricColWidth(m.key);
    final isNeg = v < 0;
    final valColor = isNeg
        ? DunesColors.resolve(context, LhColors.pos)
        : DunesColors.resolve(context, LhColors.ink2);

    // isRate + isTotal: Σ 无意义,dash
    Widget content;
    if (m.isRate && isTotal) {
      content = Text(
        '—',
        style: LhTypography.mono(
          size: 10,
          color: DunesColors.resolve(context, LhColors.mute2),
          weight: FontWeight.w500,
          context: context,
        ),
      );
    } else if (m.isRate) {
      content = Text(
        '${v.toStringAsFixed(1)}%',
        style: LhTypography.mono(
          size: 10.5,
          color: valColor,
          weight: FontWeight.w600,
          context: context,
        ),
      );
    } else {
      content = RichText(
        text: TextSpan(
          children: [
            if (isNeg)
              TextSpan(
                text: '-',
                style: LhTypography.mono(
                  size: 10.5,
                  color: DunesColors.resolve(context, LhColors.pos),
                  weight: FontWeight.w600,
                  context: context,
                ),
              ),
            TextSpan(
              text: _fmt(v.abs()),
              style: LhTypography.mono(
                size: 10.5,
                color: valColor,
                weight: FontWeight.w600,
                context: context,
              ),
            ),
            TextSpan(
              text: _unit(v.abs()),
              style: LhTypography.mono(
                size: 8,
                color: DunesColors.resolve(context, LhColors.mute),
                weight: FontWeight.w500,
                context: context,
              ),
            ),
          ],
        ),
      );
    }

    return Container(
      width: w,
      alignment: Alignment.centerRight,
      padding: const EdgeInsets.only(right: 8, left: 4),
      color: isActive
          ? DunesColors.resolve(
              context,
              _LhPlum.deep,
              role: DunesColorRole.surface,
            ).withAlpha(10)
          : null,
      child: content,
    );
  }
}

// ── The widget ────────────────────────────────────────────────────────────────
class _TrendChart extends StatefulWidget {
  const _TrendChart({
    super.key,
    required this.labels,
    required this.revenue,
    required this.cost,
    required this.profit,
    required this.rangeLabel,
    required this.title,
    this.scale = const <double>[],
    this.scaleLabel = '规模',
    this.scaleAlt = const <double>[],
    this.scaleAltLabel = '',
    this.periodScale,
    this.periodScaleAlt,
    this.periodScaleDeltaPct,
    this.periodRevenueDeltaPct,
    this.periodCostDeltaPct,
    this.periodScaleAltDeltaPct,
    this.periodCostAltDeltaPct,
    this.scaleForecast,
    this.profitForecast,
    this.onOpenForecastReport,
    this.paceDays,
    this.partialPeriod = false,
    this.showHeader = true,
    this.showLegend = true,
    this.showExtremeLabels = false,
    this.showScrubHint = true,
    this.fitHeight = false,
    this.chartHeight = 112,
    this.onInteractionChanged,
    this.onSelectedIndexChanged,
    this.selectedIndex,
    this.suppressPointMom = false,
    this.lastPointIsPeriod = false,

    /// 当前周期真实合计（与列表行 profit/revenue/totalCost 同口径）。
    /// 走势序列覆盖近 N 期，未选中点时禁止对序列求和冒充「本期合计」。
    this.periodRevenue,
    this.periodCost,
    this.periodProfit,
    this.periodCostAlt,

    /// 本期 vs 上期利润环比（%），与列表行 deltaPct / deltas.profit 同口径。
    /// 禁止用走势首末点代替环比（近 N 期跨度变化 ≠ 环比）。
    this.periodProfitDeltaPct,
    this.revenueLabel = '收入',
    this.costLabel = '成本',
    this.profitLabel = '利润',
    this.costAlt = const <double>[],
    this.costAltLabel = '',
    this.stock = const <double>[],
    this.stockLabel = '银行余额',
    this.periodStock,
    this.periodStockDeltaPct,
    this.unsignedSlots = const <String>{},
    this.valueIsRate = false,
    this.soloKey,
    this.onSoloChanged,
    this.emphasisColor,
    this.showClearSolo = true,
    this.formulaExpression,
    this.grossMarginFormula,
    this.viewportCount = 0,
    this.initialViewEnd,
    this.onViewEndChanged,
    this.historyCount = 0,
    this.historyLoading = false,
    this.historyHasMore = false,
    this.onNeedHistory,
    this.onExpand,
    this.zoomable = false,
    this.legendCompact = false,
    this.legendNamesOnly = false,
    this.hoverSelects = false,
    this.legendTrailing,
    this.candles = false,
    this.initialFromMonth,
    this.initialVisible,
    this.candleUnit = 'day',
    this.statusStamp,
  });

  /// 没点中某天时，图例行最左边写什么（全屏大图传数据时间；null = 「本期合计」）。
  final String? statusStamp;

  /// 打开时一屏看几个点（周 / 月 / 季 / 年线用；日线走 [initialFromMonth]）。
  final int? initialVisible;

  /// K 线粒度：day / week / month / quarter / year —— 决定均线窗口、
  /// 「较昨日 / 较上周…」的说法、统计条的「日均 / 周均…」。
  final String candleUnit;

  /// 主线画成日 K 蜡烛 + 7 / 30 日均线（全屏大图用）。
  final bool candles;

  /// 打开时的视窗从最近一个「这个月的 1 号」看到最新一天（7 = 从 7 月起）。
  /// 用户一拖 / 一缩放就不再自动对齐；历史还没拉到那个月时先看已拉到的全部。
  final int? initialFromMonth;

  /// 图例只留「日期 · 主线读数」一行，不铺指标格（全屏大图用，省高度）。
  final bool legendCompact;

  /// 「本期合计」图例只留指标名（可点切换曲线），数值只给选中那条。
  /// 主 Hero 用：同样的数下面那排格子已经写了一遍，不再重复。
  final bool legendNamesOnly;

  /// 桌面 / 网页：鼠标划过就选中那一格（不用点）。资金与资产的走势用，
  /// 标题旁的日期和左栏三格跟着变。
  final bool hoverSelects;

  /// 图例那一行最右侧挂的控件（全屏大图的缩放 / 收起）。
  final Widget? legendTrailing;

  /// 非空时「本期合计」那一行右侧出一张迷你 K 线卡（只在主 Hero 传）。
  /// 回传卡片在屏幕上的位置，大图从这里「抽」出来。
  final ValueChanged<Rect?>? onExpand;

  /// 全屏大图：双指捏合 / 滚轮 / 触控板缩放一屏点数，底部带全程缩略导航条。
  /// 需配合 [viewportCount] >= 2。
  final bool zoomable;

  /// 股票式视窗：>= 2 时一屏只画这么多个点，横拖平移、长按逐点看。
  /// 0 = 旧行为（整条序列铺满、横拖逐点看）。账本图不传。
  final int viewportCount;
  final double? initialViewEnd;
  final ValueChanged<double>? onViewEndChanged;

  /// 序列最前面有几个点是「往前拉」加载来的历史。
  /// 数值只增加且尾部不变时，图按「往前补了一页」处理：视窗和选中点跟着平移，不重置。
  final int historyCount;
  final bool historyLoading;
  final bool historyHasMore;

  /// 拖到左沿附近时回调，外层去要更早的一页。
  final VoidCallback? onNeedHistory;

  final List<String> labels; // 每个点的完整标签（X 轴 / tooltip）
  final List<double> revenue;
  final List<double> cost;
  final List<double> profit;
  final String rangeLabel;
  final String title;
  final bool showHeader;
  final bool showLegend;

  /// Hero 与下方指标共用同一套干净画布；极值由点选读数承担，不常驻贴纸。
  final bool showExtremeLabels;

  /// 图下「拖动查看每点」。Hero 卡高度紧，关掉以免把图例和下方面板挤出卡片。
  final bool showScrubHint;

  /// true 时折线吃掉图例下方剩余高度（主 Hero 卡）；账本展开保持固定 chartHeight。
  final bool fitHeight;
  final double chartHeight;
  final double? periodRevenue;
  final double? periodCost;
  final double? periodProfit;
  final double? periodCostAlt;
  final double? periodProfitDeltaPct;
  final String revenueLabel;
  final String costLabel;
  final String profitLabel;

  /// 第六条序列（净TA 业务成本）。空 label 表示不画。
  final List<double> costAlt;
  final String costAltLabel;

  /// 第七条：银行余额存量。图例用时点，不把近 N 期加总。
  final List<double> stock;
  final String stockLabel;
  final double? periodStock;
  final double? periodStockDeltaPct;

  /// 这些 slot 的图例金额按绝对值显示（流出 / 成本栏目本身已带方向）。
  final Set<String> unsignedSlots;

  /// 主值按百分比显示（毛利率 / ROI），不走万/亿。
  final bool valueIsRate;

  /// 外层指定只显示哪一条（`lighthouseTrendSeriesKeys`）。账本图不传。
  final String? soloKey;

  /// 图例点选时回传 slot；Hero 用来同步 KPI 选中态。
  final ValueChanged<String?>? onSoloChanged;

  /// 主线颜色。不传时用灯塔紫；账本展开图传上面那格的家族色。
  final Color? emphasisColor;

  /// solo 时是否露出「看全部」。账本展开图不放这颗字。
  final bool showClearSolo;

  /// 点开某一条时，口径式写在图例下面（≡ 科研论文式）。
  final String? formulaExpression;
  final String? grossMarginFormula;

  /// 规模序列（核销 / 销售，跟当前 anchor 口径走）。
  /// 2026-08 运营会："规模跟利润是同样重要的……如果只能显示一个，我更希望显示
  /// 规模。因为规模能推导出利润。" 非空时规模就是这张图的主线。
  final List<double> scale;

  /// 规模的中文口径名（核销规模 / 销售规模），legend 直接显示。
  final String scaleLabel;

  /// 另一口径的规模序列。anchor 是核销时这里是销售，反之亦然。
  /// 两条共用一个 Y 值域，中间填成带 —— 带宽就是「销售了还没核销」的部分。
  final List<double> scaleAlt;

  /// 另一口径规模的中文名；为空表示这条线不画。
  final String scaleAltLabel;

  /// 本期另一口径规模合计。
  final double? periodScaleAlt;

  /// 本期规模合计（与列表行同口径）；缺省时才回退序列求和。
  final double? periodScale;

  /// 本期规模环比（%，带符号），与列表行 deltas[规模字段] 同口径。
  /// 与利润的 periodProfitDeltaPct 一样：由后端下发，前端不自己算窗口。
  final double? periodScaleDeltaPct;

  /// 收入 / 成本合计 / 另一口径规模的本期环比，口径同上。
  final double? periodRevenueDeltaPct;
  final double? periodCostDeltaPct;
  final double? periodScaleAltDeltaPct;
  final double? periodCostAltDeltaPct;

  /// 月化预测（仅「点月 + 当前月 + 规模类」给）。
  /// 非空时画月末预测虚线 + legend 下方的预测条。
  final LighthousePaceForecast? scaleForecast;

  /// 当月「已过天数 / 当月天数」（仅点月 + 当前月）。利润主线用它按同一公式
  /// 外推月末（规模有 [scaleForecast]；利润可能为负，不能借规模那条的非空判断）。
  /// 缺省时回退到 [scaleForecast] 里的天数。
  final ({int elapsed, int total})? paceDays;

  /// 利润的月末预测（v2 数学模型给）。缺省时利润按 [paceDays] 线性外推。
  final LighthousePaceForecast? profitForecast;

  /// 点预测条「报告 ›」/ 连点两下预测点：打开量化报告。参数 = 是不是利润那条。
  final ValueChanged<bool>? onOpenForecastReport;

  /// 本期是不是「还没走完」（当前月/周/日看到一半）。
  ///
  /// 为 true 时禁止用走势末两期兜底算环比 —— 那是「本期截至今天 vs 上期整期」，
  /// 正是 2026-08 运营会当场否掉的口径（GMV 3.1 亿 vs 上月 3.65 亿却显示 ↑9%）。
  /// 后端没下发同期对齐的环比时，宁可显示「—」，也不显示一个错的百分比。
  final bool partialPeriod;

  /// 手指在图上按下/拖动时为 true，抬起为 false；用于外层 sheet 暂时锁滚动。
  final ValueChanged<bool>? onInteractionChanged;

  /// 点选 / 拖动到某一点时回传序号，松手不清；null = 回到整期。
  /// 主 Hero 用它把大数和指标栏整体切到那一天。账本行内图不传。
  ///
  /// 注意：外层拿到序号后**不要**把那一点的值回灌成本图的 period* 入参 ——
  /// didUpdateWidget 会判成「数据换了」而清掉选中点，一点就弹回去。
  final ValueChanged<int?>? onSelectedIndexChanged;

  /// 外层持有的选中点。主 Hero 必须传：否则「回本期」只清大数、图还亮着。
  /// 账本行内图不传，选中态留在图自己手里。
  final int? selectedIndex;

  /// Hero 点选某一期时图例仍算相邻点环比。
  final bool suppressPointMom;

  /// 最后一个点就是「本期」本身（点日视图：末点 = 当天 = 本期）。
  /// 为 true 时点到 / 拖到末点不进入点选态 —— 回传 null，Hero 保持本期，
  /// 不出「回本期」：点当天还要再点一下「回本期」回到同一组数，是多余的一步。
  final bool lastPointIsPeriod;

  @override
  State<_TrendChart> createState() => _TrendChartState();
}

class _TrendChartState extends State<_TrendChart>
    with SingleTickerProviderStateMixin {
  static const double _kChartPadH = 6.0;

  /// 视窗最右那个点的下标（拖动 / 惯性中可带小数）。
  double _viewEnd = 0;
  late final AnimationController _panAnim;
  // v3.8 · 反转层级:行 context 是"这一行的利润趋势",利润上升为 hero deep,
  // 收入/成本降为柔粉描线,视觉上让利润粗线主导.color 顺序不变,只是深浅换位.
  static const Color _cRev = Color(lighthouseRevenueAccentValue);
  static const Color _cCost = Color(lighthouseCostAccentValue);
  static const Color _cProf = Color(lighthouseProfitAccentValue);
  static const Color _cScale = Color(lighthouseScaleAccentValue);
  static const Color _cCostAlt = Color(lighthouseNetTABizCostAccentValue);
  static const Color _cStock = Color(lighthouseStockAccentValue);
  static const List<Color> _kColors = [
    _cRev,
    _cCost,
    _cProf,
    _cScale,
    _cCostAlt,
    _cStock,
  ];

  /// 上下文线的中性阶：同一支墨色（ink2）不同透明度。
  ///
  /// 五条同权彩线画在一张图里必然打架；更要命的是它们各自归一化 —— 纵轴根本
  /// 不是同一个，颜色越强越像在比高低，其实完全不可比。所以规则定成：
  /// **任何时刻画面上最多一个强调色**，其余降成中性、只提供形状上下文。
  /// 想看哪条就点图例，那条变成强调色（solo 已有的交互）。
  // 六档 alpha 从 0x6B 到 0x99 —— 那是一条不编码任何东西的假梯度：
  // 深浅既不表示大小、也不表示优先级，只是让人以为它表示了什么。
  // 上下文线之间本来就不可比，就该长得一模一样。
  static const List<Color> _kContextColors = [
    Color(0x8C5A5C56),
    Color(0x8C5A5C56),
    Color(0x8C5A5C56),
    Color(0x8C5A5C56),
    Color(0x8C5A5C56),
    Color(0x8C5A5C56),
  ];

  /// series key → 颜色槽位。scale / scaleAlt 同属规模族，共用一个槽。
  static int _colorSlotFor(int seriesIndex) => switch (seriesIndex) {
    4 => 3,
    5 => 4,
    6 => 5,
    _ => seriesIndex,
  };

  Color get _emphasisColor => widget.emphasisColor ?? _kAccent;

  /// 强调线的颜色 —— 全页统一走灯塔紫，不跟着序列的语义色跑。
  ///
  /// v15 · 之前强调线用「这条线自己的语义色」：点利润整张图变橙、点收入变
  /// 青、点成本变棕。同一张图每点一次换一次主色，读者每次都要重新找眼睛的
  /// 落点，而且那几个语义色本来就不是为大面积线条挑的。
  /// 语义色留在指标格和图例文字里做身份；图上「被强调」只有一种表达：紫。
  /// 银行余额是唯一例外 —— 存量线，「现金 = 绿」是通识，保留它自己的色。
  static const Color _kAccent = Color(lighthouseScaleAccentValue);

  Color _accentForSlot(int slot) => slot == 5 ? _kColors[5] : _emphasisColor;

  /// 绘图用色：强调的那条走紫，其余一律走中性阶。
  ///
  /// solo 与非 solo 是同一条规则，只是「谁被强调」的判据不同 —— 所以这里
  /// 不再分支，统一问 [_heroIndexFor]。
  List<Color> get _paintColors {
    final emphasis = _colorSlotFor(_heroIndexFor(_visibleFlags));
    return [
      for (var k = 0; k < _kColors.length; k++)
        k == emphasis
            ? _accentForSlot(k)
            : (k == 5 ? _kColors[5] : _kContextColors[k]),
    ];
  }

  /// 强调线的序列下标：solo 时是被点的那条，否则按固定优先级挑。
  int _heroIndexFor(List<bool> flags) {
    final solo = _soloKey;
    if (solo != null) {
      final i = lighthouseTrendSeriesKeys.indexOf(solo);
      if (i >= 0 && i < flags.length && flags[i]) return i;
    }
    return lighthouseTrendHeroIndex(flags);
  }

  /// 图例色块跟线同一套规则：强调那条是紫，其余是中性点。
  /// 入参 accent 只在 key 不在序列表里时兜底 —— 颜色由槽位决定，不由调用方决定，
  /// 否则图例和线会各说各的。
  Color _legendAccent(String key, Color accent) {
    final i = lighthouseTrendSeriesKeys.indexOf(key);
    if (i < 0) return accent;
    final slot = _colorSlotFor(i);
    final heroIdx = _heroIndexFor(_visibleFlags);
    final emphasis = _colorSlotFor(heroIdx);
    if (slot == emphasis) {
      // 亏绿赚红：利润线被裁成红绿两段时，图例色块跟本期那一点走。
      // 账本展开图锁了家族色时，图例跟线一样，不改涂红绿。
      // v18 · 利润一律赚红亏绿，账本展开图也跟线一起变。
      final sign = _signSplitEndColor(heroIdx);
      if (sign != null) return sign;
      return _accentForSlot(slot);
    }
    if (slot == 5) return _kColors[5];
    return _kContextColors[slot];
  }

  /// 当月外推倍数 = 当月天数 ÷ 已过天数；非点月 / 非当前月为 null。
  ({int elapsed, int total})? get _paceDaysResolved {
    final d = widget.paceDays;
    if (d != null) return d;
    final f = widget.scaleForecast;
    if (f == null) return null;
    return (elapsed: f.elapsedDays, total: f.totalDays);
  }

  double? get _paceMultiplier {
    final d = _paceDaysResolved;
    if (d == null || d.elapsed <= 0 || d.elapsed >= d.total) return null;
    return d.total / d.elapsed;
  }

  /// 图例下方预测条要讲哪一条：主线是规模 → 规模预测；主线是利润 →
  /// 同一公式外推利润。其余指标（收入 / 成本 / 比率）不出预测条。
  ({LighthousePaceForecast f, bool profit, double? prev, String? prevLabel})?
  get _stripForecast {
    final vis = _visibleFlags;
    final hero = _heroIndexFor(vis);
    String? labelAt(int i) =>
        i >= 0 && i < _pointLabels.length ? _pointLabels[i] : null;
    final base = widget.scaleForecast;
    if (base != null && hero == 3 && vis[3] && _hasScale) {
      final sc = _series.scale;
      return (
        f: base,
        profit: false,
        prev: sc.length >= 2 ? sc[sc.length - 2] : null,
        prevLabel: labelAt(sc.length - 2),
      );
    }
    final pf = widget.profitForecast;
    if (pf != null &&
        widget.partialPeriod &&
        hero == lighthouseTrendProfitIndex &&
        vis[2] &&
        _hasProf) {
      final p = _series.profit;
      return (
        f: pf,
        profit: true,
        prev: p.length >= 2 ? p[p.length - 2] : null,
        prevLabel: labelAt(p.length - 2),
      );
    }
    final d = _paceDaysResolved;
    if (d != null &&
        widget.partialPeriod &&
        hero == lighthouseTrendProfitIndex &&
        vis[2] &&
        _hasProf &&
        d.elapsed > 0 &&
        d.elapsed < d.total) {
      final p = _series.profit;
      if (p.isEmpty || !p.last.isFinite) return null;
      final a = p.last;
      return (
        f: LighthousePaceForecast(
          actual: a,
          forecast: a / d.elapsed * d.total,
          elapsedDays: d.elapsed,
          totalDays: d.total,
        ),
        profit: true,
        prev: p.length >= 2 ? p[p.length - 2] : null,
        prevLabel: labelAt(p.length - 2),
      );
    }
    return null;
  }

  /// 利润图例跟随本期盈亏；全赚、全亏、跨零都用同一语义色。
  Color? _signSplitEndColor(int heroIndex) {
    if (heroIndex != lighthouseTrendProfitIndex) return null;
    final spec = _trendPaintSpec(
      series: _series,
      bounds: _bounds,
      colors: _paintColors,
      index: heroIndex,
    );
    if (spec.pts.isEmpty) return null;
    final selected = _selectedIndex;
    final index =
        selected != null && selected >= 0 && selected < spec.pts.length
        ? selected
        : spec.pts.length - 1;
    return lighthouseTrendValueEarns(spec.pts[index])
        ? DunesColors.resolve(context, LhColors.neg)
        : DunesColors.resolve(context, LhColors.pos);
  }

  int? _selectedIndex;

  /// 当月那一列的两个点被点中哪个：'actual' = 已发生，'forecast' = 月末预测。
  String? _paceTap;

  /// 非空时只画这一条（`lighthouseTrendSeriesKeys`）。再点同一项或「全部」恢复。
  String? _soloKey;
  late _TrendSeries _series;
  late _TrendBounds _bounds;

  /// 画图用的序列 / 值域：全屏大图削过峰（见 [_tameTrendSeries]），其余就是原值。
  /// 读数（图例、游标）一律读 [_series]。
  late _TrendSeries _paintSeries;
  late _TrendBounds _paintBounds;

  /// 削峰参数（下标同 lighthouseTrendSeriesKeys），纵轴刻度反算真值用。
  Map<int, _TameParams> _tameParams = const {};

  /// 每个点的（月, 日）；解析不了的是 null。月初竖线、「7月」横轴标签用。
  List<({int month, int day})?> _labelMD = const [];

  /// 用户动过视窗（拖 / 缩放 / 点缩略条）之后，不再自动对齐到 initialFromMonth。
  bool _viewTouched = false;

  static final RegExp _kMonthDayRe = RegExp(r'(\d{1,2})\D(\d{1,2})\D*$');

  static ({int month, int day})? _parseMonthDay(String raw) {
    final m = _kMonthDayRe.firstMatch(raw.trim());
    if (m == null) return null;
    final month = int.tryParse(m.group(1)!);
    final day = int.tryParse(m.group(2)!);
    if (month == null || day == null) return null;
    if (month < 1 || month > 12 || day < 1 || day > 31) return null;
    return (month: month, day: day);
  }

  /// 每个点的年份：标签只有「月.日」，从最新一天（今年）往回推，
  /// 月份往回走时突然变大（1 月 → 12 月）就是跨年了。
  List<int?> _labelYears = const [];

  static List<int?> _inferYears(
    List<({int month, int day})?> md,
    int latestYear,
  ) {
    final out = List<int?>.filled(md.length, null);
    var year = latestYear;
    int? laterMonth;
    for (var i = md.length - 1; i >= 0; i--) {
      final d = md[i];
      if (d == null) continue;
      if (laterMonth != null && d.month > laterMonth) year--;
      out[i] = year;
      laterMonth = d.month;
    }
    return out;
  }

  /// 全屏大图里点中某天：写全「2026年9月16日」（不带时分）。
  /// 周 / 月 / 季 / 年线或解析不出日期时，沿用原标签。
  String _fullDateLabel(int i) {
    if (widget.candleUnit == 'day' &&
        i >= 0 &&
        i < _labelMD.length &&
        i < _labelYears.length) {
      final d = _labelMD[i];
      final y = _labelYears[i];
      if (d != null && y != null) return '$y年${d.month}月${d.day}日';
    }
    return i >= 0 && i < _pointLabels.length ? _pointLabels[i] : '';
  }

  bool _isMonthStart(int i) =>
      widget.candleUnit == 'day' &&
      i >= 0 &&
      i < _labelMD.length &&
      _labelMD[i]?.day == 1;

  /// K 线左侧纵轴栏宽：刻度数、现价牌、光标读数都坐在这一栏里，不压蜡烛。
  static const double _kCandleAxisGutter = 36;

  /// 图例里每条线一颗小眼睛：关掉就不画。
  bool _showActual = true;
  bool _showTrend = true;
  bool _showNxFast = true;
  bool _showNxSlow = true;
  bool get _showNx => _showNxFast || _showNxSlow;

  /// 默认挂着的「最新一天」明细牌被点掉了（本次打开内不再自动出现）。
  bool _hideDefaultCard = false;

  /// NX 两条带各自的两根 EMA：快带 (fa, fb)，慢带 (sa, sb)，随粒度换。
  ({int fa, int fb, int sa, int sb}) get _nxWindows =>
      switch (widget.candleUnit) {
        'week' => (fa: 4, fb: 8, sa: 12, sb: 24),
        'month' => (fa: 3, fb: 6, sa: 12, sb: 24),
        'quarter' => (fa: 2, fb: 4, sa: 4, sb: 8),
        'year' => (fa: 2, fb: 3, sa: 3, sb: 5),
        _ => (fa: 10, fb: 20, sa: 30, sb: 60),
      };

  /// K 线各粒度的说法与均线窗口。
  ({
    int fast,
    int slow,
    String fastLabel,
    String slowLabel,
    String prevLatest,
    String prevAny,
    String current,
    String avg,
  })
  get _unit => switch (widget.candleUnit) {
    'week' => (
      fast: 4,
      slow: 12,
      fastLabel: '4周均线',
      slowLabel: '12周均线',
      prevLatest: '上周',
      prevAny: '前一周',
      current: '本周',
      avg: '周均',
    ),
    'month' => (
      fast: 3,
      slow: 12,
      fastLabel: '3个月均线',
      slowLabel: '12个月均线',
      prevLatest: '上月',
      prevAny: '前一月',
      current: '本月',
      avg: '月均',
    ),
    'quarter' => (
      fast: 2,
      slow: 4,
      fastLabel: '2季均线',
      slowLabel: '4季均线',
      prevLatest: '上季',
      prevAny: '前一季',
      current: '本季',
      avg: '季均',
    ),
    'year' => (
      fast: 2,
      slow: 3,
      fastLabel: '2年均线',
      slowLabel: '3年均线',
      prevLatest: '去年',
      prevAny: '前一年',
      current: '今年',
      avg: '年均',
    ),
    _ => (
      fast: 7,
      slow: 30,
      fastLabel: '7日均线',
      slowLabel: '30日均线',
      prevLatest: '昨日',
      prevAny: '前一日',
      current: '今日',
      avg: '日均',
    ),
  };

  /// 全屏大图横轴：月初写「7月」，其余沿用日标签。
  String _zoomLabel(int i) {
    if (_isMonthStart(i)) return '${_labelMD[i]!.month}月';
    return i >= 0 && i < _xLabels.length ? _xLabels[i] : '';
  }

  /// 把视窗对到「最近一个 initialFromMonth 月的第一天 → 最新一天」。
  /// 只改字段不 setState —— initState / didUpdateWidget 里调，紧接着就会 build。
  void _applyInitialWindow() {
    if (_viewTouched || !widget.zoomable || !_viewportMode) return;
    final n = _n;
    if (n < 2) return;
    final month = widget.initialFromMonth;
    if (month == null) {
      // 周 / 月 / 季 / 年线：一屏看最近 initialVisible 个，不够就全看。
      final v = widget.initialVisible;
      if (v == null) return;
      _fitAll = false;
      _zoomVisible = v.clamp(2, n);
      _viewEnd = (n - 1).toDouble();
      return;
    }
    // 从最新往回找到最近的那个月，再往回走到它的第一天。
    var i = math.min(n, _labelMD.length) - 1;
    while (i >= 0 && _labelMD[i]?.month != month) {
      i--;
    }
    var start = 0; // 还没拉到那个月：先看已拉到的全部。
    if (i >= 0) {
      start = i;
      while (start - 1 >= 0 && _labelMD[start - 1]?.month == month) {
        start--;
      }
    }
    _fitAll = false;
    _zoomVisible = (n - start).clamp(2, n);
    _viewEnd = (n - 1).toDouble();
  }

  late List<String> _pointLabels;
  late List<String> _xLabels;
  late List<int> _xAnchors;
  double _totRev = 0, _totCost = 0, _totProf = 0, _totScale = 0;
  double _totScaleAlt = 0;
  double _totCostAlt = 0;
  double _totStock = 0;
  // v3.9 · 每条序列是否"真的有数据"(非空 & 非全 0). 后端有时只下发 profit,
  //         revenue/cost 缺 → 之前 pad(0) 后 painter 恒画 3 条线, legend 恒
  //         3 chip, 视觉上"只有一条动". 现在改成: 缺的序列 legend 不显示,
  //         painter 不画 —— 直接呈现"当前维度只有利润可看".
  bool _hasRev = false;
  bool _hasCost = false;
  bool _hasProf = false;
  bool _hasScale = false;
  bool _hasScaleAlt = false;
  bool _hasCostAlt = false;
  bool _hasStock = false;
  int get _visibleCount =>
      (_hasRev ? 1 : 0) +
      (_hasCost ? 1 : 0) +
      (_hasProf ? 1 : 0) +
      (_hasCostAlt ? 1 : 0);

  List<bool> get _baseFlags => lighthouseTrendBaseFlags(
    hasRevenue: _hasRev,
    hasCost: _hasCost,
    hasProfit: _hasProf,
    hasScale: _hasScale,
    hasScaleAlt: _hasScaleAlt,
    hasCostAlt: _hasCostAlt,
    hasStock: _hasStock,
  );

  /// 核销 / 销售是否共用真轴 —— 只有这一对才允许同时画两条。
  bool get _pairsScale => lighthouseTrendShareScaleRange(
    scaleLabel: widget.scaleLabel,
    scaleAltLabel: widget.scaleAltLabel,
  );

  List<bool> get _visibleFlags => lighthouseTrendVisibleFlags(
    hasRevenue: _hasRev,
    hasCost: _hasCost,
    hasProfit: _hasProf,
    hasScale: _hasScale,
    hasScaleAlt: _hasScaleAlt,
    hasCostAlt: _hasCostAlt,
    hasStock: _hasStock,
    soloKey: _soloKey,
    pairScale: _pairsScale,
  );

  /// 图例上这一条现在画没画在图里 —— 决定要不要给它色块。
  bool _isDrawnSeries(String key) {
    final i = lighthouseTrendSeriesKeys.indexOf(key);
    if (i < 0) return false;
    final vis = _visibleFlags;
    return i < vis.length && vis[i];
  }

  void _toggleSolo(String key) {
    final next = lighthouseTrendSoloAfterTap(_soloKey, key);
    final i = lighthouseTrendSeriesKeys.indexOf(key);
    if (i < 0 || !_baseFlags[i]) return;
    LighthouseFeedback.instance.play(LighthouseFeedbackKind.select);
    setState(() => _soloKey = next);
    widget.onSoloChanged?.call(next);
  }

  void _clearSolo() {
    if (_soloKey == null) return;
    LighthouseFeedback.instance.play(LighthouseFeedbackKind.collapse);
    setState(() => _soloKey = null);
    widget.onSoloChanged?.call(null);
  }

  int get _n => _series.profit.length;

  bool _legendNegative(String slot, bool isNeg) =>
      widget.unsignedSlots.contains(slot) ? false : isNeg;

  String _fmtHeroAbs(double v) =>
      widget.valueIsRate ? v.toStringAsFixed(2) : _fmtMoney(v);

  String _fmtHeroUnit(double v) => widget.valueIsRate ? '%' : _unitMoney(v);

  String _fmtHeroShort(double v) =>
      widget.valueIsRate ? '${v.toStringAsFixed(1)}%' : _fmtChartShort(v);

  @override
  void initState() {
    super.initState();
    _panAnim = AnimationController.unbounded(vsync: this)
      ..addListener(_onPanAnimTick);
    _soloKey = widget.soloKey;
    if (widget.onSelectedIndexChanged != null) {
      _selectedIndex = widget.selectedIndex;
    }
    _recompute();
    _viewEnd = widget.initialViewEnd == null
        ? math.max(0, _n - 1).toDouble()
        : lighthouseTrendClampViewEnd(
            viewEnd: widget.initialViewEnd!,
            count: _n,
            visible: math.max(2, widget.viewportCount),
          );
    _applyInitialWindow();
  }

  @override
  void dispose() {
    _panAnim.dispose();
    super.dispose();
  }

  /// 新数据 = 旧数据前面补了 [k] 个点（往前拉加载了一页历史），其余一概没变。
  bool _isHistoryPrepend(_TrendChart old, int k) {
    if (k <= 0) return false;
    bool tail(List<double> now, List<double> was) {
      if (now.isEmpty && was.isEmpty) return true;
      return now.length == was.length + k && listEquals(now.sublist(k), was);
    }

    return tail(widget.profit, old.profit) &&
        tail(widget.revenue, old.revenue) &&
        tail(widget.cost, old.cost) &&
        tail(widget.costAlt, old.costAlt) &&
        tail(widget.scale, old.scale) &&
        tail(widget.scaleAlt, old.scaleAlt) &&
        tail(widget.stock, old.stock) &&
        widget.labels.length == old.labels.length + k &&
        listEquals(widget.labels.sublist(k), old.labels) &&
        old.periodScaleAlt == widget.periodScaleAlt &&
        old.periodStock == widget.periodStock &&
        old.periodScaleDeltaPct == widget.periodScaleDeltaPct &&
        old.periodRevenueDeltaPct == widget.periodRevenueDeltaPct &&
        old.periodCostDeltaPct == widget.periodCostDeltaPct &&
        old.periodScaleAltDeltaPct == widget.periodScaleAltDeltaPct &&
        old.periodCostAltDeltaPct == widget.periodCostAltDeltaPct &&
        old.periodStockDeltaPct == widget.periodStockDeltaPct &&
        old.partialPeriod == widget.partialPeriod &&
        old.periodRevenue == widget.periodRevenue &&
        old.periodCost == widget.periodCost &&
        old.periodProfit == widget.periodProfit &&
        old.periodCostAlt == widget.periodCostAlt &&
        old.periodScale == widget.periodScale &&
        old.scaleForecast?.forecast == widget.scaleForecast?.forecast &&
        old.periodProfitDeltaPct == widget.periodProfitDeltaPct;
  }

  @override
  @override
  void reassemble() {
    super.reassemble();
    _recompute();
  }

  void didUpdateWidget(_TrendChart old) {
    super.didUpdateWidget(old);
    final prepended = widget.historyCount - old.historyCount;
    if (_isHistoryPrepend(old, prepended)) {
      // 往前补了一页：视窗和选中点整体右移 k 格，画面停在原处不跳。
      if (_panAnim.isAnimating) _panAnim.stop();
      _recompute();
      _viewEnd = lighthouseTrendClampViewEnd(
        viewEnd: _viewEnd + prepended,
        count: _n,
        visible: math.max(2, _visible),
      );
      _applyInitialWindow();
      widget.onViewEndChanged?.call(_viewEnd);
      if (widget.onSelectedIndexChanged != null) {
        _selectedIndex = widget.selectedIndex;
      } else if (_selectedIndex != null) {
        _selectedIndex = _selectedIndex! + prepended;
      }
      return;
    }
    final dataChanged =
        !listEquals(old.profit, widget.profit) ||
        !listEquals(old.revenue, widget.revenue) ||
        !listEquals(old.cost, widget.cost) ||
        !listEquals(old.costAlt, widget.costAlt) ||
        !listEquals(old.scale, widget.scale) ||
        !listEquals(old.scaleAlt, widget.scaleAlt) ||
        !listEquals(old.stock, widget.stock) ||
        old.periodScaleAlt != widget.periodScaleAlt ||
        old.periodStock != widget.periodStock ||
        !listEquals(old.labels, widget.labels) ||
        old.periodScaleDeltaPct != widget.periodScaleDeltaPct ||
        old.periodRevenueDeltaPct != widget.periodRevenueDeltaPct ||
        old.periodCostDeltaPct != widget.periodCostDeltaPct ||
        old.periodScaleAltDeltaPct != widget.periodScaleAltDeltaPct ||
        old.periodCostAltDeltaPct != widget.periodCostAltDeltaPct ||
        old.periodStockDeltaPct != widget.periodStockDeltaPct ||
        old.partialPeriod != widget.partialPeriod ||
        old.periodRevenue != widget.periodRevenue ||
        old.periodCost != widget.periodCost ||
        old.periodProfit != widget.periodProfit ||
        old.periodCostAlt != widget.periodCostAlt ||
        old.periodScale != widget.periodScale ||
        old.scaleForecast?.forecast != widget.scaleForecast?.forecast ||
        old.periodProfitDeltaPct != widget.periodProfitDeltaPct;
    if (dataChanged) {
      _recompute();
      _resetViewport();
      _applyInitialWindow();
      if (_selectedIndex != null) {
        _selectedIndex = null;
        final notify = widget.onSelectedIndexChanged;
        // didUpdateWidget 跑在父级 build 期间，直接回调会撞上
        // 「setState() called during build」；推到下一帧。
        if (notify != null) {
          WidgetsBinding.instance.addPostFrameCallback((_) {
            if (mounted) notify(null);
          });
        }
      }
    } else if (widget.onSelectedIndexChanged != null &&
        widget.selectedIndex != _selectedIndex) {
      // 外层「回本期」清掉序号时，图必须跟着灭高亮。
      _selectedIndex = widget.selectedIndex;
    }
    if (dataChanged || old.soloKey != widget.soloKey) {
      _applyExternalSolo(widget.soloKey);
    }
  }

  void _applyExternalSolo(String? key) {
    if (key == null || key.isEmpty) {
      _soloKey = null;
      return;
    }
    final i = lighthouseTrendSeriesKeys.indexOf(key);
    _soloKey = (i >= 0 && _baseFlags[i]) ? key : null;
  }

  static bool _seriesHasData(List<double> l, {double? period}) {
    if (l.isEmpty) return false;
    // 明确下发的本期 0 也是数据，不能把整条 0 线和读数隐藏。
    if (period != null) return true;
    for (final v in l) {
      if (v.abs() > 1e-9) return true;
    }
    return false;
  }

  void _recompute() {
    // Availability 判断：空序列不可用；全 0 且有本期值时仍须显示。
    _hasRev = _seriesHasData(widget.revenue, period: widget.periodRevenue);
    _hasCost = _seriesHasData(widget.cost, period: widget.periodCost);
    _hasProf = _seriesHasData(widget.profit, period: widget.periodProfit);
    _hasScale = _seriesHasData(widget.scale, period: widget.periodScale);
    _hasScaleAlt =
        widget.scaleAltLabel.isNotEmpty &&
        _seriesHasData(widget.scaleAlt, period: widget.periodScaleAlt);
    _hasCostAlt =
        widget.costAltLabel.isNotEmpty &&
        _seriesHasData(widget.costAlt, period: widget.periodCostAlt);
    _hasStock =
        widget.stockLabel.isNotEmpty &&
        _seriesHasData(widget.stock, period: widget.periodStock);

    final n = [
      widget.revenue.length,
      widget.cost.length,
      widget.profit.length,
      widget.scale.length,
      widget.scaleAlt.length,
      widget.costAlt.length,
      widget.stock.length,
    ].fold<int>(0, math.max);
    List<double> pad(List<double> l) =>
        l.length == n ? l : [...l, ...List<double>.filled(n - l.length, 0.0)];
    _series = _TrendSeries(
      revenue: pad(widget.revenue),
      cost: pad(widget.cost),
      profit: pad(widget.profit),
      // 没数据的规模序列留空，别喂 pad 出来的全 0 —— 它会把共用值域拉到 0，
      // 两条规模线就被压扁了。
      scale: _hasScale ? pad(widget.scale) : const <double>[],
      scaleAlt: _hasScaleAlt ? pad(widget.scaleAlt) : const <double>[],
      costAlt: _hasCostAlt ? pad(widget.costAlt) : const <double>[],
      stock: _hasStock ? pad(widget.stock) : const <double>[],
    );
    // 预测虚线要画得进画布 —— 把预测值一并纳入规模值域。
    _bounds = _computeBounds(
      _series,
      scaleForecast: _hasScale ? widget.scaleForecast?.forecast : null,
      shareScaleRange: lighthouseTrendShareScaleRange(
        scaleLabel: widget.scaleLabel,
        scaleAltLabel: widget.scaleAltLabel,
      ),
    );
    _labelMD = [for (final l in widget.labels) _parseMonthDay(l)];
    _labelYears = _inferYears(_labelMD, DateTime.now().year);
    // K 线不再削峰（会把 3 万和 22 万的顶压得差不多高）：画真值，
    // 极端日交给 _robustCandleRange 裁在图沿。
    if (widget.zoomable && !widget.candles) {
      _tameParams = _tameTrendParams(_series);
      _paintSeries = _tameTrendSeries(_series);
      _paintBounds = _computeBounds(
        _paintSeries,
        scaleForecast: _hasScale ? widget.scaleForecast?.forecast : null,
        shareScaleRange: lighthouseTrendShareScaleRange(
          scaleLabel: widget.scaleLabel,
          scaleAltLabel: widget.scaleAltLabel,
        ),
      );
    } else {
      _tameParams = const {};
      _paintSeries = _series;
      _paintBounds = _bounds;
    }
    _pointLabels = widget.labels;
    // 「本期合计」优先用行上真实周期值；仅缺省时才回退序列求和（兼容旧调用）。
    _totRev =
        widget.periodRevenue ?? _series.revenue.fold(0.0, (a, b) => a + b);
    _totCost = widget.periodCost ?? _series.cost.fold(0.0, (a, b) => a + b);
    _totProf = widget.periodProfit ?? _series.profit.fold(0.0, (a, b) => a + b);
    _totScale = widget.periodScale ?? _series.scale.fold(0.0, (a, b) => a + b);
    _totScaleAlt =
        widget.periodScaleAlt ?? _series.scaleAlt.fold(0.0, (a, b) => a + b);
    _totCostAlt =
        widget.periodCostAlt ?? _series.costAlt.fold(0.0, (a, b) => a + b);
    _totStock = lighthouseTrendStockLegendValue(
      series: _series.stock,
      periodStock: widget.periodStock,
    );
    final (xs, anchors) = lighthouseTrendXAxisLabels(widget.labels, n);
    _xLabels = xs;
    _xAnchors = anchors;
    if (_soloKey != null) {
      final i = lighthouseTrendSeriesKeys.indexOf(_soloKey!);
      if (i < 0 || !_baseFlags[i]) _soloKey = null;
    }
  }

  void _setSelectionFromX(double localX, double widthPx) {
    if (_paceTap != null) setState(() => _paceTap = null);
    final n = _n;
    final usable = widthPx - _kChartPadH * 2;
    if (usable <= 0 || n <= 0) return;
    final relX = (localX - _kChartPadH).clamp(0.0, usable);
    final int raw;
    if (_windowed) {
      raw = lighthouseTrendIndexAtX(
        x: localX,
        padH: _kChartPadH,
        step: _stepFor(widthPx),
        viewStart: _viewStart,
        visible: _visible,
        count: n,
      );
    } else {
      raw = n <= 1 ? 0 : ((relX / usable) * (n - 1)).round().clamp(0, n - 1);
    }
    final int? i = widget.lastPointIsPeriod && raw == n - 1 ? null : raw;
    if (_selectedIndex != i) {
      setState(() => _selectedIndex = i);
      widget.onSelectedIndexChanged?.call(i);
    }
  }

  void _clearSelection() {
    if (_paceTap != null) setState(() => _paceTap = null);
    if (_selectedIndex != null) {
      setState(() => _selectedIndex = null);
      widget.onSelectedIndexChanged?.call(null);
    }
  }

  void _notifyInteraction(bool active) {
    widget.onInteractionChanged?.call(active);
  }

  /// v18 · 当月那一列被点中时的读数牌：贴在被点的点左边。
  Widget _paceTag({
    required ({double x, double actY, double fcY, double actual, double fc})
    hit,
    required bool forecast,
    required double width,
    required double height,
  }) {
    final d = _paceDaysResolved;
    final v = forecast ? hit.fc : hit.actual;
    final y = forecast ? hit.fcY : hit.actY;
    String money(double x) =>
        '${x < 0 ? '−' : ''}${_fmtMoney(x.abs())}${_unitMoney(x.abs())}';
    final profitHero =
        _heroIndexFor(_visibleFlags) == lighthouseTrendProfitIndex;
    final c = profitHero
        ? (v >= 0
              ? DunesColors.resolve(context, LhColors.neg)
              : DunesColors.resolve(context, LhColors.pos))
        : lighthouseTrendEmphasisInk(_emphasisColor);
    final title = forecast ? (profitHero ? '月末预测利润' : '月末预测') : '已发生';
    final String sub;
    if (d == null) {
      sub = '';
    } else if (forecast) {
      final band = _stripForecast?.f;
      sub = band?.lo != null && band?.hi != null
          ? '80%近似区间 ${money(band!.lo!)}–${money(band!.hi!)}'
                '${widget.onOpenForecastReport != null ? ' · 再点看报告' : ''}'
          : '按日均外推 · ${money(hit.fc - hit.actual)} 待完成';
    } else {
      sub =
          '截至 ${d.elapsed}/${d.total} 天 · 日均 '
          '${money(d.elapsed <= 0 ? 0 : hit.actual / d.elapsed)}';
    }
    const tagW = 124.0;
    const tagH = 34.0;
    final left = (hit.x - tagW - 10).clamp(0.0, math.max(0.0, width - tagW));
    final top = (y - tagH / 2).clamp(0.0, math.max(0.0, height - tagH));
    return Positioned(
      left: left.toDouble(),
      top: top.toDouble(),
      width: tagW,
      child: IgnorePointer(
        child: Container(
          padding: const EdgeInsets.fromLTRB(7, 4, 7, 4),
          decoration: BoxDecoration(
            color: DunesColors.resolve(
              context,
              Colors.white,
              role: DunesColorRole.surface,
            ).withAlpha(248),
            borderRadius: BorderRadius.circular(6),
            border: Border.all(color: c.withAlpha(60), width: 0.6),
            boxShadow: [
              BoxShadow(
                color: _LhPlum.deep.withAlpha(30),
                blurRadius: 8,
                offset: const Offset(0, 2),
              ),
            ],
          ),
          child: Column(
            crossAxisAlignment: CrossAxisAlignment.start,
            mainAxisSize: MainAxisSize.min,
            children: [
              Row(
                children: [
                  Text(
                    title,
                    style: LhTypography.mono(
                      size: 7.5,
                      color: DunesColors.resolve(context, LhColors.mute2),
                      weight: FontWeight.w700,
                      letterSpacing: 0.4,
                      context: context,
                    ),
                  ),
                  const Spacer(),
                  Text(
                    money(v),
                    style: LhTypography.sans(
                      size: 11,
                      color: c,
                      weight: FontWeight.w800,
                      letterSpacing: -0.1,
                      context: context,
                    ),
                  ),
                ],
              ),
              if (sub.isNotEmpty)
                Text(
                  sub,
                  maxLines: 1,
                  overflow: TextOverflow.ellipsis,
                  style: LhTypography.mono(
                    size: 7,
                    color: DunesColors.resolve(context, LhColors.mute2),
                    weight: FontWeight.w500,
                    letterSpacing: 0.2,
                    context: context,
                  ),
                ),
            ],
          ),
        ),
      ),
    );
  }

