  String _laneLabelFor(int seriesIndex) => switch (seriesIndex) {
    0 => widget.revenueLabel,
    1 => widget.costLabel,
    2 => widget.profitLabel,
    3 => widget.scaleLabel,
    4 => widget.scaleAltLabel,
    5 => widget.costAltLabel,
    _ => widget.stockLabel,
  };

  // ── 视窗（股票式往前拉）────────────────────────────────────────────────
  //   viewportCount >= 2 时进入视窗模式：一屏固定画 viewportCount 个点，
  //   单指横拖平移、松手带惯性，拖到左沿附近回调 onNeedHistory 往前补一页；
  //   点一下选中某点，长按后拖动逐点扫（十字光标）。
  //   视窗之外的点不画、不参与 Y 值域 —— 纵轴跟着看到的那一段自适应。

  bool get _viewportMode => widget.viewportCount >= 2;

  /// 缩放后的一屏点数（null = 沿用 viewportCount）。只有 [zoomable] 会改它。
  int? _zoomVisible;

  /// 「看全部」：一屏点数跟着 _n 走，往前补了历史也照样整条铺满。
  bool _fitAll = false;

  int get _visible =>
      _fitAll ? math.max(2, _n) : (_zoomVisible ?? widget.viewportCount);

  /// 点数多于一屏：真的需要平移。
  bool get _windowed => _viewportMode && _n > _visible;
  double get _viewStart => _windowed ? _viewEnd - (_visible - 1) : 0.0;
  double _stepFor(double w) => (w - _kChartPadH * 2) / (_visible - 1);

  // ── 缩放（全屏大图）─────────────────────────────────────────────────────
  //   一屏点数 = 缩放级别：捏合 / 滚轮 / 触控板 / 顶栏按钮都只改这一个数，
  //   锚点下面那一天缩放前后停在同一个横坐标上，和看 K 线一样。
  static const int _kZoomMinVisible = 7;
  final Map<int, Offset> _zoomPointers = <int, Offset>{};
  double? _pinchStartDist;
  int _pinchStartVisible = 0;
  int _panZoomStartVisible = 0;
  bool get _pinching => _pinchStartDist != null;

  int get _zoomCurrent => math.min(math.max(2, _visible), math.max(2, _n));

  double _fracAt(double x, double w) {
    final usable = w - _kChartPadH * 2;
    if (usable <= 0) return 1.0;
    return ((x - _kChartPadH) / usable).clamp(0.0, 1.0).toDouble();
  }

  /// 一屏改看 [next] 个点；[focalFrac] 是锚点在画布上的横向比例（0 左沿 / 1 右沿）。
  /// 不给锚点时：停在最新就贴右沿缩放，否则绕中间缩放。
  void _zoomTo(int next, {double? focalFrac}) {
    if (!widget.zoomable || !_viewportMode) return;
    final n = _n;
    if (n < 2) return;
    final minV = math.min(n, _kZoomMinVisible);
    final target = next.clamp(math.max(2, minV), n).toInt();
    final cur = _zoomCurrent;
    if (target == cur && !_fitAll) return;
    if (_panAnim.isAnimating) _panAnim.stop();
    final frac = (focalFrac ?? (_viewEnd >= n - 1 - 0.5 ? 1.0 : 0.5))
        .clamp(0.0, 1.0)
        .toDouble();
    _viewTouched = true;
    final start = _windowed ? _viewStart : 0.0;
    final focus = start + frac * (cur - 1);
    final nextStart = focus - frac * (target - 1);
    setState(() {
      _fitAll = false;
      _zoomVisible = target;
      _viewEnd = lighthouseTrendClampViewEnd(
        viewEnd: nextStart + target - 1,
        count: n,
        visible: target,
      );
    });
    widget.onViewEndChanged?.call(_viewEnd);
    _maybeNeedHistory();
  }

  /// 顶栏按钮：[dir] > 0 放大（一屏少看点），< 0 缩小（一屏多看点）。
  void zoomStep(int dir) {
    final cur = _zoomCurrent;
    final next = dir > 0 ? (cur / 1.6).floor() : (cur * 1.6).ceil();
    LighthouseFeedback.instance.play(LighthouseFeedbackKind.select);
    _zoomTo(next);
  }

  /// 还原：回到打开时的视窗（日线从 7 月起 / 其余最近 N 期）。
  void resetView() {
    if (_panAnim.isAnimating) _panAnim.stop();
    LighthouseFeedback.instance.play(LighthouseFeedbackKind.navigate);
    setState(() {
      _viewTouched = false;
      _fitAll = false;
      _zoomVisible = null;
      _viewEnd = math.max(0, _n - 1).toDouble();
      _applyInitialWindow();
    });
    widget.onViewEndChanged?.call(_viewEnd);
  }

  /// 一屏铺满有数据的全部日期。
  void zoomToFit() {
    if (!widget.zoomable || !_viewportMode) return;
    LighthouseFeedback.instance.play(LighthouseFeedbackKind.expand);
    if (_panAnim.isAnimating) _panAnim.stop();
    _viewTouched = true;
    setState(() {
      _fitAll = true;
      _viewEnd = math.max(0, _n - 1).toDouble();
    });
    widget.onViewEndChanged?.call(_viewEnd);
    _maybeNeedHistory();
  }

  void _onZoomPointerDown(PointerDownEvent e) {
    _zoomPointers[e.pointer] = e.localPosition;
    if (_zoomPointers.length != 2) return;
    final pts = _zoomPointers.values.toList(growable: false);
    final d = (pts[0] - pts[1]).distance;
    if (d <= 8) return;
    _pinchStartDist = d;
    _pinchStartVisible = _zoomCurrent;
    if (_panAnim.isAnimating) _panAnim.stop();
  }

  void _onZoomPointerMove(PointerMoveEvent e, double w) {
    if (!_zoomPointers.containsKey(e.pointer)) return;
    _zoomPointers[e.pointer] = e.localPosition;
    final d0 = _pinchStartDist;
    if (d0 == null || _zoomPointers.length < 2) return;
    final pts = _zoomPointers.values.take(2).toList(growable: false);
    final d = (pts[0] - pts[1]).distance;
    if (d <= 1) return;
    final mid = (pts[0].dx + pts[1].dx) / 2;
    _zoomTo((_pinchStartVisible * d0 / d).round(), focalFrac: _fracAt(mid, w));
  }

  void _onZoomPointerUp(int pointer) {
    _zoomPointers.remove(pointer);
    if (_zoomPointers.length < 2) _pinchStartDist = null;
  }

  /// 鼠标滚轮：竖滚缩放（锚在光标下那一天），横滚平移。
  void _onZoomSignal(PointerSignalEvent e, double w) {
    if (e is! PointerScrollEvent) return;
    GestureBinding.instance.pointerSignalResolver.register(e, (ev) {
      final s = ev as PointerScrollEvent;
      final dy = s.scrollDelta.dy;
      final dx = s.scrollDelta.dx;
      if (dy.abs() >= dx.abs()) {
        if (dy.abs() < 0.5) return;
        final cur = _zoomCurrent;
        var next = (cur * math.pow(1.0018, dy)).round();
        if (next == cur) next += dy > 0 ? 1 : -1;
        _zoomTo(next, focalFrac: _fracAt(s.localPosition.dx, w));
      } else if (_windowed) {
        _panBy(-dx, w);
      }
    });
  }

  void _onPanZoomStart(PointerPanZoomStartEvent e) {
    _panZoomStartVisible = _zoomCurrent;
  }

  /// 触控板双指捏合（macOS / Windows 精确触控板）。
  void _onPanZoomUpdate(PointerPanZoomUpdateEvent e, double w) {
    if ((e.scale - 1).abs() < 0.01 || _panZoomStartVisible < 2) return;
    _zoomTo(
      (_panZoomStartVisible / e.scale).round(),
      focalFrac: _fracAt(e.localPosition.dx, w),
    );
  }

  /// 全屏大图横轴抽稀：相邻标签至少隔 46px。从最新一点往回数，
  /// 往前补了历史标签也不跳位。
  bool _xLabelShown(int i, double pxPerPoint) {
    if (!widget.zoomable || pxPerPoint <= 0) return true;
    // 月初永远标（「7月」），日标签给月初让位，不挤在一起。
    if (_isMonthStart(i)) return true;
    final stride = math.max(1, (46.0 / pxPerPoint).ceil());
    if ((_n - 1 - i) % stride != 0) return false;
    final gap = math.max(1, (40.0 / pxPerPoint).ceil());
    for (var d = 1; d <= gap; d++) {
      if (_isMonthStart(i - d) || _isMonthStart(i + d)) return false;
    }
    return true;
  }

  /// 当前读数位置：点中的那天，否则最新一天。
  int _focusIndex(int n) {
    final sel = _selectedIndex;
    return sel != null && sel >= 0 && sel < n ? sel : n - 1;
  }

  /// 副图标题，带当期数值（像 MACD 的 DIF / DEA）：
  /// 均线差 7日−30日 · 快 x · 慢 y · 差 z。
  Widget _laneTitle(BuildContext ctx) {
    final real = _heroRealPts;
    final base = LhTypography.mono(
      size: 7.5,
      color: DunesColors.resolve(ctx, LhColors.mute2),
      weight: FontWeight.w600,
      letterSpacing: 0.3,
      context: ctx,
    );
    const title = 'MACD(12,26,9)';
    if (real.isEmpty) return Text(title, style: base);
    final i = _focusIndex(real.length);
    final m = _trendMacd(real);
    final dif = m.dif[i];
    final dea = m.dea[i];
    final h = 2 * (dif - dea);
    TextSpan v(String label, double x, Color c) => TextSpan(
      text: '  $label:${_fmtHeroShort(x)}',
      style: base.copyWith(
        color: DunesColors.resolve(ctx, c),
        fontWeight: FontWeight.w700,
      ),
    );
    return Text.rich(
      TextSpan(
        children: [
          TextSpan(text: title, style: base),
          v('DIF', dif, LhKColors.dif),
          v('DEA', dea, LhKColors.dea),
          v('MACD', h, h >= 0 ? LhKColors.barUp : LhKColors.barDown),
        ],
      ),
      maxLines: 1,
      overflow: TextOverflow.ellipsis,
    );
  }

  /// 点中某天的明细牌（看盘软件长按出来的那块）：日期 · 当期值 · 较前一期 ·
  /// 快 / 慢均线 · 均线差。
  Widget _crossCard(int i) {
    final real = _heroRealPts;
    if (i < 0 || i >= real.length) return const SizedBox.shrink();
    final u = _unit;
    final v = real[i];
    final prev = i > 0 ? real[i - 1] : double.nan;
    final w = _nxWindows;
    final f = _trendEma(real, w.fa)[i];
    final sl = _trendEma(real, w.sa)[i];
    final macd = _trendMacd(real);
    final hist = 2 * (macd.dif[i] - macd.dea[i]);
    final label = widget.legendCompact
        ? _fullDateLabel(i)
        : (i < _pointLabels.length ? _pointLabels[i] : '');
    final keyStyle = LhTypography.sans(
      size: 9,
      color: DunesColors.resolve(context, LhColors.mute2),
      weight: FontWeight.w500,
      context: context,
    );
    final valStyle = LhTypography.mono(
      size: 9,
      color: DunesColors.resolve(context, LhColors.ink),
      weight: FontWeight.w700,
      letterSpacing: -0.1,
      context: context,
    );
    // 值那一格可以缩：「+148.6万 +956%」这种长串不许把牌子撑破。
    Widget row(String k, String val, {Color? color}) => Padding(
      padding: const EdgeInsets.only(top: 3),
      child: Row(
        children: [
          Text(k, style: keyStyle),
          const SizedBox(width: 8),
          Expanded(
            child: FittedBox(
              fit: BoxFit.scaleDown,
              alignment: Alignment.centerRight,
              child: Text(
                val,
                maxLines: 1,
                softWrap: false,
                style: color == null
                    ? valStyle
                    : valStyle.copyWith(color: color),
              ),
            ),
          ),
        ],
      ),
    );
    String chg() {
      if (!prev.isFinite || !v.isFinite) return '—';
      final d = v - prev;
      final pct = prev.abs() > 1e-9
          ? ' ${d >= 0 ? '+' : '−'}${(d.abs() / prev.abs() * 100).toStringAsFixed(1)}%'
          : '';
      return '${d >= 0 ? '+' : '−'}${_money(d.abs())}$pct';
    }

    final up = prev.isFinite && v >= prev;
    return _LhKStack(
      radius: 7,
      dx: 3,
      dy: -3,
      child: Stack(
        children: [
          Container(
            width: 150,
            padding: const EdgeInsets.fromLTRB(8, 6, 10, 8),
            decoration: _lhKCardDeco(context, radius: 7, strong: true),
            child: Column(
              crossAxisAlignment: CrossAxisAlignment.stretch,
              mainAxisSize: MainAxisSize.min,
              children: [
                Padding(
                  padding: const EdgeInsets.only(right: 16),
                  child: Text(
                    label,
                    maxLines: 1,
                    overflow: TextOverflow.ellipsis,
                    style: LhTypography.mono(
                      size: 9.5,
                      color: DunesColors.resolve(context, _LhPlum.deep),
                      weight: FontWeight.w800,
                      letterSpacing: 0.3,
                      context: context,
                    ),
                  ),
                ),
                Container(
                  margin: const EdgeInsets.only(top: 4, bottom: 1),
                  height: 0.6,
                  color: DunesColors.resolve(
                    context,
                    _LhPlum.line,
                    role: DunesColorRole.surface,
                  ),
                ),
                row('当${u.avg.substring(0, 1)}', _money(v)),
                row(
                  '较${u.prevAny}',
                  chg(),
                  color: prev.isFinite
                      ? DunesColors.resolve(
                          context,
                          up ? LhKColors.up : LhKColors.down,
                        )
                      : null,
                ),
                row(
                  'NX快',
                  _money(f),
                  color: DunesColors.resolve(context, LhKColors.nxFast),
                ),
                row(
                  'NX慢',
                  _money(sl),
                  color: DunesColors.resolve(context, LhKColors.nxSlow),
                ),
                row(
                  'MACD',
                  '${hist >= 0 ? '+' : '−'}${_fmtHeroShort(hist.abs())}',
                  color: DunesColors.resolve(
                    context,
                    hist >= 0 ? LhKColors.barUp : LhKColors.barDown,
                  ),
                ),
              ],
            ),
          ),
          Positioned(
            top: 0,
            right: 0,
            child: Semantics(
              button: true,
              label: '关闭',
              child: Padding(
                padding: const EdgeInsets.all(4),
                child: Icon(
                  Icons.close_rounded,
                  size: 13,
                  color: DunesColors.resolve(context, LhColors.mute2),
                ),
              ),
            ),
          ),
          const Positioned(
            right: 0,
            bottom: 0,
            child: _LhKCorner(size: 12, cardRadius: 7),
          ),
        ],
      ),
    );
  }

  /// 十字光标的小牌：深紫底白字。
  Widget _crossTag(String text) {
    return Container(
      padding: const EdgeInsets.symmetric(horizontal: 4, vertical: 1.5),
      decoration: BoxDecoration(
        color: DunesColors.resolve(
          context,
          _LhPlum.deep,
          role: DunesColorRole.surface,
        ),
        borderRadius: BorderRadius.circular(3),
      ),
      child: Text(
        text,
        maxLines: 1,
        overflow: TextOverflow.clip,
        style: LhTypography.mono(
          size: 8,
          color: Colors.white,
          weight: FontWeight.w700,
          letterSpacing: 0.1,
          context: context,
        ),
      ),
    );
  }

  /// 主线这一条的真实值（没削峰）。
  List<double> get _heroRealPts => _trendPaintSpec(
    series: _series,
    bounds: _bounds,
    colors: _paintColors,
    index: _heroIndexFor(_visibleFlags),
  ).pts;

  String _money(double v) =>
      '${v < 0 ? '−' : ''}${_fmtHeroAbs(v.abs())}${_fmtHeroUnit(v.abs())}';

  /// 读数右边的「较前一天」：▲ +1.2万 +29%，涨红跌绿。
  /// 读数右边的涨跌：写清楚跟谁比 ——「较昨日 / 较上周…」，点了某一天是
  /// 「较前一日 / 前一周…」。
  Widget _dayChangeTag() {
    final pts = _heroRealPts;
    final n = pts.length;
    final sel = _selectedIndex;
    final picked = sel != null && sel >= 0 && sel < n;
    final i = picked ? sel! : n - 1;
    final u = _unit;
    final muted = LhTypography.mono(
      size: 10,
      color: DunesColors.resolve(context, LhColors.mute2),
      weight: FontWeight.w600,
      letterSpacing: 0.1,
      context: context,
    );
    if (n == 0) return const SizedBox.shrink();
    if (i < 1 || !pts[i].isFinite || !pts[i - 1].isFinite) {
      return const SizedBox.shrink();
    }
    final d = pts[i] - pts[i - 1];
    final base = pts[i - 1].abs();
    final up = d >= 0;
    final c = DunesColors.resolve(context, up ? LhKColors.up : LhKColors.down);
    final pct = base > 1e-9
        ? ' ${up ? '+' : '−'}${(d.abs() / base * 100).toStringAsFixed(d.abs() / base >= 1 ? 0 : 1)}%'
        : '';
    final vs = picked ? u.prevAny : u.prevLatest;
    // 一颗淡底胶囊：「较前一日」灰字 + 箭头和金额 + 百分比，三段同一基线。
    final strong = LhTypography.mono(
      size: 10.5,
      color: c,
      weight: FontWeight.w700,
      letterSpacing: -0.1,
      context: context,
    );
    return Stack(
      children: [
        Container(
          height: 22,
          padding: const EdgeInsets.fromLTRB(8, 0, 12, 0),
          alignment: Alignment.center,
          decoration: BoxDecoration(
            color: LhKColors.tint(c, 0.94),
            borderRadius: BorderRadius.circular(6),
            border: Border.all(color: LhKColors.tint(c, 0.72), width: 0.7),
            boxShadow: [
              BoxShadow(
                color: c.withAlpha(28),
                blurRadius: 5,
                spreadRadius: -1,
                offset: const Offset(0, 2),
              ),
            ],
          ),
          child: Text.rich(
            TextSpan(
              children: [
                TextSpan(text: '较$vs ', style: muted.copyWith(fontSize: 9.5)),
                WidgetSpan(
                  alignment: PlaceholderAlignment.middle,
                  child: Padding(
                    padding: const EdgeInsets.symmetric(horizontal: 3),
                    child: _LhKCandleGlyph(up: up, color: c),
                  ),
                ),
                TextSpan(
                  text: '${up ? '+' : '−'}${_money(d.abs())}',
                  style: strong,
                ),
                if (pct.isNotEmpty) TextSpan(text: ' ·$pct', style: strong),
              ],
            ),
            maxLines: 1,
            overflow: TextOverflow.ellipsis,
          ),
        ),
        Positioned(
          right: 0,
          bottom: 0,
          child: _LhKCorner(size: 8, cardRadius: 6, color: c),
        ),
      ],
    );
  }

  /// 视窗统计条（跟着拖动 / 缩放变）：最高 · 最低 · 日均 · 合计 · 涨跌天数。
  Widget _windowStats() {
    final pts = _heroRealPts;
    if (pts.isEmpty) return const SizedBox(height: 16);
    final last = pts.length - 1;
    final a = _windowed ? (_viewStart - 1e-6).ceil().clamp(0, last) : 0;
    final b = _windowed ? (_viewEnd + 1e-6).floor().clamp(a, last) : last;
    var hi = double.negativeInfinity;
    var lo = double.infinity;
    var sum = 0.0;
    var cnt = 0;
    var up = 0;
    var down = 0;
    for (var i = a; i <= b; i++) {
      final v = pts[i];
      if (!v.isFinite) continue;
      if (v > hi) hi = v;
      if (v < lo) lo = v;
      sum += v;
      cnt++;
      if (i > 0 && pts[i - 1].isFinite) {
        if (v > pts[i - 1]) up++;
        if (v < pts[i - 1]) down++;
      }
    }
    if (cnt == 0) return const SizedBox(height: 16);
    final labelStyle = LhTypography.sans(
      size: 9,
      color: DunesColors.resolve(context, LhColors.mute2),
      weight: FontWeight.w500,
      context: context,
    );
    final valueStyle = LhTypography.mono(
      size: 9.5,
      color: DunesColors.resolve(context, LhColors.ink),
      weight: FontWeight.w700,
      letterSpacing: -0.1,
      context: context,
    );
    Widget cell(String label, String value, {Color? color}) => Expanded(
      child: Row(
        children: [
          Text(label, style: labelStyle),
          const SizedBox(width: 4),
          Flexible(
            child: Text(
              value,
              maxLines: 1,
              overflow: TextOverflow.ellipsis,
              style: color == null
                  ? valueStyle
                  : valueStyle.copyWith(color: color),
            ),
          ),
        ],
      ),
    );
    final cells = <Widget>[
      cell('最高', _money(hi), color: DunesColors.resolve(context, LhKColors.up)),
      cell(_unit.avg, _money(sum / cnt)),
      cell(
        '涨/跌',
        '$up/$down',
        color: DunesColors.resolve(
          context,
          up >= down ? LhKColors.up : LhKColors.down,
        ),
      ),
      cell(
        '最低',
        _money(lo),
        color: DunesColors.resolve(context, LhKColors.down),
      ),
      cell('合计', _money(sum)),
      cell('天数', '$cnt'),
    ];
    // 手机上一行塞五格会挤成省略号：窄屏改成 2 × 3，跟看盘软件的
    // 最高 / 今开 / 成交量 那块一样排。
    return LayoutBuilder(
      builder: (ctx, box) {
        final narrow = box.maxWidth < 440;
        Widget row(List<Widget> xs) =>
            SizedBox(height: 18, child: Row(children: xs));
        return Stack(
          children: [
            Container(
              padding: const EdgeInsets.fromLTRB(9, 3, 13, 3),
              decoration: _lhKCardDeco(context, radius: 8),
              child: narrow
                  ? Column(
                      mainAxisSize: MainAxisSize.min,
                      children: [
                        row(cells.sublist(0, 3)),
                        row(cells.sublist(3)),
                      ],
                    )
                  : row(cells),
            ),
            const Positioned(
              right: 0,
              bottom: 0,
              child: _LhKCorner(size: 10, cardRadius: 8),
            ),
          ],
        );
      },
    );
  }

  /// K 线图例：每条线一颗「小眼睛」——实际值 / 均线 / NX快 / NX慢，点一下开关。
  /// 开着是一张白卡（跟入口卡同一套皮），关掉变淡紫灰、字和色块都淡下去。
  Widget _candleLegend() {
    final style = LhTypography.sans(
      size: 9,
      color: DunesColors.resolve(context, LhColors.ink2),
      weight: FontWeight.w600,
      letterSpacing: 0.2,
      context: context,
    );
    final dim = style.copyWith(
      color: DunesColors.resolve(context, LhColors.mute2).withAlpha(140),
      fontWeight: FontWeight.w500,
    );
    Widget lineSwatch(Color c, bool on) => Container(
      width: 12,
      height: 2.4,
      decoration: BoxDecoration(
        color: on ? c : LhKColors.tint(c, 0.62),
        borderRadius: BorderRadius.circular(1.2),
      ),
    );
    Widget bandSwatch(Color c, bool on) => Container(
      width: 12,
      height: 7,
      decoration: BoxDecoration(
        color: LhKColors.tint(c, on ? 0.82 : 0.95),
        borderRadius: BorderRadius.circular(2),
        border: Border.all(color: on ? c : LhKColors.tint(c, 0.62), width: 0.9),
      ),
    );
    Widget box(Color c) => Container(
      width: 4,
      height: 8,
      decoration: BoxDecoration(
        color: DunesColors.resolve(context, c, role: DunesColorRole.surface),
        borderRadius: BorderRadius.circular(1),
      ),
    );
    Widget toggle(
      String label,
      Widget Function(bool on) swatch,
      bool on,
      VoidCallback flip,
    ) {
      return Semantics(
        button: true,
        toggled: on,
        label: label,
        child: GestureDetector(
          behavior: HitTestBehavior.opaque,
          onTap: () {
            LighthouseFeedback.instance.play(LighthouseFeedbackKind.select);
            setState(flip);
          },
          child: AnimatedContainer(
            duration: const Duration(milliseconds: 140),
            curve: Curves.easeOut,
            height: 16,
            padding: const EdgeInsets.symmetric(horizontal: 5),
            decoration: on
                ? _lhKCardDeco(context, radius: 5)
                : BoxDecoration(
                    color: DunesColors.resolve(
                      context,
                      const Color(0xFFF4F2F8),
                      role: DunesColorRole.surface,
                    ),
                    borderRadius: BorderRadius.circular(5),
                    border: Border.all(
                      color: DunesColors.resolve(
                        context,
                        const Color(0xFFEAE5F3),
                        role: DunesColorRole.border,
                      ),
                      width: 0.7,
                    ),
                  ),
            child: Row(
              mainAxisSize: MainAxisSize.min,
              children: [
                swatch(on),
                const SizedBox(width: 3),
                Text(label, style: on ? style : dim),
                const SizedBox(width: 3),
                Icon(
                  on
                      ? Icons.visibility_outlined
                      : Icons.visibility_off_outlined,
                  size: 10,
                  color: on
                      ? DunesColors.resolve(context, _LhPlum.deep)
                      : DunesColors.resolve(
                          context,
                          LhColors.mute2,
                        ).withAlpha(140),
                ),
              ],
            ),
          ),
        ),
      );
    }

    final narrow = MediaQuery.sizeOf(context).width < 430;
    final hintStyle = LhTypography.sans(
      size: 9,
      color: DunesColors.resolve(context, LhColors.mute2).withAlpha(140),
      weight: FontWeight.w500,
      letterSpacing: 0.2,
      context: context,
    );
    return SizedBox(
      height: 20,
      child: Row(
        children: [
          Expanded(
            child: SingleChildScrollView(
              scrollDirection: Axis.horizontal,
              padding: const EdgeInsets.symmetric(vertical: 2),
              child: Row(
                children: [
                  toggle(
                    '实际值',
                    (on) => lineSwatch(LhKColors.actual, on),
                    _showActual,
                    () => _showActual = !_showActual,
                  ),
                  const SizedBox(width: 5),
                  toggle(
                    _unit.fastLabel,
                    (on) => lineSwatch(LhKColors.trend, on),
                    _showTrend,
                    () => _showTrend = !_showTrend,
                  ),
                  const SizedBox(width: 5),
                  toggle(
                    'NX快',
                    (on) => bandSwatch(LhKColors.nxFast, on),
                    _showNxFast,
                    () => _showNxFast = !_showNxFast,
                  ),
                  const SizedBox(width: 5),
                  toggle(
                    'NX慢',
                    (on) => bandSwatch(LhKColors.nxSlow, on),
                    _showNxSlow,
                    () => _showNxSlow = !_showNxSlow,
                  ),
                  const SizedBox(width: 9),
                  box(LhKColors.up),
                  const SizedBox(width: 2),
                  box(LhKColors.down),
                  const SizedBox(width: 4),
                  Text(
                    '比${_unit.prevAny}高 / 低',
                    maxLines: 1,
                    style: hintStyle.copyWith(
                      color: DunesColors.resolve(context, LhColors.mute2),
                    ),
                  ),
                ],
              ),
            ),
          ),
          if (!narrow) ...[
            const SizedBox(width: 8),
            Text('拖动平移 · 双指缩放', maxLines: 1, style: hintStyle),
          ],
        ],
      ),
    );
  }

  /// 全屏大图的一行读数：主线那一条的「色条 · 名称 · 数值」，跟图例格同一套字。
  Widget _compactReadout({
    required double rVal,
    required double cVal,
    required double pVal,
    required double sVal,
    required double sAltVal,
    required double caVal,
    required double stVal,
  }) {
    final heroIdx = _heroIndexFor(_visibleFlags);
    final key = heroIdx >= 0 && heroIdx < lighthouseTrendSeriesKeys.length
        ? lighthouseTrendSeriesKeys[heroIdx]
        : 'profit';
    final (String label, double v, Color c) = switch (key) {
      'revenue' => (widget.revenueLabel, rVal, _cRev),
      'cost' => (widget.costLabel, cVal, _cCost),
      'scale' => (widget.scaleLabel, sVal, _cScale),
      'scaleAlt' => (widget.scaleAltLabel, sAltVal, _cScale),
      'costAlt' => (widget.costAltLabel, caVal, _cCostAlt),
      'stock' => (widget.stockLabel, stVal, _cStock),
      _ => (widget.profitLabel, pVal, _cProf),
    };
    final neg = _legendNegative(key, v < 0);
    final labelText = Text(
      label,
      style: LhTypography.sans(
        size: 11,
        color: DunesColors.resolve(context, LhColors.ink2),
        weight: FontWeight.w600,
        letterSpacing: 0.2,
        context: context,
      ),
    );
    // 全屏大图：指标名是一个下拉 —— 利润 / 核销额 / 销售规模 / 收入 / 成本 / GMV。
    String labelOf(String k) => switch (k) {
      'revenue' => widget.revenueLabel,
      'cost' => widget.costLabel,
      'scale' => widget.scaleLabel,
      'scaleAlt' => widget.scaleAltLabel,
      'costAlt' => widget.costAltLabel,
      'stock' => widget.stockLabel,
      _ => widget.profitLabel,
    };
    final base = _baseFlags;
    final pickable = <String>[
      for (final k in const [
        'profit',
        'scale',
        'scaleAlt',
        'revenue',
        'cost',
        'costAlt',
      ])
        if (lighthouseTrendSeriesKeys.indexOf(k) case final i
            when i >= 0 && i < base.length && base[i] && labelOf(k).isNotEmpty)
          k,
    ];
    final Widget labelWidget = !widget.legendCompact || pickable.length < 2
        ? labelText
        : PopupMenuButton<String>(
            tooltip: '切换指标',
            position: PopupMenuPosition.under,
            offset: const Offset(0, 4),
            color: DunesColors.resolve(
              context,
              Colors.white,
              role: DunesColorRole.surface,
            ),
            elevation: 6,
            shape: RoundedRectangleBorder(
              borderRadius: BorderRadius.circular(10),
              side: BorderSide(
                color: DunesColors.resolve(
                  context,
                  _LhPlum.line,
                  role: DunesColorRole.border,
                ),
                width: 0.8,
              ),
            ),
            onSelected: (k) {
              LighthouseFeedback.instance.play(LighthouseFeedbackKind.select);
              setState(() => _soloKey = k);
              widget.onSoloChanged?.call(k);
            },
            itemBuilder: (_) => [
              for (final k in pickable)
                PopupMenuItem<String>(
                  value: k,
                  height: 36,
                  child: Row(
                    children: [
                      Expanded(
                        child: Text(
                          labelOf(k),
                          style: LhTypography.sans(
                            size: 12,
                            color: k == key
                                ? DunesColors.resolve(context, _LhPlum.deep)
                                : DunesColors.resolve(context, LhColors.ink),
                            weight: k == key
                                ? FontWeight.w700
                                : FontWeight.w500,
                            context: context,
                          ),
                        ),
                      ),
                      if (k == key)
                        Icon(
                          Icons.check_rounded,
                          size: 14,
                          color: DunesColors.resolve(context, _LhPlum.primary),
                        ),
                    ],
                  ),
                ),
            ],
            child: _LhKStack(
              radius: 6,
              child: Container(
                padding: const EdgeInsets.fromLTRB(7, 2, 3, 2),
                decoration: _lhKCardDeco(context, radius: 6),
                child: Row(
                  mainAxisSize: MainAxisSize.min,
                  children: [
                    labelText,
                    Icon(
                      Icons.expand_more_rounded,
                      size: 14,
                      color: DunesColors.resolve(context, LhColors.ink2),
                    ),
                  ],
                ),
              ),
            ),
          );
    return Row(
      mainAxisSize: MainAxisSize.min,
      children: [
        labelWidget,
        const SizedBox(width: 8),
        Flexible(
          child: Text(
            '${neg ? '−' : ''}${_fmtHeroAbs(v.abs())}${_fmtHeroUnit(v.abs())}',
            maxLines: 1,
            overflow: TextOverflow.ellipsis,
            style: LhTypography.number(
              size: 17,
              // 利润：赚红亏绿；其它指标正数用墨色。
              color: neg
                  ? DunesColors.resolve(
                      context,
                      widget.candles ? LhKColors.down : LhColors.pos,
                    )
                  : (key == 'profit' && v > 0
                        ? DunesColors.resolve(
                            context,
                            widget.candles ? LhKColors.up : LhColors.neg,
                          )
                        : DunesColors.resolve(context, LhColors.ink)),
              context: context,
            ).copyWith(height: 1.0),
          ),
        ),
      ],
    );
  }

  /// 「本期合计」那一行右侧的入口：一张迷你 K 线卡（最近几天的利润），
  /// 后面叠一张淡紫卡，右下角贴一个紫色角标。占位高度压在 13px 以内。
  Widget _trendExpandButton(ValueChanged<Rect?> onTap) {
    final tail = <double>[];
    for (var i = widget.profit.length - 1; i >= 0 && tail.length < 10; i--) {
      final v = widget.profit[i];
      if (v.isFinite) tail.insert(0, v);
    }
    return SizedBox(
      width: 30,
      height: 13,
      child: OverflowBox(
        maxHeight: 26,
        alignment: Alignment.centerRight,
        child: _LhMiniKButton(
          values: tail,
          loading: tail.length < 3,
          onTap: onTap,
        ),
      ),
    );
  }

  void _resetViewport() {
    if (_panAnim.isAnimating) _panAnim.stop();
    _viewEnd = math.max(0, _n - 1).toDouble();
    widget.onViewEndChanged?.call(_viewEnd);
  }

  void _setViewEnd(double v) {
    final next = lighthouseTrendClampViewEnd(
      viewEnd: v,
      count: _n,
      visible: _visible,
    );
    if ((next - _viewEnd).abs() < 1e-6) return;
    setState(() => _viewEnd = next);
    widget.onViewEndChanged?.call(_viewEnd);
  }

  void _maybeNeedHistory({bool onStart = false}) {
    final cb = widget.onNeedHistory;
    if (cb == null || !widget.historyHasMore || widget.historyLoading) return;
    // 第一次拖动就先要一页（还没有任何历史时），之后只在靠近左沿时再要。
    if ((onStart && widget.historyCount == 0) || _viewStart <= 2.0) cb();
  }

  void _panBy(double dx, double w) {
    if (_pinching) return;
    _viewTouched = true;
    final step = _stepFor(w);
    if (step <= 0) return;
    _setViewEnd(_viewEnd - dx / step);
    _maybeNeedHistory();
  }

  void _endPan(double vx, double w) {
    final step = _stepFor(w);
    if (_pinching || !_windowed || step <= 0 || vx.abs() < 60) return;
    _panAnim.animateWith(FrictionSimulation(0.08, _viewEnd, -vx / step));
  }

  void _onPanAnimTick() {
    if (!mounted) return;
    final raw = _panAnim.value;
    final v = lighthouseTrendClampViewEnd(
      viewEnd: raw,
      count: _n,
      visible: _visible,
    );
    if ((v - raw).abs() > 1e-6 && _panAnim.isAnimating) _panAnim.stop();
    if ((v - _viewEnd).abs() > 1e-6) {
      setState(() => _viewEnd = v);
      widget.onViewEndChanged?.call(_viewEnd);
    }
    _maybeNeedHistory();
  }

  void _jumpToLatest() {
    LighthouseFeedback.instance.play(LighthouseFeedbackKind.navigate);
    _panAnim.stop();
    _panAnim.value = _viewEnd;
    _panAnim.animateTo(
      math.max(0, _n - 1).toDouble(),
      duration: const Duration(milliseconds: 360),
      curve: Curves.easeOutCubic,
    );
  }

  _TrendSeries _sliceSeries(int lo, int hi) {
    List<double> cut(List<double> l) =>
        l.isEmpty ? l : l.sublist(lo, math.min(hi + 1, l.length));
    final src = _paintSeries;
    return _TrendSeries(
      revenue: cut(src.revenue),
      cost: cut(src.cost),
      profit: cut(src.profit),
      scale: cut(src.scale),
      scaleAlt: cut(src.scaleAlt),
      costAlt: cut(src.costAlt),
      stock: cut(src.stock),
    );
  }

  /// 视窗模式下贴在画布上的小胶囊（加载中 / 已到最早 / 回到最新）。
  Widget _viewportTag(String text, {bool busy = false, VoidCallback? onTap}) {
    final pill = Container(
      padding: const EdgeInsets.symmetric(horizontal: 6, vertical: 2),
      decoration: BoxDecoration(
        color: DunesColors.resolve(
          context,
          Colors.white,
          role: DunesColorRole.surface,
        ).withAlpha(240),
        borderRadius: BorderRadius.circular(8),
        border: Border.all(
          color: DunesColors.resolve(
            context,
            _LhPlum.deep,
            role: DunesColorRole.border,
          ).withAlpha(22),
          width: 0.5,
        ),
        boxShadow: [
          BoxShadow(
            color: _LhPlum.deep.withAlpha(22),
            blurRadius: 6,
            spreadRadius: -1,
            offset: const Offset(0, 1.5),
          ),
        ],
      ),
      child: Row(
        mainAxisSize: MainAxisSize.min,
        children: [
          if (busy) ...[
            SizedBox(
              width: 7,
              height: 7,
              child: CircularProgressIndicator(
                strokeWidth: 1.1,
                color: DunesColors.resolve(
                  context,
                  _LhPlum.primary,
                ).withAlpha(200),
              ),
            ),
            const SizedBox(width: 4),
          ],
          Text(
            text,
            style: LhTypography.mono(
              size: 7.5,
              color: onTap != null
                  ? DunesColors.resolve(context, _LhPlum.deep)
                  : DunesColors.resolve(context, LhColors.mute2),
              weight: FontWeight.w700,
              letterSpacing: 0.3,
              context: context,
            ),
          ),
          if (onTap != null)
            Icon(
              Icons.chevron_right_rounded,
              size: 10,
              color: DunesColors.resolve(context, _LhPlum.deep).withAlpha(200),
            ),
        ],
      ),
    );
    if (onTap == null) return IgnorePointer(child: pill);
    return GestureDetector(
      behavior: HitTestBehavior.opaque,
      onTap: onTap,
      child: Padding(padding: const EdgeInsets.all(4), child: pill),
    );
  }

  /// 年末延伸：主线的预测里带了当月之后的月份（且不多于
  /// [lighthouseYearEndChartMaxMonths]）时，图右侧接着画这几个月。
  List<LighthouseFutureMonth> get _futureShown {
    const none = <LighthouseFutureMonth>[];
    if (widget.candles || _n < 2) return none;
    final vis = _visibleFlags;
    final hero = _heroIndexFor(vis);
    final f = vis[3]
        ? widget.scaleForecast
        : (hero == lighthouseTrendProfitIndex && widget.partialPeriod
              ? widget.profitForecast
              : null);
    final list = f?.future ?? none;
    return list.length > lighthouseYearEndChartMaxMonths ? none : list;
  }

  /// 右侧给之后各月留的宽度：按「一屏点数 + 之后月数」重新均分，
  /// 已发生的那几个月和之后的月份点距一样，不会一边挤一边松。
  double _futureGutterW(double fullW, int months) {
    if (months <= 0) return 0;
    final slots = (_windowed ? _visible : _n) - 1 + months;
    if (slots <= 0) return 0;
    final step = (fullW - _kChartPadH * 2) / slots;
    return step <= 0 ? 0 : months * step;
  }

  /// 视窗停在最新一期（之后各月才接得上实线末端）。
  bool get _atLatest => !_windowed || _viewEnd >= _n - 1 - 1e-3;

  /// 横轴上之后各月的标签（「11月」「12月」），跟图里的预测点对齐。
  Widget _futureAxisLabels() => Positioned.fill(
    child: LayoutBuilder(
      builder: (ctx, c) {
        final future = _futureShown;
        if (future.isEmpty || !_atLatest) return const SizedBox.shrink();
        final futW = _futureGutterW(c.maxWidth, future.length);
        if (futW <= 0) return const SizedBox.shrink();
        final w = c.maxWidth - futW;
        final step = futW / future.length;
        final slotW = math.min(34.0, step + 6);
        return Stack(
          clipBehavior: Clip.none,
          children: [
            for (var k = 0; k < future.length; k++)
              Positioned(
                left: w - _kChartPadH + (k + 1) * step - slotW / 2,
                width: slotW,
                child: Center(
                  child: Text(
                    '${future[k].month.month.toString().padLeft(2, '0')}月',
                    maxLines: 1,
                    softWrap: false,
                    style: LhTypography.mono(
                      size: 8.5,
                      color: DunesColors.resolve(
                        ctx,
                        LhColors.mute2,
                      ).withAlpha(170),
                      weight: FontWeight.w500,
                      letterSpacing: 0.1,
                      context: ctx,
                    ),
                  ),
                ),
              ),
          ],
        );
      },
    ),
  );

  Widget _trendCanvas() {
    return LayoutBuilder(
      builder: (ctx, c) {
        // 年末延伸：右侧留出之后各月的位置，已发生部分的几何只在剩下的宽度里算。
        final future = _futureShown;
        final futW = _futureGutterW(c.maxWidth, future.length);
        final w = c.maxWidth - futW;
        final chartH = c.maxHeight.isFinite && c.maxHeight < 4000
            ? c.maxHeight
            : widget.chartHeight;
        final vis = _visibleFlags;
        final heroIndex = _heroIndexFor(vis);
        // 利润主线在当月没走完时，同规模一样画「已发生实柱 + 月末预测虚框」。
        final paceMult = _paceMultiplier;
        final double? profitFc =
            heroIndex == lighthouseTrendProfitIndex &&
                vis[heroIndex] &&
                _hasProf &&
                widget.partialPeriod &&
                _series.profit.length >= 2
            ? (widget.profitForecast?.forecast ??
                  (paceMult != null && paceMult > 1
                      ? _series.profit.last * paceMult
                      : null))
            : null;
        final profitPaceOn = profitFc != null;
        final laneIndex = lighthouseTrendLaneIndex(vis, heroIndex);
        final geo = lighthouseTrendCanvasGeometry(
          chartH,
          wantsLane: laneIndex >= 0 || widget.candles,
        );
        final padTop = geo.plotTop;
        final usableH = geo.plotBottom - geo.plotTop;
        if (usableH <= 4) return const SizedBox.shrink();

        // ── 视窗切片 ──────────────────────────────────────────────────
        //   只把可见区间左右各多带一个点交给画笔（线从画布外平滑地进来），
        //   画笔按切片自己的点距画，再整体平移 left 像素、裁在画布里。
        final n = _n;
        final windowed = _windowed;
        var lo = 0;
        var hi = math.max(0, n - 1);
        var paintLeft = 0.0;
        var paintW = w;
        var step = n <= 1 ? 0.0 : (w - _kChartPadH * 2) / (n - 1);
        var series = _paintSeries;
        var bounds = _paintBounds;
        if (profitPaceOn && !windowed) {
          bounds = _computeBounds(
            series,
            scaleForecast: _hasScale ? widget.scaleForecast?.forecast : null,
            profitForecast: profitFc,
            shareScaleRange: lighthouseTrendShareScaleRange(
              scaleLabel: widget.scaleLabel,
              scaleAltLabel: widget.scaleAltLabel,
            ),
          );
        }
        final viewStart = _viewStart;
        if (windowed) {
          step = _stepFor(w);
          lo = math.max(0, viewStart.floor() - 1);
          hi = math.min(n - 1, _viewEnd.ceil() + 1);
          series = _sliceSeries(lo, hi);
          bounds = _computeBounds(
            series,
            scaleForecast: hi == n - 1 && _hasScale
                ? widget.scaleForecast?.forecast
                : null,
            profitForecast: hi == n - 1 ? profitFc : null,
            shareScaleRange: lighthouseTrendShareScaleRange(
              scaleLabel: widget.scaleLabel,
              scaleAltLabel: widget.scaleAltLabel,
            ),
          );
          paintLeft = (lo - viewStart) * step;
          paintW = _kChartPadH * 2 + (hi - lo) * step;
        }
        if (widget.candles) {
          // 纵轴按「看得见的这一段」的大多数来定，线性、不变形。
          final hp = _trendPaintSpec(
            series: series,
            bounds: bounds,
            colors: _paintColors,
            index: heroIndex,
          ).pts;
          final a0 = windowed ? math.max(0, (viewStart - 1e-6).ceil() - lo) : 0;
          final b0 = windowed
              ? math.min(hp.length - 1, (_viewEnd + 1e-6).floor() - lo)
              : hp.length - 1;
          final r = _robustCandleRange(hp, a0, b0);
          if (r != null) bounds = _boundsWithHero(bounds, heroIndex, r);
        }
        final includesLatest = hi == n - 1;
        // K 线均线在整条序列上算（窗口要往视窗左边借数），再切到画布那一段。
        List<double>? maFast;
        List<double>? maSlow;
        List<List<double>>? nxBands;
        List<double>? macdDif;
        List<double>? macdDea;
        if (widget.candles) {
          final full = _trendPaintSpec(
            series: _paintSeries,
            bounds: _paintBounds,
            colors: _paintColors,
            index: heroIndex,
          ).pts;
          List<double> cutMa(List<double> l) =>
              l.isEmpty ? l : l.sublist(lo, math.min(hi + 1, l.length));
          maFast = _showTrend
              ? cutMa(_trendMovingAverage(full, _unit.fast))
              : null;
          maSlow = cutMa(_trendMovingAverage(full, _unit.slow));
          final w = _nxWindows;
          if (_showNx) {
            nxBands = [
              _showNxFast ? cutMa(_trendEma(full, w.fa)) : const <double>[],
              _showNxFast ? cutMa(_trendEma(full, w.fb)) : const <double>[],
              _showNxSlow ? cutMa(_trendEma(full, w.sa)) : const <double>[],
              _showNxSlow ? cutMa(_trendEma(full, w.sb)) : const <double>[],
            ];
          }
          final macd = _trendMacd(full);
          macdDif = cutMa(macd.dif);
          macdDea = cutMa(macd.dea);
        }
        final forecast = !includesLatest
            ? null
            : (vis[3] ? widget.scaleForecast?.forecast : profitFc);
        // v2 模型的 80% 区间：图上当月那一列画一根须线。
        final band = !includesLatest
            ? null
            : (vis[3]
                  ? widget.scaleForecast
                  : (profitPaceOn ? widget.profitForecast : null));
        final extremeSpec = _trendPaintSpec(
          series: series,
          bounds: bounds,
          colors: _paintColors,
          index: heroIndex,
        );
        final profitBounds = extremeSpec.range;
        // 没走完的那期是进度胶囊，不算主线极值 —— 否则 MIN 永远钉在当月。
        final partial = _trendIsPartial(
          forecast: forecast,
          flags: vis,
          heroIndex: heroIndex,
          heroPts: extremeSpec.pts,
        );
        // 极值只在「看得见的点」里找（切片两端各多出的一个点在画布外）。
        final pts = extremeSpec.pts;
        var eLo = 0;
        var eHi = pts.length - 1 - (partial ? 1 : 0);
        if (windowed) {
          eLo = math.max(eLo, (viewStart - 1e-6).ceil() - lo);
          eHi = math.min(eHi, (_viewEnd + 1e-6).floor() - lo);
        }
        final extremePts = (pts.isNotEmpty && eHi >= eLo)
            ? pts.sublist(eLo, eHi + 1)
            : const <double>[];
        final hasProfit = vis[heroIndex] && extremePts.isNotEmpty;
        final actualMaxP = hasProfit ? extremePts.reduce(math.max) : 0.0;
        final actualMinP = hasProfit ? extremePts.reduce(math.min) : 0.0;
        double yOf(double v) =>
            padTop + (profitBounds.max - v) / profitBounds.span * usableH;
        final maxY = yOf(actualMaxP);
        final minY = yOf(actualMinP);
        // MAX/MIN 跟着极值点的横坐标走（旧版钉在右边缘，读数挂到了别的线上）。
        double extremeLeft(bool wantMax) {
          if (!hasProfit) return w - 56;
          var best = 0;
          for (var i = 1; i < extremePts.length; i++) {
            final better = wantMax
                ? extremePts[i] > extremePts[best]
                : extremePts[i] < extremePts[best];
            if (better) best = i;
          }
          // pill 以点为中心，靠边时夹回画布内。
          final px = paintLeft + _kChartPadH + (eLo + best) * step;
          return (px - 26).clamp(0.0, math.max(0.0, w - 58));
        }

        final showExtremes =
            widget.showExtremeLabels &&
            (!widget.fitHeight || lighthouseCompactHeroShowsExtremeLabels) &&
            hasProfit &&
            extremePts.length >= 3 &&
            (actualMaxP - actualMinP).abs() > 1e-6 &&
            (minY - maxY) > 26;
        // ── 当月那一列的两个点（已发生 / 月末预测）：命中区 + 读数 ─────────
        //   规模主线：实柱顶 = 已发生，虚框顶 = 月末预测；
        //   利润主线：同一画法，已发生实柱 + 按同一公式外推的月末虚框。
        ({double x, double actY, double fcY, double actual, double fc})?
        paceHit;
        if (includesLatest && extremeSpec.pts.length >= 2) {
          final hp = extremeSpec.pts;
          final lastV = hp.last;
          final mult = _paceMultiplier;
          double? fcv;
          if (partial) {
            fcv = forecast;
          } else if (heroIndex == lighthouseTrendProfitIndex &&
              vis[heroIndex] &&
              widget.partialPeriod &&
              mult != null &&
              mult > 1) {
            fcv = lastV * mult;
          }
          if (fcv != null && lastV.isFinite && fcv.isFinite) {
            double cy(double v) =>
                yOf(v).clamp(padTop, geo.plotBottom).toDouble();
            paceHit = (
              x: paintLeft + _kChartPadH + (hp.length - 1) * step,
              actY: cy(lastV),
              fcY: cy(fcv),
              actual: lastV,
              fc: fcv,
            );
          }
        }
        final paceTagOn =
            paceHit != null && _paceTap != null && _selectedIndex == n - 1;
        final sel = _selectedIndex;
        final sliceSelected = sel == null || sel < lo || sel > hi
            ? null
            : sel - lo;
        final viewport = _viewportMode;
        final showLatestTag = windowed && _viewEnd < n - 1 - 0.5;
        final showEarliestTag =
            viewport &&
            !widget.historyLoading &&
            !widget.historyHasMore &&
            widget.historyCount > 0 &&
            viewStart < 0.5;
        // 十字光标位置（K 线模式、选中点在这一段里）。
        double? crossY;
        double? crossX;
        String? crossValue;
        String? crossLabel;
        if (widget.candles &&
            sliceSelected != null &&
            sliceSelected < pts.length &&
            pts[sliceSelected].isFinite) {
          crossY = yOf(
            pts[sliceSelected],
          ).clamp(padTop, geo.plotBottom).toDouble();
          crossX = paintLeft + _kChartPadH + sliceSelected * step;
          final real = _trendPaintSpec(
            series: _series,
            bounds: _bounds,
            colors: _paintColors,
            index: heroIndex,
          ).pts;
          final gi = sel!;
          if (gi < real.length) crossValue = _fmtHeroShort(real[gi]);
          if (gi < _pointLabels.length) crossLabel = _pointLabels[gi];
        }
        // 点中某天的明细牌。
        Widget? crossCard;
        // 没点中任何一天时，默认挂着最新一天的明细牌（构图更完整）；
        // 点一下它就收起，点别的天换成那天的。
        double? cardAnchorX = crossX;
        final defaultCard =
            widget.candles &&
            sel == null &&
            includesLatest &&
            !_hideDefaultCard &&
            n > 0;
        if (crossX != null && sel != null) {
          crossCard = _crossCard(sel);
        } else if (defaultCard) {
          crossCard = _crossCard(n - 1);
          cardAnchorX = paintLeft + _kChartPadH + (n - 1 - lo) * step;
        }
        // 视窗最高 / 最低标注（K 线模式、没点中时）。
        final extremeMarks = <({double left, double y, Widget child})>[];
        if (widget.candles && sel == null && pts.length >= 3) {
          final real = _heroRealPts;
          var iMax = -1;
          var iMin = -1;
          for (
            var k = math.max(0, eLo);
            k <= math.min(eHi, pts.length - 1);
            k++
          ) {
            if (!pts[k].isFinite) continue;
            if (iMax < 0 || pts[k] > pts[iMax]) iMax = k;
            if (iMin < 0 || pts[k] < pts[iMin]) iMin = k;
          }
          void mark(int k, bool high) {
            final gi = lo + k;
            if (k < 0 || gi >= real.length) return;
            final x = paintLeft + _kChartPadH + k * step;
            final y = yOf(pts[k]).clamp(padTop, geo.plotBottom).toDouble();
            final leftSide = x > w * 0.62;
            final text = '${high ? '高' : '低'} ${_fmtHeroShort(real[gi])}';
            final style = LhTypography.mono(
              size: 8,
              color: DunesColors.resolve(ctx, LhColors.ink2),
              weight: FontWeight.w700,
              letterSpacing: 0.1,
              context: ctx,
            );
            final tp = TextPainter(
              text: TextSpan(text: text, style: style),
              textDirection: TextDirection.ltr,
            )..layout();
            const tick = 10.0;
            final width = tp.width + tick + 3;
            final child = SizedBox(
              width: width,
              height: 12,
              child: Row(
                children: [
                  if (!leftSide)
                    Container(
                      width: tick,
                      height: 0.8,
                      color: DunesColors.resolve(ctx, LhColors.ink2),
                    ),
                  if (!leftSide) const SizedBox(width: 3),
                  Text(text, style: style),
                  if (leftSide) const SizedBox(width: 3),
                  if (leftSide)
                    Container(
                      width: tick,
                      height: 0.8,
                      color: DunesColors.resolve(ctx, LhColors.ink2),
                    ),
                ],
              ),
            );
            extremeMarks.add((
              left: (leftSide ? x - width - 2 : x + 2)
                  .clamp(0.0, math.max(0.0, w - width))
                  .toDouble(),
              y: y,
              child: child,
            ));
          }

          if (iMax >= 0) mark(iMax, true);
          if (iMin >= 0 && iMin != iMax) mark(iMin, false);
        }
        // 现价牌：只在 K 线模式、视窗里含最新一天时出。
        double? latestPillY;
        Widget? latestPill;
        if (widget.candles && includesLatest && pts.isNotEmpty) {
          final realPts = _trendPaintSpec(
            series: _series,
            bounds: _bounds,
            colors: _paintColors,
            index: heroIndex,
          ).pts;
          if (realPts.isNotEmpty && pts.last.isFinite) {
            final last = realPts.last;
            final prev = realPts.length >= 2
                ? realPts[realPts.length - 2]
                : last;
            final up = last >= prev;
            latestPillY = yOf(
              pts.last,
            ).clamp(padTop, geo.plotBottom).toDouble();
            latestPill = Container(
              padding: const EdgeInsets.symmetric(horizontal: 4, vertical: 1.5),
              decoration: BoxDecoration(
                color: DunesColors.resolve(
                  ctx,
                  up ? LhKColors.up : LhKColors.down,
                  role: DunesColorRole.surface,
                ),
                borderRadius: BorderRadius.circular(3),
              ),
              child: Text(
                _fmtHeroShort(last),
                style: LhTypography.mono(
                  size: 8,
                  color: Colors.white,
                  weight: FontWeight.w700,
                  letterSpacing: 0.1,
                  context: ctx,
                ),
              ),
            );
          }
        }
        // 之后各月：从本月预测点接着往右，每月一个空心点 + 80% 区间须线。
        _LhFutureMonthsPainter? futurePaint;
        final fcNow = band?.forecast;
        if (future.isNotEmpty &&
            futW > 0 &&
            includesLatest &&
            _atLatest &&
            fcNow != null) {
          final col = heroIndex == lighthouseTrendProfitIndex
              ? (lighthouseTrendValueEarns(fcNow) ? LhColors.neg : LhColors.pos)
              : extremeSpec.color;
          futurePaint = _LhFutureMonthsPainter(
            step: futW / future.length,
            originY: yOf(fcNow).clamp(padTop, geo.plotBottom).toDouble(),
            originLo: band?.lo == null ? null : yOf(band!.lo!),
            originHi: band?.hi == null ? null : yOf(band!.hi!),
            tintFrom: _kChartPadH,
            ys: [for (final f in future) yOf(f.forecast)],
            los: [for (final f in future) f.lo == null ? null : yOf(f.lo!)],
            his: [for (final f in future) f.hi == null ? null : yOf(f.hi!)],
            plotTop: padTop,
            plotBottom: geo.plotBottom,
            labels: [for (final f in future) _fmtHeroShort(f.forecast)],
            color: col,
          );
        }
        final gesture = GestureDetector(
          behavior: HitTestBehavior.opaque,
          onTapDown: (d) {
            _notifyInteraction(true);
            // 视窗模式里按下可能是要拖，等抬手再选点。
            if (!viewport) _setSelectionFromX(d.localPosition.dx, w);
          },
          onTapUp: (d) {
            final prevTap = _paceTap;
            final prevSel = _selectedIndex;
            _setSelectionFromX(d.localPosition.dx, w);
            // K 线里再点一次同一天：收起明细牌。
            if (widget.candles &&
                prevSel != null &&
                _selectedIndex == prevSel) {
              _clearSelection();
              _notifyInteraction(false);
              return;
            }
            // 点在当月那一列附近：离哪个点近就选哪个（已发生 / 月末预测）。
            final ph = paceHit;
            if (ph != null && (d.localPosition.dx - ph.x).abs() <= 22) {
              final dy = d.localPosition.dy;
              final pick = (dy - ph.fcY).abs() <= (dy - ph.actY).abs()
                  ? 'forecast'
                  : 'actual';
              if (_selectedIndex != n - 1) {
                _selectedIndex = n - 1;
                widget.onSelectedIndexChanged?.call(n - 1);
              }
              LighthouseFeedback.instance.play(LighthouseFeedbackKind.select);
              setState(() => _paceTap = pick);
              // 已经选中预测点时再点一下：打开量化报告。
              final open = widget.onOpenForecastReport;
              if (prevTap == 'forecast' && pick == 'forecast' && open != null) {
                open(heroIndex == lighthouseTrendProfitIndex);
              }
            }
            _notifyInteraction(false);
          },
          onTapCancel: () => _notifyInteraction(false),
          onHorizontalDragStart: (d) {
            _notifyInteraction(true);
            if (viewport) {
              _panAnim.stop();
              _maybeNeedHistory(onStart: true);
            } else {
              _setSelectionFromX(d.localPosition.dx, w);
            }
          },
          onHorizontalDragUpdate: (d) {
            if (viewport) {
              _panBy(d.delta.dx, w);
            } else {
              _setSelectionFromX(d.localPosition.dx, w);
            }
          },
          onHorizontalDragEnd: (d) {
            if (viewport) _endPan(d.velocity.pixelsPerSecond.dx, w);
            _notifyInteraction(false);
          },
          onHorizontalDragCancel: () => _notifyInteraction(false),
          onLongPressStart: viewport
              ? (d) {
                  LighthouseFeedback.instance.play(
                    LighthouseFeedbackKind.select,
                  );
                  _panAnim.stop();
                  _notifyInteraction(true);
                  _setSelectionFromX(d.localPosition.dx, w);
                }
              : null,
          onLongPressMoveUpdate: viewport
              ? (d) => _setSelectionFromX(d.localPosition.dx, w)
              : null,
          onLongPressEnd: viewport ? (_) => _notifyInteraction(false) : null,
          child: SizedBox(
            height: chartH,
            child: Stack(
              clipBehavior: Clip.none,
              children: [
                Positioned.fill(
                  child: ClipRect(
                    child: Stack(
                      clipBehavior: Clip.none,
                      children: [
                        // 月初竖向浅灰线：一眼分出几月几月。
                        if (widget.candles)
                          for (var i = lo; i <= hi; i++)
                            if (_isMonthStart(i))
                              Positioned(
                                left: paintLeft + _kChartPadH + (i - lo) * step,
                                top: padTop - 6,
                                height:
                                    (geo.lane
                                        ? geo.laneBottom
                                        : geo.plotBottom) -
                                    padTop +
                                    6,
                                width: 0.7,
                                child: const ColoredBox(
                                  color: Color(0xFFECEBEF),
                                ),
                              ),
                        Positioned(
                          left: paintLeft,
                          top: 0,
                          bottom: 0,
                          width: paintW,
                          child: RepaintBoundary(
                            child: CustomPaint(
                              painter: _TrendLinesPainter(
                                series: series,
                                bounds: bounds,
                                colors: _paintColors,
                                padH: _kChartPadH,
                                available: vis,
                                heroIndexOverride: heroIndex,
                                keepPaletteColor: widget.emphasisColor != null,
                                scaleForecast: forecast,
                                extremeLo: eLo,
                                extremeHi: eHi,
                                showEndpoint: includesLatest,
                                forecastLo: band?.lo,
                                forecastHi: band?.hi,
                                profitPartial:
                                    widget.partialPeriod && includesLatest,
                                profitPace: includesLatest
                                    ? _paceMultiplier
                                    : null,
                                dotScale: widget.zoomable ? 0.62 : 1.0,
                                candles: widget.candles,
                                maFast: maFast,
                                nx: nxBands,
                                showActual: _showActual,
                                macdDif: macdDif,
                                macdDea: macdDea,
                                maSlow: maSlow,
                              ),
                            ),
                          ),
                        ),
                        Positioned(
                          left: paintLeft,
                          top: 0,
                          bottom: 0,
                          width: paintW,
                          child: CustomPaint(
                            painter: _TrendOverlayPainter(
                              series: series,
                              bounds: bounds,
                              colors: _paintColors,
                              padH: _kChartPadH,
                              selectedIndex: sliceSelected,
                              available: vis,
                              heroIndexOverride: heroIndex,
                              scaleForecast: forecast,
                              paceForecastPicked:
                                  paceTagOn && _paceTap == 'forecast',
                              profitForecastValue:
                                  heroIndex == lighthouseTrendProfitIndex
                                  ? paceHit?.fc
                                  : null,
                              dotScale: widget.zoomable ? 0.62 : 1.0,
                              candles: widget.candles,
                            ),
                          ),
                        ),
                      ],
                    ),
                  ),
                ),
                if (futurePaint != null)
                  Positioned(
                    left: w - _kChartPadH,
                    top: 0,
                    width: _kChartPadH + futW,
                    height: chartH,
                    child: IgnorePointer(
                      child: CustomPaint(painter: futurePaint),
                    ),
                  ),
                // 纵轴读数：贴在每条浅灰刻度线上方，写的是真值（削峰反算回来）。
                if (widget.candles)
                  for (final f in lighthouseCandleGridFractions)
                    if ((latestPillY == null ||
                            (padTop + usableH * f - latestPillY).abs() > 14) &&
                        (crossY == null ||
                            (padTop + usableH * f - crossY).abs() > 14))
                      Positioned(
                        right: w + 4,
                        top: math.max(0.0, padTop + usableH * f - 6),
                        child: IgnorePointer(
                          child: Text(
                            _fmtHeroShort(
                              _untameValue(
                                _tameParams[heroIndex],
                                profitBounds.max - f * profitBounds.span,
                              ),
                            ),
                            style: LhTypography.mono(
                              size: 8,
                              color: DunesColors.resolve(ctx, LhColors.mute2),
                              weight: FontWeight.w500,
                              letterSpacing: 0.1,
                              context: ctx,
                            ),
                          ),
                        ),
                      ),
                // 视窗里的最高 / 最低：小横线 + 数，贴在那根蜡烛旁边。
                for (final mk in extremeMarks)
                  Positioned(
                    left: mk.left,
                    top: (mk.y - 6)
                        .clamp(0.0, math.max(0.0, chartH - 12))
                        .toDouble(),
                    child: IgnorePointer(child: mk.child),
                  ),
                // 点中某天的明细牌：放在光标对面那半边，不挡住被点的蜡烛。
                if (crossCard != null && cardAnchorX != null)
                  Positioned(
                    top: padTop,
                    left: cardAnchorX < w / 2 ? null : 30,
                    right: cardAnchorX < w / 2 ? 4 : null,
                    child: GestureDetector(
                      behavior: HitTestBehavior.opaque,
                      onTap: sel == null
                          ? () => setState(() => _hideDefaultCard = true)
                          : _clearSelection,
                      child: crossCard,
                    ),
                  ),
                // 十字光标（K 线模式）：横线 + 左侧读数牌 + 底部日期牌。
                if (crossY != null) ...[
                  Positioned(
                    left: 0,
                    right: 0,
                    top: crossY,
                    height: 0.7,
                    child: IgnorePointer(
                      child: ColoredBox(
                        color: LhKColors.tint(_LhPlum.deep, 0.62),
                      ),
                    ),
                  ),
                  if (crossValue != null)
                    Positioned(
                      right: w + 1,
                      top: (crossY - 7)
                          .clamp(0.0, math.max(0.0, chartH - 14))
                          .toDouble(),
                      child: IgnorePointer(child: _crossTag(crossValue)),
                    ),
                  if (crossX != null && crossLabel != null)
                    Positioned(
                      left: (crossX - 26)
                          .clamp(0.0, math.max(0.0, w - 52))
                          .toDouble(),
                      width: 52,
                      top: geo.plotBottom - 13,
                      child: IgnorePointer(
                        child: Center(child: _crossTag(crossLabel)),
                      ),
                    ),
                ],
                // 最新一天的现价牌：贴左边、跟着那根虚线走，涨红跌绿。
                if (latestPillY != null && latestPill != null)
                  Positioned(
                    right: w + 1,
                    top: (latestPillY - 7)
                        .clamp(0.0, math.max(0.0, chartH - 14))
                        .toDouble(),
                    child: IgnorePointer(child: latestPill),
                  ),
                if (paceTagOn)
                  _paceTag(
                    hit: paceHit!,
                    forecast: _paceTap == 'forecast',
                    width: w,
                    height: chartH,
                  ),
                // 选中某一点时极值 pill 让位给游标，免得两套读数叠在一起。
                if (showExtremes && _selectedIndex == null)
                  Positioned(
                    left: extremeLeft(true),
                    top: (maxY - 17).clamp(0.0, math.max(0.0, chartH - 20)),
                    child: _extremePill('MAX', actualMaxP),
                  ),
                if (showExtremes && _selectedIndex == null)
                  Positioned(
                    left: extremeLeft(false),
                    top: (minY + 5).clamp(0.0, math.max(0.0, chartH - 20)),
                    child: _extremePill('MIN', actualMinP),
                  ),
                // 小柱层的名字就写在缝里 —— 它有自己的尺，不和上面的线比高低，
                // 所以不再需要「各线自归一」那句解释。
                if (geo.lane && (laneIndex >= 0 || widget.candles))
                  Positioned(
                    left: _kChartPadH,
                    top: geo.laneTop - 11,
                    child: widget.candles
                        ? _laneTitle(ctx)
                        : Text(
                            _laneLabelFor(laneIndex),
                            style: LhTypography.mono(
                              size: 7,
                              color: DunesColors.resolve(
                                ctx,
                                LhColors.mute2,
                              ).withAlpha(170),
                              weight: FontWeight.w600,
                              letterSpacing: 0.4,
                              context: ctx,
                            ),
                          ),
                  ),
                if (viewport &&
                    widget.historyLoading &&
                    (!widget.zoomable || viewStart < 3))
                  Positioned(
                    left: 0,
                    top: geo.plotBottom - 16,
                    child: _viewportTag('加载更早', busy: true),
                  )
                else if (showEarliestTag)
                  Positioned(
                    left: 0,
                    top: geo.plotBottom - 16,
                    child: _viewportTag('已到最早'),
                  ),
                if (showLatestTag)
                  Positioned(
                    right: -4,
                    top: geo.plotBottom - 20,
                    child: _viewportTag('回到最新', onTap: _jumpToLatest),
                  ),
              ],
            ),
          ),
        );
        final interactive = widget.hoverSelects
            ? MouseRegion(
                onHover: (e) => _setSelectionFromX(e.localPosition.dx, w),
                child: gesture,
              )
            : gesture;
        if (!widget.zoomable) return interactive;
        return Listener(
          onPointerDown: _onZoomPointerDown,
          onPointerMove: (e) => _onZoomPointerMove(e, w),
          onPointerUp: (e) => _onZoomPointerUp(e.pointer),
          onPointerCancel: (e) => _onZoomPointerUp(e.pointer),
          onPointerSignal: (e) => _onZoomSignal(e, w),
          onPointerPanZoomStart: _onPanZoomStart,
          onPointerPanZoomUpdate: (e) => _onPanZoomUpdate(e, w),
          child: interactive,
        );
      },
    );
  }

  Widget _legendChip(String label, double value, Color color, bool isSelected) {
    final isNeg = value < 0;
