    return Semantics(
      button: true,
      selected: active,
      label: label,
      child: GestureDetector(
        behavior: HitTestBehavior.opaque,
        onTap: () => _toggleSolo(seriesKey),
        child: AnimatedOpacity(
          opacity: dimmed ? 0.6 : 1,
          duration: const Duration(milliseconds: 180),
          child: AnimatedContainer(
            duration: const Duration(milliseconds: 160),
            curve: Curves.easeOut,
            height: 24,
            padding: const EdgeInsets.symmetric(horizontal: 8),
            decoration: BoxDecoration(
              color: DunesColors.resolve(
                context,
                active ? _LhPlum.mist : LhColors.paper,
                role: DunesColorRole.surface,
              ),
              // 方块：圆角 6，比整圆胶囊更像「表格里的一格」，和下面指标格同一语汇。
              borderRadius: BorderRadius.circular(6),
              border: Border.all(
                color: active
                    ? DunesColors.resolve(
                        context,
                        _LhPlum.primary,
                        role: DunesColorRole.border,
                      ).withAlpha(70)
                    : DunesColors.resolve(
                        context,
                        _LhPlum.line,
                        role: DunesColorRole.border,
                      ),
                width: 0.8,
              ),
            ),
            child: Row(
              mainAxisSize: MainAxisSize.min,
              children: [
                if (drawn)
                  Container(
                    width: 7,
                    height: 7,
                    decoration: BoxDecoration(
                      color: DunesColors.resolveNullable(
                        context,
                        color,
                        role: DunesColorRole.surface,
                      ),
                      borderRadius: BorderRadius.circular(2),
                    ),
                  )
                else
                  Container(
                    width: 6,
                    height: 6,
                    decoration: BoxDecoration(
                      color: DunesColors.resolve(
                        context,
                        LhColors.mute2,
                        role: DunesColorRole.surface,
                      ).withAlpha(110),
                      borderRadius: BorderRadius.circular(1.5),
                    ),
                  ),
                const SizedBox(width: 5),
                Text(
                  // 跟下面那排指标格同名（格子里叫「核销额 / 销售额」）。
                  switch (label) {
                    '核销规模' => '核销额',
                    '销售规模' => '销售额',
                    _ => label,
                  },
                  maxLines: 1,
                  softWrap: false,
                  style: LhTypography.sans(
                    size: 11,
                    color: drawn || active
                        ? DunesColors.resolve(context, LhColors.ink2)
                        : DunesColors.resolve(context, LhColors.mute),
                    weight: drawn || active ? FontWeight.w600 : FontWeight.w500,
                    height: 1.0,
                    letterSpacing: 0.2,
                    context: context,
                  ),
                ),
                if (active) ...[
                  const SizedBox(width: 6),
                  Text(
                    '${negative ? '−' : ''}$value',
                    maxLines: 1,
                    softWrap: false,
                    style: LhTypography.number(
                      size: 11.5,
                      color: negative
                          ? DunesColors.resolve(context, LhColors.pos)
                          : DunesColors.resolve(context, LhColors.ink),
                      context: context,
                    ).copyWith(fontWeight: FontWeight.w700, height: 1.0),
                  ),
                  if (momText != null) ...[
                    const SizedBox(width: 4),
                    Text(
                      momText,
                      maxLines: 1,
                      softWrap: false,
                      style:
                          LhTypography.mono(
                            size: lighthouseLedgerSummaryDeltaFontSize,
                            color: momColor,
                            weight: loudMom ? FontWeight.w700 : FontWeight.w600,
                            height: 1.0,
                            letterSpacing: -0.2,
                            context: context,
                          ).copyWith(
                            fontFeatures: const [FontFeature.tabularFigures()],
                          ),
                    ),
