  /// v16 · 图例格：一行一格 ——「标记 · 名称 …… 数值 环比」。
  ///   旧版每格两行、各带底色、宽窄不一还自由换行，五格排出来参差不齐，
  ///   名称 / 数值 / 环比三种字号互相打架。现在固定两列网格、同一行高，
  ///   数值和环比都右对齐成列，眼睛可以竖着扫。
  Widget _trendLegendChip({
    required String label,
    required Color color,
    required bool negative,
    required String absFmt,
    required String unitFmt,
    String? seriesKey,
    double? momPct,
  }) {
    final soloing = _soloKey != null;
    final active = seriesKey != null && _soloKey == seriesKey;
    final dimmed = soloing && !active;
    // 画在图上的那条（主线，或核销 / 销售那一对）。其余是纯数字。
    final drawn = seriesKey != null && _isDrawnSeries(seriesKey);
    final momUp = momPct != null && momPct >= 0;
    // 和下面那排指标格同一条规矩：默认走 ink2，越过 ±20% 或是利润 / 核销才上红绿。
    // （mute2 是暖灰，一排小字叠起来会泛黄，跟这张卡的冷底打架。）
    final deltaKey = seriesKey == 'profit'
        ? 'profit'
        : (label.contains('核销') ? 'verifiedSales' : (seriesKey ?? ''));
    final momColor = momPct == null
        ? DunesColors.resolve(context, LhColors.mute2)
        : (lighthouseHeroDeltaIsLoud(deltaKey, momPct)
              ? (momUp
                    ? DunesColors.resolve(context, LhColors.neg)
                    : DunesColors.resolve(context, LhColors.pos))
              : DunesColors.resolve(context, LhColors.ink2));
    const tabular = [FontFeature.tabularFigures()];
    final compact = MediaQuery.sizeOf(context).width < 430;
    final loudMom =
        momPct != null && lighthouseHeroDeltaIsLoud(deltaKey, momPct);
    if (widget.legendNamesOnly && seriesKey != null) {
      return _trendLegendNameChip(
        label: label,
        color: color,
        negative: negative,
        value: '$absFmt$unitFmt',
        seriesKey: seriesKey,
        momText: momPct == null
            ? null
            : '${momUp ? '↑' : '↓'}'
                  '${momPct.abs().toStringAsFixed(momPct.abs() >= 10 ? 0 : 1)}%',
        momColor: momColor,
        loudMom: loudMom,
      );
    }
    final cell = SizedBox(
      // v25 · 格子压矮一档：图例是一排读数，不是六张卡片，
      //   行高越接近文字本身，整块越像表、越不像框。
      height: compact ? 26 : 28,
      child: Row(
        children: [
          // 标记：画在图上的是一小段线（和图里的线同形），没画的只是一个灰点。
          SizedBox(
            width: compact ? 12 : 14,
            child: Center(
              child: drawn
                  ? Container(
                      width: compact ? 10 : 12,
                      height: 2.5,
                      decoration: BoxDecoration(
                        color: DunesColors.resolveNullable(
                          context,
                          color,
                          role: DunesColorRole.surface,
                        ),
                        borderRadius: BorderRadius.circular(1.5),
                      ),
                    )
                  : Container(
                      width: 4,
                      height: 4,
                      decoration: BoxDecoration(
                        color: DunesColors.resolve(
                          context,
                          LhColors.mute2,
                          role: DunesColorRole.surface,
                        ).withAlpha(110),
                        shape: BoxShape.circle,
                      ),
                    ),
            ),
          ),
          const SizedBox(width: 4),
          Expanded(
            child: label == '毛利率' && widget.grossMarginFormula != null
                ? LighthouseGrossMarginLabel(
                    formula: widget.grossMarginFormula!,
                  )
                : LhScrollText(
                    label,
                    maxLines: 1,
                    overflow: TextOverflow.ellipsis,
                    // 标签字号 / 字重跟账本摘要格同一档，不自造一套大字。
                    style: LhTypography.sans(
                      size: compact ? 9.5 : lighthouseLedgerMetricLabelFontSize,
                      color: drawn || active
                          ? DunesColors.resolve(context, LhColors.ink2)
                          : DunesColors.resolve(context, LhColors.mute2),
                      weight: drawn || active
                          ? FontWeight.w600
                          : FontWeight.w500,
                      height: 1.0,
                      letterSpacing: 0.2,
                      context: context,
                    ),
                  ),
          ),
          const SizedBox(width: 6),
          // 数值在窄屏仍完整显示；长数字只缩这一项，不挤掉其他指标。
          Flexible(
            child: FittedBox(
              fit: BoxFit.scaleDown,
              alignment: Alignment.centerRight,
              child: Text(
                '${negative ? '−' : ''}$absFmt$unitFmt',
                maxLines: 1,
                softWrap: false,
                // v25 · 数字一律走墨色，不再给「画在图上的那条」换成紫。
                //   色相在 11px 下只表达「另一类」，不表达「更重要」（见
                //   lighthouseTrendEmphasisInk 处 v19 的说明）；身份交给左边
                //   那截线，轻重交给字重。负数仍按全站规矩走绿。
                style:
                    LhTypography.number(
                      size: compact ? 11 : lighthouseLedgerValueFontSize,
                      color: negative
                          ? DunesColors.resolve(context, LhColors.pos)
                          : DunesColors.resolve(context, LhColors.ink),
                      context: context,
                    ).copyWith(
                      fontWeight: drawn || active
                          ? FontWeight.w700
                          : FontWeight.w600,
                      height: 1.0,
                    ),
              ),
            ),
          ),
          // 环比压成短写（≥10% 不留小数，与大数下面那行同规则），给名称让宽度。
          SizedBox(
            width: compact ? 34 : 40,
            child: FittedBox(
              fit: BoxFit.scaleDown,
              alignment: Alignment.centerRight,
              child: Text(
                momPct == null
                    ? ''
                    : '${momUp ? '↑' : '↓'}'
                          '${momPct.abs().toStringAsFixed(momPct.abs() >= 10 ? 0 : 1)}%',
                maxLines: 1,
                softWrap: false,
                textAlign: TextAlign.right,
                style: LhTypography.mono(
                  size: lighthouseLedgerSummaryDeltaFontSize,
                  color: momColor,
                  weight: loudMom ? FontWeight.w700 : FontWeight.w600,
                  height: 1.0,
                  letterSpacing: -0.2,
                  context: context,
                ).copyWith(fontFeatures: tabular),
              ),
            ),
          ),
        ],
      ),
    );
    if (seriesKey == null) return cell;
    return GestureDetector(
      behavior: HitTestBehavior.opaque,
      onTap: () => _toggleSolo(seriesKey),
      child: AnimatedOpacity(
        opacity: dimmed ? 0.55 : 1,
        duration: const Duration(milliseconds: 180),
        curve: Curves.easeOutCubic,
        child: AnimatedContainer(
          duration: const Duration(milliseconds: 160),
          curve: Curves.easeOut,
          // 选中态跟账本摘要格一样「浮起来」：白底 + 淡紫细边 + 轻投影，
          // 平时不给每格各自描边铺底 —— 底面交给外面那块面板。
          // 只做水平 inset，上下再缩会让整行高度跳动。
          margin: EdgeInsets.symmetric(
            horizontal: active ? lighthouseLedgerSummaryActiveInsetH : 0.0,
          ),
          padding: EdgeInsets.symmetric(horizontal: active ? 6 : 8),
          decoration: BoxDecoration(
            // 面板改白之后，选中态不能再靠「更白」浮起来：翻过来用淡紫面，
            // 边和投影仍是账本那一套。
            color: active
                ? DunesColors.resolve(
                    context,
                    _LhPlum.mist,
                    role: DunesColorRole.surface,
                  )
                : Colors.transparent,
            borderRadius: BorderRadius.circular(8),
            border: Border.all(
              color: active
                  ? DunesColors.resolve(
                      context,
                      _LhPlum.primary,
                      role: DunesColorRole.border,
                    ).withAlpha(46)
                  : Colors.transparent,
              width: 0.8,
            ),
            boxShadow: active
                ? [
                    BoxShadow(
                      color: _LhPlum.deep.withAlpha(28),
                      blurRadius: 6,
                      offset: const Offset(0, 1.5),
                    ),
                  ]
                : null,
          ),
          child: cell,
        ),
      ),
    );
  }

  @override
  Widget build(BuildContext context) {
    final si = _selectedIndex;
    final isSelected = si != null && si >= 0 && si < _n;
    final compactLegend = MediaQuery.sizeOf(context).width < 430;

    double at(List<double> l, int i) => (i >= 0 && i < l.length) ? l[i] : 0;
    final rVal = isSelected ? at(_series.revenue, si) : _totRev;
    final cVal = isSelected ? at(_series.cost, si) : _totCost;
    final pVal = isSelected ? at(_series.profit, si) : _totProf;
    // 全屏大图没点中某天时，不写「本期合计」，写数据时间（2026年10月12日 19:22）。
    final statusText = (isSelected && si < _pointLabels.length)
        ? (widget.legendCompact ? _fullDateLabel(si) : _pointLabels[si])
        : (widget.legendCompact && widget.statusStamp != null
              ? widget.statusStamp!
              : '本期合计');

    final sVal = isSelected ? at(_series.scale, si) : _totScale;
    final sAltVal = isSelected ? at(_series.scaleAlt, si) : _totScaleAlt;
    final caVal = isSelected ? at(_series.costAlt, si) : _totCostAlt;
    final stVal = isSelected ? at(_series.stock, si) : _totStock;
    final sAbsFmt = _fmtHeroAbs(sVal.abs());
    final sUnitFmt = _fmtHeroUnit(sVal.abs());
    final sAltAbsFmt = _fmtHeroAbs(sAltVal.abs());
    final sAltUnitFmt = _fmtHeroUnit(sAltVal.abs());
    final caAbsFmt = _fmtHeroAbs(caVal.abs());
    final caUnitFmt = _fmtHeroUnit(caVal.abs());
    final stAbsFmt = _fmtHeroAbs(stVal.abs());
    final stUnitFmt = _fmtHeroUnit(stVal.abs());
    final pIsNeg = pVal < 0;
    final pAbsFmt = _fmtHeroAbs(pVal.abs());
    final pUnitFmt = _fmtHeroUnit(pVal.abs());
    final rAbsFmt = _fmtHeroAbs(rVal.abs());
    final rUnitFmt = _fmtHeroUnit(rVal.abs());
    final cAbsFmt = _fmtHeroAbs(cVal.abs());
    final cUnitFmt = _fmtHeroUnit(cVal.abs());

    final pnlLegendKeys = lighthouseTrendPnlLegendKeys(
      hasScale: _hasScale,
      hasStock: _hasStock,
      hasProfit: _hasProf,
      hasCostAlt: _hasCostAlt,
      hasRevenue: _hasRev || rVal.abs() > 1e-9,
      hasCost: _hasCost || cVal.abs() > 1e-9,
      hasScaleAlt: _hasScaleAlt,
    );
    final editorialLegend = Column(
      crossAxisAlignment: CrossAxisAlignment.start,
      children: [
        // 头一行不铺底不描边：一根色条 + 期间字，和展开体里「左侧色条 +
        // 发丝线」同一套层级手法。
        Padding(
          padding: const EdgeInsets.fromLTRB(2, 0, 2, 0),
          child: Row(
            crossAxisAlignment: CrossAxisAlignment.center,
            children: [
              Text(
                statusText,
                style: LhTypography.mono(
                  size: 9.5,
                  color: isSelected
                      ? DunesColors.resolve(context, _LhPlum.deep)
                      : DunesColors.resolve(context, LhColors.ink2),
                  weight: FontWeight.w700,
                  letterSpacing: 0.5,
                  context: context,
                ),
              ),
              if (!compactLegend && !widget.legendCompact) ...[
                const SizedBox(width: 8),
                Text(
                  _soloKey == null ? '点指标切换曲线' : '已聚焦单项',
                  style: LhTypography.sans(
                    size: 9,
                    color: DunesColors.resolve(context, LhColors.mute2),
                    weight: FontWeight.w500,
                    context: context,
                  ),
                ),
              ],
              const Spacer(),
              // 「看全部」只在 solo 了某一条时出现 —— 平时它是一个点不动的词。
              if (widget.showClearSolo &&
                  !widget.legendCompact &&
                  _soloKey != null &&
                  pnlLegendKeys.length > 1)
                GestureDetector(
                  behavior: HitTestBehavior.opaque,
                  onTap: _clearSolo,
                  child: Padding(
                    padding: const EdgeInsets.symmetric(
                      horizontal: 4,
                      vertical: 2,
                    ),
                    child: Text(
                      '显示全部',
                      style: LhTypography.mono(
                        size: 9.5,
                        color: DunesColors.resolve(context, _LhPlum.primary),
                        weight: FontWeight.w700,
                        letterSpacing: 0.4,
                        context: context,
                      ),
                    ),
                  ),
                ),
              if (isSelected)
                GestureDetector(
                  behavior: HitTestBehavior.opaque,
                  onTap: _clearSelection,

                  child: Padding(
                    padding: EdgeInsets.all(2),
                    child: Icon(
                      Icons.close_rounded,
                      size: 14,
                      color: DunesColors.resolve(context, LhColors.mute2),
                    ),
                  ),
                ),
              if (widget.onExpand != null) _trendExpandButton(widget.onExpand!),
              if (widget.legendTrailing case final trailing?) ...[
                const SizedBox(width: 8),
                // 贴最右：Align 吃满分到的宽度，把分组签顶到右沿。
                Flexible(
                  flex: 3,
                  child: Align(
                    alignment: Alignment.centerRight,
                    child: trailing,
                  ),
                ),
              ],
            ],
          ),
        ),
        if (pnlLegendKeys.isNotEmpty && !widget.legendCompact) ...[
          const SizedBox(height: 8),
          LayoutBuilder(
            builder: (context, legendBox) {
              Widget chipFor(String key) => switch (key) {
                'scale' => _trendLegendChip(
                  label: widget.scaleLabel,
                  color: _legendAccent('scale', _cScale),
                  negative: _legendNegative('scale', sVal < 0),
                  absFmt: sAbsFmt,
                  unitFmt: sUnitFmt,
                  seriesKey: 'scale',
                  momPct: lighthouseTrendMomPct(
                    periodDeltaPct: widget.periodScaleDeltaPct,
                    partialPeriod: widget.partialPeriod,
                    selectedIndex: _selectedIndex,
                    suppressPointMom: widget.suppressPointMom,
                    series: _series.scale,
                  ),
                ),
                'stock' => _trendLegendChip(
                  label: widget.stockLabel,
                  color: _legendAccent('stock', _cStock),
                  negative: _legendNegative('stock', stVal < 0),
                  absFmt: stAbsFmt,
                  unitFmt: stUnitFmt,
                  seriesKey: 'stock',
                  momPct: lighthouseTrendMomPct(
                    periodDeltaPct: widget.periodStockDeltaPct,
                    partialPeriod: widget.partialPeriod,
                    selectedIndex: _selectedIndex,
                    suppressPointMom: widget.suppressPointMom,
                    series: _series.stock,
                  ),
                ),
                'profit' => _trendLegendChip(
                  label: widget.profitLabel,
                  color: _legendAccent('profit', _cProf),
                  negative: _legendNegative('profit', pIsNeg),
                  absFmt: pAbsFmt,
                  unitFmt: pUnitFmt,
                  seriesKey: 'profit',
                  momPct: lighthouseTrendMomPct(
                    periodDeltaPct: widget.periodProfitDeltaPct,
                    partialPeriod: widget.partialPeriod,
                    selectedIndex: _selectedIndex,
                    suppressPointMom: widget.suppressPointMom,
                    series: _series.profit,
                  ),
                ),
                'costAlt' => _trendLegendChip(
                  label: widget.costAltLabel,
                  color: _legendAccent('costAlt', _cCostAlt),
                  negative: _legendNegative('costAlt', caVal < 0),
                  absFmt: caAbsFmt,
                  unitFmt: caUnitFmt,
                  seriesKey: 'costAlt',
                  momPct: lighthouseTrendMomPct(
                    periodDeltaPct: widget.periodCostAltDeltaPct,
                    partialPeriod: widget.partialPeriod,
                    selectedIndex: _selectedIndex,
                    suppressPointMom: widget.suppressPointMom,
                    series: _series.costAlt,
                  ),
                ),
                'revenue' => _trendLegendChip(
                  label: widget.revenueLabel,
                  color: _legendAccent('revenue', _cRev),
                  negative: _legendNegative('revenue', rVal < 0),
                  absFmt: rAbsFmt,
                  unitFmt: rUnitFmt,
                  seriesKey: 'revenue',
                  momPct: lighthouseTrendMomPct(
                    periodDeltaPct: widget.periodRevenueDeltaPct,
                    partialPeriod: widget.partialPeriod,
                    selectedIndex: _selectedIndex,
                    suppressPointMom: widget.suppressPointMom,
                    series: _series.revenue,
                  ),
                ),
                'cost' => _trendLegendChip(
                  label: widget.costLabel,
                  color: _legendAccent('cost', _cCost),
                  negative: _legendNegative('cost', cVal < 0),
                  absFmt: cAbsFmt,
                  unitFmt: cUnitFmt,
                  seriesKey: 'cost',
                  momPct: lighthouseTrendMomPct(
                    periodDeltaPct: widget.periodCostDeltaPct,
                    partialPeriod: widget.partialPeriod,
                    selectedIndex: _selectedIndex,
                    suppressPointMom: widget.suppressPointMom,
                    series: _series.cost,
                  ),
                ),
                'scaleAlt' => _trendLegendChip(
                  label: widget.scaleAltLabel,
                  color: _legendAccent('scaleAlt', _cScale),
                  negative: _legendNegative('scaleAlt', sAltVal < 0),
                  absFmt: sAltAbsFmt,
                  unitFmt: sAltUnitFmt,
                  seriesKey: 'scaleAlt',
                  momPct: lighthouseTrendMomPct(
                    periodDeltaPct: widget.periodScaleAltDeltaPct,
                    partialPeriod: widget.partialPeriod,
                    selectedIndex: _selectedIndex,
                    suppressPointMom: widget.suppressPointMom,
                    series: _series.scaleAlt,
                  ),
                ),
                _ => const SizedBox.shrink(),
              };
              // 规模一对（核销 / 销售）排在一起打头，其余按原顺序。
              final keys = <String>[
                for (final k in pnlLegendKeys)
                  if (k == 'scale' || k == 'scaleAlt') k,
                for (final k in pnlLegendKeys)
                  if (k != 'scale' && k != 'scaleAlt') k,
              ];
              if (widget.legendNamesOnly) {
                return Wrap(
                  spacing: 6,
                  runSpacing: 6,
                  children: [for (final k in keys) chipFor(k)],
                );
              }
              final cols = keys.length <= 1
                  ? 1
                  : (legendBox.maxWidth >= 460 ? 3 : 2);
              // v24 · 几格拼成一块面板：行与行、列与列只用内缩发丝线分隔，
              //   不给每格各自描边铺底（和账本卡片摘要格 v23 同一套皮）。
              // v25 · 面板改白：趋势卡本身就是 F7F6FA，面板再铺同一个灰
              //   等于没铺，整块糊成一片。账本那边是「白卡 + 灰面板」，
              //   这里是灰卡，那就反过来 —— 差的是那一层，不是那个色。
              return Container(
                padding: const EdgeInsets.symmetric(vertical: 2),
                decoration: BoxDecoration(
                  color: DunesColors.resolve(
                    context,
                    LhColors.paper,
                    role: DunesColorRole.surface,
                  ),
                  borderRadius: BorderRadius.circular(
                    lighthouseLedgerSummaryPanelRadius,
                  ),
                ),
                child: Column(
                  crossAxisAlignment: CrossAxisAlignment.stretch,
                  children: [
                    for (var i = 0; i < keys.length; i += cols) ...[
                      if (i > 0)
                        Container(
                          height: lighthouseLedgerSummaryRowDividerHeight,
                          margin: const EdgeInsets.symmetric(
                            horizontal: lighthouseLedgerSummaryDividerInset,
                          ),
                          // Hero 里的发丝线走紫（全页 hairline 的规矩）：
                          // line2 是暖米色，铺在白面板上会泛黄。
                          color: DunesColors.resolve(
                            context,
                            _LhPlum.line,
                            role: DunesColorRole.surface,
                          ),
                        ),
                      Row(
                        children: [
                          for (var c = 0; c < cols; c++) ...[
                            // 末行缺格时不画那根孤零零的竖发丝线。
                            if (c > 0 && i + c < keys.length)
                              Container(
                                width: lighthouseLedgerSummaryRowDividerHeight,
                                height: 14,
                                color: DunesColors.resolve(
                                  context,
                                  _LhPlum.line,
                                  role: DunesColorRole.surface,
                                ),
                              ),
                            Expanded(
                              child: i + c < keys.length
                                  ? chipFor(keys[i + c])
                                  : const SizedBox.shrink(),
                            ),
                          ],
                        ],
                      ),
                    ],
                  ],
                ),
              );
            },
          ),
        ],
      ],
    );

    return Column(
      mainAxisSize: widget.fitHeight ? MainAxisSize.max : MainAxisSize.min,
      crossAxisAlignment: CrossAxisAlignment.start,
      children: [
        if (widget.showHeader) ...[
          Row(
            mainAxisAlignment: MainAxisAlignment.spaceBetween,
            children: [
              Text(
                widget.title,
                style: LhTypography.mono(
                  size: 9.5,
                  color: DunesColors.resolve(context, LhColors.mute),
                  weight: FontWeight.w600,
                  letterSpacing: 1.2,
                  context: context,
                ),
              ),
              Text(
                widget.rangeLabel,
                style: LhTypography.mono(
                  size: 9,
                  color: DunesColors.resolve(context, LhColors.mute2),
                  weight: FontWeight.w500,
                  letterSpacing: 0.3,
                  context: context,
                ),
              ),
            ],
          ),
          const SizedBox(height: 8),
        ],
        if (widget.showLegend) editorialLegend,
        // 全屏大图：读数单独一行（手机上跟按钮挤一行会被截成「4…」）。
        if (widget.showLegend && widget.legendCompact) ...[
          const SizedBox(height: 6),
          // 左：主线读数；右：涨跌胶囊，右沿跟上一行的分组签对齐。
          SizedBox(
            height: 26,
            child: Row(
              crossAxisAlignment: CrossAxisAlignment.center,
              children: [
                Expanded(
                  child: Align(
                    alignment: Alignment.centerLeft,
                    child: _compactReadout(
                      rVal: rVal,
                      cVal: cVal,
                      pVal: pVal,
                      sVal: sVal,
                      sAltVal: sAltVal,
                      caVal: caVal,
                      stVal: stVal,
                    ),
                  ),
                ),
                if (widget.candles) ...[
                  const SizedBox(width: 8),
                  _dayChangeTag(),
                ],
              ],
            ),
          ),
        ],
        if (widget.candles) ...[const SizedBox(height: 6), _windowStats()],
        if (widget.formulaExpression != null &&
            widget.formulaExpression!.trim().isNotEmpty) ...[
          const SizedBox(height: 6),
          _trendFormulaInline(widget.formulaExpression!),
        ],
        if (!widget.legendCompact)
          if (_stripForecast case final sf?) ...[
            const SizedBox(height: 7),
            _forecastStrip(
              sf.f,
              prev: sf.prev,
              prevLabel: sf.prevLabel,
              profit: sf.profit,
            ),
          ],
        const SizedBox(height: 10),
        if (widget.fitHeight)
          Expanded(
            child: Padding(
              padding: EdgeInsets.only(
                left: widget.candles ? _kCandleAxisGutter : 0,
              ),
              child: _trendCanvas(),
            ),
          )
        else
          _trendCanvas(),
        const SizedBox(height: 4),
        Container(
          height: 14,
          padding: EdgeInsets.only(
            left: widget.candles ? _kCandleAxisGutter : 0,
          ),
          child: Stack(
            clipBehavior: Clip.none,
            children: [
              Positioned.fill(
                child: LayoutBuilder(
                  builder: (ctx, c) {
                    final w =
                        c.maxWidth -
                        _futureGutterW(c.maxWidth, _futureShown.length);
                    final usableW = w - _kChartPadH * 2;
                    final n = _n;
                    if (_windowed) {
                      // 视窗模式：标签跟着点平移，只摆看得见的那几个。
                      final step = _stepFor(w);
                      final vs = _viewStart;
                      final slotW = widget.zoomable
                          ? 44.0
                          : (usableW / _visible).clamp(18.0, 32.0);
                      final labelSize = widget.zoomable
                          ? 8.5
                          : (_visible > 12 ? 7.0 : (_visible > 8 ? 7.5 : 8.5));
                      final first = math.max(0, vs.floor());
                      final last = math.min(n - 1, _viewEnd.ceil());
                      return ClipRect(
                        child: Stack(
                          children: [
                            for (
                              int i = first;
                              i <= last && i < _xLabels.length;
                              i++
                            )
                              if (_xLabelShown(i, step))
                                Positioned(
                                  // 点在视窗里的那几个标签贴边收进来，不让 ClipRect
                                  // 把最后一天（本期）裁成半个字；滑出视窗的照旧跟着走。
                                  left: () {
                                    final cx = _kChartPadH + (i - vs) * step;
                                    final raw = cx - slotW / 2;
                                    if (cx < 0 || cx > w) return raw;
                                    return raw
                                        .clamp(0.0, math.max(0.0, w - slotW))
                                        .toDouble();
                                  }(),
                                  width: slotW,
                                  child: Center(
                                    child: Text(
                                      widget.zoomable
                                          ? _zoomLabel(i)
                                          : _xLabels[i],
                                      maxLines: 1,
                                      overflow: TextOverflow.ellipsis,
                                      style: LhTypography.mono(
                                        size: labelSize,
                                        color:
                                            widget.partialPeriod && i == n - 1
                                            ? DunesColors.resolve(
                                                ctx,
                                                _LhPlum.deep,
                                              )
                                            : (widget.zoomable &&
                                                      _isMonthStart(i)
                                                  ? DunesColors.resolve(
                                                      ctx,
                                                      LhColors.ink2,
                                                    )
                                                  : DunesColors.resolve(
                                                      ctx,
                                                      LhColors.mute2,
                                                    )),
                                        weight:
                                            (widget.partialPeriod &&
                                                    i == n - 1) ||
                                                (widget.zoomable &&
                                                    _isMonthStart(i))
                                            ? FontWeight.w700
                                            : FontWeight.w500,
                                        letterSpacing: 0.1,
                                        context: ctx,
                                      ),
                                    ),
                                  ),
                                ),
                          ],
                        ),
                      );
                    }
                    final labelCount = _xAnchors.length;
                    final slotW = labelCount <= 1
                        ? usableW
                        : (widget.zoomable
                              ? 44.0
                              : (usableW / labelCount).clamp(18.0, 32.0));
                    final labelSize = widget.zoomable
                        ? 8.5
                        : (labelCount > 12
                              ? 7.0
                              : (labelCount > 8 ? 7.5 : 8.5));
                    final pxPerPoint = n <= 1 ? 0.0 : usableW / (n - 1);
                    bool currentAnchor(int i) =>
                        widget.partialPeriod && n > 0 && _xAnchors[i] == n - 1;
                    return Stack(
                      children: [
                        for (int i = 0; i < _xAnchors.length; i++)
                          if (_xLabelShown(_xAnchors[i], pxPerPoint))
                            Positioned(
                              left:
                                  (labelCount <= 1 || n <= 1
                                          ? _kChartPadH
                                          : _kChartPadH +
                                                _xAnchors[i] /
                                                    (n - 1) *
                                                    usableW -
                                                slotW / 2)
                                      .clamp(
                                        0.0,
                                        (w - slotW).clamp(0.0, double.infinity),
                                      ),
                              width: slotW,
                              child: Center(
                                child: Text(
                                  widget.zoomable
                                      ? _zoomLabel(_xAnchors[i])
                                      : _xLabels[i],
                                  maxLines: 1,
                                  overflow: TextOverflow.ellipsis,
                                  // v16 · 本期（没走完的那一列）标签用主色加粗，
                                  // 和进度胶囊呼应，一眼找到「现在」在哪。
                                  style: LhTypography.mono(
                                    size: labelSize,
                                    color: currentAnchor(i)
                                        ? DunesColors.resolve(ctx, _LhPlum.deep)
                                        : DunesColors.resolve(
                                            ctx,
                                            LhColors.mute2,
                                          ),
                                    weight: currentAnchor(i)
                                        ? FontWeight.w700
                                        : FontWeight.w500,
                                    letterSpacing: 0.1,
                                    context: ctx,
                                  ),
                                ),
                              ),
                            ),
                      ],
                    );
                  },
                ),
              ),
              _futureAxisLabels(),
            ],
          ),
        ),
        if (widget.candles) ...[
          const SizedBox(height: 10),
          _candleLegend(),
          const SizedBox(height: 4),
        ],
        if (widget.showScrubHint) ...[
          const SizedBox(height: 4),
          SizedBox(
            height: 12,
            child: isSelected
                ? const SizedBox.shrink()
                : Text(
                    _viewportMode ? '拖动翻看历史 · 长按查看每点' : '拖动查看每点',
                    style: LhTypography.sans(
                      size: 9,
                      color: DunesColors.resolve(context, LhColors.mute2),
                      weight: FontWeight.w500,
                      letterSpacing: 0.4,
                      context: context,
                    ),
                  ),
          ),
        ],
      ],
    );
  }
}

/// Hero 单指标趋势图：点哪个格只看那一条线，交互与列表 _TrendChart 一致。
class _HeroMetricTrendChart extends StatefulWidget {
  const _HeroMetricTrendChart({
    required this.labels,
    required this.data,
    required this.metricLabel,
    required this.color,
    required this.isRate,
    required this.periodValue,
    this.expected,
    this.expectedColor,
    this.violationTint,
    this.warnTint,
    this.compareData,
    this.forecast,
    this.paceDays,
    this.periodDeltaPct,
    this.partialPeriod = false,
    this.chartHeight = 168,
    this.onInteractionChanged,
    this.grossMarginFormula,
  });

  final List<String> labels;
  final List<double> data;
  final String metricLabel;
  final String? grossMarginFormula;
  final Color color;
  final bool isRate;
  final double periodValue;
  final double? expected;
  final Color? expectedColor;
  final Color? violationTint; // breach 带 tint
  final Color? warnTint; // warn 带 tint
  final List<double>? compareData;

  /// 月化预测（仅点月 + 当前月 + 规模/金额类）。非空时画月末预测虚线。
  final LighthousePaceForecast? forecast;

  /// 当月已过天数 / 当月天数 —— 利润盈亏柱外推月末用。
  final ({int elapsed, int total})? paceDays;

  /// 本期环比（%，比率类为 pp），带符号，由后端按同期对齐窗口算出。
  ///
  /// 走势序列在点月时是「整月桶」：末位是本月未走完的 MTD，末位前一格是上月
  /// 整月。拿这两格相减，就是 2026-08 运营会当场否掉的口径，所以「本期合计」
  /// 态的环比必须走这个字段，而不是自己拿序列减。
  final double? periodDeltaPct;

  /// 本期是否还没走完（当前月/周看到一半）。
  /// 为 true 且没有 [periodDeltaPct] 时，宁可不显示环比，也不显示错的。
  final bool partialPeriod;
  final double chartHeight;
  final ValueChanged<bool>? onInteractionChanged;

  @override
  State<_HeroMetricTrendChart> createState() => _HeroMetricTrendChartState();
}

class _HeroMetricTrendChartState extends State<_HeroMetricTrendChart> {
  static const double _padLeft = 28;
  static const double _padRight = 6;
  int? _selectedIndex;

  // ═══════════════════════════════════════════════════════════════════════
  // 指标公式表 (点开折线后 "本期合计" 右边展示, 科研论文式)
  //   ≡ 是定义符 (identity/definition), 术语 ink2 中性, 运算符 + 字面量 accent 高亮
  //   会议原话:"想把每个对应的公式规规整整的写到本期合计的右边，有科研感"
  // ═══════════════════════════════════════════════════════════════════════
  static const _kMetricFormulas = <String, String>{
    '销售额': '下单张数 × 面值',
    '核销额': '核销张数 × 面值',
    '核销规模': '核销张数 × 面值',
    '销售规模': '下单张数 × 面值',
    'GMV': '撮合交易额',
    '预收净增': '销售额 − 核销额',
    '利差率': '收入 ÷ 核销规模 × 100%',
    '利差': '已核销利差',
    '收入': '核销额 × 利差率',
    '收入（已核销利差）': '核销规模 × 利差率',
    '经营成本': '业务成本',
    '业务成本': '账单三级 BUSINESS_COST',
    '项目成本': '利润对应成本',
    '税务成本': '收入 × 5%',
    '成本': '项目成本 + 业务成本',
    '成本合计': '项目成本 + 业务成本',
    '利润': '收入 − 成本合计',
    '毛利率': '利润 ÷ 核销额 × 100%',
    '净利': '利润 − 业务成本',
    '净利润': '利润 − 业务成本',
    'ROI': '利润 ÷ 成本合计 × 100%',
  };

  /// 内联公式渲染 — mono LaTeX 感, 分色 tokens.
  ///   ≡ (定义符): accent bold
  ///   运算符 (÷ × − + =): accent bold
  ///   字面量 (100%, 5%): accent semi-bold
  ///   术语 (收入, 核销规模 等): ink2 中性
  Widget _buildFormulaInline(String metricLabel, Color accent) {
    final formula = metricLabel == '毛利率' && widget.grossMarginFormula != null
        ? '${widget.grossMarginFormula} × 100%'
        : _kMetricFormulas[metricLabel];
    if (formula == null || formula.isEmpty) return const SizedBox.shrink();

    final tokens = formula
        .split(' ')
        .where((t) => t.isNotEmpty)
        .toList(growable: false);

    bool isOperator(String t) => t.length == 1 && '÷×−+='.contains(t);
    bool isLiteral(String t) => RegExp(r'^\d+(\.\d+)?%?$').hasMatch(t);

    final spans = <TextSpan>[
      TextSpan(
        text: '≡  ',
        style: LhTypography.mono(
          size: 11,
          color: accent,
          weight: FontWeight.w800,
          letterSpacing: 0.4,
          context: context,
        ),
      ),
    ];

    for (int i = 0; i < tokens.length; i++) {
      final t = tokens[i];
      final Color color;
      final FontWeight weight;
      if (isOperator(t)) {
        color = accent;
        weight = FontWeight.w800;
      } else if (isLiteral(t)) {
        color = accent;
        weight = FontWeight.w700;
      } else {
        color = DunesColors.resolve(context, LhColors.ink2);
        weight = FontWeight.w600;
      }
      spans.add(
        TextSpan(
          text: t,
          style: LhTypography.mono(
            size: 10,
            color: color,
            weight: weight,
            letterSpacing: 0.3,
            context: context,
          ),
        ),
      );
      if (i < tokens.length - 1) {
        spans.add(const TextSpan(text: '  '));
      }
    }

    return LhScrollRichText(
      maxLines: 1,
      overflow: TextOverflow.ellipsis,
      text: TextSpan(children: spans),
    );
  }

  void _notifyInteraction(bool active) {
    widget.onInteractionChanged?.call(active);
  }

  void _setSelectionFromX(double localX, double widthPx) {
    final n = widget.data.length;
    final usable = widthPx - _padLeft - _padRight;
    if (usable <= 0 || n <= 0) return;
    final relX = (localX - _padLeft).clamp(0.0, usable);
    final i = n <= 1 ? 0 : ((relX / usable) * (n - 1)).round().clamp(0, n - 1);
    if (_selectedIndex != i) setState(() => _selectedIndex = i);
  }

  void _clearSelection() {
    if (_selectedIndex != null) setState(() => _selectedIndex = null);
  }

  String _formatValue(double v) {
    if (widget.isRate) return '${v.toStringAsFixed(2)}%';
    return '${_fmtMoney(v)}${_unitMoney(v)}';
  }

  @override
  Widget build(BuildContext context) {
    if (widget.data.isEmpty) {
      return Padding(
        padding: const EdgeInsets.symmetric(vertical: 28),
        child: Center(
          child: Text(
            '暂无趋势数据',
            style: LhTypography.sans(
              size: 11,
              color: DunesColors.resolve(context, LhColors.mute),
              context: context,
            ),
          ),
        ),
      );
    }

    final chartData = widget.data.length >= 2
        ? widget.data
        : [widget.data.first, widget.data.first];

    final si = _selectedIndex;
    final isSelected = si != null && si >= 0 && si < chartData.length;
    final displayValue = isSelected ? chartData[si] : widget.periodValue;
    final statusText = isSelected && si < widget.labels.length
        ? widget.labels[si]
        : '本期合计';

    final stats = _computeStats(chartData);
    final isProfitMetric =
        !widget.isRate &&
        (widget.metricLabel.contains('利润') ||
            widget.metricLabel.contains('利润'));

    return Column(
      crossAxisAlignment: CrossAxisAlignment.stretch,
      children: [
        // ═══════════════════════════════════════════════════════════
        // § 1. Editorial header — hero 大数字 + 铜色 accent 下划线 + 公式
        // ═══════════════════════════════════════════════════════════
        _buildEditorialHeader(
          isSelected: isSelected,
          displayValue: displayValue,
          statusText: statusText,
        ),

        const SizedBox(height: 8),

        // ═══════════════════════════════════════════════════════════
        // § 2. Trend chart — 与主 Hero 共用同一套线、网格和色调
        // ═══════════════════════════════════════════════════════════
        // 单指标弹层直接复用主 Hero 的线、网格、渐变和点选逻辑。
        _TrendChart(
          labels: widget.labels,
          grossMarginFormula: widget.grossMarginFormula,
          revenue: const <double>[],
          cost: const <double>[],
          profit: isProfitMetric ? chartData : const <double>[],
          scale: isProfitMetric ? const <double>[] : chartData,
          scaleLabel: widget.metricLabel,
          profitLabel: widget.metricLabel,
          periodProfit: isProfitMetric ? widget.periodValue : null,
          periodScale: isProfitMetric ? null : widget.periodValue,
          periodProfitDeltaPct: isProfitMetric ? widget.periodDeltaPct : null,
          periodScaleDeltaPct: isProfitMetric ? null : widget.periodDeltaPct,
          scaleForecast: isProfitMetric ? null : widget.forecast,
          paceDays: widget.paceDays,
          rangeLabel: '',
          title: widget.metricLabel,
          showHeader: false,
          // 指标详情和主 Hero 用同一张图例：名称、数值、环比的读法不变。
          showLegend: true,
          showExtremeLabels: false,
          showScrubHint: false,
          chartHeight: widget.chartHeight,
          valueIsRate: widget.isRate,
          partialPeriod: widget.partialPeriod,
          selectedIndex: _selectedIndex,
          onSelectedIndexChanged: (index) {
            if (_selectedIndex != index) setState(() => _selectedIndex = index);
          },
          onInteractionChanged: _notifyInteraction,
        ),

        const SizedBox(height: 14),

        // ═══════════════════════════════════════════════════════════
        // § 3. Stats bar — MIN / AVG / MAX / 本期 (4 列 hairline 分隔)
        // ═══════════════════════════════════════════════════════════
        _buildStatsBar(stats, displayValue, isSelected),

        const SizedBox(height: 10),

        // ═══════════════════════════════════════════════════════════
        // § 4. Insight line — 本期 vs 均值 · 分位区间
        // ═══════════════════════════════════════════════════════════
        _buildInsightLine(displayValue, stats),

        const SizedBox(height: 12),

        // ═══════════════════════════════════════════════════════════
        // § 5. Swipe hint — 极简 mono 一行
        // ═══════════════════════════════════════════════════════════
        _buildSwipeHint(isSelected),
      ],
    );
  }

  // ═══════════════════════════════════════════════════════════════════════
  //   Editorial header —— 大数字 + accent 下划线 + 公式 + 环比 delta
  //   编辑体铜纸墨: paper 底, ink 主字, mute mono meta, copper accent bar
  // ═══════════════════════════════════════════════════════════════════════
  Widget _buildEditorialHeader({
    required bool isSelected,
    required double displayValue,
    required String statusText,
  }) {
    final ({String text, Color color, IconData icon})? delta = _computeDelta(
      isSelected: isSelected,
      displayValue: displayValue,
    );
    final absFmt = widget.isRate
        ? displayValue.abs().toStringAsFixed(2)
        : _fmtMoney(displayValue.abs());
    final unitFmt = widget.isRate ? '%' : _unitMoney(displayValue.abs());
    final valueStyle = LhTypography.mono(
      size: 9,
      color: displayValue < 0
          ? DunesColors.resolve(context, LhColors.pos)
          : widget.color,
      weight: FontWeight.w700,
      height: 1.0,
      context: context,
    );

    return Column(
      crossAxisAlignment: CrossAxisAlignment.start,
      children: [
        Row(
          crossAxisAlignment: CrossAxisAlignment.center,
          children: [
            Text(
              statusText,
              style: LhTypography.mono(
                size: 8.5,
                color: isSelected
                    ? widget.color
                    : DunesColors.resolve(context, LhColors.mute2),
                weight: FontWeight.w700,
                letterSpacing: 0.8,
                context: context,
              ),
            ),
            const Spacer(),
            if (isSelected)
              GestureDetector(
                behavior: HitTestBehavior.opaque,
                onTap: _clearSelection,
                child: Padding(
                  padding: EdgeInsets.all(2),
                  child: Icon(
                    Icons.close_rounded,
                    size: 11,
                    color: DunesColors.resolve(context, LhColors.mute2),
                  ),
                ),
              ),
          ],
        ),
        const SizedBox(height: 6),
        Column(
          crossAxisAlignment: CrossAxisAlignment.start,
          mainAxisSize: MainAxisSize.min,
          children: [
            Row(
              mainAxisSize: MainAxisSize.min,
              children: [
                Container(
                  width: 10,
                  height: 2.5,
                  decoration: BoxDecoration(
                    color: DunesColors.resolveNullable(
                      context,
                      widget.color,
                      role: DunesColorRole.surface,
                    ),
                    borderRadius: BorderRadius.circular(1),
                  ),
                ),
                const SizedBox(width: 4),
                Text(
                  widget.metricLabel,
                  style: LhTypography.mono(
                    size: 7.5,
                    color: DunesColors.resolve(context, LhColors.mute2),
                    weight: FontWeight.w600,
                    height: 1.0,
                    context: context,
                  ),
                ),
                const SizedBox(width: 3),
                if (displayValue < 0) Text('-', style: valueStyle),
                Text('$absFmt$unitFmt', style: valueStyle),
              ],
            ),
            if (_kMetricFormulas[widget.metricLabel] != null) ...[
              const SizedBox(height: 6),
              _buildFormulaInline(widget.metricLabel, widget.color),
            ],
            if (lighthouseTrendLegendMomOnSecondLine && delta != null) ...[
              const SizedBox(height: 2),
              Padding(
                padding: const EdgeInsets.only(left: 14),
                child: Text(
                  delta.text,
                  maxLines: 1,
                  style: LhTypography.mono(
                    size: 7.5,
                    color: delta.color,
                    weight: FontWeight.w700,
                    letterSpacing: 0.1,
                    height: 1.0,
                    context: context,
                  ),
                ),
              ),
            ],
          ],
        ),
      ],
    );
  }

