  // ═══════════════════════════════════════════════════════════════════════
  //   Stats bar —— MIN / AVG / MAX / 本期 (4 列, 上下 hairline, 列间 hairline)
  // ═══════════════════════════════════════════════════════════════════════
  Widget _buildStatsBar(
    _TrendStats stats,
    double currentValue,
    bool isSelected,
  ) {
    // 判断本期读数处于哪段: min/avg/max 匹配则该列高亮 accent
    final n = widget.data.length;
    int matchIdx = -1;
    for (int i = 0; i < n; i++) {
      if ((widget.data[i] - currentValue).abs() < 1e-6) {
        matchIdx = i;
        break;
      }
    }
    final currentIsMin = matchIdx == stats.minIdx;
    final currentIsMax = matchIdx == stats.maxIdx;

    return Container(
      decoration: BoxDecoration(
        border: Border(
          top: BorderSide(
            color: DunesColors.resolve(
              context,
              LhColors.line,
              role: DunesColorRole.border,
            ),
            width: 0.8,
          ),
          bottom: BorderSide(
            color: DunesColors.resolve(
              context,
              LhColors.line,
              role: DunesColorRole.border,
            ),
            width: 0.8,
          ),
        ),
      ),
      padding: const EdgeInsets.symmetric(vertical: 10),
      child: Row(
        children: [
          Expanded(
            child: _buildStatCol(
              'MIN',
              stats.min,
              accent: currentIsMin
                  ? widget.color
                  : DunesColors.resolve(context, LhColors.mute2),
              accentValue: currentIsMin,
            ),
          ),
          _statDivider(),
          Expanded(
            child: _buildStatCol(
              'AVG',
              stats.avg,
              accent: DunesColors.resolve(context, LhColors.mute2),
            ),
          ),
          _statDivider(),
          Expanded(
            child: _buildStatCol(
              'MAX',
              stats.max,
              accent: currentIsMax
                  ? widget.color
                  : DunesColors.resolve(context, LhColors.mute2),
              accentValue: currentIsMax,
            ),
          ),
          _statDivider(),
          Expanded(
            child: _buildStatCol(
              isSelected ? '当选' : '本期',
              currentValue,
              accent: widget.color,
              accentValue: true,
            ),
          ),
        ],
      ),
    );
  }

  Widget _statDivider() => Container(
    width: 0.8,
    height: 34,
    color: DunesColors.resolve(
      context,
      LhColors.line,
      role: DunesColorRole.surface,
    ),
  );

