                Text(
                  widget.isRate ? v.toStringAsFixed(2) : _fmtMoney(v),
                  style: LhTypography.number(
                    size: 15,
                    color: accentValue
                        ? accent
                        : DunesColors.resolve(context, LhColors.ink),
                    context: context,
                  ),
                ),
                const SizedBox(width: 1.5),
                Text(
                  widget.isRate ? '%' : _unitMoney(v),
                  style: LhTypography.sans(
