  // ═══════════════════════════════════════════════════════════════════════
  //   Insight line —— 一句 mono 分析 (本期 vs 均值 · 分位区间)
  // ═══════════════════════════════════════════════════════════════════════
  Widget _buildInsightLine(double currentValue, _TrendStats stats) {
    final avg = stats.avg;
    final absAvg = avg.abs();
    final diffPct = absAvg < 1e-9 ? 0.0 : (currentValue - avg) / absAvg * 100;
    final absDiff = diffPct.abs();

    // 分位区间 (min → p25 → avg → p75 → max)
    String bandLabel;
    Color bandColor;
    if (currentValue >= stats.p75) {
      bandLabel = '高位区间 · P75+';
      bandColor = DunesColors.resolve(context, LhColors.copper);
    } else if (currentValue >= avg) {
      bandLabel = '均值以上';
      bandColor = DunesColors.resolve(context, LhColors.ink2);
    } else if (currentValue >= stats.p25) {
      bandLabel = '均值以下';
      bandColor = DunesColors.resolve(context, LhColors.ink2);
    } else {
      bandLabel = '低位区间 · P25-';
      bandColor = DunesColors.resolve(context, LhColors.mute);
    }

    String vsAvgText;
    if (absDiff < 1.5) {
      vsAvgText = '贴近均值';
    } else if (currentValue > avg) {
      vsAvgText = '高出均值 ${absDiff.toStringAsFixed(1)}%';
    } else {
      vsAvgText = '低于均值 ${absDiff.toStringAsFixed(1)}%';
    }

    return Row(
      children: [
        Icon(
          Icons.arrow_right_rounded,
          size: 14,
          color: DunesColors.resolveNullable(context, bandColor.withAlpha(200)),
        ),
        const SizedBox(width: 2),
        Flexible(
          child: LhScrollRichText(
            text: TextSpan(
              children: [
                TextSpan(
                  text: '本期 · ',
                  style: LhTypography.mono(
                    size: 9.5,
                    color: DunesColors.resolve(context, LhColors.mute2),
                    weight: FontWeight.w600,
                    letterSpacing: 0.4,
                    context: context,
                  ),
                ),
                TextSpan(
                  text: vsAvgText,
                  style: LhTypography.mono(
                    size: 9.5,
                    color: DunesColors.resolve(context, LhColors.ink2),
                    weight: FontWeight.w700,
                    letterSpacing: 0.2,
                    context: context,
                  ),
                ),
                TextSpan(
                  text: '  ·  ',
                  style: LhTypography.mono(
                    size: 9.5,
                    color: DunesColors.resolve(context, LhColors.mute2),
                    weight: FontWeight.w600,
                    context: context,
                  ),
                ),
                TextSpan(
                  text: bandLabel,
                  style: LhTypography.mono(
                    size: 9.5,
                    color: bandColor,
                    weight: FontWeight.w800,
                    letterSpacing: 0.4,
                    context: context,
                  ),
                ),
              ],
            ),
            overflow: TextOverflow.ellipsis,
            maxLines: 1,
          ),
        ),
      ],
    );
  }

  // ═══════════════════════════════════════════════════════════════════════
  //   Swipe hint —— 极简一行 mono, 无 box
  // ═══════════════════════════════════════════════════════════════════════
  Widget _buildSwipeHint(bool isSelected) {
    return Row(
      mainAxisSize: MainAxisSize.min,
      children: [
        Icon(
          isSelected ? Icons.touch_app_outlined : Icons.swipe_rounded,
          size: 11,
          color: DunesColors.resolve(context, LhColors.mute2),
        ),
        const SizedBox(width: 5),
        Text(
          isSelected ? '已锁定该期读数  ·  点 CLEAR 或再点当期回到本期' : '轻触或横向拖动  ·  查看每期读数',
          style: LhTypography.mono(
            size: 8.5,
            color: DunesColors.resolve(context, LhColors.mute2),
            weight: FontWeight.w600,
            letterSpacing: 0.8,
            context: context,
          ),
        ),
      ],
    );
  }

  // ═══════════════════════════════════════════════════════════════════════
  //   Stats compute —— min/max/avg + p25/p75 分位
  // ═══════════════════════════════════════════════════════════════════════
  _TrendStats _computeStats(List<double> data) {
    double minV = data.first, maxV = data.first;
    int minIdx = 0, maxIdx = 0;
    double sum = 0;
    for (int i = 0; i < data.length; i++) {
      final v = data[i];
      sum += v;
      if (v < minV) {
        minV = v;
        minIdx = i;
      }
      if (v > maxV) {
        maxV = v;
        maxIdx = i;
      }
    }
    final avg = sum / data.length;

    // p25 / p75 —— 简易分位 (nearest-rank), n<4 时退化到 min/max
    final sorted = List<double>.from(data)..sort();
    double pct(double p) {
      if (sorted.length == 1) return sorted.first;
      final idx = ((sorted.length - 1) * p)
          .clamp(0, sorted.length - 1)
          .toDouble();
      final lo = idx.floor();
      final hi = idx.ceil();
      if (lo == hi) return sorted[lo];
      final frac = idx - lo;
      return sorted[lo] + (sorted[hi] - sorted[lo]) * frac;
    }

    return _TrendStats(
      min: minV,
      max: maxV,
      avg: avg,
      minIdx: minIdx,
      maxIdx: maxIdx,
      p25: pct(0.25),
      p75: pct(0.75),
    );
  }

  // ═══════════════════════════════════════════════════════════════════════
  //   Delta —— 本期读数 vs 环比参照 (未选中时: series 末 vs series[-2])
  //   selected 态: 相对上一期 (i vs i-1)
  // ═══════════════════════════════════════════════════════════════════════
  /// 把带符号的环比值渲染成 delta 视觉（中文财报语义：涨 = 红，跌 = 绿）。
  ({String text, Color color, IconData icon}) _deltaVisual(
    double v,
    String unit,
  ) {
    if (v.abs() < 0.05) {
      return (
        text: '0.0$unit',
        color: DunesColors.resolve(context, LhColors.mute),
        icon: Icons.remove_rounded,
      );
    }
    final isUp = v > 0;
    return (
      text: '${v.toStringAsFixed(1)}$unit',
      color: isUp
          ? DunesColors.resolve(context, LhColors.neg)
          : DunesColors.resolve(context, LhColors.pos),
      icon: isUp ? Icons.arrow_upward_rounded : Icons.arrow_downward_rounded,
    );
  }

  ({String text, Color color, IconData icon})? _computeDelta({
    required bool isSelected,
    required double displayValue,
  }) {
    final data = widget.data;
    if (data.length < 2) return null;

    // v4.0 · 本期未走完时，「序列末位 vs 前一位」＝ 本期 MTD vs 上期整期，
    //   正是会上被否掉的口径。这种情况一律走后端的同期对齐值；后端没给就留空。
    //   比率类不受窗口长短影响（MTD 毛利率 vs 上月毛利率仍可比），照旧兜底。
    final onPartialPoint =
        widget.partialPeriod &&
        (!isSelected || _selectedIndex == data.length - 1);
    if (onPartialPoint) {
      final api = widget.periodDeltaPct;
      if (api != null) {
        if (!widget.isRate && !lighthouseDeltaPctShown(api)) return null;
        return _deltaVisual(api, widget.isRate ? 'pp' : '%');
      }
      if (!widget.isRate) return null;
    } else if (!isSelected && widget.periodDeltaPct != null) {
      // 本期已走完：后端值和序列相减同口径，优先用后端的，跟卡片/列表一个数。
      if (!widget.isRate && !lighthouseDeltaPctShown(widget.periodDeltaPct)) {
        return null;
      }
      return _deltaVisual(widget.periodDeltaPct!, widget.isRate ? 'pp' : '%');
    }

    late double base;
    if (isSelected) {
      final i = _selectedIndex!;
      if (i <= 0) return null;
      base = data[i - 1];
    } else {
      base = data[data.length - 2];
    }
    if (widget.isRate) {
      final pp = displayValue - base;
      if (pp.abs() < 0.05) {
        return (
          text: '0.0pp',
          color: DunesColors.resolve(context, LhColors.mute),
          icon: Icons.remove_rounded,
        );
      }
      final isUp = pp > 0;
      return (
        text: '${pp.toStringAsFixed(1)}pp',
        color: isUp
            ? DunesColors.resolve(context, LhColors.neg)
            : DunesColors.resolve(context, LhColors.pos),
        icon: isUp ? Icons.arrow_upward_rounded : Icons.arrow_downward_rounded,
      );
    }
    final absBase = base.abs();
    if (absBase < 1e-9) return null;
    final pct = (displayValue - base) / absBase * 100;
    if (!lighthouseDeltaPctShown(pct)) return null;
    if (pct.abs() < 0.05) {
      return (
        text: '0.0%',
        color: DunesColors.resolve(context, LhColors.mute),
        icon: Icons.remove_rounded,
      );
    }
    // 中文财报语义: 涨 = 红, 跌 = 绿；数值保留正负号（图标另示方向）
    final isUp = pct > 0;
    return (
      text: '${pct.toStringAsFixed(1)}%',
      color: isUp
          ? DunesColors.resolve(context, LhColors.neg)
          : DunesColors.resolve(context, LhColors.pos),
      icon: isUp ? Icons.arrow_upward_rounded : Icons.arrow_downward_rounded,
    );
  }
}

// ═════════════════════════════════════════════════════════════════════════
// _MetricExcelPanel · v10 —— 二级"excel"式明细面板
// ─────────────────────────────────────────────────────────────────────────
//   放在 _showMetricTrendSheet 的公式面板下方。
//   顶部一排维度 tab（横向可滚），下方一张 label · value · delta 三列表。
//   语言完全对齐 hero cell 与 midstrip：mono UPPER kicker + sans w700 数字，
//   copper hairline + _LhPlum.primary 下划线，不引入新颜色 token。
// ═════════════════════════════════════════════════════════════════════════
class _MetricExcelPanel extends StatefulWidget {
  const _MetricExcelPanel({
    super.key,
    required this.metric,
    required this.dims,
    required this.activeDim,
    required this.rowsFor,
    required this.onDimChanged,
  });

  final _HeroMetric metric;
  final List<({String key, String label})> dims;
  final String activeDim;
  final List<Map<String, dynamic>> Function(String dim) rowsFor;
  final ValueChanged<String> onDimChanged;

  @override
  State<_MetricExcelPanel> createState() => _MetricExcelPanelState();
}

class _MetricExcelPanelState extends State<_MetricExcelPanel> {
  late String _activeDim = widget.activeDim;
  int _page = 1;
  static const int _pageSize = 10;

  @override
  void didUpdateWidget(covariant _MetricExcelPanel old) {
    super.didUpdateWidget(old);
    if (old.metric.key != widget.metric.key) {
      _activeDim = widget.activeDim;
      _page = 1;
    }
  }

  double _rowValue(Map<String, dynamic> r) {
    final v = r[widget.metric.key];
    if (v is num) return v.toDouble();
    return 0.0;
  }

  String _fmtVal(double v) {
    final abs = v.abs();
    // v12.5 · 强制万口径: sub-1 万也走 0.XX 万, 不再回退到裸数字
    if (abs >= 1e8) return '${(v / 1e8).toStringAsFixed(1)}亿';
    final wan = v / 1e4;
    if (wan.abs() >= 100) return '${wan.toStringAsFixed(0)}万';
    if (wan.abs() >= 1) return '${wan.toStringAsFixed(1)}万';
    return '${wan.toStringAsFixed(2)}万';
  }

  @override
  Widget build(BuildContext context) {
    final rawRows = widget.rowsFor(_activeDim);
    // 降序 by 当前 metric abs（保留符号显示）
    final rows = List<Map<String, dynamic>>.from(rawRows)
      ..sort((a, b) => _rowValue(b).abs().compareTo(_rowValue(a).abs()));

    // 分页
    final totalPages = rows.isEmpty
        ? 1
        : ((rows.length + _pageSize - 1) ~/ _pageSize);
    final page = _page.clamp(1, totalPages);
    final start = (page - 1) * _pageSize;
    final end = (start + _pageSize).clamp(0, rows.length);
    final visible = rows.sublist(start, end);

    // 总量 —— 供 delta 列的 share 显示
    final total = rows.fold<double>(0, (s, r) => s + _rowValue(r).abs());

    return Container(
      decoration: BoxDecoration(
        border: Border(
          top: BorderSide(
            color: DunesColors.resolve(
              context,
              LhColors.line,
              role: DunesColorRole.border,
            ),
            width: 0.8,
          ),
          bottom: BorderSide(
            color: DunesColors.resolve(
              context,
              LhColors.line2,
              role: DunesColorRole.border,
            ),
            width: 0.6,
          ),
        ),
      ),
      padding: const EdgeInsets.symmetric(vertical: 12),
      child: Column(
        crossAxisAlignment: CrossAxisAlignment.start,
        children: [
          // ── kicker: DETAIL · 明细（excel 语言） ────────────────────────
          Row(
            children: [
              Text(
                'DETAIL',
                style: LhTypography.mono(
                  size: 8.5,
                  color: DunesColors.resolve(context, LhColors.copper),
                  weight: FontWeight.w800,
                  letterSpacing: 1.4,
                  context: context,
                ),
              ),
              const SizedBox(width: 6),
              Text(
                '明细 · ${widget.metric.label}',
                style: LhTypography.mono(
                  size: 9,
                  color: DunesColors.resolve(context, LhColors.mute2),
                  weight: FontWeight.w700,
                  letterSpacing: 0.6,
                  context: context,
                ),
              ),
              const SizedBox(width: 10),
              Expanded(
                child: Container(
                  height: 0.6,
                  color: DunesColors.resolve(
                    context,
                    LhColors.line,
                    role: DunesColorRole.surface,
                  ),
                ),
              ),
              const SizedBox(width: 10),
              Text(
                '共 ${rows.length} 行',
                style: LhTypography.mono(
                  size: 9,
                  color: DunesColors.resolve(context, LhColors.ink2),
                  weight: FontWeight.w700,
                  letterSpacing: 0.2,
                  context: context,
                ),
              ),
            ],
          ),
          const SizedBox(height: 10),
          // ── 维度切换 (横向滚动) ─────────────────────────────────────────
          SizedBox(
            height: 30,
            child: SingleChildScrollView(
              scrollDirection: Axis.horizontal,
              physics: const ClampingScrollPhysics(),
              child: Row(
                mainAxisSize: MainAxisSize.min,
                children: [
                  for (final d in widget.dims) ...[
                    _buildDimChip(d),
                    const SizedBox(width: 12),
                  ],
                ],
              ),
            ),
          ),
          const SizedBox(height: 4),
          Container(
            height: 0.6,
            color: DunesColors.resolve(
              context,
              LhColors.line2,
              role: DunesColorRole.surface,
            ),
          ),
          // ── 表头 ───────────────────────────────────────────────────────
          Padding(
            padding: const EdgeInsets.symmetric(vertical: 7),
            child: Row(
              children: [
                Expanded(
                  flex: 5,
                  child: Text(
                    '维度',
                    style: LhTypography.mono(
                      size: 8.4,
                      color: DunesColors.resolve(context, LhColors.mute2),
                      weight: FontWeight.w700,
                      letterSpacing: 0.5,
                      context: context,
                    ),
                  ),
                ),
                Expanded(
                  flex: 3,
                  child: Text(
                    widget.metric.label,
                    textAlign: TextAlign.right,
                    style: LhTypography.mono(
                      size: 8.4,
                      color: DunesColors.resolve(context, LhColors.mute2),
                      weight: FontWeight.w700,
                      letterSpacing: 0.5,
                      context: context,
                    ),
                  ),
                ),
                Expanded(
                  flex: 2,
                  child: Text(
                    '占比',
                    textAlign: TextAlign.right,
                    style: LhTypography.mono(
                      size: 8.4,
                      color: DunesColors.resolve(context, LhColors.mute2),
                      weight: FontWeight.w700,
                      letterSpacing: 0.5,
                      context: context,
                    ),
                  ),
                ),
              ],
            ),
          ),
          Container(
            height: 0.6,
            color: DunesColors.resolve(
              context,
              LhColors.line2,
              role: DunesColorRole.surface,
            ),
          ),
          // ── 行 ─────────────────────────────────────────────────────────
          if (visible.isEmpty)
            Padding(
              padding: const EdgeInsets.symmetric(vertical: 24),
              child: Center(
                child: Text(
                  '暂无数据',
                  style: LhTypography.sans(
                    size: 11,
                    color: DunesColors.resolve(context, LhColors.mute),
                    context: context,
                  ),
                ),
              ),
            )
          else
            for (int i = 0; i < visible.length; i++)
              _buildExcelRow(visible[i], start + i, total),
          // ── 分页 ───────────────────────────────────────────────────────
          if (totalPages > 1) ...[
            const SizedBox(height: 10),
            _buildPageBar(page: page, totalPages: totalPages),
          ],
        ],
      ),
