  }

  Widget _buildDimChip(({String key, String label}) d) {
    final isOn = d.key == _activeDim;
    return GestureDetector(
      behavior: HitTestBehavior.opaque,
      onTap: () {
        setState(() {
          _activeDim = d.key;
          _page = 1;
        });
        widget.onDimChanged(d.key);
      },
      child: Column(
        mainAxisSize: MainAxisSize.min,
        crossAxisAlignment: CrossAxisAlignment.center,
        children: [
          Padding(
            padding: const EdgeInsets.symmetric(vertical: 5),
            child: Text(
              d.label,
              style: LhTypography.sans(
                size: 12,
                color: isOn
                    ? DunesColors.resolve(context, LhColors.ink)
                    : DunesColors.resolve(context, LhColors.mute),
                weight: isOn ? FontWeight.w700 : FontWeight.w500,
                letterSpacing: 0.3,
                context: context,
              ),
            ),
          ),
          Container(
            height: 2,
            width: isOn ? 20 : 0,
            color: DunesColors.resolve(
              context,
              _LhPlum.primary,
              role: DunesColorRole.surface,
            ),
          ),
        ],
      ),
    );
  }

  Widget _buildExcelRow(Map<String, dynamic> r, int idx, double total) {
    final name = r['name']?.toString() ?? '';
    final group = r['group']?.toString() ?? '';
    final val = _rowValue(r);
    final absVal = val.abs();
    final share = total > 0 ? (absVal / total * 100) : 0.0;
    final isNeg = val < 0;
    final isAlt = idx.isOdd;

    return Container(
      color: isAlt
          ? DunesColors.resolve(
              context,
              _LhPlum.mist,
              role: DunesColorRole.surface,
            )
          : DunesColors.resolve(
              context,
              Colors.white,
              role: DunesColorRole.surface,
            ),
      padding: const EdgeInsets.symmetric(vertical: 7, horizontal: 2),
      child: Row(
        crossAxisAlignment: CrossAxisAlignment.center,
        children: [
          Expanded(
            flex: 5,
            child: Column(
              crossAxisAlignment: CrossAxisAlignment.start,
              mainAxisSize: MainAxisSize.min,
              children: [
                LhScrollText(
                  name.isEmpty ? '未命名' : name,
                  style: LhTypography.sans(
                    size: 11,
                    weight: FontWeight.w600,
                    color: DunesColors.resolve(context, LhColors.ink),
                    letterSpacing: -0.1,
                    context: context,
                  ),
                  maxLines: 1,
                  overflow: TextOverflow.ellipsis,
                ),
                if (group.isNotEmpty) ...[
                  const SizedBox(height: 2),
                  LhScrollText(
                    group,
                    style: LhTypography.mono(
                      size: 8.4,
                      color: DunesColors.resolve(context, LhColors.mute2),
                      weight: FontWeight.w500,
                      letterSpacing: 0.2,
                      context: context,
                    ),
                    maxLines: 1,
                    overflow: TextOverflow.ellipsis,
                  ),
                ],
              ],
            ),
          ),
          Expanded(
            flex: 3,
            child: Text(
              (isNeg ? '-' : '') + _fmtVal(absVal),
              textAlign: TextAlign.right,
              style: LhTypography.sans(
                size: 12,
                weight: FontWeight.w700,
                color: isNeg
                    ? DunesColors.resolve(context, LhColors.pos)
                    : DunesColors.resolve(context, LhColors.ink),
                letterSpacing: -0.2,
                context: context,
              ),
            ),
          ),
          Expanded(
            flex: 2,
            child: Text(
              share < 0.1 ? '<0.1%' : '${share.toStringAsFixed(1)}%',
              textAlign: TextAlign.right,
              style: LhTypography.mono(
                size: 9.2,
                color: DunesColors.resolve(context, LhColors.mute),
                weight: FontWeight.w600,
                letterSpacing: 0.2,
                context: context,
              ),
            ),
          ),
        ],
      ),
    );
  }

  Widget _buildPageBar({required int page, required int totalPages}) {
    return Row(
      mainAxisAlignment: MainAxisAlignment.center,
      children: [
        _pageBtn(
          '‹',
          enabled: page > 1,
          onTap: () => setState(() => _page = page - 1),
        ),
        const SizedBox(width: 12),
        Text(
          '$page / $totalPages',
          style: LhTypography.mono(
            size: 10,
            color: DunesColors.resolve(context, LhColors.ink2),
            weight: FontWeight.w700,
            letterSpacing: 0.4,
            context: context,
          ),
        ),
        const SizedBox(width: 12),
        _pageBtn(
          '›',
          enabled: page < totalPages,
          onTap: () => setState(() => _page = page + 1),
        ),
      ],
    );
  }

  Widget _pageBtn(
    String label, {
    required bool enabled,
    required VoidCallback onTap,
  }) {
    return GestureDetector(
      onTap: enabled ? onTap : null,
      behavior: HitTestBehavior.opaque,
      child: Container(
        padding: const EdgeInsets.symmetric(horizontal: 10, vertical: 3),
        decoration: BoxDecoration(
          border: Border.all(
            color: enabled
                ? DunesColors.resolve(
                    context,
                    LhColors.line,
                    role: DunesColorRole.border,
                  )
                : DunesColors.resolve(
                    context,
                    LhColors.line2,
                    role: DunesColorRole.border,
                  ),
            width: 0.8,
          ),
          borderRadius: BorderRadius.circular(4),
        ),
        child: Text(
          label,
          style: LhTypography.mono(
            size: 12,
            color: enabled
                ? DunesColors.resolve(context, LhColors.ink2)
                : DunesColors.resolve(context, LhColors.mute2),
            weight: FontWeight.w700,
            context: context,
          ),
        ),
      ),
    );
  }
}

