/// 仅在手指几乎未移动时触发点击，避免列表滑动/拖动误触进入指标页。
class _LhScrollSafeTap extends StatefulWidget {
  const _LhScrollSafeTap({super.key, required this.onTap, required this.child});

  final VoidCallback onTap;
  final Widget child;

  @override
  State<_LhScrollSafeTap> createState() => _LhScrollSafeTapState();
}

class _LhScrollSafeTapState extends State<_LhScrollSafeTap> {
  Offset? _down;
  bool _moved = false;
  int? _pointer;

  void _reset() {
    _down = null;
    _moved = false;
    _pointer = null;
  }

  /// 这个 State 会被 Flutter 按「类型 + 位置」复用到另一个按钮上。
  /// 复用时必须把上一次的手势残留清掉，否则新按钮一上来就带着一个
  /// 永远等不到 up 的 pointer id。
  @override
  void didUpdateWidget(covariant _LhScrollSafeTap old) {
    super.didUpdateWidget(old);
    if (!identical(old.onTap, widget.onTap)) _reset();
  }

  @override
  void deactivate() {
    // 按下之后这棵子树被移出（数据刷新重建列表、叠层打开等），
    // up / cancel 都不会再送到这里 —— 不清掉的话 _pointer 永久残留。
    _reset();
    super.deactivate();
  }

  @override
  Widget build(BuildContext context) {
    return Listener(
      behavior: HitTestBehavior.translucent,
      onPointerDown: (e) {
        // v15 · 这里原来是 `if (_pointer != null) return;`。
        //
        //   一旦某次按下之后 up / cancel 没送达（子树被移除、State 被复用到
        //   另一个按钮），_pointer 就永远留着一个死 id，此后这个按钮的每一次
        //   点击都会在这一行被静默丢掉 —— 表现正是「按钮还在，但点不进去」。
        //   新的一次按下永远比一个悬着的旧 id 更可信，直接接管。
        _pointer = e.pointer;
        _down = e.position;
        _moved = false;
      },
      onPointerMove: (e) {
        if (e.pointer != _pointer || _down == null || _moved) return;
        if ((e.position - _down!).distance > 16) _moved = true;
      },
      onPointerUp: (e) {
        if (e.pointer != _pointer) return;
        if (!_moved && _down != null) {
          widget.onTap();
          LighthouseFeedback.instance.play(LighthouseFeedbackKind.select);
        }
        _reset();
      },
      onPointerCancel: (e) {
        if (e.pointer == _pointer) _reset();
      },
      child: widget.child,
    );
  }
}

