class _LighthouseEmbeddedCardState extends State<LighthouseEmbeddedCard> {
  final _navigation = DunesNavigationController();
  final _unread = CommUnreadNotifier();
  final _badge = WorkbenchBadgeNotifier();
  @override
  void dispose() {
    _navigation.dispose();
    _unread.dispose();
    _badge.dispose();
    super.dispose();
  }

  @override
  Widget build(BuildContext context) => LayoutBuilder(
    builder: (context, box) {
      final media = MediaQuery.of(context);
      return MediaQuery(
        data: media.copyWith(
          size: Size(
            box.maxWidth.isFinite ? box.maxWidth : media.size.width,
            media.size.height,
          ),
        ),
        child: NativeLighthousePage(
          session: widget.session,
          navigation: _navigation,
          commUnread: _unread,
          workbenchBadge: _badge,
          active: false,
          sharedCard: widget.data,
        ),
      );
    },
  );
}

class NativeLighthousePage extends StatefulWidget {
  const NativeLighthousePage({
    super.key,
    required this.session,
    required this.navigation,
    required this.commUnread,
    required this.workbenchBadge,
    this.active = true,
    this.service,
    this.sharedCard,
  });

  final AuthSession session;
  final DunesNavigationController navigation;
  final CommUnreadNotifier commUnread;
  final WorkbenchBadgeNotifier workbenchBadge;

  /// keep-alive 离屏时为 false，避免占用全局返回拦截把其它 Tab 拉回灯塔。
  final bool active;

  /// Injectable data source for offline widget regression tests.
  @visibleForTesting
  final LighthouseService? service;

  /// IM uses the same card builders with scoped, already-shared data. No fetches.
  final LighthouseSharedCardData? sharedCard;

  @override
  State<NativeLighthousePage> createState() => _LighthouseTopicHostState();
}

/// 专题宿主：只记「当前专题」。换专题 = 按 key 重建整页，
/// 期间 / 维度 / 分类经 [LighthouseTopicHandoff] 带过去。
/// 好处是所有按期间算的缓存键、晚到响应的校验都不用再认专题。
class _LighthouseTopicHostState extends State<NativeLighthousePage> {
  String _topic = '';
  LighthouseTopicHandoff? _handoff;

  void _onTopicChanged(String key, LighthouseTopicHandoff handoff) {
    if (key == _topic) return;
    setState(() {
      _topic = key;
      _handoff = handoff;
    });
  }

  @override
  Widget build(BuildContext context) {
    return _LighthouseTopicBody(
      key: ValueKey<String>('lighthouse-topic:$_topic'),
      session: widget.session,
      navigation: widget.navigation,
      commUnread: widget.commUnread,
      workbenchBadge: widget.workbenchBadge,
      active: widget.active,
      service: widget.service,
      sharedCard: widget.sharedCard,
      topic: _topic,
      handoff: _handoff,
      onTopicChanged: widget.sharedCard == null ? _onTopicChanged : null,
    );
  }
}

class _LighthouseTopicBody extends StatefulWidget {
  const _LighthouseTopicBody({
    super.key,
    required this.session,
    required this.navigation,
    required this.commUnread,
    required this.workbenchBadge,
    required this.active,
    required this.service,
    required this.sharedCard,
    required this.topic,
    required this.handoff,
    required this.onTopicChanged,
  });

  final AuthSession session;
  final DunesNavigationController navigation;
  final CommUnreadNotifier commUnread;
  final WorkbenchBadgeNotifier workbenchBadge;
  final bool active;
  final LighthouseService? service;
  final LighthouseSharedCardData? sharedCard;

  /// 专题 key，空 = 全盘。
  final String topic;

  /// 上一个专题页留下的浏览状态（期间 / 维度 / 分类）。
  final LighthouseTopicHandoff? handoff;
  final void Function(String key, LighthouseTopicHandoff handoff)?
  onTopicChanged;

  @override
  State<_LighthouseTopicBody> createState() => _NativeLighthousePageState();
}

enum _DdMode { none, category, metric }

/// 预警这一路查得怎么样。「查成功没有」和「压根没查到」必须分得开：
/// 前者是好消息，后者是我们自己的问题。
enum _LhNoticeFetch { pending, ok, failed }

class _NativeLighthousePageState extends State<_LighthouseTopicBody> {
  static const String _kPrefsMetricProduct = 'lighthouse.metrics.product';
  static const String _kPrefsMetricSupply = 'lighthouse.metrics.supply';
  static const String _kPrefsMetricChannel = 'lighthouse.metrics.channel';
  static const String _kPrefsUiZoom = 'lighthouse.uiZoom';

  /// 用户自定义列序 —— 每个 tab 各存一份（渠道看成本、产品看利润，诉求不同）。
  static const String _kPrefsColOrderProduct = 'lighthouse.colorder.product';
  static const String _kPrefsColOrderSupply = 'lighthouse.colorder.supply';
  static const String _kPrefsColOrderChannel = 'lighthouse.colorder.channel';

  /// 「用户动过手」标记 —— 决定 _ensureNetProfitAfterProfit 还纠不纠正顺序。
  static const String _kPrefsColOrderTouched = 'lighthouse.colorder.touched';
  static const List<double> _kUiZoomOptions = [
    0.75,
    0.80,
    0.85,
    0.9,
    1.0,
    1.1,
    1.25,
    1.5,
  ];

  late final LighthouseService _service;

  /// 业务 / 财务口径（2026-10-30）。净TA 归财务侧：_tab == 'netTa' 也算财务。
  bool _financeLedger = false;
  LighthouseBfController? _bf;

  /// 从财务「主体」切去净TA 前的账本维度，回业务时还原。
  String _bfReturnTab = 'product';
  bool get _isFinanceLedger => _financeLedger || _tab == 'netTa';
  bool get _bfSubjectView => _financeLedger && _tab != 'netTa' && _bf != null;
  LighthouseDataBundle? _bundle;
  bool _loading = true;
  String? _loadError;
  final Set<String> _loadedTabs = {};
  final Set<String> _loadingTabs = {};

  /// tab → 这次 in-flight 请求的 cacheKey。旧请求 finally 对不上就不摘加载标记。
  final Map<String, String> _tabLoadKeys = {};
  final Map<String, String> _tabErrors = {};

  /// BI 当前视角。切日周月要拉这一维，不能只拉主列表 `_tab`。
  String? _biDim;

  /// `$dim|day` / `$dim|month` → 日历今天、本月的行，给构成图例「本日/本月新增」。
  final Map<String, List<Map<String, dynamic>>> _biWindowRows = {};
  final Set<String> _biWindowLoading = {};
  int _biWindowGen = 0;
  final Set<String> _loadingDetails = {};

  /// 自动补详情每个实体、周期只尝试一次；失败后由用户主动重试。
  final Set<String> _autoDetailAttempts = {};
  final Map<String, String> _detailErrors = {};

  /// Track which period+offset each detail was loaded with.
  ///   Key = '$type:$key' (matches _detailEntityMap lookup)
  ///   Value = '$_period:$_periodOffset' (period key at load time)
  /// _buildDetailView 用它检测缓存过期 (外面改了 period 但 detail 缓存仍是老的)
  /// —— 命中过期时触发 _loadDetail 重拉, 避免"外面在日, 点进去还是月"这个 bug.
  final Map<String, String> _detailLoadedFor = {};
  final Set<String> _loadedTrends = {};
  final Set<String> _loadingTrends = {};

  /// 防止详情页 build → 趋势失败 → setState → build 无限请求。
  final Set<String> _failedTrends = {};
  final Map<String, String> _trendErrors = {};

  /// tab → (rowKey → trend)。不依赖该维列表是否已加载；二级/三级展开靠它回填。
  final Map<String, Map<String, Map<String, dynamic>>> _trendCache = {};
  bool _discountsLoading = false;
  Map<String, dynamic> _discountsByName = const {};
  bool _fundPoolLoading = false;
  Map<String, LighthouseFundPoolAmounts> _fundPoolByProvince = const {};
  // 顶部资产总览当前聚焦的曲线：scale / revenue / profit；null = 全部。
  String? _supplyAssetSoloKey;
  // 顶部资产走势当前点中的日期；null = 最新一期。
  int? _supplyAssetPointIndex;
  String _supplyAssetTrendPrimeKey = '';

