  Map<String, dynamic>? _hunOptionByToken(String token) {
    if (token.isEmpty || token == 'none') return null;
    for (final o in _hunOptions) {
      if (o['value'] == token ||
          o['match'] == token ||
          o['cubeValue'] == token) {
        return o;
      }
    }
    return null;
  }

  String _hunMatchFor(String filterValue) {
    final o = _hunOptionByToken(filterValue);
    return o?['match'] as String? ?? (filterValue == '全部' ? '' : filterValue);
  }

  Color _hunColorFor(String token) =>
      _lhColorFromKey(_hunOptionByToken(token)?['colorKey'] as String?);

  String _hunBadgeFor(String token) {
    final o = _hunOptionByToken(token);
    return o?['badge'] as String? ?? o?['label'] as String? ?? token;
  }

  String _hunLabelFor(String token) {
    final o = _hunOptionByToken(token);
    return o?['label'] as String? ?? token;
  }

  String _cubeFilterLabel(String key) {
    for (final d in _cubeFilterDefs) {
      if (d['key'] == key) return d['label'] as String? ?? key;
    }
    return key;
  }

  List<Map<String, String>> _cubeHunOptionPairs() {
    final out = <Map<String, String>>[];
    for (final o in _hunOptions) {
      final value = o['value'] as String? ?? '';
      if (value == '全部') {
        out.add({'value': '全部', 'label': '全部'});
        continue;
      }
      final cubeValue =
          o['cubeValue'] as String? ?? o['match'] as String? ?? value;
      out.add({
        'value': cubeValue,
        'label': o['label'] as String? ?? cubeValue,
      });
    }
    if (out.isEmpty)
      return const [
        {'value': '全部', 'label': '全部'},
      ];
    return out;
  }

  String _hunBarTitle() =>
      (_uiFilterDef('supply', 'hun')?['label'] as String?) ?? 'U/N';

  List<String> _mergeCategoryLists(List<String> a, List<String> b) {
    final seen = <String>{};
    final out = <String>['全部'];
    seen.add('全部');
    // 保留 UI/后端下发顺序，再由 _pinPreferredCategory 置顶指定项
    for (final list in [a, b]) {
      for (final g in list) {
        if (g.isEmpty || g == '全部' || seen.contains(g)) continue;
        seen.add(g);
        out.add(g);
      }
    }
    return out;
  }

  /// 下拉里置顶的快捷分类（仍排在「全部」之后）。
  /// 仅置顶方便点选；默认选中一律「全部」，保证三维 Hero 全量口径一致。
  static const _kPinnedCategoryHint = <String, String>{
    'supply': '中石油',
    'channel': '平安',
  };

  /// 把常用分类挪到「全部」之后第一位（存在才挪），方便筛选。
  List<String> _pinPreferredCategory(String tab, List<String> cats) {
    final preferred = _kPinnedCategoryHint[tab];
    if (preferred == null || preferred.isEmpty || cats.length <= 1) {
      return cats;
    }
    final idx = cats.indexWhere(
      (g) => g != '全部' && (g == preferred || g.contains(preferred)),
    );
    if (idx <= 1) return cats; // 已是第一或找不到
    final pinned = cats[idx];
    final next = List<String>.from(cats)..removeAt(idx);
    final insertAt = next.isNotEmpty && next.first == '全部' ? 1 : 0;
    next.insert(insertAt, pinned);
    return next;
  }

  /// 默认 L1 分类：产品 / 供给 / 渠道 / 人效一律「全部」。
  String _defaultGroupFilter(String tab) => lighthouseDefaultGroupFilter(tab);

  /// 展开分类条或切 Tab：保留用户选的「全部」；仅失效分类回退。
  void _ensureDefaultGroupFilter() {
    if (_isNonLedgerTab || _tab == 'netTa') return;
    final opts = _categoryOptions(_tab);
    _groupFilter = lighthouseNormalizeGroupFilter(
      current: _groupFilter,
      options: opts,
    );
  }

  List<String> _categoryOptions(String tab) {
    final fromUi =
        (_uiTab(tab)?['categories'] as List?)?.cast<String>() ?? const [];
    List<String> raw;
    if (_bundle != null) {
      final fromRows = _getGroups(tab, _bundle!.rowsOf(tab));
      if (fromUi.isNotEmpty || fromRows.length > 1) {
        raw = _mergeCategoryLists(fromUi, fromRows);
      } else if (fromUi.isNotEmpty) {
        raw = fromUi;
      } else {
        raw = _getGroups(tab, _bundle!.rowsOf(tab));
      }
    } else if (fromUi.isNotEmpty) {
      raw = fromUi;
    } else {
      return const ['全部'];
    }
    return _pinPreferredCategory(tab, raw);
  }

  void _syncMetricsFromUI() {
    for (final tab in const ['product', 'supply', 'channel', 'people']) {
      final defs = _uiMetricDefMap(tab);
      final defaults = _uiDefaultMetrics(tab);
      final order = defaults.isNotEmpty ? defaults : _kLedgerMetricOrder;
      final full = [
        for (final k in order)
          if (defs.containsKey(k) && k != 'discount') k,
      ];
      // 用户存过的显隐偏好优先。原来这里无条件覆盖成全量默认，
      // _savedMetricPrefs 写了从来没被读过 —— 隐藏列一重启就回来了。
      final saved = _savedMetricPrefs[tab];
      _metrics[tab] = (saved == null || saved.isEmpty)
          ? full
          : [
              for (final k in saved)
                if (defs.containsKey(k) && k != 'discount') k,
            ];
      if (_metrics[tab]!.isEmpty) _metrics[tab] = full;

      // 列序对账 —— defs 到手了才做，丢弃后端已删的 key、补回后端新增的 key。
      final savedOrder = _colOrder[tab] ?? const <String>[];
      if (savedOrder.isNotEmpty) {
        _colOrder[tab] = _reconcileColOrder(tab, savedOrder);
      }
    }
  }

  /// 净利必须紧跟利润；旧偏好里常被追加在列尾，这里纠正顺序。
  List<String> _ensureNetProfitAfterProfit(List<String> keys) {
    final out = List<String>.from(keys);
    final netIdx = out.indexOf('netProfit');
    if (netIdx < 0) return out;
    out.removeAt(netIdx);
    var profitIdx = out.indexOf('profit');
    if (profitIdx < 0) {
      // 有净利无利润时补上利润，再把净利贴在后面
      out.add('profit');
      profitIdx = out.length - 1;
    }
    out.insert(profitIdx + 1, 'netProfit');
    return out;
  }

  // ── 列排列 · 解析与对账 ───────────────────────────────────────────────────

  /// 该 tab 当前生效的列序（全量 key，含被隐藏的）。
  /// 未自定义 → 默认序；自定义过 → 存的那份，但要先跟后端指标定义对账。
  List<String> _colOrderFor(String tab) {
    final saved = _colOrder[tab] ?? const <String>[];
    if (saved.isEmpty) return _defaultColOrderFor(tab);
    return saved;
  }

  List<String> _defaultColOrderFor(String tab) {
    final defs = _uiMetricDefMap(tab);
    return [
      for (final k in _kLedgerMetricOrder)
        if (defs.containsKey(k) && k != 'discount') k,
    ];
  }

  /// 存下来的列序 × 后端最新指标定义 的对账。
  ///
  /// 两个必须处理的场景（不处理就会出脏列 / 丢列）：
  ///   · 后端删了某指标 → 用户序里的残留 key 会渲染出「标签是裸 key、值恒 0」的空列
  ///   · 后端加了某指标 → 一律甩到最右不合理，应按默认序的相对位置插回原位
  List<String> _reconcileColOrder(String tab, List<String> saved) {
    final defs = _uiMetricDefMap(tab);
    final out = <String>[];
    final seen = <String>{};
    for (final k in saved) {
      if (k == 'discount' || !defs.containsKey(k) || !seen.add(k)) continue;
      out.add(k);
    }
    final fallback = _defaultColOrderFor(tab);
    for (var i = 0; i < fallback.length; i++) {
      final k = fallback[i];
      if (seen.contains(k)) continue;
      // 往前找它在默认序里最近的、且已在结果里的邻居，插到它后面。
      var at = 0;
      for (var j = i - 1; j >= 0; j--) {
        final idx = out.indexOf(fallback[j]);
        if (idx >= 0) {
          at = idx + 1;
          break;
        }
      }
      out.insert(at, k);
      seen.add(k);
    }
    return out;
  }

  String _colOrderPrefsKey(String tab) {
    switch (tab) {
      case 'product':
        return _kPrefsColOrderProduct;
      case 'supply':
        return _kPrefsColOrderSupply;
      case 'channel':
        return _kPrefsColOrderChannel;
      default:
        return 'lighthouse.colorder.$tab';
    }
  }

  String _metricPrefsKey(String tab) {
    switch (tab) {
      case 'product':
        return _kPrefsMetricProduct;
      case 'supply':
        return _kPrefsMetricSupply;
      case 'channel':
        return _kPrefsMetricChannel;
      default:
        return 'lighthouse.metrics.$tab';
    }
  }

  Future<void> _restoreMetricPrefs() async {
    final prefs = await SharedPreferences.getInstance();
    final restored = <String, List<String>>{};
    for (final tab in const ['product', 'supply', 'channel', 'people']) {
      final saved = prefs.getStringList(_metricPrefsKey(tab));
      if (saved != null && saved.isNotEmpty) {
        restored[tab] = List<String>.from(saved);
      }
    }
    final restoredOrder = <String, List<String>>{};
    for (final tab in const ['product', 'supply', 'channel', 'people']) {
      final saved = prefs.getStringList(_colOrderPrefsKey(tab));
      if (saved != null && saved.isNotEmpty) {
        restoredOrder[tab] = List<String>.from(saved);
      }
    }
    final touched = prefs.getStringList(_kPrefsColOrderTouched) ?? const [];
    final savedZoom = prefs.getDouble(_kPrefsUiZoom);
    unawaited(LighthousePkBasket.instance.load());
    if (!mounted) return;
    setState(() {
      // 对账放到 _syncMetricsFromUI 之后做 —— 此刻 _bundle 可能还没到，
      // 后端指标定义拿不到，现在对账等于拿空 defs 把用户列序清光。
      _colOrder
        ..clear()
        ..addAll({
          'product': <String>[],
          'supply': <String>[],
          'channel': <String>[],
        })
        ..addAll(restoredOrder);
      _colOrderTouched
        ..clear()
        ..addAll(touched);
      if (restored.isNotEmpty) {
        _savedMetricPrefs
          ..clear()
          ..addAll(restored);
        if (_bundle != null) {
          _syncMetricsFromUI();
        }
      }
      if (savedZoom != null &&
          _kUiZoomOptions.any((z) => (z - savedZoom).abs() < 0.001)) {
        _uiZoom = savedZoom;
      }
    });
  }

  Future<void> _persistUiZoom() async {
    final prefs = await SharedPreferences.getInstance();
    await prefs.setDouble(_kPrefsUiZoom, _uiZoom);
  }

  Future<void> _persistMetricPrefs() async {
    final prefs = await SharedPreferences.getInstance();
    for (final tab in const ['product', 'supply', 'channel', 'people']) {
      final selected = _metrics[tab] ?? const <String>[];
      await prefs.setStringList(
        _metricPrefsKey(tab),
        List<String>.from(selected),
      );
      final order = _colOrder[tab] ?? const <String>[];
      if (order.isEmpty) {
        await prefs.remove(_colOrderPrefsKey(tab));
      } else {
        await prefs.setStringList(
          _colOrderPrefsKey(tab),
          List<String>.from(order),
        );
      }
    }
    await prefs.setStringList(
      _kPrefsColOrderTouched,
      _colOrderTouched.toList(),
    );
    // 显隐是列排列模型的一半，存完要让 _savedMetricPrefs 跟上，
    // 否则同一会话内 _syncMetricsFromUI 再跑一次会读到旧值。
    _savedMetricPrefs
      ..clear()
      ..addAll({
        for (final tab in const ['product', 'supply', 'channel', 'people'])
          tab: List<String>.from(_metrics[tab] ?? const <String>[]),
      });
  }

  @override
  void initState() {
    super.initState();
    _service = widget.service ?? LighthouseService(session: widget.session);
    _service.topic = widget.topic;
    if (widget.sharedCard == null && widget.topic.trim().isEmpty) {
      _bf = LighthouseBfController(service: _service);
      unawaited(_bf!.load());
    }
    // 资金池先放回内存缓存那份（同一次打开 App 里再进灯塔，首帧就有总资产）。
    _restoreFundPoolFromMemory();
    if (widget.sharedCard != null) {
      _applySharedCard(widget.sharedCard!);
      return;
    }
    _applyTopicHandoff(widget.handoff);
    unawaited(LighthouseFeedback.instance.load());
    if (widget.active) _installBackInterceptor();
    _restoreMetricPrefs();
    if (widget.session.effectiveLighthouseAccess) {
      _load();
      // 与 overview 并行：预警拿不到也不影响主数据。
      unawaited(_loadDelayNotice());
      _syncDelayNoticePolling();
    } else {
      _loading = false;
    }
  }

  // ── 专题 ────────────────────────────────────────────────────────────────
  bool get _inTopic => widget.topic.isNotEmpty;

  LighthouseTopic? get _topicDef => lighthouseTopicOf(widget.topic);

  void _applyTopicHandoff(LighthouseTopicHandoff? h) {
    if (h == null) return;
    _period = h.period;
    _periodOffset = h.periodOffset;
    _customStart = h.customStart;
    _customEnd = h.customEnd;
    // 净TA 不进专题（不是账本口径）；从专题出来再回到产品。
    _tab = (h.tab == 'netTa' && _inTopic) ? 'product' : h.tab;
    _groupFilter = h.groupFilter;
    _tabBarShowsGroups = h.tabBarShowsGroups;
    if (_tab == 'supply' && _inTopic) {
      // 总资产是省级资管数，专题下没有，按利润排。
      _sortField = 'profit';
      _sortDesc = true;
    }
  }

  void _switchTopic(String key) {
    final cb = widget.onTopicChanged;
    if (cb == null || key == widget.topic) return;
    LighthouseFeedback.instance.play(LighthouseFeedbackKind.navigate);
    _closeDropdown();
    cb(
      key,
      LighthouseTopicHandoff(
        period: _period,
        periodOffset: _periodOffset,
        customStart: _customStart,
        customEnd: _customEnd,
        tab: _detailKey == null ? _tab : (_detailType ?? _tab),
        groupFilter: _groupFilter,
        tabBarShowsGroups: _tabBarShowsGroups,
      ),
    );
  }

  Widget _buildTopicStrip() {
    return Padding(
      padding: const EdgeInsets.only(bottom: 6),
      child: LighthouseTopicStrip(
        current: widget.topic,
        onSelect: _switchTopic,
        padding: const EdgeInsets.symmetric(
          horizontal: lighthouseHeroShellMarginH,
        ),
      ),
    );
  }

  Widget _buildTopicLedgerBar() {
    final t = _topicDef;
    if (t == null) return const SizedBox.shrink();
    return LighthouseTopicLedgerBar(topic: t, onExit: () => _switchTopic(''));
  }

  void _applySharedCard(LighthouseSharedCardData card) {
    _tab = card.tab;
    _period = card.period;
    _groupFilter = card.row['group']?.toString().trim() ?? '全部';
    if (_groupFilter.isEmpty) _groupFilter = '全部';
    final json = card.toJson();
    _periodOffset = (json['offset'] as num?)?.toInt() ?? 0;
    _customStart = DateTime.tryParse(json['start']?.toString() ?? '');
    _customEnd = DateTime.tryParse(json['end']?.toString() ?? '');
    _bundle = LighthouseDataBundle.empty().copyWith(
      data: {
        card.tab: [card.row],
      },
      metrics: card.metrics,
    );
    _loading = false;
    _paceDaily = null;
    _paceModelCache.clear();
    if (json['paceDaily'] is Map) {
      _paceDaily = {
        for (final entry in (json['paceDaily'] as Map).entries)
          if (entry.value is Map)
            entry.key.toString(): {
              for (final daily in (entry.value as Map).entries)
                if (DateTime.tryParse(daily.key.toString()) != null &&
                    daily.value is num)
                  DateTime.parse(daily.key.toString()): (daily.value as num)
                      .toDouble(),
            },
      };
      _paceDailyKey = _paceDailyReqKey;
    }
    _fundPoolByProvince = {};
    _fundPoolProfitMonth = {};
    _fundPoolProfitDay = {};
    void restorePool(Map<String, dynamic> row) {
      final name = row['name']?.toString() ?? '';
      final pool = LighthouseFundPoolAmounts.fromJson(row['sharedFundPool']);
      if (pool != null) _fundPoolByProvince[name] = pool;
      if (row['sharedProfitMonth'] is num)
        _fundPoolProfitMonth[name] = (row['sharedProfitMonth'] as num)
            .toDouble();
      if (row['sharedProfitDay'] is num)
        _fundPoolProfitDay[name] = (row['sharedProfitDay'] as num).toDouble();
      for (final child in lighthouseProductL3Children(row)) {
        restorePool(child);
      }
    }

    restorePool(card.row);
    _expandedTrends.clear();
    _expandedLedgerSolo.clear();
    _expandedProductL3.clear();
    _expandedTrendKey = card.kind == 'hero'
        ? json['focusKey']?.toString()
        : null;
    _heroTraceKey = card.kind == 'hero' ? json['traceKey']?.toString() : null;
    _heroViewEnd = card.viewEnd;
    _heroPointIndex = card.kind == 'hero'
        ? (json['pointIndex'] as num?)?.toInt()
        : null;
  }

  Map<String, dynamic> _shareEntityData(
    Map<String, dynamic> row, {
    bool includeFundPool = false,
  }) {
    final resolved = _rowWithResolvedTrend(row);
    final children = lighthouseProductL3LedgerRows(row);
    final name = row['name']?.toString() ?? '';
    final pool = includeFundPool
        ? lighthouseFundPoolForRow(row, _fundPoolByProvince)
        : null;
    return {
      ...resolved,
      'grossMarginBasis': _rowMarginBasis(row),
      if (_rowMarginProduct(row) != null)
        'marginProduct': _rowMarginProduct(row),
      if (pool != null)
        'sharedFundPool': {
          'endingPrepaymentBalance': pool.endingPrepaymentBalance,
          'endingReceivableRebate': pool.endingReceivableRebate,
          'fundPoolBalance': pool.fundPoolBalance,
          'inventoryVoucherBalance': pool.inventoryVoucherBalance,
          'contractVoucherBalance': pool.contractVoucherBalance,
          'systemDifference': pool.systemDifference,
          'inTransitFunds': pool.inTransitFunds,
          'regulatoryAccountBalance': pool.regulatoryAccountBalance,
          'totalAssets': pool.totalAssets,
          'invoiceToIssue': pool.invoiceToIssue,
          'invoiceIssued': pool.invoiceIssued,
          'invoiceTaxRate': pool.invoiceTaxRate,
          'invoiceOriginals': pool.invoiceOriginals,
          'advanceVoucherBalance': pool.advanceVoucherBalance,
        },
      if (pool != null)
        'sharedProfitMonth': lighthouseLookupProvinceAmount(
          _fundPoolProfitMonth,
          name,
        ),
      if (pool != null)
        'sharedProfitDay': lighthouseLookupProvinceAmount(
          _fundPoolProfitDay,
          name,
        ),
      if (children.isNotEmpty)
        'children': [
          for (final child in children)
            _shareEntityData({
              ...child,
              'parentProduct': _rowMarginProduct(row) ?? row['name'],
            }),
        ],
    };
  }

  LighthouseSharedCardData _sharedCardData({
    required String kind,
    required String title,
    Map<String, dynamic>? entityRow,
    Map<String, double>? totals,
    String? section,
    int index = 0,
    String? tab,
    bool panelWhite = false,
  }) {
    final effectiveTab = tab ?? _tab;
    final values =
        totals ??
        (entityRow == null
            ? const <String, double>{}
            : _heroTotalsFromRow(entityRow));
    final row = entityRow != null
        ? _shareEntityData(entityRow, includeFundPool: effectiveTab == 'supply')
        : <String, dynamic>{
            ...values,
            'name': title,
            'group': _grossMarginContextGroup ?? '',
            'grossMarginBasis': _grossMarginContextBasis,
            if (_grossMarginContextProduct != null)
              'marginProduct': _grossMarginContextProduct,
            'trend': {
              'labels': _heroTrendLabels(_seriesForMetric('profit').length),
              for (final key in <String>{
                'profit',
                'sales',
                'verifiedSales',
                'gmv',
                'revenue',
                'totalCost',
                'cost',
                'projectCost',
                'netProfit',
                'prepaid',
                'spread',
                'netTa',
                ...values.keys,
              })
                key: _seriesForMetric(key),
            },
            'deltas': {
              for (final key in values.keys)
                if (_deltaForMetric(key) case final delta?)
                  key: delta.isUp ? delta.pct : -delta.pct,
            },
          };
    final trend = row['trend'] as Map? ?? const {};
    final metrics = <String, dynamic>{
      ...values,
      if (effectiveTab == 'netTa' && entityRow == null)
        for (final entry
            in (_bundle?.metrics ?? const <String, dynamic>{}).entries)
          if (entry.key.startsWith('netTa')) entry.key: entry.value,
      'grossMarginBasis': row['grossMarginBasis'],
      'heroSeriesLabels': trend['labels'] ?? trend['xLabels'] ?? const [],
      ...lighthouseSeriesFieldsFromTrend(trend),
      if (row['deltas'] is Map) 'deltas': row['deltas'],
      'profitSeries': trend['profit'] ?? trend['points'] ?? const [],
      for (final entry in (row['deltas'] as Map? ?? const {}).entries)
        if (entry.value is num) ...{
          '${entry.key}DeltaPct': (entry.value as num).abs(),
          '${entry.key}DeltaDir': (entry.value as num) >= 0 ? 'up' : 'down',
        },
    };
    return LighthouseSharedCardData.create({
      'kind': kind,
      'title': title,
      'range': _selectedRangeLabel,
      'period': _period,
      'offset': _periodOffset,
      'start': _customStart?.toIso8601String(),
      'end': _customEnd?.toIso8601String(),
      'tab': effectiveTab,
      'index': index,
      'row': row,
      'totals': values,
      'metrics': metrics,
      'section': section,
      'panelWhite': panelWhite,
      'pointIndex': _heroPointIndex,
      if (kind == 'hero') ...{
        'focusKey': _expandedTrendKey,
        'traceKey': _heroTraceKey,
        'viewportCount': _heroViewportCount,
        'historyCount': _heroHistoryCount,
        'viewEnd': _heroViewEnd,
      },
      // 再次转发仍是原数据口径；消息发送时间由 IM 自己记录。
      'capturedAt': (widget.sharedCard?.capturedAt ?? DateTime.now())
          .toUtc()
          .toIso8601String(),
      if (kind == 'hero' &&
          entityRow == null &&
          _paceDaily != null &&
          _paceDailyKey == _paceDailyReqKey)
        'paceDaily': {
          for (final entry in _paceDaily!.entries)
            entry.key: {
              for (final daily in entry.value.entries)
                daily.key.toIso8601String(): daily.value,
            },
        },
    });
  }

  Widget _sharedCardPreview(LighthouseSharedCardData data) =>
      LighthouseEmbeddedCard(session: widget.session, data: data);

  void _openSharedEntityDetail(Map<String, dynamic> row) {
    final data = _sharedCardData(
      kind: 'hero',
      title: row['name']?.toString() ?? '灯塔',
      entityRow: row,
      totals: _heroTotalsFromRow(row),
    );
    showModalBottomSheet<void>(
      context: context,
      isScrollControlled: true,
      showDragHandle: true,
      builder: (context) => SafeArea(
        child: SizedBox(
          height: MediaQuery.sizeOf(context).height * .88,
          child: SingleChildScrollView(child: _sharedCardPreview(data)),
        ),
      ),
    );
  }

  Widget _buildSharedCard() {
    final data = widget.sharedCard!;
    if (data.kind == 'entity') {
      return _buildLedger(
        [data.row],
        metricsTab: data.tab,
        indexOffset: data.index,
        onRowTap: _openSharedEntityDetail,
        allowDefaultDetailOpen: false,
      );
    }
    if (data.kind == 'panel') {
      final chart = _expandedTrendKey == null
          ? null
          : _trendChartFor(
              data.row,
              soloMetricKey: _expandedTrendKey,
              showHeader: false,
            );
      return Padding(
        padding: const EdgeInsets.all(8),
        child: Column(
          mainAxisSize: MainAxisSize.min,
          crossAxisAlignment: CrossAxisAlignment.stretch,
          children: [
            if (chart != null) ...[chart, const SizedBox(height: 12)],
            _buildHeroStatRail(
              data.totals,
              entityRow: data.tab == 'netTa' ? null : data.row,
              sectionOnly: data.section,
              whiteBackground: data.toJson()['panelWhite'] == true,
              focusKey: _expandedTrendKey,
              traceKey: _heroTraceKey,
              onMetricActivate: (next) => setState(() {
                _expandedTrendKey = next.focus;
                _heroTraceKey = next.trace;
              }),
            ),
          ],
        ),
      );
    }
    final trend = data.row['trend'] as Map? ?? const {};
    final profit = (trend['profit'] as List? ?? const [])
        .whereType<num>()
        .map((v) => v.toDouble())
        .toList();
    final labels = (trend['labels'] as List? ?? const [])
        .map((v) => v.toString())
        .toList();
    return _buildHeroShell(
      child: _buildHero(
        totalsOverride: data.totals,
        summaryTitle: data.title,
        showFilters: false,
        profitSeriesOverride: profit,
        profitLabelsOverride: labels,
      ),
    );
  }

  /// 查一次数据延迟预警。进页、回到灯塔、下拉刷新和 30 秒轮询都走这里；
  /// 切期间 / 切账本 tab 不额外触发，避免一次交互重复请求。失败不弹错、
  /// 不拦主流程，但会明确标成「预警未取到」。
  Future<void> _loadDelayNotice() async {
    if (_delayNoticeLoading) return;
    _delayNoticeLoading = true;
    try {
      final res = await _service.fetchDelayNotices();
      if (!mounted) return;
      setState(() {
        _delayNotices = res.notices;
        _pixelCtl.storm = res.notices.any((n) => !n.isEmpty);
        _delayNoticeFetch = res.ok ? _LhNoticeFetch.ok : _LhNoticeFetch.failed;
        if (res.notices.isEmpty) _delayNoticeOpen = false;
        final active = res.notices.where((n) => !n.isEmpty).toList();
        if (active.isEmpty) {
          _delayNoticeAutoOpenedFor = '';
        } else {
          final sig = active
              .map(
                (n) =>
                    '${n.sourceCode}|${n.bizDeptCode}|${n.message}|${n.raisedAt}',
              )
              .join('\n');
          if (sig != _delayNoticeAutoOpenedFor) {
            _delayNoticeAutoOpenedFor = sig;
            _delayNoticeOpen = true;
          }
        }
      });
    } finally {
      _delayNoticeLoading = false;
    }
  }

  /// 灯塔是底部导航里的保活页，用户停在别处时不会销毁。通知不能只在第一次
  /// initState 查一次，否则同事后来发出的 OPEN 预警在本机上会一直显示成灰色。
  /// 当前页每 30 秒轻量重查一次；切走即停，切回来立即查并恢复轮询。
  void _syncDelayNoticePolling() {
    _delayNoticeTimer?.cancel();
    _delayNoticeTimer = null;
    if (widget.sharedCard != null ||
        !widget.active ||
        !widget.session.effectiveLighthouseAccess) {
      return;
    }
    _delayNoticeTimer = Timer.periodic(_delayNoticePollEvery, (_) {
      if (!mounted || !widget.active) return;
      unawaited(_loadDelayNotice());
    });
  }

  /// 落款旁只留「查挂了」这一句。小喇叭始终存在，有记录时点开看原文。
  ///   查成功 0 行 → 小喇叭灰显
  ///   有 OPEN 行 → 小喇叭高亮
  ///   404 / 表没有 / 查挂了 → 预警未取到
  String? get _delayNoticeMissNote {
    if (_delayNoticeFetch == _LhNoticeFetch.failed) return '预警未取到';
    return null;
  }

  /// 小喇叭表达的是全局运行提醒，不属于当前账本页签。只要接口返回 OPEN
  /// 通知就必须高亮；不能因为用户恰好停在净 TA 等页签把通知过滤成灰色。
  List<LighthouseDelayNotice> get _activeDelayNotices =>
      _delayNotices.where((n) => !n.isEmpty).toList(growable: false);

  @override
  void didUpdateWidget(covariant _LighthouseTopicBody oldWidget) {
    super.didUpdateWidget(oldWidget);
    if (widget.sharedCard != null) {
      if (widget.sharedCard != oldWidget.sharedCard) {
        _applySharedCard(widget.sharedCard!);
      }
      return;
    }
    if (widget.active != oldWidget.active) {
      if (widget.active) {
        _installBackInterceptor();
        // 保活页重新出现时先立即对一次，不能等下一轮 30 秒。
        unawaited(_loadDelayNotice());
      } else {
        _clearBackInterceptor();
      }
      _syncDelayNoticePolling();
    }
    _recoverFromUnavailableNetTa();
    _recoverFromUnavailablePeople();
    _recoverFromHiddenAnalysis();
  }

  /// 「分析」tab 已从维度条拿掉。若还停在分析页，踢回产品维。
  void _recoverFromHiddenAnalysis() {
    if (_tab != 'analysis' || lighthouseLedgerShowsAnalysisTab) return;
    setState(() {
      _tab = 'product';
      _groupFilter = '全部';
      _tabBarShowsGroups = true;
      _hunFilter = '全部';
      _tradeTypeFilter = '全部';
      if (_sortField == 'netTa') _sortField = 'profit';
      _listLimit = _listPageSize;
      _rowsCacheKey = '';
      _rowsCache = null;
      _closeMetricPage();
      _restoreSharedHeroMetrics();
    });
    unawaited(_loadTab('product'));
  }

  /// 同 [_recoverFromUnavailableNetTa]：会话刷新可能收回月度绩效考评权限，
  /// 或人效 tab 已从维度条拿掉。别把一个进不去的 tab 留在选中态。
  void _recoverFromUnavailablePeople() {
    if (_tab != 'people' || _showsPeopleTab) return;
    setState(() {
      _tab = 'product';
      _groupFilter = '全部';
      _tabBarShowsGroups = true;
      _tradeTypeFilter = '全部';
      _sortField = 'profit';
      _listLimit = _listPageSize;
      _rowsCacheKey = '';
      _rowsCache = null;
      _closeMetricPage();
      _biViewOpen = false;
      _restoreSharedHeroMetrics();
    });
    unawaited(_loadTab('product'));
  }

  /// A session refresh can revoke Net TA while this keep-alive page is open.
  /// Return to the safe default instead of leaving an inaccessible tab selected.
  void _recoverFromUnavailableNetTa() {
    if (_tab != 'netTa' || _hasNetTaAccess) return;
    setState(() {
      _tab = 'product';
      _groupFilter = '全部';
      _tabBarShowsGroups = true;
      _hunFilter = '全部';
      _tradeTypeFilter = '全部';
      _anomalyFilter = '全部';
      _sortField = 'profit';
      _listLimit = _listPageSize;
      _rowsCacheKey = '';
      _rowsCache = null;
      _closeMetricPage();
      _invalidateAiSummary();
      _clearNetTAHeroTransientState();
      _restoreSharedHeroMetrics();
    });
    unawaited(_loadTab('product'));
  }

  void _installBackInterceptor() {
    widget.navigation.canBackInterceptor = _hasInternalBackStack;
    widget.navigation.backInterceptor = _handleInternalBack;
  }

  void _clearBackInterceptor() {
    if (widget.navigation.canBackInterceptor == _hasInternalBackStack) {
      widget.navigation.canBackInterceptor = null;
    }
    if (widget.navigation.backInterceptor == _handleInternalBack) {
      widget.navigation.backInterceptor = null;
    }
  }

  @override
  void dispose() {
    _heroPagePos.dispose();
    _pkHost = null;
    _pkQueryCtrl.dispose();
    _clearBackInterceptor();
    _delayNoticeTimer?.cancel();
    _ddEntry?.remove();
    _detailSkuSearchCtrl.dispose();
    _ledgerSearchCtl.dispose();
    _ledgerSearchFocus.dispose();
    _discountFocusTimer?.cancel();
    _mainListScrollCtrl.dispose();
    _ledgerTabsStuck.dispose();
    _bf?.dispose();
    _service.dispose();
    _heroFullscreenTick.dispose();
    _pixelCtl.dispose();
    super.dispose();
  }

  void _captureMainListScroll() {
    if (_mainListScrollCtrl.hasClients) {
      _savedMainListOffset = _mainListScrollCtrl.offset;
    }
  }

  void _restoreMainListScroll() {
    final saved = _savedMainListOffset;
    if (saved == null) return;
    WidgetsBinding.instance.addPostFrameCallback((_) {
      if (!mounted || !_mainListScrollCtrl.hasClients) return;
      final max = _mainListScrollCtrl.position.maxScrollExtent;
      _mainListScrollCtrl.jumpTo(lighthouseRestoreScrollOffset(saved, max));
    });
  }

  bool _hasInternalBackStack() =>
      _detailKey != null || _metricPageKey != null || _biViewOpen;

  String _detailRouteKey() {
    final detail = '${_detailType ?? ''}:${_detailKey ?? ''}';
    final drill = '${_drillDim ?? ''}:${_drillKey ?? ''}';
    final code = _codeDrillKey ?? '';
    return 'detail:$detail:drill:$drill:code:$code';
  }

  void _enterMetricPage(String key) {
    _metricPageKey = key;
    _metricPageStack
      ..clear()
      ..add(key);
  }

  void _switchMetricPage(String key) {
    if (_metricPageKey == key) return;
    _metricPageKey = key;
    _metricPageStack.add(key);
  }

  /// 指标页内返回上一级；栈空则回到主页列表。
  bool _popMetricPage() {
    if (_metricPageStack.length > 1) {
      _metricPageStack.removeLast();
      _metricPageKey = _metricPageStack.last;
      return true;
    }
    _closeMetricPage();
    return false;
  }

  void _closeMetricPage() {
    _metricPageKey = null;
    _metricPageStack.clear();
  }

  bool _handleInternalBack() {
    if (_biViewOpen) {
      _closeDropdown();
      _restoreErrorProbe();
      setState(() => _biViewOpen = false);
      return true;
    }
    if (_detailKey != null) {
      _closeDropdown();
      if (_codeDrillKey != null) {
        setState(() {
          _resetCodeDrill();
          _detailPage = 1;
        });
        return true;
      }
      if (_drillKey != null) {
        setState(() {
          _resetDetailDrill();
          _detailPage = 1;
          _resetDetailSkuSearch();
        });
        return true;
      }
      if (_detailReturnStack.isNotEmpty) {
        setState(_popDetailReturnStack);
        return true;
      }
      setState(() {
        _detailReturnStack.clear();
        _detailKey = null;
        _detailType = null;
        _resetDetailSkuSearch();
        _resetDetailDrill();
        _resetCodeDrill();
        _closeMetricPage();
      });
      _restoreMainListScroll();
      return true;
    }
    if (_metricPageKey != null) {
      _closeDropdown();
      setState(_popMetricPage);
      return true;
    }
    return false;
  }

  void _resetDetailSkuSearch() {
    _detailSkuQuery = '';
    if (_detailSkuSearchCtrl.text.isNotEmpty) {
      _detailSkuSearchCtrl.clear();
    }
  }

  void _resetDetailDrill() {
    if (_drillDim != null) {
      _detailSubTab = _drillDim!;
    }
    _resetCodeDrill();
    _drillDim = null;
    _drillKey = null;
    _drillDisplayName = '';
    _drillGroup = '';
    _detailDrillReloadAttempted = false;
    _resetCodeDrill();
  }

  void _resetCodeDrill() {
    _codeDrillKey = null;
    _codeDrillDisplayName = '';
    _codeDrillGroup = '';
  }

  List<Map<String, dynamic>> _supplierCodeDrillRows(
    Map<String, dynamic> dict,
    String skuKey,
  ) {
    final raw = dict['supplier_code_drill'];
    if (raw is Map && raw[skuKey] is List) {
      return (raw[skuKey] as List)
          .whereType<Map>()
          .map((e) => Map<String, dynamic>.from(e))
          .toList();
    }
    return const [];
  }

  bool _hasSupplierCodeDrill(
    Map<String, dynamic> dict,
    Map<String, dynamic> row,
  ) {
    final skuKey = row['name']?.toString() ?? '';
    return _supplierCodeDrillRows(dict, skuKey).isNotEmpty;
  }

  void _openSupplierCodeDrill({
    required Map<String, dynamic> contextDict,
    required Map<String, dynamic> row,
  }) {
    final skuKey = row['name']?.toString() ?? '';
    if (!_hasSupplierCodeDrill(contextDict, row)) {
      _showDetailDrillHint('暂无 supplier_product_code 明细');
      return;
    }
    setState(() {
      _codeDrillKey = skuKey;
      _codeDrillDisplayName = skuKey;
      _codeDrillGroup = row['group']?.toString() ?? '';
      _detailPage = 1;
      _resetDetailSkuSearch();
    });
  }

  String _detailDrillMapField(String dim) {
    switch (dim) {
      case 'product':
        return 'product_drill';
      case 'supply':
        return 'supply_drill';
      case 'channel':
        return 'channel_drill';
      case 'province':
        return 'province_drill';
      case 'project':
        return 'project_drill';
      case 'productName':
        return 'sku_drill';
      case 'signEntity':
        return 'sign_entity_drill';
      case 'people':
        return 'people_drill';
      default:
        return '';
    }
  }

  String _detailRowDrillKey(String dim, Map<String, dynamic> row) {
    return lighthouseDetailRowDrillKey(
      name: row['name']?.toString() ?? '',
      group: row['group']?.toString() ?? '',
    );
  }

  Map<String, dynamic>? _detailEntityMap(String type, String key) {
    if (_bundle == null) return null;
    final Map<String, dynamic> root;
    switch (type) {
      case 'product':
        root = _bundle!.productDetail;
      case 'supply':
        root = _bundle!.supplyDetail;
      case 'channel':
        root = _bundle!.channelDetail;
      case 'people':
        root = _bundle!.peopleDetail;
      default:
        return null;
    }
    final raw = root[key];
    if (raw is Map) {
      return Map<String, dynamic>.from(raw);
    }
    return null;
  }

  /// 当前详情 Hero 对应的汇总实体（L3 用 drill payload，否则用 L2 detail header）。
  Map<String, dynamic>? _currentDetailSummaryForTrend() {
    final type = _detailType;
    final key = _detailKey;
    if (type == null || key == null) return null;
    final detail = _detailEntityMap(type, key);
    if (detail == null) {
      // detail 尚未返回时，仍可用一级列表行 trend 撑起 sparkline
      return _findDimensionRow(type, key);
    }
    if (_drillKey != null && _drillDim != null) {
      final drillRoot = _detailDrillRoot(detail, _drillDim!);
      final drillPayload = drillRoot?[_drillKey!];
      if (drillPayload is Map) {
        return Map<String, dynamic>.from(drillPayload);
      }
    }
    return detail;
  }

  bool _detailHasDrillMaps(Map<String, dynamic> detail) {
    for (final field in const [
      'product_drill',
      'supply_drill',
      'channel_drill',
      'province_drill',
      'project_drill',
      'sku_drill',
      'sign_entity_drill',
      'people_drill',
    ]) {
      final raw = detail[field];
      if (raw is Map && raw.isNotEmpty) return true;
    }
    return false;
  }

  Map<String, dynamic>? _detailDrillRoot(
    Map<String, dynamic> detail,
    String dim,
  ) {
    final field = _detailDrillMapField(dim);
    if (field.isEmpty) return null;
    final raw = detail[field];
    if (raw is Map) {
      return Map<String, dynamic>.from(raw);
    }
    return null;
  }

  String? _resolveDrillKey(
    Map<String, dynamic>? drillRoot,
    String dim,
    Map<String, dynamic> row,
  ) {
    if (drillRoot == null || drillRoot.isEmpty) return null;
    return lighthouseResolveDrillKey(
      drillKeys: drillRoot.keys.map((k) => k.toString()),
      name: row['name']?.toString() ?? '',
      group: row['group']?.toString() ?? '',
    );
  }

  void _showDetailDrillHint(String message) {
    if (!mounted) return;
    ScaffoldMessenger.of(context).showSnackBar(
      SnackBar(
        content: Text(
          message,
          style: LhTypography.sans(
            size: 12.5,
            color: DunesColors.resolve(context, Colors.white),
            context: context,
          ),
        ),
        duration: const Duration(seconds: 2),
        behavior: SnackBarBehavior.floating,
      ),
    );
  }

  Future<void> _ensureDetailDrillData() async {
    if (_detailDrillRefreshPending || _loading) return;
    final type = _detailType;
    final key = _detailKey;
    if (type == null || key == null) return;
    _detailDrillRefreshPending = true;
    try {
      await _loadDetail(type, key);
    } finally {
      _detailDrillRefreshPending = false;
    }
  }

  void _openDetailDrill({
    required Map<String, dynamic> detailDict,
    required String dim,
    required Map<String, dynamic> row,
  }) {
    final drillRoot = _detailDrillRoot(detailDict, dim);
    final drillKey = _resolveDrillKey(drillRoot, dim, row);
    if (drillKey != null) {
      setState(() {
        _resetCodeDrill();
        _drillDim = dim;
        _drillKey = drillKey;
        _drillDisplayName = row['name']?.toString() ?? '';
        var group = row['group']?.toString() ?? '';
        // 唯一前缀回退命中 name::group 时，把分组补回 Hero 文案。
        if (group.isEmpty && drillKey.contains('::')) {
          group = drillKey.substring(drillKey.indexOf('::') + 2);
        }
        _drillGroup = group;
        final drillTabs = _drillSubTabsFor(dim);
        _detailSubTab = drillTabs.first.key;
        _detailPage = 1;
        _resetDetailSkuSearch();
      });
      return;
    }

    if (!_detailHasDrillMaps(detailDict)) {
      _showDetailDrillHint('当前网关未返回细分明细，请部署新版 lighthouse-go 或使用本地 API');
      _ensureDetailDrillData();
      return;
    }

    _showDetailDrillHint('该行暂无细分明细');
  }

