        padding: const EdgeInsets.symmetric(horizontal: 10, vertical: 2),
        decoration: BoxDecoration(
          color: DunesColors.resolve(
            context,
            LhColors.paper,
            role: DunesColorRole.surface,
          ),
          border: Border.all(
            color: active
                ? DunesColors.resolve(
                    context,
                    LhColors.ink2,
                    role: DunesColorRole.border,
                  )
                : DunesColors.resolve(
                    context,
                    LhColors.line,
                    role: DunesColorRole.border,
                  ),
            width: 1,
          ),
          borderRadius: BorderRadius.circular(5),
        ),
        child: Row(
          children: [
            Icon(
              Icons.search_rounded,
              size: 15,
              color: active
                  ? DunesColors.resolve(context, LhColors.ink)
                  : DunesColors.resolve(context, LhColors.mute),
            ),
            const SizedBox(width: 8),
            Expanded(
              child: TextField(
                controller: _detailSkuSearchCtrl,
                style: LhTypography.sans(
                  size: 12,
                  color: DunesColors.resolve(context, LhColors.ink),
                  weight: FontWeight.w500,
                  context: context,
                ),
                decoration: InputDecoration(
                  isDense: true,
                  hintText: '搜索 SKU 名称…',
                  hintStyle: LhTypography.sans(
                    size: 12,
                    color: DunesColors.resolve(context, LhColors.mute2),
                    weight: FontWeight.w400,
                    context: context,
                  ),
                  border: InputBorder.none,
                  contentPadding: const EdgeInsets.symmetric(vertical: 8),
                ),
                textInputAction: TextInputAction.search,
                onChanged: (v) => setState(() {
                  _detailSkuQuery = v;
                  _detailPage = 1;
                }),
              ),
            ),
            if (active)
              GestureDetector(
                behavior: HitTestBehavior.opaque,
                onTap: () => setState(() {
                  _resetDetailSkuSearch();
                  _detailPage = 1;
                }),
                child: Padding(
                  padding: const EdgeInsets.all(4),
                  child: Icon(
                    Icons.close_rounded,
                    size: 14,
                    color: DunesColors.resolve(context, LhColors.mute),
                  ),
                ),
              ),
          ],
        ),
      ),
    );
  }

  /// 人停在二级 / 三级时换日期，摘要会换成一份空详情的新包。
  /// 把当前实体的详情留住，列表才不会被卸掉再从顶部长出来。
  LighthouseDataBundle _retainOpenDetail(LighthouseDataBundle next) {
    if (_detailKey == null) return next;
    final prev = _bundle;
    if (prev == null) return next;
    return next.copyWith(
      productDetail: prev.productDetail,
      supplyDetail: prev.supplyDetail,
      channelDetail: prev.channelDetail,
      peopleDetail: prev.peopleDetail,
    );
  }

  Future<void> _load() async {
    final requestedPeriod = _period;
    final requestedOffset = _periodOffset;
    // v12.7 · 自定义区间在这里也参与 cache-key + 传给后端 (startDate/endDate).
    //   后端如未支持这两个参数, 需要在 LighthouseService.fetchSummary /
    //   fetchOverview / fetchDimension / fetchAnalysisCube / fetchDetail
    //   的签名里都加上可选 `DateTime? startDate, DateTime? endDate`;
    //   收到后拿它们做 SQL where 覆盖 period+offset 的桶推导.
    final requestedStart = _customStart;
    final requestedEnd = _customEnd;
    final requestedTab = _tab;
    final requestedGroup = _groupFilter;
    final cacheKey =
        '$requestedPeriod|$requestedOffset|${requestedStart?.toIso8601String() ?? ""}|${requestedEnd?.toIso8601String() ?? ""}';
    bool stillCurrent() =>
        requestedPeriod == _period &&
        requestedOffset == _periodOffset &&
        requestedStart == _customStart &&
        requestedEnd == _customEnd &&
        requestedTab == _tab &&
        requestedGroup == _groupFilter;
    final service = _service;
    final tabToLoad = (requestedTab == 'analysis' || requestedTab == 'netTa')
        ? 'product'
        : requestedTab;
    // 摘要与当前列表没有数据依赖，网络请求并行启动；摘要先到即可先结束首屏遮罩。
    final summaryRequest = service.fetchSummary(
      period: requestedPeriod,
      offset: requestedOffset,
      startDate: requestedStart,
      endDate: requestedEnd,
      tab: tabToLoad,
      group: requestedGroup,
    );
    final dimensionRequest = requestedTab == 'netTa'
        ? null
        : service.fetchDimension(
            tab: tabToLoad,
            period: requestedPeriod,
            offset: requestedOffset,
            startDate: requestedStart,
            endDate: requestedEnd,
          );
    // 即使摘要失败走 overview 兜底，也要消费并行列表请求的错误，避免未处理 Future。
    if (dimensionRequest != null) {
      unawaited(dimensionRequest.then<void>((_) {}, onError: (Object _) {}));
    }
    try {
      final summary = await summaryRequest;
      if (mounted && stillCurrent()) {
        setState(() {
          _splitCacheKey = cacheKey;
          final carryTab = requestedTab == 'netTa' ? 'netTa' : tabToLoad;
          final carryRows =
              _bundle?.rowsOf(carryTab) ?? const <Map<String, dynamic>>[];
          var next = LighthouseDataBundle.empty().withSummary(summary);
          // 新列表还在路上时先留着上一期的行（压淡、不可点），列表不塌成
          // 240 高的空白 —— 塌了滚动位置就被夹回顶上，看起来像整页跳走。
          if (carryRows.isNotEmpty) {
            next = next.withDimension(carryTab, carryRows);
            _staleRowsTab = carryTab;
          } else {
            _staleRowsTab = null;
          }
          _bundle = _retainOpenDetail(next);
          _loadError = null;
          _loading = false;
          _loadedTabs.clear();
          _loadingTabs.clear();
          _tabLoadKeys.clear();
          _tabErrors.clear();
          _loadingDetails.clear();
          _autoDetailAttempts.clear();
          _detailErrors.clear();
          _loadedTrends.clear();
          _loadingTrends.clear();
          _failedTrends.clear();
          _trendErrors.clear();
          _trendCache.clear();
          _productL3VisibleCount.clear();
          _discountsLoading = false;
          _discountsByName = const {};
          _fundPoolLoading = false;
          _fundPoolByProvince = const {};
          _fundPoolSnapshot = LighthouseFundPoolSnapshot.empty;
          // 资金池不跟周期走：换周期 / 刷新时先放回缓存那份（不闪「资金池加载中…」），
          // 是否去后端再拿由 _loadFundPool 按新鲜度决定。
          _restoreFundPoolFromMemory();
          _heroFundPoolTried = false;
          _fundPoolProfitMonth = const {};
          _fundPoolProfitDay = const {};
          _expandedFundPools.clear();
          _fundPoolTraces.clear();
          _rowsCacheKey = '';
          _rowsCache = null;
          _cubeCacheKey = '';
          _cubeData = null;
          _cubeError = false;
          // 「数据已同步」展示前端拉取数据的当前时刻（强制中国时间 UTC+8，不依赖设备时区）。
          _lastSyncedAt = _nowCST();
          _syncMetricsFromUI();
          _rememberSharedHeroMetricsIfUnfiltered(
            requestedGroup,
            _bundle?.metrics,
          );
        });
        _pixelAfterLoad(cacheKey);
      }
      if (stillCurrent()) {
        if (requestedTab == 'netTa') {
          await _loadTab('netTa');
        } else if (dimensionRequest != null) {
          await _loadTab(tabToLoad, prefetched: dimensionRequest);
        }
        if (_biViewOpen) await _ensureBiLedgerDims();
      }
    } catch (e) {
      try {
        final bundle = await service.fetchOverview(
          period: requestedPeriod,
          offset: requestedOffset,
          startDate: requestedStart,
          endDate: requestedEnd,
        );
        if (mounted && stillCurrent()) {
          setState(() {
            _splitCacheKey = cacheKey;
            _bundle = _retainOpenDetail(bundle);
            _loadedTabs
              ..clear()
              ..addAll(const ['product', 'supply', 'channel']);
            _loadingTabs.clear();
            _tabLoadKeys.clear();
            _tabErrors.clear();
            _loadingDetails.clear();
            _autoDetailAttempts.clear();
            _detailErrors.clear();
            _failedTrends.clear();
            _productL3VisibleCount.clear();
            _loading = false;
            _staleRowsTab = null;
            _loadError = null;
            _rowsCacheKey = '';
            _rowsCache = null;
            _cubeCacheKey = '';
            _cubeData = null;
            _cubeError = false;
            _lastSyncedAt = _nowCST();
            _syncMetricsFromUI();
            _ensureDefaultGroupFilter();
            _rememberSharedHeroMetricsIfUnfiltered(
              requestedGroup,
              _bundle?.metrics,
            );
          });
          _pixelAfterLoad(cacheKey);
        }
        if (stillCurrent()) {
          if (requestedTab == 'netTa') {
            await _loadTab('netTa');
          }
          if (_biViewOpen) await _ensureBiLedgerDims();
        }
      } catch (_) {
        if (mounted && stillCurrent()) {
          setState(() {
            _loading = false;
            _staleRowsTab = null;
            _loadError = e.toString().replaceFirst('Exception: ', '');
          });
        }
      }
    }
  }

  /// 顶栏像素灯塔：一轮数据落地后放哪个动效。
  ///   首次进页 / 手动刷新 → 同步完成；换了周期或日期 → 切换日期；
  ///   只是切页签、切分类 → 不放（太频繁会吵）。
  ///   放了的那一轮里，利润环比上涨且超过醒目门槛（±30%）→ 晚 1.6 秒再放烟花。
  void _pixelAfterLoad(String key) {
    final first = _pixelLoadKey == null;
    final keyChanged = _pixelLoadKey != key;
    _pixelLoadKey = key;
    final refreshed = _pixelRefreshPending;
    _pixelRefreshPending = false;
    if (first || refreshed) {
      _pixelCtl.fire(LighthousePixelEvent.sync);
    } else if (keyChanged) {
      _pixelCtl.fire(LighthousePixelEvent.date);
    } else {
      return;
    }
    final d = _deltaForMetric('profit');
    if (d != null && d.isUp && lighthouseDeltaIsLoud(d.pct)) {
      Future<void>.delayed(const Duration(milliseconds: 1600), () {
        if (mounted) _pixelCtl.fire(LighthousePixelEvent.profit);
      });
    }
  }

  /// 按当前 Tab + L1 分类重拉 Hero（数字 / 环比 / 走势）。列表维度数据保留。
  Future<void> _reloadHeroSummary() async {
    if (_isNonLedgerTab || _tab == 'netTa') return;
    final requestedPeriod = _period;
    final requestedOffset = _periodOffset;
    final requestedStart = _customStart;
    final requestedEnd = _customEnd;
    final requestedTab = _tab;
    final requestedGroup = _groupFilter;
    try {
      final summary = await _service.fetchSummary(
        period: requestedPeriod,
        offset: requestedOffset,
        startDate: requestedStart,
        endDate: requestedEnd,
        tab: requestedTab,
        group: requestedGroup,
      );
      if (!mounted) return;
      if (requestedPeriod != _period ||
          requestedOffset != _periodOffset ||
          requestedStart != _customStart ||
          requestedEnd != _customEnd ||
          requestedTab != _tab ||
          requestedGroup != _groupFilter) {
        return;
      }
      setState(() {
        final base = _bundle ?? LighthouseDataBundle.empty();
        _bundle = base.withSummary(summary);
        _lastSyncedAt = _nowCST();
        _syncMetricsFromUI();
        _rememberSharedHeroMetricsIfUnfiltered(
          requestedGroup,
          _bundle?.metrics,
        );
      });
    } catch (e) {
      debugPrint('lighthouse hero reload failed: $e');
    }
  }

  /// 切换 L1 分类并同步 Hero。
  void _setGroupFilter(String group, {bool closeDropdown = false}) {
    final next = group.trim().isEmpty ? '全部' : group;
    if (next == _groupFilter) {
      if (closeDropdown) _closeDropdown();
      return;
    }
    setState(() {
      _groupFilter = next;
      // 切分类 = 换了一份数据，之前点住的那一天已经不是同一个口径 —— 直接回本期。
      _heroPointIndex = null;
      _listLimit = _listPageSize;
      _rowsCacheKey = '';
      _rowsCache = null;
      if (next == '全部') _restoreSharedHeroMetrics();
    });
    if (closeDropdown) _closeDropdown();
    final reload = _reloadHeroSummary();
    _heroGroupReload = reload;
    unawaited(reload);
  }

  /// 最近一次切分组触发的 Hero 重拉；走势大图等它回来再画，不先画旧分组。
  Future<void>? _heroGroupReload;

  Future<void> _loadTab(
    String tab, {
    bool force = false,
    Future<Map<String, dynamic>>? prefetched,
  }) async {
    if (tab == 'analysis') return;
    final requestedPeriod = _period;
    final requestedOffset = _periodOffset;
    final requestedStart = _customStart;
    final requestedEnd = _customEnd;
    final cacheKey =
        '$requestedPeriod|$requestedOffset|${requestedStart?.toIso8601String() ?? ""}|${requestedEnd?.toIso8601String() ?? ""}';
    final netTaSeriesReady =
        tab != 'netTa' || lighthouseNetTAHeroSeriesReady(_bundle?.metrics);
    // 折扣 UI 已关掉：进供给不再预拉 /discounts，避免每行加条子把 Web 卡死。
    if (!force &&
        _splitCacheKey == cacheKey &&
        _loadedTabs.contains(tab) &&
        netTaSeriesReady) {
      return;
    }
    // 同一区间已经在飞：别再开一条。换了区间则让旧请求自己过期退出。
    if (_loadingTabs.contains(tab) && _tabLoadKeys[tab] == cacheKey) {
      return;
    }
    setState(() {
      _loadingTabs.add(tab);
      _tabLoadKeys[tab] = cacheKey;
      _tabErrors.remove(tab);
    });
    // 趋势先并行请求；供给补充指标等主列表首帧完成后再加载。
    if (tab != 'netTa') unawaited(_loadTrend(tab, force: force));
    try {
      late final List<Map<String, dynamic>> rows;
      Map<String, dynamic>? tabUi;
      Map<String, dynamic>? netTaMetrics;
      if (tab == 'netTa') {
        final data = await _service.fetchNetTA(
          period: requestedPeriod,
          offset: requestedOffset,
          startDate: requestedStart,
          endDate: requestedEnd,
        );
        netTaMetrics = data;
        final cats = (data['categories'] as List? ?? const [])
            .whereType<Map>()
            .map((e) => Map<String, dynamic>.from(e))
            .toList();
        rows = lighthousePrepareNetTARows(cats);
      } else {
        final data =
            await (prefetched ??
                _service.fetchDimension(
                  tab: tab,
                  period: requestedPeriod,
                  offset: requestedOffset,
                  startDate: requestedStart,
                  endDate: requestedEnd,
                ));
        rows = (data['rows'] as List? ?? const [])
            .whereType<Map>()
            .map((e) => Map<String, dynamic>.from(e))
            .toList();
        final metrics = data['metrics'];
        if (metrics is Map) {
          final m = Map<String, dynamic>.from(metrics);
          if (m['tab'] is Map) {
            tabUi = Map<String, dynamic>.from(m['tab'] as Map);
          } else {
            final ui = m['ui'];
            if (ui is Map) {
              final tabs = ui['tabs'];
              if (tabs is Map && tabs[tab] is Map) {
                tabUi = Map<String, dynamic>.from(tabs[tab] as Map);
              }
            }
          }
        }
      }
      if (!mounted ||
          requestedPeriod != _period ||
          requestedOffset != _periodOffset ||
          requestedStart != _customStart ||
          requestedEnd != _customEnd) {
        return;
      }
      setState(() {
        var base = _bundle ?? LighthouseDataBundle.empty();
        base = base.withDimension(tab, rows);
        if (tabUi != null) {
          base = base.withTabUi(tab, tabUi);
        }
        if (netTaMetrics != null) {
          final nextMetrics = Map<String, dynamic>.from(base.metrics);
          final total = netTaMetrics['total'];
          if (total is num) nextMetrics['netTa'] = total.toDouble();
          final pct = netTaMetrics['deltaPct'];
          if (pct is num) nextMetrics['netTaDeltaPct'] = pct.toDouble();
          final dir = netTaMetrics['deltaDir'];
          if (dir is String) nextMetrics['netTaDeltaDir'] = dir;
          final unmapped = netTaMetrics['unmapped'];
          if (unmapped is Map) {
            final amt = unmapped['amount'];
            if (amt is num) nextMetrics['netTaUnmapped'] = amt.toDouble();
            final samples = unmapped['samples'];
            if (samples is List) {
              nextMetrics['netTaUnmappedSamples'] = [
                for (final s in samples)
                  if (s.toString().trim().isNotEmpty) s.toString().trim(),
              ];
            }
          } else {
            nextMetrics.remove('netTaUnmapped');
            nextMetrics.remove('netTaUnmappedSamples');
          }
          lighthouseMergeNetTAHeroTrend(
            nextMetrics,
            lighthouseNetTAHeroTrendFromPayload(netTaMetrics),
          );
          // Hero 指标栏三列取数：后端 `hero` 已按 lighthouseNetTAHeroSections
          // 的键名给好值与环比，这里摊平成 metrics，_deltaForMetric 直接可用。
          // 放在 trend 合并之后：hero 是区间真实汇总，比曲线末点更权威。
          final heroStats = netTaMetrics['hero'];
          if (heroStats is Map) {
            for (final entry in heroStats.entries) {
              final key = entry.key.toString().trim();
              final raw = entry.value;
              if (key.isEmpty || raw is! Map) continue;
              final value = raw['value'];
              if (value is num) nextMetrics[key] = value.toDouble();
              final pct = raw['deltaPct'];
              if (pct is num) nextMetrics['${key}DeltaPct'] = pct.toDouble();
              final dir = raw['deltaDir'];
              if (dir is String) nextMetrics['${key}DeltaDir'] = dir;
            }
          }
          final unmappedAmount = nextMetrics['netTaUnmapped'];
          if (unmappedAmount is! num) nextMetrics['netTaUnmapped'] = 0.0;
          // 存量锚点：账上现在有多少。拿不到就把键清掉 —— 界面上整行不渲染，
          // 显示 0 会被读成「账上没钱」。
          final bankBalance = netTaMetrics['bankBalance'];
          if (bankBalance is Map) {
            final total = bankBalance['total'];
            if (total is num) {
              nextMetrics['netTaBankBalance'] = total.toDouble();
            } else {
              nextMetrics.remove('netTaBankBalance');
            }
            final asOf = bankBalance['asOf']?.toString().trim() ?? '';
            if (asOf.isNotEmpty) {
              nextMetrics['netTaBankBalanceAt'] = asOf;
            } else {
              nextMetrics.remove('netTaBankBalanceAt');
            }
            final count = bankBalance['companyCount'];
            if (count is num) {
              nextMetrics['netTaBankBalanceCount'] = count.toInt();
            } else {
              nextMetrics.remove('netTaBankBalanceCount');
            }
            // 业务日：来自 bank_flow_sub 的 flow_date，是真的账实时点。
            // 后端没上这个字段之前键不存在，界面自动退回用拉取时刻。
            final asOfDate = bankBalance['asOfDate']?.toString().trim() ?? '';
            if (asOfDate.isNotEmpty) {
              nextMetrics['netTaBankBalanceAtDate'] = asOfDate;
            } else {
              nextMetrics.remove('netTaBankBalanceAtDate');
            }
            // 存量序列。两个点以下画不出线，直接当没有 ——
            // 一根横杠比没有更误导。日/周/月/季/年由后端折好。
            final series = bankBalance['series'];
            if (series is List) {
              final dates = <String>[];
              final totals = <double>[];
              final labels = <String>[];
              for (final e in series.whereType<Map>()) {
                final v = (e['total'] as num?)?.toDouble();
                if (v == null) continue;
                final date = e['date']?.toString().trim() ?? '';
                dates.add(date);
                totals.add(v);
                final label = e['label']?.toString().trim() ?? '';
                labels.add(
                  label.isNotEmpty
                      ? label
                      : lighthouseBankBalanceSeriesLabel(date),
                );
              }
              if (totals.length >= 2) {
                nextMetrics['netTaBankBalanceSeriesDates'] = dates;
                nextMetrics['netTaBankBalanceSeries'] = totals;
                nextMetrics['netTaBankBalanceSeriesLabels'] = labels;
              } else {
                nextMetrics.remove('netTaBankBalanceSeriesDates');
                nextMetrics.remove('netTaBankBalanceSeries');
                nextMetrics.remove('netTaBankBalanceSeriesLabels');
              }
            } else {
              nextMetrics.remove('netTaBankBalanceSeriesDates');
              nextMetrics.remove('netTaBankBalanceSeries');
              nextMetrics.remove('netTaBankBalanceSeriesLabels');
            }
            final change = lighthouseBankBalanceChangeFromPayload(
              bankBalance['change'],
            );
            if (change != null) {
              nextMetrics['netTaBankBalanceChange'] = change.amount;
              nextMetrics['netTaBankBalanceChangeVs'] = change.vs;
              if (change.pct != null) {
                nextMetrics['netTaBankBalanceChangePct'] = change.pct;
              } else {
                nextMetrics.remove('netTaBankBalanceChangePct');
              }
            } else {
              nextMetrics.remove('netTaBankBalanceChange');
              nextMetrics.remove('netTaBankBalanceChangeVs');
              nextMetrics.remove('netTaBankBalanceChangePct');
            }
            // 公司明细接口里已经给了（余额前 80 家），点开时直接用，不再多打一次请求。
            // 账户必须原样带上：丢掉的话前端展开箭头永远出不来。
            final list = bankBalance['companies'];
            if (list is List && list.isNotEmpty) {
              nextMetrics['netTaBankBalanceList'] =
                  lighthouseNetTABankBalanceCompanies(list);
            } else {
              nextMetrics.remove('netTaBankBalanceList');
            }
          } else {
            nextMetrics.remove('netTaBankBalance');
            nextMetrics.remove('netTaBankBalanceAt');
            nextMetrics.remove('netTaBankBalanceAtDate');
            nextMetrics.remove('netTaBankBalanceCount');
            nextMetrics.remove('netTaBankBalanceList');
            nextMetrics.remove('netTaBankBalanceSeries');
            nextMetrics.remove('netTaBankBalanceSeriesDates');
            nextMetrics.remove('netTaBankBalanceSeriesLabels');
            nextMetrics.remove('netTaBankBalanceChange');
            nextMetrics.remove('netTaBankBalanceChangeVs');
            nextMetrics.remove('netTaBankBalanceChangePct');
          }
          base = base.copyWith(metrics: nextMetrics);
        }
        _bundle = base;
        _splitCacheKey = cacheKey;
        _loadedTabs.add(tab);
        _loadingTabs.remove(tab);
        if (_staleRowsTab == tab) _staleRowsTab = null;
        _rowsCacheKey = '';
        _rowsCache = null;
        _syncMetricsFromUI();
        if (tab == _tab) {
          final before = _groupFilter;
          _ensureDefaultGroupFilter();
          if (before != _groupFilter) {
            WidgetsBinding.instance.addPostFrameCallback((_) {
              if (mounted) unawaited(_reloadHeroSummary());
            });
          }
        }
      });
      // 补充数据等主列表首帧画完再请求，避免和主要金额抢连接与解析时间。
      if (tab == 'supply') {
        WidgetsBinding.instance.addPostFrameCallback((_) {
          if (!mounted || _tab != 'supply') return;
          if (lighthouseLedgerShowsDiscountUi) unawaited(_loadDiscounts());
          unawaited(_loadFundPool());
          unawaited(_loadFundPoolProfit());
        });
      }
    } catch (e) {
      if (!mounted) return;
      if (_tabLoadKeys[tab] != cacheKey) return;
      setState(() {
        _tabErrors[tab] = e.toString().replaceFirst('Exception: ', '');
        // 新列表拿不到：别把上一期的行当成这一期的数留在那儿。
        if (_staleRowsTab == tab) {
          _staleRowsTab = null;
          _bundle = _bundle?.withDimension(tab, const <Map<String, dynamic>>[]);
          _rowsCacheKey = '';
          _rowsCache = null;
        }
      });
    } finally {
      if (_tabLoadKeys[tab] == cacheKey) {
        _loadingTabs.remove(tab);
        _tabLoadKeys.remove(tab);
      }
    }
  }

  Future<void> _loadTrend(String tab, {bool force = false}) async {
    if (widget.sharedCard != null) return;
    if (tab == 'analysis' || tab == 'netTa') return;
    final requestedPeriod = _period;
    final requestedOffset = _periodOffset;
    final requestedStart = _customStart;
    final requestedEnd = _customEnd;
    final key =
        '$tab|$requestedPeriod|$requestedOffset|${requestedStart?.toIso8601String() ?? ""}|${requestedEnd?.toIso8601String() ?? ""}';
    if (!force && _loadedTrends.contains(key) && _trendCache.containsKey(tab)) {
      return;
    }
    if (!force && _failedTrends.contains(key)) return;
    if (force) {
      _loadedTrends.remove(key);
      _failedTrends.remove(key);
    }
    if (_loadingTrends.contains(key)) return;
    _loadingTrends.add(key);
    try {
      final data = await _service.fetchTrend(
        tab: tab,
        period: requestedPeriod,
        offset: requestedOffset,
        startDate: requestedStart,
        endDate: requestedEnd,
      );
      final trends = Map<String, dynamic>.from(
        data['trends'] as Map? ?? const {},
      );
      if (!mounted ||
          requestedPeriod != _period ||
          requestedOffset != _periodOffset ||
          requestedStart != _customStart ||
          requestedEnd != _customEnd) {
        return;
      }
      // 独立缓存：即使该维 rows 尚未加载，二级子行也能按 key 取到走势。
      final cached = <String, Map<String, dynamic>>{};
      trends.forEach((k, v) {
        if (v is Map) {
          cached[k.toString()] = Map<String, dynamic>.from(v);
        }
      });
      setState(() {
        _trendCache[tab] = cached;
        _trendErrors.remove(tab);
        _failedTrends.remove(key);
        final base = _bundle ?? LighthouseDataBundle.empty();
        _bundle = base.withTrends(tab, trends);
        _loadedTrends.add(key);
        _rowsCacheKey = '';
        _rowsCache = null;
      });
    } catch (e) {
      if (!mounted ||
          requestedPeriod != _period ||
          requestedOffset != _periodOffset ||
          requestedStart != _customStart ||
          requestedEnd != _customEnd) {
        return;
      }
      setState(() {
        _failedTrends.add(key);
        _trendErrors[tab] = e.toString().replaceFirst('Exception: ', '');
      });
    } finally {
      _loadingTrends.remove(key);
    }
  }

  Future<void> _loadDiscounts() async {
    if (!lighthouseLedgerShowsDiscountUi) return;
    if (_discountsLoading) return;
    final requestedPeriod = _period;
    final requestedOffset = _periodOffset;
    final requestedStart = _customStart;
    final requestedEnd = _customEnd;
    _discountsLoading = true;
    try {
      final data = await _service.fetchDiscounts(
        period: requestedPeriod,
        offset: requestedOffset,
        startDate: requestedStart,
        endDate: requestedEnd,
      );
      final discounts = lighthouseDiscountResolveForDisplay(
        Map<String, dynamic>.from(data['discounts'] as Map? ?? const {}),
        allowFixture: kDebugMode,
      );
      if (!mounted ||
          requestedPeriod != _period ||
          requestedOffset != _periodOffset ||
          requestedStart != _customStart ||
          requestedEnd != _customEnd) {
        return;
      }
      setState(() {
        _discountsByName = discounts;
        final base = _bundle ?? LighthouseDataBundle.empty();
        _bundle = base.withDiscounts(discounts);
        _rowsCacheKey = '';
        _rowsCache = null;
      });
    } catch (_) {
      if (!mounted ||
          requestedPeriod != _period ||
          requestedOffset != _periodOffset ||
          requestedStart != _customStart ||
          requestedEnd != _customEnd) {
        return;
      }
      final discounts = lighthouseDiscountResolveForDisplay(
        const {},
        allowFixture: kDebugMode,
      );
      if (discounts.isEmpty) return;
      setState(() {
        _discountsByName = discounts;
        final base = _bundle ?? LighthouseDataBundle.empty();
        _bundle = base.withDiscounts(discounts);
        _rowsCacheKey = '';
        _rowsCache = null;
      });
    } finally {
      _discountsLoading = false;
    }
  }

  /// 资金池缓存按账号 + 环境分开（受限账号看到的范围不同，不能串）。
  String get _fundPoolCacheKey => LighthouseFundPoolCache.keyFor(
    apiBase: widget.session.apiBase,
    userId: widget.session.userId,
  );

  /// 把一份资金池数据装进页面状态（调用方负责 setState）。
  void _setFundPoolData(Map<String, dynamic> data) {
    final snapshot = LighthouseFundPoolSnapshot.parse(data);
    // 省 key 口径（内蒙古自治区 → 内蒙古）；老后端没有 provinces 时退回旧解析。
    final byProvince = snapshot.isEmpty
        ? lighthouseParseFundPoolByProvince(data['byProvince'])
        : snapshot.amountsByProvinceKey();
    _fundPoolSnapshot = snapshot;
    _fundPoolByProvince = byProvince;
    // 「全部」视图的省级行要挂总资产、按总资产排序，列表得重算。
    _rowsCacheKey = '';
    _rowsCache = null;
  }

  /// 内存里有就同步放回去（首帧就有数）。调用方负责 setState。
  bool _restoreFundPoolFromMemory() {
    if (_hidesSensitiveFinance) return false;
    if (widget.sharedCard != null) return false;
    final cached = LighthouseFundPoolCache.memory(_fundPoolCacheKey);
    if (cached == null) return false;
    _setFundPoolData(cached);
    return true;
  }

  /// 资金池（2026-10-26 起带缓存）：先出缓存那份 —— 内存（同一次打开 App）
  /// 或落盘（当天再开 App）—— 再按新鲜度决定要不要去后端：10 分钟内拉过就不拉
  /// （后端自己也缓存 10 分钟，拉了也是同一份）；手动刷新会先把缓存标旧。
  Future<void> _loadFundPool() async {
    if (_hidesSensitiveFinance) return;
    if (_fundPoolLoading) return;
    _fundPoolLoading = true;
    final key = _fundPoolCacheKey;
    try {
      if (_fundPoolSnapshot.isEmpty) {
        final cached =
            LighthouseFundPoolCache.memory(key) ??
            await LighthouseFundPoolCache.disk(key);
        if (cached != null && mounted) {
          setState(() => _setFundPoolData(cached));
        }
      }
      if (!_fundPoolSnapshot.isEmpty && LighthouseFundPoolCache.isFresh(key)) {
        return;
      }
      // 资金池是最新快照（昨天，资管主体接口不收今天），不跟随灯塔的业务周期/日期筛选。
      final data = await _service.fetchFundPool();
      unawaited(LighthouseFundPoolCache.put(key, data));
      if (!mounted) return;
      setState(() => _setFundPoolData(data));
    } catch (_) {
      // Fund-pool is supplemental; keep "—" when unavailable (e.g. IP whitelist).
    } finally {
      _fundPoolLoading = false;
    }
  }

  /// 当月 / 当日利润 —— offset 0 + period day|month 就是「此刻这一天 / 这一月」，
  /// 不用自己拼日期，也不受页面上选的周期影响。
  ///
  /// 供给列表是按「标签二 + 供给分类」分行的，一个省份会有多行，所以按省份加总。
  Future<void> _loadFundPoolProfit() async {
    if (_hidesSensitiveFinance) return;
    if (_fundPoolProfitLoading) return;
    _fundPoolProfitLoading = true;
    try {
      final results = await Future.wait([
        _service.fetchDimension(tab: 'supply', period: 'month', offset: 0),
        _service.fetchDimension(tab: 'supply', period: 'day', offset: 0),
      ]);
      Map<String, double> sumByProvince(Map<String, dynamic> data) {
        final out = <String, double>{};
        for (final raw in (data['rows'] as List? ?? const [])) {
          if (raw is! Map) continue;
          final name = raw['name']?.toString().trim() ?? '';
          if (name.isEmpty) continue;
          final profit = (raw['profit'] as num?)?.toDouble();
          if (profit == null) continue;
          out[name] = (out[name] ?? 0) + profit;
        }
        return out;
      }

      final month = sumByProvince(results[0]);
      final day = sumByProvince(results[1]);
      if (!mounted) return;
      setState(() {
        _fundPoolProfitMonth = month;
        _fundPoolProfitDay = day;
      });
    } catch (_) {
      // 和资金池一样是补充数据：取不到就留「—」，不打断主流程。
    } finally {
      _fundPoolProfitLoading = false;
    }
  }

  String get _detailPeriodCacheKey => lighthouseDetailPeriodCacheKey(
    period: _period,
    periodOffset: _periodOffset,
    customStart: _customStart,
    customEnd: _customEnd,
  );

  Future<void> _loadDetail(String type, String key) async {
    if (widget.sharedCard != null) return;
    final detailKey = '$type:$key';
    final loadPeriodKey = _detailPeriodCacheKey;
    final requestKey = '$detailKey|$loadPeriodKey';
    final requestedPeriod = _period;
    final requestedOffset = _periodOffset;
    final requestedStart = _customStart;
    final requestedEnd = _customEnd;
    // 同一实体、同一周期已经水合过，返回后再次进入直接使用内存详情。
    if (_detailLoadedFor[detailKey] == loadPeriodKey &&
        _detailEntityMap(type, key) != null) {
      return;
    }
    if (_loadingDetails.contains(requestKey)) return;
    _loadingDetails.add(requestKey);
    // 记录本次拉取用的 period+offset+range —— _buildDetailView 会用它做过期检测
    try {
      final data = await _service.fetchDetail(
        tab: type,
        key: key,
        period: requestedPeriod,
        offset: requestedOffset,
        startDate: requestedStart,
        endDate: requestedEnd,
      );
      final detail = Map<String, dynamic>.from(
        data['detail'] as Map? ?? const {},
      );
      if (!mounted || loadPeriodKey != _detailPeriodCacheKey) return;
      if (detail.isEmpty) {
        setState(() => _detailErrors[requestKey] = '暂无详情数据');
        return;
      }
      detail['_deltaAvailable'] = data['deltaAvailable'] != false;
      setState(() {
        final base = _bundle ?? LighthouseDataBundle.empty();
        _bundle = base.withDetail(type, key, detail);
        _detailErrors.remove(requestKey);
        _detailLoadedFor[detailKey] = loadPeriodKey;
      });
    } catch (e) {
      if (mounted && loadPeriodKey == _detailPeriodCacheKey) {
        setState(
          () => _detailErrors[requestKey] = e.toString().replaceFirst(
            'Exception: ',
            '',
          ),
        );
      }
    } finally {
      _loadingDetails.remove(requestKey);
    }
  }

  /// 手动刷新 — 点击顶部「数据已同步」胶囊触发，重新拉取概览 + 立方体。
  /// 不清空当前页面（保留视图）。下拉刷新、顶部刷新钮和同步落款都走这里，
  /// 并复用切换日 / 周 / 月 / 季 / 年时的「旧内容压淡 + 期间条下进度线」。
  Future<void> _refresh() async {
    if (_refreshing || _loading) return;
    _pixelRefreshPending = true;
    // 手动刷新：资金池缓存标旧，这一轮一定去后端拿最新的（旧的先留着显示）。
    LighthouseFundPoolCache.markStale(_fundPoolCacheKey);
    setState(() {
      _refreshing = true;
      _loading = true;
      _loadError = null;
      _rowsCacheKey = '';
      _rowsCache = null;
      _cubeCacheKey = '';
      _cubeData = null;
      _cubeError = false;
      _biWindowGen++;
      _biWindowRows.clear();
      _biWindowLoading.clear();
      _paceDailyKey = null;
      _paceDaily = null;
      _paceModelCache.clear();
    });
    await _load();
    if (_heroKpiPage == 1) _ensureBillOutstanding(force: true);
    // 预警跟着「下拉刷新 / 点同步印章」重查一次，与 overview 并行。
    unawaited(_loadDelayNotice());
    if (_tab == 'analysis') await _loadAnalysisCube();
    if (mounted) setState(() => _refreshing = false);
  }

  Future<void> _loadAnalysisCube() async {
    final key =
        '$_period|$_periodOffset|${_customStart?.toIso8601String() ?? ""}|${_customEnd?.toIso8601String() ?? ""}';
    if (_cubeLoading) return;
    if (_cubeCacheKey == key && _cubeData != null) return;

    setState(() => _cubeLoading = true);
    try {
      final data = await _service.fetchAnalysisCube(
        period: _period,
        offset: _periodOffset,
        startDate: _customStart,
        endDate: _customEnd,
      );
      if (!mounted) return;
      setState(() {
        _cubeData = _parseCubeData(data);
        _cubeCacheKey = key;
        _cubeLoading = false;
        _cubeError = false;
      });
    } catch (_) {
      if (mounted) {
        setState(() {
          _cubeData = null;
          _cubeCacheKey = key;
          _cubeLoading = false;
          _cubeError = true;
        });
      }
    }
  }

  List<_DiscountRow> _discountRowsFromBundle() {
    // 优先直接吃 /discounts map：日维度供给可能没有中石油行，挂载会失败。
    final fromApi = lighthouseDiscountRowsFromMap(_discountsByName);
    if (fromApi.isNotEmpty) {
      final result = <_DiscountRow>[];
      for (final raw in fromApi) {
        final parsed = _DiscountRow.fromApi(
          raw,
          raw['province']?.toString() ?? '',
        );
        if (parsed != null) result.add(parsed);
      }
      return result;
    }
    final rows = _bundle?.rowsOf('supply') ?? const [];
    final result = <_DiscountRow>[];
    for (final r in rows) {
      final raw = r['discount'];
      if (raw is Map) {
        final parsed = _DiscountRow.fromApi(
          Map<String, dynamic>.from(raw),
          r['name']?.toString() ?? '',
        );
        if (parsed != null) result.add(parsed);
      }
    }
    return result;
  }

  _CubeData _parseCubeData(Map<String, dynamic> data) {
    List<({String name, String group, double profit})> parseDim(String key) {
      final raw = data[key] as List? ?? const [];
      return raw
          .whereType<Map>()
          .map(
            (r) => (
              name: r['name']?.toString() ?? '',
              group: r['group']?.toString() ?? '',
              profit: (r['profit'] as num?)?.toDouble() ?? 0,
            ),
          )
          .toList();
    }

    final products = parseDim('products');
    final supplies = parseDim('supplies');
    final channels = parseDim('channels');

    int dimIndex(
      List<({String name, String group, double profit})> dims,
      String name,
      int fallback,
    ) {
      for (var i = 0; i < dims.length; i++) {
        if (dims[i].name == name) return i;
      }
      return fallback.clamp(0, dims.isEmpty ? 0 : dims.length - 1);
    }

    final lit = <_CubePoint>[];
    for (final item in (data['lit'] as List? ?? const []).whereType<Map>()) {
      final productName = item['x']?.toString() ?? '';
      final supplyName = item['y']?.toString() ?? '';
      final channelName = item['z']?.toString() ?? '';
      final productGroup = item['x_group']?.toString() ?? '';
      // 优先用后端 owner（接通后） — 当前 mock：按产品组(业务线)派生负责人
      final ownerName = item['owner']?.toString().isNotEmpty == true
          ? item['owner'].toString()
          : _deriveCubeOwner(productGroup, supplyName);
      lit.add(
        _CubePoint(
          xi: dimIndex(
            products,
            productName,
            (item['xi'] as num?)?.toInt() ?? 0,
          ),
          yi: dimIndex(
            supplies,
            supplyName,
            (item['yi'] as num?)?.toInt() ?? 0,
          ),
          zi: dimIndex(
            channels,
            channelName,
            (item['zi'] as num?)?.toInt() ?? 0,
          ),
          x: productName,
          y: supplyName,
          z: channelName,
          value: (item['value'] as num?)?.toDouble() ?? 0,
          productGroup: item['x_group']?.toString() ?? '',
          supplyGroup: item['y_group']?.toString() ?? '',
          channelGroup: item['z_group']?.toString() ?? '',
          supplyHun: item['supply_hun']?.toString() ?? 'none',
          channelHun: item['channel_hun']?.toString() ?? 'none',
          owner: ownerName,
        ),
      );
    }

    final stats = data['stats'] as Map? ?? const {};
    return _CubeData(
      products: products,
      supplies: supplies,
      channels: channels,
      lit: lit,
      litCount: (stats['lit_count'] as num?)?.toInt(),
      totalPossible: (stats['total_possible'] as num?)?.toInt(),
      coveragePct: (stats['coverage_pct'] as num?)?.toDouble(),
    );
  }

  /// 返回中国时间 (UTC+8)，不依赖设备本地时区。
  /// 返回的 DateTime 是 isUtc=true 的"伪 CST"对象，hour/minute/day/weekday 都是
  /// 北京时间的值，直接读用即可（不要再 .toLocal()）。
  DateTime _nowCST() => (widget.sharedCard?.capturedAt ?? DateTime.now())
      .toUtc()
      .add(const Duration(hours: 8));

  /// 当前周期还没走完（本周/本月/本季截至今天；日/年的当期也禁止用走势首末点当环比）。
  bool get _periodInProgress {
    if (_isCustomRange || _periodOffset != 0) return false;
    return lighthouseResolveAlignedPeriod(
      period: _period,
      now: _nowCST(),
    ).inProgress;
  }

  /// 当前视图是不是「点月 + 当前月」—— 月化预测唯一适用的口径。
  /// 会议明确：点日 / 点周 / 点季 / 点年都不预测；自定义区间也不预测。
  bool get _isCurrentMonthView =>
      _period == 'month' && _periodOffset == 0 && !_isCustomRange;

  /// 月化规模预测 —— 预测月末规模 = 本月已发生 ÷ 已过天数 × 当月天数。
  ///
  /// [actual] 传「图上实线末端那个值」而不是别的口径值 —— 虚线是从那个点
  /// 往上画的，两者必须同源，否则虚线方向会跟直觉相反。
  /// 不满足口径（非当前月 / 比率指标 / 无发生额）时返回 null，调用方不画虚线。
  // ── 月末预测 v4 · 动态日模型 ────────────────────────────────────────
  //   只给主 Hero：点月 + 当前月时拉近 ~8 个月的日数据（hero-history 日粒度，
  //   每页 90 天，拉 3 页），交给 lighthouse_forecast_model.dart 的纯函数。
  //   数据没到 / 拉失败时一律回退到线性外推，不影响原有展示。
  Map<String, Map<DateTime, double>>? _paceDaily;

  /// 年末预测用的月度合计：指标 → { 月初 → 全月 }（只存本月以前的整月）。
  Map<String, Map<DateTime, double>>? _paceMonthly;
  String? _paceDailyKey;
  String? _paceDailyLoadingKey;
  final Map<String, LighthousePaceForecast?> _paceModelCache = {};

  String get _paceDailyReqKey {
    final t = _nowCST();
    return 'v4|$_tab|$_groupFilter|${t.year}-${t.month}-${t.day}';
  }

  static const _kPaceDailyMetrics = <String>[
    'verifiedSales',
    'sales',
    'revenue',
    'totalCost',
    'profit',
  ];

  void _ensurePaceDaily() {
    if (widget.sharedCard != null) return;
    if (!_isCurrentMonthView) return;
    final key = _paceDailyReqKey;
    if (_paceDailyKey == key || _paceDailyLoadingKey == key) return;
    _paceDailyLoadingKey = key;
    Future.microtask(() => _loadPaceDaily(key));
  }

  Future<void> _loadPaceDaily(String key) async {
    if (widget.sharedCard != null) return;
    final t = _nowCST();
    final requestTab = _tab;
    final requestGroup = _groupFilter;
    String two(int v) => v.toString().padLeft(2, '0');
    var before = '${t.year}-${two(t.month)}-${two(t.day)}';
    final out = <String, Map<DateTime, double>>{
      for (final k in _kPaceDailyMetrics) k: <DateTime, double>{},
    };
    try {
      for (var page = 0; page < 3; page++) {
        final data = await _service.fetchHeroHistory(
          before: before,
          period: 'day',
          tab: requestTab,
          group: requestGroup,
          count: 90,
        );
        final keys =
            (data['keys'] as List?)?.map((e) => '$e').toList() ??
            const <String>[];
        if (keys.isEmpty) break;
        final series = data['series'] is Map
            ? Map<String, dynamic>.from(data['series'] as Map)
            : const <String, dynamic>{};
        final days = [for (final k in keys) DateTime.tryParse(k)];
        for (final m in _kPaceDailyMetrics) {
          final raw = series['${m}Series'];
          if (raw is! List) continue;
          for (var i = 0; i < days.length && i < raw.length; i++) {
            final day = days[i];
            final v = raw[i];
            if (day == null || v is! num) continue;
            out[m]![DateTime(day.year, day.month, day.day)] = v.toDouble();
          }
        }
        if (data['hasMore'] != true) break;
        before = keys.first;
      }
    } catch (_) {
      // 不发布半截历史：所有页成功后才交给模型，否则保持线性对照。
      for (final values in out.values) {
        values.clear();
      }
    }
    // 年末预测要「今年 1 月至上月」和「去年全年」：日数据只有 ~9 个月，
    // 补一页月粒度。失败只是没有年末预测，月末预测照旧。
    final monthly = <String, Map<DateTime, double>>{
      for (final k in _kPaceDailyMetrics) k: <DateTime, double>{},
    };
    final thisMonth = DateTime(t.year, t.month, 1);
    DateTime? monthOf(String k) {
      final m = RegExp(r'^(\d{4})\D?(\d{1,2})').firstMatch(k.trim());
      if (m == null) return null;
      final mo = int.parse(m[2]!);
      if (mo < 1 || mo > 12) return null;
      return DateTime(int.parse(m[1]!), mo, 1);
    }

    void absorb(List<String> keys, Map<String, dynamic> series) {
      final months = [for (final k in keys) monthOf(k)];
      for (final m in _kPaceDailyMetrics) {
        final raw = series['${m}Series'];
        if (raw is! List) continue;
        for (var i = 0; i < months.length && i < raw.length; i++) {
          final mo = months[i];
          final v = raw[i];
          if (mo == null || v is! num || !mo.isBefore(thisMonth)) continue;
          monthly[m]![mo] = v.toDouble();
        }
      }
    }

    try {
      final baseKeys = _heroBaseSeriesKeys;
      if (baseKeys.isNotEmpty && _period == 'month') {
        final data = await _service.fetchHeroHistory(
          before: baseKeys.first,
          period: 'month',
          tab: requestTab,
          group: requestGroup,
          count: 24,
        );
        absorb(
          (data['keys'] as List?)?.map((e) => '$e').toList() ??
              const <String>[],
          data['series'] is Map
              ? Map<String, dynamic>.from(data['series'] as Map)
              : const <String, dynamic>{},
        );
        // 视窗里那几个月（04–09 月）在当前这一页的 hero 序列里。
        absorb(baseKeys, _bundle?.metrics ?? const <String, dynamic>{});
      }
    } catch (_) {
      for (final values in monthly.values) {
        values.clear();
      }
    }
    if (!mounted || _paceDailyReqKey != key) {
      if (_paceDailyLoadingKey == key) _paceDailyLoadingKey = null;
      return;
    }
    setState(() {
      _paceDaily = {
        for (final e in out.entries)
          if (e.value.isNotEmpty) e.key: e.value,
      };
      _paceMonthly = {
        for (final e in monthly.entries)
          if (e.value.isNotEmpty) e.key: e.value,
      };
      _paceDailyKey = key;
      _paceDailyLoadingKey = null;
      _paceModelCache.clear();
    });
  }

  /// 月末结构预测（多层有序 logit）：给某个维度（product / supply / channel）
  /// 拉 5 段区间的列表（本月 1 日至昨天 / 上月同期 / 上月全月 / 近 7 天 /
  /// 前 7 天），按「名称::分组」拼特征后逐个实体打分。
  Future<LighthouseOrdinalBundle?> _loadOrdinal(String tab) async {
    final model = await LighthouseProductOrdinalModel.load();
    if (model == null) return null;
    final t = _nowCST();
    final y1 = DateTime(t.year, t.month, t.day - 1); // T+1：截至昨天
    if (y1.month != t.month) return null; // 1 号还没有本月数据
    final day = y1.day;
    final dim = DateTime(t.year, t.month + 1, 0).day;
    final pmStart = DateTime(t.year, t.month - 1, 1);
    final pmEnd = DateTime(t.year, t.month, 0);
    final cp = math.max(1, (day * pmEnd.day / dim).round());
    final ranges = <String, (DateTime, DateTime)>{
      'cur': (DateTime(t.year, t.month, 1), y1),
      'prevSameDay': (pmStart, DateTime(pmStart.year, pmStart.month, cp)),
      'prevTotal': (pmStart, pmEnd),
      'last7': (DateTime(y1.year, y1.month, y1.day - 6), y1),
      'prev7': (
        DateTime(y1.year, y1.month, y1.day - 13),
        DateTime(y1.year, y1.month, y1.day - 7),
      ),
    };
    try {
      final keys = ranges.keys.toList();
      final pages = await Future.wait([
        for (final k in keys)
          _service.fetchDimension(
            tab: tab,
            startDate: ranges[k]!.$1,
            endDate: ranges[k]!.$2,
          ),
      ]);
      final rows = <String, Map<String, Map<String, dynamic>>>{};
      for (var i = 0; i < keys.length; i++) {
        final byKey = <String, Map<String, dynamic>>{};
        for (final r in (pages[i]['rows'] as List? ?? const [])) {
          if (r is! Map) continue;
          final m = Map<String, dynamic>.from(r);
          var name = '${m['name'] ?? ''}'.trim();
          final cut = name.indexOf('::');
          if (cut >= 0) name = name.substring(0, cut);
          if (name.isEmpty) continue;
          final group = '${m['group'] ?? ''}'.trim();
          final key = '$name::${group.isEmpty ? '(未分类)' : group}';
          // 同名同组的多行（极少）合并相加。
          final prev = byKey[key];
          if (prev == null) {
            byKey[key] = m;
          } else {
            for (final f in lighthouseOrdinalRowField.values) {
              final a = prev[f];
              final b = m[f];
              prev[f] = (a is num ? a : 0) + (b is num ? b : 0);
            }
          }
        }
        rows[keys[i]] = byKey;
      }
      return lighthouseScoreEntities(
        model: model,
        dim: tab,
        rows: rows,
        day: day,
        daysInMonth: dim,
        month: DateTime(t.year, t.month, 1),
      );
    } catch (_) {
      return null;
    }
  }

  /// 同一天内每个维度只拉一次（BI 里来回切视角不重复打 5 次接口）。
  final Map<String, Future<LighthouseOrdinalBundle?>> _ordinalCache = {};

  Future<LighthouseOrdinalBundle?> _loadOrdinalCached(String tab) {
    final t = _nowCST();
    final key = '$tab|${t.year}-${t.month}-${t.day}';
    return _ordinalCache.putIfAbsent(key, () {
      final f = _loadOrdinal(tab);
      // 失败的不缓存，下次再试。
      unawaited(
        f.then((v) {
          if (v == null) _ordinalCache.remove(key);
        }),
      );
      return f;
    });
  }

