  /// 打开「月末预测 · 量化报告」底部弹层。
  void _openForecastReport(String metricKey, String label) {
    final daily = _paceDailyKey == _paceDailyReqKey
        ? (_paceDaily?[metricKey])
        : null;
    final report = daily == null
        ? null
        : lighthouseForecastReport(
            daily: daily,
            today: _nowCST(),
            signed: metricKey == 'profit',
            monthly: _paceMonthly?[metricKey] ?? const <DateTime, double>{},
          );
    if (report == null) {
      ScaffoldMessenger.maybeOf(context)?.showSnackBar(
        SnackBar(
          content: Text(
            daily == null ? '日数据尚未就绪，稍后再试' : '历史不足或日数据有缺口，暂不生成模型报告',
          ),
        ),
      );
      return;
    }
    LighthouseFeedback.instance.play(LighthouseFeedbackKind.select);
    final h = MediaQuery.sizeOf(context).height;
    showModalBottomSheet<void>(
      context: context,
      backgroundColor: DunesColors.resolve(
        context,
        LhColors.paper,
        role: DunesColorRole.surface,
      ),
      isScrollControlled: true,
      shape: const RoundedRectangleBorder(
        borderRadius: BorderRadius.vertical(top: Radius.circular(12)),
      ),
      builder: (ctx) => SizedBox(
        height: h * 0.92,
        child: LighthouseForecastReportSheet(
          report: report,
          metricLabel: label,
          profit: metricKey == 'profit',
          ordinalLoader: _loadOrdinalCached,
          productMetric: switch (metricKey) {
            'verifiedSales' => 'verify',
            'sales' => 'sales',
            'revenue' => 'revenue',
            _ => 'profit',
          },
        ),
      ),
    );
  }

  /// 主 Hero 的月末预测：有日数据就走动态日模型与时间回测，否则退回线性对照。
  /// [linearFallback] 为 false 时（利润）没有模型结果就返回 null，
  /// 由图自己按天数线性外推（利润可能为负，线性函数会拒绝负值）。
  LighthousePaceForecast? _heroPaceForecast(
    String metricKey,
    double shownActual, {
    bool linearFallback = true,
  }) {
    final linear = linearFallback
        ? _monthPaceForecast(metricKey, shownActual)
        : null;
    if (!_isCurrentMonthView || !lighthouseMetricSupportsPace(metricKey)) {
      return linear;
    }
    _ensurePaceDaily();
    // 模型的日序列还在路上：先不出预测，别拿线性外推顶上（看起来像旧算法）。
    if (_paceDailyKey != _paceDailyReqKey) return null;
    final daily = _paceDaily?[metricKey];
    if (daily == null) return linear;
    final cacheKey = 'v5|$metricKey|$shownActual';
    if (_paceModelCache.containsKey(cacheKey)) {
      return _paceModelCache[cacheKey] ?? linear;
    }
    // v5 · 同一个日模型顺着走到 12 月 31 日，顺带给出之后各月和全年。
    final today = _nowCST();
    final mf = lighthouseModelForecast(
      daily: daily,
      today: today,
      signed: metricKey == 'profit',
      toYearEnd: true,
    );
    final yearEnd = mf == null
        ? null
        : lighthouseYearEndForecast(
            month: mf,
            daily: daily,
            today: today,
            monthly: _paceMonthly?[metricKey] ?? const <DateTime, double>{},
          );
    final res = mf == null
        ? null
        : lighthousePaceFromModel(
            mf,
            shownActual: shownActual,
            yearEnd: yearEnd,
          );
    _paceModelCache[cacheKey] = res;
    return res ?? linear;
  }

  /// 当月「已过天数 / 当月天数」—— 与 [_monthPaceForecast] 同一口径，
  /// 给利润盈亏柱外推月末用（利润可能为负，不能靠规模预测是否非空来判断）。
  ({int elapsed, int total})? get _monthPaceDays {
    if (!_isCurrentMonthView) return null;
    final now = _nowCST();
    final total = lighthouseDaysInMonth(now.year, now.month);
    if (now.day <= 1) return null;
    return (elapsed: now.day - 1, total: total);
  }

  LighthousePaceForecast? _monthPaceForecast(String metricKey, double actual) {
    if (!_isCurrentMonthView) return null;
    if (!lighthouseMetricSupportsPace(metricKey)) return null;
    final now = _nowCST();
    if (now.day <= 1) return null;
    return lighthouseMonthPaceForecast(
      actual: actual,
      now: DateTime(now.year, now.month, now.day - 1),
    );
  }

  // ── FE-1: Greeting / AppBar 动态文案 ───────────────────────────────────────
  String _formatDateLabel() {
    // 与列表/选区间同一 period 实例，避免墙钟「今天」与数据日错位。
    if (_isCustomRange && _customStart != null && _customEnd != null) {
      return '${_two(_customStart!.month)}.${_two(_customStart!.day)}'
          '–${_two(_customEnd!.month)}.${_two(_customEnd!.day)}';
    }
    if (_period == 'day') {
      const weekdays = ['一', '二', '三', '四', '五', '六', '日'];
      final a = _periodAnchor(_period, _periodOffset);
      final w = weekdays[a.weekday - 1];
      return '星期$w · ${_two(a.month)}.${_two(a.day)}';
    }
    return _periodInstanceDetail(_period, _periodOffset);
  }

  String _syncedAtLabel() {
    return lighthouseSyncedAtStamp(_lastSyncedAt ?? _nowCST());
  }

  /// header 内联版本：顶栏已不再单独放日期，胶囊里带上当天日期 + 时分。
  String _syncedAtLabelShort() {
    return lighthouseSyncedAtStamp(_lastSyncedAt ?? _nowCST());
  }

  /// 顶栏胶囊用的紧凑戳：当天只给时刻，跨天才补月日。
  String _syncedAtLabelCompact() {
    final now = _nowCST();
    return lighthouseSyncedAtCompact(_lastSyncedAt ?? now, now: now);
  }

  Set<String> _liveMetrics(String tab) {
    final keys = _uiMetricDefs(
      tab,
    ).where((d) => d['listDefault'] == true).map((d) => d['key'] as String);
    final set = keys.toSet();
    return set.isEmpty ? _uiDefaultMetrics(tab).toSet() : set;
  }

  double _targetRoiPct() {
    final metrics = _bundle?.metrics ?? const <String, dynamic>{};
    final decision = metrics['projectDecision'];
    if (decision is Map) {
      final v = (decision['targetROI'] as num?)?.toDouble();
      if (v != null && v > 0) return v;
    }
    final expected = (metrics['rateExpected'] as num?)?.toDouble();
    if (expected != null && expected > 0) return expected;
    return 1.1;
  }

  /// 金额按「万」展示时会被收成 0.00 的阈值（|n| &lt; 0.005 万 = 50 元）。
  /// 这类核销作 ROI 分母会把效率吹成几千%，失去经营意义。
  static const double _kRoiAnchorMinYuan = 50;

  /// 成本合计 = 直读后端 totalCost（= SUM(total_cost)）。
  double _rowCostTotal(Map<String, dynamic> r) =>
      (r['totalCost'] as num?)?.toDouble() ??
      (r['costTotal'] as num?)?.toDouble() ??
      0;

  /// ROI 的分母 = 成本合计（total_cost）。
  double _roiAnchor(Map<String, dynamic> r) {
    final total = _rowCostTotal(r);
    return lighthouseValidRateBase(total, minimumBase: _kRoiAnchorMinYuan);
  }

  /// ROI = 利润 ÷ 成本合计
  double _rowRoiPct(Map<String, dynamic> r) {
    final anchor = _roiAnchor(r);
    if (anchor == 0) return 0;
    final profit = (r['profit'] as num?)?.toDouble() ?? 0;
    return profit / anchor * 100;
  }

  /// 毛利率分母：运营商用销售额，其余用核销额。
  String? get _grossMarginContextGroup {
    if (_detailKey != null) {
      return _currentDetailSummaryForTrend()?['group']?.toString();
    }
    if (_groupFilter != '全部' && _groupFilter.isNotEmpty) return _groupFilter;
    return null;
  }

  LighthouseHeroFormula? _heroFormula(String key) =>
      lighthouseHeroFormulaForKey(
        key,
        group: _grossMarginContextGroup,
        product: _grossMarginContextProduct,
        basis: _grossMarginContextBasis,
      );

  LighthouseHeroFormula? _rowHeroFormula(
    Map<String, dynamic> row,
    String key,
  ) => lighthouseHeroFormulaForKey(
    key,
    group: row['group']?.toString(),
    product: _rowMarginProduct(row),
    basis: row['grossMarginBasis']?.toString(),
  );

  String? get _grossMarginContextProduct {
    final shared = widget.sharedCard?.row['marginProduct']?.toString();
    if (shared != null) return shared;
    if (_detailType != 'product') return null;
    // A product subdivision retains the parent product's existing denominator.
    final subdivision = lighthouseParseProductL3Key(_detailKey ?? '');
    return subdivision?.l2 ?? _detailKey?.split('::').first;
  }

  String? get _grossMarginContextBasis {
    if (_detailKey != null)
      return _currentDetailSummaryForTrend()?['grossMarginBasis']?.toString();
    final rows = _currentRows;
    if (rows.isNotEmpty && rows.every((r) => _rowMarginBasis(r) == 'gmv'))
      return 'gmv';
    if (_heroSummaryMatchesGroup && !_heroFilterActive)
      return _bundle?.metrics['grossMarginBasis']?.toString();
    return null;
  }

  String? _rowMarginProduct(Map<String, dynamic> row) =>
      row['marginProduct']?.toString() ??
      row['parentProduct']?.toString() ??
      (lighthouseProductUsesGmv(row['name']?.toString())
          ? row['name']?.toString()
          : _grossMarginContextProduct);

  String _rowMarginBasis(Map<String, dynamic> row) =>
      lighthouseGrossMarginDenominatorKey(
        product: _rowMarginProduct(row),
        group: row['group']?.toString(),
        basis: row['grossMarginBasis']?.toString(),
      );

  String _grossMarginFormula([Map<String, dynamic>? row]) =>
      (row == null
              ? _heroFormula('grossMargin')
              : _rowHeroFormula(row, 'grossMargin'))
          ?.expression ??
      '利润 ÷ 核销额';

  double _salesOf(Map<String, dynamic> row) => _metricNum(row, 'sales') ?? 0.0;

  /// 毛利率的分母 = 核销额；运营商改用销售额。
  double _grossMarginBase(Map<String, dynamic> r) {
    return lighthouseGrossMarginBase(
      verifiedSales: _verifiedSalesOf(r),
      sales: _salesOf(r),
      gmv: _metricNum(r, 'gmv') ?? 0,
      product: _rowMarginProduct(r),
      basis: r['grossMarginBasis']?.toString(),
      group: r['group']?.toString(),
      minimumBase: _kRoiAnchorMinYuan,
    );
  }

  /// 毛利率 = 利润 ÷ 核销额；运营商 = 利润 ÷ 销售额
  double _rowGrossMarginPct(Map<String, dynamic> r) {
    final base = _grossMarginBase(r);
    if (base == 0) return 0;
    final profit = (r['profit'] as num?)?.toDouble() ?? 0;
    return profit / base * 100;
  }

  double _rowOperatingCost(Map<String, dynamic> r) {
    return (r['cost'] as num?)?.toDouble() ?? 0;
  }

  bool _rowMatchesAnomaly(Map<String, dynamic> r, String filter) {
    if (filter == '全部') return true;
    final profit = (r['profit'] as num?)?.toDouble() ?? 0;
    final revenue = (r['revenue'] as num?)?.toDouble() ?? 0;
    final spread = (r['spread'] as num?)?.toDouble();
    final anchor = _roiAnchor(r);
    final operatingCost = _rowOperatingCost(r);
    final tax = (r['tax'] as num?)?.toDouble() ?? 0;
    final totalCost = (r['totalCost'] as num?)?.toDouble() ?? 0;

    switch (filter) {
      case '亏损':
        return profit < 0;
      case 'ROI低于目标':
        return anchor > 0 && _rowRoiPct(r) < _targetRoiPct();
      case '成本异常':
        final operatingRate = anchor > 0 ? operatingCost / anchor * 100 : 0;
        final taxRate = revenue > 0 ? tax / revenue * 100 : 0;
        return (revenue > 0 && totalCost > revenue) ||
            operatingRate > 0.8 ||
            taxRate > 8;
      case '利差倒挂':
        return (spread != null && spread < 0) || revenue < 0;
      default:
        return true;
    }
  }

  List<Map<String, dynamic>> _rowsBeforeAnomalyFilter() {
    if (_bundle == null) return const [];
    var rows = _bundle!.rowsOf(_tab);
    if (_tab != 'netTa' && _groupFilter != '全部') {
      rows = rows.where((r) => r['group']?.toString() == _groupFilter).toList();
    }
    if (_hunFilter != '全部' && (_tab == 'supply' || _tab == 'channel')) {
      final match = _hunMatchFor(_hunFilter);
      rows = rows.where((r) => _hunOf(r).primary == match).toList();
    }
    if (_tab == 'supply' && _tradeTypeFilter != '全部') {
      rows = rows
          .where((row) => lighthouseProductTradeFlagOf(row) == _tradeTypeFilter)
          .toList();
    }
    if (_supplyProvinceViewActive) {
      // 标签二「全部」：账本行（省 × 供给分类 × 交易标识）按省合并成一行，
      // 挂上资管总资产。HUN / 交易类型筛的是账本，资产跟不过去，
      // 开了这两个筛选就只合并、不挂资产。
      return lighthouseSupplyProvinceRows(
        rows,
        _fundPoolSnapshot,
        attachAssets:
            !_hidesSensitiveFinance &&
            _supplyAssetScopeSupported &&
            _hunFilter == '全部' &&
            _tradeTypeFilter == '全部',
        assetCategory: _supplySelectedAssetCategory,
      );
    }
    return List<Map<String, dynamic>>.from(rows);
  }

  /// 标签二根层始终是省级视图；分类只改变省份范围和顶部资产走势。
  bool get _supplyProvinceViewActive =>
      _tab == 'supply' &&
      _detailKey == null &&
      widget.sharedCard == null &&
      !_inTopic;

  String? get _supplySelectedAssetCategory {
    if (_groupFilter.contains('中石化')) return lighthouseAssetCategoryPetro;
    if (_groupFilter.contains('中石油')) return lighthouseAssetCategoryOil;
    return null;
  }

  bool get _supplyAssetScopeSupported =>
      _groupFilter == '全部' || _supplySelectedAssetCategory != null;

  /// 标签二一级选了具体分类（中石油 / 中石化…）：资产不能按分类拆，隐藏。
  bool get _supplyAssetsHiddenByGroup => _inTopic;

  /// 当前真正生效的排序字段。总资产只在省级视图里有值，其余视图退回利润。
  String get _effectiveSortField =>
      _sortField == lighthouseTotalAssetsSortKey && !_supplyProvinceViewActive
      ? 'profit'
      : _sortField;

  // ══ 列表内查找 ════════════════════════════════════════════════════
  //
  //  一行 151pt，一屏只看得到四行 —— 30 个产品要找某一个就是一路翻。
  //  查找只过**列表**，不动 Hero：Hero 回答「这一段整体怎么样」，
  //  输入框回答「那一行在哪」，两件事不该互相改写。分类筛选才该改 Hero。
  bool _ledgerSearchOpen = false;
  String _ledgerSearch = '';

  /// 这条查询是在哪个维度输入的。换了维度就不再沿用 —— 「出行」在产品维
  /// 有意义，切到供给维只会得到一个空列表，而用户根本没意识到还开着筛。
  String _ledgerSearchTab = '';
  final TextEditingController _ledgerSearchCtl = TextEditingController();
  final FocusNode _ledgerSearchFocus = FocusNode();

  bool get _ledgerSearchActive =>
      _detailKey == null &&
      _ledgerSearchTab == _tab &&
      _ledgerSearch.trim().isNotEmpty;

  List<Map<String, dynamic>> _ledgerSearchFiltered(
    List<Map<String, dynamic>> rows,
  ) {
    if (!_ledgerSearchActive) return rows;
    final q = _ledgerSearch.trim().toLowerCase();
    // 产品行连三级名一起找：搜「出行金」要能找到它所在的「会员套餐点播」，
    // 命中的三级在卡片下方自动展开（见 _buildLedgerRowGroup）。
    return rows.where((r) => lighthouseLedgerRowMatchesSearch(r, q)).toList();
  }

  String get _ledgerSearchHint {
    switch (_tab) {
      case 'supply':
        return '找省份 / 集团';
      case 'channel':
        return '找渠道 / 分类';
      case 'people':
        return '找姓名';
      default:
        return '找产品 / 分类';
    }
  }

  void _closeLedgerSearch() {
    _ledgerSearchCtl.clear();
    _ledgerSearchFocus.unfocus();
    setState(() {
      _ledgerSearch = '';
      _ledgerSearchOpen = false;
      _listLimit = _listPageSize;
    });
  }

  // Cached sorted/filtered rows — re-computed only when the source state changes.
  String _rowsCacheKey = '';
  List<Map<String, dynamic>>? _rowsCache;

  List<Map<String, dynamic>> get _currentRows {
    if (_bundle == null) return const [];
    final key =
        '$_period|$_tab|$_groupFilter|$_hunFilter|$_tradeTypeFilter|$_anomalyFilter|$_sortField|$_sortDesc|${identityHashCode(_fundPoolSnapshot)}';
    final cached = _rowsCache;
    if (cached != null && key == _rowsCacheKey) return cached;
    _listLimit = _listPageSize; // 筛选/排序/周期变化时重置分页
    _discountExpanded = false;
    // 切期间：已经滑出来的条数保留，列表不缩回第一页，视角不跳。
    final keptLimit = _listLimitKeptForReload;
    if (keptLimit != null) {
      if (keptLimit > _listLimit) _listLimit = keptLimit;
      if (!_loading && _staleRowsTab == null) _listLimitKeptForReload = null;
    }

    var rows = _rowsBeforeAnomalyFilter();
    if (_anomalyFilter != '全部' && _tab != 'netTa') {
      rows = rows.where((r) => _rowMatchesAnomaly(r, _anomalyFilter)).toList();
    }
    final result = List<Map<String, dynamic>>.from(rows);
    if (_tab != 'netTa') {
      final sortField = _effectiveSortField;
      result.sort((a, b) {
        if (sortField == lighthouseTotalAssetsSortKey) {
          // 资管没有这个省的快照：不当 0 插在正负之间，一律垫底。
          final ma = a[lighthouseTotalAssetsSortKey] is! num;
          final mb = b[lighthouseTotalAssetsSortKey] is! num;
          if (ma != mb) return ma ? 1 : -1;
        }
        // costTotal / rate / grossMargin 等须走派生读数
        final pa = _rowMetricValue(a, sortField);
        final pb = _rowMetricValue(b, sortField);
        return _sortDesc ? pb.compareTo(pa) : pa.compareTo(pb);
      });
    }
    if (_tab == 'netTa') {
      _listLimit = result.length;
    }
    _rowsCacheKey = key;
    _rowsCache = result;
    return result;
  }

  /// 当后端未返回 `label` 时，按当前日期动态生成，避免显示过期硬编码日期。
  String _periodLabelFor(String period) {
    final now = _nowCST();
    String two(int v) => v.toString().padLeft(2, '0');
    switch (period) {
      case 'day':
        return '今日 · ${now.year}.${two(now.month)}.${two(now.day)}';
      case 'week':
        final monday = now.subtract(Duration(days: now.weekday - 1));
        final sunday = monday.add(const Duration(days: 6));
        return '本周 · ${two(monday.month)}.${two(monday.day)} – ${two(sunday.month)}.${two(sunday.day)}';
      case 'month':
        return '本月 · ${now.year}.${two(now.month)}';
      case 'quarter':
        final q = ((now.month - 1) ~/ 3) + 1;
        return '本季 · ${now.year}.Q$q';
      case 'year':
        return '今年 · ${now.year}';
      default:
        return '';
    }
  }

  /// Hero 顶部聚合：完全读后端 `metrics`，缺字段用 0 / 动态日期占位（无写死业务兜底）。
  _PeriodInfo get _heroInfo {
    final m = _bundle?.metrics ?? const <String, dynamic>{};
    final dynamicLabel = _periodLabelFor(_period);

    final compose = <_ComposeItem>[];
    final rawCompose = m['compose'];
    if (rawCompose is List) {
      for (final c in rawCompose.whereType<Map>()) {
        final name = c['name']?.toString() ?? '';
        compose.add(
          _ComposeItem(
            name: name,
            pct: (c['pct'] as num?)?.toDouble() ?? 0,
            color: _composeColor(c['colorKey']?.toString() ?? '', name),
          ),
        );
      }
    }

    final deltaAvailable = m['deltaAvailable'] != false;
    final salesDir = deltaAvailable
        ? (m['salesDeltaDir']?.toString() ??
              m['deltaDir']?.toString() ??
              'flat')
        : 'flat';
    final salesPct =
        (m['salesDeltaPct'] as num?)?.toDouble() ??
        (m['deltaPct'] as num?)?.toDouble();

    return _PeriodInfo(
      label: m['label']?.toString() ?? dynamicLabel,
      short: m['short']?.toString() ?? (_kPeriodShort[_period] ?? ''),
      salesV: (m['salesV'] as num?)?.toDouble() ?? 0,
      salesU: m['salesU']?.toString() ?? '',
      deltaDir: salesDir == 'down' ? 'down' : 'up',
      deltaVal: salesPct?.abs() ?? 0,
      deltaVs: _periodVsLabel,
      hasDelta: deltaAvailable && salesDir != 'flat' && salesPct != null,
      profitV: (m['profitV'] as num?)?.toDouble() ?? 0,
      profitU: m['profitU']?.toString() ?? '',
      gmvV: (m['gmvV'] as num?)?.toDouble() ?? 0,
      gmvU: m['gmvU']?.toString() ?? '',
      rate: (m['rate'] as num?)?.toDouble() ?? 0,
      compose: compose,
    );
  }

  /// 后端 compose.colorKey → 颜色；未知时按 name 推断。
  Color _composeColor(String key, String name) {
    switch (key) {
      case 'cnpc':
        return DunesColors.resolve(context, LhColors.cnpc);
      case 'sinopec':
        return DunesColors.resolve(context, LhColors.sinopec);
      case 'private':
        return DunesColors.resolve(context, LhColors.private);
      case 'carrier':
        return DunesColors.resolve(context, LhColors.carrier);
      case 'pingan':
        return DunesColors.resolve(context, LhColors.pingan);
      case 'dict':
        return DunesColors.resolve(context, LhColors.dict);
      case 'multi':
        return DunesColors.resolve(context, LhColors.multi);
      case 'unk':
        return DunesColors.resolve(context, LhColors.unk);
    }
    return lhGroupColor(name);
  }

  bool get _mainFilterActive => _groupFilter != '全部';

  bool get _listFilterActive =>
      _mainFilterActive ||
      ((_tab == 'supply' || _tab == 'channel') && _hunFilter != '全部') ||
      (_tab == 'supply' && _tradeTypeFilter != '全部') ||
      _anomalyFilter != '全部';

  /// 主 Hero 用当前列表行汇总的场景：
  /// - L1 分类非「全部」：与列表同口径
  /// - HUN / 异常：后端 summary 不含这两层，只能前端聚
  /// 「全部」且无 HUN/异常时走后端共享 summary，三维 Hero 一致。
  bool get _heroFilterActive =>
      _mainFilterActive ||
      ((_tab == 'supply' || _tab == 'channel') && _hunFilter != '全部') ||
      (_tab == 'supply' && _tradeTypeFilter != '全部') ||
      _anomalyFilter != '全部';

  bool get _heroLocalOnlyFilterActive =>
      ((_tab == 'supply' || _tab == 'channel') && _hunFilter != '全部') ||
      (_tab == 'supply' && _tradeTypeFilter != '全部') ||
      _anomalyFilter != '全部';

  bool get _supplyTradeTypeFilterActive =>
      _tab == 'supply' && _tradeTypeFilter != '全部';

  /// summary 的 filterGroup / filterTab 是否已与当前 L1 对齐（金额 / 环比 / 走势）。
  ///
  /// 切到产品 / 供给 / 渠道后，上一档分类的 summary 不能再显示成「本日利润」。
  bool get _heroSummaryMatchesGroup {
    if (_tab == 'netTa') return true;
    return lighthouseHeroSummaryAppliesTo(
      tab: _tab,
      group: _groupFilter,
      filterTab: _bundle?.metrics['filterTab']?.toString(),
      filterGroup: _bundle?.metrics['filterGroup']?.toString(),
    );
  }

  void _rememberSharedHeroMetricsIfUnfiltered(
    String group,
    Map<String, dynamic>? metrics,
  ) {
    if (metrics == null || metrics.isEmpty) return;
    final g = group.trim().isEmpty ? '全部' : group.trim();
    if (g != '全部') return;
    _sharedHeroMetrics = lighthouseSharedHeroMetricsSnapshot(metrics);
  }

  /// 离开净TA / 切维时清掉净TA 专用展开态，避免产品页还在画净TA 单线或空白。
  void _clearNetTAHeroTransientState() {
    _netTaBalanceOpen = false;
    _netTaBalanceOpenCompany = null;
    final focus = (_expandedTrendKey ?? '').trim();
    if (focus.startsWith('netTa') || focus == 'inflow' || focus == 'outflow') {
      _expandedTrendKey = null;
      _heroTraceKey = null;
    }
  }

  void _restoreSharedHeroMetrics() {
    final shared = _sharedHeroMetrics;
    final base = _bundle;
    if (shared == null || base == null) return;
    final next = Map<String, dynamic>.from(shared);
    final ui = base.metrics['ui'];
    if (ui != null) next['ui'] = ui;
    lighthouseCarryNetTAMetrics(base.metrics, next);
    _bundle = base.copyWith(metrics: next);
  }

  double _heroAmountFrom({
    required Map<String, dynamic> metrics,
    required bool useRowAmounts,
    required bool metricsMatch,
    required List<String> keys,
    required double rowSum,
  }) {
    double? pick(Map<String, dynamic> m) {
      for (final key in keys) {
        final v = (m[key] as num?)?.toDouble();
        if (v != null) return v;
      }
      return null;
    }

    final shared = _sharedHeroMetrics;
    return lighthouseHeroMetricAmount(
      useRowAmounts: useRowAmounts,
      metricsMatch: metricsMatch,
      metricsValue: pick(metrics),
      sharedValue: shared == null ? null : pick(shared),
      rowSum: rowSum,
    );
  }

  /// Hero 上方 pills：展示当前 L1 分类 + HUN / 异常。
  List<({String label, String value, VoidCallback onClear})>
  _activeHeroFilters() {
    final list = <({String label, String value, VoidCallback onClear})>[];
    if (_groupFilter != '全部') {
      list.add((
        label: '分类',
        value: _groupFilter,
        onClear: () => _setGroupFilter('全部'),
      ));
    }
    if ((_tab == 'supply' || _tab == 'channel') && _hunFilter != '全部') {
      list.add((
        label: _uiFilterDef(_tab, 'hun')?['label'] as String? ?? 'U/N',
        value: _hunLabelFor(_hunFilter),
        onClear: () => setState(() => _hunFilter = '全部'),
      ));
    }
    if (_tab == 'supply' && _tradeTypeFilter != '全部') {
      list.add((
        label: '类型',
        value: _tradeTypeFilter,
        onClear: () => setState(() {
          _tradeTypeFilter = '全部';
          _rowsCacheKey = '';
          _rowsCache = null;
        }),
      ));
    }
    if (_anomalyFilter != '全部') {
      list.add((
        label: '异常',
        value: _anomalyFilter,
        onClear: () => setState(() => _anomalyFilter = '全部'),
      ));
    }
    return list;
  }

  // ── Dropdown helpers ──────────────────────────────────────────────────────
  // 浮层使用 per-button GlobalKey 锚定到具体按钮，配合屏幕边界避让 + 入场动画
  void _closeDropdown() {
    _ddEntry?.remove();
    _ddEntry = null;
    if (mounted) setState(() => _ddMode = _DdMode.none);
  }

  void _toggleDropdown(_DdMode mode) {
    if (_ddMode == mode) {
      _closeDropdown();
      return;
    }
    _ddEntry?.remove();
    _ddEntry = null;
    setState(() => _ddMode = mode);
    WidgetsBinding.instance.addPostFrameCallback((_) {
      if (!mounted || _ddMode != mode) return;
      _showDropdownOverlay(mode);
    });
  }

  GlobalKey? _btnKeyFor(_DdMode mode) {
    switch (mode) {
      case _DdMode.category:
        return _btnKeyCategory;
      case _DdMode.metric:
        return _activeMetricButtonKey ?? _btnKeyMetric;
      case _DdMode.none:
        return null;
    }
  }

  double _panelWidthFor(_DdMode mode) {
    switch (mode) {
      case _DdMode.metric:
        return 280;
      case _DdMode.category:
        return 220;
      case _DdMode.none:
        return 220;
    }
  }

  void _showDropdownOverlay(_DdMode mode) {
    final key = _btnKeyFor(mode);
    final ctx = key?.currentContext;
    if (ctx == null) return;
    final rb = ctx.findRenderObject() as RenderBox?;
    if (rb == null || !rb.attached) return;
    final btnTopLeft = rb.localToGlobal(Offset.zero);
    final btnSize = rb.size;
    final mq = MediaQuery.of(context);
    final screen = mq.size;
    final panelW = math.min(_panelWidthFor(mode), screen.width - 16);

    const gap = 6.0;
    const absoluteMaxH = 360.0;
    final topInset = mq.padding.top + 8;
    final bottomInset = mq.padding.bottom + 12;
    final spaceBelow =
        screen.height - (btnTopLeft.dy + btnSize.height) - gap - bottomInset;
    final spaceAbove = btnTopLeft.dy - gap - topInset;
    // 优先在按钮下方展开，避免面板「往上飘」脱离触发按钮
    final placeBelow = spaceBelow >= 88 || spaceBelow >= spaceAbove;
    final panelMaxH = math.min(
      absoluteMaxH,
      math.max(120.0, placeBelow ? spaceBelow : spaceAbove),
    );
    final top = placeBelow
        ? btnTopLeft.dy + btnSize.height + gap
        : math.max(topInset, btnTopLeft.dy - gap - panelMaxH);

    double left = btnTopLeft.dx + btnSize.width - panelW;
    if (left < 8) left = btnTopLeft.dx;
    if (left + panelW > screen.width - 8) left = screen.width - 8 - panelW;
    if (left < 8) left = 8;

    _ddEntry = OverlayEntry(
      builder: (overlayCtx) {
        return Stack(
          children: [
            // 全屏遮罩：点外部收起（Web 上用 Listener 比 GestureDetector 更可靠）
            Positioned.fill(
              child: Listener(
                behavior: HitTestBehavior.opaque,
                onPointerDown: (_) => _closeDropdown(),
                child: ColoredBox(
                  color: DunesColors.resolve(
                    context,
                    Colors.black,
                    role: DunesColorRole.surface,
                  ).withAlpha(18),
                ),
              ),
            ),
            Positioned(
              left: left,
              top: top,
              width: panelW,
              child: TapRegion(
                onTapOutside: (_) => _closeDropdown(),
                child: TweenAnimationBuilder<double>(
                  duration: const Duration(milliseconds: 140),
                  curve: Curves.easeOutCubic,
                  tween: Tween(begin: 0.0, end: 1.0),
                  builder: (_, t, child) {
                    return Opacity(
                      opacity: t,
                      child: Transform.translate(
                        offset: Offset(
                          0,
                          placeBelow ? (1 - t) * -4 : (1 - t) * 4,
                        ),
                        child: child,
                      ),
                    );
                  },
                  child: Material(
                    color: Colors.transparent,
                    child: _LhDropdownPanel(
                      width: panelW,
                      maxHeight: panelMaxH,
                      child: _buildDropdownContent(mode),
                    ),
                  ),
                ),
              ),
            ),
          ],
        );
      },
    );
    Overlay.of(context, rootOverlay: true).insert(_ddEntry!);
  }

  void _refreshDropdown() {
    setState(() {});
    _ddEntry?.markNeedsBuild();
  }

  Widget _buildDropdownContent(_DdMode mode) {
    if (mode == _DdMode.category) return _buildCategoryDropdown();
    if (mode == _DdMode.metric) return _buildMetricDropdown();
    return const SizedBox();
  }

  // ── 期间浮层 ──────────────────────────────────────────────────────────────
  //
  //   原来是页面顶部一整条 44px 的分段（日/周/月/季/年）+ 点开后再展开一条
  //   横滑实例条。它是全页作用域最大的控件，却也是频率最低的一个 —— 大多数人
  //   一天切不了两次，却让它长期占着首屏最高的位置，把主角（大数）往下压。
  //
  //   现在收成 Hero 标题行上的一颗「日 ▾」：粒度和「产品汇总 · 09.08」同处
  //   一行，Hero 自己就说清了口径；整条 44px 省掉，页面上移一截。
  //   代价是切换从一次点击变两次 —— 对这个频率的操作，换一屏是划算的。
  //
  //   浮层把原来分两层的东西并成一屏：上半选粒度，下半选具体哪一天/周/月，
  //   底部再挂自定义区间。三件事在一个面里，不用点开一层再点开一层。

  // ── Category dropdown ─────────────────────────────────────────────────────
  Widget _buildCategoryDropdown() {
    final groups = _groups;
    return StatefulBuilder(
      builder: (ctx, setLocal) {
        return Column(
          mainAxisSize: MainAxisSize.min,
          crossAxisAlignment: CrossAxisAlignment.start,
          children: [
            _ddSectionHeader(
              '选择分类',
              'CATEGORY',
              resetLabel: '全部 · CLEAR',
              onReset: () {
                _setGroupFilter('全部', closeDropdown: true);
              },
            ),
            _ddHairline(margin: 8),
            Wrap(
              spacing: 4,
              runSpacing: 4,
              children: groups.map((g) {
                final isOn = g == _groupFilter;
                // 单选：每个分类有自己的颜色 (lhGroupColor) 做 accent,
                // 用户在这里选出的分类, 在主列表 tag 上就是同色, 视觉闭环.
                final accent = g == '全部'
                    ? DunesColors.resolve(ctx, _LhPlum.primary)
                    : lhGroupColor(g);
                return _ddChip(
                  label: g,
                  isOn: isOn,
                  isMulti: false,
                  accent: accent,
                  onTap: () {
                    _setGroupFilter(g, closeDropdown: true);
                  },
                );
              }).toList(),
            ),
          ],
        );
      },
    );
  }

  // ── HUN helper — 读行级 hunU / hunN / hunH（后端真字段） ─────────────────
  _HunInfo _hunOf(Map<String, dynamic> r) {
    return _HunInfo(
      u: (r['hunU'] as num?)?.toDouble() ?? 0,
      n: (r['hunN'] as num?)?.toDouble() ?? 0,
      h: (r['hunH'] as num?)?.toDouble() ?? 0,
    );
  }

  Widget _buildMetricDropdown() {
    final tab = _metricsTab;
    final defs = _uiMetricDefs(tab);
    final available = defs
        .where((d) => d['listDefault'] == true)
        .map((d) => d['key'] as String)
        .toList();
    var sortable = [
      for (final d in defs)
        if (d['sortable'] != false) d['key'] as String,
    ];
    if (sortable.isEmpty) {
      sortable = ['profit', ...available.where((k) => k != 'discount')];
    }
    // 标签二「全部」按省排序，默认按总资产；总资产不是一列，只在排序里出现。
    if (tab == 'supply' &&
        !_inTopic &&
        !_hidesSensitiveFinance &&
        !sortable.contains(lighthouseTotalAssetsSortKey)) {
      sortable = [lighthouseTotalAssetsSortKey, ...sortable];
    }

    return StatefulBuilder(
      builder: (ctx, setLocal) {
        final selected = _metrics[tab] ?? [];

        void refresh() {
          _refreshDropdown();
          setLocal(() {});
        }

        return Column(
          mainAxisSize: MainAxisSize.min,
          crossAxisAlignment: CrossAxisAlignment.start,
          children: [
            // ── Section 1: 排序 & 显示 ──
            _ddSectionHeader(
              '排序 & 显示',
              'SORT & VIEW',
              resetLabel: '默认 · RESET',
              onReset: () {
                setState(() {
                  _metrics[tab] = List.from(_uiResetMetrics());
                  _sortField = _uiResetSortField();
                  _sortDesc = true;
                  // RESET 是「这个 tab 全部回到出厂」，列序也要一起回。
                  _colOrder[tab] = <String>[];
                  _colOrderTouched.remove(tab);
                });
                _persistMetricPrefs();
                refresh();
              },
            ),
            _ddHairline(margin: 8),

            // ── 排序字段 (单选) ──
            _ddSubKicker(
              '按 ${_metricLabel(_sortField, tab: tab)} 排序',
              'SORT BY',
            ),
            const SizedBox(height: 6),
            Wrap(
              spacing: 4,
              runSpacing: 4,
              children: sortable.map((k) {
                final isOn = k == _sortField;
                return _ddChip(
                  label: _metricLabel(k, tab: tab),
                  isOn: isOn,
                  isMulti: false,
                  onTap: () {
                    setState(() => _sortField = k);
                    refresh();
                  },
                );
              }).toList(),
            ),
            const SizedBox(height: 9),

            // ── 排序方向 ──
            Row(
              children: [
                Expanded(child: _ddDirBtn('↓ 从高到低', 'desc', refresh)),
                const SizedBox(width: 5),
                Expanded(child: _ddDirBtn('↑ 从低到高', 'asc', refresh)),
              ],
            ),

            _ddHairline(margin: 10),

            // ── 列排列入口 ──
            //   显隐（下面那组复选）和排列是同一个模型的两个面，放在一起。
            //   排列要拖拽，chip 排布撑不下，所以走独立 sheet。
            GestureDetector(
              behavior: HitTestBehavior.opaque,
              onTap: () {
                _closeDropdown();
                _openColOrderSheet();
              },
              child: Container(
                padding: const EdgeInsets.symmetric(vertical: 9, horizontal: 8),
                decoration: BoxDecoration(
                  color: DunesColors.resolve(
                    ctx,
                    _LhPlum.mist,
                    role: DunesColorRole.surface,
                  ),
                  borderRadius: BorderRadius.circular(4),
                ),
                child: Row(
                  children: [
                    Icon(
                      Icons.reorder_rounded,
                      size: 15,
                      color: DunesColors.resolve(ctx, _LhPlum.primary),
                    ),
                    const SizedBox(width: 7),
                    Expanded(
                      child: Text(
                        '列排列',
                        style: LhTypography.sans(
                          size: 12,
                          color: DunesColors.resolve(ctx, LhColors.ink),
                          weight: FontWeight.w600,
                          context: ctx,
                        ),
                      ),
                    ),
                    Text(
                      _activeColPreset(tab) == null
                          ? '自定义'
                          : _kColOrderPresets[_activeColPreset(tab)]!.$1,
                      style: LhTypography.mono(
                        size: 9.5,
                        color: DunesColors.resolve(ctx, LhColors.mute2),
                        weight: FontWeight.w600,
                        letterSpacing: 0.4,
                        context: ctx,
                      ),
                    ),
                    Icon(
                      Icons.chevron_right_rounded,
                      size: 15,
                      color: DunesColors.resolve(ctx, LhColors.mute2),
                    ),
                  ],
                ),
              ),
            ),

            _ddHairline(margin: 10),

            // ── Section 2: 每行展示指标 (多选) ──
            _ddSubKicker('每行展示指标', 'DISPLAY METRICS'),
            const SizedBox(height: 6),
            Wrap(
              spacing: 4,
              runSpacing: 4,
              children: available.map((k) {
                final isOn = selected.contains(k);
                return _ddChip(
                  label: _metricLabel(k, tab: tab),
                  isOn: isOn,
                  isMulti: true, // ← 复选: 前置 4.5px 小圆点区分单选/多选
                  onTap: () {
                    setState(() {
                      final m = _metrics[tab]!;
                      if (isOn) {
                        if (m.length > 1) m.remove(k);
                      } else {
                        m.add(k);
                      }
                      // 用户已自定义列序的 tab 不再纠正顺序 —— 排列权在用户手上。
                      _metrics[tab] = _colOrderTouched.contains(tab)
                          ? m
                          : _ensureNetProfitAfterProfit(m);
                    });
                    _persistMetricPrefs();
                    refresh();
                  },
                );
              }).toList(),
            ),
          ],
        );
      },
    );
  }

  Widget _ddDirBtn(String label, String dir, VoidCallback refresh) {
