  // ═════════════════════════════════════════════════════════════════════════
  // ── Dropdown 通用组件 (v3.7) —— 对齐 hero cell / list row 字型语言 ────────
  //   问题：原 dropdown 用 bordered chips + letterSpacing 1.2 + sans w500,
  //         跟外层主列表 (mono UPPER 0.5 kicker + no-border + copper-tint on)
  //         明显是两套 UI kit, 属于"外面 hero 化了里面 SaaS 化"。
  //   收敛: 抽 3 个 helper —— header / chip / hairline, 之后所有 dropdown 用
  //         同一套. 以后再改 UI 只动 helper.
  // ═════════════════════════════════════════════════════════════════════════

  /// Dropdown 分区头 —— 双语 kicker + 可选 reset 动作.
  /// 中文 sans w700 -0.1 (主 label), 英文 mono UPPER letterSpacing 0.5 (kicker).
  /// Reset 用 mono copper letterSpacing 0.5 —— 跟 hero 系统 kicker 同族.
  Widget _ddSectionHeader(
    String zhLabel,
    String enKicker, {
    String? resetLabel,
    VoidCallback? onReset,
  }) {
    return Row(
      mainAxisAlignment: MainAxisAlignment.spaceBetween,
      crossAxisAlignment: CrossAxisAlignment.baseline,
      textBaseline: TextBaseline.alphabetic,
      children: [
        Row(
          mainAxisSize: MainAxisSize.min,
          crossAxisAlignment: CrossAxisAlignment.baseline,
          textBaseline: TextBaseline.alphabetic,
          children: [
            Text(
              zhLabel,
              style: LhTypography.sans(
                size: 11.5,
                color: DunesColors.resolve(context, LhColors.ink),
                weight: FontWeight.w700,
                letterSpacing: -0.1,
                context: context,
              ),
            ),
            const SizedBox(width: 6),
            Text(
              enKicker,
              style: LhTypography.mono(
                size: 7.5,
                color: DunesColors.resolve(context, LhColors.mute2),
                weight: FontWeight.w600,
                letterSpacing: 0.5,
                context: context,
              ),
            ),
          ],
        ),
        if (resetLabel != null && onReset != null)
          GestureDetector(
            behavior: HitTestBehavior.opaque,
            onTap: onReset,
            child: Padding(
              padding: const EdgeInsets.symmetric(horizontal: 4, vertical: 2),
              child: Text(
                resetLabel,
                style: LhTypography.mono(
                  size: 7.5,
                  color: DunesColors.resolve(context, _LhPlum.primary),
                  weight: FontWeight.w600,
                  letterSpacing: 0.5,
                  context: context,
                ),
              ),
            ),
          ),
      ],
    );
  }

  /// Dropdown 子分区 kicker —— "按 XX 排序" / "每行展示指标" 这类
  Widget _ddSubKicker(String zhLabel, String enKicker) {
    return Row(
      mainAxisSize: MainAxisSize.min,
      crossAxisAlignment: CrossAxisAlignment.baseline,
      textBaseline: TextBaseline.alphabetic,
      children: [
        Text(
          zhLabel,
          style: LhTypography.sans(
            size: 9.5,
            color: DunesColors.resolve(context, LhColors.mute),
            weight: FontWeight.w600,
            context: context,
          ),
        ),
        const SizedBox(width: 5),
        Text(
          enKicker,
          style: LhTypography.mono(
            size: 7,
            color: DunesColors.resolve(context, LhColors.mute2),
            weight: FontWeight.w600,
            letterSpacing: 0.5,
            context: context,
          ),
        ),
      ],
    );
  }

  /// 极细 hairline 分隔条 (跟主列表 meta 上方那条同款)
  Widget _ddHairline({double margin = 8}) => Container(
    height: 1,
    color: DunesColors.resolve(
      context,
      LhColors.line2,
      role: DunesColorRole.surface,
    ),
    margin: EdgeInsets.symmetric(vertical: margin),
  );

  /// 统一 chip —— 无 border, off 透明, on 用 accent alpha 24 填色.
  /// isMulti=true 时前置 4.5×4.5 圆点区分复选/单选语义 (跟 hero 签名点同族).
  /// accent 默认 copper (跟主列表 top3 / meta highlight 同色).
  Widget _ddChip({
    required String label,
    required bool isOn,
    VoidCallback? onTap,
    bool isMulti = false,
    Color? accent,
    Color? offColor,
  }) {
    final acc = accent ?? DunesColors.resolve(context, _LhPlum.primary);
    final off = offColor ?? DunesColors.resolve(context, LhColors.ink2);
    return GestureDetector(
      behavior: HitTestBehavior.opaque,
      onTap: onTap,
      child: AnimatedContainer(
        duration: const Duration(milliseconds: 140),
        padding: EdgeInsets.fromLTRB(isMulti ? 7 : 9, 4, 9, 4),
        decoration: BoxDecoration(
          color: DunesColors.resolveNullable(
            context,
            isOn ? acc.withAlpha(24) : Colors.transparent,
            role: DunesColorRole.surface,
          ),
          borderRadius: BorderRadius.circular(4),
        ),
        child: Row(
          mainAxisSize: MainAxisSize.min,
          children: [
            if (isMulti) ...[
              Container(
                width: 4.5,
                height: 4.5,
                margin: const EdgeInsets.only(right: 6),
                decoration: BoxDecoration(
                  color: DunesColors.resolveNullable(
                    context,
                    isOn ? acc : off.withAlpha(60),
                    role: DunesColorRole.surface,
                  ),
                  shape: BoxShape.circle,
                ),
              ),
            ],
            Text(
              label,
              style: LhTypography.sans(
                size: 10.5,
                color: isOn ? acc : off,
                weight: isOn ? FontWeight.w700 : FontWeight.w500,
                letterSpacing: isOn ? -0.15 : 0,
                context: context,
              ),
            ),
          ],
        ),
      ),
    );
  }

