  bool get _isNonLedgerTab => _tab == 'analysis';

  bool _isNoPermissionError(Object? error) {
    if (error == null) return false;
    final msg = error.toString();
    return msg.contains('暂无权限') || msg.contains('无权限') || msg.contains('403');
  }

