  @override
  Widget build(BuildContext context) {
    _syncHeroFullscreen();
    _warmHeroHistory();
    if (widget.sharedCard != null) {
      return Theme(
        data: Theme.of(context).brightness == Brightness.dark
            ? Theme.of(context)
            : DunesTheme.light(),
        child: Material(color: Colors.transparent, child: _buildSharedCard()),
      );
    }
    return PopScope(
      canPop: !_hasInternalBackStack(),
      onPopInvokedWithResult: (didPop, _) {
        if (didPop) return;
        _handleInternalBack();
      },
      child: Theme(
        data: Theme.of(context).brightness == Brightness.dark
            ? Theme.of(context)
            : DunesTheme.light(),
        child: Scaffold(
          backgroundColor: DunesColors.resolve(
            context,
            DunesColors.bgApp,
            role: DunesColorRole.surface,
          ),
          // 键盘弹出时不顶起底部 Column —— SKU 搜索时
          // 通讯/千机/灯塔/我的 这条主 tab bar 保持在屏幕底部，
          // 不会被怼到键盘正上方。搜索框本身在页面中上部，
          // 不会被键盘遮挡。
          resizeToAvoidBottomInset: false,
          body: _withStatusBand(
            SafeArea(
              bottom: false,
              // 跟通讯 / 我的一样：内容铺到屏幕底，四个 Tab 浮在灯塔上面。
              // 末行不被挡住靠 ListView 底部 padding，不在这里垫白板。
              child: _wrapWithUiZoom(
                Column(
                  children: [
                    // L2/L3 详情自带 sticky header（返回·灯塔·缩放/更新），
                    // 若再挂一级 AppBar 会叠出双份标题与右侧按钮。
                    if (_detailKey == null && !_biViewOpen) _buildAppBar(),
                    Expanded(
                      child: !_hasAccess
                          ? _buildNoAccessView()
                          : Stack(
                              children: [
                                // 撑满整块区域 —— 别删。
                                //
                                //   Stack 默认 StackFit.loose：自身尺寸取「非
                                //   Positioned 子节点里最大的那个」。这里 Expanded
                                //   只给了紧高度，宽度是松的（Column 默认 center，
                                //   不 stretch）。
                                //   BI 打开时，唯一的非 Positioned 子节点是那个
                                //   offstage 的主列表，而 offstage 的 RenderBox 尺寸
                                //   是 0 —— Stack 宽度于是塌成 0，Positioned.fill
                                //   跟着填了个 0 宽的框，BI 整页存在但没有一个像素。
                                //   表现正是「点了没反应 / 白屏」。
                                //   进 L2 不出问题，只是因为详情那层是有尺寸的非
                                //   Positioned 子节点，替 Stack 把宽度撑住了。
                                const SizedBox.expand(),
                                // 一级主列表始终保活（Offstage），进 L2 不销毁，
                                // 右滑/返回可回到原先滚动浏览位置。
                                Offstage(
                                  offstage: _detailKey != null || _biViewOpen,
                                  child: TickerMode(
                                    enabled: _detailKey == null && !_biViewOpen,
                                    child: KeyedSubtree(
                                      key: const ValueKey('main'),
                                      child: _buildMainView(),
                                    ),
                                  ),
                                ),
                                if (_detailKey != null)
                                  AnimatedSwitcher(
                                    duration: const Duration(milliseconds: 220),
                                    switchInCurve: Curves.easeOut,
                                    switchOutCurve: Curves.easeIn,
                                    transitionBuilder: (child, animation) {
                                      final slide = Tween<Offset>(
                                        begin: const Offset(0.035, 0),
                                        end: Offset.zero,
                                      ).animate(animation);
                                      return FadeTransition(
                                        opacity: animation,
                                        child: SlideTransition(
                                          position: slide,
                                          child: child,
                                        ),
                                      );
                                    },
                                    child: KeyedSubtree(
                                      key: ValueKey(_detailRouteKey()),
                                      child: _buildDetailView(),
                                    ),
                                  ),
                                if (_showPageBusyOverlay)
                                  _buildLoadingOverlay(),
                                if (_biViewOpen)
                                  Positioned.fill(
                                    child: Material(
                                      color: DunesColors.resolve(
                                        context,
                                        LhColors.mist,
                                        role: DunesColorRole.surface,
                                      ),
                                      child: LhBiViewPage(
                                        initialDim: _biInitialDim(),
                                        dims: _biDims(),
                                        initialMetric: _sortField,
                                        rangeLabel: _selectedRangeLabel,
                                        periodLabel: _periodLabelFor(_period),
                                        rowsFor: (d) =>
                                            _bundle?.rowsOf(d) ??
                                            const <Map<String, dynamic>>[],
                                        metricsFor: _biMetricsFor,
                                        metricValue: _rowMetricValue,
                                        dimLabel: _biDimLabel,
                                        categoriesFor: _biCategoriesFor,
                                        metricDelta: _deltaFromEntityRow,
                                        breakdownFor: _biBreakdownFor,
                                        requestBreakdown: _biRequestBreakdown,
                                        seriesFor: _biSeriesFor,
                                        loading: _biDimLoading,
                                        windowRowsFor: _biWindowRowsFor,
                                        reportFor: _biReportFor,
                                        reportBusy: _biReportBusyFor,
                                        requestReport: _biRequestReport,
                                        forecastFor: _biForecastCard,
                                        onDimChanged: (d) {
                                          if (!_kBiDims.contains(d)) return;
                                          _biDim = d;
                                          unawaited(_loadTab(d));
                                          unawaited(_loadBiWindowRows(d));
                                        },
                                        onClose: _closeBiView,
                                        topChrome: _buildBiTopChrome(),
                                        periodBar: _buildPeriodBar(),
                                      ),
                                    ),
                                  ),
                                if (_biViewOpen && _biError != null)
                                  Positioned(
                                    left: 0,
                                    right: 0,
                                    top: 0,
                                    child: _buildBiErrorBanner(),
                                  ),
                              ],
                            ),
                    ),
                  ],
                ),
              ),
            ),
          ),
        ),
      ),
    );
  }

  /// 与通讯 / 我的一致：内容铺满，滚动到最底再让出悬浮 Tab。
  double _bottomNavScrollPadding(BuildContext context) =>
      dunesAppBottomNavContentPadding(context, fallback: 16);

  // ───── AppBar ─────────────────────────────────────────────────────────────
  // 标题、日期、同步状态、工具同一行。
  Widget _buildAppBar() {
    const onDark = lighthouseTopBandDark;
    Widget brand({bool showEn = true}) => Row(
      mainAxisSize: MainAxisSize.min,
      children: [
        if (lighthouseAppBarShowsBrandMark) ...[
          const _LhAppBrandMark(size: 26),
          const SizedBox(width: 9),
        ],
        Flexible(
          child: RichText(
            maxLines: 1,
            overflow: TextOverflow.ellipsis,
            text: TextSpan(
              children: [
                TextSpan(
                  text: '灯塔',
                  style: LhTypography.sans(
                    size: lighthouseAppBarTitleFontSize,
                    weight: FontWeight.w600,
                    color: onDark
                        ? _kLhBandInkStrong
                        : DunesColors.resolve(
                            context,
                            Color(lighthouseAppBarTitleColorValue),
                          ),
                    letterSpacing: onDark ? 0.8 : -0.3,
                    context: context,
                  ),
                ),
                if (showEn)
                TextSpan(
                  text: '  LIGHTHOUSE',
                  style: LhTypography.mono(
                    size: lighthouseAppBarEnglishFontSize,
                    color: onDark
                        ? _kLhBandMute
                        : DunesColors.resolve(context, LhColors.mute2),
                    weight: FontWeight.w600,
                    letterSpacing: 1.8,
                    context: context,
                  ),
                ),
              ],
            ),
          ),
        ),
      ],
    );

    return LayoutBuilder(
      builder: (context, c) {
        // 2026-10-26 · 方案 E：顶栏只剩一行 —— 左品牌，右「周期浮岛 + ⋯」。
        // 日周月季年收进浮岛，点开再选；缩放 / 刷新 / 声音收进 ⋯。
        if (onDark) {
          return _lhBand(
            shadow: true,
            padding: const EdgeInsets.fromLTRB(
              lighthouseAppBarPaddingH,
              10,
              8,
              10,
            ),
            child: Row(
              crossAxisAlignment: CrossAxisAlignment.center,
              children: lighthousePixelMarkEnabled
                  // 2026-10-27 · 像素灯塔填在标题和周期浮岛之间：光束朝右扫向浮岛。
                  // 英文「LIGHTHOUSE」让位给这块场景。
                  ? [
                      // brand 里的标题是 Flexible，这里按自身宽度占位，不参与分空间。
                      IntrinsicWidth(child: brand(showEn: false)),
                      const SizedBox(width: 8),
                      // 像素场景占品牌和浮岛之间的空隙，长度是这段的 70%，靠左。
                      // 浮岛本身不参与伸缩，这样多余空白留在光束和浮岛之间，整组贴在最右侧。
                      Expanded(
                        child: Align(
                          alignment: Alignment.centerLeft,
                          child: FractionallySizedBox(
                            widthFactor: 0.7,
                            alignment: Alignment.centerLeft,
                            child: LighthousePixelMark(controller: _pixelCtl),
                          ),
                        ),
                      ),
                      const SizedBox(width: 8),
                      _buildTopIslands(),
                    ]
                  : [
                      brand(showEn: c.maxWidth >= 640),
                      const SizedBox(width: 10),
                      Expanded(child: _buildTopIslands()),
                    ],
            ),
          );
        }
        final inline = _lhBandHoldsPeriod(c.maxWidth);
        final tools = _buildAppBarToolbar(onDark: onDark);
        return _lhBand(
          shadow: inline,
          padding: EdgeInsets.fromLTRB(
            lighthouseAppBarPaddingH,
            inline ? 11 : 10,
            lighthouseAppBarPaddingH,
            inline ? 11 : 10,
          ),
          child: inline
              // 宽屏一行：左品牌 · 中日周月季年 · 右工具。
              ? Row(
                  crossAxisAlignment: CrossAxisAlignment.center,
                  children: [
                    Expanded(
                      child: Align(
                        alignment: Alignment.centerLeft,
                        child: brand(),
                      ),
                    ),
                    const SizedBox(width: 14),
                    Flexible(
                      flex: 3,
                      child: ConstrainedBox(
                        constraints: const BoxConstraints(maxWidth: 560),
                        child: _buildPeriodBar(onDark: true),
                      ),
                    ),
                    const SizedBox(width: 14),
                    Expanded(
                      child: Align(
                        alignment: Alignment.centerRight,
                        child: tools,
                      ),
                    ),
                  ],
                )
              : Row(
                  crossAxisAlignment: CrossAxisAlignment.center,
                  children: [
                    Expanded(
                      child: Align(
                        alignment: Alignment.centerLeft,
                        child: brand(),
                      ),
                    ),
                    const SizedBox(width: 8),
                    tools,
                  ],
                ),
        );
      },
    );
  }

  /// 一级主页、宽屏、看得到数据：日周月季年并进顶栏那一行。
  bool _lhBandHoldsPeriod(double width) =>
      lighthouseTopBandDark &&
      width >= lighthouseTopBandInlinePeriodMinWidth &&
      _detailKey == null &&
      !_biViewOpen &&
      _metricPageKey == null &&
      _hasAccess;

  /// 深色带外壳：一级顶栏、二级 / 三级 / 四级吸顶头、期间条都套这一层，
  /// 上下接起来是一整条。[shadow] 只给最下面那一截。
  Widget _lhBand({
    required EdgeInsets padding,
    required Widget child,
    bool shadow = false,
  }) {
    if (!lighthouseTopBandDark) return Padding(padding: padding, child: child);
    // 毛玻璃：底下滚过去的卡片隐约透出来。只有最下面那一截画底边发丝线 + 极淡投影。
    return DecoratedBox(
      decoration: BoxDecoration(
        boxShadow: shadow
            ? const [
                BoxShadow(
                  color: Color(0x144A3A7A),
                  blurRadius: 14,
                  spreadRadius: -6,
                  offset: Offset(0, 6),
                ),
              ]
            : null,
      ),
      child: ClipRect(
        child: BackdropFilter(
          filter: ImageFilter.blur(sigmaX: 18, sigmaY: 18),
          child: Container(
            width: double.infinity,
            padding: padding,
            decoration: BoxDecoration(
              color: _kLhBand,
              border: shadow
                  ? const Border(
                      bottom: BorderSide(color: _kLhBandEdge, width: 0.5),
                    )
                  : null,
            ),
            child: child,
          ),
        ),
      ),
    );
  }

  /// 手机刘海 / 状态栏那一截也刷成深色带，状态栏图标改白。
  Widget _withStatusBand(Widget child) {
    if (!lighthouseTopBandDark) return child;
    final top = MediaQuery.paddingOf(context).top;
    // 浅色毛玻璃顶栏：状态栏图标改深色。
    return AnnotatedRegion<SystemUiOverlayStyle>(
      value: SystemUiOverlayStyle.dark,
      child: Stack(
        children: [
          Positioned.fill(child: child),
          if (top > 0)
            Positioned(
              left: 0,
              right: 0,
              top: 0,
              height: top,
              child: ClipRect(
                child: BackdropFilter(
                  filter: ImageFilter.blur(sigmaX: 18, sigmaY: 18),
                  child: const ColoredBox(color: _kLhBand),
                ),
              ),
            ),
        ],
      ),
    );
  }

  /// 一级切 tab / 二级进详情共用的载入特效：大号品牌 spinner + mono 文案。
  Widget _buildBrandBusyContent({required String label}) {
    return Column(
      mainAxisSize: MainAxisSize.min,
      children: [
        const _LhBrandLoader(size: 72),
        const SizedBox(height: 14),
        Text(
          label,
          style: LhTypography.mono(
            size: 10,
            color: DunesColors.resolve(context, LhColors.mute),
            weight: FontWeight.w600,
            letterSpacing: 1.6,
            context: context,
          ),
        ),
      ],
    );
  }

  Widget _buildLoadingOverlay() {
    final label = _cubeLoading && !_loading ? '分析加载中' : '数据同步中';
    return Positioned.fill(
      child: ColoredBox(
        color: DunesColors.resolve(
          context,
          Colors.white,
          role: DunesColorRole.surface,
        ).withAlpha(210),
        child: Center(child: _buildBrandBusyContent(label: label)),
      ),
    );
  }

  void _maybeLoadMoreL1() {
    if (_isNonLedgerTab) return;
    final total = _currentRows.length;
    if (_listLimit >= total || _listLoadingMore) return;
    _listLoadingMore = true;
    setState(() {
      _listLimit = (_listLimit + _listPageSize).clamp(0, total);
    });
    WidgetsBinding.instance.addPostFrameCallback((_) {
      _listLoadingMore = false;
    });
  }

  // ───── Main View ──────────────────────────────────────────────────────────
  Widget _buildMainView() {
    if (_metricPageKey != null)
      return _buildMetricAnalysisPage(_metricPageKey!);
    // 内容高度变了（切期间、切维度、展开行）但没滚动时，也要重新判断要不要钉住。
    WidgetsBinding.instance.addPostFrameCallback((_) {
      if (mounted) _updateLedgerTabsStuck();
    });
    return Column(
      crossAxisAlignment: CrossAxisAlignment.stretch,
      children: [
        _buildPinnedPeriodBar(),
        // 业务 / 财务切换钉在顶栏下面，列表滚动时一直在。
        ColoredBox(
          color: DunesColors.resolve(
            context,
            lighthouseMainPageBg,
            role: DunesColorRole.surface,
          ),
          child: _buildLedgerModeSwitch(),
        ),
        Expanded(
          child: Stack(
            key: _mainListAreaKey,
            children: [
              Positioned.fill(
                child: ColoredBox(
                  color: DunesColors.resolve(
                    context,
                    lighthouseMainPageBg,
                    role: DunesColorRole.surface,
                  ),
                  child: _buildMainList(),
                ),
              ),
              // 列表一滚动，钉住的时间条底下浮出一道淡紫阴影（画在列表上面，
              // 不然会被列表盖住），表示内容从它下面经过。
              Positioned(
                left: 0,
                right: 0,
                top: 0,
                height: 10,
                child: IgnorePointer(
                  child: AnimatedBuilder(
                    animation: _mainListScrollCtrl,
                    builder: (ctx, _) {
                      final c = _mainListScrollCtrl;
                      final scrolled =
                          c.hasClients &&
                          c.positions.length == 1 &&
                          c.offset > 2;
                      return AnimatedOpacity(
                        opacity: scrolled ? 1 : 0,
                        duration: const Duration(milliseconds: 160),
                        child: DecoratedBox(
                          decoration: BoxDecoration(
                            gradient: LinearGradient(
                              begin: Alignment.topCenter,
                              end: Alignment.bottomCenter,
                              colors: [
                                _LhPlum.deep.withAlpha(22),
                                _LhPlum.deep.withAlpha(0),
                              ],
                            ),
                          ),
                        ),
                      );
                    },
                  ),
                ),
              ),
              // 产品 / 供给方 / … + 分类：滑过之后钉在期间条下面。
              Positioned(
                left: 0,
                right: 0,
                top: 0,
                child: ValueListenableBuilder<bool>(
                  valueListenable: _ledgerTabsStuck,
                  builder: (context, stuck, _) => stuck
                      ? _buildStickyLedgerTabs()
                      : const SizedBox.shrink(),
                ),
              ),
            ],
          ),
        ),
      ],
    );
  }

  // ───── 业务 / 财务口径 ────────────────────────────────────────────────────

  Widget _buildLedgerModeSwitch() {
    final bf = _bf;
    if (bf == null) return const SizedBox.shrink();
    return ValueListenableBuilder<bool?>(
      valueListenable: bf.access,
      builder: (context, access, _) {
        if (!_hasNetTaAccess && access != true) return const SizedBox.shrink();
        return Padding(
          padding: const EdgeInsets.fromLTRB(
            lighthouseHeroShellMarginH,
            2,
            lighthouseHeroShellMarginH,
            10,
          ),
          child: LighthouseLedgerModeSwitch(
            finance: _isFinanceLedger,
            onChanged: _setFinanceLedger,
          ),
        );
      },
    );
  }

  void _setFinanceLedger(bool finance) {
    if (finance == _isFinanceLedger) return;
    _closeDropdown();
    final bf = _bf;
    if (finance) {
      setState(() => _financeLedger = true);
      if (bf != null && bf.access.value == false && _hasNetTaAccess) {
        _enterNetTaTab();
      } else if (bf != null && bf.summary == null && !bf.loading) {
        unawaited(bf.load());
      }
      return;
    }
    setState(() => _financeLedger = false);
    if (_tab == 'netTa') _enterLedgerTab(_bfReturnTab);
  }

  /// 与维度条点「净TA」同一套状态重置。
  void _enterNetTaTab() {
    if (!_hasNetTaAccess || _tab == 'netTa') return;
    _closeDropdown();
    setState(() {
      _bfReturnTab = _tab == 'analysis' ? 'product' : _tab;
      _financeLedger = true;
      _tab = 'netTa';
      _groupFilter = '全部';
      _heroPointIndex = null;
      _tabBarShowsGroups = false;
      _hunFilter = '全部';
      _tradeTypeFilter = '全部';
      _anomalyFilter = '全部';
      _sortField = 'netTa';
      _listLimit = _listPageSize;
      _rowsCacheKey = '';
      _rowsCache = null;
      _netTaBalanceOpen = false;
      _closeMetricPage();
      _invalidateAiSummary();
      _restoreSharedHeroMetrics();
    });
    unawaited(_loadTab('netTa'));
  }

  /// 与维度条切到一个账本维度同一套状态重置（离开净TA 时用）。
  void _enterLedgerTab(String key) {
    if (key == _tab) return;
    final prevGroup = _groupFilter;
    final leavingNetTa = _tab == 'netTa';
    final leavingPeople = _tab == 'people';
    setState(() {
      _tab = key;
      _heroPointIndex = null;
      _tabBarShowsGroups = true;
      if (_sortField == 'netTa') _sortField = 'profit';
      if (key == 'supply' && !_inTopic) {
        _sortField = lighthouseTotalAssetsSortKey;
        _sortDesc = true;
      } else if (_sortField == lighthouseTotalAssetsSortKey) {
        _sortField = 'profit';
      }
      _groupFilter = lighthouseGroupAfterTabSwitch(
        currentGroup: prevGroup,
        nextTabOptions: _categoryOptions(key),
      );
      _ensureDefaultGroupFilter();
      if (key != 'supply' && key != 'channel') _hunFilter = '全部';
      if (key != 'supply') _tradeTypeFilter = '全部';
      _listLimit = _listPageSize;
      _rowsCacheKey = '';
      _rowsCache = null;
      _closeMetricPage();
      _invalidateAiSummary();
      _clearNetTAHeroTransientState();
      if (leavingPeople) {
        _expandedTrendKey = null;
        _heroTraceKey = null;
      }
      if (_groupFilter == '全部' || leavingNetTa) {
        _restoreSharedHeroMetrics();
      }
    });
    unawaited(_reloadHeroSummary());
    _loadTab(key);
  }

  /// 财务 Hero 的「业财对照 / 业财差额」→ 滚到主体列表。
  void _scrollToLedger() {
    final anchor = _ledgerTabsAnchorKey.currentContext?.findRenderObject();
    final area = _mainListAreaKey.currentContext?.findRenderObject();
    if (anchor is! RenderBox ||
        area is! RenderBox ||
        !anchor.attached ||
        !area.attached ||
        !_mainListScrollCtrl.hasClients) {
      return;
    }
    final dy = anchor.localToGlobal(Offset.zero, ancestor: area).dy;
    final pos = _mainListScrollCtrl.position;
    final target = (pos.pixels + dy)
        .clamp(pos.minScrollExtent, pos.maxScrollExtent)
        .toDouble();
    unawaited(
      _mainListScrollCtrl.animateTo(
        target,
        duration: const Duration(milliseconds: 360),
        curve: Curves.easeOutCubic,
      ),
    );
  }

  /// 账本卡顶上那块（维度 + 分类）的上沿滑出列表区顶部 → 钉住。
  void _updateLedgerTabsStuck() {
    final anchor = _ledgerTabsAnchorKey.currentContext?.findRenderObject();
    final area = _mainListAreaKey.currentContext?.findRenderObject();
    var stuck = false;
    if (anchor is RenderBox &&
        area is RenderBox &&
        anchor.attached &&
        area.attached &&
        anchor.hasSize &&
        area.hasSize) {
      final dy = anchor.localToGlobal(Offset.zero, ancestor: area).dy;
      stuck = dy < -0.5;
    }
    if (_ledgerTabsStuck.value != stuck) _ledgerTabsStuck.value = stuck;
  }

  /// 钉住时的那一份：同一套 _buildTabSegment，外面一道跟账本卡同宽的白卡，
  /// 两侧和上方用页面底色垫满，滑过去的内容不会从缝里露出来。
  Widget _buildStickyLedgerTabs() {
    return Container(
      color: DunesColors.resolve(
        context,
        lighthouseMainPageBg,
        role: DunesColorRole.surface,
      ),
      padding: const EdgeInsets.fromLTRB(
        lighthouseHeroShellMarginH,
        0,
        lighthouseHeroShellMarginH,
        6,
      ),
      child: Container(
        decoration: BoxDecoration(
          color: DunesColors.resolve(
            context,
            Colors.white,
            role: DunesColorRole.surface,
          ),
          border: Border.all(
            color: DunesColors.resolve(
              context,
              _LhPlum.line,
              role: DunesColorRole.border,
            ),
            width: lighthouseLedgerPanelBorderWidth,
          ),
          borderRadius: BorderRadius.circular(lighthouseLedgerPanelRadius),
          boxShadow: [
            BoxShadow(
              color: _LhPlum.deep.withAlpha(30),
              blurRadius: 16,
              spreadRadius: -6,
              offset: const Offset(0, 6),
            ),
          ],
        ),
        clipBehavior: Clip.antiAlias,
        child: _inTopic
            ? Column(
                mainAxisSize: MainAxisSize.min,
                crossAxisAlignment: CrossAxisAlignment.stretch,
                children: [
                  _buildTopicLedgerBar(),
                  _buildTabSegment(sticky: true),
                ],
              )
            : _buildTabSegment(sticky: true),
      ),
    );
  }

  // ───── 顶部浮岛（2026-10-26 · 方案 E）─────────────────────────────────────
  //
  //   [本月] 10.01–10.26 ⌄   ( ⋯ )
  //
  // · 周期岛：渐变紫小胶囊写当前期（本月 / 上月 / 9月…），旁边 mono 日期；
  //   点开从岛的位置弹出周期面板（日周月季年区间 + 往前翻），选完自动收起。
  // · ⋯ 岛：缩放 / 更新数据 / 触感与声音。刷新时 ⋯ 本身变成品牌 loading，
  //   缩放不是 100% 时右上角亮一颗小紫点。
  // · 材质见 core/theme/dunes_island.dart（只灯塔用；App 底栏保持原样）。

  static const double _kIslandH = 40;
  static const Color _kIslandInk = Color(0xFF4A3A7A);
  static const Color _kIslandInkStrong = Color(0xFF2B2147);
  static const Color _kIslandMute = Color(0xFF6E6890);
  static const Color _kIslandIcon = Color(0xFF5A458F);

  Widget _buildTopIslands() {
    // 周期和更多浮岛作为一组靠右。父级给了有限宽度时，周期岛可收缩；
    // 顶栏把本组放在最右侧、宽度不限时，按内容宽度排，避免把空白顶到组后面。
    // 2026-10-30 · 财务也按日 / 周 / 月 / 季 / 年：和业务共用同一颗周期岛。
    final period = _hasAccess ? _buildGlowingPeriodIsland() : null;
    return LayoutBuilder(
      builder: (context, constraints) {
        final bounded = constraints.maxWidth.isFinite;
        return Row(
          mainAxisSize: bounded ? MainAxisSize.max : MainAxisSize.min,
          children: [
            if (period != null)
              bounded
                  ? Expanded(
                      child: Align(
                        alignment: Alignment.centerRight,
                        child: period,
                      ),
                    )
                  : period,
            if (_hasAccess) const SizedBox(width: 8),
            _buildMoreIsland(),
          ],
        );
      },
    );
  }

  /// 同步完成 / 切换日期时，像素光束照到周期浮岛，亮一圈金光。
  Widget _buildGlowingPeriodIsland() {
    return ValueListenableBuilder<bool>(
      valueListenable: _pixelCtl.islandGlow,
      builder: (context, glow, child) => AnimatedContainer(
        duration: _islandDur(300),
        curve: Curves.easeOut,
        decoration: BoxDecoration(
          borderRadius: BorderRadius.circular(_kIslandH / 2),
          boxShadow: [
            BoxShadow(
              color: const Color(0xFFFFC450).withAlpha(glow ? 140 : 0),
              blurRadius: 16,
              spreadRadius: glow ? 1 : 0,
            ),
            BoxShadow(
              color: const Color(0xFFFFD66B).withAlpha(glow ? 115 : 0),
              spreadRadius: glow ? 3 : 0,
            ),
          ],
        ),
        child: child,
      ),
      child: _buildPeriodIsland(),
    );
  }

  String get _islandName =>
      _isCustomRange ? '区间' : _periodPillLabel(_period, _periodOffset);

  String get _islandRange =>
      _isCustomRange ? _customRangePillLabel() : _selectedRangeLabel;

  Duration _islandDur(int ms) => MediaQuery.disableAnimationsOf(context)
      ? Duration.zero
      : Duration(milliseconds: ms);

  Widget _buildIslandRangeLabel(String range) {
    return AnimatedSwitcher(
      duration: _islandDur(220),
      child: Text(
        range,
        key: ValueKey('island-range-$range'),
        maxLines: 1,
        softWrap: false,
        overflow: TextOverflow.ellipsis,
        style: _tabular(
          LhTypography.mono(
            size: 11.5,
            weight: FontWeight.w700,
            color: _kIslandInk,
            letterSpacing: 0.2,
            height: 1.0,
            context: context,
          ),
        ),
      ),
    );
  }

  Widget _buildPeriodIsland() {
    final name = _islandName;
    final range = _islandRange;
    return Builder(
      builder: (anchor) => Semantics(
        button: true,
        expanded: _periodSheetOpen,
        label: '切换周期，当前$name，$range',
        excludeSemantics: true,
        child: GestureDetector(
          behavior: HitTestBehavior.opaque,
          onTap: () => _openPeriodSheet(anchor),
          child: AnimatedScale(
            scale: _periodSheetOpen ? 0.96 : 1,
            duration: _islandDur(180),
            curve: Curves.easeOutCubic,
            child: Container(
              height: _kIslandH,
              padding: const EdgeInsets.fromLTRB(4, 4, 8, 4),
              decoration: dunesIslandDecoration(
                context,
                radius: _kIslandH / 2,
              ),
              child: LayoutBuilder(
                builder: (context, constraints) {
                  final bounded = constraints.maxWidth.isFinite;
                  final rangeLabel = _buildIslandRangeLabel(range);
                  return Row(
                mainAxisSize: MainAxisSize.min,
                children: [
                  // 切期时这颗字块从下往上翻过来（老的往下淡出）。
                  AnimatedSwitcher(
                    duration: _islandDur(280),
                    switchInCurve: Curves.easeOutBack,
                    switchOutCurve: Curves.easeInCubic,
                    transitionBuilder: (child, a) => FadeTransition(
                      opacity: a,
                      child: SlideTransition(
                        position: Tween<Offset>(
                          begin: const Offset(0, 0.45),
                          end: Offset.zero,
                        ).animate(a),
                        child: child,
                      ),
                    ),
                    layoutBuilder: (current, previous) => Stack(
                      alignment: Alignment.center,
                      children: [...previous, ?current],
                    ),
                    child: Container(
                      key: ValueKey('island-$name'),
                      height: _kIslandH - 8,
                      padding: const EdgeInsets.symmetric(horizontal: 12),
                      alignment: Alignment.center,
                      decoration: const BoxDecoration(
                        gradient: kDunesIslandPillGradient,
                        borderRadius: BorderRadius.all(
                          Radius.circular((_kIslandH - 8) / 2),
                        ),
                        boxShadow: kDunesIslandPillShadow,
                      ),
                      child: Text(
                        name,
                        maxLines: 1,
                        style: LhTypography.sans(
                          size: 13,
                          weight: FontWeight.w700,
                          color: Colors.white,
                          letterSpacing: 0.4,
                          height: 1.0,
                          context: context,
                        ),
                      ),
                    ),
                  ),
                  const SizedBox(width: 9),
                  if (bounded) Flexible(child: rangeLabel) else rangeLabel,
                  const SizedBox(width: 2),
                  AnimatedRotation(
                    turns: _periodSheetOpen ? 0.5 : 0,
                    duration: _islandDur(300),
                    curve: Curves.easeOutCubic,
                    child: const Icon(
                      Icons.keyboard_arrow_down_rounded,
                      size: 18,
                      color: _kIslandIcon,
                    ),
                  ),
                ],
              );
                },
              ),
            ),
          ),
        ),
      ),
    );
  }

  Widget _buildMoreIsland() {
    final busy = _isPageBusy || _refreshing || _loading;
    final zoomed = (_uiZoom - 1.0).abs() >= 0.001;
    return Builder(
      builder: (anchor) => Semantics(
        button: true,
        label: busy ? '更多，正在更新数据' : '更多',
        excludeSemantics: true,
        child: GestureDetector(
          behavior: HitTestBehavior.opaque,
          onTap: () => _openMoreMenu(anchor),
          child: Container(
            width: _kIslandH,
            height: _kIslandH,
            decoration: dunesIslandDecoration(context, radius: _kIslandH / 2),
            child: Stack(
              clipBehavior: Clip.none,
              alignment: Alignment.center,
              children: [
                AnimatedSwitcher(
                  duration: _islandDur(220),
                  child: busy
                      ? const KeyedSubtree(
                          key: ValueKey('more-busy'),
                          child: _LhBrandLoader(size: 16),
                        )
                      : const Icon(
                          Icons.more_horiz_rounded,
                          key: ValueKey('more-idle'),
                          size: 20,
                          color: _kIslandIcon,
                        ),
                ),
                if (zoomed)
                  Positioned(
                    top: 7,
                    right: 7,
                    child: Container(
                      width: 6,
                      height: 6,
                      decoration: const BoxDecoration(
                        shape: BoxShape.circle,
                        gradient: kDunesIslandPillGradient,
                      ),
                    ),
                  ),
              ],
            ),
          ),
        ),
      ),
    );
  }

  /// 浮岛在屏幕上的位置（缩放过的页面也对）。
  Rect? _islandRectOf(BuildContext anchor) {
    final box = anchor.findRenderObject();
    if (box is! RenderBox || !box.hasSize || !box.attached) return null;
    return Rect.fromPoints(
      box.localToGlobal(Offset.zero),
      box.localToGlobal(box.size.bottomRight(Offset.zero)),
    );
  }

  /// 从浮岛的位置弹出一张卡：淡紫遮罩 + 从岛那一点带回弹地放大出来。
  ///
  /// 收起要「一碰就走」：手指一按到卡片外面（不用等抬起、往下滑也算）就收，
  /// 收起动画 150ms，比展开快一倍 —— 跟 iOS 的菜单一样，退场不拖泥带水。
  /// 手机（窄于 600）上卡片左右各留 12 铺满，宽屏才贴着浮岛右对齐。
  Future<void> _showIslandPopover({
    required BuildContext anchor,
    required double maxWidth,
    required String barrierLabel,
    required Widget Function(BuildContext ctx, StateSetter setLocal) builder,
    bool fillOnPhone = false,
  }) async {
    final r = _islandRectOf(anchor);
    if (r == null) return;
    final screen = MediaQuery.sizeOf(context);
    final phone = screen.width < 600;
    final width = fillOnPhone && phone
        ? screen.width - 24
        : math.min(maxWidth, screen.width - 24);
    final left = (r.right - width)
        .clamp(12.0, math.max(12.0, screen.width - 12 - width))
        .toDouble();
    final top = r.bottom + 8;
    final ox = ((r.center.dx - left) / width).clamp(0.0, 1.0) * 2 - 1;
    final origin = Alignment(ox, -1);
    final reduce = MediaQuery.disableAnimationsOf(context);
    await Navigator.of(context, rootNavigator: true).push<void>(
      PageRouteBuilder<void>(
        opaque: false,
        barrierDismissible: false,
        transitionDuration: reduce
            ? Duration.zero
            : const Duration(milliseconds: 340),
        reverseTransitionDuration: reduce
            ? Duration.zero
            : const Duration(milliseconds: 150),
        pageBuilder: (ctx, a, _) => Semantics(
          scopesRoute: true,
          explicitChildNodes: true,
          child: Stack(
            children: [
              // 遮罩：按下即收（不等抬手），读屏可点「收起」。
              Positioned.fill(
                child: Semantics(
                  button: true,
                  label: barrierLabel,
                  onTap: () => _closeIslandPopover(ctx),
                  child: Listener(
                    behavior: HitTestBehavior.opaque,
                    onPointerDown: (_) => _closeIslandPopover(ctx),
                    child: FadeTransition(
                      opacity: CurvedAnimation(
                        parent: a,
                        curve: Curves.easeOut,
                        reverseCurve: Curves.easeIn,
                      ),
                      child: const ColoredBox(color: Color(0x242B2147)),
                    ),
                  ),
                ),
              ),
              Positioned(
                left: left,
                top: top,
                width: width,
                // 卡片自己吃掉点击，点卡片空白处不会误收。
                child: Listener(
                  behavior: HitTestBehavior.opaque,
                  child: FadeTransition(
                    opacity: CurvedAnimation(
                      parent: a,
                      curve: const Interval(0, 0.55, curve: Curves.easeOut),
                      reverseCurve: Curves.easeIn,
                    ),
                    child: ScaleTransition(
                      alignment: origin,
                      scale: Tween<double>(begin: 0.9, end: 1).animate(
                        CurvedAnimation(
                          parent: a,
                          curve: Curves.easeOutBack,
                          reverseCurve: Curves.easeInCubic,
                        ),
                      ),
                      child: Material(
                        type: MaterialType.transparency,
                        child: StatefulBuilder(builder: builder),
                      ),
                    ),
                  ),
                ),
              ),
            ],
          ),
        ),
      ),
    );
  }

  BoxDecoration _islandPanelDecoration({double radius = 24}) => BoxDecoration(
    color: DunesColors.resolve(
      context,
      Colors.white,
      role: DunesColorRole.surface,
    ),
    borderRadius: BorderRadius.circular(radius),
    border: Border.all(color: kDunesIslandEdge, width: 0.5),
    boxShadow: kDunesIslandPanelShadow,
  );

  void _closeIslandPopover(BuildContext ctx) {
    if (!ctx.mounted) return;
    if (ModalRoute.of(ctx)?.isCurrent ?? false) Navigator.of(ctx).pop();
  }

  // ── 周期面板 ──

  static const double _kIslandInstW = 78;

  Future<void> _openPeriodSheet(BuildContext anchor) async {
    if (_periodSheetOpen) return;
    LighthouseFeedback.instance.play(LighthouseFeedbackKind.select);
    setState(() {
      _periodSheetOpen = true;
      _periodPickerOpen = false;
    });
    // 往前翻那条：最新在最右，往左滑看更早；打开时让选中那期露在视野里。
    final scroll = ScrollController(
      initialScrollOffset: math.max(0, (-_periodOffset - 1) * _kIslandInstW),
    );
    try {
      await _showIslandPopover(
        anchor: anchor,
        maxWidth: 420,
        fillOnPhone: true,
        barrierLabel: '收起周期',
        builder: (ctx, setLocal) => _buildPeriodSheet(ctx, setLocal, scroll),
      );
    } finally {
      if (mounted) setState(() => _periodSheetOpen = false);
      // 弹窗 future 在收起动画开始时就返回了，列表还挂着这个 controller；
      // 等收起动画走完再释放。
      Future<void>.delayed(const Duration(milliseconds: 300), scroll.dispose);
    }
  }

  Widget _buildPeriodSheet(
    BuildContext ctx,
    StateSetter setLocal,
    ScrollController scroll,
  ) {
    void refresh() {
      if (ctx.mounted) setLocal(() {});
    }

    const grains = ['日', '周', '月', '季', '年', '区间'];
    final sel = _isCustomRange ? 5 : _kPeriodKeys.indexOf(_period);

    String sub(int i) {
      if (i == 5) return _isCustomRange ? _customRangePillLabel() : '自选起止';
      final k = _kPeriodKeys[i];
      return (!_isCustomRange && k == _period)
          ? _periodPillLabel(k, _periodOffset)
          : _periodPillLabel(k, 0);
    }

    void pickGrain(int i) {
      LighthouseFeedback.instance.play(LighthouseFeedbackKind.select);
      if (i == 5) {
        _closeIslandPopover(ctx);
        unawaited(_pickDateRange());
        return;
      }
      final k = _kPeriodKeys[i];
      if (_isCustomRange) {
        _clearCustomRange();
        if (k != _period) _applyPeriod(period: k, offset: 0);
      } else if (k != _period) {
        _applyPeriod(period: k, offset: 0);
      }
      if (scroll.hasClients) {
        scroll.animateTo(
          0,
          duration: _islandDur(320),
          curve: Curves.easeOutCubic,
        );
      }
      refresh();
    }

    void pickOffset(int off) {
      LighthouseFeedback.instance.play(LighthouseFeedbackKind.select);
      _applyPeriod(offset: off);
      refresh();
      // 留一下让人看到选中落在哪，再收起。
      Future<void>.delayed(
        _islandDur(180),
        () => _closeIslandPopover(ctx),
      );
    }

    Widget grain(int i) {
      final on = i == sel;
      return Expanded(
        child: Semantics(
          button: true,
          selected: on,
          label: '${grains[i]}，${sub(i)}',
          excludeSemantics: true,
          child: GestureDetector(
            behavior: HitTestBehavior.opaque,
            onTap: () => pickGrain(i),
            child: AnimatedContainer(
              duration: _islandDur(240),
              curve: Curves.easeOutCubic,
              height: 54,
              decoration: BoxDecoration(
                gradient: on ? kDunesIslandPillGradient : null,
                color: on
                    ? null
                    : DunesColors.resolve(
                        context,
                        const Color(0xFFF4F1FC),
                        role: DunesColorRole.surface,
                      ),
                borderRadius: BorderRadius.circular(15),
                boxShadow: on ? kDunesIslandPillShadow : const [],
              ),
              child: Column(
                mainAxisAlignment: MainAxisAlignment.center,
                children: [
                  Text(
                    grains[i],
                    style: LhTypography.sans(
                      size: 15,
                      weight: on ? FontWeight.w700 : FontWeight.w600,
                      color: on ? Colors.white : const Color(0xFF3A2A66),
                      height: 1.0,
                      context: context,
                    ),
                  ),
                  const SizedBox(height: 5),
                  Padding(
                    padding: const EdgeInsets.symmetric(horizontal: 6),
                    child: Text(
                      sub(i),
                      maxLines: 1,
                      softWrap: false,
                      overflow: TextOverflow.ellipsis,
                      style: LhTypography.mono(
                        size: 9.5,
                        weight: FontWeight.w600,
                        color: on
                            ? const Color(0xD9FFFFFF)
                            : const Color(0xFF8A80AE),
                        height: 1.0,
                        context: context,
                      ),
                    ),
                  ),
                ],
              ),
            ),
          ),
        ),
      );
    }

    Widget inst(int i) {
      final off = -i;
      final on = off == _periodOffset;
      return Semantics(
        button: true,
        selected: on,
        label: _periodInstanceLabel(_period, off),
        excludeSemantics: true,
        child: GestureDetector(
          behavior: HitTestBehavior.opaque,
          onTap: () => pickOffset(off),
          child: AnimatedContainer(
            duration: _islandDur(220),
            curve: Curves.easeOutCubic,
            constraints: const BoxConstraints(minWidth: _kIslandInstW - 4),
            margin: const EdgeInsets.symmetric(horizontal: 2),
            padding: const EdgeInsets.symmetric(horizontal: 10),
            alignment: Alignment.center,
            decoration: BoxDecoration(
              color: on
                  ? DunesColors.resolve(
                      context,
                      Colors.white,
                      role: DunesColorRole.surface,
                    )
                  : Colors.transparent,
              borderRadius: BorderRadius.circular(12),
              border: Border.all(
                color: on ? const Color(0x2E7B5CD8) : Colors.transparent,
                width: 0.6,
              ),
              boxShadow: on
                  ? const [
                      BoxShadow(
                        color: Color(0x2E4A3A7A),
                        blurRadius: 8,
                        spreadRadius: -2,
                        offset: Offset(0, 2),
                      ),
                    ]
                  : const [],
            ),
            child: Column(
              mainAxisAlignment: MainAxisAlignment.center,
              children: [
                Text(
                  _periodInstanceLabel(_period, off),
                  maxLines: 1,
                  style: LhTypography.sans(
                    size: 12.5,
                    weight: on ? FontWeight.w700 : FontWeight.w500,
                    color: on ? _kIslandInkStrong : _kIslandMute,
                    height: 1.0,
                    context: context,
                  ),
                ),
                const SizedBox(height: 4),
                Text(
                  _islandInstDetail(_period, off),
                  maxLines: 1,
                  style: _tabular(
                    LhTypography.mono(
                      size: 8.5,
                      weight: FontWeight.w600,
                      color: on
                          ? const Color(0xFF6A4FC9)
                          : const Color(0xFF9A92BA),
                      height: 1.0,
                      context: context,
                    ),
                  ),
                ),
              ],
            ),
          ),
        ),
      );
    }

    Widget label(String text) => Text(
      text,
      style: LhTypography.sans(
        size: 12,
        weight: FontWeight.w600,
        color: _kIslandMute,
        height: 1.0,
        context: context,
      ),
    );

    Widget chip(String text, VoidCallback onTap) => GestureDetector(
      behavior: HitTestBehavior.opaque,
      onTap: onTap,
      child: Container(
        padding: const EdgeInsets.symmetric(horizontal: 9, vertical: 5),
        decoration: BoxDecoration(
          color: const Color(0x147B5CD8),
          borderRadius: BorderRadius.circular(10),
        ),
        child: Text(
          text,
          style: LhTypography.sans(
            size: 11,
            weight: FontWeight.w700,
            color: const Color(0xFF6A4FC9),
            height: 1.0,
            context: context,
          ),
        ),
      ),
    );

    final count = _periodInstanceCount(_period);
    return Container(
      padding: const EdgeInsets.fromLTRB(14, 16, 14, 14),
      decoration: _islandPanelDecoration(),
      child: Column(
        mainAxisSize: MainAxisSize.min,
        crossAxisAlignment: CrossAxisAlignment.stretch,
        children: [
          Row(
            children: [
              label('看哪个周期'),
              const SizedBox(width: 12),
              Expanded(
                child: Text(
                  _islandRange,
                  maxLines: 1,
                  overflow: TextOverflow.ellipsis,
                  textAlign: TextAlign.right,
                  style: _tabular(
                    LhTypography.mono(
                      size: 11,
                      weight: FontWeight.w700,
                      color: _kIslandInk,
                      height: 1.0,
                      context: context,
                    ),
                  ),
                ),
              ),
            ],
          ),
          const SizedBox(height: 12),
          Row(
            children: [
              grain(0),
              const SizedBox(width: 8),
              grain(1),
              const SizedBox(width: 8),
              grain(2),
            ],
          ),
          const SizedBox(height: 8),
          Row(
            children: [
              grain(3),
              const SizedBox(width: 8),
              grain(4),
              const SizedBox(width: 8),
              grain(5),
            ],
          ),
          if (_isCustomRange) ...[
            const SizedBox(height: 16),
            Row(
              children: [
                label('当前区间'),
                const SizedBox(width: 8),
                Expanded(
                  child: Text(
                    _customRangePillLabel(),
                    maxLines: 1,
                    overflow: TextOverflow.ellipsis,
                    style: _tabular(
                      LhTypography.mono(
                        size: 11.5,
                        weight: FontWeight.w700,
                        color: _kIslandInkStrong,
                        height: 1.0,
                        context: context,
                      ),
                    ),
                  ),
                ),
                chip('换一段', () {
                  _closeIslandPopover(ctx);
                  unawaited(_pickDateRange());
                }),
                const SizedBox(width: 6),
                chip('清除', () {
                  LighthouseFeedback.instance.play(
                    LighthouseFeedbackKind.select,
                  );
                  _clearCustomRange();
                  refresh();
                }),
              ],
            ),
          ] else ...[
            const SizedBox(height: 16),
            Row(
              children: [
                label('往前翻'),
                const SizedBox(width: 6),
                const Icon(
                  Icons.west_rounded,
                  size: 12,
                  color: Color(0xFFB0A8CC),
                ),
                const Spacer(),
                if (_periodOffset != 0)
                  chip('回到${_periodPillLabel(_period, 0)}', () {
                    pickOffset(0);
                  }),
              ],
            ),
            const SizedBox(height: 8),
            Container(
              height: 50,
              padding: const EdgeInsets.all(4),
              decoration: BoxDecoration(
                color: const Color(0x0F7B5CD8),
                borderRadius: BorderRadius.circular(16),
              ),
              // 左边缘渐隐：提示往左还有更早的。
              child: ShaderMask(
                blendMode: BlendMode.dstIn,
                shaderCallback: (b) => const LinearGradient(
                  colors: [Color(0x00000000), Color(0xFF000000)],
                  stops: [0.0, 0.1],
                ).createShader(b),
                child: ListView.builder(
                  controller: scroll,
                  reverse: true,
                  scrollDirection: Axis.horizontal,
