  /// 日 / 周 / 月 / 季 / 年 钉在列表上方：往下滑看账本时它不走，随时能切时间段。
  Widget _buildPinnedPeriodBar() {
    // 方案 E：周期收进顶栏的浮岛（一级顶栏、二级 / 三级 / 四级吸顶头都有），
    // 不再单独占一行。
    if (lighthouseTopBandDark) return const SizedBox.shrink();
    // ignore: dead_code
    if (lighthouseTopBandDark) {
      return LayoutBuilder(
        builder: (context, c) {
          // 一级宽屏：期间条已经并进顶栏那一行。
          if (_lhBandHoldsPeriod(c.maxWidth)) return const SizedBox.shrink();
          return _lhBand(
            shadow: true,
            padding: const EdgeInsets.fromLTRB(
              lighthouseHeroShellMarginH,
              0,
              lighthouseHeroShellMarginH,
              12,
            ),
            child: _buildPeriodBar(onDark: true),
          );
        },
      );
    }
    return Container(
      padding: const EdgeInsets.fromLTRB(
        lighthouseHeroShellMarginH,
        lighthousePeriodGapAbove,
        lighthouseHeroShellMarginH,
        8,
      ),
      color: DunesColors.resolve(
        context,
        lighthouseMainPageBg,
        role: DunesColorRole.surface,
      ),
      child: _buildPeriodBar(),
    );
  }

  Widget _buildMainList() {
    return RefreshIndicator.noSpinner(
      key: const ValueKey('lighthouse-pull-refresh'),
      onRefresh: _refresh,
      child: NotificationListener<ScrollNotification>(
        onNotification: (n) {
          if (n.metrics.axis == Axis.vertical && n.depth == 0) {
            _updateLedgerTabsStuck();
          }
          if (_ddMode != _DdMode.none && n is ScrollStartNotification) {
            _closeDropdown();
          }
          // 产品 / 供给 / 渠道：接近底部（或内容撑不满一屏）自动加载更多
          if (n is ScrollUpdateNotification ||
              n is OverscrollNotification ||
              n is ScrollEndNotification) {
            final m = n.metrics;
            final nearBottom = m.pixels >= m.maxScrollExtent - 200;
            final cantScrollYet =
                m.maxScrollExtent <= 40 && _listLimit < _currentRows.length;
            if (nearBottom || cantScrollYet) {
              _maybeLoadMoreL1();
            }
          }
          return false;
        },
        child: ListView(
          controller: _mainListScrollCtrl,
          physics: const AlwaysScrollableScrollPhysics(),
          padding: EdgeInsets.only(bottom: _bottomNavScrollPadding(context)),
          children: [
            _buildPanel(),
            if (_tab == 'analysis') _buildAnalysisView(),
            if (_tab == 'supply' && lighthouseLedgerShowsDiscountBoard)
              _buildDiscountSection(),
            _buildFooter(),
          ],
        ),
      ),
    );
  }

  /// 浏览器式界面缩放：按比例放大/缩小整页内容，默认 100%。
  Widget _wrapWithUiZoom(Widget child) {
    return LayoutBuilder(
      builder: (context, constraints) {
        final zoom = _uiZoom.clamp(0.5, 2.0);
        if ((zoom - 1.0).abs() < 0.001) return child;
        final w = constraints.maxWidth;
        final h = constraints.maxHeight;
        return ClipRect(
          child: Align(
            alignment: Alignment.topLeft,
            child: OverflowBox(
              alignment: Alignment.topLeft,
              minWidth: w / zoom,
              maxWidth: w / zoom,
              minHeight: h / zoom,
              maxHeight: h / zoom,
              child: Transform.scale(
                scale: zoom,
                alignment: Alignment.topLeft,
                child: SizedBox(
                  width: w / zoom,
                  height: h / zoom,
                  child: child,
                ),
              ),
            ),
          ),
        );
      },
    );
  }

  void _nudgeUiZoom(int dir) {
    final idx = _kUiZoomOptions.indexWhere((z) => (z - _uiZoom).abs() < 0.001);
    int cur;
    if (idx >= 0) {
      cur = idx;
    } else {
      final ge = _kUiZoomOptions.indexWhere((z) => z >= _uiZoom);
      cur = ge < 0 ? _kUiZoomOptions.length - 1 : ge;
    }
    final next = (cur + dir).clamp(0, _kUiZoomOptions.length - 1);
    final v = _kUiZoomOptions[next];
    if ((v - _uiZoom).abs() < 0.001) return;
    setState(() => _uiZoom = v);
    unawaited(_persistUiZoom());
  }

  /// 右上角工具条：界面缩放 + 更新数据。
  ///
  /// 旧版是一整块白纸盒子 + 灰描边 + 投影，里面塞「🔍− 100% 🔍+ │ ⟳」
  /// 四个等重的饱和紫字形：
  ///   · 放大镜读起来像「搜索」，不像「缩放」
  ///   · 四个紫字形比左边「灯塔」标题还重，顶栏重心被拽到右上角
  ///   · 白纸 + 米灰边是另一套材质，跟下面的期间条 / Hero 雾紫壳不是一家
  ///   · 低频的「缩放设置」和高频的「刷新」挤在一个盒子里，谁都不突出
  ///
  /// 这版：
  ///   · 拆成两件 —— 缩放步进胶囊 + 独立圆形刷新钮，中间留 6 的气口
  ///   · 材质直接借期间条：雾紫轨道 + 轻紫边，不再有白盒投影
  ///   · 字形换成细 − / +，走低饱和的 plum ink；主紫只留给「非 100%」状态
  ///   · 100% 时读数退成灰 mono（默认态不该吵）；缩放过后读数变成白紫小胶囊
  ///     （= 期间条选中态），一眼看出「动过了」，点它回 100%
  Widget _buildAppBarToolbar({bool onDark = false}) {
    return Row(
      mainAxisSize: MainAxisSize.min,
      children: [
        _buildUiZoomButton(onDark: onDark),
        const SizedBox(width: 6),
        _buildAppBarRefreshButton(onDark: onDark),
        const SizedBox(width: 6),
        IconButton(
          tooltip: '触感与声音',
          constraints: const BoxConstraints(minWidth: 32, minHeight: 32),
          padding: EdgeInsets.zero,
          icon: Icon(
            Icons.volume_up_outlined,
            size: 17,
            color: onDark
                ? _kLhBandInk
                : DunesColors.resolve(context, _LhPlum.primary),
          ),
          onPressed: () => LighthouseFeedback.instance.showSettings(context),
        ),
      ],
    );
  }

  /// 顶栏工具的共用壳：期间条同款凹槽（v24 跟着期间条换成淡紫底 + Hero 卡紫发丝边）。
  BoxDecoration _appBarToolShell({
    required double radius,
    bool onDark = false,
  }) {
    if (onDark) {
      return BoxDecoration(
        color: const Color(0x127B5CD8),
        borderRadius: BorderRadius.circular(radius),
        border: Border.all(color: _kLhBandEdge, width: 0.6),
      );
    }
    return BoxDecoration(
      color: DunesColors.resolve(
        context,
        const Color(0xFFF3EFFA),
        role: DunesColorRole.surface,
      ),
      borderRadius: BorderRadius.circular(radius),
      border: Border.all(
        color: DunesColors.resolve(
          context,
          _LhPlum.line,
          role: DunesColorRole.border,
        ),
        width: 0.8,
      ),
    );
  }

  /// 右上角缩放：缩小 / 读数（点击恢复 100%）/ 放大。
  Widget _buildUiZoomButton({bool onDark = false}) {
    final pct = (_uiZoom * 100).round();
    final atMin = (_uiZoom - _kUiZoomOptions.first).abs() < 0.001;
    final atMax = (_uiZoom - _kUiZoomOptions.last).abs() < 0.001;
    final atDefault = (_uiZoom - 1.0).abs() < 0.001;
    const h = lighthouseAppBarToolbarHeight;
    const r = lighthouseAppBarToolbarRadius;

    Widget step({
      required IconData icon,
      required String tooltip,
      required bool enabled,
      required VoidCallback onTap,
    }) {
      return Tooltip(
        message: tooltip,
        waitDuration: const Duration(milliseconds: 400),
        child: GestureDetector(
          behavior: HitTestBehavior.opaque,
          onTap: enabled
              ? () {
                  LighthouseFeedback.instance.play(
                    LighthouseFeedbackKind.select,
                  );
                  onTap();
                }
              : null,
          child: SizedBox(
            width: 28,
            height: h,
            child: Icon(
              icon,
              size: 15,
              color: enabled
                  ? (onDark
                        ? _kLhBandInkStrong
                        : DunesColors.resolve(context, _LhPlum.ink))
                  : (onDark
                        ? _kLhBandInk.withAlpha(90)
                        : DunesColors.resolve(
                            context,
                            _LhPlum.soft,
                          ).withAlpha(150)),
            ),
          ),
        ),
      );
    }

    final readout = AnimatedContainer(
      duration: const Duration(milliseconds: lighthousePeriodAnimationMs),
      curve: Curves.easeOutCubic,
      height: h - 8,
      constraints: const BoxConstraints(minWidth: 38),
      padding: const EdgeInsets.symmetric(horizontal: 6),
      alignment: Alignment.center,
      decoration: BoxDecoration(
        color: atDefault
            ? DunesColors.resolve(
                context,
                _LhPlum.heroFill,
                role: DunesColorRole.surface,
              ).withAlpha(0)
            : DunesColors.resolve(
                context,
                Colors.white,
                role: DunesColorRole.surface,
              ),
        borderRadius: BorderRadius.circular(r - 4),
        border: Border.all(
          color: atDefault
              ? DunesColors.resolve(
                  context,
                  _LhPlum.line,
                  role: DunesColorRole.border,
                ).withAlpha(0)
              : DunesColors.resolve(
                  context,
                  _LhPlum.line,
                  role: DunesColorRole.border,
                ),
          width: 0.8,
        ),
        boxShadow: atDefault
            ? const <BoxShadow>[]
            : [
                BoxShadow(
                  color: _LhPlum.deep.withAlpha(22),
                  blurRadius: 5,
                  spreadRadius: -1,
                  offset: const Offset(0, 1.5),
                ),
              ],
      ),
      child: Text(
        '$pct%',
        style: LhTypography.mono(
          size: 10.5,
          color: atDefault
              ? (onDark
                    ? _kLhBandInk
                    : DunesColors.resolve(context, LhColors.mute2))
              : DunesColors.resolve(context, _LhPlum.heroNum),
          weight: atDefault ? FontWeight.w600 : FontWeight.w700,
          letterSpacing: 0.2,
          height: 1.0,
          context: context,
        ),
      ),
    );

    return Container(
      height: h,
      decoration: _appBarToolShell(radius: r, onDark: onDark),
      child: Row(
        mainAxisSize: MainAxisSize.min,
        children: [
          step(
            icon: Icons.remove_rounded,
            tooltip: '缩小',
            enabled: !atMin,
            onTap: () => _nudgeUiZoom(-1),
          ),
          Tooltip(
            message: atDefault ? '实际大小' : '恢复实际大小',
            waitDuration: const Duration(milliseconds: 400),
            child: GestureDetector(
              behavior: HitTestBehavior.opaque,
              onTap: atDefault
                  ? null
                  : () {
                      LighthouseFeedback.instance.play(
                        LighthouseFeedbackKind.select,
                      );
                      setState(() => _uiZoom = 1.0);
                      unawaited(_persistUiZoom());
                    },
              child: readout,
            ),
          ),
          step(
            icon: Icons.add_rounded,
            tooltip: '放大全部',
            enabled: !atMax,
            onTap: () => _nudgeUiZoom(1),
          ),
        ],
      ),
    );
  }

  Widget _buildAppBarRefreshButton({bool onDark = false}) {
    final busy = _isPageBusy || _refreshing || _loading;
    const h = lighthouseAppBarToolbarHeight;
    return Tooltip(
      message: busy ? '正在更新…' : '更新数据',
      waitDuration: const Duration(milliseconds: 400),
      child: GestureDetector(
        behavior: HitTestBehavior.opaque,
        onTap: busy
            ? null
            : () {
                LighthouseFeedback.instance.play(
                  LighthouseFeedbackKind.navigate,
                );
                unawaited(_refresh());
              },
        child: Container(
          width: h,
          height: h,
          decoration: _appBarToolShell(radius: h / 2, onDark: onDark),
          child: Center(
            child: busy
                ? const _LhBrandLoader(size: 14)
                : Icon(
                    Icons.refresh_rounded,
                    size: 16,
                    color: onDark
                        ? _kLhBandInkStrong
                        : DunesColors.resolve(context, _LhPlum.ink),
                  ),
          ),
        ),
      ),
    );
  }

  // ───── Greeting ───────────────────────────────────────────────────────────
  // v2 淡紫改造：日期用 mono 加强编辑体节奏；pill 保留状态指示但去掉冗余
  // refresh icon（刷新入口已挪至 AppBar 右侧胶囊按钮）。
  Widget _buildGreeting() {
    return Padding(
      padding: const EdgeInsets.fromLTRB(
        lighthouseHeroShellMarginH,
        4,
        lighthouseHeroShellMarginH,
        10,
      ),
      child: Row(
        crossAxisAlignment: CrossAxisAlignment.center,
        children: [
          Text(
            _formatDateLabel(),
            style: LhTypography.mono(
              size: 10.5,
              color: DunesColors.resolve(context, LhColors.mute),
              weight: FontWeight.w500,
              letterSpacing: 0.6,
              context: context,
            ),
          ),
          const Spacer(),
          _buildPill(),
        ],
      ),
    );
  }

  /// 顶栏同步态胶囊。
  ///
  /// 旧版是一块淡绿底 + 淡绿描边 + 「已同步 · 2026.09.08 18:04」：
  /// 整块面被涂成绿的，绿点淹在同色底里失去意义；一长串年月日时分又把
  /// 胶囊撑得比 logo 还宽，顶栏最不重要的信息占了最大的面积。
  ///
  /// 这版换个说法：
  ///   · 面回到中性（纸白 + 发丝描边），颜色只留给那颗脉冲绿点 ——
  ///     状态由「灯」表达，不是把整块牌子刷成绿的
  ///   · 文案拆成「已同步 │ 18:04」：状态词用 sans，时刻用 mono，
  ///     中间一道细分隔 —— 两种信息各归各位，扫一眼就分得开
  ///   · 时刻当天只给时分，跨天才补月日（见 lighthouseSyncedAtCompact）
  Widget _buildPill() {
    final busy = _refreshing || _loading;
    return Container(
      height: 22,
      padding: const EdgeInsets.symmetric(horizontal: 8),
      decoration: BoxDecoration(
        color: DunesColors.resolve(
          context,
          LhColors.paper,
          role: DunesColorRole.surface,
        ),
        borderRadius: BorderRadius.circular(999),
        border: Border.all(
          color: DunesColors.resolve(
            context,
            LhColors.line2,
            role: DunesColorRole.border,
          ),
          width: 0.7,
        ),
        boxShadow: [
          BoxShadow(
            color: Colors.black.withAlpha(6),
            blurRadius: 4,
            offset: const Offset(0, 1),
          ),
        ],
      ),
      child: Row(
        mainAxisSize: MainAxisSize.min,
        children: [
          if (busy)
            const _LhBrandLoader(size: 9)
          else
            _LhPulseDot(
              color: DunesColors.resolve(context, LhColors.pos),
              size: 5,
            ),
          const SizedBox(width: 6),
          Text(
            busy ? '同步中' : '已同步',
            style: LhTypography.sans(
              size: 9.5,
              color: DunesColors.resolve(context, LhColors.ink2),
              weight: FontWeight.w600,
              letterSpacing: 0.2,
              height: 1.0,
              context: context,
            ),
          ),
          if (!busy) ...[
            const SizedBox(width: 6),
            Container(
              width: 0.7,
              height: 9,
              color: DunesColors.resolve(
                context,
                LhColors.line2,
                role: DunesColorRole.surface,
              ),
            ),
            const SizedBox(width: 6),
            Text(
              _syncedAtLabelCompact(),
              style: LhTypography.mono(
                size: 9.5,
                color: DunesColors.resolve(context, LhColors.mute),
                weight: FontWeight.w600,
                letterSpacing: 0.3,
                height: 1.0,
                context: context,
              ),
            ),
          ],
        ],
      ),
    );
  }

  // ═══════════════════════════════════════════════════════════════════════
  // AI 解读 · 取数
  // ═══════════════════════════════════════════════════════════════════════

  /// 上下文指纹 —— 必须和列表接口的查询参数一一对应。
  /// 少放一项，就会出现「AI 说的和列表显示的对不上」，那比没有 AI 更糟。
  /// 不用 `_currentRows.length`：二次刷新行数微变会导致「生成完成时 key 已变 →
  /// 结果被丢弃 → 又没有下一轮调度」，看起来就像必须手动点刷新。
  String get _aiContextKey {
    final range = _isCustomRange
        ? '${_customStart!.toIso8601String()}~${_customEnd!.toIso8601String()}'
        : '$_period@$_periodOffset';
    return [
      _tab,
      range,
      _anchor.name,
      _groupFilter,
      _hunFilter,
      _anomalyFilter,
    ].join('|');
  }

  /// 期间 / 筛选切换时立刻作废，避免旧结论挂在新上下文标题下。
  void _invalidateAiSummary({bool clearContent = true}) {
    _aiLoadedKey = null;
    _aiInflightKey = null;
    _aiFailed = false;
    _aiSummaryId = null;
    _aiFactsHash = null;
    _aiVote = 0;
    _aiExpanded = false;
    if (clearContent) {
      _aiSummary = null;
      _aiLoading = false;
    }
  }

  /// build 里调用，只负责「该不该发起一次生成」，不做 setState。
  void _ensureAiSummary() {
    // AI 是补充信息；当前可见列表尚未返回时先让出网络与后端查询资源。
    if (_isPageBusy || _loadingTabs.contains(_activeListTab)) return;
    final key = _aiContextKey;
    if (_aiInflightKey == key) return;
    if (_aiLoadedKey == key) return;
    _aiInflightKey = key;
    WidgetsBinding.instance.addPostFrameCallback((_) {
      if (!mounted) return;
      // 帧间上下文可能又变了，交还给 ensure 重新判断。
      if (_aiContextKey != key) {
        if (_aiInflightKey == key) _aiInflightKey = null;
        _ensureAiSummary();
        return;
      }
      _loadAiSummary(key);
    });
  }

  Future<void> _loadAiSummary(String key) async {
    if (!mounted) return;
    setState(() {
      _aiLoading = true;
      _aiFailed = false;
      // 换上下文时先清空旧结论，避免「标题已是本周、正文仍是本月」。
      if (_aiLoadedKey != key) _aiSummary = null;
    });
    try {
      _LhAiSummary result;
      String? summaryId;
      String? factsHash;
      try {
        final data = await _service.fetchAiSummary(
          tab: _tab,
          period: _period,
          offset: _periodOffset,
          startDate: _isCustomRange ? _customStart : null,
          endDate: _isCustomRange ? _customEnd : null,
          group: _groupFilter,
          anchor: _anchor == _LhAnchor.verified ? 'verified' : 'sales',
          hun: _hunFilter,
          anomaly: _anomalyFilter,
        );
        result = _aiSummaryFromApi(data);
        summaryId = data['summary_id']?.toString();
        factsHash = data['facts_hash']?.toString();
      } catch (_) {
        // 网络/后端失败时保留本地规则引擎，保证卡片永远有内容。
        result = _buildLocalAiSummary();
      }
      if (!mounted) return;
      if (_aiContextKey != key) {
        // 结果过期：清 inflight 后立刻为当前上下文再排一次。
        if (_aiInflightKey == key) _aiInflightKey = null;
        WidgetsBinding.instance.addPostFrameCallback((_) {
          if (mounted) _ensureAiSummary();
        });
        return;
      }
      setState(() {
        _aiSummary = result;
        _aiSummaryId = summaryId;
        _aiFactsHash = factsHash;
        _aiLoadedKey = key;
        _aiLoading = false;
        _aiExpanded = false;
        _aiVote = 0;
      });
    } catch (_) {
      if (!mounted) return;
      if (_aiContextKey != key) {
        if (_aiInflightKey == key) _aiInflightKey = null;
        WidgetsBinding.instance.addPostFrameCallback((_) {
          if (mounted) _ensureAiSummary();
        });
        return;
      }
      setState(() {
        _aiLoading = false;
        _aiFailed = true;
        // 失败也认领这个 key，否则 build → 重试 → 失败会转成死循环。
        // 重试只走刷新按钮。
        _aiLoadedKey = key;
      });
    } finally {
      if (_aiInflightKey == key) _aiInflightKey = null;
    }
  }

  _LhAiSummary _aiSummaryFromApi(Map<String, dynamic> data) {
    final rawItems = data['items'];
    final items = <_LhAiInsight>[];
    if (rawItems is List) {
      for (final raw in rawItems) {
        if (raw is! Map) continue;
        final m = Map<String, dynamic>.from(raw);
        final type = m['type']?.toString() ?? '';
        final severity = m['severity']?.toString() ?? '';
        final text = m['text']?.toString() ?? '';
        final evidence = <_LhAiEvidence>[];
        final ev = m['evidence'];
        if (ev is List) {
          for (final e in ev) {
            if (e is! Map) continue;
            final em = Map<String, dynamic>.from(e);
            final metric = em['metric']?.toString() ?? '';
            final value = (em['value'] as num?)?.toDouble() ?? 0;
            evidence.add(
              _LhAiEvidence(_aiMetricLabel(metric), _fmtAmountWithUnit(value)),
            );
          }
        }
        items.add(
          _LhAiInsight(
            tone: _aiToneFromApi(type, severity),
            spans: _aiSpansFromText(text),
            evidence: evidence,
            drill: _aiDrillFromApi(m['drill']),
          ),
        );
      }
    }
    DateTime generatedAt = DateTime.now();
    final ga = data['generated_at']?.toString();
    if (ga != null && ga.isNotEmpty) {
      generatedAt = DateTime.tryParse(ga) ?? generatedAt;
    }
    return _LhAiSummary(
      items: items.isEmpty ? _buildLocalAiSummary().items : items,
      generatedAt: generatedAt,
      degraded: data['degraded'] == true,
    );
  }

  _LhAiTone _aiToneFromApi(String type, String severity) {
    switch (type) {
      case 'risk':
        return _LhAiTone.risk;
      case 'opportunity':
        return _LhAiTone.opportunity;
      case 'anomaly':
      case 'quality':
        return _LhAiTone.watch;
      case 'structure':
        return _LhAiTone.neutral;
      default:
        switch (severity) {
          case 'high':
            return _LhAiTone.risk;
          case 'mid':
            return _LhAiTone.watch;
          default:
            return _LhAiTone.neutral;
        }
    }
  }

  String _aiMetricLabel(String metric) {
    switch (metric) {
      case 'revenue':
        return '收入';
      case 'totalCost':
      case 'costTotal':
        return '成本合计';
      case 'businessCost':
      case 'cost':
        return '业务成本';
      case 'projectCost':
        return '项目成本';
      case 'profit':
        return '利润';
      case 'netProfit':
        return '净利';
      case 'expectedNet':
        return '恒等式期望';
      default:
        return metric;
    }
  }

  List<({String text, Color? color})> _aiSpansFromText(String text) {
    final re = RegExp(r'\{(\w+)\}');
    final out = <({String text, Color? color})>[];
    var start = 0;
    for (final m in re.allMatches(text)) {
      if (m.start > start) {
        out.add((text: text.substring(start, m.start), color: null));
      }
      final key = m.group(1) ?? '';
      final label = _aiMetricLabel(key);
      final accent = _LhPnl.accentFor(key);
      out.add((
        text: label,
        color: accent?.bar ?? DunesColors.resolve(context, LhColors.copper),
      ));
      start = m.end;
    }
    if (start < text.length) {
      out.add((text: text.substring(start), color: null));
    }
    if (out.isEmpty) {
      out.add((text: text, color: null));
    }
    return out;
  }

  VoidCallback? _aiDrillFromApi(dynamic raw) {
    if (raw is! Map) return null;
    final drill = Map<String, dynamic>.from(raw);
    final level = drill['level']?.toString() ?? '';
    if (level == 'metric') {
      final metricKey = drill['metric_key']?.toString() ?? '';
      if (metricKey.isEmpty) return null;
      return () => setState(() => _expandedTrendKey = metricKey);
    }
    if (level == 'entity') {
      final id = drill['entity_id']?.toString() ?? '';
      final name = drill['entity_name']?.toString() ?? '';
      return () {
        if (id.contains('::')) {
          final parts = id.split('::');
          _openAiRowDrill({
            'name': parts.first,
            'group': parts.length > 1 ? parts.sublist(1).join('::') : '',
          });
          return;
        }
        _openAiRowDrill({'name': name.isNotEmpty ? name : id, 'group': ''});
      };
    }
    return null;
  }

  Future<void> _submitAiVote(int vote) async {
    final next = _aiVote == vote ? 0 : vote;
    setState(() => _aiVote = next);
    final id = _aiSummaryId;
    if (id == null || id.isEmpty) return;
    try {
      await _service.submitAiSummaryFeedback(
        summaryId: id,
        itemIndex: 0,
        vote: next,
        factsHash: _aiFactsHash,
      );
    } catch (_) {
      // 反馈失败不回滚 UI，避免打扰阅读。
    }
  }

  void _retryAiSummary() {
    setState(() {
      _invalidateAiSummary(clearContent: true);
      _aiFailed = false;
    });
  }

  /// 从 AI 结论跳到某一行的二级页。复用列表行的 openDefaultDetail 口径，
  /// key 拼法必须一致，否则跳过去是空页。
  void _openAiRowDrill(Map<String, dynamic> row) {
    final name = row['name']?.toString().trim() ?? '';
    if (name.isEmpty) return;
    final group = row['group']?.toString() ?? '';
    _captureMainListScroll();
    final detKey = _tab == 'people' || group.isEmpty ? name : '$name::$group';
    unawaited(_loadDetail(_tab, detKey));
    setState(() {
      _closeMetricPage();
      _detailReturnStack.clear();
      _detailKey = detKey;
      _detailType = _tab;
      _detailSubTab = '';
      _detailPage = 1;
      _heroPointIndex = null;
      _resetDetailSkuSearch();
      _resetDetailDrill();
      _detailDrillReloadAttempted = false;
    });
  }

  /// AI 解读跟随日周月季年：当前窗口用语。
  String _aiPeriodThisWord() {
    if (_isCustomRange) return '本区间';
    switch (_period) {
      case 'day':
        return '本日';
      case 'week':
        return '本周';
      case 'month':
        return '本月';
      case 'quarter':
        return '本季';
      case 'year':
        return '本年';
      default:
        return '本期';
    }
  }

  // ═══════════════════════════════════════════════════════════════════════
  // AI 解读 · 本地规则引擎
  //
  //   这一段做的正是后端「事实层」该做的事：确定性地算出该说什么。
  //   接了 LLM 之后它不删，改成降级路径 —— 模型超时、回校失败时兜底，
  //   保证这张卡永远有内容。它夹在 hero 和列表中间，空一块比没有更难看。
  // ═══════════════════════════════════════════════════════════════════════
  _LhAiSummary _buildLocalAiSummary() {
    final rows = _currentRows;
    double revenue = 0,
        totalCost = 0,
        netProfit = 0,
        profit = 0,
        businessCost = 0,
        projectCost = 0;
    for (final r in rows) {
      revenue += (r['revenue'] as num?)?.toDouble() ?? 0;
      totalCost += _rowCostTotal(r);
      netProfit += (r['netProfit'] as num?)?.toDouble() ?? 0;
      profit += (r['profit'] as num?)?.toDouble() ?? 0;
      businessCost += (r['cost'] as num?)?.toDouble() ?? 0;
      projectCost += (r['projectCost'] as num?)?.toDouble() ?? 0;
    }

    final dNet = _deltaForMetric('netProfit');
    final dRev = _deltaForMetric('revenue');
    final dCost = _deltaForMetric('totalCost');
    final items = <_LhAiInsight>[];

    String pct(double v) => v.abs().toStringAsFixed(1);
    final thisWord = _aiPeriodThisWord();
    final deltaWord = _period == 'year' ? '同比' : '环比';
    final vs = _periodVsLabel;

    // ── 规则 1 · 恒等式缺口：净利跌但收入涨 → 问题一定在成本 ──────────
    if (dNet != null && dRev != null && dCost != null) {
      final outpace = dCost.pct.abs() - dRev.pct.abs();
      if (!dNet.isUp && dRev.isUp && dCost.isUp && outpace > 0.5) {
        items.add(
          _LhAiInsight(
            tone: _LhAiTone.watch,
            spans: [
              (text: '净利润$deltaWord ', color: null),
              (
                text: '↓${pct(dNet.pct)}%',
                color: DunesColors.resolve(context, _LhPnl.netNum),
              ),
              (text: '（$vs），但 ', color: null),
              (
                text: '收入',
                color: DunesColors.resolve(context, _LhPnl.revenueBar),
              ),
              (text: ' 是涨的 —— 缺口在 ', color: null),
              (
                text: '成本合计',
                color: DunesColors.resolve(context, _LhPnl.costBar),
              ),
              (text: '，$deltaWord ', color: null),
              (
                text: '+${pct(dCost.pct)}%',
                color: DunesColors.resolve(context, _LhPnl.costNum),
              ),
              (text: '，跑赢收入 ${pct(outpace)}pp。', color: null),
            ],
            evidence: [
              _LhAiEvidence('业务成本', _fmtAmountWithUnit(businessCost)),
              _LhAiEvidence('项目成本', _fmtAmountWithUnit(projectCost)),
            ],
            drill: () => setState(() => _expandedTrendKey = 'totalCost'),
          ),
        );
      }
    }

    // ── 规则 2 · 低效实体：ROI 低于均值 × 成本占比高，两者相乘才是「值得管」 ──
    //   只看 ROI 低会揪出一堆金额可忽略的小行；只看成本高会揪出正常的大户。
    if (rows.isNotEmpty && totalCost >= _kRoiAnchorMinYuan) {
      final avgRoi = profit / totalCost * 100;
      Map<String, dynamic>? worst;
      double worstScore = 0, worstRoi = 0, worstShare = 0, worstCost = 0;
      for (final r in rows) {
        final c = _rowCostTotal(r);
        if (c < _kRoiAnchorMinYuan) continue;
        final p = (r['profit'] as num?)?.toDouble() ?? 0;
        final roi = p / c * 100;
        final share = c / totalCost;
        final score = (avgRoi - roi) * share;
        if (score > worstScore) {
          worstScore = score;
          worst = r;
          worstRoi = roi;
          worstShare = share;
          worstCost = c;
        }
      }
      if (worst != null && (avgRoi - worstRoi) >= 5) {
        final row = worst;
        items.add(
          _LhAiInsight(
            tone: _LhAiTone.risk,
            spans: [
              (text: '${row['name'] ?? '未命名'} ', color: null),
              (
                text: 'ROI ${worstRoi.toStringAsFixed(1)}%',
                color: DunesColors.resolve(context, LhColors.copper),
              ),
              (
                text:
                    '，低于均值 ${(avgRoi - worstRoi).toStringAsFixed(1)}pp，且吃掉$thisWord ',
                color: null,
              ),
              (
                text: '${(worstShare * 100).toStringAsFixed(1)}%',
                color: DunesColors.resolve(context, _LhPnl.costNum),
              ),
              (text: ' 的成本合计。', color: null),
            ],
            evidence: [
              _LhAiEvidence('成本', _fmtAmountWithUnit(worstCost)),
              _LhAiEvidence(
                '利润',
                _fmtAmountWithUnit((row['profit'] as num?)?.toDouble() ?? 0),
              ),
            ],
            drill: () => _openAiRowDrill(row),
          ),
        );
      }
    }

    // ── 规则 3 · 集中度：净利润最大贡献方 ────────────────────────────
    if (rows.isNotEmpty && netProfit.abs() >= _kRoiAnchorMinYuan) {
      Map<String, dynamic>? top;
      double topNet = 0;
      for (final r in rows) {
        final n = (r['netProfit'] as num?)?.toDouble() ?? 0;
        if (n > topNet) {
          topNet = n;
          top = r;
        }
      }
      final share = netProfit != 0 ? topNet / netProfit * 100 : 0.0;
      if (top != null && share >= 30) {
        final row = top;
        items.add(
          _LhAiInsight(
            tone: _LhAiTone.opportunity,
            spans: [
              (text: '${row['name'] ?? '未命名'} 贡献了 ', color: null),
              (text: '净利润', color: DunesColors.resolve(context, _LhPnl.netBar)),
              (text: ' 的 ', color: null),
              (
                text: '${share.toStringAsFixed(0)}%',
                color: DunesColors.resolve(context, _LhPnl.netNum),
              ),
              (text: '，集中度偏高 —— 这一家波动会直接决定大盘。', color: null),
            ],
            evidence: [
              _LhAiEvidence('净利', _fmtAmountWithUnit(topNet)),
              _LhAiEvidence(
                '收入',
                _fmtAmountWithUnit((row['revenue'] as num?)?.toDouble() ?? 0),
              ),
            ],
            drill: () => _openAiRowDrill(row),
          ),
        );
      }
    }

    // ── 兜底 · 一条都没触发时，说清楚「确实没事」，不要留空卡 ──────────
    if (items.isEmpty) {
      items.add(
        _LhAiInsight(
          tone: _LhAiTone.neutral,
          spans: [
            (text: '$thisWord无显著异动。', color: null),
            (
              text: '收入',
              color: DunesColors.resolve(context, _LhPnl.revenueBar),
            ),
            (text: ' ${_fmtAmountWithUnit(revenue)} · ', color: null),
            (text: '成本合计', color: DunesColors.resolve(context, _LhPnl.costBar)),
            (text: ' ${_fmtAmountWithUnit(totalCost)} · ', color: null),
            (text: '净利润', color: DunesColors.resolve(context, _LhPnl.netBar)),
            (text: ' ${_fmtAmountWithUnit(netProfit)}。', color: null),
          ],
        ),
      );
    }

    return _LhAiSummary(
      items: items,
      generatedAt: DateTime.now(),
      degraded: true, // 本地规则产出 → 标题显示「要点」；接了 LLM 后由后端决定
    );
  }

  // ═══════════════════════════════════════════════════════════════════════
  // AI 解读 · 卡片
  //
  //   白底 + 紫 hairline，和列表卡同级。全页唯一有色面仍然只有 hero，这条不破。
  // ═══════════════════════════════════════════════════════════════════════
  Widget _buildAiSummaryCard() {
    // build 期只调度，不 setState —— 实际请求走 postFrame。
    _ensureAiSummary();

    final s = _aiSummary;
    final showSkeleton = _aiLoading && s == null;

    return Container(
      margin: const EdgeInsets.fromLTRB(
        lighthouseHeroShellMarginH,
        0,
        lighthouseHeroShellMarginH,
        16,
      ),
      decoration: BoxDecoration(
        color: DunesColors.resolve(
          context,
          Colors.white,
          role: DunesColorRole.surface,
        ),
        border: Border.all(
          color: DunesColors.resolve(
            context,
            _LhPlum.line,
            role: DunesColorRole.border,
          ),
          width: 0.5,
        ),
        borderRadius: BorderRadius.circular(14),
        boxShadow: [
          BoxShadow(
            color: LhColors.ink.withAlpha(10),
            blurRadius: 10,
            spreadRadius: -4,
            offset: const Offset(0, 3),
          ),
        ],
      ),
      clipBehavior: Clip.antiAlias,
      child: Column(
        crossAxisAlignment: CrossAxisAlignment.stretch,
        children: [
          _buildAiHeader(s),
          Container(
            height: 0.5,
            color: DunesColors.resolve(
              context,
              _LhPlum.line,
              role: DunesColorRole.surface,
            ),
          ),
          if (showSkeleton)
            _buildAiSkeleton()
          else if (_aiFailed && s == null)
            _buildAiError()
          else if (s != null) ...[
            for (int i = 0; i < _aiVisibleItems(s).length; i++)
              _buildAiInsightRow(
                _aiVisibleItems(s)[i],
                last: i == _aiVisibleItems(s).length - 1,
              ),
            _buildAiFooter(s),
          ],
        ],
      ),
    );
  }

  List<_LhAiInsight> _aiVisibleItems(_LhAiSummary s) =>
      _aiExpanded ? s.items : s.items.take(_kAiCollapsedCount).toList();

  Widget _buildAiHeader(_LhAiSummary? s) {
    final title = (s?.degraded ?? false) ? '要点' : 'AI 解读';
    return Padding(
      padding: const EdgeInsets.fromLTRB(14, 11, 14, 10),
      child: Row(
        children: [
          Expanded(
            child: Row(
              crossAxisAlignment: CrossAxisAlignment.stretch,
              children: [
                Icon(
                  Icons.auto_awesome_outlined,
                  size: 15,
                  color: DunesColors.resolve(context, _LhPlum.primary),
                ),
                const SizedBox(width: 7),
                Text(
                  title,
                  style: LhTypography.mono(
                    size: 12,
                    color: DunesColors.resolve(context, _LhPlum.ink),
                    weight: FontWeight.w700,
                    letterSpacing: 0.4,
                    context: context,
                  ),
                ),
                const SizedBox(width: 8),
                Flexible(
                  child: LhScrollText(
                    _isCustomRange
                        ? '自定义区间'
                        : _periodInstanceLabel(_period, _periodOffset),
                    maxLines: 1,
                    overflow: TextOverflow.ellipsis,
                    style: LhTypography.mono(
                      size: 11,
                      color: DunesColors.resolve(context, LhColors.mute2),
                      weight: FontWeight.w500,
                      context: context,
                    ),
                  ),
                ),
              ],
            ),
          ),
          if (s != null)
            Text(
              '${_two(s.generatedAt.hour)}:${_two(s.generatedAt.minute)} 生成',
              style: _tabular(
                LhTypography.mono(
                  size: 11,
                  color: DunesColors.resolve(context, LhColors.mute2),
                  weight: FontWeight.w500,
                  context: context,
                ),
              ),
            ),
          const SizedBox(width: 10),
          GestureDetector(
            behavior: HitTestBehavior.opaque,
            onTap: _aiLoading ? null : _retryAiSummary,
            child: Icon(
              Icons.refresh_rounded,
              size: 15,
              color: _aiLoading
                  ? DunesColors.resolve(context, LhColors.mute2)
                  : DunesColors.resolve(context, LhColors.mute),
            ),
          ),
        ],
      ),
    );
  }

  Widget _buildAiSkeleton() {
    Widget bar(double w) => Container(
      height: 10,
      width: w,
      margin: const EdgeInsets.only(bottom: 8),
      color: DunesColors.resolve(
        context,
        LhColors.line2,
        role: DunesColorRole.surface,
      ),
    );
    return Padding(
      padding: const EdgeInsets.fromLTRB(14, 14, 14, 10),
      child: Column(
        crossAxisAlignment: CrossAxisAlignment.start,
        children: [bar(240), bar(180), bar(206)],
      ),
    );
  }

  Widget _buildAiError() {
    return Padding(
      padding: const EdgeInsets.fromLTRB(14, 14, 14, 14),
      child: Row(
        children: [
          Expanded(
            child: Text(
              '解读没生成出来。',
              style: LhTypography.sans(
                size: 13,
                color: DunesColors.resolve(context, LhColors.mute),
                weight: FontWeight.w500,
                context: context,
              ),
            ),
          ),
          GestureDetector(
            behavior: HitTestBehavior.opaque,
            onTap: _retryAiSummary,
            child: Text(
              '重试',
              style: LhTypography.mono(
                size: 12,
                color: DunesColors.resolve(context, _LhPlum.primary),
                weight: FontWeight.w700,
                context: context,
              ),
            ),
          ),
        ],
      ),
    );
  }

  Widget _buildAiInsightRow(_LhAiInsight it, {required bool last}) {
    final body = LhTypography.sans(
      size: 13,
      color: DunesColors.resolve(context, LhColors.ink),
      weight: FontWeight.w500,
      height: 1.65,
      context: context,
    );

    TextStyle spanStyle(Color? color, TextStyle bodyStyle) {
      if (color == null) return bodyStyle;
      return LhTypography.mono(
        size: 12.5,
        color: color,
        weight: FontWeight.w700,
        height: 1.65,
        context: context,
      );
    }

    return GestureDetector(
      behavior: HitTestBehavior.opaque,
      onTap: it.drill,
      child: Container(
        decoration: BoxDecoration(
          border: last
              ? null
              : Border(
                  bottom: BorderSide(
                    color: DunesColors.resolve(
                      context,
                      LhColors.line2,
                      role: DunesColorRole.border,
                    ),
                    width: 0.5,
                  ),
                ),
        ),
        padding: const EdgeInsets.fromLTRB(14, 12, 14, 12),
        child: IntrinsicHeight(
          child: Row(
            crossAxisAlignment: CrossAxisAlignment.stretch,
            children: [
              Container(
                width: 2,
                color: DunesColors.resolveNullable(
                  context,
                  _lhAiToneBar(it.tone),
                  role: DunesColorRole.surface,
                ),
              ),
              const SizedBox(width: 10),
              Expanded(
                child: Column(
                  crossAxisAlignment: CrossAxisAlignment.start,
                  mainAxisSize: MainAxisSize.min,
                  children: [
                    RichText(
                      text: TextSpan(
                        children: [
                          for (final sp in it.spans)
                            TextSpan(
                              text: sp.text,
                              style: spanStyle(sp.color, body),
                            ),
                        ],
                      ),
                    ),
                    if (it.evidence.isNotEmpty) ...[
                      const SizedBox(height: 7),
                      Wrap(
                        spacing: 6,
                        runSpacing: 6,
                        children: [
                          for (final e in it.evidence)
                            Container(
                              padding: const EdgeInsets.symmetric(
                                horizontal: 7,
                                vertical: 3,
                              ),
                              color: DunesColors.resolve(
                                context,
                                LhColors.line2,
                                role: DunesColorRole.surface,
                              ),
                              child: Text(
                                '${e.label} ${e.value}',
                                style: _tabular(
                                  LhTypography.mono(
                                    size: 11,
                                    color: DunesColors.resolve(
                                      context,
                                      LhColors.ink2,
                                    ),
                                    weight: FontWeight.w600,
                                    context: context,
                                  ),
                                ),
                              ),
                            ),
                        ],
                      ),
                    ],
                  ],
                ),
              ),
              if (it.drill != null) ...[
                const SizedBox(width: 8),
                Center(
                  child: Icon(
                    Icons.chevron_right_rounded,
                    size: 16,
                    color: DunesColors.resolve(context, LhColors.mute2),
                  ),
                ),
              ],
            ],
          ),
        ),
      ),
    );
  }

  Widget _buildAiFooter(_LhAiSummary s) {
    final hidden = s.items.length - _kAiCollapsedCount;
    final canExpand = hidden > 0;

    Widget vote(int v, IconData icon) => GestureDetector(
      behavior: HitTestBehavior.opaque,
      onTap: () => _submitAiVote(v),
      child: Icon(
        icon,
        size: 14,
        color: _aiVote == v
            ? DunesColors.resolve(context, _LhPlum.primary)
            : DunesColors.resolve(context, LhColors.mute2),
      ),
    );

    return Padding(
      padding: const EdgeInsets.fromLTRB(14, 10, 14, 10),
      child: Row(
        children: [
          if (canExpand)
            GestureDetector(
              behavior: HitTestBehavior.opaque,
              onTap: () => setState(() => _aiExpanded = !_aiExpanded),
              child: Text(
                _aiExpanded ? '收起' : '展开其余 $hidden 条',
                style: LhTypography.mono(
                  size: 12,
                  color: DunesColors.resolve(context, _LhPlum.ink),
                  weight: FontWeight.w600,
                  context: context,
                ),
              ),
            ),
          const Spacer(),
          vote(1, Icons.thumb_up_alt_outlined),
          const SizedBox(width: 14),
          vote(-1, Icons.thumb_down_alt_outlined),
        ],
      ),
    );
  }

  // ───── Panel (Hero + Tabs + Sortbar) ──────────────────────────────────────
  // 与二级页统一：期间条在卡外，摘要卡白→雾紫渐变，下方再挂 tab / 排序。
  // 分析 Tab 不展示 Hero 总览，只保留期间条 + Tab。
  Widget _buildPanel() {
    // 财务视角跟业务共用期间：周期岛一变，业财数据按同一个期间重拉。
    if (_bfSubjectView) {
      final bf = _bf!;
      final p = _period;
      final o = _periodOffset;
      final cs = _customStart;
      final ce = _customEnd;
      WidgetsBinding.instance.addPostFrameCallback((_) {
        if (mounted) bf.syncPeriod(p, o, cs, ce);
      });
    }
    return Column(
      crossAxisAlignment: CrossAxisAlignment.stretch,
      children: [
        // 日 / 周 / 月 / 季 / 年 已钉在列表上方（_buildPinnedPeriodBar），
        // 这里只留原来的间距。
        SizedBox(height: lighthouseSoftReloadKeepsContent ? 0 : 10),
        // 原来 10pt 的留白里放进度条：不占新高度，刷新前后页面不跳。
        if (lighthouseSoftReloadKeepsContent) _buildSoftReloadLine(),
        if (lighthouseTopicStripEnabled && widget.onTopicChanged != null)
          _buildTopicStrip(),
        // Hero：始终展示；L1 分类只筛列表，不在 Hero 上贴「能源」等标签
        // 财务口径（主体）换成业财 Hero；净TA 仍走原来的 Hero。
        _softReloadDim(
          KeyedSubtree(
            key: _heroCardKey,
            child: _buildHeroShell(
              child: _bfSubjectView
                  ? LighthouseBfHero(
                      controller: _bf!,
                      onOpenSubjects: _scrollToLedger,
                    )
                  : _buildHero(),
            ),
          ),
        ),
        // Hero 与账本之间的边界。
        //
        // v20 · 旧版是一条 7pt 的双线灰带，上下再各留 14 / 16pt 空白：
        // 三段留白夹一条带子，Hero 像停在半空，账本卡又像另起一页 —— 那道
        // 「衔接」其实是一整块 37pt 的空地。改回一条通栏细线贴着 Hero 收口，
        // 线到卡只留 10pt：线说「上面这段完了」，紧接着的卡自己说「这段开始」，
        // 一句话说一遍。同步落款已经上提到标题行，Hero 末行就是指标栏，
        // 收口落在内容上而不是落在一行小字上。
        if (lighthouseHeroUsesFlatLayout) ...[
          const SizedBox(height: 12),
          Container(
            height: 0.7,
            color: DunesColors.resolve(
              context,
              LhColors.line,
              role: DunesColorRole.surface,
            ),
          ),
          const SizedBox(height: 10),
        ] else
          const SizedBox(height: 12),
        _softReloadDim(
          Container(
            margin: const EdgeInsets.fromLTRB(
              lighthouseHeroShellMarginH,
              0,
              lighthouseHeroShellMarginH,
              18,
            ),
            decoration: BoxDecoration(
              color: DunesColors.resolve(
                context,
                Colors.white,
                role: DunesColorRole.surface,
              ),
              border: Border.all(
                color: lighthouseLedgerUsesLavenderPanelFrame
                    ? DunesColors.resolve(
                        context,
                        _LhPlum.line,
                        role: DunesColorRole.border,
                      )
                    : DunesColors.resolve(
                        context,
                        LhColors.line2,
                        role: DunesColorRole.border,
                      ),
                width: lighthouseLedgerPanelBorderWidth,
              ),
              borderRadius: BorderRadius.circular(lighthouseLedgerPanelRadius),
              boxShadow: [
                BoxShadow(
                  color: _LhPlum.primary.withAlpha(10),
                  blurRadius: lighthouseLedgerPanelShadowBlur,
                  spreadRadius: -3,
                  offset: const Offset(0, 3),
                ),
              ],
            ),
            clipBehavior: Clip.antiAlias,
            child: Column(
              crossAxisAlignment: CrossAxisAlignment.stretch,
              children: [
                if (_inTopic) _buildTopicLedgerBar(),
                // 跟「产品汇总」同款的小标题：两张卡都由标题开头。
                // 2026-10-20：维度 tab 已经说了是哪张表、期间条已经说了日期，不再重复一行标题。
                if (lighthouseLedgerShowsTitle &&
                    _tab != 'analysis' &&
                    !_bfSubjectView)
                  _buildLedgerTitle(),
                KeyedSubtree(
                  key: _ledgerTabsAnchorKey,
                  child: _buildTabSegment(),
                ),
                if (_bfSubjectView)
                  LighthouseBfSubjectList(controller: _bf!)
                else if (_tab != 'analysis') ...[
                  if (_tab == 'netTa') _buildNetTAListMeta(),
                  // 🔍 / 指标已并进分类行；只有在查找、或分类行不在时才露这一行。
                  if (_tab != 'netTa' &&
                      (_ledgerSearchOpen || !_ledgerToolsInFilterRow)) ...[
                    _buildSortbar(),
                    Container(
                      height: 0.7,
                      color: DunesColors.resolve(
                        context,
                        LhColors.line2,
                        role: DunesColorRole.surface,
                      ),
                    ),
                  ],
                  _buildList(embedded: true),
                ],
              ],
            ),
          ),
        ),
      ],
    );
  }

  /// 期间条下方 10pt 槽位里的细进度条。不刷新时是透明留白。
  Widget _buildSoftReloadLine() {
    final on = _softReloading;
    return SizedBox(
      height: 10,
      child: Padding(
        padding: const EdgeInsets.symmetric(horizontal: 34),
        child: Center(
          child: AnimatedOpacity(
            opacity: on ? 1 : 0,
            duration: const Duration(milliseconds: 160),
            child: ClipRRect(
              borderRadius: BorderRadius.circular(2),
              child: SizedBox(
                height: 2,
                child: on
                    ? LinearProgressIndicator(
                        key: ValueKey('lighthouse-soft-reload-progress'),
                        minHeight: 2,
                        backgroundColor: DunesColors.resolve(
                          context,
                          _LhPlum.heroEdge,
                          role: DunesColorRole.surface,
                        ),
                        valueColor: AlwaysStoppedAnimation<Color>(
                          DunesColors.resolve(context, _LhPlum.primary),
                        ),
                      )
                    : null,
              ),
            ),
          ),
        ),
      ),
    );
  }

  /// 软刷新期间旧内容压淡且不可点：看得出「这是上一期的数，新的在路上」，
  /// 又不会点进一个马上要被换掉的行。
  Widget _softReloadDim(Widget child) {
    if (!lighthouseSoftReloadKeepsContent) return child;
    final on = _softReloading;
    return IgnorePointer(
      ignoring: on,
      child: AnimatedOpacity(
        opacity: on ? 0.42 : 1,
        duration: Duration(milliseconds: on ? 120 : 220),
        curve: Curves.easeOut,
        child: child,
      ),
    );
  }

  String get _l1SummaryTitle {
    final topic = _topicDef;
    if (topic != null && _tab != 'analysis') return '${topic.name}专题';
    switch (_tab) {
      case 'product':
        return '产品汇总';
      case 'supply':
        return '供给方汇总';
      case 'channel':
        return '渠道汇总';
      case 'netTa':
        return '净TA汇总';
      case 'people':
        return '人效汇总';
      case 'analysis':
        return '分析总览';
      default:
        return '汇总';
    }
  }

  Map<String, dynamic>? _netTACategoryRow(String name) {
    for (final r
        in _bundle?.rowsOf('netTa') ?? const <Map<String, dynamic>>[]) {
