        decoration: BoxDecoration(
          color: DunesColors.resolve(
            context,
            LhColors.copperSoft,
            role: DunesColorRole.surface,
          ),
          border: Border.all(
            color: DunesColors.resolve(
              context,
              const Color(0xFFEEDFC2),
              role: DunesColorRole.border,
            ),
          ),
          borderRadius: BorderRadius.circular(9),
        ),
        child: Text.rich(
          TextSpan(
            style: LhTypography.sans(
              size: 11,
              color: DunesColors.resolve(context, const Color(0xFF7A5514)),
              height: 1.55,
              context: context,
            ),
            children: [
              const TextSpan(text: '本期 '),
              TextSpan(
                text: _fmtAmountWithUnit(unmapped),
                style: const TextStyle(fontWeight: FontWeight.w700),
              ),
              const TextSpan(text: ' 流水未匹配资金分类，未计入净TA'),
              if (samples.isNotEmpty) TextSpan(text: ' — ${samples.join('、')}'),
