  /// [shareBase] 给了就在环比缺失时退回「占 x%」（占该桶明细绝对值之和）。
  /// 资管这些二级分类经常没有上期数，一整屏「—」等于什么都没说。
  Widget _buildNetTAMetricGrid(
    List<Map<String, dynamic>> metrics, {
    bool inflowBadge = false,
    double shareBase = 0,
  }) {
    Widget tile(Map<String, dynamic> m) {
      final name = m['name']?.toString() ?? '';
      final v = (m['netTa'] as num?)?.toDouble() ?? 0;
      final rawDelta = _deltaFromEntityRow(m, 'netTa');
      final delta = rawDelta != null && lighthouseDeltaPctShown(rawDelta.pct)
          ? rawDelta
          : null;
      final share = (delta == null && shareBase > 0 && v.abs() > 0)
          ? v.abs() / shareBase * 100
          : null;
      final showIn = inflowBadge && v > 0 && !name.startsWith('其余');
      return Column(
        crossAxisAlignment: CrossAxisAlignment.start,
        children: [
          Row(
            children: [
              Flexible(
                child: LhScrollText(
                  name,
                  maxLines: 1,
                  overflow: TextOverflow.ellipsis,
                  style: LhTypography.sans(
                    size: 10,
                    color: DunesColors.resolve(context, LhColors.mute),
                    weight: FontWeight.w500,
                    context: context,
                  ),
                ),
              ),
              if (showIn) ...[
                const SizedBox(width: 4),
                Container(
                  padding: const EdgeInsets.symmetric(
                    horizontal: 3,
                    vertical: 0,
                  ),
                  decoration: BoxDecoration(
                    color: DunesColors.resolve(
                      context,
                      const Color(0xFFEDF3EA),
                      role: DunesColorRole.surface,
                    ),
                    borderRadius: BorderRadius.circular(3),
                  ),
                  child: Text(
                    '流入',
                    style: LhTypography.sans(
                      size: 8,
                      color: DunesColors.resolve(context, LhColors.pos),
                      weight: FontWeight.w700,
                      context: context,
                    ),
                  ),
                ),
              ],
            ],
          ),
          const SizedBox(height: 1),
          Text.rich(
            TextSpan(
              children: [
                TextSpan(
                  text: _fmtMoney(v),
                  style: LhTypography.number(
                    size: lighthouseLedgerValueFontSize,
                    color: DunesColors.resolve(context, LhColors.ink),
                    context: context,
                  ),
                ),
                TextSpan(
                  text: _unitMoney(v),
                  style: LhTypography.sans(
                    size: lighthouseLedgerUnitFontSize,
                    color: DunesColors.resolve(context, LhColors.mute),
                    weight: FontWeight.w500,
                    context: context,
                  ),
                ),
              ],
            ),
          ),
          const SizedBox(height: 1),
          Text(
            delta != null
                ? '${delta.isUp ? '↑' : '↓'}'
                      '${delta.pct.abs().toStringAsFixed(delta.pct.abs() >= 10 ? 0 : 1)}%'
                : (share != null ? '占 ${share.toStringAsFixed(1)}%' : '—'),
            style: LhTypography.mono(
              size: 8.5,
              color: delta == null
                  ? DunesColors.resolve(context, LhColors.mute2)
                  : (delta.isUp
                        ? DunesColors.resolve(context, LhColors.neg)
                        : DunesColors.resolve(context, LhColors.pos)),
              weight: FontWeight.w600,
              context: context,
            ),
          ),
        ],
      );
    }

    final rows = <Widget>[];
    for (var i = 0; i < metrics.length; i += 2) {
      rows.add(
        Row(
          crossAxisAlignment: CrossAxisAlignment.start,
          children: [
            Expanded(child: tile(metrics[i])),
            const SizedBox(width: 16),
            Expanded(
              child: i + 1 < metrics.length
                  ? tile(metrics[i + 1])
                  : const SizedBox.shrink(),
            ),
          ],
        ),
      );
      if (i + 2 < metrics.length) rows.add(const SizedBox(height: 8));
    }
    return Column(children: rows);
  }

  String get _profitPeriodLabel =>
      lighthouseHeroMetricPeriodLabel(_period, 'profit');

  // ───── Hero（一级 / 二级 / 三级共用；二级三级传 totalsOverride 用详情 payload）──
  /// 从详情行（L2/L3 summaryEntity）拼出与一级 Hero 同结构的 totals。
  Map<String, double> _heroTotalsFromRow(Map<String, dynamic> e) {
    final sales = (e['sales'] as num?)?.toDouble() ?? 0;
    final verified = _verifiedSalesOf(e);
    final profit = (e['profit'] as num?)?.toDouble() ?? 0;
    final netProfit = (e['netProfit'] as num?)?.toDouble() ?? 0;
    final revenue = (e['revenue'] as num?)?.toDouble() ?? 0;
    final gmv = (e['gmv'] as num?)?.toDouble() ?? 0;
    final cost = (e['cost'] as num?)?.toDouble() ?? 0;
    final projectCost = (e['projectCost'] as num?)?.toDouble() ?? 0;
    final totalCost = _rowCostTotal(e);
    final spread = (e['spread'] as num?)?.toDouble() ?? 0;
    final tax = (e['tax'] as num?)?.toDouble() ?? 0;
    final handlingFee = (e['handlingFee'] as num?)?.toDouble() ?? 0;
    final platformFee = (e['platformServiceFee'] as num?)?.toDouble() ?? 0;
    // 与一级同口径：ROI = 利润 ÷ 成本合计；毛利率默认 ÷ 核销额，运营商 ÷ 销售额
    final roiBase = lighthouseValidRateBase(
      totalCost,
      minimumBase: _kRoiAnchorMinYuan,
    );
    final rate = roiBase > 0 ? profit / roiBase * 100 : 0.0;
    final gmBase = lighthouseGrossMarginBase(
      verifiedSales: verified,
      sales: sales,
      gmv: gmv,
      product: _rowMarginProduct(e),
      basis: e['grossMarginBasis']?.toString(),
      group: e['group']?.toString(),
      minimumBase: _kRoiAnchorMinYuan,
    );
    final grossMargin = gmBase > 0 ? profit / gmBase * 100 : 0.0;
    final anchor = _anchor == _LhAnchor.verified && verified > 0
        ? verified
        : sales;
    final spreadRate = anchor > 0 ? revenue / anchor * 100 : 0.0;
    final prepaid = (e['prepaid'] as num?)?.toDouble() ?? 0.0;
    final netTa = (e['netTa'] as num?)?.toDouble();
    return {
      'sales': sales,
      'verifiedSales': verified,
      'prepaid': prepaid,
      if (netTa != null) 'netTa': netTa,
      'gmv': gmv,
      'cost': cost,
      'projectCost': projectCost,
      'totalCost': totalCost,
      'costTotal': totalCost,
      'spread': spread,
      'businessCost': cost,
      'handlingFee': handlingFee,
      'platformServiceFee': platformFee,
      'tax': tax,
      'profit': profit,
      'netProfit': netProfit,
      'revenue': revenue,
      'grossMargin': grossMargin,
      'spreadRate': spreadRate,
      'rate': rate,
    };
  }

  /// 实体行环比（L2/L3 `deltas` / 旧 `deltaPct`）。
  ({double pct, bool isUp})? _deltaFromEntityRow(
    Map<String, dynamic> e,
    String key,
  ) {
    if (e['_deltaAvailable'] == false) return null;
    if (key == 'grossMargin' && _rowMarginBasis(e) == 'gmv') {
      final delta = _ledgerDelta(e, key);
      if (delta == null) return null;
      return (pct: delta, isUp: delta >= 0);
    }
    final deltas = (e['deltas'] as Map?)?.cast<String, dynamic>();
    final lookup = switch (key) {
      'costTotal' => 'totalCost',
      'businessCost' => 'cost',
      _ => key,
    };
    num? raw = deltas?[lookup] as num?;
    if (key == 'profit' && raw == null) {
      raw = e['deltaPct'] as num?;
    }
    if (raw == null || raw.abs() < 1e-9) return null;
    final v = raw.toDouble();
    return (pct: v, isUp: v >= 0);
  }

  ({double pct, bool isUp})? _profitDeltaFromRow(Map<String, dynamic> e) =>
      _deltaFromEntityRow(e, 'profit');

  /// 一级列表行 key = name 或 name::group（与开详情 / withTrends 一致）。
  String _dimensionRowKey(Map<String, dynamic> r) {
    final name = r['name']?.toString() ?? '';
    final group = r['group']?.toString() ?? '';
    return group.isEmpty ? name : '$name::$group';
  }

  Map<String, dynamic>? _findDimensionRow(String tab, String key) {
    for (final r in _bundle?.rowsOf(tab) ?? const <Map<String, dynamic>>[]) {
      final k = _dimensionRowKey(r);
      final name = r['name']?.toString() ?? '';
      if (k == key || name == key) return r;
    }
    return null;
  }

  List<double> _trendNums(dynamic v) {
    if (v is! List) return const <double>[];
    return v
        .map((x) => (x is num) ? x.toDouble() : 0.0)
        .toList(growable: false);
  }

  /// 列表行展开走势时，到哪张一级 tab 去对齐同名实体的 trend。
  String? _trendLookupTabForListRow() {
    if (_detailKey != null) {
      // 人效 L2 子行、以及产品/供给/渠道二级页上的人效子维，
      // 都不能去吃全公司 people trend —— 那是这个人在全公司的曲线，
      // 不是「这个产品底下这个人」的曲线。行上的 trend 才是对的。
      if (_detailType == 'people' || _detailSubTab == 'people') return null;
      return lighthouseTrendTabForSubDim(_detailSubTab);
    }
    return lighthouseTrendTabForSubDim(_tab);
  }

  bool _trendMapUsable(Map<String, dynamic> t) => lighthouseTrendMapUsable(t);

  Map<String, dynamic>? _trendFromCache(
    String tab,
    String key, [
    String? name,
  ]) {
    final cached = _trendCache[tab];
    if (cached == null || cached.isEmpty) return null;
    final direct = cached[key];
    if (direct != null && _trendMapUsable(direct)) {
      return Map<String, dynamic>.from(direct);
    }
    if (name != null && name.isNotEmpty) {
      final byName = cached[name];
      if (byName != null && _trendMapUsable(byName)) {
        return Map<String, dynamic>.from(byName);
      }
    }
    // key 可能是 name::group，也试只匹配 name 前缀
    if (key.contains('::')) {
      final onlyName = key.split('::').first;
      final byPrefix = cached[onlyName];
      if (byPrefix != null && _trendMapUsable(byPrefix)) {
        return Map<String, dynamic>.from(byPrefix);
      }
    }
    return null;
  }

  /// 账本行 / 展开图：行上无 trend 时，按当前 sub-tab 维回填（缓存优先，不依赖列表已加载）。
  Map<String, dynamic>? _resolvedRowTrend(Map<String, dynamic> r) {
    final direct = r['trend'];
    if (direct is Map) {
      final m = Map<String, dynamic>.from(direct);
      if (_trendMapUsable(m)) return m;
    }
    if (r['isChild'] == true) {
      // 三级金额属于「父产品 ∩ 三级」；同名一级产品的全局走势不是它的走势。
      if (_detailKey == null && _tab == 'product') {
        final parent = r['parent']?.toString() ?? '';
        final group = r['group']?.toString() ?? '';
        final key = group.isEmpty ? parent : '$parent::$group';
        final detail = _detailEntityMap('product', key);
        final rows = detail?['productL3'];
        if (rows is List) {
          for (final item in rows) {
            if (item is! Map || item['name'] != r['name']) continue;
            final trend = item['trend'];
            if (trend is Map) {
              final m = Map<String, dynamic>.from(trend);
              if (_trendMapUsable(m)) return m;
            }
          }
        }
      }
      return null;
    }
    if (_detailKey != null) return null;
    final tab = _trendLookupTabForListRow();
    if (tab == null) return null;
    final key = _dimensionRowKey(r);
    final name = r['name']?.toString() ?? '';
    final fromCache = _trendFromCache(tab, key, name);
    if (fromCache != null) return fromCache;
    final listRow =
        _findDimensionRow(tab, key) ??
        (name.isEmpty ? null : _findDimensionRow(tab, name));
    final t = listRow?['trend'];
    if (t is Map) {
      final m = Map<String, dynamic>.from(t);
      if (_trendMapUsable(m)) return m;
    }
    return null;
  }

  Map<String, dynamic> _rowWithResolvedTrend(Map<String, dynamic> r) {
    if (r['trend'] is Map &&
        _trendMapUsable(Map<String, dynamic>.from(r['trend'] as Map))) {
      return r;
    }
    final t = _resolvedRowTrend(r);
    if (t == null) return r;
    return Map<String, dynamic>.from(r)..['trend'] = t;
  }

  void _ensureTrendLoaded(String tab) {
    if (widget.sharedCard != null) return;
    final resolved = lighthouseTrendTabForSubDim(tab);
    if (resolved == 'product' ||
        resolved == 'supply' ||
        resolved == 'channel' ||
        resolved == 'province' ||
        resolved == 'people') {
      unawaited(_loadTrend(resolved!));
    }
  }

  /// 详情 Hero / 展开走势：优先 payload.trend。
  /// L2 可回填同实体一级缓存；L3 只回填本实体所在交叉维，禁止用父级走势。
  Map<String, dynamic>? _resolvedDetailTrend(Map<String, dynamic> e) {
    final direct = e['trend'];
    if (direct is Map) {
      final m = Map<String, dynamic>.from(direct);
      if (_trendMapUsable(m)) return m;
    }
    final name = e['name']?.toString() ?? '';
    final isDrill = _drillKey != null || _codeDrillKey != null;
    if (isDrill) {
      if (!lighthouseCanFallbackToChildTrend(isDrill: true)) return null;
      final childTab = lighthouseTrendTabForSubDim(_drillDim ?? '');
      if (childTab == null) return null;
      final key = _dimensionRowKey(e);
      return _trendFromCache(childTab, key, name);
    }
    if (!lighthouseCanFallbackToRootTrend(isDrill: false)) return null;
    final type = _detailType;
    final key = _detailKey;
    if (type == null || key == null) return null;
    final fromCache = _trendFromCache(
      type,
      key,
      name.isEmpty ? key.split('::').first : name,
    );
    if (fromCache != null) return fromCache;
    final row = _findDimensionRow(type, key);
    final t = row?['trend'];
    if (t is Map) return Map<String, dynamic>.from(t);
    return null;
  }

  List<double> _seriesFromTrendMap(
    Map<String, dynamic> t,
    String key, {
    String? group,
    String? product,
    String? basis,
  }) {
    switch (key) {
      case 'profit':
        var profit = _trendNums(t['profit']);
        if (profit.isEmpty) profit = _trendNums(t['points']);
        return profit;
      case 'revenue':
        return _trendNums(t['revenue']);
      case 'sales':
        return _trendNums(t['sales']);
      case 'gmv':
        return _trendNums(t['gmv']);
      case 'verifiedSales':
        return _trendNums(t['verifiedSales']);
      case 'prepaid':
        return _trendNums(t['prepaid']);
      case 'projectCost':
        return _trendNums(t['projectCost']);
      case 'cost':
      case 'businessCost':
        return _trendNums(t['businessCost']);
      case 'totalCost':
      case 'costTotal':
        final total = _trendNums(t['totalCost']);
        return total.isNotEmpty ? total : _trendNums(t['cost']);
      case 'netProfit':
        return _trendNums(t['netProfit']);
      case 'spread':
        return _trendNums(t['spread']);
      case 'grossMargin':
        return lighthouseGrossMarginSeries(
          profit: _seriesFromTrendMap(t, 'profit'),
          verifiedSales: _seriesFromTrendMap(t, 'verifiedSales'),
          sales: _seriesFromTrendMap(t, 'sales'),
          gmv: _seriesFromTrendMap(t, 'gmv'),
          product: product ?? _grossMarginContextProduct,
          basis: basis ?? _grossMarginContextBasis,
          group: group,
          minimumBase: _kRoiAnchorMinYuan,
        );
      case 'rate':
        final profit = _seriesFromTrendMap(t, 'profit');
        final total = _seriesFromTrendMap(t, 'totalCost');
        final n = profit.length < total.length ? profit.length : total.length;
        return List<double>.generate(n, (i) {
          final base = lighthouseValidRateBase(
            total[i],
            minimumBase: _kRoiAnchorMinYuan,
          );
          return base > 0 ? profit[i] / base * 100 : 0.0;
        }, growable: false);
      case 'spreadRate':
        final revenue = _seriesFromTrendMap(t, 'revenue');
        final verified = _seriesFromTrendMap(t, 'verifiedSales');
        final sales = _seriesFromTrendMap(t, 'sales');
        final n = revenue.length < verified.length
            ? revenue.length
            : verified.length;
        return List<double>.generate(n, (i) {
          final anchor = _anchor == _LhAnchor.verified && verified[i] > 0
              ? verified[i]
              : (i < sales.length ? sales[i] : 0.0);
          return anchor > 0 ? revenue[i] / anchor * 100 : 0.0;
        }, growable: false);
      default:
        return const <double>[];
    }
  }

  List<double> _profitSeriesFromRow(Map<String, dynamic> e) {
    final t = _resolvedDetailTrend(e);
    if (t == null) return const [];
    return _normalizeTrendSeriesForChart(_seriesFromTrendMap(t, 'profit'));
  }

  List<String> _trendLabelsFromRow(Map<String, dynamic> e) {
    final t = _resolvedDetailTrend(e);
    if (t == null) return const [];
    final raw = t['labels'] ?? t['xLabels'];
    if (raw is! List || raw.isEmpty) return const [];
    return raw.map((x) => x.toString()).toList(growable: false);
  }

  Widget _buildHeroShell({
    required Widget child,
    bool whiteBackground = false,
  }) {
    // 拍平版：一级 Hero 不再是一张卡，直接坐在页面白底上。
    // 二级/三级仍然用卡 —— 那一层是「某个实体的切片」，需要一个明确的边界
    // 把它和上面的面包屑、下面的子列表隔开。
    // 左右取 22 —— 和期间条、下面的账本白卡同一条左沿。拍平之后没有卡边框
    // 帮忙对齐，整页就靠这一条竖直参考线站住。
    if (lighthouseHeroUsesFlatLayout && !whiteBackground) {
      return Padding(
        padding: const EdgeInsets.fromLTRB(
          lighthouseHeroShellMarginH,
          2,
          lighthouseHeroShellMarginH,
          0,
        ),
        child: child,
      );
    }
    if (lighthouseHeroMatchesLedgerCard && !whiteBackground) {
      // v23 · 与账本外框同一套皮（见 lighthouseHeroMatchesLedgerCard）。
      return Container(
        margin: const EdgeInsets.symmetric(
          horizontal: lighthouseHeroShellMarginH,
        ),
        decoration: BoxDecoration(
          color: DunesColors.resolve(
            context,
            Colors.white,
            role: DunesColorRole.surface,
          ),
          border: Border.all(
            color: lighthouseLedgerUsesLavenderPanelFrame
                ? DunesColors.resolve(
                    context,
                    _LhPlum.line,
                    role: DunesColorRole.border,
                  )
                : DunesColors.resolve(
                    context,
                    LhColors.line2,
                    role: DunesColorRole.border,
                  ),
            width: lighthouseLedgerPanelBorderWidth,
          ),
          borderRadius: BorderRadius.circular(lighthouseLedgerPanelRadius),
          boxShadow: [
            BoxShadow(
              color: _LhPlum.primary.withAlpha(10),
              blurRadius: lighthouseLedgerPanelShadowBlur,
              spreadRadius: -3,
              offset: const Offset(0, 3),
            ),
          ],
        ),
        clipBehavior: Clip.antiAlias,
        child: Padding(
          padding: const EdgeInsets.fromLTRB(
            lighthouseHeroShellPaddingH,
            12,
            lighthouseHeroShellPaddingH,
            12,
          ),
          child: child,
        ),
      );
    }
    return Container(
      margin: const EdgeInsets.fromLTRB(12, 0, 12, 0),
      decoration: BoxDecoration(
        color: whiteBackground
            ? DunesColors.resolve(
                context,
                Colors.white,
                role: DunesColorRole.surface,
              )
            : DunesColors.resolve(
                context,
                _LhPlum.heroFill,
                role: DunesColorRole.surface,
              ),
        border: Border.all(
          color: DunesColors.resolve(
            context,
            _LhPlum.heroEdge,
            role: DunesColorRole.border,
          ),
          width: 0.7,
        ),
        borderRadius: BorderRadius.circular(18),
        boxShadow: whiteBackground
            ? const []
            : [
                BoxShadow(
                  color: _LhPlum.deep.withAlpha(15),
                  blurRadius: 16,
                  spreadRadius: -7,
                  offset: const Offset(0, 5),
                ),
              ],
      ),
      clipBehavior: Clip.antiAlias,
      child: Padding(
        padding: const EdgeInsets.fromLTRB(14, 12, 14, 14),
        child: child,
      ),
    );
  }

  /// Hero 主图的五条线：规模族（核销额 / 销售额）+ 收入 / 成本合计 / 利润。
  ///
  /// 列表顺序 = 图例顺序 = 阅读顺序：先规模（会议口径「规模能推导利润，
  /// 监测先看规模」，anchor 那条是主线），再利润恒等式的收入 / 成本 / 利润。
  /// 序列缺失或全 0 的线直接不进图也不进图例 —— pad 成全 0 会在图上多出一条
  /// 贴底的假线，图例里多出一个恒为 0 的数。
  List<_HeroTrendLine> _buildHeroTrendLines(
    Map<String, double> totals,
    List<double> profitSeries,
  ) {
    bool usable(List<double> s) {
      if (s.length < 2) return false;
      for (final v in s) {
        if (v.abs() > 1e-9) return true;
      }
      return false;
    }

    if (_tab == 'netTa') {
      _HeroTrendLine? line({
        required String key,
        required String name,
        required Color color,
        required List<double> series,
        double? total,
        bool hero = false,
      }) {
        if (!usable(series)) return null;
        return _HeroTrendLine(
          key: key,
          name: name,
          color: color,
          values: series,
          total: total,
          hero: hero,
        );
      }

      return [
        ?line(
          key: 'netTa',
          name: '累计净TA',
          color: DunesColors.resolve(context, _LhPlum.primary),
          series: _seriesForMetric('netTa'),
          total: totals['netTa'],
          hero: true,
        ),
        ?line(
          key: 'netTaOperating',
          name: '经营活动',
          color: DunesColors.resolve(
            context,
            Color(lighthouseRevenueAccentValue),
          ),
          series: _seriesForMetric('netTaOperating'),
          total: totals['netTaOperating'],
        ),
        ?line(
          key: 'netTaFinancing',
          name: '筹资活动',
          color: DunesColors.resolve(
            context,
            Color(lighthouseScaleAccentValue),
          ),
          series: _seriesForMetric('netTaFinancing'),
          total: totals['netTaFinancing'],
        ),
        ?line(
          key: 'netTaOpCost',
          name: '经营成本',
          color: DunesColors.resolve(context, Color(lighthouseCostAccentValue)),
          series: _seriesForMetric('netTaOpCost'),
          total: totals['netTaOpCost'],
        ),
        ?line(
          key: 'netTaProjectCost',
          name: '项目成本',
          color: DunesColors.resolve(
            context,
            Color(lighthouseProfitAccentValue),
          ),
          series: _seriesForMetric('netTaProjectCost'),
          total: totals['netTaProjectCost'],
        ),
        ?line(
          key: 'netTaBizCost',
          name: '业务成本',
          color: DunesColors.resolve(
            context,
            Color(lighthouseNetTABizCostAccentValue),
          ),
          series: _seriesForMetric('netTaBizCost'),
          total: totals['netTaBizCost'],
        ),
      ].whereType<_HeroTrendLine>().toList(growable: false);
    }

    final scaleColor = DunesColors.resolve(
      context,
      Color(lighthouseScaleAccentValue),
    );
    final revenueColor = DunesColors.resolve(
      context,
      Color(lighthouseRevenueAccentValue),
    );
    final costColor = DunesColors.resolve(
      context,
      Color(lighthouseCostAccentValue),
    );
    final profitColor = DunesColors.resolve(
      context,
      Color(lighthouseProfitAccentValue),
    );

    final verified = _seriesForMetric('verifiedSales');
    final sales = _seriesForMetric('sales');
    final revenue = _seriesForMetric('revenue');
    final totalCost = _seriesForMetric('totalCost');

    // anchor 决定规模族谁是主线；主口径序列缺了就让另一条顶上，
    // 别让「规模」整条从 hero 图里消失。
    var verifiedIsHero = _anchor == _LhAnchor.verified;
    final verifiedOk = usable(verified);
    final salesOk = usable(sales);
    if (verifiedIsHero && !verifiedOk && salesOk) verifiedIsHero = false;
    if (!verifiedIsHero && !salesOk && verifiedOk) verifiedIsHero = true;

    // 两条都是「规模」，同单位同色 —— 换色会让人以为它们是两个不同的东西。
    // anchor 那条拿 hero：A/B 里它是粗线，C 里它直接当主图。
    _HeroTrendLine scaleLine(String key, String name, List<double> values) {
      return _HeroTrendLine(
        key: key,
        name: name,
        color: scaleColor,
        values: values,
        total: totals[key],
        sharedRange: true,
        hero: (key == 'verifiedSales') == verifiedIsHero,
      );
    }

    final verifiedLine = scaleLine('verifiedSales', '核销', verified);
    final salesLine = scaleLine('sales', '销售', sales);

    final out = <_HeroTrendLine>[];
    for (final l
        in verifiedIsHero
            ? <_HeroTrendLine>[verifiedLine, salesLine]
            : <_HeroTrendLine>[salesLine, verifiedLine]) {
      if (l.hasData) out.add(l);
    }
    for (final l in <_HeroTrendLine>[
      _HeroTrendLine(
        key: 'revenue',
        name: '收入',
        color: revenueColor,
        values: revenue,
        total: totals['revenue'],
      ),
      _HeroTrendLine(
        key: 'totalCost',
        name: '成本',
        color: costColor,
        values: totalCost,
        total: totals['totalCost'],
      ),
      _HeroTrendLine(
        key: 'profit',
        name: '利润',
        color: profitColor,
        values: profitSeries,
        total: totals['profit'],
      ),
    ]) {
      if (l.hasData) out.add(l);
    }

    if (out.isNotEmpty && !out.any((l) => l.hero)) {
      final i = out.indexWhere((l) => l.key == 'profit');
      out[i >= 0 ? i : out.length - 1] = out[i >= 0 ? i : out.length - 1]
          .asHero();
    }
    return out;
  }

  bool _heroHistoryPreloadScheduled = false;

  /// 当前这份 summary 还没有任何历史页时，下一帧预取一页。
  /// 只预取第一页；再往前由拖到左沿时触发（_TrendChart.onNeedHistory）。
  void _scheduleHeroHistoryPreload() {
    if (_heroHistoryPreloadScheduled || !_heroHistorySupported) return;
    if (_activeHeroHistory != null) return;
    _heroHistoryPreloadScheduled = true;
    WidgetsBinding.instance.addPostFrameCallback((_) {
      _heroHistoryPreloadScheduled = false;
      if (!mounted || _activeHeroHistory != null) return;
      unawaited(_loadHeroHistory());
    });
  }

  /// 走势图回传选中点。松手不清；点图例 / 换周期 / 换分类导致数据变化时
  /// 由图自己回传 null，Hero 跟着回到整期 —— 不必在每个切 tab 的地方补一行。
  void _onHeroPointSelected(int? i) {
    if (_heroPointIndex == i) return;
    if (!mounted) return;
    setState(() => _heroPointIndex = i);
  }

  /// 点日视图里走势末点就是本期（当天），点它不进点选态。
  bool get _heroLastPointIsPeriod =>
      lighthouseHeroLastPointIsPeriod(_period, isCustomRange: _isCustomRange);

  /// 「回本期」和外层日期胶囊刷新：清掉点选。图通过 selectedIndex 跟着灭高亮。
  void _clearHeroPointSelection() {
    if (_heroPointIndex == null) return;
    LighthouseFeedback.instance.play(LighthouseFeedbackKind.select);
    setState(() => _heroPointIndex = null);
  }

  /// 主 Hero 走势图上被点住的那一点（null = 看整期合计）。
  /// 图通过 selectedIndex 和外层共用这一份，避免「回本期」只清大数、图还亮着。
  int? _heroPointIndex;

  // ── 主 Hero 走势往前拉加载历史（股票式）─────────────────────────────────
  //
  //   summary 只给最近 N 个桶；往前拖到左沿时按 heroSeriesKeys 首键请求
  //   /lighthouse/hero-history，一页页拼在前面。拼好的是一份「更长的 metrics
  //   视图」（_heroSeriesMetrics）：走势图、点选某天换大数（_heroTotalsAtPoint）、
  //   点选环比（_deltaAtHeroPoint）全部读它，下标天然对齐。
  //   只做一级主 Hero；二级详情、净TA、自定义区间、本地筛选不开。

  LighthouseHeroHistory? _heroHistory;
  Map<String, dynamic>? _heroMergedMetrics;
  Object? _heroMergedBase;
  String _heroMergedKey = '';
  DateTime? _heroHistoryRetryAt;
  double? _heroViewEnd;

  List<String> get _heroBaseSeriesKeys {
    final raw = _bundle?.metrics['heroSeriesKeys'];
    if (raw is! List) return const <String>[];
    return [for (final e in raw) e.toString()];
  }

  bool get _heroHistorySupported =>
      widget.sharedCard == null &&
      _detailKey == null &&
      !_isCustomRange &&
      !_isNonLedgerTab &&
      _tab != 'netTa' &&
      !_heroLocalOnlyFilterActive &&
      _heroSummaryMatchesGroup &&
      _heroBaseSeriesKeys.length >= 2;

  String get _heroHistoryRequestKey {
    final keys = _heroBaseSeriesKeys;
    return '$_period|$_periodOffset|$_tab|$_groupFilter|${keys.isEmpty ? '' : keys.first}';
  }

  LighthouseHeroHistory? get _activeHeroHistory {
    if (!_heroHistorySupported) return null;
    final key = _heroHistoryRequestKey;
    var h = _heroHistory;
    if (h == null || h.requestKey != key) {
      // 同一天、同一口径之前拉过：直接用记住的那份，不再转圈。
      final remembered = _heroHistoryMemo[key];
      if (remembered != null) {
        _heroHistory = remembered;
        h = remembered;
      }
    }
    if (h == null) return null;
    return h.requestKey == key ? h : null;
  }

  // ── 主 Hero 历史的「记忆」：静默预取 + 内存 + 落盘 ─────────────────────────
  //   点日时页面一出来就在后台把历史拉到「最近一个 7 月 1 号再往前 30 天」
  //   （30 日均线要往前借 30 天），点开大图时已经是现成的。
  //   拉到的历史按 requestKey 记在内存（离开页面再回来不重拉）并落盘
  //   （当天再开 App 也不重拉）。requestKey 带着当前窗口首日，跨天自然作废。

  static final Map<String, LighthouseHeroHistory> _heroHistoryMemo =
      <String, LighthouseHeroHistory>{};
  static const int _kHeroHistoryMemoMax = 6;
  bool _heroWarmScheduled = false;

  /// 后台静默预取要拉到的历史天数（不含 summary 自带的最近几天）。
  int get _heroWarmTargetCount {
    // 周 / 月 / 季 / 年：一屏的量 + 慢均线要往前借的那段。
    final other = switch (_period) {
      'week' => 26 + 12,
      'month' => 24 + 12,
      'quarter' => 12 + 4,
      'year' => 8,
      _ => null,
    };
    if (other != null) return math.max(0, other - _heroBaseSeriesKeys.length);
    final now = DateTime.now();
    var july = DateTime(now.year, _kHeroFullscreenFromMonth, 1);
    if (now.isBefore(july)) {
      july = DateTime(now.year - 1, _kHeroFullscreenFromMonth, 1);
    }
    final days = now.difference(july).inDays + 1 + 30;
    return math.max(0, days - _heroBaseSeriesKeys.length);
  }

  /// 每次页面重建后看一眼：点日、还没拉够、没在拉 → 下一帧静默再拉一页。
  void _warmHeroHistory() {
    if (_heroWarmScheduled || !_heroCanOpenFullscreen) return;
    if (!_heroHistorySupported) return;
    if (_heroHistoryLoading || !_heroHistoryHasMore) return;
    if (_heroHistoryCount >= _heroWarmTargetCount) return;
    final retryAt = _heroHistoryRetryAt;
    if (retryAt != null && DateTime.now().isBefore(retryAt)) return;
    _heroWarmScheduled = true;
    WidgetsBinding.instance.addPostFrameCallback((_) {
      _heroWarmScheduled = false;
      if (!mounted) return;
      unawaited(_loadHeroHistory());
    });
  }

  void _rememberHeroHistory(LighthouseHeroHistory h) {
    if (h.length == 0) return;
    _heroHistoryMemo.remove(h.requestKey);
    _heroHistoryMemo[h.requestKey] = h.copyWith(loading: false);
    while (_heroHistoryMemo.length > _kHeroHistoryMemoMax) {
      _heroHistoryMemo.remove(_heroHistoryMemo.keys.first);
    }
  }

  /// 已拼到主 Hero 序列前面的历史点数。
  int get _heroHistoryCount =>
      widget.sharedCard?.historyCount ?? _activeHeroHistory?.length ?? 0;

  /// 走势类读数统一走这里：有历史时是「历史 + 本窗口」拼好的 metrics。
  Map<String, dynamic> get _heroSeriesMetrics {
    final base = _bundle?.metrics ?? const <String, dynamic>{};
    final h = _activeHeroHistory;
    if (h == null || h.length == 0) return base;
    final cacheKey = '${h.requestKey}#${h.version}';
    final cached = _heroMergedMetrics;
    if (cached != null &&
        identical(_heroMergedBase, base) &&
        _heroMergedKey == cacheKey) {
      return cached;
    }
    final merged = lighthouseMergeHeroHistory(base, h);
    _heroMergedMetrics = merged;
    _heroMergedBase = base;
    _heroMergedKey = cacheKey;
    return merged;
  }

  /// 主 Hero 走势图共用的视窗参数（见 _TrendChart.viewportCount）。
  int get _heroViewportCount =>
      widget.sharedCard?.viewportCount ??
      (_heroHistorySupported ? _heroBaseSeriesKeys.length : 0);

  bool get _heroHistoryLoading => _activeHeroHistory?.loading ?? false;

  bool get _heroHistoryHasMore {
    if (!_heroHistorySupported) return false;
    return _activeHeroHistory?.hasMore ?? true;
  }

  Future<void> _loadHeroHistory() async {
    if (!mounted || !_heroHistorySupported) return;
    final retryAt = _heroHistoryRetryAt;
    if (retryAt != null && DateTime.now().isBefore(retryAt)) return;
    final reqKey = _heroHistoryRequestKey;
    var h = _heroHistory;
    if (h == null || h.requestKey != reqKey) {
      h = LighthouseHeroHistory(requestKey: reqKey);
    }
    if (h.loading || !h.hasMore) return;
    final before = h.keys.isNotEmpty ? h.keys.first : _heroBaseSeriesKeys.first;
    final started = h.copyWith(loading: true);
    setState(() => _heroHistory = started);
    final period = _period;
    final offset = _periodOffset;
    final tab = _tab;
    final group = _groupFilter;
    try {
      final page = await _service.fetchHeroHistory(
        before: before,
        period: period,
        offset: offset,
        tab: tab,
        group: group,
        // 一页拉满后端上限（90 个桶），日线两三页就够大图从 7 月看起。
        count: 90,
      );
      if (!mounted) return;
      final cur = _heroHistory;
      if (cur == null ||
          cur.requestKey != reqKey ||
          _heroHistoryRequestKey != reqKey) {
        return;
      }
      final next = cur.prependPage(page);
      final added = next.length - cur.length;
      _heroHistoryRetryAt = null;
      _rememberHeroHistory(next);
      setState(() {
        _heroHistory = next;
        final sel = _heroPointIndex;
        if (added > 0 && sel != null) _heroPointIndex = sel + added;
      });
    } catch (e) {
      if (!mounted) return;
      final cur = _heroHistory;
      if (cur == null || cur.requestKey != reqKey) return;
      // 失败后 3 秒内不再自动重试，免得拖动的每一帧都去打接口。
      _heroHistoryRetryAt = DateTime.now().add(const Duration(seconds: 3));
      setState(() {
        _heroHistory = cur.copyWith(
          loading: false,
          error: e.toString().replaceFirst('Exception: ', ''),
        );
      });
    }
  }

  /// 把整期 totals 换成第 i 点（日/周/月…粒度随当前区间）的值。
  ///
  /// 金额直接取日序列；比率**必须**拿换完的金额重算 —— 直接取率序列会让
  /// 分子分母不同源，日粒度下基数常常小到让率失去意义。基数不够时
  /// lighthouseValidRateBase 会返回 0，率就归 0，不硬凑一个好看的百分比。
  /// 一个金额都取不到（序列没下发 / 长度不够）时返回 null，调用方退回整期。
  Map<String, double>? _heroTotalsAtPoint(int i, Map<String, double> base) {
    if (i < 0) return null;
    double? at(String key) {
      final s = _seriesForMetric(key);
      if (i >= s.length) return null;
      return s[i];
    }

    final out = Map<String, double>.from(base);
    var hit = 0;
    for (final key in const <String>[
      'sales',
      'verifiedSales',
      'prepaid',
      'gmv',
      'cost',
      'projectCost',
      'totalCost',
      'spread',
      'profit',
      'netProfit',
      'revenue',
      'netTa',
      'netTaOperating',
      'netTaFinancing',
      'netTaOpCost',
      'netTaProjectCost',
      'netTaBizCost',
      'netTaProjectBiz',
      'handlingFee',
      'platformServiceFee',
    ]) {
      final v = at(key);
      if (v == null) continue;
      out[key] = v;
      hit++;
    }
    if (hit == 0) return null;
    out['costTotal'] = out['totalCost'] ?? 0;
    out['businessCost'] = out['cost'] ?? 0;
    final verified = out['verifiedSales'] ?? 0;
    final sales = out['sales'] ?? 0;
    final anchorTotal = _anchor == _LhAnchor.verified && verified > 0
        ? verified
        : sales;
    final profit = out['profit'] ?? 0;
    final roiBase = lighthouseValidRateBase(
      out['totalCost'] ?? 0,
      minimumBase: _kRoiAnchorMinYuan,
    );
    out['rate'] = roiBase > 0 ? profit / roiBase * 100 : 0.0;
    final gmKey = lighthouseGrossMarginDenominatorKey(
      product: _grossMarginContextProduct,
      group: _grossMarginContextGroup,
      basis: _grossMarginContextBasis,
    );
    final gmRaw = gmKey == 'gmv'
        ? (out['gmv'] ?? 0)
        : gmKey == 'sales'
        ? sales
        : verified;
    final gmBase = lighthouseValidRateBase(
      gmRaw,
      minimumBase: _kRoiAnchorMinYuan,
    );
    out['grossMargin'] = gmBase > 0 ? profit / gmBase * 100 : 0.0;
    out['spreadRate'] = anchorTotal > 0
        ? (out['revenue'] ?? 0) / anchorTotal * 100
        : 0.0;
    return out;
  }

  /// 主 Hero 图例会排几格 —— 趋势区高度按它算，图才不会被图例挤扁。
  /// 只用于算高度，宁可多算一格也不要少算（少算就会把图压没）。
  int _heroLegendMetricCount() {
    bool usable(List<double> s) {
      if (s.length < 2) return false;
      for (final v in s) {
        if (v.abs() > 1e-9) return true;
      }
      return false;
    }

    var n = 0;
    if (_tab == 'netTa') {
      const keys = [
        'netTa',
        'netTaFinancing',
        'netTaOperating',
        'netTaOpCost',
        'netTaProjectCost',
        'netTaBizCost',
      ];
      for (final k in keys) {
        if (usable(_normalizeTrendSeriesForChart(_seriesForMetric(k)))) n++;
      }
      if (lighthouseSeriesHasVisibleData(_netTABankBalanceSeries())) n++;
      return n.clamp(1, 7);
    }
    if (usable(_seriesForMetric('verifiedSales'))) n++;
    if (usable(_seriesForMetric('sales'))) n++;
    if (usable(_seriesForMetric('profit'))) n++;
    if (usable(_seriesForMetric('revenue'))) n++;
    if (usable(_seriesForMetric('totalCost'))) n++;
    if (usable(_seriesForMetric('gmv'))) n++;
    return n.clamp(1, 7);
  }

  // ── 主 Hero 走势全屏大图（只在点日时开放）────────────────────────────────
  //   「本期合计」右边那颗放大钮 → 整张图弹出来铺满屏幕：股票式往前拉、
  //   捏合 / 滚轮缩放、底部全程缩略条。打开期间把历史一页页拉到最早，
  //   有数据的日期都看得到。大图读的是同一份 Hero 状态（选中点 / 聚焦指标
  //   两边同步）：页面每次重建后的下一帧通知大图跟着重建。

  final ValueNotifier<int> _heroFullscreenTick = ValueNotifier<int>(0);
  final GlobalKey<_TrendChartState> _heroFullscreenChartKey =
      GlobalKey<_TrendChartState>();
  bool _heroFullscreenOpen = false;

  /// 大图默认画日 K；顶栏可切回折线。
  final bool _heroFullscreenCandles = true;
  ({
    Map<String, double> totals,
    List<double> profitSeries,
    List<String> labels,
  })?
  _heroTrendArgs;

  /// 大图一打开的视窗：从最近一个 7 月 1 号看到今天。
  static const int _kHeroFullscreenFromMonth = 7;

  /// 大图打开时自动往前拉到的上限（约三年日线），再早的交给手动拖到左沿。
  static const int _kHeroFullscreenHistoryCap = 1100;

  bool get _heroCanOpenFullscreen =>
      widget.sharedCard == null && !_isCustomRange && _tab != 'netTa';

  /// 周 / 月 / 季 / 年线打开时一屏看几个（日线从 7 月起，见 _kHeroFullscreenFromMonth）。
  int? get _heroFullscreenInitialVisible => switch (_period) {
    'week' => 26,
    'month' => 24,
    'quarter' => 12,
    'year' => 999,
    _ => null,
  };

  /// 大图一打开先看这么多天，捏合再放大 / 缩小。
  int get _heroFullscreenViewportCount => math.max(_heroViewportCount, 45);

  void _syncHeroFullscreen() {
    if (!_heroFullscreenOpen) return;
    WidgetsBinding.instance.addPostFrameCallback((_) {
      if (!mounted || !_heroFullscreenOpen) return;
      _heroFullscreenTick.value++;
      _pumpHeroFullscreenHistory();
    });
  }

  void _pumpHeroFullscreenHistory() {
    if (!_heroFullscreenOpen || !_heroHistorySupported) return;
    if (_heroHistoryLoading || !_heroHistoryHasMore) return;
    if (_heroHistoryCount >= _kHeroFullscreenHistoryCap) return;
    unawaited(_loadHeroHistory());
  }

  /// 一级 Hero 卡（产品汇总那张）。走势大图跟它等宽，并从它身上「翻」出来。
  final GlobalKey _heroCardKey = GlobalKey();

  /// Hero 卡在屏幕上的位置（扣掉外壳左右边距 = 卡片本身）。
  Rect? _heroCardRect() {
    final ro = _heroCardKey.currentContext?.findRenderObject();
    if (ro is! RenderBox || !ro.hasSize || !ro.attached) return null;
    final r = ro.localToGlobal(Offset.zero) & ro.size;
    const inset = lighthouseHeroShellMarginH;
    return Rect.fromLTRB(r.left + inset, r.top, r.right - inset, r.bottom);
  }

  /// 数据时间：最近一次拉到数据的时刻（北京时间），没有就用现在。
  String get _heroDataStamp {
    final t = _lastSyncedAt ?? _nowCST();
    String two(int v) => v.toString().padLeft(2, '0');
    return '${t.year}年${t.month}月${t.day}日 ${two(t.hour)}:${two(t.minute)}';
  }

  /// 走势大图在等新数据（切分组 / 切周期）：先转圈，不画旧数据。
  bool _heroFullscreenAwaiting = false;

  /// 大图里选的指标（下拉切）；null = 默认利润。每次打开重置。
  String? _heroFullscreenMetric;

  static const String _kFullscreenTab = 'product';
  static const String _kFullscreenGroup = '能源';

  /// 大图打开时把页面切到「产品 › 能源」。已经是就什么都不做。
  void _enterFullscreenEnergy() {
    if (_tab == _kFullscreenTab) {
      if (_groupFilter != _kFullscreenGroup) {
        _switchGroupForFullscreen(_kFullscreenGroup);
      }
      return;
    }
    // 从供给 / 渠道 / 人效点开：整页切到产品 › 能源（跟点「产品」tab 同一套收拾）。
    final leavingPeople = _tab == 'people';
    setState(() {
      _tab = _kFullscreenTab;
      _heroPointIndex = null;
      _tabBarShowsGroups = true;
      if (_sortField == 'netTa' || _sortField == lighthouseTotalAssetsSortKey) {
        _sortField = 'profit';
      }
      _groupFilter = _kFullscreenGroup;
      _hunFilter = '全部';
      _tradeTypeFilter = '全部';
      _listLimit = _listPageSize;
      _rowsCacheKey = '';
      _rowsCache = null;
      _closeMetricPage();
      _invalidateAiSummary();
      _clearNetTAHeroTransientState();
      if (leavingPeople) {
        _expandedTrendKey = null;
        _heroTraceKey = null;
      }
    });
    final reload = _reloadHeroSummary();
    _heroGroupReload = reload;
    _heroFullscreenAwaiting = true;
    reload.whenComplete(() {
      if (!mounted) return;
      setState(() => _heroFullscreenAwaiting = false);
    });
    // 产品的分类表还没拉回来时，_loadTab 可能把「能源」规整回「全部」：
    // 拉完再确认一次，大图还开着就扳回能源。
    _loadTab(_kFullscreenTab).whenComplete(() {
      if (!mounted || !_heroFullscreenOpen) return;
      if (_tab == _kFullscreenTab && _groupFilter != _kFullscreenGroup) {
        _switchGroupForFullscreen(_kFullscreenGroup);
      }
    });
  }

  /// 大图里数据没对上 / 拉失败了：再拉一次当前分组。
  void _retryFullscreenReload() {
    final reload = _reloadHeroSummary();
    _heroGroupReload = reload;
    setState(() => _heroFullscreenAwaiting = true);
    reload.whenComplete(() {
      if (!mounted) return;
      setState(() => _heroFullscreenAwaiting = false);
    });
  }

  void _switchGroupForFullscreen(String group) {
    _setGroupFilter(group);
    final reload = _heroGroupReload;
    if (reload == null) return;
    _heroFullscreenAwaiting = true;
    reload.whenComplete(() {
      if (!mounted) return;
      setState(() => _heroFullscreenAwaiting = false);
    });
  }

  void _openHeroTrendFullscreen([Rect? origin]) {
    if (_heroFullscreenOpen || _heroTrendArgs == null) return;
    _heroFullscreenOpen = true;
    _heroFullscreenMetric = null;
    // 不管从哪儿点开（哪个 tab、之前选的什么分类），大图一律先看
    // 「产品 › 能源」的利润；数据确认是能源之前只转圈，绝不先画「全部」。
    _enterFullscreenEnergy();
    _pumpHeroFullscreenHistory();
    final theme = Theme.of(context);
    final fromRect = _heroCardRect();
    unawaited(
      Navigator.of(context, rootNavigator: true)
          .push<void>(
            PageRouteBuilder<void>(
              opaque: false,
              barrierDismissible: true,
              barrierLabel: '收起走势大图',
              barrierColor: const Color(0x261E1830),
              transitionDuration: const Duration(milliseconds: 820),
              reverseTransitionDuration: const Duration(milliseconds: 300),
              pageBuilder: (routeCtx, anim, secondary) => Theme(
                data: theme,
                child: _LhPopStage(
                  animation: anim,
                  fromRect: fromRect,
                  originRect: origin,
                  onDismiss: () {
                    LighthouseFeedback.instance.play(
                      LighthouseFeedbackKind.collapse,
                    );
                    Navigator.of(routeCtx).maybePop();
                  },
                  child: ValueListenableBuilder<int>(
                    valueListenable: _heroFullscreenTick,
                    builder: (ctx, tick, child) =>
                        _buildHeroTrendFullscreen(ctx),
                  ),
                ),
              ),
              // 动效全在 _LhPopStage 里（3D 翻起 + 回弹 + 扫光）。
              transitionsBuilder: (ctx, anim, secondary, child) => child,
            ),
          )
          .whenComplete(() => _heroFullscreenOpen = false),
    );
  }

  /// 走势大图弹层：屏幕正中、约四成高。顶部只有一行：
  /// 日期 · 主线读数 …… K 线 / 折线 · 缩放 · 收起。
  /// 大图顶部的 日线 / 周线 / 月线 / 季线 / 年线。跟页面顶上的周期是同一个：
  /// 在这里点周线 = 页面切到「周」，后端按周给数，大图跟着变。
  Widget _heroCandlePeriodTabs(BuildContext ctx) {
    const tabs = [
      ('day', '日线'),
      ('week', '周线'),
      ('month', '月线'),
      ('quarter', '季线'),
      ('year', '年线'),
    ];
    return SizedBox(
      height: 30,
      child: Row(
        children: [
          // 分段：淡紫灰凹槽，选中那一格是一张「入口迷你卡」—— 白卡 + 发丝边 +
          // 紫色柔投影，右下角贴一颗紫色四分之一圆。
          Container(
            padding: const EdgeInsets.all(3),
            decoration: BoxDecoration(
              color: DunesColors.resolve(
                ctx,
                const Color(0xFFF4F2F8),
                role: DunesColorRole.surface,
              ),
              borderRadius: BorderRadius.circular(9),
              border: Border.all(
                color: DunesColors.resolve(
                  ctx,
                  const Color(0xFFEAE5F3),
                  role: DunesColorRole.border,
                ),
                width: 0.6,
              ),
            ),
            child: Row(
              mainAxisSize: MainAxisSize.min,
              children: [
                for (final (key, label) in tabs)
                  Semantics(
                    button: true,
                    selected: _period == key,
                    label: label,
                    child: GestureDetector(
                      behavior: HitTestBehavior.opaque,
                      onTap: () {
                        if (_period == key) return;
                        LighthouseFeedback.instance.play(
                          LighthouseFeedbackKind.select,
                        );
                        _applyPeriod(period: key, offset: 0);
                      },
                      child: Stack(
                        children: [
                          AnimatedContainer(
                            duration: const Duration(milliseconds: 160),
                            curve: Curves.easeOutCubic,
                            padding: const EdgeInsets.symmetric(horizontal: 10),
                            alignment: Alignment.center,
                            decoration: _period == key
                                ? _lhKCardDeco(ctx, radius: 7)
                                : BoxDecoration(
                                    borderRadius: BorderRadius.circular(7),
                                    border: Border.all(
                                      color: Colors.transparent,
                                      width: 0.7,
                                    ),
                                  ),
                            child: Text(
                              label,
                              style: LhTypography.sans(
                                size: 11,
                                color: _period == key
                                    ? DunesColors.resolve(ctx, _LhPlum.deep)
                                    : DunesColors.resolve(
                                        ctx,
                                        const Color(0xFF8A8D94),
                                      ),
                                weight: _period == key
                                    ? FontWeight.w700
                                    : FontWeight.w500,
                                context: ctx,
                              ),
                            ),
                          ),
                          if (_period == key)
                            const Positioned(
                              right: 0,
                              bottom: 0,
                              child: _LhKCorner(size: 8, cardRadius: 7),
                            ),
                        ],
                      ),
                    ),
                  ),
              ],
            ),
          ),
          if (_loading) ...[
            const SizedBox(width: 8),
            SizedBox(
              width: 10,
              height: 10,
              child: CircularProgressIndicator(
                strokeWidth: 1.2,
                color: DunesColors.resolve(ctx, _LhPlum.primary).withAlpha(200),
              ),
            ),
          ],
        ],
      ),
    );
  }

  /// 大图右上角：现在看的是哪一份数据 ——「产品汇总 › 能源 › HUN · 类型」。
  /// 汇总名是主语（深色粗体），筛选是一枚枚淡紫小签，没筛就写「全部」。
  Widget _heroScopeBadge(BuildContext ctx) {
    final groupOptions = _categoryOptions(_tab);
    final canPickGroup = groupOptions.length > 1;
    final parts = <String>[
      if (!canPickGroup && _groupFilter.isNotEmpty && _groupFilter != '全部')
        _groupFilter,
      if (_tab == 'supply' || _tab == 'channel')
        if (_hunFilter != '全部') _hunLabelFor(_hunFilter),
      if (_tab == 'supply' && _tradeTypeFilter != '全部') _tradeTypeFilter,
    ];
    final titleStyle = LhTypography.sans(
      size: 11.5,
      color: DunesColors.resolve(ctx, LhColors.ink),
      weight: FontWeight.w700,
      letterSpacing: 0.2,
      context: ctx,
    );
    Widget chip(String text, {bool muted = false}) => Container(
      padding: const EdgeInsets.symmetric(horizontal: 7, vertical: 2.5),
      decoration: BoxDecoration(
        color: DunesColors.resolve(
          ctx,
          muted ? const Color(0xFFF3F2F6) : _LhPlum.mist,
          role: DunesColorRole.surface,
        ),
        borderRadius: BorderRadius.circular(6),
        border: Border.all(
          color: muted
              ? Colors.transparent
              : DunesColors.resolve(
                  ctx,
                  _LhPlum.primary,
                  role: DunesColorRole.border,
                ).withAlpha(50),
          width: 0.7,
        ),
      ),
      child: Text(
        text,
        maxLines: 1,
        overflow: TextOverflow.ellipsis,
        style: LhTypography.sans(
          size: 10.5,
          color: muted
              ? DunesColors.resolve(ctx, LhColors.mute2)
              : DunesColors.resolve(ctx, _LhPlum.deep),
          weight: FontWeight.w700,
          letterSpacing: 0.2,
          context: ctx,
        ),
      ),
    );
    Widget sep() => Padding(
      padding: const EdgeInsets.symmetric(horizontal: 3),
      child: Icon(
        Icons.chevron_right_rounded,
        size: 13,
        color: DunesColors.resolve(ctx, LhColors.mute2),
      ),
    );
    return Padding(
      padding: const EdgeInsets.only(right: 2),
      child: Row(
        mainAxisSize: MainAxisSize.min,
        children: [
          Container(
            width: 5,
            height: 5,
            decoration: BoxDecoration(
              color: DunesColors.resolve(
                ctx,
                _LhPlum.primary,
                role: DunesColorRole.surface,
              ),
              shape: BoxShape.circle,
            ),
          ),
          const SizedBox(width: 6),
          Text(_l1SummaryTitle, style: titleStyle),
          sep(),
          // 分组可切：能源 / Fintech / 运营商…… 跟着当前 tab 的分类走。
          if (canPickGroup) ...[
            PopupMenuButton<String>(
              tooltip: '切换分组',
              position: PopupMenuPosition.under,
              offset: const Offset(0, 4),
              color: DunesColors.resolve(
                ctx,
                Colors.white,
                role: DunesColorRole.surface,
              ),
              elevation: 6,
              shape: RoundedRectangleBorder(
                borderRadius: BorderRadius.circular(10),
                side: BorderSide(
                  color: DunesColors.resolve(
                    ctx,
                    _LhPlum.line,
                    role: DunesColorRole.border,
                  ),
                  width: 0.8,
                ),
              ),
              onSelected: (g) {
                LighthouseFeedback.instance.play(LighthouseFeedbackKind.select);
                _switchGroupForFullscreen(g);
              },
              itemBuilder: (_) => [
                for (final g in groupOptions)
                  PopupMenuItem<String>(
                    value: g,
                    height: 36,
                    child: Row(
                      children: [
                        Expanded(
                          child: Text(
                            g,
                            style: LhTypography.sans(
                              size: 12,
                              color: g == _groupFilter
                                  ? DunesColors.resolve(ctx, _LhPlum.deep)
                                  : DunesColors.resolve(ctx, LhColors.ink),
                              weight: g == _groupFilter
                                  ? FontWeight.w700
                                  : FontWeight.w500,
                              context: ctx,
                            ),
                          ),
                        ),
                        if (g == _groupFilter)
                          Icon(
                            Icons.check_rounded,
                            size: 14,
                            color: DunesColors.resolve(ctx, _LhPlum.primary),
                          ),
                      ],
                    ),
                  ),
              ],
              child: _LhKStack(
                radius: 7,
                child: Container(
                  padding: const EdgeInsets.fromLTRB(8, 3, 4, 3),
                  decoration: _lhKCardDeco(ctx, radius: 7),
                  child: Row(
                    mainAxisSize: MainAxisSize.min,
                    children: [
                      Text(
                        _groupFilter.isEmpty ? '全部' : _groupFilter,
                        style: LhTypography.sans(
                          size: 10.5,
                          color: DunesColors.resolve(ctx, _LhPlum.deep),
                          weight: FontWeight.w700,
                          letterSpacing: 0.2,
                          context: ctx,
                        ),
                      ),
                      Icon(
                        Icons.expand_more_rounded,
                        size: 14,
                        color: DunesColors.resolve(ctx, _LhPlum.deep),
                      ),
                    ],
                  ),
                ),
              ),
            ),
            if (parts.isNotEmpty) const SizedBox(width: 6),
          ],
          if (parts.isEmpty && !canPickGroup)
            chip('全部', muted: true)
          else
            for (var i = 0; i < parts.length; i++) ...[
              if (i > 0) const SizedBox(width: 4),
              Flexible(child: chip(parts[i])),
            ],
        ],
      ),
    );
  }

  Widget _buildHeroTrendFullscreen(BuildContext ctx) {
    final args = _heroTrendArgs;
    void close() {
      LighthouseFeedback.instance.play(LighthouseFeedbackKind.collapse);
      Navigator.of(ctx).maybePop();
    }

    return GestureDetector(
      behavior: HitTestBehavior.opaque,
      // 点卡片里空白处：收起明细牌（取消选中那一天）。
      onTap: () => _heroFullscreenChartKey.currentState?._clearSelection(),
      child: Material(
        type: MaterialType.transparency,
        child: Container(
          padding: EdgeInsets.zero,
          decoration: BoxDecoration(
            color: DunesColors.resolve(
              ctx,
              LhColors.paper,
              role: DunesColorRole.surface,
            ),
            borderRadius: BorderRadius.circular(lighthouseHeroCardRadius + 2),
            border: Border.all(
              color: DunesColors.resolve(
                ctx,
                _LhPlum.heroEdge,
                role: DunesColorRole.border,
              ),
              width: 0.7,
            ),
          ),
          child: Stack(
            children: [
              Padding(
                padding: const EdgeInsets.fromLTRB(12, 9, 8, 14),
                child: Column(
                  crossAxisAlignment: CrossAxisAlignment.stretch,
                  children: [
                    _heroCandlePeriodTabs(ctx),
                    const SizedBox(height: 8),
                    Expanded(
                      // 新分组 / 新周期的数据没回来前只转圈，不画旧图。
                      // 只在「Hero 数据确实是当前分组的」时才画：summary 的
                      // filterGroup 对不上（还在路上 / 拉失败）就不画旧数据。
                      child:
                          (args == null || _heroFullscreenAwaiting || _loading)
                          ? const Center(child: _LhBrandLoader(size: 44))
                          : !_heroSummaryMatchesGroup
                          ? Center(
                              child: Column(
                                mainAxisSize: MainAxisSize.min,
                                children: [
                                  Text(
                                    '$_groupFilter 的数据没拉到',
                                    style: LhTypography.sans(
                                      size: 12,
                                      color: DunesColors.resolve(
                                        ctx,
                                        LhColors.ink2,
                                      ),
                                      context: ctx,
                                    ),
                                  ),
                                  const SizedBox(height: 8),
                                  TextButton(
                                    onPressed: _retryFullscreenReload,
                                    child: const Text('重新加载'),
                                  ),
                                ],
                              ),
                            )
                          : _buildHeroUnifiedTrendChart(
                              totals: args.totals,
                              profitSeries: args.profitSeries,
                              labels: args.labels,
                              chartMaxHeight: 4000,
                              fullscreen: true,
                              fullscreenTrailing: _heroScopeBadge(ctx),
                            ),
                    ),
                  ],
                ),
              ),
              // 收起钉在卡片最右上角。
              Positioned(
                top: 9,
                right: 6,
                child: _LhKCollapseButton(onTap: close),
              ),
            ],
          ),
        ),
      ),
    );
  }

  Widget _buildHeroUnifiedTrendChart({
    required Map<String, double> totals,
    required List<double> profitSeries,
    required List<String> labels,
    double? chartMaxHeight,
    bool fullscreen = false,
    Widget? fullscreenTrailing,
  }) {
    if (!fullscreen) {
      _heroTrendArgs = (
        totals: totals,
        profitSeries: profitSeries,
        labels: labels,
      );
    }
    if (_tab == 'netTa') {
      final netTa = _normalizeTrendSeriesForChart(_seriesForMetric('netTa'));
      final operating = _normalizeTrendSeriesForChart(
        _seriesForMetric('netTaOperating'),
      );
      final financing = _normalizeTrendSeriesForChart(
        _seriesForMetric('netTaFinancing'),
      );
      final opCost = _normalizeTrendSeriesForChart(
        _seriesForMetric('netTaOpCost'),
      );
      final projectCost = _normalizeTrendSeriesForChart(
        _seriesForMetric('netTaProjectCost'),
      );
      final businessCost = _normalizeTrendSeriesForChart(
        _seriesForMetric('netTaBizCost'),
      );
      return LayoutBuilder(
        builder: (context, _) {
          final overlaySlot = lighthouseNetTAHeroOverlaySlot(_expandedTrendKey);
          final chartLabels = labels.isNotEmpty
              ? labels
              : _heroTrendLabels(netTa.length);
          // 银行余额是「日度存量」，这张图的横轴却跟着日/周/月/季/年变。
          // 直接按标签对点会整段对不上（对不上就返回全 0，再被判成没数据，
          // 于是余额线在图上根本不出现）—— 这里按轴的口径折进每一格，
          // 每格取期末余额，不求和。日期比标签准，能拿到日期就用日期。
          final bankValues = _netTABankBalanceSeries();
          final bankDates = _netTABankBalanceSeriesDates();
          final bankSeries = lighthouseFoldStockToAxis(
            axisLabels: chartLabels,
            seriesLabels: bankDates.length == bankValues.length
                ? bankDates
                : _netTABankBalanceSeriesLabels(),
            values: bankValues,
          );
          final stock = lighthouseSeriesHasVisibleData(bankSeries)
              ? bankSeries
              : const <double>[];
          final bankChange = _netTABankBalanceChange();
          final periodStock = (_bundle?.metrics['netTaBankBalance'] as num?)
              ?.toDouble();
          return _TrendChart(
            key: const ValueKey('hero-overview-netTa'),
            legendNamesOnly: true,
            onSelectedIndexChanged: _onHeroPointSelected,
            lastPointIsPeriod: _heroLastPointIsPeriod,
            selectedIndex: _heroPointIndex,
            suppressPointMom: lighthouseHeroSuppressPointMom,
            labels: chartLabels,
            scale: netTa,
            scaleLabel: '净TA',
            scaleAlt: financing,
            scaleAltLabel: '筹资活动',
            revenue: operating,
            revenueLabel: '经营活动',
            cost: opCost,
            costLabel: '经营成本',
            profit: projectCost,
            profitLabel: '项目成本',
            costAlt: businessCost,
            costAltLabel: '业务成本',
            stock: stock,
            stockLabel: '银行余额',
            unsignedSlots: const {'cost', 'profit', 'costAlt', 'scaleAlt'},
            periodScale: totals['netTa'],
            periodScaleAlt: totals['netTaFinancing'],
            periodRevenue: totals['netTaOperating'],
            periodCost: totals['netTaOpCost'],
            periodProfit: totals['netTaProjectCost'],
            periodCostAlt: totals['netTaBizCost'],
            periodStock: periodStock,
            periodScaleDeltaPct: _deltaForMetric('netTa')?.pct,
            periodScaleAltDeltaPct: _deltaForMetric('netTaFinancing')?.pct,
            periodRevenueDeltaPct: _deltaForMetric('netTaOperating')?.pct,
            periodCostDeltaPct: _deltaForMetric('netTaOpCost')?.pct,
            periodProfitDeltaPct: _deltaForMetric('netTaProjectCost')?.pct,
            periodCostAltDeltaPct: _deltaForMetric('netTaBizCost')?.pct,
            periodStockDeltaPct: bankChange?.pct,
            showHeader: false,
            showScrubHint: false,
            fitHeight: true,
            chartHeight: 48,
            rangeLabel: _heroTrendRangeLabel(chartLabels),
            title: _heroTrendTitle(),
            partialPeriod: _periodInProgress,
            soloKey: overlaySlot,
            onSoloChanged: (slot) {
              setState(() {
                final key = lighthouseNetTAHeroMetricFromSlot(slot);
                _expandedTrendKey = key;
                _heroTraceKey = key != null && _heroFormula(key) != null
                    ? key
                    : null;
              });
            },
          );
        },
      );
    }
    // 不等人拖：主 Hero 一出来就把前一段历史先拉好，第一下拖动就有东西可看。
    _scheduleHeroHistoryPreload();
    final preferVerified = _anchor == _LhAnchor.verified;
    final verified = _seriesForMetric('verifiedSales');
    final sales = _seriesForMetric('sales');
    var scaleKey = preferVerified ? 'verifiedSales' : 'sales';
    var scale = preferVerified ? verified : sales;
    var altKey = preferVerified ? 'sales' : 'verifiedSales';
    var scaleAlt = preferVerified ? sales : verified;
    bool usable(List<double> s) {
      if (s.length < 2) return false;
      for (final v in s) {
        if (v.abs() > 1e-9) return true;
      }
      return false;
    }

    if (!usable(scale) && usable(scaleAlt)) {
      scaleKey = altKey;
      scale = scaleAlt;
      altKey = '';
      scaleAlt = const <double>[];
    } else if (!usable(scale)) {
      scale = const <double>[];
      altKey = '';
      scaleAlt = const <double>[];
    } else if (!usable(scaleAlt)) {
      altKey = '';
      scaleAlt = const <double>[];
    }
    String scaleNameOf(String k) => k == 'verifiedSales' ? '核销规模' : '销售规模';
    final gmv = _normalizeTrendSeriesForChart(_seriesForMetric('gmv'));
    final showGmv = usable(gmv) || (totals['gmv'] ?? 0).abs() > 1e-9;
    final focus = _expandedTrendKey;
    final overlaySlot = lighthouseHeroOverlaySoloSlot(
      metricKey: focus,
      scaleKey: scaleKey,
      scaleAltKey: altKey,
      hasScale: scale.isNotEmpty,
      hasScaleAlt: scaleAlt.isNotEmpty,
      hasGmv: showGmv,
    );
    final swapMetric = focus != null && overlaySlot == null;

    return LayoutBuilder(
      builder: (context, box) {
        final maxH = box.maxHeight.isFinite && box.maxHeight > 0
            ? box.maxHeight
            : lighthouseCompactHeroSparkHeight;
        // v24 · 图例不再按固定 76px 估：它现在是面板式的，几个指标就几行，
        //   估少了走势图会被挤成一条缝。这里按行数实算，图保底不低于
        //   [lighthouseTrendChartMinHeight]。
        final reserved = lighthouseHeroTrendReservedHeightFor(
          screenWidth: MediaQuery.sizeOf(context).width,
          legendWidth: box.maxWidth,
          metricCount: _heroLegendMetricCount(),
          hasForecastStrip: _isCurrentMonthView && scale.isNotEmpty,
        );
        final chartMax =
            chartMaxHeight ?? lighthouseCompactHeroChartMaxHeightWide;
        final chartH = (maxH - reserved)
            .clamp(math.min(lighthouseTrendChartMinHeight, chartMax), chartMax)
            .toDouble();
        if (swapMetric) {
          return _heroMetricSoloTrendChart(
                focus!,
                totals,
                fitHeight: true,
                chartHeight: chartH,
                showScrubHint: false,
              ) ??
              _heroMetricEmptyTrend(focus!);
        }
        return _TrendChart(
          key: fullscreen
              ? _heroFullscreenChartKey
              : const ValueKey('hero-overview'),
          viewportCount: fullscreen
              ? _heroFullscreenViewportCount
              : _heroInlineViewportCount,
          initialViewEnd: fullscreen ? null : widget.sharedCard?.viewEnd,
          onViewEndChanged: fullscreen ? null : (value) => _heroViewEnd = value,
          zoomable: fullscreen,
          legendCompact: fullscreen,
          legendNamesOnly: true,
          legendTrailing: fullscreenTrailing,
          candles: fullscreen && _heroFullscreenCandles,
          initialFromMonth: fullscreen && _period == 'day'
              ? _kHeroFullscreenFromMonth
              : null,
          initialVisible: fullscreen ? _heroFullscreenInitialVisible : null,
          candleUnit: _period,
          statusStamp: fullscreen ? _heroDataStamp : null,
          onExpand: !fullscreen && _heroCanOpenFullscreen
              ? _openHeroTrendFullscreen
              : null,
          historyCount: _heroHistoryCount,
          historyLoading: _heroHistoryLoading,
          historyHasMore: _heroHistoryHasMore,
          onNeedHistory: _loadHeroHistory,
          onSelectedIndexChanged: _onHeroPointSelected,
          lastPointIsPeriod: _heroLastPointIsPeriod,
          selectedIndex: _heroPointIndex,
          suppressPointMom: lighthouseHeroSuppressPointMom,
          labels: labels,
          revenue: _seriesForMetric('revenue'),
          cost: _seriesForMetric('totalCost'),
          profit: profitSeries,
          scale: scale,
          scaleLabel: scaleNameOf(scaleKey),
          scaleAlt: scaleAlt,
          scaleAltLabel: altKey.isEmpty ? '' : scaleNameOf(altKey),
          costAlt: showGmv ? gmv : const <double>[],
          costAltLabel: showGmv ? 'GMV' : '',
          periodScale: totals[scaleKey],
          periodScaleAlt: altKey.isEmpty ? null : totals[altKey],
          periodCostAlt: showGmv ? totals['gmv'] : null,
          periodScaleDeltaPct: _deltaForMetric(scaleKey)?.pct,
          periodRevenueDeltaPct: _deltaForMetric('revenue')?.pct,
          periodCostDeltaPct: _deltaForMetric('totalCost')?.pct,
          periodScaleAltDeltaPct: altKey.isEmpty
              ? null
              : _deltaForMetric(altKey)?.pct,
          periodCostAltDeltaPct: showGmv ? _deltaForMetric('gmv')?.pct : null,
          scaleForecast: scale.isEmpty
              ? null
              : _heroPaceForecast(scaleKey, scale.last),
          profitForecast: profitSeries.isEmpty
              ? null
              : _heroPaceForecast(
                  'profit',
                  profitSeries.last,
                  linearFallback: false,
                ),
          // 报告入口属于「月 · 本月」视图本身，不能再跟日历史请求的瞬时状态
          // 绑定。历史尚未回来时入口也保留，点击后由 _openForecastReport 给出
          // 明确的“计算中 / 数据不足”反馈；否则网络慢一下入口就像被删掉了。
          onOpenForecastReport: _isCurrentMonthView
              ? (profit) => _openForecastReport(
                  profit ? 'profit' : scaleKey,
                  profit ? '利润' : scaleNameOf(scaleKey),
                )
              : null,
          paceDays: _monthPaceDays,
          partialPeriod: _periodInProgress,
          rangeLabel: _heroTrendRangeLabel(labels),
          title: _heroTrendTitle(),
          showHeader: false,
          showScrubHint: false,
          fitHeight: true,
          chartHeight: chartH,
          periodRevenue: totals['revenue'],
          periodCost: totals['totalCost'],
          periodProfit: totals['profit'],
          periodProfitDeltaPct: _deltaForMetric('profit')?.pct,
          // 大图「显示全部」时默认看利润，不看核销规模。
          soloKey: fullscreen
              ? (_heroFullscreenMetric ?? 'profit')
              : overlaySlot,
          formulaExpression:
              !lighthouseHeroShowsFormulaBar ||
                  overlaySlot == null ||
                  focus == null
              ? null
              : _heroFormula(focus!)?.expression,
          onSoloChanged: fullscreen
              ? (slot) => setState(() => _heroFullscreenMetric = slot)
              : (slot) {
                  setState(() {
                    if (slot == null) {
                      _expandedTrendKey = null;
                      _heroTraceKey = null;
                      return;
                    }
                    final key = switch (slot) {
                      'profit' => 'profit',
                      'revenue' => 'revenue',
                      'cost' => 'totalCost',
                      'scale' => scaleKey,
                      'scaleAlt' => altKey.isEmpty ? scaleKey : altKey,
                      'costAlt' => showGmv ? 'gmv' : _expandedTrendKey,
                      _ => _expandedTrendKey,
                    };
                    _expandedTrendKey = key;
                    _heroTraceKey = key != null && _heroFormula(key) != null
                        ? key
                        : null;
                  });
                },
        );
      },
    );
  }

  /// 一级主 Hero —— 产品 / 供给方 / 渠道 / 人效 / 净TA共用同一具躯壳。
  ///
  /// 这五个 tab 不是五个页面，是同一份区间数据的五种分组方式：Hero 的标题、
  /// 大数、走势、三列指标带、stat rail 全部同构，换 tab 只换「按什么分组」。
  /// 人效也在其中 —— 人只是又一个分组键（账本按负责人聚合），不该有专属版式。
  /// 主 Hero 能挂资产：一级的产品 / 供给 / 渠道（资产是公司级最新快照，
  /// 跟日周月与分类筛选无关，人效 / 净TA 不挂）。
  bool get _heroAssetsEligible =>
      lighthouseFundsHeroVisible(
        hideSensitiveFinance: _hidesSensitiveFinance,
      ) &&
      const {'product', 'supply', 'channel'}.contains(_tab) &&
      _detailKey == null &&
      widget.sharedCard == null &&
      // 资金 / 资产是省级资管数，拆不出专题那一份。
      !_inTopic;

  /// 合计 / 中石油 / 中石化 三行（受限账号只合计看得到的省）。
  List<LighthouseAssetFooterLine> get _heroAssetLines {
    if (!_heroAssetsEligible || _fundPoolSnapshot.isEmpty) {
      return const <LighthouseAssetFooterLine>[];
    }
    final rows = _tab == 'supply'
        ? _currentRows
        : (_bundle?.rowsOf('supply') ?? const <Map<String, dynamic>>[]);
    return lighthouseSupplyAssetFooter(rows, _fundPoolSnapshot);
  }

  LighthouseAssetFooterLine? _heroAssetLine(String key) {
    for (final line in _heroAssetLines) {
      if (line.key == key) return line;
    }
    return null;
  }

  /// 资金池原来只在进供给页时拉；主 Hero 要挂总资产，一级页面首帧后补拉一次。
  void _ensureHeroFundPool() {
    // 有缓存那份也要按新鲜度刷新一次（每轮加载最多一次，见 _heroFundPoolTried）。
    if (!_heroAssetsEligible ||
        _fundPoolLoading ||
        (!_fundPoolSnapshot.isEmpty &&
            LighthouseFundPoolCache.isFresh(_fundPoolCacheKey)) ||
        _heroFundPoolTried) {
      return;
    }
    _heroFundPoolTried = true;
    WidgetsBinding.instance.addPostFrameCallback((_) {
      if (mounted) unawaited(_loadFundPool());
    });
  }

  String _heroWan(double? v) {
    if (v == null || !v.isFinite) return '—';
    final p = lighthouseFormatFundPoolWanParts(v.abs());
    return '${v < 0 ? '−' : ''}${p.number}${p.unit}';
  }

  /// 当前板块没勾「经营性现金流」时，预收净增和经营性净现金流整块不出现。
  /// 旧接口没有 cashFlowAccess 时照旧显示。行上 prepaidStatus=hidden 是服务端已经裁过的数。
  bool _showOperatingCashFlow({Map<String, dynamic>? row}) {
    if (row != null && row['prepaidStatus']?.toString() == 'hidden') {
      return false;
    }
    final access = _bundle?.metrics['cashFlowAccess'];
    if (access is Map) {
      final key = _tab == 'netTa' ? 'netTa' : _tab;
      final flag = access[key];
      if (flag is bool) return flag;
    }
    return true;
  }

  /// 预收净增（本期流量）的读数：值 + 环比，点了主走势图切到预收净增。
  ({double value, String delta, bool active}) _heroPrepaidReadout(
    Map<String, double> heroTotals,
  ) {
    final d = _heroPointIndex != null
        ? _deltaAtHeroPoint('prepaid')
        : _deltaForMetric('prepaid');
    return (
      value: heroTotals['prepaid'] ?? 0,
      delta: d == null || !lighthouseDeltaPctShown(d.pct)
          ? '—'
          : '${d.isUp ? '↑' : '↓'}'
                '${d.pct.abs().toStringAsFixed(d.pct.abs() >= 10 ? 0 : 1)}%',
      active:
          _expandedTrendKey != null &&
          lighthouseLedgerMetricKeysMatch(_expandedTrendKey!, 'prepaid'),
    );
  }

  void _toggleHeroPrepaidTrend() {
    LighthouseFeedback.instance.play(LighthouseFeedbackKind.select);
    final next = lighthouseHeroMetricActivateAfterTap(
      _expandedTrendKey,
      'prepaid',
    );
    setState(() {
      _expandedTrendKey = next.focus;
      _heroTraceKey = next.trace;
    });
  }

  // ── 主 Hero · 滑动（2026-10-21）──────────────────────────────────────────
  //   手势和几何在 lighthouse_hero_swipe.dart；这里只管内容：
  //   竖条、资金与资产页、拉宽后多看几天。

  /// 主 Hero 走势一屏几个点：拉宽后多看一倍（日线 7 → 14），封顶 31。
  /// 宽度多了 ~50%，点数翻倍后点距反而略密 —— 拉宽就是为了看更长的一段。
  int get _heroInlineViewportCount {
    final base = _heroViewportCount;
    if (!_heroTrendWide || base < 2 || widget.sharedCard != null) return base;
    return math.min(31, base * 2);
  }

  void _setHeroTrendWide(bool wide) {
    if (_heroTrendWide == wide) return;
    LighthouseFeedback.instance.play(
      wide ? LighthouseFeedbackKind.expand : LighthouseFeedbackKind.collapse,
    );
    setState(() => _heroTrendWide = wide);
    // 宽了要多画一倍的点：历史还没拉过就现在拉。
    if (wide) _scheduleHeroHistoryPreload();
  }


  /// 切到「资金」页时拉一次未结账款；10 分钟内不重拉（后端也有缓存）。
  void _ensureBillOutstanding({bool force = false}) {
    if (!lighthouseBillOutstandingEnabled ||
        _billsLoading ||
        widget.sharedCard != null ||
        _inTopic) {
      return;
    }
    final at = _billsFetchedAt;
    if (!force && at != null && DateTime.now().difference(at).inMinutes < 10) {
      return;
    }
    _billsLoading = true;
    unawaited(
      _service
          .fetchBillOutstanding()
          .then((data) {
            if (!mounted) return;
            setState(() {
              _bills = LhBillOutstanding.fromJson(data);
              _billsFetchedAt = DateTime.now();
            });
          })
          .catchError((Object _) {
            // 拉不到就不出这块，不在资金页上挂错误。
            _billsFetchedAt = DateTime.now();
          })
          .whenComplete(() => _billsLoading = false),
    );
  }

  /// 资金页：规模 / 成本 / 利润下面的「账款」面板（同一套面板样式）。
  Widget _buildBillPanel() {
    final bills = _bills;
    if (!lighthouseBillOutstandingEnabled || bills == null || !bills.visible) {
      return const SizedBox.shrink();
    }
    return Padding(
      padding: const EdgeInsets.only(top: lighthouseHeroCardGap),
      child: LhBillPanel(
        data: bills,
        focus: _billFocusActive ? _billFocus : null,
        // 再点一次已选的那格：回到总资产。
        onPick: (side) => _setBillFocus(_billFocus == side ? null : side),
        panelColor: DunesColors.resolve(
          context,
          const Color(lighthouseLedgerSummaryNeutralPanelValue),
          role: DunesColorRole.surface,
        ),
        edgeColor: DunesColors.resolve(
          context,
          const Color(lighthouseHeroPanelNeutralEdgeValue),
          role: DunesColorRole.border,
        ),
        radius: lighthouseLedgerSummaryPanelRadius,
      ),
    );
  }

  void _setBillFocus(String? side) {
    if (_billFocus == side) return;
    LighthouseFeedback.instance.play(LighthouseFeedbackKind.select);
    setState(() {
      _billFocus = side;
      _heroPointIndex = null;
    });
  }

  void _openBillSheet([String? side]) {
    final bills = _bills;
    if (bills == null || !bills.visible) return;
    LighthouseFeedback.instance.play(LighthouseFeedbackKind.expand);
    unawaited(
      showLighthouseBillOutstandingSheet(context, bills, initialSide: side),
    );
  }

  /// 大数卡第二页选中账款时：和总资产页同一副骨架 ——
  ///
  ///     [🧾 应付未付款]  统计日 10-27       ← 同一颗口径胶囊
  ///     2.29 亿                              ← 同字号
  ///     4,532 张 · 其中结束日超 7 天 63%
  ///     ↺ 回总资产
  ///     ───────────────
  ///     应收 1284万  ⟍▲⟋  应付 2.29亿        ← 迷你天平（点开按对方明细）
  ///     净应付 2.16亿 · 按对方查看 ›
  Widget _buildBillMasthead(LhBillOutstanding bills, String side) {
    final mute2 = DunesColors.resolve(context, LhColors.mute2);
    final ink2 = DunesColors.resolve(context, LhColors.ink2);
    final plum = DunesColors.resolve(context, _LhPlum.primary);
    final t = bills.totalOf(side);
    final label = side == 'AR' ? '应收未回款' : '应付未付款';
    final sub = t == null
        ? '这一侧没查'
        : '${t.unpaidCount} 张 · 其中结束日超 ${bills.graceDays} 天 '
              '${(t.overdueShare * 100).round()}%';
    return Padding(
      // 顶部留 38 给「利润 | 资金」切换条（和总资产页同一个内边距）。
      padding: const EdgeInsets.fromLTRB(8, 38, 8, 8),
      child: Column(
        crossAxisAlignment: CrossAxisAlignment.stretch,
        children: [
          Expanded(
            child: LayoutBuilder(
              builder: (context, box) => FittedBox(
                fit: BoxFit.scaleDown,
                alignment: Alignment.centerLeft,
                child: SizedBox(
                  width: box.maxWidth,
                  child: Column(
                    mainAxisSize: MainAxisSize.min,
                    crossAxisAlignment: CrossAxisAlignment.start,
                    mainAxisAlignment: MainAxisAlignment.center,
                    children: [
                      Wrap(
                        spacing: 6,
                        runSpacing: 3,
                        crossAxisAlignment: WrapCrossAlignment.center,
                        children: [
                          _heroPageChip(Icons.receipt_long_outlined, label),
                          if (bills.asOfShort.isNotEmpty)
                            Text(
                              '统计日 ${bills.asOfShort}',
                              maxLines: 1,
                              style: LhTypography.mono(
                                size: 9,
                                color: mute2,
                                height: 1.0,
                                context: context,
                              ),
                            ),
                          if (bills.fixture)
                            Text(
                              '样例',
                              style: LhTypography.sans(
                                size: 9,
                                color: DunesColors.resolve(
                                  context,
                                  const Color(0xFF8A6A12),
                                ),
                                height: 1.0,
                                context: context,
                              ),
                            ),
                        ],
                      ),
                      const SizedBox(height: 6),
                      FittedBox(
                        fit: BoxFit.scaleDown,
                        alignment: Alignment.centerLeft,
                        child: _heroSplitWan(
                          t?.unpaidAmount,
                          size: lighthouseHeroMastheadFontSize,
                          unitSize: 10.5,
                          color: DunesColors.resolve(context, _LhPlum.heroNum),
                        ),
                      ),
                      const SizedBox(height: 5),
                      Text(
                        sub,
                        maxLines: 2,
                        overflow: TextOverflow.ellipsis,
                        style: LhTypography.sans(
                          size: 10,
                          color: ink2,
                          height: 1.25,
                          context: context,
                        ),
                      ),
                      const SizedBox(height: 6),
                      Semantics(
                        button: true,
                        label: '回到总资产',
                        child: GestureDetector(
                          behavior: HitTestBehavior.opaque,
                          onTap: () => _setBillFocus(null),
                          child: Container(
                            padding: const EdgeInsets.fromLTRB(6, 3, 8, 3),
                            decoration: BoxDecoration(
                              color: DunesColors.resolve(
                                context,
                                _LhPlum.primary,
                                role: DunesColorRole.surface,
                              ).withAlpha(14),
                              borderRadius: BorderRadius.circular(10),
                            ),
                            child: Row(
                              mainAxisSize: MainAxisSize.min,
                              children: [
                                Icon(Icons.replay_rounded, size: 11, color: plum),
                                const SizedBox(width: 3),
                                Text(
                                  '回总资产',
                                  style: LhTypography.sans(
                                    size: 9.5,
                                    color: plum,
                                    weight: FontWeight.w600,
                                    height: 1.0,
                                    context: context,
                                  ),
                                ),
                              ],
                            ),
                          ),
                        ),
                      ),
                    ],
                  ),
                ),
              ),
            ),
          ),
          LhBillMiniBalance(
            data: bills,
            onTap: () => _openBillSheet(side),
          ),
        ],
      ),
    );
  }

  void _setHeroKpiPage(int page) {
    if (_heroKpiPage == page) return;
    setState(() {
      _heroKpiPage = page;
      // 翻回利润页再回来，从总资产看起。
      _billFocus = null;
    });
    if (page == 1) _ensureBillOutstanding();
  }

  /// 「资金与资产」面板的展开 / 收起（大数卡底部那一格和资金页的「明细」共用）。
  void _toggleHeroAssetPanel() {
    final assetKey = _tab == 'supply'
        ? (_supplySelectedAssetCategory ?? 'total')
        : 'total';
    final open = _heroAssetOpen;
    LighthouseFeedback.instance.play(
      open ? LighthouseFeedbackKind.collapse : LighthouseFeedbackKind.expand,
    );
    setState(() {
      _heroAssetOpen = !open;
      if (!open) {
        _heroAssetKey = _heroAssetLine(assetKey) == null ? 'total' : assetKey;
        _supplyAssetPointIndex = null;
      }
    });
  }

  // ── 主 Hero · 上滑收起（2026-10-21）──────────────────────────────────
  //   Hero 底下一根把手：往上一推，大数 / 走势 / 规模成本利润收成一条摘要，
  //   下面产品 / 供给 / 渠道列表顶上来，方便边看列表边对数；往下拉或点摘要展开。

  void _setHeroFolded(bool folded) {
    if (_heroFolded == folded) return;
    LighthouseFeedback.instance.play(
      folded ? LighthouseFeedbackKind.collapse : LighthouseFeedbackKind.expand,
    );
    setState(() => _heroFolded = folded);
  }

  /// 规模 / 成本 / 利润下面那根把手（手势在 [LighthouseFoldSection] 里）。
  /// [t]：0 展开 · 1 收起，拖动中带小数 —— 箭头跟着转、文案过半换。
  Widget _buildHeroFoldHandle(double t) {
    final mute2 = DunesColors.resolve(context, LhColors.mute2);
    final plum = DunesColors.resolve(context, _LhPlum.primary);
    final folded = t >= 0.5;
    return Semantics(
      button: true,
      label: folded ? '展开规模成本利润' : '收起规模成本利润',
      // 整行都是热区（原来只有中间一小块），高 32，手指好找。
      child: SizedBox(
        height: 32,
        child: Column(
          mainAxisAlignment: MainAxisAlignment.center,
          children: [
            Container(
              width: 30 + 8 * t,
              height: 4,
              decoration: BoxDecoration(
                color: plum.withAlpha((60 + 60 * t).round()),
                borderRadius: BorderRadius.circular(2),
              ),
            ),
            const SizedBox(height: 5),
            Row(
              mainAxisSize: MainAxisSize.min,
              children: [
                Transform.rotate(
                  angle: math.pi * t,
                  child: Icon(
                    Icons.keyboard_arrow_up_rounded,
                    size: 12,
                    color: mute2,
                  ),
                ),
                // 2026-10-26 · 「上滑收起」四个字去掉，把手和手势照旧；收起后才写怎么展开。
                if (folded) ...[
                  const SizedBox(width: 2),
                  Text(
                    '下拉展开 规模 · 成本 · 利润',
                    style: LhTypography.sans(
                      size: 9,
                      color: mute2,
                      weight: FontWeight.w500,
                      height: 1.0,
                      context: context,
                    ),
                  ),
                ],
              ],
            ),
          ],
        ),
      ),
    );
  }

  // 10.26 起收起只收规模 / 成本 / 利润，这条整卡摘要不再挂；留着备用。
  // ignore: unused_element
  /// 收起后的一条摘要：大数（本日利润）· 规模（核销 / 销售）· 总资产（或 GMV）。
  Widget _buildHeroFoldedStrip({
    required String mastheadKey,
    required double value,
    required bool isRate,
    required bool isNeg,
    required ({double pct, bool isUp})? delta,
    required Map<String, double> heroTotals,
  }) {
    final mute = DunesColors.resolve(context, LhColors.mute);
    final ink = DunesColors.resolve(context, LhColors.ink);

    Widget deltaText(({double pct, bool isUp})? d, {bool rate = false}) {
      if (d == null || !lighthouseDeltaPctShown(d.pct, isRate: rate)) {
        return const SizedBox.shrink();
      }
      final a = d.pct.abs();
      return Padding(
        padding: const EdgeInsets.only(left: 4),
        child: Text(
          '${d.isUp ? '↑' : '↓'}${a.toStringAsFixed(a >= 10 ? 0 : 1)}'
          '${rate ? 'pp' : '%'}',
          maxLines: 1,
          softWrap: false,
          style: _tabular(
            LhTypography.mono(
              size: 10.5,
              color: DunesColors.resolve(
                context,
                d.isUp ? LhColors.neg : LhColors.pos,
              ),
              weight: FontWeight.w700,
              height: 1.0,
              context: context,
            ),
          ),
        ),
      );
    }

    Widget metric(
      String label,
      String number,
      String unit,
      Color color,
      Widget trailing,
    ) => Expanded(
      child: Column(
        crossAxisAlignment: CrossAxisAlignment.start,
        mainAxisSize: MainAxisSize.min,
        children: [
          Text(
            label,
            maxLines: 1,
            overflow: TextOverflow.ellipsis,
            style: LhTypography.sans(
              size: 9.5,
              color: mute,
              weight: FontWeight.w500,
              height: 1.1,
              context: context,
            ),
          ),
          const SizedBox(height: 3),
          Row(
            crossAxisAlignment: CrossAxisAlignment.center,
            children: [
              Flexible(
                child: FittedBox(
                  fit: BoxFit.scaleDown,
                  alignment: Alignment.centerLeft,
                  child: Text.rich(
                    TextSpan(
                      children: [
                        TextSpan(
                          text: number,
                          style: _tabular(
                            LhTypography.number(
                              size: 15,
                              color: color,
                              context: context,
                            ),
                          ).copyWith(height: 1.0),
                        ),
                        TextSpan(
                          text: unit,
                          style: LhTypography.sans(
                            size: 9,
                            color: mute,
                            weight: FontWeight.w500,
                            context: context,
                          ),
                        ),
                      ],
                    ),
                    maxLines: 1,
                    softWrap: false,
                  ),
                ),
              ),
              trailing,
            ],
          ),
        ],
      ),
    );

    Widget divider() => Container(
      width: 0.7,
      height: 26,
      margin: const EdgeInsets.symmetric(horizontal: 8),
      color: DunesColors.resolve(
        context,
        LhColors.line2,
        role: DunesColorRole.surface,
      ),
    );

    String money(double v) => '${v < 0 ? '−' : ''}${_fmtMoney(v.abs())}';

    final headColor = _grossProfitValueColor(
      mastheadKey,
      value,
      isNeg
          ? DunesColors.resolve(context, LhColors.pos)
          : DunesColors.resolve(context, _LhPlum.heroNum),
    );
    final scaleKey = _anchor == _LhAnchor.verified ? 'verifiedSales' : 'sales';
    final scaleV = heroTotals[scaleKey] ?? 0;
    final assetTotal = _heroAssetsEligible
        ? _heroAssetLine('total')?.amounts?.totalAssets
        : null;
    final third = assetTotal != null
        ? (() {
            final p = lighthouseFormatFundPoolWanParts(assetTotal.abs());
            return metric(
              '总资产',
              '${assetTotal < 0 ? '−' : ''}${p.number}',
              p.unit,
              DunesColors.resolve(context, _LhPlum.heroNum),
              const SizedBox.shrink(),
            );
          })()
        : metric(
            'GMV',
            money(heroTotals['gmv'] ?? 0),
            _unitMoney(heroTotals['gmv'] ?? 0),
            ink,
            deltaText(_deltaForMetric('gmv')),
