              metric(
                lighthouseHeroMetricPeriodLabel(_period, mastheadKey),
                isRate
                    ? value.toStringAsFixed(2)
                    : '${isNeg ? '−' : ''}${_fmtMoney(value.abs())}',
                isRate ? '%' : _unitMoney(value.abs()),
                headColor,
                deltaText(delta, rate: isRate),
              ),
              divider(),
              metric(
                scaleKey == 'verifiedSales' ? '核销额' : '销售额',
