  /// 「1.02亿」拆成数 + 单位两段排（单位小一号、灰）。
  Widget _heroSplitWan(
    double? v, {
    required double size,
    Color? color,
    double unitSize = 9,
  }) {
    final mute = DunesColors.resolve(context, LhColors.mute);
    if (v == null || !v.isFinite) {
      return Text(
        '—',
        style: _tabular(
          LhTypography.number(
            size: size * 0.8,
            color: DunesColors.resolve(context, LhColors.mute2),
            context: context,
          ),
        ),
      );
    }
    final p = lighthouseFormatFundPoolWanParts(v.abs());
    return Text.rich(
      TextSpan(
        children: [
          TextSpan(
            text: '${v < 0 ? '−' : ''}${p.number}',
            style: _tabular(
              LhTypography.number(
                size: size,
                color: color ?? DunesColors.resolve(context, LhColors.ink),
                context: context,
              ),
            ).copyWith(height: 1.0, letterSpacing: size >= 24 ? -0.6 : -0.2),
          ),
          TextSpan(
            text: p.unit,
            style: LhTypography.sans(
              size: unitSize,
              color: mute,
              weight: FontWeight.w500,
              context: context,
            ),
          ),
        ],
      ),
      maxLines: 1,
      softWrap: false,
    );
  }

  /// 迷你柱：最近 [count] 期，最后一根（今天）高亮。
  /// [signed] = 正负两向（预收净增），否则从底往上（利润）。
  Widget _heroMiniBars(
    List<double> series, {
    required bool signed,
    required Color today,
    required Color pos,
    Color? neg,
    Color? todayNeg,
    int count = 7,
    int? endIndex,
  }) {
    if (series.isEmpty) return const SizedBox.shrink();
    // 走势上点了某一天：柱子换成「截到那一天」的最近 [count] 根，那一根高亮。
    final end = (endIndex != null && endIndex >= 0 && endIndex < series.length)
        ? endIndex + 1
        : series.length;
    final vals = series.sublist(math.max(0, end - count), end);
    final mx = vals.fold<double>(0, (m, v) => math.max(m, v.abs()));
    // 有正负时：基线按「正的最大 : 负的最大」落位，全负就贴顶、柱往下长满。
    // 原来固定在正中、只用一半高度，全是负数时柱子缩成一条线。
    final pMax = vals.fold<double>(0, (m, v) => v > 0 ? math.max(m, v) : m);
    final nMax = vals.fold<double>(0, (m, v) => v < 0 ? math.max(m, -v) : m);
    final pn = pMax + nMax;
    return LayoutBuilder(
      builder: (context, box) {
        final h = box.maxHeight.isFinite ? box.maxHeight : 18.0;
        final baseY = pn <= 0 ? h / 2 : h * pMax / pn;
        return Row(
          crossAxisAlignment: CrossAxisAlignment.stretch,
          children: [
            for (var i = 0; i < vals.length; i++) ...[
              if (i > 0) SizedBox(width: signed ? 1.5 : 3),
              Expanded(
                child: Builder(
                  builder: (_) {
                    final v = vals[i];
                    final isToday = i == vals.length - 1;
                    final c = isToday
                        ? (v < 0 && todayNeg != null ? todayNeg : today)
                        : (v < 0 && neg != null ? neg : pos);
                    double top, bh;
                    if (signed) {
                      bh = pn <= 0
                          ? 1.5
                          : math.max(1.5, v.abs() / pn * h);
                      top = v >= 0 ? baseY - bh : baseY;
                    } else {
                      bh = mx <= 0
                          ? h * 0.18
                          : h * (0.18 + 0.82 * math.max(0.0, v) / mx);
                      top = h - bh;
                    }
                    return Stack(
                      children: [
                        Positioned(
                          left: 0,
                          right: 0,
                          top: top,
                          height: bh,
                          child: DecoratedBox(
                            decoration: BoxDecoration(
                              color: c,
                              borderRadius: BorderRadius.circular(
                                signed ? 1 : 2,
                              ),
                            ),
                          ),
                        ),
                      ],
                    );
                  },
                ),
              ),
            ],
          ],
        );
      },
    );
  }

  /// 利润页底部：近 7 日利润迷你柱。正数红、负数绿（和利润数字同一套），
  /// 最后一根实色。走势上点了某一天 → 柱子截到那一天，下面写那一天。
  Widget _buildHeroProfitMiniBars(
    List<double> series, {
    int? pickIndex,
    List<String> labels = const <String>[],
  }) {
    if (series.length < 2) return const SizedBox.shrink();
    final k = math.min(7, series.length);
    final red = DunesColors.resolve(context, LhColors.neg);
    final green = DunesColors.resolve(context, LhColors.pos);
    final copper = red;
    final mute2 = DunesColors.resolve(context, LhColors.mute2);
    final unit = _period == 'day' ? '日' : '期';
    // 序列和横轴右对齐：轴上第 i 格 = 序列第 i − (轴长 − 序列长) 个。
    final offset = labels.length - series.length;
    final pi = pickIndex ?? -1;
    final seriesPick = pi - offset;
    final picked = pi >= 0 && seriesPick >= 0 && seriesPick < series.length;
    final pickText = picked && pi < labels.length ? labels[pi] : null;
    return Column(
      crossAxisAlignment: CrossAxisAlignment.stretch,
      mainAxisSize: MainAxisSize.min,
      children: [
        Container(
          height: 0.7,
          color: DunesColors.resolve(
            context,
            LhColors.line2,
            role: DunesColorRole.surface,
          ),
        ),
        const SizedBox(height: 7),
        SizedBox(
          height: 22,
          child: _heroMiniBars(
            series,
            signed: true,
            today: red,
            todayNeg: green,
            pos: red.withAlpha(70),
            neg: green.withAlpha(70),
            endIndex: picked ? seriesPick : null,
          ),
        ),
        const SizedBox(height: 3),
        Row(
          children: [
            Expanded(
              child: Text(
                '近 $k $unit利润',
                maxLines: 1,
                overflow: TextOverflow.ellipsis,
                style: LhTypography.sans(
                  size: 9,
                  color: mute2,
                  weight: FontWeight.w500,
                  height: 1.0,
                  context: context,
                ),
              ),
            ),
            Text(
              pickText ?? (_period == 'day' ? '今' : '本期'),
              style: LhTypography.sans(
                size: 9,
                color: copper,
                weight: FontWeight.w700,
                height: 1.0,
                context: context,
              ),
            ),
          ],
        ),
      ],
    );
  }

  /// 点资金页的预收净增：右卡切到走势并打开柱。
  void _focusHeroPrepaid() {
    LighthouseFeedback.instance.play(LighthouseFeedbackKind.select);
    setState(() {
      _heroFundsView = 'trend';
      _heroFundsBars = true;
      _heroFundsFocus = null;
    });
    // focusKey 只在变了的时候生效：先清空再设，连点两次也能切回来。
    WidgetsBinding.instance.addPostFrameCallback((_) {
      if (mounted) setState(() => _heroFundsFocus = lhHeroBarsTabKey);
    });
  }

  /// 总资产的环比：拿资产走势里「上月同日」（日线）或上一格（周 / 月 / 季 / 年）比。
  /// 走势还没拉回来、或者那一点没有数 → null（环比行写「—」）。
  ({double pct, bool isUp})? _heroTotalAssetsDelta() {
    final scope = _heroAssetLine('total')?.scope;
    if (scope == null) return null;
    final trend = LighthouseAssetTrendLoader.cached(
      scope,
      _period,
      count: _heroAssetTrendCount,
    );
    if (trend == null) return null;
    final pts = [
      for (final p in trend.points)
        if (p.total != null) p,
    ];
    if (pts.length < 2) return null;
    final last = pts.last;
    double? base;
    if (_period == 'day') {
      final d = DateTime.tryParse(last.asOfDate);
      if (d == null) return null;
      final want = DateTime(d.year, d.month - 1, d.day);
      for (final p in pts) {
        final pd = DateTime.tryParse(p.asOfDate);
        if (pd != null &&
            pd.year == want.year &&
            pd.month == want.month &&
            pd.day == want.day) {
          base = p.total;
          break;
        }
      }
    } else {
      base = pts[pts.length - 2].total;
    }
    final cur = last.total;
    if (base == null || cur == null || base.abs() < 1) return null;
    final pct = (cur - base) / base.abs() * 100;
    return (pct: pct.abs(), isUp: pct >= 0);
  }

  /// 大数卡第二页：资金与资产。2026-10-26 · 和利润页同一副骨架，一模一样的四层：
  ///
  ///     [🏦 总资产]  截至 10-25          ← 同利润页的口径胶囊
  ///     8367 万                           ← 同字号（lighthouseHeroMastheadFontSize）
  ///     ↓x% vs 上月同日                   ← 同一个 _heroDeltaLine
  ///     ───────────────
  ///     ▁▃▂▅▁▇▂                          ← 近 7 日预收净增（同利润页近 7 日利润）
  ///     近 7 日预收净增        今 −49.6万   ← 点这一块：右卡走势打开柱
  ///
  /// 原来多出来的「本日预收净增 −49.6万 / — vs 上月同日」两行去掉了：今天的数
  /// 并进柱子下面那行说明，两页翻过去结构对得上，不再是两种排法。
  Widget _buildHeroFundsPage(
    Map<String, double> heroTotals, {
    List<String> labels = const <String>[],
  }) {
    _ensureHeroFundPool();
    _primeHeroAssetTrends();
    if (_heroKpiPage == 1) _ensureBillOutstanding();
    if (_billFocusActive) return _buildBillMasthead(_bills!, _billFocus!);
    final mute2 = DunesColors.resolve(context, LhColors.mute2);
    final deep = DunesColors.resolve(context, _LhPlum.deep);
    final snapshotTotal = _heroAssetLine('total')?.amounts?.totalAssets;
    final asOf = _fundPoolSnapshot.asOfDate;
    final asOfShort = asOf.length == 10 ? asOf.substring(5) : asOf;
    final r = _heroPrepaidReadout(heroTotals);
    final ppActive = _heroFundsView == 'trend' && _heroFundsBars;
    final pp = _seriesForMetric('prepaid');

    // 2026-10-26 · 右边走势点了某一天：左边总资产、环比、预收净增柱都换成那一天
    // （和利润页同一个 _heroPointIndex）。资产走势在快照日之后没有数 → 写「待更新」。
    final pick = _heroPointIndex ?? -1;
    final pickOk = pick >= 0 && pick < labels.length;
    double? pickTotal;
    ({double pct, bool isUp})? pickDelta;
    if (pickOk) {
      final scope = _heroAssetLine('total')?.scope;
      final trend = scope == null
          ? null
          : LighthouseAssetTrendLoader.cached(
              scope,
              _period,
              count: _heroAssetTrendCount,
            );
      final vals = _heroFundsAxisValues(labels, trend);
      pickTotal = pick < vals.length ? vals[pick] : null;
      double? prev;
      for (var k = pick - 1; k >= 0 && k < vals.length; k--) {
        if (vals[k] != null) {
          prev = vals[k];
          break;
        }
      }
      final cur = pickTotal;
      if (cur != null && prev != null && prev.abs() >= 1) {
        final pct = (cur - prev) / prev.abs() * 100;
        pickDelta = (pct: pct.abs(), isUp: pct >= 0);
      }
    }
    final total = pickOk ? pickTotal : snapshotTotal;
    final stampText = pickOk ? labels[pick] : (asOfShort.isEmpty ? '' : '截至 $asOfShort');
    // 预收净增柱：序列和横轴右对齐。
    final ppPick = pickOk ? pick - (labels.length - pp.length) : -1;
    final ppPickOk = pickOk && ppPick >= 0 && ppPick < pp.length;

    return Padding(
      // 顶部留 38 给「利润 | 资金」切换条（和利润页同一个内边距）。
      padding: const EdgeInsets.fromLTRB(8, 38, 8, 8),
      child: Column(
        crossAxisAlignment: CrossAxisAlignment.stretch,
        children: [
          Expanded(
            child: LayoutBuilder(
              builder: (context, box) => FittedBox(
                fit: BoxFit.scaleDown,
                alignment: Alignment.centerLeft,
                child: SizedBox(
                  width: box.maxWidth,
                  child: Column(
                    mainAxisSize: MainAxisSize.min,
                    crossAxisAlignment: CrossAxisAlignment.start,
                    mainAxisAlignment: MainAxisAlignment.center,
                    children: [
                      // 手机上卡窄：「截至」放不下就自己换到胶囊下面一行，不挤出界。
                      Wrap(
                        spacing: 6,
                        runSpacing: 3,
                        crossAxisAlignment: WrapCrossAlignment.center,
                        children: [
                          _heroPageChip(
                            Icons.account_balance_rounded,
                            '总资产',
                          ),
                          if (stampText.isNotEmpty)
                            Text(
                              stampText,
                              maxLines: 1,
                              style: LhTypography.mono(
                                size: 9,
                                color: mute2,
                                height: 1.0,
                                context: context,
                              ),
                            ),
                        ],
                      ),
                      const SizedBox(height: 6),
                      total == null
                          ? Text(
                              pickOk
                                  ? '待更新'
                                  : (_fundPoolLoading ? '资金池加载中…' : '暂无资金数据'),
                              style: LhTypography.sans(
                                size: 11,
                                color: mute2,
                                height: 1.2,
                                context: context,
                              ),
                            )
                          // 大数只缩不折行：窄卡上「1.02亿」宁可小一号，也不拆成两行或被裁。
                          : FittedBox(
                              fit: BoxFit.scaleDown,
                              alignment: Alignment.centerLeft,
                              child: _heroSplitWan(
                                total,
                                size: lighthouseHeroMastheadFontSize,
                                unitSize: 10.5,
                                color: DunesColors.resolve(
                                  context,
                                  _LhPlum.heroNum,
                                ),
                              ),
                            ),
                      const SizedBox(height: 5),
                      _heroDeltaLine(
                        pickOk ? pickDelta : _heroTotalAssetsDelta(),
                        pointMode: pickOk,
                      ),
                    ],
                  ),
                ),
              ),
            ),
          ),
          if (pp.length >= 2 && _showOperatingCashFlow())
            Semantics(
              button: true,
              selected: ppActive,
              label: '预收净增走势',
              child: GestureDetector(
                behavior: HitTestBehavior.opaque,
                onTap: _focusHeroPrepaid,
                child: Column(
                  crossAxisAlignment: CrossAxisAlignment.stretch,
                  mainAxisSize: MainAxisSize.min,
                  children: [
                    Container(
                      height: 0.7,
                      color: DunesColors.resolve(
                        context,
                        LhColors.line2,
                        role: DunesColorRole.surface,
                      ),
                    ),
                    const SizedBox(height: 7),
                    SizedBox(
                      height: 22,
                      child: _heroMiniBars(
                        pp,
                        signed: true,
                        endIndex: ppPickOk ? ppPick : null,
                        today: deep,
                        pos: DunesColors.resolve(
                          context,
                          const Color(0xFFB39CF0),
                        ),
                        neg: DunesColors.resolve(
                          context,
                          const Color(0xFFD6CBF5),
                          role: DunesColorRole.surface,
                        ),
                      ),
                    ),
                    const SizedBox(height: 3),
                    Row(
                      children: [
                        Expanded(
                          child: Text(
                            '近 ${math.min(7, pp.length)} ${_period == 'day' ? '日' : '期'}预收净增',
                            maxLines: 1,
                            overflow: TextOverflow.ellipsis,
                            style: LhTypography.sans(
                              size: 9,
                              // 右图正在画这排柱时，说明文字跟着变深紫 —— 两边是同一份数。
                              color: ppActive ? deep : mute2,
                              weight: ppActive
                                  ? FontWeight.w600
                                  : FontWeight.w500,
                              height: 1.0,
                              context: context,
                            ),
                          ),
                        ),
                        Text(
                          ppPickOk
                              ? '${labels[pick]} ${_heroWan(pp[ppPick])}'
                              : '${_period == 'day' ? '今' : '本期'} ${_heroWan(r.value)}',
                          maxLines: 1,
                          style: _tabular(
                            LhTypography.sans(
                              size: 9,
                              color: deep,
                              weight: FontWeight.w700,
                              height: 1.0,
                              context: context,
                            ),
                          ),
                        ),
                      ],
                    ),
                  ],
                ),
              ),
            ),
        ],
      ),
    );
  }

  // ── 主 Hero 右卡 ───────────────────────────────────────────────────────

  List<double?> _heroAlignTo(int n, List<double> s) {
    final out = List<double?>.filled(n, null);
    for (var i = 0; i < s.length && i < n; i++) {
      out[n - 1 - i] = s[s.length - 1 - i];
    }
    return out;
  }

  String _heroChartMoney(double v) =>
      '${v < 0 ? '−' : ''}${_fmtMoney(v.abs())}${_unitMoney(v)}';

  String _heroChartSigned(double v) =>
      '${v < 0 ? '−' : '+'}${_fmtMoney(v.abs())}${_unitMoney(v)}';

  /// 一屏几个点：平时一屏（日线 7）。拉宽后的点数见 [_heroChartWideCount] ——
  /// 走势卡跟着拉宽进度在两者之间连续变（2026-10-26），这里不再按 _heroTrendWide 跳。
  int _heroChartVisibleCount(int labelCount) {
    final base = _heroViewportCount >= 2 ? _heroViewportCount : labelCount;
    return math.max(1, base);
  }

  /// 拉宽到头一屏几个点：多一倍，封顶 31。
  int _heroChartWideCount(int labelCount) =>
      math.min(31, _heroChartVisibleCount(labelCount) * 2);

  Widget _heroTrendKButton() {
    final can = _heroCanOpenFullscreen;
    return Semantics(
      button: true,
      enabled: can,
      label: '打开走势大图',
      child: GestureDetector(
        behavior: HitTestBehavior.opaque,
        onTap: can ? () => _openHeroTrendFullscreen() : null,
        child: Padding(
          padding: const EdgeInsets.symmetric(horizontal: 2, vertical: 2),
          child: LighthouseHeroCandleGlyph(enabled: can),
        ),
      ),
    );
  }

  /// 右卡：利润模式 / 资金模式。翻页过程中整卡先淡出再淡入（过 0.5 换内容）。
  Widget _buildHeroDualTrend({
    required Map<String, double> totals,
    required List<double> profitSeries,
    required List<String> labels,
    required bool paged,
  }) {
    _heroTrendArgs = (
      totals: totals,
      profitSeries: profitSeries,
      labels: labels,
    );
    _scheduleHeroHistoryPreload();
    if (!paged) return _buildHeroProfitTrendCard(labels, profitSeries);
    return ValueListenableBuilder<double>(
      valueListenable: _heroPagePos,
      builder: (context, pos, _) {
        final funds = pos >= 0.5;
        final moving = (pos - pos.roundToDouble()).abs() > 0.001;
        final fade = moving
            ? ((pos - 0.5).abs() * 2.2).clamp(0.0, 1.0).toDouble()
            : 1.0;
        return Opacity(
          opacity: 0.35 + 0.65 * fade,
          child: funds
              ? _buildHeroFundsTrendCard(labels)
              : _buildHeroProfitTrendCard(labels, profitSeries),
        );
      },
    );
  }

  /// 利润模式：核销 / 销售 / 利润 / 收入默认叠画，GMV、成本点图例加上。
  Widget _buildHeroProfitTrendCard(
    List<String> labels,
    List<double> profitSeries,
  ) {
    final n = labels.length;
    final preferVerified = _anchor == _LhAnchor.verified;
    final scaleKey = preferVerified ? 'verifiedSales' : 'sales';
    final altKey = preferVerified ? 'sales' : 'verifiedSales';
    String nameOf(String k) => k == 'verifiedSales' ? '核销额' : '销售额';
    LhHeroLine line(
      String key,
      String name,
      Color color,
      List<double> s, {
      List<double>? dash,
    }) => LhHeroLine(
      key: key,
      name: name,
      color: color,
      values: _heroAlignTo(n, s),
      format: _heroChartMoney,
      dash: dash,
    );
    final lines = <LhHeroLine>[
      // 2026-10-26 · 六个指标六种颜色（原来四根都是深浅紫，小卡片上分不清）：
      //   核销紫 · 销售蓝 · 利润红 · 收入琥珀 · GMV 青 · 成本灰。
      // 利润排第一个分段：首页默认就停在利润（左边大数也是利润）。
      line(
        'profit',
        '利润',
        lighthouseHeroSegmentColors['profit']!,
        profitSeries,
      ),
      line(
        scaleKey,
        nameOf(scaleKey),
        lighthouseHeroSegmentColors[scaleKey]!,
        _seriesForMetric(scaleKey),
      ),
      line(
        altKey,
        nameOf(altKey),
        lighthouseHeroSegmentColors[altKey] ?? const Color(0xFF4A86E8),
        _seriesForMetric(altKey),
      ),
      line(
        'revenue',
        '收入',
        lighthouseHeroSegmentColors['revenue']!,
        _seriesForMetric('revenue'),
        dash: const [4, 3],
      ),
      line(
        'gmv',
        'GMV',
        lighthouseHeroSegmentColors['gmv']!,
        _seriesForMetric('gmv'),
        dash: const [2, 3],
      ),
      line(
        'totalCost',
        '成本',
        const Color(0xFF8F86A8),
        _seriesForMetric('totalCost'),
        dash: const [6, 3],
      ),
    ];
    String? focus;
    final f = _expandedTrendKey;
    if (f != null) {
      for (final l in lines) {
        if (lighthouseLedgerMetricKeysMatch(f, l.key)) {
          focus = l.key;
          break;
        }
      }
    }
    return LighthouseHeroTrendCard(
      key: const ValueKey('hero-trend-profit'),
      title: '本期合计',
      labels: labels,
      lines: lines,
      defaultVisible: {scaleKey, altKey, 'profit', 'revenue'},
      // 2026-10-26 · 柱 + 线（原型 B）试过后按要求改回多线叠画；要再开：
      //   combo: true, comboBarKeys: {scaleKey, altKey, 'gmv'},
      //   comboRatioLabels: const {'profit': '利润率'},
      // 原型 A 的排布：分段按钮选主线 + 一行大读数，图里照样多线叠画。
      segmented: true,
      compareLabel: _heroCompareLabel,
      // 没点过别的指标 → 停在利润（原来落到第一根线核销额上，和左边的利润对不上）。
      focusKey: focus ?? 'profit',
      // 点上面那排分段：左边大数跟着换成同一个指标（利润 = 回到默认）。
      onFocusChanged: (k) {
        final next = k == 'profit' ? null : k;
        if (next == _expandedTrendKey) return;
        LighthouseFeedback.instance.play(LighthouseFeedbackKind.select);
        setState(() => _expandedTrendKey = next);
      },
      visibleCount: _heroChartVisibleCount(n),
      wideVisibleCount: _heroChartWideCount(n),
      selectedIndex: _heroPointIndex,
      onSelectedIndexChanged: _onHeroPointSelected,
      lastIsPartial: _periodInProgress,
      trailing: _heroTrendKButton(),
      // 图里横拖往前翻历史（10.21 换新卡时漏接了，2026-10-26 补回）。
      historyCount: _heroHistoryCount,
      historyLoading: _heroHistoryLoading,
      historyHasMore: _heroHistoryHasMore,
      onNeedHistory: _heroHistorySupported
          ? () => unawaited(_loadHeroHistory())
          : null,
    );
  }

  /// 资产走势先拉好（合计 / 中石油 / 中石化 同一个格数），拉完重画一次。
  void _primeHeroAssetTrends() {
    final trendCount = _heroAssetTrendCount;
    final scopes = <String>{
      for (final l in _heroAssetLines)
        if (l.scope case final scope?) scope,
    };
    if (scopes.isEmpty) return;
    final primeKey = '$_period::$trendCount::${scopes.join('|')}';
    if (_heroAssetPrimeKey == primeKey) return;
    _heroAssetPrimeKey = primeKey;
    final period = _period;
    WidgetsBinding.instance.addPostFrameCallback((_) async {
      try {
        await Future.wait([
          for (final scope in scopes)
            LighthouseAssetTrendLoader.prefetch(
              service: _service,
              scope: scope,
              period: period,
              count: trendCount,
            ),
        ]);
      } catch (_) {
        // 某一类缺走势时，那根线就不画。
      }
      if (mounted && _heroAssetPrimeKey == primeKey) setState(() {});
    });
  }

  /// 资产（存量）折到主走势的横轴上。日线按日期精确对位 —— 快照日之后的
  /// 格子留空（不往后补），图上那根线就停在快照日，读数卡写「待更新」。
  List<double?> _heroFundsAxisValues(
    List<String> axis,
    LighthouseAssetTrend? trend,
  ) {
    final empty = List<double?>.filled(axis.length, null);
    if (trend == null || axis.isEmpty) return empty;
    final pts = [
      for (final p in trend.points)
        if (p.total != null) p,
    ];
    if (pts.isEmpty) return empty;
    if (_period == 'day') {
      final byKey = <String, double>{};
      for (final p in pts) {
        final d = DateTime.tryParse(p.asOfDate);
        if (d == null) continue;
        byKey['${d.month}.${d.day.toString().padLeft(2, '0')}'] = p.total!;
      }
      final hit = <double?>[for (final l in axis) byKey[l.trim()]];
      if (hit.any((v) => v != null)) return hit;
    }
    final folded = lighthouseFoldStockToAxis(
      axisLabels: axis,
      seriesLabels: [
        for (final p in pts) p.asOfDate.isNotEmpty ? p.asOfDate : p.label,
      ],
      values: [for (final p in pts) p.total!],
    );
    if (folded.isEmpty) return empty;
    return <double?>[for (final v in folded) v];
  }

  /// 资金模式：走势（线 = 资产，柱 = 预收净增）/ 构成。
  Widget _buildHeroFundsTrendCard(List<String> labels) {
    _ensureHeroFundPool();
    _primeHeroAssetTrends();
    if (_billFocusActive) {
      final bills = _bills!;
      return LighthouseHeroTrendCard(
        key: const ValueKey('hero-trend-bills'),
        title: '未结账款',
        subtitle: '${bills.asOfShort} 快照 · 按对方',
        labels: const <String>[],
        lines: const <LhHeroLine>[],
        // 资管只给当天快照：「走势」置灰，等灯塔自己每天存档后再点亮。
        trailing: const LhBillSnapshotSegment(),
        body: LhBillMix(
          data: bills,
          side: _billFocus!,
          onSideChanged: (s) => _setBillFocus(s),
          onOpenAll: () => _openBillSheet(_billFocus),
        ),
      );
    }
    final seg = LighthouseHeroSegment(
      labels: const ['走势', '构成'],
      index: _heroFundsView == 'mix' ? 1 : 0,
      onChanged: (i) {
        LighthouseFeedback.instance.play(LighthouseFeedbackKind.select);
        setState(() => _heroFundsView = i == 1 ? 'mix' : 'trend');
      },
    );
    if (_heroFundsView == 'mix') {
      return LighthouseHeroTrendCard(
        key: const ValueKey('hero-trend-funds-mix'),
        title: '资金',
        labels: const <String>[],
        lines: const <LhHeroLine>[],
        trailing: seg,
        body: _buildHeroFundsMix(),
      );
    }
    final n = labels.length;
    final lines = <LhHeroLine>[];
    void add(String key, String name, Color color, List<double>? dash) {
      final line = _heroAssetLine(key);
      final scope = line?.scope;
      if (line == null || scope == null) return;
      final trend = LighthouseAssetTrendLoader.cached(
        scope,
        _period,
        count: _heroAssetTrendCount,
      );
      lines.add(
        LhHeroLine(
          key: key,
          name: name,
          color: color,
          dash: dash,
          values: _heroFundsAxisValues(labels, trend),
          format: _heroChartMoney,
          stock: true,
        ),
      );
    }

    add('total', '总资产', const Color(0xFF6A4FC9), null);
    add(
      lighthouseAssetCategoryOil,
      '中石油',
      const Color(0xFFB5563F),
      const [3, 3],
    );
    add(
      lighthouseAssetCategoryPetro,
      '中石化',
      const Color(0xFF4A78C9),
      const [3, 3],
    );
    final pp = _seriesForMetric('prepaid');
    // 2026-10-26 · 和利润卡同一种排布：标题「本期合计」，下面一排分段
    // 「总资产 | 中石油 | 中石化 | 预收净增」+ 一行大读数（vs 上日 / vs 上月）。
    return LighthouseHeroTrendCard(
      key: const ValueKey('hero-trend-funds'),
      title: '本期合计',
      labels: labels,
      lines: lines,
      defaultVisible: const {'total'},
      segmented: true,
      compareLabel: _heroCompareLabel,
      focusKey: _heroFundsFocus,
      // 点哪一天，左边资金页跟着换（和利润卡共用一个选中点）。
      selectedIndex: _heroPointIndex,
      onSelectedIndexChanged: _onHeroPointSelected,
      bars: pp.isEmpty
          ? null
          : LhHeroBars(
              name: '预收净增',
              values: _heroAlignTo(n, pp),
              format: _heroChartSigned,
            ),
      barsVisible: _heroFundsBars,
      onBarsVisibleChanged: (v) {
        LighthouseFeedback.instance.play(LighthouseFeedbackKind.select);
        setState(() => _heroFundsBars = v);
      },
      visibleCount: _heroChartVisibleCount(n),
      wideVisibleCount: _heroChartWideCount(n),
      lastIsPartial: _periodInProgress,
      trailing: seg,
      emptyText: _fundPoolLoading ? '资金池加载中…' : '暂无资金走势',
      historyCount: _heroHistoryCount,
      historyLoading: _heroHistoryLoading,
      historyHasMore: _heroHistoryHasMore,
      onNeedHistory: _heroHistorySupported
          ? () => unawaited(_loadHeroHistory())
          : null,
    );
  }

  /// 资金「构成」：原来点「资金与资产」往下展开那块的全部明细，搬进右卡。
  ///
  ///     [ 合计 1.02亿 | 中石油 2508万 | 中石化 7700万 ]   ← 点哪个看哪个
  ///     ▬▬▬▬▬▬▬▬▬▬▬▬▬▬▬▬▬▬▬▬▬▬ 中石油 / 中石化 占比
  ///     ┌ 账面资产怎么来 ─────┐ ┌ 期末预付怎么拆 ──────┐
  ///     │   已入账       x万 │ │   期末预付       x万 │
  ///     │ + 待入账       x万 │ │ − 可动用额度     x万 │
  ///     │ + 期末预付     x万 │ │ − 券资产         x万 │
  ///     │ = 账面资产     x万 │ │ − 应收返利       x万 │
  ///     └────────────────────┘ │ = 对账差额       x万 │
  ///                             └──────────────────────┘
  Widget _buildHeroFundsMix() {
    final ink = DunesColors.resolve(context, LhColors.ink);
    final ink2 = DunesColors.resolve(context, LhColors.ink2);
    final mute = DunesColors.resolve(context, LhColors.mute);
    final mute2 = DunesColors.resolve(context, LhColors.mute2);
    final plum = DunesColors.resolve(context, _LhPlum.primary);
    final deep = DunesColors.resolve(context, _LhPlum.deep);
    final warn = DunesColors.resolve(context, LhColors.neg);
    final edge = DunesColors.resolve(
      context,
      const Color(0xFFECE6F8),
      role: DunesColorRole.border,
    );
    final ordered = <LighthouseAssetFooterLine>[
      for (final k in const [
        'total',
        lighthouseAssetCategoryOil,
        lighthouseAssetCategoryPetro,
      ])
        if (_heroAssetLine(k) case final l?) l,
    ];
    if (ordered.isEmpty) {
      return Center(
        child: Text(
          _fundPoolLoading ? '资金池加载中…' : '暂无资金数据',
          style: LhTypography.sans(size: 10, color: mute2, context: context),
        ),
      );
    }
    final selected = _heroAssetLine(_heroAssetKey) ?? ordered.first;
    String shortLabel(String key) => switch (key) {
      lighthouseAssetCategoryOil => '中石油',
      lighthouseAssetCategoryPetro => '中石化',
      _ => '合计',
    };
    Color accentOf(String key) => DunesColors.resolve(context, switch (key) {
      lighthouseAssetCategoryOil => LhColors.cnpc,
      lighthouseAssetCategoryPetro => LhColors.sinopec,
      _ => _LhPlum.primary,
    });
    final asOf = _fundPoolSnapshot.asOfDate;
    final asOfShort = asOf.length == 10 ? asOf.substring(5) : asOf;
    final a = selected.amounts;
    double? v(String key) => lighthouseFundPoolAmountByKey(a, key);
    bool hasDiff(double? x) => x != null && x.abs() >= 1;

    // ── 分类切换：合计 / 中石油 / 中石化，每格带总资产 ──
    Widget pick(LighthouseAssetFooterLine l) {
      final on = l.key == selected.key;
      return Expanded(
        child: Semantics(
          button: true,
          selected: on,
          label: '${shortLabel(l.key)}资产明细',
          child: GestureDetector(
            behavior: HitTestBehavior.opaque,
            onTap: on
                ? null
                : () {
                    LighthouseFeedback.instance.play(
                      LighthouseFeedbackKind.select,
                    );
                    setState(() => _heroAssetKey = l.key);
                  },
            child: AnimatedContainer(
              duration: const Duration(milliseconds: 140),
              padding: const EdgeInsets.fromLTRB(6, 5, 4, 5),
              decoration: BoxDecoration(
                color: on
                    ? DunesColors.resolve(
                        context,
                        Colors.white,
                        role: DunesColorRole.surface,
                      )
                    : const Color(0x00FFFFFF),
                borderRadius: BorderRadius.circular(6),
                boxShadow: on
                    ? [
                        BoxShadow(
                          color: _LhPlum.deep.withAlpha(30),
                          blurRadius: 3,
                          offset: const Offset(0, 1),
                        ),
                      ]
                    : null,
              ),
              child: Column(
                crossAxisAlignment: CrossAxisAlignment.start,
                mainAxisSize: MainAxisSize.min,
                children: [
                  Row(
                    children: [
                      Container(
                        width: 2.5,
                        height: 9,
                        decoration: BoxDecoration(
                          color: accentOf(l.key),
                          borderRadius: BorderRadius.circular(1),
                        ),
                      ),
                      const SizedBox(width: 4),
                      Flexible(
                        child: Text(
                          shortLabel(l.key),
                          maxLines: 1,
                          overflow: TextOverflow.ellipsis,
                          style: LhTypography.sans(
                            size: 9.5,
                            color: on ? ink : mute,
                            weight: on ? FontWeight.w700 : FontWeight.w500,
                            height: 1.0,
                            context: context,
                          ),
                        ),
                      ),
                    ],
                  ),
                  const SizedBox(height: 3),
                  FittedBox(
                    fit: BoxFit.scaleDown,
                    alignment: Alignment.centerLeft,
                    child: Text(
                      _heroWan(l.amounts?.totalAssets),
                      maxLines: 1,
                      softWrap: false,
                      style: _tabular(
                        LhTypography.number(
                          size: 11.5,
                          color: on ? ink : ink2,
                          context: context,
                        ),
                      ).copyWith(fontWeight: FontWeight.w700, height: 1.0),
                    ),
                  ),
                ],
              ),
            ),
          ),
        ),
      );
    }

    final picker = Container(
      padding: const EdgeInsets.all(2),
      decoration: BoxDecoration(
        color: DunesColors.resolve(
          context,
          const Color(0xFFEEE8FB),
          role: DunesColorRole.surface,
        ),
        borderRadius: BorderRadius.circular(8),
      ),
      child: Row(
        children: [
          for (var i = 0; i < ordered.length; i++) ...[
            if (i > 0) const SizedBox(width: 2),
            pick(ordered[i]),
          ],
        ],
      ),
    );

    // ── 中石油 / 中石化 占比条 ──
    final oilV = _heroAssetLine(lighthouseAssetCategoryOil)?.amounts?.totalAssets;
    final petroV =
        _heroAssetLine(lighthouseAssetCategoryPetro)?.amounts?.totalAssets;
    final sum = (oilV ?? 0).abs() + (petroV ?? 0).abs();
    final oilShare = sum > 0 ? (oilV ?? 0).abs() / sum : 0.0;
    Widget shareBar() => ClipRRect(
      borderRadius: BorderRadius.circular(2),
      child: SizedBox(
        height: 4,
        child: Row(
          crossAxisAlignment: CrossAxisAlignment.stretch,
          children: [
            Expanded(
              flex: math.max(1, (oilShare * 1000).round()),
              child: ColoredBox(color: accentOf(lighthouseAssetCategoryOil)),
            ),
            const SizedBox(width: 2),
            Expanded(
              flex: math.max(1, ((1 - oilShare) * 1000).round()),
              child: ColoredBox(color: accentOf(lighthouseAssetCategoryPetro)),
            ),
          ],
        ),
      ),
    );

    // ── 两列竖账（同原来资产面板的「明细」） ──
    Widget ledgerRow(
      String op,
      String label,
      double? value, {
      bool total = false,
      bool hl = false,
      Color? valueColor,
      Color? boxTint,
    }) {
      final row = Row(
        children: [
          SizedBox(
            width: 10,
            child: Text(
              op,
              style: LhTypography.mono(
                size: 10,
                color: mute2,
                weight: FontWeight.w700,
                height: 1.0,
                context: context,
              ),
            ),
          ),
          Expanded(
            child: Text(
              label,
              maxLines: 1,
              overflow: TextOverflow.ellipsis,
              style: LhTypography.sans(
                size: total ? 10 : 9.5,
                color: total ? ink : (hl ? deep : ink2),
                weight: total
                    ? FontWeight.w700
                    : (hl ? FontWeight.w700 : FontWeight.w500),
                height: 1.0,
                context: context,
              ),
            ),
          ),
          const SizedBox(width: 4),
          Text(
            _heroWan(value),
            maxLines: 1,
            style: _tabular(
              LhTypography.number(
                size: total ? 12 : 10,
                color: valueColor ?? (hl ? deep : ink),
                context: context,
              ),
            ).copyWith(
              fontWeight: total ? FontWeight.w700 : FontWeight.w600,
              height: 1.0,
            ),
          ),
        ],
      );
      if (!total) return SizedBox(height: 19, child: row);
      final tint = boxTint ?? plum;
      return Container(
        height: 26,
        margin: const EdgeInsets.only(top: 3, bottom: 5),
        padding: const EdgeInsets.symmetric(horizontal: 5),
        decoration: BoxDecoration(
          color: tint.withAlpha(18),
          border: Border.all(color: tint.withAlpha(110), width: 0.9),
          borderRadius: BorderRadius.circular(6),
        ),
        child: row,
      );
    }

    Widget ledgerColumn(
      String title,
      List<Widget> rows, {
      bool expand = true,
    }) {
      final box = Container(
        padding: const EdgeInsets.fromLTRB(7, 6, 7, 0),
        decoration: BoxDecoration(
          color: DunesColors.resolve(
            context,
            Colors.white,
            role: DunesColorRole.surface,
          ),
          border: Border.all(color: edge, width: 0.7),
          borderRadius: BorderRadius.circular(8),
        ),
        child: Column(
          crossAxisAlignment: CrossAxisAlignment.stretch,
          children: [
            Text(
              title,
              maxLines: 1,
              overflow: TextOverflow.ellipsis,
              style: LhTypography.sans(
                size: 9,
                color: mute,
                weight: FontWeight.w700,
                height: 1.0,
                context: context,
              ),
            ),
            const SizedBox(height: 4),
            ...rows,
          ],
        ),
      );
      return expand ? Expanded(child: box) : box;
    }

    final diff = v('systemDifference');
    List<Widget> assetRows() => [
      ledgerRow('', '已入账', v('regulatoryAccountBalance')),
      ledgerRow('+', '待入账', v('inTransitFunds')),
      ledgerRow('+', '期末预付', v('endingPrepaymentBalance'), hl: true),
      ledgerRow(
        '=',
        '账面资产',
        v('totalAssets'),
        total: true,
        valueColor: deep,
      ),
    ];
    List<Widget> reconRows() => [
      ledgerRow('', '期末预付', v('endingPrepaymentBalance'), hl: true),
      ledgerRow('−', '可动用额度', v('fundPoolBalance')),
      ledgerRow('−', '券资产', v('stockAndSyncVouchers')),
      ledgerRow('−', '应收返利', v('endingReceivableRebate')),
      ledgerRow(
        '=',
        '对账差额',
        diff,
        total: true,
        valueColor: hasDiff(diff) ? warn : null,
        boxTint: hasDiff(diff) ? warn : null,
      ),
    ];
    // 2026-10-26 · 手机上右卡只有 ~200px，两列竖账并排每列不到 100px，金额被挤没
    //   （「看不到总资产」）。窄于 300 改成上下两块，账面资产那块在上面。
    final ledger = LayoutBuilder(
      builder: (context, c) => c.maxWidth < 300
          ? Column(
              crossAxisAlignment: CrossAxisAlignment.stretch,
              children: [
                ledgerColumn('账面资产怎么来', assetRows(), expand: false),
                const SizedBox(height: 6),
                ledgerColumn('期末预付怎么拆', reconRows(), expand: false),
              ],
            )
          : Row(
              crossAxisAlignment: CrossAxisAlignment.start,
              children: [
                ledgerColumn('账面资产怎么来', assetRows()),
                const SizedBox(width: 6),
                ledgerColumn('期末预付怎么拆', reconRows()),
              ],
            ),
    );

    return SingleChildScrollView(
      physics: const ClampingScrollPhysics(),
      child: Column(
        crossAxisAlignment: CrossAxisAlignment.stretch,
        children: [
          picker,
          if (sum > 0) ...[const SizedBox(height: 5), shareBar()],
          const SizedBox(height: 7),
          ledger,
          if (asOfShort.isNotEmpty) ...[
            const SizedBox(height: 5),
            Text(
              '资管快照 · 截至 $asOfShort',
              textAlign: TextAlign.right,
              style: LhTypography.mono(
                size: 8.5,
                color: mute2,
                height: 1.0,
                context: context,
              ),
            ),
          ],
        ],
      ),
    );
  }

  /// 大数卡底部：「预收净增」和「资金与资产」合成一张小卡（2026-10-20）。
  ///
  ///     ┌──────────────────┐
  ///     │ 预收净增   ↓454% │   ← 点它：主走势切到预收净增（淡紫底）
  ///     │ −58.4万          │
  ///     ├──────────────────┤
  ///     │ 🏦 资金与资产   › │   ← 点它：下面展开资金与资产（深紫底）
  ///     └──────────────────┘
  ///
  /// 原来是一颗浅紫胶囊标签 + 一行数 + 另一颗按钮，三样东西各自一套样式，
  /// 堆在窄卡底部很乱。现在一张白卡、一根发丝线分上下两格，字号跟指标格同档。
  /// 移动端这张卡只有 85~90 宽：分两行，字号不随卡宽缩。
  Widget _buildHeroFundsMini(
    Map<String, double> heroTotals, {
    required bool withAssets,
  }) {
    if (withAssets) _ensureHeroFundPool();
    final hasAssets = withAssets && _heroAssetLines.isNotEmpty;
    final ink = DunesColors.resolve(context, LhColors.ink);
    final mute = DunesColors.resolve(context, LhColors.mute);
    final mute2 = DunesColors.resolve(context, LhColors.mute2);
    final plum = DunesColors.resolve(context, _LhPlum.primary);
    final deep = DunesColors.resolve(context, _LhPlum.deep);
    final r = _heroPrepaidReadout(heroTotals);

    final prepaidPart = Semantics(
      button: true,
      selected: r.active,
      label: '预收净增走势',
      child: GestureDetector(
        behavior: HitTestBehavior.opaque,
        onTap: _toggleHeroPrepaidTrend,
        child: AnimatedContainer(
          duration: const Duration(milliseconds: 160),
          padding: const EdgeInsets.fromLTRB(8, 6, 8, 6),
          color: r.active
              ? DunesColors.resolve(
                  context,
                  _LhPlum.mist,
                  role: DunesColorRole.surface,
                )
              : const Color(0x00FFFFFF),
          // 手机上这张卡只有 85~90 宽：标签独占一行（宁可缩字也不省略成「预…」），
          // 第二行左边数值、右边环比；数值太长时只缩数值。
          child: Column(
            crossAxisAlignment: CrossAxisAlignment.stretch,
            mainAxisSize: MainAxisSize.min,
            children: [
              FittedBox(
                fit: BoxFit.scaleDown,
                alignment: Alignment.centerLeft,
                child: Text(
                  '预收净增',
                  maxLines: 1,
                  softWrap: false,
                  style: LhTypography.sans(
                    size: lighthouseHeroCellLabelFontSize,
                    color: r.active ? deep : mute,
                    weight: r.active ? FontWeight.w700 : FontWeight.w500,
                    height: 1.1,
                    context: context,
                  ),
                ),
              ),
              const SizedBox(height: 4),
              Row(
                crossAxisAlignment: CrossAxisAlignment.end,
                children: [
                  Expanded(
                    child: FittedBox(
                      fit: BoxFit.scaleDown,
                      alignment: Alignment.centerLeft,
                      child: Text(
                        _heroWan(r.value),
                        maxLines: 1,
                        softWrap: false,
                        style: _tabular(
                          LhTypography.number(
                            size: lighthouseHeroMetricValueFontSize,
                            color: r.active ? deep : ink,
                            context: context,
                          ),
                        ).copyWith(fontWeight: FontWeight.w700, height: 1.0),
                      ),
                    ),
                  ),
                  const SizedBox(width: 4),
                  Text(
                    r.delta,
                    maxLines: 1,
                    softWrap: false,
                    style: _tabular(
                      LhTypography.mono(
                        size: lighthouseHeroCellDeltaFontSize,
                        color: mute2,
                        weight: FontWeight.w600,
                        height: 1.0,
                        context: context,
                      ),
                    ),
                  ),
                ],
              ),
            ],
          ),
        ),
      ),
    );

    Widget card(List<Widget> children) => Container(
      clipBehavior: Clip.antiAlias,
      decoration: BoxDecoration(
        color: DunesColors.resolve(
          context,
          Colors.white,
          role: DunesColorRole.surface,
        ),
        border: Border.all(color: plum.withAlpha(45), width: 0.8),
        borderRadius: BorderRadius.circular(9),
      ),
      child: Column(
        crossAxisAlignment: CrossAxisAlignment.stretch,
        mainAxisSize: MainAxisSize.min,
        children: children,
      ),
    );

    // 供给页选了中石油 / 中石化时，点开默认就看那一家。
    final assetKey = _tab == 'supply'
        ? (_supplySelectedAssetCategory ?? 'total')
        : 'total';
    final open = _heroAssetOpen;
    final assetsPart = Semantics(
      button: true,
      expanded: open,
      label: open ? '收起资金与资产' : '展开资金与资产',
      child: GestureDetector(
        behavior: HitTestBehavior.opaque,
        onTap: () {
          LighthouseFeedback.instance.play(
            open ? LighthouseFeedbackKind.collapse : LighthouseFeedbackKind.expand,
          );
          setState(() {
            _heroAssetOpen = !open;
            if (!open) {
              _heroAssetKey = _heroAssetLine(assetKey) == null
                  ? 'total'
                  : assetKey;
              _supplyAssetPointIndex = null;
            }
          });
        },
        child: AnimatedContainer(
          duration: const Duration(milliseconds: 160),
          height: 26,
          padding: const EdgeInsets.symmetric(horizontal: 8),
          color: open ? deep : const Color(0x00FFFFFF),
          child: Row(
            children: [
              Icon(
                Icons.account_balance_rounded,
                size: 11,
                color: open ? Colors.white : plum,
              ),
              const SizedBox(width: 4),
              Expanded(
                child: FittedBox(
                  fit: BoxFit.scaleDown,
                  alignment: Alignment.centerLeft,
                  child: Text(
                    '资金与资产',
                    maxLines: 1,
                    softWrap: false,
                    style: LhTypography.sans(
                      size: 10,
                      color: open ? Colors.white : deep,
                      weight: FontWeight.w700,
                      height: 1.0,
                      context: context,
                    ),
                  ),
                ),
              ),
              Icon(
                open
                    ? Icons.keyboard_arrow_up_rounded
                    : Icons.chevron_right_rounded,
                size: 13,
                color: open ? Colors.white : plum,
              ),
            ],
          ),
        ),
      ),
    );
    final showCash = _showOperatingCashFlow();
    if (!showCash && !hasAssets) return const SizedBox.shrink();
    if (!showCash) return card([assetsPart]);
    if (!hasAssets) return card([prepaidPart]);
    return card([
      prepaidPart,
      Container(height: 0.7, color: plum.withAlpha(30)),
      assetsPart,
    ]);
  }

  /// 主 Hero 的「资金与资产」：一块矮卡。
  ///   顶行：标题 · 截至日 · 收起。预收净增在按钮上面，不进这张卡。
  ///   左栏：合计 / 中石油 / 中石化 竖着切，每格写总资产 + 对账差额
  ///   右边：走势 ⇄ 明细 同一块里切换（明细 = 账面资产怎么来 + 期末预付怎么拆）
  Widget _buildHeroAssetPanel() {
    final lines = _heroAssetLines;
    final ordered = <LighthouseAssetFooterLine>[
      for (final k in const [
        'total',
        lighthouseAssetCategoryOil,
        lighthouseAssetCategoryPetro,
      ])
        if (_heroAssetLine(k) case final l?) l,
    ];
    if (ordered.isEmpty) return const SizedBox.shrink();
    final selected =
        _heroAssetLine(_heroAssetKey) ?? _heroAssetLine('total') ?? lines.first;
    final ink = DunesColors.resolve(context, LhColors.ink);
    final ink2 = DunesColors.resolve(context, LhColors.ink2);
    final mute = DunesColors.resolve(context, LhColors.mute);
    final mute2 = DunesColors.resolve(context, LhColors.mute2);
    final plum = DunesColors.resolve(context, _LhPlum.primary);
    final deep = DunesColors.resolve(context, _LhPlum.deep);
    final warn = DunesColors.resolve(context, LhColors.neg);
    final neutral = DunesColors.resolve(
      context,
      const Color(lighthouseLedgerSummaryNeutralPanelValue),
      role: DunesColorRole.surface,
    );
    final edge = DunesColors.resolve(
      context,
      const Color(lighthouseHeroPanelNeutralEdgeValue),
      role: DunesColorRole.border,
    );
    final asOf = _fundPoolSnapshot.asOfDate;
    final asOfShort = asOf.length == 10 ? asOf.substring(5) : asOf;
    String shortLabel(LighthouseAssetFooterLine l) => switch (l.key) {
      lighthouseAssetCategoryOil => '中石油',
      lighthouseAssetCategoryPetro => '中石化',
      _ => '合计',
    };
    Color accentOf(String key) => DunesColors.resolve(context, switch (key) {
      lighthouseAssetCategoryOil => LhColors.cnpc,
      lighthouseAssetCategoryPetro => LhColors.sinopec,
      _ => _LhPlum.primary,
    });
    bool hasDiff(double? v) => v != null && v.abs() >= 1;

    // ── 走势点中的日期：左栏三格跟着换成那一天的总资产 ──
    //   三类走势一起预取（同一个格数），点哪天三格都能同步读到那天的数。
    final trendCount = _heroAssetTrendCount;
    final trendScopes = <String>{
      for (final l in ordered)
        if (l.scope case final scope?) scope,
    };
    final primeKey = '$_period::$trendCount::${trendScopes.join('|')}';
    if (_heroAssetPrimeKey != primeKey) {
      _heroAssetPrimeKey = primeKey;
      final period = _period;
      WidgetsBinding.instance.addPostFrameCallback((_) async {
        try {
          await Future.wait([
            for (final scope in trendScopes)
              LighthouseAssetTrendLoader.prefetch(
                service: _service,
                scope: scope,
                period: period,
                count: trendCount,
              ),
          ]);
        } catch (_) {
          // 某一类缺走势时，那一格停在最新快照。
        }
        if (mounted && _heroAssetPrimeKey == primeKey) setState(() {});
      });
    }
    String? pickedDate;
    String pickedLabel = '';
    if (_supplyAssetPointIndex case final index?) {
      final scope = selected.scope;
      final pts = scope == null
          ? null
          : LighthouseAssetTrendLoader.cached(
              scope,
              _period,
              count: trendCount,
            )?.points.where((p) => p.total != null).toList();
      // 点的是最新一格 = 就是快照那一天，照常显示差额。
      if (pts != null && index >= 0 && index < pts.length - 1) {
        final p = pts[index];
        pickedDate = p.asOfDate.isNotEmpty ? p.asOfDate : p.key;
        pickedLabel = p.asOfDate.length == 10
            ? p.asOfDate.substring(5)
            : p.label;
      }
    }
    double? totalOf(LighthouseAssetFooterLine l) {
      final date = pickedDate;
      final scope = l.scope;
      if (date == null || scope == null) return l.amounts?.totalAssets;
      return lighthouseAssetTrendTotalAtDate(
        LighthouseAssetTrendLoader.cached(scope, _period, count: trendCount),
        date,
        fallback: l.amounts?.totalAssets,
      );
    }

    // ── 左栏：竖着切 ──
    Widget railTile(LighthouseAssetFooterLine l) {
      final active = l.key == selected.key;
      return Expanded(
        child: Semantics(
          button: true,
          selected: active,
          label: '${shortLabel(l)}资产',
          child: GestureDetector(
            behavior: HitTestBehavior.opaque,
            onTap: () {
              if (active) return;
              LighthouseFeedback.instance.play(LighthouseFeedbackKind.select);
              setState(() {
                _heroAssetKey = l.key;
                _supplyAssetPointIndex = null;
              });
            },
            child: AnimatedContainer(
