  /// 标题旁的日期「印章」：浅紫底细边小方块，月份淡、日子重；
  /// 单日后面挂星期（周二），区间写成「10.01 → 10.18」。
  /// 原来是一串灰色等宽数字，像页脚。
  Widget _heroDateStamp(String label) {
    final plum = DunesColors.resolve(context, _LhPlum.primary);
    final deep = DunesColors.resolve(context, _LhPlum.deep);
    // 一个色：整枚印章都走深紫，只用深浅分层（2026-10 · 原来紫 / 深紫 / 灰三色打架）。
    final soft = deep.withAlpha(140);
    final dateRe = RegExp(r'^(\d{1,2})\.(\d{1,2})$');
    final parts = label
        .split(RegExp(r'\s*[–—~-]\s*'))
        .map((e) => e.trim())
        .where((e) => e.isNotEmpty)
        .toList();
    final dates = [for (final p in parts) dateRe.firstMatch(p)];
    TextStyle numStyle(Color c, FontWeight w) => _tabular(
      LhTypography.mono(
        size: lighthouseHeroSummaryRangeFontSize,
        color: c,
        weight: w,
        letterSpacing: 0.2,
        height: 1.0,
        context: context,
      ),
    );
    final spans = <InlineSpan>[];
    if (dates.isEmpty || dates.any((m) => m == null)) {
      // 认不出的格式（「近 7 天」之类）：原样写，只换成印章样式。
      spans.add(TextSpan(text: label, style: numStyle(deep, FontWeight.w700)));
    } else {
      for (var i = 0; i < dates.length; i++) {
        final m = dates[i]!;
        if (i > 0) {
          spans.add(TextSpan(text: ' → ', style: numStyle(deep, FontWeight.w700)));
        }
        spans
          // 2026-10-21 · 日期整枚加粗（月 / 点 / 日原来 600 / 500 / 800 三档，读着发虚）。
          ..add(TextSpan(text: m[1]!.padLeft(2, '0'), style: numStyle(deep, FontWeight.w700)))
          ..add(TextSpan(text: '.', style: numStyle(deep, FontWeight.w700)))
          ..add(TextSpan(text: m[2]!.padLeft(2, '0'), style: numStyle(deep, FontWeight.w700)));
      }
      if (dates.length == 1) {
        final now = _nowCST();
        final d = DateTime(now.year, int.parse(dates[0]![1]!), int.parse(dates[0]![2]!));
        const wk = ['一', '二', '三', '四', '五', '六', '日'];
        spans.add(
          TextSpan(
            text: '  周${wk[d.weekday - 1]}',
            style: LhTypography.sans(
              size: lighthouseHeroSummaryRangeFontSize - 1.5,
              color: deep,
              weight: FontWeight.w700,
              height: 1.0,
              context: context,
            ),
          ),
        );
      }
    }
    return Container(
      padding: const EdgeInsets.fromLTRB(6, 3, 7, 3),
      decoration: BoxDecoration(
        color: DunesColors.resolve(
          context,
          _LhPlum.lavender,
          role: DunesColorRole.surface,
        ),
        border: Border.all(color: plum.withAlpha(45), width: 0.8),
        borderRadius: BorderRadius.circular(6),
      ),
      child: Row(
        mainAxisSize: MainAxisSize.min,
        children: [
          Icon(Icons.event_rounded, size: 11, color: soft),
          const SizedBox(width: 4),
          Flexible(
            child: Text.rich(
              TextSpan(children: spans),
              maxLines: 1,
              overflow: TextOverflow.ellipsis,
            ),
          ),
        ],
      ),
    );
  }

  Widget _buildHero({
    Map<String, double>? totalsOverride,
    ({double pct, bool isUp})? profitDeltaOverride,
    List<double>? profitSeriesOverride,
    List<String>? profitLabelsOverride,
    String? summaryTitle,
    Widget? summaryTitleWidget,
    bool showFilters = true,
  }) {
    // 主 Hero 大数跟着底下点中的指标走；没点开时默认利润 / 净TA。
    final mastheadKey = _tab == 'netTa'
        ? _netTAHeroMastheadKey(_expandedTrendKey)
        : lighthouseHeroMastheadKey(_expandedTrendKey);
    final mastheadIsRate = lighthouseHeroMetricIsRate(mastheadKey);

    // totals = 整期合计，走势图永远吃这一份；
    // heroTotals = 大数与指标栏实际显示的那一份，选中某一点时换成那点的值。
    late final Map<String, double> totals;
    late final Map<String, double> heroTotals;
    var heroPointActive = false;
    late final List<double> profitSeries;
    late final double heroMastheadValue;
    late final bool mastheadIsNeg;

    if (totalsOverride != null) {
      totals = totalsOverride;
      // 实体走势优先；无走势则空（勿回退一级全量序列，避免 L2/L3 串档）。
      final overrideSeries = profitSeriesOverride ?? const <double>[];
      profitSeries = overrideSeries.length >= 2
          ? overrideSeries
          : _seriesForMetric('profit');
    } else {
      // Compute totals from data
      final rows = _currentRows;
      final metrics = _bundle?.metrics ?? const <String, dynamic>{};
      double sumSales = 0,
          sumVerifiedSales = 0,
          sumGmv = 0,
          sumCost = 0,
          sumProjectCost = 0,
          sumTotalCost = 0,
          sumSpread = 0,
          sumProfit = 0,
          sumNetProfit = 0,
          sumRevenue = 0,
          sumHandlingFee = 0,
          sumPlatformFee = 0,
          sumPrepaid = 0;
      for (final r in rows) {
        final s = (r['sales'] as num?)?.toDouble() ?? 0;
        final v = _verifiedSalesOf(r);
        sumSales += s;
        sumVerifiedSales += v;
        sumPrepaid += (r['prepaid'] as num?)?.toDouble() ?? 0;
        sumGmv += (r['gmv'] as num?)?.toDouble() ?? 0;
        sumCost += (r['cost'] as num?)?.toDouble() ?? 0;
        sumProjectCost += (r['projectCost'] as num?)?.toDouble() ?? 0;
        // 成本合计必须走 _rowCostTotal（兼容 totalCost / costTotal），
        // 否则切分类时其它指标变了、成本合计仍卡在 metrics 全量值。
        sumTotalCost += _rowCostTotal(r);
        sumSpread += (r['spread'] as num?)?.toDouble() ?? 0;
        sumProfit += (r['profit'] as num?)?.toDouble() ?? 0;
        sumNetProfit += (r['netProfit'] as num?)?.toDouble() ?? 0;
        sumRevenue += (r['revenue'] as num?)?.toDouble() ?? 0;
        sumHandlingFee += (r['handlingFee'] as num?)?.toDouble() ?? 0;
        sumPlatformFee += (r['platformServiceFee'] as num?)?.toDouble() ?? 0;
      }
      // 有分类/HUN/异常时：跟当前列表行加总；「全部」无本地筛时走后端共享 summary，
      // 避免产品/供给/渠道三维列表加总口径不一致。
      // 切维后上一档分类的 summary 不能继续当本日利润。
      final useRowAmounts = lighthouseHeroUseRowAmounts(
        filterActive: _heroFilterActive,
        hasRows: rows.isNotEmpty,
      );
      final metricsMatch = _heroSummaryMatchesGroup;
      final heroSales = _heroAmountFrom(
        metrics: metrics,
        useRowAmounts: useRowAmounts,
        metricsMatch: metricsMatch,
        keys: const ['sales'],
        rowSum: sumSales,
      );
      final heroVerified = _heroAmountFrom(
        metrics: metrics,
        useRowAmounts: useRowAmounts,
        metricsMatch: metricsMatch,
        keys: const ['verifiedSales'],
        rowSum: sumVerifiedSales,
      );
      final periodProfit = _heroAmountFrom(
        metrics: metrics,
        useRowAmounts: useRowAmounts,
        metricsMatch: metricsMatch,
        keys: const ['profit'],
        rowSum: sumProfit,
      );
      final anchorTotal = _anchor == _LhAnchor.verified && heroVerified > 0
          ? heroVerified
          : heroSales;
      final heroRevenue = _heroAmountFrom(
        metrics: metrics,
        useRowAmounts: useRowAmounts,
        metricsMatch: metricsMatch,
        keys: const ['revenue'],
        rowSum: sumRevenue,
      );
      final heroTotalCost = _heroAmountFrom(
        metrics: metrics,
        useRowAmounts: useRowAmounts,
        metricsMatch: metricsMatch,
        keys: const ['totalCost', 'costTotal'],
        rowSum: sumTotalCost,
      );
      final heroCost = _heroAmountFrom(
        metrics: metrics,
        useRowAmounts: useRowAmounts,
        metricsMatch: metricsMatch,
        keys: const ['cost', 'operatingCost'],
        rowSum: sumCost,
      );
      final heroProjectCost = _heroAmountFrom(
        metrics: metrics,
        useRowAmounts: useRowAmounts,
        metricsMatch: metricsMatch,
        keys: const ['projectCost'],
        rowSum: sumProjectCost,
      );
      final heroNetProfit = _heroAmountFrom(
        metrics: metrics,
        useRowAmounts: useRowAmounts,
        metricsMatch: metricsMatch,
        keys: const ['netProfit'],
        rowSum: sumNetProfit,
      );
      final heroHandling = _heroAmountFrom(
        metrics: metrics,
        useRowAmounts: useRowAmounts,
        metricsMatch: metricsMatch,
        keys: const ['handlingFee'],
        rowSum: sumHandlingFee,
      );
      final heroPlatform = _heroAmountFrom(
        metrics: metrics,
        useRowAmounts: useRowAmounts,
        metricsMatch: metricsMatch,
        keys: const ['platformServiceFee'],
        rowSum: sumPlatformFee,
      );
      final heroGmv = _heroAmountFrom(
        metrics: metrics,
        useRowAmounts: useRowAmounts,
        metricsMatch: metricsMatch,
        keys: const ['gmv'],
        rowSum: sumGmv,
      );
      final heroSpread = _heroAmountFrom(
        metrics: metrics,
        useRowAmounts: useRowAmounts,
        metricsMatch: metricsMatch,
        keys: const ['spread'],
        rowSum: sumSpread,
      );
      final roiBase = lighthouseValidRateBase(
        heroTotalCost,
        minimumBase: _kRoiAnchorMinYuan,
      );
      final sumRate = roiBase > 0 ? periodProfit / roiBase * 100 : 0.0;
      final gmKey = lighthouseGrossMarginDenominatorKey(
        product: _grossMarginContextProduct,
        group: _grossMarginContextGroup,
        basis: _grossMarginContextBasis,
      );
      final gmRaw = gmKey == 'gmv'
          ? heroGmv
          : gmKey == 'sales'
          ? heroSales
          : heroVerified;
      final gmBase = lighthouseValidRateBase(
        gmRaw,
        minimumBase: _kRoiAnchorMinYuan,
      );
      final grossMargin = gmBase > 0 ? periodProfit / gmBase * 100 : 0.0;
      final spreadRate = anchorTotal > 0
          ? heroRevenue / anchorTotal * 100
          : 0.0;
      final heroPrepaid = _heroAmountFrom(
        metrics: metrics,
        useRowAmounts: useRowAmounts,
        metricsMatch: metricsMatch,
        keys: const ['prepaid'],
        rowSum: sumPrepaid,
      );
      // 净TA 是公司级银行流水，不能按产品行加总。
      final heroNetTa = _heroAmountFrom(
        metrics: metrics,
        useRowAmounts: false,
        metricsMatch: metricsMatch,
        keys: const ['netTa'],
        rowSum: 0,
      );
      totals = {
        'sales': heroSales,
        'verifiedSales': heroVerified,
        'prepaid': heroPrepaid,
        'netTa': heroNetTa,
        'netTaOperating': _netTACategoryAmount('经营活动'),
        'netTaFinancing': _netTACategoryAmount('筹资活动'),
        'netTaOpCost': _netTACategoryAmount('经营成本'),
        'netTaProjectBiz':
            _netTACategoryAmount('项目成本') + _netTACategoryAmount('业务成本'),
        'gmv': heroGmv,
        'cost': heroCost,
        'projectCost': heroProjectCost,
        'totalCost': heroTotalCost,
        'costTotal': heroTotalCost,
        'spread': heroSpread,
        'businessCost': heroCost,
        'handlingFee': heroHandling,
        'platformServiceFee': heroPlatform,
        'profit': periodProfit,
        'netProfit': heroNetProfit,
        'revenue': heroRevenue,
        'grossMargin': grossMargin,
        'spreadRate': spreadRate,
        'rate': sumRate,
      };
      if (_tab == 'netTa') {
        // 净TA 指标栏的流入 / 流出 / 五类净额全部来自 metrics（公司级银行流水），
        // 不能按行加总，所以在这里补进 totals 而不是走 rowSum。
        for (final key in lighthouseNetTAHeroMetricKeys()) {
          final value = _metricNum(metrics, key);
          if (value != null) totals[key] = value;
        }
      }
      profitSeries = _tab == 'netTa'
          ? _seriesForMetric('netTa')
          : _seriesForMetric('profit');
    }

    // 一级 / 二级共用：点住某一天 → 大数、环比、指标栏切到那一天，并出「回本期」。
    final pointTotals = _heroPointIndex == null
        ? null
        : _heroTotalsAtPoint(_heroPointIndex!, totals);
    heroPointActive = pointTotals != null;
    heroTotals = pointTotals ?? totals;
    heroMastheadValue = _mastheadValueForKey(heroTotals, mastheadKey);
    mastheadIsNeg =
        !lighthouseHeroMetricDisplaysMagnitude(mastheadKey) &&
        heroMastheadValue < 0;

    // 点选某一期：大数、环比、指标栏都切到那一点；环比用该点对前一点。
    final rawDelta = heroPointActive
        ? _deltaAtHeroPoint(mastheadKey)
        : (profitDeltaOverride ?? _mastheadDeltaForKey(mastheadKey));
    // 大数用和账本格子同一把尺：筛到某个小分类、或者点到某一天时，Hero 一样
    // 会冒出「0.02万 ↑300%」这种没法核对的数（见 lighthouseDeltaIsReadable）。
    final profitDelta =
        rawDelta != null &&
            lighthouseDeltaIsReadable(
              rawDelta.isUp ? rawDelta.pct.abs() : -rawDelta.pct.abs(),
              value: heroMastheadValue,
              isRate: mastheadIsRate,
            )
        ? rawDelta
        : null;

    final profitLabels =
        (profitLabelsOverride != null && profitLabelsOverride.isNotEmpty)
        ? profitLabelsOverride
        : _heroTrendLabels(profitSeries.length);
    final hasProfitTrend = profitSeries.length >= 2;
    // 主 Hero 与账本展开共用 _TrendChart：叠线 + 图例，点图例只留一条。
    final heroTrendLines = _buildHeroTrendLines(totals, profitSeries);
    final hasMultiTrend = heroTrendLines.length >= 2;
    final hasHeroTrend = _tab == 'netTa' || hasMultiTrend || hasProfitTrend;
    final heroTrendPointCount = heroTrendLines.fold<int>(
      0,
      (acc, l) => math.max(acc, l.values.length),
    );
    final heroTrendLabels =
        (profitLabelsOverride != null &&
            profitLabelsOverride.length == heroTrendPointCount)
        ? profitLabelsOverride
        : _heroTrendLabels(heroTrendPointCount);
    // 选中点的日期，画进大数上方那颗标签胶囊里 —— 大数换了口径，
    // 标签必须当场说清楚换成了哪一天，否则就是一个没有出处的数字。
    final heroPointIdx = _heroPointIndex;
    final heroPointLabel =
        (heroPointActive &&
            heroPointIdx != null &&
            heroPointIdx >= 0 &&
            heroPointIdx < heroTrendLabels.length)
        ? heroTrendLabels[heroPointIdx]
        : null;
    final title = summaryTitle ?? _l1SummaryTitle;
    final rangeLabel = _selectedRangeLabel;
    // 产品 / 供给 / 渠道的汇总 Hero 共用同一视觉身份；只替换标题和数据。
    final summaryAccent = DunesColors.resolve(context, _LhPlum.primary);
    // 图标按维度换：产品 = 货品盒，供给 = 加油站（供给方就是油站），
    // 渠道 = 分流，人效 = 人群；不再是一个看不出含义的「仪表盘」。
    final summaryIcon = switch (_tab) {
      'supply' => Icons.local_gas_station_rounded,
      'channel' => Icons.alt_route_rounded,
      'people' => Icons.groups_rounded,
      'netTa' => Icons.account_balance_wallet_rounded,
      _ => Icons.inventory_2_rounded,
    };

    // v14 · 版式压缩 441 → ~300pt (首屏占比 53% → 36%, 列表可见 2 行 → 4 行)：
    //   · §02 大数与环比并到同一 baseline —— 省一整行 (−24)
    //   · §03 hero sparkline 60 → 38 —— 折线读的是形状不是幅值 (−26)
    //   · §04 hairline 分隔线删除 —— 折线本身已是视觉断点，再画一条是重复 (−15)
    //   · §05 stat rail 每格四层压到三层，去掉 30×10 迷你折线 (−59)
    //     30px 宽画不出任何可辨认形状，七格白扔 119pt。指标一个不减。
    //   字号阶梯收敛成 34 / 16 / 13 / 11 / 10 五档，8.5 与 9 全部上提。
    return LighthouseShareableCard(
      session: widget.session,
      title: title,
      rangeLabel: rangeLabel,
      data: () => _sharedCardData(kind: 'hero', title: title, totals: totals),
      previewBuilder: _sharedCardPreview,
      builder: (shareIcon) => Column(
        mainAxisSize: MainAxisSize.min,
        crossAxisAlignment: CrossAxisAlignment.start,
        children: [
          AnimatedSize(
            duration: const Duration(milliseconds: 280),
            curve: Curves.easeOutCubic,
            alignment: Alignment.topCenter,
            child: Column(
              crossAxisAlignment: CrossAxisAlignment.start,
              children: [
          // ── § 01 · 来源路径 + 当前页标题 ───────────────────────────
          if (summaryTitleWidget != null) ...[
            summaryTitleWidget,
            const SizedBox(height: 8),
          ],
          Row(
            crossAxisAlignment: CrossAxisAlignment.center,
            children: [
              if (lighthouseHeroShowsLiveMetadata) ...[
                Container(
                  width: 5,
                  height: 5,
                  decoration: BoxDecoration(
                    color: DunesColors.resolve(
                      context,
                      _LhPlum.primary,
                      role: DunesColorRole.surface,
                    ),
                    shape: BoxShape.circle,
                  ),
                ),
                const SizedBox(width: 8),
                Text(
                  'LIVE',
                  style: LhTypography.mono(
                    size: 10,
                    color: DunesColors.resolve(context, _LhPlum.primary),
                    weight: FontWeight.w700,
                    letterSpacing: 1.6,
                    context: context,
                  ),
                ),
                const SizedBox(width: 12),
              ],
              Container(
                width: lighthouseHeroSummaryIconSize,
                height: lighthouseHeroSummaryIconSize,
                // 卡标题是这一屏层级最高的字：图标片走实心 + 白图标，
                // 不能比下面「规模 / 成本 / 利润」的实心小片还淡。
                // 2026-10 · 实心紫 → 紫到深紫的斜向渐变 + 一圈很淡的内高光，
                //   像一枚小徽章，跟顶部深色带同一个色系。
                decoration: BoxDecoration(
                  gradient: LinearGradient(
                    begin: Alignment.topLeft,
                    end: Alignment.bottomRight,
                    colors: [
                      summaryAccent,
                      DunesColors.resolve(
                        context,
                        _LhPlum.deep,
                        role: DunesColorRole.surface,
                      ),
                    ],
                  ),
                  border: Border.all(
                    color: Colors.white.withAlpha(60),
                    width: 0.8,
                  ),
                  borderRadius: BorderRadius.circular(
                    lighthouseHeroSummaryIconRadius,
                  ),
                  boxShadow: [
                    BoxShadow(
                      color: _LhPlum.deep.withAlpha(50),
                      blurRadius: 6,
                      spreadRadius: -2,
                      offset: const Offset(0, 2),
                    ),
                  ],
                ),
                child: Icon(
                  summaryIcon,
                  size: 12.5,
                  color: DunesColors.resolve(context, LhColors.paper),
                ),
              ),
              const SizedBox(width: 8),
              // 左组：标题 + 真实区间 + 分类筛选；右端挂同步落款。
              Expanded(
                child: Row(
                  children: [
                    Flexible(
                      // 2026-10-26 · 截图量过：标题字（16 号中文、行高 1.1）的字面中线
                      // 比左边徽章、日期章、「已同步」、转发钮低 1.5px，整行看着不在
                      // 一条线上。底下垫 3px，字面中线上提 1.5px，和整行对齐。
                      child: Padding(
                        padding: const EdgeInsets.only(bottom: 3),
                        child: LhScrollText(
                          title,
                          maxLines: 1,
                          overflow: TextOverflow.ellipsis,
                          style: LhTypography.sans(
                            size: lighthouseHeroSummaryTitleFontSize,
                            color: DunesColors.resolve(context, LhColors.ink),
                            weight: FontWeight.w700,
                            letterSpacing: 0,
                            height: 1.1,
                            context: context,
                          ),
                        ),
                      ),
                    ),
                    if (lighthouseHeroShowsDateStamp &&
                        rangeLabel.isNotEmpty) ...[
                      const SizedBox(width: 8),
                      Flexible(child: _heroDateStamp(rangeLabel)),
                    ],
                    if (showFilters && _activeHeroFilters().isNotEmpty) ...[
                      const SizedBox(width: 10),
                      _buildHeroFilterStack(),
                    ],
                  ],
                ),
              ),
              // 「已同步 · 09:41」上提到标题行右端：它是这张卡的出处说明，
              // 留在卡底时正好卡在 Hero 与账本之间，把那道衔接撑成一条空带。
              if (totalsOverride == null) ...[
                const SizedBox(width: 8),
                _buildHeroSyncStamp(inline: true),
              ],
              const SizedBox(width: 4),
              shareIcon,
            ],
          ),
          // 拍平版的结构全靠线：标题行下这条是「汇总从这里开始」。
          // 比其它分隔线重一档，它是这一屏里层级最高的一条。
          if (lighthouseHeroUsesFlatLayout && totalsOverride == null) ...[
            const SizedBox(height: 9),
            Container(
              height: 1,
              color: DunesColors.resolve(
                context,
                LhColors.line,
                role: DunesColorRole.surface,
              ),
            ),
          ],
          // 有记录时标题下不直接铺横幅。小喇叭点开后，这里才是 message 原文。
          if (totalsOverride == null &&
              _delayNoticeOpen &&
              _activeDelayNotices.isNotEmpty)
            _buildDelayNoticePanel(_activeDelayNotices),

          // ── § 02 · 主数与趋势左右并排；窄屏只加高走势图 ─────────
          // 2026-10-26 · 上滑收起不再收这一块，只收下面的规模 / 成本 / 利润。
          Padding(
            padding: const EdgeInsets.only(top: 10, bottom: 10),
            child: LayoutBuilder(
              builder: (context, box) {
                final heroW = box.maxWidth;
                // 2026-10-26 · 手机（窄于 480）大数卡 3:7 只剩 ~107px：资金页「8367万」32 号放不下、
                //   截至日期挤出界。手机改 4:6（~142px），平板 / 桌面照旧 3:7。
                final heroPhone = heroW < 480;
                final heroKpiFlex = heroPhone ? 4 : lighthouseCompactHeroKpiFlex;
                final heroTrendFlex = heroPhone ? 6 : lighthouseCompactHeroTrendFlex;
                final hasBankBalance =
                    _tab == 'netTa' &&
                    (_bundle?.metrics['netTaBankBalance'] as num?) != null;
                final baseSparkH = _tab == 'netTa'
                    ? lighthouseNetTAHeroSparkHeightFor(
                        heroW,
                        hasBankBalance: hasBankBalance,
                        hasBiButton: totalsOverride == null,
                      )
                    : lighthouseCompactHeroSparkHeightFor(
                        heroW,
                        hasBiButton: totalsOverride == null,
                      );
                // v24 · 手机上这一段是被图例压垮的：图例几行、有没有月末预测条
                //   都在跟走势图抢同一个固定高度。改成「图例要多高就给多高，
                //   走势图保底 104」，不够就把整段撑开 —— 图不再让位。
                // 宽度只用来判图例排两列还是三列；两栏中缝按最宽的那版（拍平版
                // 12 + 0.7 + 12）扣，宁可估窄一点 —— 估窄只会多留高度。
                final trendColW =
                    (heroW - 25) *
                        heroTrendFlex /
                        (heroKpiFlex +
                            heroTrendFlex) -
                    lighthouseHeroChartCardPadding * 2;
                final sparkH = math.max(
                  baseSparkH,
                  lighthouseHeroTrendSectionMinHeightFor(
                    screenWidth: MediaQuery.sizeOf(context).width,
                    legendWidth: trendColW,
                    metricCount: _heroLegendMetricCount(),
                    hasForecastStrip: _isCurrentMonthView,
                  ),
                );
                final chartMaxH = lighthouseCompactHeroChartMaxHeightFor(heroW);
                final trendSectionH =
                    sparkH + lighthouseHeroChartCardPadding * 2;

                // 拍平版：两块内容不再各住一张卡，靠中间一条竖线分开。
                final flatHero =
                    lighthouseHeroUsesFlatLayout && totalsOverride == null;
                // 2026-10-21 · 一级产品 / 供给 / 渠道：大数卡翻页（利润 ⇄ 资金），
                //   右卡换成新走势卡（多线 + 资金模式）。
                final heroPaged =
                    totalsOverride == null &&
                    !flatHero &&
                    _tab != 'netTa' &&
                    _heroAssetsEligible;
                final useNewTrend =
                    lighthouseHeroUsesTrendCard &&
                    totalsOverride == null &&
                    !flatHero &&
                    _tab != 'netTa' &&
                    hasHeroTrend &&
                    widget.sharedCard == null;
                final profitPanel =
                    lighthouseHeroKpiUsesResultTint &&
                    mastheadKey == 'profit' &&
                    lighthouseHeroMatchesLedgerCard;
                final kpiCard = Container(
                  decoration: flatHero
                      ? null
                      : (lighthouseHeroMatchesLedgerCard
                            ? BoxDecoration(
                                color: profitPanel
                                    ? DunesColors.resolve(
                                        context,
                                        const Color(
                                          lighthouseLedgerResultBlockAccentValue,
                                        ),
                                        role: DunesColorRole.surface,
                                      ).withAlpha(
                                        lighthouseLedgerSummaryResultPanelAlpha,
                                      )
                                    : DunesColors.resolve(
                                        context,
                                        const Color(
                                          lighthouseLedgerSummaryNeutralPanelValue,
                                        ),
                                        role: DunesColorRole.surface,
                                      ),
                                border: Border.all(
                                  color: profitPanel
                                      ? DunesColors.resolve(
                                          context,
                                          const Color(
                                            lighthouseLedgerResultBlockAccentValue,
                                          ),
                                          role: DunesColorRole.border,
                                        ).withAlpha(
                                          lighthouseHeroPanelResultEdgeAlpha,
                                        )
                                      : DunesColors.resolve(
                                          context,
                                          const Color(
                                            lighthouseHeroPanelNeutralEdgeValue,
                                          ),
                                          role: DunesColorRole.border,
                                        ),
                                  width: lighthouseHeroPanelEdgeWidth,
                                ),
                                borderRadius: BorderRadius.circular(
                                  lighthouseLedgerSummaryPanelRadius,
                                ),
                              )
                            : BoxDecoration(
                                color: DunesColors.resolve(
                                  context,
                                  const Color(0xFFFFFDFF),
                                  role: DunesColorRole.surface,
                                ),
                                border: Border.all(
                                  color: DunesColors.resolve(
                                    context,
                                    _LhPlum.heroEdge,
                                    role: DunesColorRole.border,
                                  ),
                                  width: 0.7,
                                ),
                                borderRadius: BorderRadius.circular(
                                  lighthouseHeroCardRadius,
                                ),
                              )),
                  // 固定行高内容偏满时勿裁切环比行（↓xx% vs 昨日）。
                  clipBehavior: Clip.none,
                  child: Column(
                    crossAxisAlignment: CrossAxisAlignment.stretch,
                    children: [
                      // 内边距下沉到内容层：BI 底栏要通栏贴到卡的两边和底边，
                      // 留着外层 padding 它就只能是一颗浮在留白里的钮。
                      Expanded(
                        // 2026-10-21 · 左滑翻到「资金与资产」（一级产品 / 供给 / 渠道）。
                        child: _heroKpiPaged(
                          enabled: heroPaged,
                          heroTotals: heroTotals,
                          labels: heroTrendLabels.isNotEmpty
                              ? heroTrendLabels
                              : profitLabels,
                          first: Padding(
                          // 拍平版没有卡，左边不再缩进 —— 大数要和标题、和下面
                          // 分区表头的左缘对齐成一条线，那条线是整屏的基准。
                          padding: flatHero
                              ? const EdgeInsets.fromLTRB(0, 2, 8, 0)
                              : heroPaged
                              // 顶部留 38 给「利润 | 资金」切换条（6 + 24 + 8）。
                              ? const EdgeInsets.fromLTRB(8, 38, 8, 8)
                              : const EdgeInsets.fromLTRB(8, 6, 8, 4),
                          child: Column(
                            crossAxisAlignment: CrossAxisAlignment.stretch,
                            // 银行余额钉在顶上；标签+大数+环比在剩余高度里垂直居中。
                            // 产品汇总没有银行余额时，整块内容就会落在卡正中。
                            children: [
                              if (_tab == 'netTa') _buildNetTABankBalanceLine(),
                              // 大数块高度是定死的：选毛利率时多一行「利润 ÷ 核销额」，
                              // 内容会比格子高几个像素（底部溢出黄黑条）。放不下时整块
                              // 按比例缩一点点（4px ≈ 3%，肉眼看不出），不再溢出。
                              Expanded(
                                child: LayoutBuilder(
                                  builder: (context, mastheadBox) => FittedBox(
                                    fit: BoxFit.scaleDown,
                                    alignment: Alignment.centerLeft,
                                    child: SizedBox(
                                      width: mastheadBox.maxWidth,
                                      child: Column(
                                        mainAxisSize: MainAxisSize.min,
                                        crossAxisAlignment:
                                            CrossAxisAlignment.stretch,
                                        mainAxisAlignment:
                                            MainAxisAlignment.center,
                                        children: [
                                          if (lighthouseHeroMastheadLabelAboveNumber) ...[
                                            Align(
                                              alignment: Alignment.centerLeft,
                                              child: Container(
                                                padding:
                                                    const EdgeInsets.fromLTRB(
                                                      5,
                                                      4,
                                                      7,
                                                      4,
                                                    ),
                                                decoration: BoxDecoration(
                                                  color: profitPanel
                                                      ? DunesColors.resolve(
                                                          context,
                                                          const Color(
                                                            lighthouseHeroResultSectionChipValue,
                                                          ),
                                                          role: DunesColorRole
                                                              .surface,
                                                        )
                                                      : DunesColors.resolve(
                                                          context,
                                                          _LhPlum.primary,
                                                          role: DunesColorRole
                                                              .surface,
                                                        ).withAlpha(12),
                                                  borderRadius:
                                                      BorderRadius.circular(
                                                        lighthouseHeroMastheadLabelRadius,
                                                      ),
                                                ),
                                                child: Row(
                                                  children: [
                                                    Container(
                                                      width:
                                                          lighthouseHeroMastheadLabelIconSize,
                                                      height:
                                                          lighthouseHeroMastheadLabelIconSize,
                                                      decoration: BoxDecoration(
                                                        color: profitPanel
                                                            ? DunesColors.resolve(
                                                                context,
                                                                const Color(
                                                                  lighthouseLedgerResultBlockAccentValue,
                                                                ),
                                                                role:
                                                                    DunesColorRole
                                                                        .surface,
                                                              ).withAlpha(34)
                                                            : DunesColors.resolve(
                                                                context,
                                                                _LhPlum.primary,
                                                                role:
                                                                    DunesColorRole
                                                                        .surface,
                                                              ).withAlpha(24),
                                                        borderRadius:
                                                            BorderRadius.circular(
                                                              5,
                                                            ),
                                                      ),
                                                      child: Icon(
                                                        Icons
                                                            .trending_up_rounded,
                                                        size: 11,
                                                        color: profitPanel
                                                            ? DunesColors.resolve(
                                                                context,
                                                                const Color(
                                                                  lighthouseHeroResultSectionTitleValue,
                                                                ),
                                                              )
                                                            : DunesColors.resolve(
                                                                context,
                                                                _LhPlum.primary,
                                                              ),
                                                      ),
                                                    ),
                                                    const SizedBox(width: 5),
                                                    // 选中某一天时，日期**替换**掉口径名而不是排在它
                                                    // 后面 —— 追加的写法会把「本月利润」挤成「本日…」，
                                                    // 而日期本来就是更具体的那一个，该它站在前面。
                                                    if (heroPointLabel !=
                                                        null) ...[
                                                      // 2026-10-21 · 日期不再参与缩：窄卡上「10.16」被挤成「10.…」，
                                                      // 读不出是哪一天。日期最短也就「2026.10」，让口径名去缩。
                                                      Text(
                                                          heroPointLabel,
                                                          maxLines: 1,
                                                          softWrap: false,
                                                          overflow: TextOverflow
                                                              .ellipsis,
                                                          style: _tabular(
                                                            LhTypography.mono(
                                                              size:
                                                                  lighthouseHeroMastheadLabelFontSize,
                                                              color:
                                                                  DunesColors.resolve(
                                                                    context,
                                                                    _LhPlum
                                                                        .primary,
                                                                  ),
                                                              weight: FontWeight
                                                                  .w700,
                                                              letterSpacing:
                                                                  0.2,
                                                              height: 1.0,
                                                              context: context,
                                                            ),
                                                          ),
                                                        ),
                                                      const SizedBox(width: 4),
                                                      Flexible(
                                                        flex: 2,
                                                        child: Text(
                                                          _metricPageLabel(
                                                            mastheadKey,
                                                          ),
                                                          maxLines: 1,
                                                          overflow: TextOverflow
                                                              .ellipsis,
                                                          style: LhTypography.sans(
                                                            size:
                                                                lighthouseHeroMastheadLabelFontSize,
                                                            color:
                                                                DunesColors.resolve(
                                                                  context,
                                                                  LhColors.ink2,
                                                                ),
                                                            weight:
                                                                FontWeight.w600,
                                                            letterSpacing: 0.1,
                                                            height: 1.0,
                                                            context: context,
                                                          ),
                                                        ),
                                                      ),
                                                      const SizedBox(width: 3),
                                                      GestureDetector(
                                                        behavior:
                                                            HitTestBehavior
                                                                .opaque,
                                                        onTap:
                                                            _clearHeroPointSelection,
                                                        child: Padding(
                                                          padding:
                                                              EdgeInsets.symmetric(
                                                                horizontal: 2,
                                                                vertical: 3,
                                                              ),
                                                          child: Icon(
                                                            Icons
                                                                .refresh_rounded,
                                                            size: 11,
                                                            color:
                                                                DunesColors.resolve(
                                                                  context,
                                                                  _LhPlum
                                                                      .primary,
                                                                ),
                                                          ),
                                                        ),
                                                      ),
                                                    ] else ...[
                                                      Flexible(
                                                        child: Text(
                                                          lighthouseHeroMetricPeriodLabel(
                                                            _period,
                                                            mastheadKey,
                                                          ),
                                                          maxLines: 1,
                                                          overflow: TextOverflow
                                                              .ellipsis,
                                                          style: LhTypography.sans(
                                                            size:
                                                                lighthouseHeroMastheadLabelFontSize,
                                                            color:
                                                                DunesColors.resolve(
                                                                  context,
                                                                  LhColors.ink,
                                                                ),
                                                            weight:
                                                                FontWeight.w600,
                                                            letterSpacing: 0.1,
                                                            height: 1.0,
                                                            context: context,
                                                          ),
                                                        ),
                                                      ),
                                                      // 点了下面某个指标后，大数和走势都换成它；
                                                      // 原来只能再点一次那格才回得去，很多人不知道。
                                                      // 这里给一个明面上的 ×，一点回到默认口径。
                                                      if (lighthouseHeroMastheadShowsFocusExit &&
                                                          _expandedTrendKey !=
                                                              null) ...[
                                                        const SizedBox(
                                                          width: 3,
                                                        ),
                                                        GestureDetector(
                                                          behavior:
                                                              HitTestBehavior
                                                                  .opaque,
                                                          onTap: () {
                                                            LighthouseFeedback
                                                                .instance
                                                                .play(
                                                                  LighthouseFeedbackKind
                                                                      .select,
                                                                );
                                                            setState(() {
                                                              _expandedTrendKey =
                                                                  null;
                                                              _heroTraceKey =
                                                                  null;
                                                            });
                                                          },
                                                          child: Padding(
                                                            padding:
                                                                EdgeInsets.symmetric(
                                                                  horizontal: 4,
                                                                  vertical: 3,
                                                                ),
                                                            child: Icon(
                                                              Icons
                                                                  .close_rounded,
                                                              size: 12,
                                                              color:
                                                                  DunesColors.resolve(
                                                                    context,
                                                                    _LhPlum
                                                                        .primary,
                                                                  ),
                                                            ),
                                                          ),
                                                        ),
                                                      ],
                                                    ],
                                                  ],
                                                ),
                                              ),
                                            ),
                                            const SizedBox(height: 6),
                                          ],
                                          if (mastheadKey == 'grossMargin') ...[
                                            Text(
                                              _grossMarginFormula(),
                                              style: LhTypography.sans(
                                                size: 9,
                                                color: DunesColors.resolve(
                                                  context,
                                                  LhColors.ink2,
                                                ),
                                                height: 1.2,
                                                context: context,
                                              ),
                                            ),
                                            const SizedBox(height: 5),
                                          ],
                                          _LhAnimatedNumber(
                                            value: mastheadIsRate
                                                ? heroMastheadValue
                                                : heroMastheadValue.abs(),
                                            duration: const Duration(
                                              milliseconds: 800,
                                            ),
                                            immediate: heroPointActive,
                                            builder: (context, v) => LhScrollRichText(
                                              maxLines: 1,
                                              overflow: TextOverflow.ellipsis,
                                              text: TextSpan(
                                                children: [
                                                  if (mastheadIsNeg)
                                                    TextSpan(
                                                      text: '−',
                                                      style: LhTypography.number(
                                                        size:
                                                            lighthouseHeroMastheadFontSize,
                                                        color:
                                                            DunesColors.resolve(
                                                              context,
                                                              LhColors.pos,
                                                            ),
                                                        context: context,
                                                      ),
                                                    ),
                                                  TextSpan(
                                                    text: mastheadIsRate
                                                        ? v.toStringAsFixed(2)
                                                        : (lighthouseHeroMetricPlainNumber(
                                                                mastheadKey,
                                                                v,
                                                              ) ??
                                                              _fmtMoney(v)),
                                                    style: LhTypography.number(
                                                      size:
                                                          lighthouseHeroMastheadFontSize,
                                                      // 2026-10-26 · 大数和右边选中那一段同色
                                                      // （核销紫、销售蓝、收入琥珀…）；利润负数仍绿。
                                                      color: mastheadIsNeg
                                                          ? DunesColors.resolve(
                                                              context,
                                                              LhColors.pos,
                                                            )
                                                          : (lighthouseHeroSegmentColors[
                                                                        mastheadKey] !=
                                                                    null
                                                                ? DunesColors.resolve(
                                                                    context,
                                                                    lighthouseHeroSegmentColors[
                                                                        mastheadKey]!,
                                                                  )
                                                                : _grossProfitValueColor(
                                                                    mastheadKey,
                                                                    heroMastheadValue,
                                                                    DunesColors.resolve(
                                                                      context,
                                                                      _LhPlum.heroNum,
                                                                    ),
                                                                  )),
                                                      context: context,
                                                    ),
                                                  ),
                                                  TextSpan(
                                                    text: mastheadIsRate
                                                        ? '%'
                                                        : (lighthouseHeroMetricPlainUnit(
                                                                    mastheadKey,
                                                                  ) !=
                                                                  null
                                                              ? ' ${lighthouseHeroMetricPlainUnit(mastheadKey)}'
                                                              : ' ${_unitMoney(v)}'),
                                                    style: LhTypography.sans(
                                                      size: 10.5,
                                                      color:
                                                          DunesColors.resolve(
                                                            context,
                                                            LhColors.mute,
                                                          ),
                                                      weight: FontWeight.w500,
                                                      context: context,
                                                    ),
                                                  ),
                                                ],
                                              ),
                                            ),
                                          ),
                                          const SizedBox(height: 5),
                                          _heroDeltaLine(
                                            profitDelta,
                                            pointMode: heroPointActive,
                                            isRate: mastheadIsRate,
                                            vsLabel: _heroDeltaVsLabel(
                                              pointMode: heroPointActive,
                                              series:
                                                  mastheadKey ==
                                                      'netTaBankBalance'
                                                  ? _netTABankBalanceSeries()
                                                  : _seriesForMetric(
                                                      mastheadKey,
                                                    ),
                                            ),
                                          ),
                                        ],
                                      ),
                                    ),
                                  ),
                                ),
                              ),
                              if (!flatHero &&
                                  _tab != 'netTa' &&
                                  !heroPaged &&
                                  !_hidesSensitiveFinance) ...[
                                Container(
                                  height: 0.7,
                                  margin: const EdgeInsets.fromLTRB(2, 0, 2, 5),
                                  color: profitPanel
                                      ? DunesColors.resolve(
                                          context,
                                          const Color(
                                            lighthouseLedgerResultBlockAccentValue,
                                          ),
                                          role: DunesColorRole.surface,
                                        ).withAlpha(42)
                                      : DunesColors.resolve(
                                          context,
                                          LhColors.line2,
                                          role: DunesColorRole.surface,
                                        ),
                                ),
                                _buildHeroFundsMini(
                                  heroTotals,
                                  withAssets: totalsOverride == null,
                                ),
                              ],
                              // 翻页版：预收净增去了资金页，这里换成近 7 日利润迷你柱。
                              // 敏感财务名单关掉资金页后，也走这根利润柱，避免退回「预收净增」小卡。
                              if (heroPaged ||
                                  (!flatHero &&
                                      _tab != 'netTa' &&
                                      _hidesSensitiveFinance &&
                                      totalsOverride == null))
                                _buildHeroProfitMiniBars(
                                  profitSeries,
                                  pickIndex: heroPointActive ? heroPointIdx : null,
                                  labels: heroTrendLabels.isNotEmpty
                                      ? heroTrendLabels
                                      : profitLabels,
                                ),
                            ],
                          ),
                        ),
                        ),
                      ),
                      // BI 入口钉在大数卡底部：它问的是「这个数还能怎么看」，
                      // 就该长在这个数下面，而不是飘在 Hero 外面自成一块。
                      // 二级/三级不挂 —— 那里的 Hero 已经是某个实体的切片了。
                      if (totalsOverride == null && !_inTopic)
                        _buildHeroBiButton(),
                    ],
                  ),
                );

                final trendCard = useNewTrend
                    ? _buildHeroDualTrend(
                        totals: totals,
                        profitSeries: profitSeries,
                        labels: heroTrendLabels.isNotEmpty
                            ? heroTrendLabels
                            : profitLabels,
                        paged: heroPaged,
                      )
                    : Container(
                  clipBehavior: Clip.none,
                  padding: flatHero
                      ? const EdgeInsets.fromLTRB(0, 2, 0, 0)
                      : const EdgeInsets.all(lighthouseHeroChartCardPadding),
                  decoration: (!lighthouseHeroChartUsesCardSurface || flatHero)
                      ? null
                      : lighthouseHeroMatchesLedgerCard
                      ? BoxDecoration(
                          color: DunesColors.resolve(
                            context,
                            const Color(
                              lighthouseLedgerSummaryNeutralPanelValue,
                            ),
                            role: DunesColorRole.surface,
                          ),
                          border: Border.all(
                            color: DunesColors.resolve(
                              context,
                              const Color(lighthouseHeroPanelNeutralEdgeValue),
                              role: DunesColorRole.border,
                            ),
                            width: lighthouseHeroPanelEdgeWidth,
                          ),
                          borderRadius: BorderRadius.circular(
                            lighthouseLedgerSummaryPanelRadius,
                          ),
                        )
                      : BoxDecoration(
                          color: DunesColors.resolve(
                            context,
                            const Color(0xFFFFFDFF),
                            role: DunesColorRole.surface,
                          ),
                          border: Border.all(
                            color: DunesColors.resolve(
                              context,
                              _LhPlum.heroEdge,
                              role: DunesColorRole.border,
                            ),
                            width: 0.7,
                          ),
                          borderRadius: BorderRadius.circular(
                            lighthouseHeroCardRadius,
                          ),
                          boxShadow: lighthouseHeroUsesCardShadow
                              ? [
                                  BoxShadow(
                                    color: Colors.black.withAlpha(9),
                                    blurRadius: 8,
                                    offset: const Offset(0, 2),
                                  ),
                                ]
                              : null,
                        ),
                  child:
                      (_tab == 'netTa' &&
                          _netTaBalanceOpen &&
                          _netTABankBalanceCanOpen)
                      ? _buildNetTABankBalancePanel()
                      : hasHeroTrend
                      ? _buildHeroUnifiedTrendChart(
                          totals: totals,
                          profitSeries: profitSeries,
                          labels: heroTrendLabels.isNotEmpty
                              ? heroTrendLabels
                              : profitLabels,
                          chartMaxHeight: chartMaxH,
                        )
                      : SizedBox(height: sparkH),
                );

                // 2026-10-21 · 走势卡左滑拉宽，大数卡收成竖条（lighthouse_hero_swipe.dart）。
                //   拍平版没有卡、没有走势时不挂 —— 没有东西可拉。
                if (!flatHero && hasHeroTrend) {
                  return SizedBox(
                    height: trendSectionH,
                    child: LighthouseHeroWideRow(
                      wide: _heroTrendWide,
                      onWideChanged: _setHeroTrendWide,
                      kpiFlex: heroKpiFlex,
                      trendFlex: heroTrendFlex,
                      gap: 10,
                      radius: lighthouseHeroMatchesLedgerCard
                          ? lighthouseLedgerSummaryPanelRadius
                          : lighthouseHeroCardRadius,
                      accent: DunesColors.resolve(context, _LhPlum.primary),
                      // 2026-10-21 · 拉到头不再自动弹全屏大图（像 bug）；
                      //   要看大图点走势卡右上角的小 K 线。
                      onOverpull: null,
                      overpullHint: _heroOverpullHint(),
                      kpi: kpiCard,
                      rail: heroPaged && _heroKpiPage == 1
                          ? _buildHeroWideRail(
                              label: _billFocusActive
                                  ? (_billFocus == 'AR' ? '应收未回款' : '应付未付款')
                                  : '总资产',
                              mastheadKey: 'totalAssets',
                              value: _billFocusActive
                                  ? (_bills!.totalOf(_billFocus!)?.unpaidAmount ?? 0)
                                  : (_heroAssetLine('total')?.amounts?.totalAssets ??
                                        0),
                              isRate: false,
                              isNeg: false,
                              delta: null,
                              profitPanel: false,
                            )
                          : _buildHeroWideRail(
                              label: lighthouseHeroMetricPeriodLabel(
                                _period,
                                mastheadKey,
                              ),
                              mastheadKey: mastheadKey,
                              value: heroMastheadValue,
                              isRate: mastheadIsRate,
                              isNeg: mastheadIsNeg,
                              delta: profitDelta,
                              profitPanel: profitPanel,
                            ),
                      trend: trendCard,
                    ),
                  );
                }
                return SizedBox(
                  height: trendSectionH,
                  child: Row(
                    crossAxisAlignment: CrossAxisAlignment.stretch,
                    children: [
                      Expanded(
                        flex: heroKpiFlex,
                        child: kpiCard,
                      ),
                      if (flatHero) ...[
                        const SizedBox(width: 12),
                        Container(
                          width: 0.7,
                          color: DunesColors.resolve(
                            context,
                            LhColors.line2,
                            role: DunesColorRole.surface,
                          ),
                        ),
                        const SizedBox(width: 12),
                      ] else
                        const SizedBox(width: 10),
                      Expanded(
                        flex: heroTrendFlex,
                        child: trendCard,
                      ),
                    ],
                  ),
                );
              },
            ),
          ),

          if (totalsOverride == null &&
              _heroAssetOpen &&
              _heroAssetsEligible &&
              !lighthouseHeroFundsInHero &&
              _heroAssetLines.isNotEmpty) ...[
            _buildHeroAssetPanel(),
          ],
              ],
            ),
          ),
          // ── § 05 · Stat rail (7 格全平铺, 固定 4 列网格) ─────────────
          // netTa 走同一条路径，只是分区换成 流入 / 流出 / 未映射 / 五类净额。
          // 拍平版：大数区和分区表之间只留一段空白 —— 分区表自己的浅灰栏头
          // 已经是一条足够强的界线，再加线就成了两道。
          // 跟手折叠必须放在外层 AnimatedSize 外面：高度每帧在变，套进去会
          // 在自己的 performLayout 里重启动画，触发 RenderAnimatedSize 断言。
          if (lighthouseHeroUsesFlatLayout && totalsOverride == null)
            const SizedBox(height: 14),
          if (totalsOverride == null)
            LighthouseFoldSection(
              folded: _heroFolded,
              onFoldedChanged: _setHeroFolded,
              handleBuilder: (context, t) => _buildHeroFoldHandle(t),
              // 2026-10-28 · 资金页：规模 / 成本 / 利润下面多一块「账款」（资管账单）。
              // 利润页、专题、二级页都不出；和分区表一起折叠。
              child: (_heroAssetsEligible && _heroKpiPage == 1)
                  ? Column(
                      crossAxisAlignment: CrossAxisAlignment.stretch,
                      mainAxisSize: MainAxisSize.min,
                      children: [
                        _buildHeroStatRail(heroTotals),
                        _buildBillPanel(),
                      ],
                    )
                  : _buildHeroStatRail(heroTotals),
            )
          else
            _buildHeroStatRail(heroTotals),
        ],
      ),
    );
  }

  /// 查挂了才在落款旁写这一句。没有记录不写，有记录走小喇叭。
  Widget _buildDelayNoticeMissNote(String text) {
    return Text(
      text,
      maxLines: 1,
      overflow: TextOverflow.ellipsis,
      style: LhTypography.sans(
        size: 8.5,
        color: DunesColors.resolve(context, LhColors.mute),
        weight: FontWeight.w600,
        letterSpacing: 0.2,
        height: 1.0,
        context: context,
      ),
    );
  }

  /// 小喇叭固定留在 Hero 顶部：有预警时高亮并可展开，没有时灰显常驻。
  Widget _buildDelayNoticeHorn() {
    final noticeCount = _activeDelayNotices.length;
    final hasNotices = noticeCount > 0;
    final open = _delayNoticeOpen && hasNotices;
    var color = DunesColors.resolve(context, LhColors.mute2);
    if (hasNotices) {
      color = DunesColors.resolve(context, LhColors.copper);
    }
    return Semantics(
      button: hasNotices,
      enabled: hasNotices,
      label: hasNotices ? '$noticeCount 条运行提醒' : '暂无运行提醒',
      child: _LhScrollSafeTap(
        onTap: () {
          if (!hasNotices) return;
          LighthouseFeedback.instance.play(LighthouseFeedbackKind.select);
          setState(() => _delayNoticeOpen = !_delayNoticeOpen);
        },
        child: SizedBox(
          width: 17,
          height: 15,
          child: Stack(
            clipBehavior: Clip.none,
            children: [
              Positioned(
                left: 0,
                top: 1,
                child: Icon(
                  Icons.campaign_rounded,
                  size: 13,
                  color: DunesColors.resolveNullable(context, color),
                ),
              ),
              if (hasNotices)
                Positioned(
                  right: 0,
                  top: 0,
                  child: Container(
                    width: 5,
                    height: 5,
                    decoration: BoxDecoration(
                      color: open
                          ? DunesColors.resolve(
                              context,
                              _LhPlum.primary,
                              role: DunesColorRole.surface,
                            )
                          : DunesColors.resolve(
                              context,
                              LhColors.copper,
                              role: DunesColorRole.surface,
                            ),
                      shape: BoxShape.circle,
                      border: Border.all(
                        color: DunesColors.resolve(
                          context,
                          LhColors.paper,
                          role: DunesColorRole.border,
                        ),
                        width: 0.8,
                      ),
                    ),
                  ),
                ),
            ],
          ),
        ),
      ),
    );
  }

  /// 点开小喇叭后的提醒面板。多条通知收在同一个容器里，正文仍是
  /// `message` 原文，不改写、不拼接。
  Widget _buildDelayNoticePanel(List<LighthouseDelayNotice> notices) {
    return Container(
      margin: const EdgeInsets.only(top: 8),
      decoration: BoxDecoration(
        gradient: LinearGradient(
          begin: Alignment.topLeft,
          end: Alignment.bottomRight,
          colors: [
            DunesColors.resolve(
              context,
              LhColors.paper,
              role: DunesColorRole.surface,
            ),
            DunesColors.resolve(
              context,
              LhColors.copperSoft,
              role: DunesColorRole.surface,
            ).withAlpha(92),
          ],
        ),
        borderRadius: BorderRadius.circular(13),
        border: Border.all(
          color: DunesColors.resolve(
            context,
            LhColors.copper,
            role: DunesColorRole.border,
          ).withAlpha(42),
          width: 0.7,
        ),
        boxShadow: const [
          BoxShadow(
            color: Color(0x0A2F2418),
            blurRadius: 12,
            offset: Offset(0, 4),
          ),
        ],
      ),
      clipBehavior: Clip.antiAlias,
      child: Column(
        children: [
          Padding(
            padding: const EdgeInsets.fromLTRB(11, 8, 9, 7),
            child: Row(
              children: [
                Container(
                  width: 22,
                  height: 22,
                  decoration: BoxDecoration(
                    color: DunesColors.resolve(
                      context,
                      LhColors.copper,
                      role: DunesColorRole.surface,
                    ).withAlpha(18),
                    borderRadius: BorderRadius.circular(7),
                  ),
                  child: Icon(
                    Icons.notifications_none_rounded,
                    size: 13,
                    color: DunesColors.resolve(context, LhColors.copper),
                  ),
                ),
                const SizedBox(width: 7),
                Text(
                  '运行提醒',
                  style: LhTypography.sans(
                    size: 10.5,
                    color: DunesColors.resolve(context, LhColors.ink),
                    weight: FontWeight.w700,
                    letterSpacing: 0.1,
                    context: context,
                  ),
                ),
                const Spacer(),
                Container(
                  padding: const EdgeInsets.symmetric(
                    horizontal: 7,
                    vertical: 3,
                  ),
                  decoration: BoxDecoration(
                    color: DunesColors.resolve(
                      context,
                      LhColors.paper,
                      role: DunesColorRole.surface,
                    ).withAlpha(190),
                    borderRadius: BorderRadius.circular(999),
                    border: Border.all(
                      color: DunesColors.resolve(
                        context,
                        LhColors.copper,
                        role: DunesColorRole.border,
                      ).withAlpha(30),
                      width: 0.6,
                    ),
                  ),
                  child: Text(
                    '${notices.length} 条待关注',
                    style: LhTypography.sans(
                      size: 8.5,
                      color: DunesColors.resolve(context, LhColors.copper),
                      weight: FontWeight.w700,
                      context: context,
                    ),
                  ),
                ),
              ],
            ),
          ),
          Container(
            height: 0.7,
            color: DunesColors.resolve(
              context,
              LhColors.copper,
              role: DunesColorRole.surface,
            ).withAlpha(24),
          ),
          ...List<Widget>.generate(notices.length, (index) {
            final notice = notices[index];
            return Column(
              children: [
                _buildDelayNoticePanelRow(notice),
                if (index < notices.length - 1)
                  Padding(
                    padding: const EdgeInsets.only(left: 40, right: 11),
                    child: Container(
                      height: 0.6,
                      color: DunesColors.resolve(
                        context,
                        LhColors.line2,
                        role: DunesColorRole.surface,
                      ),
                    ),
                  ),
              ],
            );
          }),
        ],
      ),
    );
  }

  Widget _buildDelayNoticePanelRow(LighthouseDelayNotice notice) {
    final label = notice.isServerProbe
        ? (notice.bizDeptName.isEmpty ? '服务' : notice.bizDeptName)
        : '数据同步';
    final icon = notice.isServerProbe
        ? Icons.dns_outlined
        : Icons.sync_problem_rounded;
    return Padding(
      padding: const EdgeInsets.fromLTRB(11, 8, 11, 9),
      child: Row(
        crossAxisAlignment: CrossAxisAlignment.start,
        children: [
          Container(
            width: 21,
            height: 21,
            decoration: BoxDecoration(
              color: DunesColors.resolve(
                context,
                LhColors.paper,
                role: DunesColorRole.surface,
              ).withAlpha(205),
              borderRadius: BorderRadius.circular(7),
              border: Border.all(
                color: DunesColors.resolve(
                  context,
                  LhColors.copper,
                  role: DunesColorRole.border,
                ).withAlpha(32),
                width: 0.6,
              ),
            ),
            child: Icon(
              icon,
              size: 12,
              color: DunesColors.resolve(context, LhColors.copper),
            ),
          ),
          const SizedBox(width: 8),
          Expanded(
            child: Column(
              crossAxisAlignment: CrossAxisAlignment.start,
              children: [
                Text(
                  label,
                  style: LhTypography.sans(
                    size: 8.5,
                    color: DunesColors.resolve(context, LhColors.copper),
                    weight: FontWeight.w700,
                    letterSpacing: 0.15,
                    height: 1.15,
                    context: context,
                  ),
                ),
                const SizedBox(height: 3),
                Text(
                  notice.message,
                  style: LhTypography.sans(
                    size: 10.5,
                    color: DunesColors.resolve(context, LhColors.ink2),
                    weight: FontWeight.w500,
                    height: 1.35,
                    context: context,
                  ),
                ),
              ],
            ),
          ),
        ],
      ),
    );
  }

  /// Hero 卡底部的同步落款。
  ///
  /// 它原来是顶栏上一颗胶囊。但「这批数是什么时候的」说的是数据，不是 App ——
  /// 放在顶栏，它和 logo、缩放钮挤成一排互不相干的小东西；放在卡的最后一行，
  /// 它就是这张卡的落款，跟印刷品在图表下角标数据来源是同一个道理：
  /// 读者先读数，读完才会问「这是什么时候的」。
  ///
  /// 顺手接上刷新：点它就重拉，同步中原地转 —— 状态和动作合成一个东西，
  /// 比「顶栏显示状态、另一颗按钮负责刷新」少一次视线往返。
  Widget _buildHeroSyncStamp({bool inline = false}) {
    final busy = _refreshing || _loading;
    final stamp = _buildHeroSyncStampChip(busy);
    // 行内形态挂在标题行右端，自带宽度，外面不能再包 Align（在 Row 里会撑满）。
    if (inline) return stamp;
    return Container(
      padding: const EdgeInsets.only(top: 8),
      decoration: lighthouseHeroUsesFlatLayout
          // 拍平版：Hero 没有卡边，落款靠一条顶线跟上面的分区表断开 ——
          // 表格的表尾就是这么收的。
          ? BoxDecoration(
              border: Border(
                top: BorderSide(
                  color: DunesColors.resolve(
                    context,
                    LhColors.line,
                    role: DunesColorRole.border,
                  ),
                  width: 0.7,
                ),
              ),
            )
          : null,
      margin: EdgeInsets.only(top: lighthouseHeroUsesFlatLayout ? 10 : 1),
      child: Align(alignment: Alignment.centerRight, child: stamp),
    );
  }

  Widget _buildHeroSyncStampChip(bool busy) {
    // 刷新的点击区只包到时间为止。「预警未取到」是另一句话，不跟着重拉。
    // 绿点带呼吸环会比字高：必须和半句待在同一行里居中，不能先组完印章
    // 再和外面包一层 Flexible —— 两段各算各的中线，字就对不齐。
    final missNote = busy ? null : _delayNoticeMissNote;
    Widget sep() => Container(
      width: 0.7,
      height: 8,
      color: DunesColors.resolve(
        context,
        LhColors.line2,
        role: DunesColorRole.surface,
      ),
    );
    Text stampWord(
      String text, {
      required Color color,
      bool mono = false,
      FontWeight weight = FontWeight.w600,
    }) {
      return Text(
        text,
        maxLines: 1,
        overflow: TextOverflow.ellipsis,
        style: (mono ? LhTypography.mono : LhTypography.sans)(
          size: 8.5,
          color: color,
          weight: weight,
          letterSpacing: mono ? 0.3 : 0.2,
          height: 1.0,
        ),
      );
    }

    // 呼吸环比字高（8.5），先裁进和字一样高的槽，再和半句排进同一行。
    final marker = busy
        ? const SizedBox(
            width: 8.5,
            height: 8.5,
            child: Center(child: _LhBrandLoader(size: 8)),
          )
        : SizedBox(
            width: 8.5,
            height: 8.5,
            child: OverflowBox(
              maxWidth: 11,
              maxHeight: 11,
              child: _LhPulseDot(
                color: DunesColors.resolve(context, LhColors.pos),
                size: 4.5,
              ),
            ),
          );

    return Padding(
      padding: const EdgeInsets.symmetric(horizontal: 2, vertical: 2),
      child: Row(
        mainAxisSize: MainAxisSize.min,
        crossAxisAlignment: CrossAxisAlignment.center,
        children: [
          _LhScrollSafeTap(
            onTap: () {
              if (busy) return;
              LighthouseFeedback.instance.play(LighthouseFeedbackKind.select);
              unawaited(_refresh());
            },
            child: Row(
              mainAxisSize: MainAxisSize.min,
              crossAxisAlignment: CrossAxisAlignment.center,
              children: [
                marker,
                const SizedBox(width: 5),
                stampWord(
                  busy ? '同步中' : '已同步',
                  color: DunesColors.resolve(context, LhColors.mute),
                ),
                if (!busy) ...[
                  const SizedBox(width: 5),
                  sep(),
                  const SizedBox(width: 5),
                  stampWord(
                    _syncedAtLabelCompact(),
                    color: DunesColors.resolve(context, LhColors.mute2),
                    mono: true,
                  ),
                ],
              ],
            ),
          ),
          const SizedBox(width: 5),
          sep(),
          const SizedBox(width: 6),
          _buildDelayNoticeHorn(),
          if (missNote != null) ...[
            const SizedBox(width: 5),
            sep(),
            const SizedBox(width: 5),
            _buildDelayNoticeMissNote(missNote),
          ],
        ],
      ),
    );
  }

  /// 与底部「选区间」同一窗口文案，挂在「产品汇总 / 供给方汇总」标题旁。
  String get _selectedRangeLabel {
    if (widget.sharedCard != null) return widget.sharedCard!.range;
    if (_isCustomRange && _customStart != null && _customEnd != null) {
      return lighthouseMdDashRange(_customStart!, _customEnd!);
    }
    final fromApi = _bundle?.metrics['deltaWindow']?.toString().trim() ?? '';
    if (fromApi.isNotEmpty && _periodOffset == 0) return fromApi;
    return lighthouseResolveAlignedPeriod(
      period: _period,
      now: _nowCST(),
      offset: _periodOffset,
    ).currentLabel;
  }

  /// 当前在看的日期窗口（纯文字）+ 清除 / 回到当前。
  /// 挂在列表控制条左侧（与「指标」同行），不进 Hero。
  Widget _buildDateRangeControl() {
    final label = _selectedRangeLabel;

    // 选区间已经并进期间条第 6 格「区间」，这里只留一行日期说明在看哪一段。
    return Row(
      children: [
        Flexible(
          child: LhScrollText(
            label,
            maxLines: 1,
            overflow: TextOverflow.ellipsis,
            style: _tabular(
              LhTypography.mono(
                size: 11,
                color: DunesColors.resolve(context, LhColors.ink2),
                weight: FontWeight.w600,
                letterSpacing: 0.2,
                context: context,
              ),
            ),
          ),
        ),
        if (_isCustomRange)
          GestureDetector(
            behavior: HitTestBehavior.opaque,
            onTap: _clearCustomRange,
            child: Padding(
              padding: const EdgeInsets.only(left: 10, top: 2, bottom: 2),
              child: Text(
                '清除',
                style: LhTypography.mono(
                  size: 10,
                  color: DunesColors.resolve(context, LhColors.mute),
                  weight: FontWeight.w600,
                  letterSpacing: 0.3,
                  context: context,
                ),
              ),
            ),
          )
        else if (_periodOffset != 0)
          GestureDetector(
            behavior: HitTestBehavior.opaque,
            onTap: () => _applyPeriod(offset: 0),
            child: Padding(
              padding: const EdgeInsets.only(left: 10, top: 2, bottom: 2),
              child: Text(
                '回到当前',
                style: LhTypography.mono(
                  size: 10,
                  color: DunesColors.resolve(context, LhColors.mute),
                  weight: FontWeight.w600,
                  letterSpacing: 0.3,
                  context: context,
                ),
              ),
            ),
          ),
      ],
    );
  }

  /// Hero 环比 —— 与主数字同一 baseline，跟在它右侧。
  ///
  /// v14：从主数字下方独占一行，改成右侧同基线。省一整行，且被修饰的数
  ///   和修饰它的量物理相邻，这是终端类界面的标准做法。
  ///   无数据时显示「暂无对比」，不显示裸破折号。
  /// 净TA 页左侧大数：跟着展开指标走，默认净TA。
  String _netTAHeroMastheadKey(String? expandedTrendKey) {
    final focus = (expandedTrendKey ?? '').trim();
    if (focus.isEmpty) return 'netTa';
    if (focus == 'costTotal') return 'totalCost';
    if (focus == 'businessCost') return 'cost';
    return focus;
  }

  /// 左侧大数环比：跟 masthead 同一指标；银行余额用存量涨跌口径。
  ({double pct, bool isUp})? _mastheadDeltaForKey(String mastheadKey) {
    if (mastheadKey == 'netTaBankBalance') {
      final change = _netTABankBalanceChange();
      final pct = change?.pct;
      if (change == null || pct == null) return null;
      return (pct: pct, isUp: change.amount >= 0);
    }
    return _deltaForMetric(mastheadKey);
  }

  /// 点选走势图某一期：该点对前一点。率用 pp，金额用相对涨幅。
  ({double pct, bool isUp})? _deltaAtHeroPoint(String key) {
    final i = _heroPointIndex;
    if (i == null) return null;
    final series = key == 'netTaBankBalance'
        ? _netTABankBalanceSeries()
        : _seriesForMetric(key);
    final period = key == 'netTaBankBalance'
        ? _netTABankBalanceChange()?.pct
        : _deltaForMetric(key)?.pct;
    final pct = lighthouseTrendMomPct(
      periodDeltaPct: period,
      partialPeriod: _periodInProgress,
      series: series,
      selectedIndex: i,
      suppressPointMom: lighthouseHeroSuppressPointMom,
      asPercentagePoints: lighthouseHeroMetricIsRate(key),
    );
    if (pct == null) return null;
    return (pct: pct, isUp: pct >= 0);
  }

  /// 点选时对照文案跟序列粒度走；未走完的最后一点仍用后端同期窗口文案。
  String _heroDeltaVsLabel({
    required bool pointMode,
    required List<double> series,
  }) {
    final i = _heroPointIndex;
    if (!pointMode || i == null) return _periodVsLabel;
    if (lighthouseHeroPointUsesAlignedPeriodDelta(
      partialPeriod: _periodInProgress,
      selectedIndex: i,
      seriesLength: series.length,
    )) {
      return _periodVsLabel;
    }
    return lighthouseHeroPointVsLabel(
      _bundle?.metrics['heroSeriesGranularity']?.toString(),
      period: _period,
    );
  }

  /// 左侧大数取值：银行余额不在 totals 里，走 metrics 存量。
  double _mastheadValueForKey(Map<String, double> totals, String mastheadKey) {
    if (mastheadKey == 'netTaBankBalance') {
      return (_bundle?.metrics['netTaBankBalance'] as num?)?.toDouble() ?? 0;
    }
    final v = lighthouseHeroMetricValue(totals, mastheadKey);
    if (v != null) return v;
    // 取不到就归 0，绝不回退到利润 —— 标签写着「本月GMV」、下面却是利润
    // 那个数，是这张卡最容易读错的一种错：看的人根本不知道自己在看什么。
    return 0;
  }

  /// [pointMode] = 正看走势图上的某一个点。环比是该点对前一点；
  /// 没有前一点时写「暂无对比」，并留「回本期」退出点选。
  Widget _heroDeltaLine(
    ({double pct, bool isUp})? d, {
    bool pointMode = false,
    bool isRate = false,
    String? vsLabel,
  }) {
    if (d != null && !lighthouseDeltaPctShown(d.pct, isRate: isRate)) {
      d = null;
    }
    final vs = (vsLabel == null || vsLabel.isEmpty) ? _periodVsLabel : vsLabel;
    final color = d == null
        ? DunesColors.resolve(context, LhColors.mute2)
        : (d.isUp
              ? DunesColors.resolve(context, LhColors.neg)
              : DunesColors.resolve(context, LhColors.pos));
    final a = d == null ? 0.0 : d.pct.abs();
    final unit = isRate ? 'pp' : '%';
    final pctText = Text(
      d == null
          ? '暂无对比'
          : '${d.isUp ? '↑' : '↓'}${a.toStringAsFixed(a >= 10 ? 0 : 1)}$unit',
      maxLines: 1,
      overflow: TextOverflow.ellipsis,
      style: _tabular(
        LhTypography.mono(
          // 2026-10-21 · 环比加粗放大：11.5 / w600 → 13.5 / w800。
          size: d == null ? 9.5 : 13.5,
          color: color,
          weight: d == null ? FontWeight.w600 : FontWeight.w800,
          letterSpacing: 0.2,
          context: context,
        ),
      ),
    );
    final vsText = LhScrollText(
      vs,
      maxLines: 1,
      overflow: TextOverflow.ellipsis,
      style: LhTypography.mono(
        size: 9.5,
        color: DunesColors.resolve(context, LhColors.mute),
        weight: FontWeight.w500,
        letterSpacing: 0.3,
        context: context,
      ),
    );
    if (!pointMode) {
      return Row(
        crossAxisAlignment: CrossAxisAlignment.center,
        children: [
          pctText,
          const SizedBox(width: 7),
          Flexible(child: vsText),
        ],
      );
    }
    // 「回本期」是退出点选的唯一文字入口，绝不能被裁。
    //   旧版和环比、对照文案挤在一行，窄卡（手机上的产品汇总）里总被右沿吃掉。
    //   做成不收缩的小胶囊：放得下就跟在同一行，放不下就单独起一行。
    final backChip = GestureDetector(
      behavior: HitTestBehavior.opaque,
      onTap: _clearHeroPointSelection,
      child: Container(
        padding: const EdgeInsets.symmetric(horizontal: 7, vertical: 3),
        decoration: BoxDecoration(
          color: DunesColors.resolve(
            context,
            _LhPlum.primary,
            role: DunesColorRole.surface,
          ).withAlpha(20),
          borderRadius: BorderRadius.circular(10),
          border: Border.all(
            color: DunesColors.resolve(
              context,
              _LhPlum.primary,
              role: DunesColorRole.border,
            ).withAlpha(60),
            width: 0.6,
          ),
        ),
        child: Row(
          mainAxisSize: MainAxisSize.min,
          children: [
            Icon(
              Icons.refresh_rounded,
              size: 10,
              color: DunesColors.resolve(context, _LhPlum.primary),
            ),
            const SizedBox(width: 3),
            Text(
              '回本期',
              maxLines: 1,
              softWrap: false,
              style: LhTypography.mono(
                size: 9.5,
                color: DunesColors.resolve(context, _LhPlum.primary),
                weight: FontWeight.w700,
                letterSpacing: 0.3,
                height: 1.0,
                context: context,
              ),
            ),
          ],
        ),
      ),
    );
    return LayoutBuilder(
      builder: (context, c) {
        // 环比 ~48 + 对照文案至少 ~40 + 胶囊 ~62 + 间距；低于这个宽度就换行。
        final oneLine = !c.maxWidth.isFinite || c.maxWidth >= 190;
        final deltaRow = Row(
          crossAxisAlignment: CrossAxisAlignment.center,
          children: [
            pctText,
            const SizedBox(width: 7),
            Flexible(child: vsText),
            if (oneLine) ...[const SizedBox(width: 8), backChip],
          ],
        );
        if (oneLine) return deltaRow;
        return Column(
          mainAxisSize: MainAxisSize.min,
          crossAxisAlignment: CrossAxisAlignment.start,
          children: [deltaRow, const SizedBox(height: 6), backChip],
        );
      },
    );
  }

  /// hero grid 的业务口径核心指标 (5 格, 硬编码, 不受 tab 影响)
  ///   第 1 行 (损益): 利润 / 收入 / 效率
  ///   第 2 行 (成本): 经营成本 / 成本合计
  /// 会议规则:
  ///   - 大数字销售规模保留(业务盘子)
  ///   - grid 展示损益 + 成本, 让运营/财务/市场看统一口径
  ///   - 成本合计直读 totalCost (= SUM(total_cost))
  List<_HeroMetric> _lhCoreMetrics() {
    return [
      _HeroMetric(
        key: 'profit',
        label: '利润',
        isRate: false,
        cellColor: DunesColors.resolve(context, LhColors.neg),
      ),
      _HeroMetric(
        key: 'revenue',
        label: '收入（已核销利差）',
        isRate: false,
        cellColor: DunesColors.resolve(context, LhColors.cnpc),
      ),
      _HeroMetric(
        key: 'rate',
        label: 'ROI',
        isRate: true,
        cellColor: DunesColors.resolve(context, _LhPlum.primary),
      ),
      _HeroMetric(
        key: 'totalCost',
        label: '成本合计',
        isRate: false,
        cellColor: DunesColors.resolve(context, LhColors.pos),
      ),
    ];
  }

