  // ═══════════════════════════════════════════════════════════════════════
  // 页面级周期筛选：粒度（日/周/月/季/年）+ 实例（哪一天/周/月/季/年）
  // offset 0 = 当前实例，-1 = 上一个，依此类推。所有数据仍走后端真实库，
  // offset 透传给 fetchOverview / fetchAnalysisCube。
  // ═══════════════════════════════════════════════════════════════════════

  String _two(int v) => v.toString().padLeft(2, '0');

  /// 给定粒度 + offset 的锚点日期（实例起点）。
  DateTime _periodAnchor(String period, int offset) {
    final now = _nowCST();
    switch (period) {
      case 'day':
        return DateTime(
          now.year,
          now.month,
          now.day,
        ).add(Duration(days: offset));
      case 'week':
        final mon = DateTime(
          now.year,
          now.month,
          now.day,
        ).subtract(Duration(days: now.weekday - 1));
        return mon.add(Duration(days: offset * 7));
      case 'month':
        return DateTime(now.year, now.month + offset, 1);
      case 'quarter':
        final q0 = (now.month - 1) ~/ 3; // 0..3
        final idx = now.year * 4 + q0 + offset;
        return DateTime(idx ~/ 4, (idx % 4) * 3 + 1, 1);
      case 'year':
        return DateTime(now.year + offset, 1, 1);
      default:
        return now;
    }
  }

  /// 实例主标签（按钮 + 列表）。
  String _periodInstanceLabel(String period, int offset) {
    final a = _periodAnchor(period, offset);
    switch (period) {
      case 'day':
        if (offset == 0) return '今日';
        if (offset == -1) return '昨日';
        if (offset == -2) return '前日';
        return '${_two(a.month)}.${_two(a.day)}';
      case 'week':
        if (offset == 0) return '本周';
        if (offset == -1) return '上周';
        return '${-offset}周前';
      case 'month':
        if (offset == 0) return '本月';
        if (offset == -1) return '上月';
        return '${a.year}.${_two(a.month)}';
      case 'quarter':
        final q = (a.month - 1) ~/ 3 + 1;
        if (offset == 0) return '本季';
        if (offset == -1) return '上季';
        return '${a.year} Q$q';
      case 'year':
        if (offset == 0) return '今年';
        if (offset == -1) return '去年';
        return '${a.year}';
      default:
        return '';
    }
  }

  /// 期间条选中胶囊上的短名 —— 必须 ≤ 4 个字宽，胶囊里还要放圆点和 ▾。
  /// 近两期用口语（本月 / 上月），再往前用最短的绝对值（7月 / 9.13 / Q1）。
  String _periodPillLabel(String period, int offset) {
    final a = _periodAnchor(period, offset);
    final nowYear = _nowCST().year;
    String yy(int y) => _two(y % 100);
    switch (period) {
      case 'day':
        if (offset == 0) return '今日';
        if (offset == -1) return '昨日';
        return '${a.month}.${a.day}';
      case 'week':
        if (offset == 0) return '本周';
        if (offset == -1) return '上周';
        return '${-offset}周前';
      case 'month':
        if (offset == 0) return '本月';
        if (offset == -1) return '上月';
        return a.year == nowYear
            ? '${a.month}月'
            : '${yy(a.year)}.${_two(a.month)}';
      case 'quarter':
        final q = (a.month - 1) ~/ 3 + 1;
        if (offset == 0) return '本季';
        if (offset == -1) return '上季';
        return a.year == nowYear ? 'Q$q' : '${yy(a.year)}Q$q';
      case 'year':
        if (offset == 0) return '今年';
        if (offset == -1) return '去年';
        return '${a.year}';
      default:
        return _kPeriodShort[period] ?? '';
    }
  }

  /// 实例副标签（小字日期范围 / 精确值）。
  /// v12.2 · 用户明确要求"几号到几号"格式 —— 所有粒度都返回完整区间,
  /// 不再只有 week 显示 X.X–X.X, 其他粒度含糊的 "本月/本季/年度".
  String _periodInstanceDetail(String period, int offset) {
    if (period != 'day') {
      return lighthouseResolveAlignedPeriod(
        period: period,
        now: _nowCST(),
        offset: offset,
      ).currentLabel;
    }
    final a = _periodAnchor(period, offset);
    switch (period) {
      case 'day':
        const wk = ['一', '二', '三', '四', '五', '六', '日'];
        return '${a.year}.${_two(a.month)}.${_two(a.day)} 周${wk[a.weekday - 1]}';
      case 'week':
        final end = a.add(const Duration(days: 6));
        return '${_two(a.month)}.${_two(a.day)}–${_two(end.month)}.${_two(end.day)}';
      case 'month':
        // 月末 = 下月 1 号减 1 天 (自动处理 28/29/30/31)
        final end = DateTime(a.year, a.month + 1, 0);
        return '${_two(a.month)}.${_two(a.day)}–${_two(end.month)}.${_two(end.day)}';
      case 'quarter':
        // 季度末 = 起始月 +3 月 的 0 号 (上月末)
        final end = DateTime(a.year, a.month + 3, 0);
        return '${_two(a.month)}.${_two(a.day)}–${_two(end.month)}.${_two(end.day)}';
      case 'year':
        return '${a.year}.01.01–${a.year}.12.31';
      default:
        return '';
    }
  }

  /// 每种粒度展示的实例数量（offset 0..-(n-1)）。
  int _periodInstanceCount(String period) {
    switch (period) {
      case 'day':
        return 14;
      case 'week':
        return 12;
      case 'month':
        return 12;
      case 'quarter':
        return 8;
      case 'year':
        return 5;
      default:
        return 6;
    }
  }

  /// 统一切换粒度 / 实例 → 清缓存 + 重新拉取（真实库数据）。
  /// v3.9: 用户在 detail 里改 period 时**不关闭 detail** —— 保留 _detailKey,
  /// 让 detail 就地 refetch (via _detailLoadedFor 过期检测). 用户预期是"我
  /// 想看这个产品的日粒度", 不是"帮我关掉页面".
  void _applyPeriod({String? period, int? offset}) {
    final newPeriod = period ?? _period;
    final newOffset = offset ?? _periodOffset;
    if (newPeriod == _period && newOffset == _periodOffset) {
      setState(() => _periodPickerOpen = false);
      return;
    }
    final wasInDetail = _detailKey != null;
    final detailTypeSnapshot = _detailType;
    final detailKeySnapshot = _detailKey;
    setState(() {
      _listLimitKeptForReload = _listLimit;
      _period = newPeriod;
      _periodOffset = newOffset;
      _heroPointIndex = null;
      _periodPickerOpen = false;
      _loading = true;
      _loadError = null;
      // 只有不在 detail 时才清 detail 状态; 在 detail 时 detail 保持打开,
      // drill 状态 reset (fresh period, fresh drill).
      if (!wasInDetail) {
        _detailKey = null;
        _detailType = null;
      }
      _resetDetailSkuSearch();
      // 人还在二级 / 三级里：别拆掉当前这一层。拆了路由键会变，
      // 整页重建，滚动位置回到顶部。新周期的数到了再原地换。
      if (!wasInDetail) _resetDetailDrill();
      _closeMetricPage();
      _rowsCacheKey = '';
      _rowsCache = null;
      _cubeCacheKey = '';
      _cubeData = null;
      _cubeError = false;
      _invalidateAiSummary();
    });
    _load();
    if (_tab == 'analysis') _loadAnalysisCube();
    // 在 detail 里改 period —— 立刻 refetch 当前 detail (新 period).
    if (wasInDetail &&
        detailTypeSnapshot != null &&
        detailKeySnapshot != null) {
      _loadDetail(detailTypeSnapshot, detailKeySnapshot);
    }
  }

  /// v12.7 · 用户明确要求"看一段时间, 比如 6.12 到 6.20 —— 可以选择时间段".
  /// 点「开始」/「结束」决定日历改哪一头；已选完整区间时改其中一头，不整段重来.
  ///   · 返回 (start, end); 选完之后写入 _customStart/_customEnd, 触发 reload.
  ///   · Bottom sheet + 月历 grid, 头部两个 chip 显示当前选择, 尾部 取消/确定.
  Future<void> _pickDateRange() async {
    final now = _nowCST();
    final today = DateTime(now.year, now.month, now.day);
    final firstDate = DateTime(today.year - 2, 1, 1);

    // 初始定位: 如果当前已有自定义区间, 用 start 那月; 否则用当前 period anchor.
    final anchorMonth = _customStart != null
        ? DateTime(_customStart!.year, _customStart!.month, 1)
        : () {
            final a = _periodAnchor(_period, _periodOffset);
            return DateTime(a.year, a.month, 1);
          }();

    bool sameDay(DateTime a, DateTime b) =>
        a.year == b.year && a.month == b.month && a.day == b.day;
    bool inRangeInclusive(DateTime d, DateTime s, DateTime e) =>
        !d.isBefore(s) && !d.isAfter(e);

    final result = await showModalBottomSheet<({DateTime start, DateTime end})?>(
      context: context,
      isScrollControlled: true,
      backgroundColor: Colors.transparent,
      barrierColor: Colors.black.withAlpha(55),
      builder: (ctx) {
        // 本地状态: 当前月 / 草稿 (每次打开都以已有值预填)
        var month = anchorMonth;
        var draft = lighthouseRangeDraftOpen(
          start: _customStart,
          end: _customEnd,
        );

        return StatefulBuilder(
          builder: (ctx, setLocal) {
            final monthStart = DateTime(month.year, month.month, 1);
            final daysInMonth = DateTime(month.year, month.month + 1, 0).day;
            final leadingEmpty = monthStart.weekday - 1;
            final cellCount = ((leadingEmpty + daysInMonth + 6) ~/ 7) * 7;
            final canPrev = DateTime(
              month.year,
              month.month - 1,
              1,
            ).isAfter(DateTime(firstDate.year, firstDate.month - 1, 1));
            final canNext = DateTime(
              month.year,
              month.month + 1,
              1,
            ).isBefore(DateTime(today.year, today.month + 1, 1));

            DateTime? selStart = draft.start;
            DateTime? selEnd = draft.end;

            void tapDay(DateTime d) {
              setLocal(() {
                draft = lighthouseRangeDraftTapDay(draft, d);
              });
            }

            void tapChip(LighthouseRangeFocus focus) {
              setLocal(() {
                draft = lighthouseRangeDraftTapChip(draft, focus);
                final jump = focus == LighthouseRangeFocus.start
                    ? draft.start
                    : draft.end;
                if (jump != null) {
                  month = DateTime(jump.year, jump.month, 1);
                }
              });
            }

            Widget navBtn(IconData icon, bool enabled, VoidCallback onTap) {
              return GestureDetector(
                behavior: HitTestBehavior.opaque,
                onTap: enabled ? onTap : null,
                child: Container(
                  width: 28,
                  height: 28,
                  alignment: Alignment.center,
                  decoration: BoxDecoration(
                    color: enabled
                        ? DunesColors.resolve(
                            ctx,
                            LhColors.paper,
                            role: DunesColorRole.surface,
                          )
                        : DunesColors.resolve(
                            ctx,
                            _LhPlum.mist,
                            role: DunesColorRole.surface,
                          ),
                    border: Border.all(
                      color: DunesColors.resolve(
                        ctx,
                        LhColors.line,
                        role: DunesColorRole.border,
                      ),
                      width: 1,
                    ),
                    borderRadius: BorderRadius.circular(7),
                  ),
                  child: Icon(
                    icon,
                    size: 15,
                    color: enabled
                        ? DunesColors.resolve(ctx, LhColors.ink2)
                        : DunesColors.resolve(ctx, LhColors.mute2),
                  ),
                ),
              );
            }

            Widget endpointChip(
              String label,
              DateTime? d,
              bool active, {
              required VoidCallback onTap,
            }) {
              final txt = d == null
                  ? '—'
                  : '${d.year}.${_two(d.month)}.${_two(d.day)}';
              return GestureDetector(
                behavior: HitTestBehavior.opaque,
                onTap: onTap,
                child: Container(
                  padding: const EdgeInsets.fromLTRB(9, 6, 9, 6),
                  decoration: BoxDecoration(
                    color: active
                        ? DunesColors.resolve(
                            ctx,
                            _LhPlum.mist,
                            role: DunesColorRole.surface,
                          )
                        : DunesColors.resolve(
                            ctx,
                            LhColors.paper,
                            role: DunesColorRole.surface,
                          ),
                    border: Border.all(
                      color: active
                          ? DunesColors.resolve(
                              ctx,
                              _LhPlum.primary,
                              role: DunesColorRole.border,
                            )
                          : DunesColors.resolve(
                              ctx,
                              LhColors.line2,
                              role: DunesColorRole.border,
                            ),
                      width: active ? 1.4 : 1,
                    ),
                    borderRadius: BorderRadius.circular(8),
                  ),
                  child: Column(
                    crossAxisAlignment: CrossAxisAlignment.start,
                    mainAxisSize: MainAxisSize.min,
                    children: [
                      Text(
                        label,
                        style: LhTypography.mono(
                          size: 8.5,
                          color: active
                              ? DunesColors.resolve(ctx, _LhPlum.primary)
                              : DunesColors.resolve(ctx, LhColors.mute2),
                          weight: FontWeight.w700,
                          letterSpacing: 0.6,
                          context: ctx,
                        ),
                      ),
                      const SizedBox(height: 2),
                      Text(
                        txt,
                        style: LhTypography.sans(
                          size: 12.5,
                          color: d == null
                              ? DunesColors.resolve(ctx, LhColors.mute2)
                              : DunesColors.resolve(ctx, LhColors.ink),
                          weight: FontWeight.w700,
                          letterSpacing: -0.1,
                          context: ctx,
                        ),
                      ),
                    ],
                  ),
                ),
              );
            }

            final bottomHint = lighthouseRangeDraftHint(draft);
            final canConfirm = draft.canConfirm;

            // isScrollControlled 时整屏都是 sheet，上方透明区点不到 barrier；
            // 点卡片外 = pop(null)，与「取消」一致，不改动已选区间。
            return SafeArea(
              top: false,
              child: GestureDetector(
                behavior: HitTestBehavior.opaque,
                onTap: () => Navigator.of(ctx).pop(null),
                child: Align(
                  alignment: Alignment.bottomCenter,
                  child: GestureDetector(
                    onTap: () {}, // 吞掉卡片内点击，避免冒泡关闭
                    child: Container(
                      margin: const EdgeInsets.fromLTRB(14, 0, 14, 10),
                      padding: const EdgeInsets.fromLTRB(14, 12, 14, 12),
                      decoration: BoxDecoration(
                        color: DunesColors.resolve(
                          ctx,
                          LhColors.paper,
                          role: DunesColorRole.surface,
                        ),
                        border: Border.all(
                          color: DunesColors.resolve(
                            ctx,
                            LhColors.line2,
                            role: DunesColorRole.border,
                          ),
                          width: 1,
                        ),
                        borderRadius: BorderRadius.circular(16),
                        boxShadow: [
                          BoxShadow(
                            color: Colors.black.withAlpha(16),
                            blurRadius: 24,
                            offset: const Offset(0, 10),
                          ),
                        ],
                      ),
                      child: Column(
                        mainAxisSize: MainAxisSize.min,
                        crossAxisAlignment: CrossAxisAlignment.stretch,
                        children: [
                          // Title
                          Padding(
                            padding: const EdgeInsets.only(bottom: 10),
                            child: Text(
                              '选择时间段',
                              style: LhTypography.sans(
                                size: 13,
                                color: DunesColors.resolve(ctx, LhColors.ink),
                                weight: FontWeight.w700,
                                letterSpacing: 0.2,
                                context: ctx,
                              ),
                            ),
                          ),
                          // Start / End endpoint chips
                          Row(
                            children: [
                              Expanded(
                                child: endpointChip(
                                  '开始',
                                  selStart,
                                  draft.focus == LighthouseRangeFocus.start,
                                  onTap: () =>
                                      tapChip(LighthouseRangeFocus.start),
                                ),
                              ),
                              const SizedBox(width: 8),
                              Icon(
                                Icons.arrow_forward_rounded,
                                size: 14,
                                color: DunesColors.resolve(ctx, LhColors.mute2),
                              ),
                              const SizedBox(width: 8),
                              Expanded(
                                child: endpointChip(
                                  '结束',
                                  selEnd,
                                  draft.focus == LighthouseRangeFocus.end,
                                  onTap: () =>
                                      tapChip(LighthouseRangeFocus.end),
                                ),
                              ),
                            ],
                          ),
                          const SizedBox(height: 12),
                          // Month nav
                          Row(
                            children: [
                              navBtn(Icons.chevron_left_rounded, canPrev, () {
                                setLocal(
                                  () => month = DateTime(
                                    month.year,
                                    month.month - 1,
                                    1,
                                  ),
                                );
                              }),
                              Expanded(
                                child: Text(
                                  '${month.year}.${_two(month.month)}',
                                  textAlign: TextAlign.center,
                                  style: LhTypography.sans(
                                    size: 13,
                                    color: DunesColors.resolve(
                                      ctx,
                                      LhColors.ink2,
                                    ),
                                    weight: FontWeight.w700,
                                    context: ctx,
                                  ),
                                ),
                              ),
                              navBtn(Icons.chevron_right_rounded, canNext, () {
                                setLocal(
                                  () => month = DateTime(
                                    month.year,
                                    month.month + 1,
                                    1,
                                  ),
                                );
                              }),
                            ],
                          ),
                          const SizedBox(height: 10),
                          // Weekday header
                          Row(
                            children: const ['一', '二', '三', '四', '五', '六', '日']
                                .map(
                                  (d) => Expanded(
                                    child: Center(
                                      child: Text(
                                        d,
                                        style: TextStyle(
                                          fontFamily: 'Geist Mono',
                                          fontSize: 9,
                                          color: DunesColors.resolve(
                                            ctx,
                                            LhColors.mute2,
                                          ),
                                          fontWeight: FontWeight.w600,
                                        ),
                                      ),
                                    ),
                                  ),
                                )
                                .toList(),
                          ),
                          const SizedBox(height: 5),
                          // Day grid — height must fit 4/5/6 weeks; fixed 206 clipped
                          // months like 2026-07 (Wed start, 31 days → 5 rows, days 27–31 gone).
                          LayoutBuilder(
                            builder: (ctx, constraints) {
                              const crossSpacing = 4.0;
                              const mainSpacing = 4.0;
                              const aspect = 1.12;
                              final weeks = cellCount ~/ 7;
                              final cellW =
                                  (constraints.maxWidth - crossSpacing * 6) / 7;
                              final cellH = cellW / aspect;
                              final gridH =
                                  weeks * cellH +
                                  (weeks > 0 ? (weeks - 1) * mainSpacing : 0);
                              return SizedBox(
                                height: gridH,
                                child: GridView.builder(
                                  padding: EdgeInsets.zero,
                                  physics: const NeverScrollableScrollPhysics(),
                                  gridDelegate:
                                      const SliverGridDelegateWithFixedCrossAxisCount(
                                        crossAxisCount: 7,
                                        mainAxisSpacing: mainSpacing,
                                        crossAxisSpacing: crossSpacing,
                                        childAspectRatio: aspect,
                                      ),
                                  itemCount: cellCount,
                                  itemBuilder: (ctx, i) {
                                    final dayNo = i - leadingEmpty + 1;
                                    if (dayNo < 1 || dayNo > daysInMonth) {
                                      return const SizedBox.shrink();
                                    }
                                    final day = DateTime(
                                      month.year,
                                      month.month,
                                      dayNo,
                                    );
                                    final disabled =
                                        day.isAfter(today) ||
                                        day.isBefore(firstDate);
                                    final isStart =
                                        selStart != null &&
                                        sameDay(day, selStart!);
                                    final isEnd =
                                        selEnd != null && sameDay(day, selEnd!);
                                    final inBetween =
                                        selStart != null &&
                                        selEnd != null &&
                                        inRangeInclusive(
                                          day,
                                          selStart!,
                                          selEnd!,
                                        ) &&
                                        !isStart &&
                                        !isEnd;
                                    final isToday = sameDay(day, today);

                                    Color cellBg;
                                    Color textColor;
                                    Color borderColor;
                                    FontWeight weight;
                                    if (isStart || isEnd) {
                                      cellBg = DunesColors.resolve(
                                        ctx,
                                        _LhPlum.primary,
                                        role: DunesColorRole.surface,
                                      );
                                      textColor = DunesColors.resolve(
                                        ctx,
                                        Colors.white,
                                      );
                                      borderColor = DunesColors.resolve(
                                        ctx,
                                        _LhPlum.primary,
                                      );
                                      weight = FontWeight.w700;
                                    } else if (inBetween) {
                                      cellBg = DunesColors.resolve(
                                        ctx,
                                        _LhPlum.mist,
                                        role: DunesColorRole.surface,
                                      );
                                      textColor = DunesColors.resolve(
                                        ctx,
                                        _LhPlum.deep,
                                      );
                                      borderColor = Colors.transparent;
                                      weight = FontWeight.w600;
                                    } else {
                                      cellBg = Colors.transparent;
                                      textColor = disabled
                                          ? DunesColors.resolve(
                                              ctx,
                                              LhColors.mute2,
                                            ).withAlpha(120)
                                          : DunesColors.resolve(
                                              ctx,
                                              LhColors.ink2,
                                            );
                                      borderColor = isToday
                                          ? DunesColors.resolve(
                                              ctx,
                                              _LhPlum.primary,
                                            ).withAlpha(120)
                                          : Colors.transparent;
                                      weight = isToday
                                          ? FontWeight.w700
                                          : FontWeight.w500;
                                    }

                                    return GestureDetector(
                                      behavior: HitTestBehavior.opaque,
                                      onTap: disabled
                                          ? null
                                          : () => tapDay(day),
                                      child: Container(
                                        alignment: Alignment.center,
                                        decoration: BoxDecoration(
                                          color: DunesColors.resolveNullable(
                                            ctx,
                                            cellBg,
                                            role: DunesColorRole.surface,
                                          ),
                                          border: Border.all(
                                            color: borderColor,
                                            width: 1,
                                          ),
                                          borderRadius: BorderRadius.circular(
                                            8,
                                          ),
                                        ),
                                        child: Text(
                                          '$dayNo',
                                          style: LhTypography.sans(
                                            size: 10.5,
                                            color: textColor,
                                            weight: weight,
                                            context: ctx,
                                          ),
                                        ),
                                      ),
                                    );
                                  },
                                ),
                              );
                            },
                          ),
                          const SizedBox(height: 10),
                          // Bottom hint + actions
                          Row(
                            children: [
                              Expanded(
                                child: Text(
                                  bottomHint,
                                  style: LhTypography.mono(
                                    size: 9.2,
                                    color: canConfirm
                                        ? DunesColors.resolve(
                                            ctx,
                                            _LhPlum.primary,
                                          )
                                        : DunesColors.resolve(
                                            ctx,
                                            LhColors.mute,
                                          ),
                                    weight: FontWeight.w600,
                                    letterSpacing: 0.3,
                                    context: ctx,
                                  ),
                                ),
                              ),
                              GestureDetector(
                                behavior: HitTestBehavior.opaque,
                                onTap: () => Navigator.of(ctx).pop(null),
                                child: Padding(
                                  padding: const EdgeInsets.symmetric(
                                    horizontal: 12,
                                    vertical: 8,
                                  ),
                                  child: Text(
                                    '取消',
                                    style: LhTypography.sans(
                                      size: 11.5,
                                      color: DunesColors.resolve(
                                        ctx,
                                        LhColors.mute,
                                      ),
                                      weight: FontWeight.w600,
                                      context: ctx,
                                    ),
                                  ),
                                ),
                              ),
                              const SizedBox(width: 4),
                              GestureDetector(
                                behavior: HitTestBehavior.opaque,
                                onTap: canConfirm
                                    ? () => Navigator.of(
                                        ctx,
                                      ).pop((start: selStart!, end: selEnd!))
                                    : null,
                                child: Container(
                                  padding: const EdgeInsets.symmetric(
                                    horizontal: 14,
                                    vertical: 8,
                                  ),
                                  decoration: BoxDecoration(
                                    color: canConfirm
                                        ? DunesColors.resolve(
                                            ctx,
                                            _LhPlum.primary,
                                            role: DunesColorRole.surface,
                                          )
                                        : DunesColors.resolve(
                                            ctx,
                                            _LhPlum.mist,
                                            role: DunesColorRole.surface,
                                          ),
                                    borderRadius: BorderRadius.circular(8),
                                  ),
                                  child: Text(
                                    '确定',
                                    style: LhTypography.sans(
                                      size: 11.5,
                                      color: canConfirm
                                          ? DunesColors.resolve(
                                              ctx,
                                              Colors.white,
                                            )
                                          : DunesColors.resolve(
                                              ctx,
                                              LhColors.mute2,
                                            ),
                                      weight: FontWeight.w700,
                                      context: ctx,
                                    ),
                                  ),
                                ),
                              ),
                            ],
                          ),
                        ],
                      ),
                    ),
                  ),
                ),
              ),
            );
          },
        );
      },
    );
    if (result == null) return;
    // 用户确认了一个区间 —— 覆盖 period+offset, 触发 reload
    _applyCustomRange(result.start, result.end);
  }

  /// 应用自定义区间, 清 period offset, 触发数据 reload.
  void _applyCustomRange(DateTime start, DateTime end) {
    final s = DateTime(start.year, start.month, start.day);
    final e = DateTime(end.year, end.month, end.day);
    final wasInDetail = _detailKey != null;
    final detailTypeSnapshot = _detailType;
    final detailKeySnapshot = _detailKey;
    setState(() {
      _listLimitKeptForReload = _listLimit;
      _customStart = s;
      _customEnd = e;
      _periodOffset = 0; // 显式清 offset, 让 UI 状态一致
      _periodPickerOpen = false;
      _loading = true;
      _loadError = null;
      if (!wasInDetail) {
        _detailKey = null;
        _detailType = null;
      }
      _resetDetailSkuSearch();
      if (!wasInDetail) _resetDetailDrill();
      _closeMetricPage();
      _rowsCacheKey = '';
      _rowsCache = null;
      _cubeCacheKey = '';
      _cubeData = null;
      _cubeError = false;
      _invalidateAiSummary();
    });
    _load();
    if (_tab == 'analysis') _loadAnalysisCube();
    if (wasInDetail &&
        detailTypeSnapshot != null &&
        detailKeySnapshot != null) {
      _loadDetail(detailTypeSnapshot, detailKeySnapshot);
    }
  }

  /// 「区间」胶囊里的短日期：同月 `10.01–14`，跨月 `9.28–10.3`，单日 `10.01`。
  String _customRangePillLabel() {
    final s = _customStart;
    final e = _customEnd;
    if (s == null || e == null) return '区间';
    String two(int v) => v.toString().padLeft(2, '0');
    if (s.year == e.year && s.month == e.month) {
      if (s.day == e.day) return '${two(s.month)}.${two(s.day)}';
      return '${two(s.month)}.${two(s.day)}–${two(e.day)}';
    }
    return '${s.month}.${s.day}–${e.month}.${e.day}';
  }

  /// 清掉自定义区间, 回到 period+offset 模式.
  void _clearCustomRange() {
    if (!_isCustomRange) return;
    setState(() {
      _listLimitKeptForReload = _listLimit;
      _customStart = null;
      _customEnd = null;
      _loading = true;
      _loadError = null;
      _invalidateAiSummary();
    });
    _load();
    if (_tab == 'analysis') _loadAnalysisCube();
  }

  /// 悬浮圆角分段：日/周/月/季/年。
  /// 选中那一项右边多一个小 ▾ — 点它（或再点选中项）展开实例选择条。
  /// 非选中项：点 → 切粒度并把 offset 重置为 0。
  Widget _buildPeriodBar({bool onDark = false}) {
    return Column(
      crossAxisAlignment: CrossAxisAlignment.start,
      mainAxisSize: MainAxisSize.min,
      children: [
        // 2026-10-26 · 顶栏上（onDark）：整条改成胶囊，描边和底部 App 金刚位胶囊同款渐变，
        // 选中仍是白滑块 —— 上下两颗同材质、同轮廓的胶囊互相呼应。
        CustomPaint(
          // 方案 E 起上下呼应改靠浮岛 + 渐变选中块，这里不再描渐变边。
          foregroundPainter: null,
          child: LhPeriodBar(
          // 第 6 格「区间」：自选起止日期，不再在列表头单独挂一个「选区间」。
          labels: [for (final k in _kPeriodKeys) _kPeriodShort[k] ?? '', '区间'],
          selectedIndex: _isCustomRange
              ? _kPeriodKeys.length
              : _kPeriodKeys.indexOf(_period),
          pickerOpen: _periodPickerOpen,
          floating: lighthousePeriodUsesFloatingSegment,
          height: lighthousePeriodTrackHeight,
          trackRadius: onDark
              ? lighthousePeriodTrackHeight / 2
              : lighthousePeriodTrackRadius,
          pillRadius: onDark
              ? lighthousePeriodTrackHeight / 2 - lighthousePeriodTrackPadding
              : lighthousePeriodSelectedRadius,
          dotSize: lighthousePeriodStatusDotSize,
          trackPadding: lighthousePeriodTrackPadding,
          primary: DunesColors.resolve(
            context,
            _LhPlum.primary,
            role: DunesColorRole.surface,
          ),
          deep: DunesColors.resolve(context, _LhPlum.deep),
          // v24 · 轨道 = 凹槽（淡紫底、Hero 卡同款紫发丝边、不投影），
          // 胶囊 = 缩小的 Hero 白卡（白纸 + 同色边 + 轻投影）。
          // 深色带上：轨道是一层 7% 白，选中是一颗白胶囊。
          // 毛玻璃顶栏上：轨道 = 8% 紫的槽，选中 = 白滑块（同主卡「利润 | 资金」）。
          trackColor: onDark
              ? const Color(0x177B5CD8)
              : lighthousePeriodUsesHeroSurface
              ? DunesColors.resolve(
                  context,
                  const Color(0xFFF3EFFA),
                  role: DunesColorRole.surface,
                )
              : DunesColors.resolve(
                  context,
                  LhColors.paper,
                  role: DunesColorRole.surface,
                ),
          trackBorder: onDark
              ? const Color(0x00000000)
              : lighthousePeriodUsesHeroSurface
              ? DunesColors.resolve(
                  context,
                  _LhPlum.line,
                  role: DunesColorRole.border,
                )
              : DunesColors.resolve(
                  context,
                  LhColors.line2,
                  role: DunesColorRole.border,
                ),
          trackShadowColor: onDark
              ? Colors.transparent
              : lighthousePeriodUsesHeroSurface
              ? Colors.transparent
              : DunesColors.resolve(context, Colors.black).withAlpha(8),
          pillGradient: onDark
              ? const [Color(0xFFFFFFFF), Color(0xFFF5F1FD), Color(0xFFFFFFFF)]
              : lighthousePeriodUsesHeroSurface
              ? [
                  DunesColors.resolve(
                    context,
                    Color(0xFFFFFFFF),
                    role: DunesColorRole.surface,
                  ),
                  DunesColors.resolve(
                    context,
                    Color(0xFFFFFFFF),
                    role: DunesColorRole.surface,
                  ),
                  DunesColors.resolve(
                    context,
                    Color(0xFFFCFAFF),
                    role: DunesColorRole.surface,
                  ),
                ]
              : [
                  DunesColors.resolve(
                    context,
                    Color(0xFFF6F1FD),
                    role: DunesColorRole.surface,
                  ),
                  DunesColors.resolve(
                    context,
                    Color(0xFFE3D9F7),
                    role: DunesColorRole.surface,
                  ),
                  DunesColors.resolve(
                    context,
                    Color(0xFFEFE9FB),
                    role: DunesColorRole.surface,
                  ),
                ],
          pillEdgeColor: onDark
              ? const Color(0x1F7B5CD8)
              : lighthousePeriodUsesHeroSurface
              ? DunesColors.resolve(context, _LhPlum.line)
              : null,
          pillShadowColor: onDark
              ? const Color(0x2E4A3A7A)
              : lighthousePeriodUsesHeroSurface
              ? DunesColors.resolve(context, _LhPlum.deep).withAlpha(30)
              : null,
          shimmerColor: onDark
              ? const Color(0xFFEDE6FB)
              : lighthousePeriodUsesHeroSurface
              ? DunesColors.resolve(context, _LhPlum.lavender)
              : DunesColors.resolve(context, Colors.white),
          idleTextColor: onDark
              ? _kLhBandInk
              : DunesColors.resolve(context, LhColors.ink2),
          selectedTextColor: onDark
              ? const Color(0xFF3A2A66)
              : lighthousePeriodUsesHeroSurface
              ? DunesColors.resolve(context, _LhPlum.heroNum)
              : null,
          selectedLabel: _isCustomRange
              ? _customRangePillLabel()
              : (!lighthousePeriodPillShowsInstance
                    ? null
                    : _periodPillLabel(_period, _periodOffset)),
          ambientMotion: lighthousePeriodAmbientMotion,
          baseTextStyle: LhTypography.sans(
            size: lighthousePeriodLabelFontSize,
            color: DunesColors.resolve(context, LhColors.ink2),
            weight: FontWeight.w500,
            letterSpacing: 0,
            height: 1.0,
            context: context,
          ),
          onTap: (i) {
            LighthouseFeedback.instance.play(LighthouseFeedbackKind.select);
            // 「区间」格：直接弹日历；已经在看区间时再点 = 换一段。
            // 取消不改任何东西，胶囊留在原来那格。
            if (i >= _kPeriodKeys.length) {
              if (_periodPickerOpen) {
                setState(() => _periodPickerOpen = false);
              }
              _pickDateRange();
              return;
            }
            final k = _kPeriodKeys[i];
            // v12.7 · 自定义区间生效时, 点任何 period tab 都先清区间
            //   然后按 tab 意图继续: 同 tab 就切到 offset=0, 不同 tab 切粒度.
            if (_isCustomRange) {
              _clearCustomRange();
              if (k != _period) {
                _applyPeriod(period: k, offset: 0);
              }
              return;
            }
            if (k == _period) {
              // 再点选中项 → 展开/收起实例选择
              setState(() => _periodPickerOpen = !_periodPickerOpen);
            } else {
              // 切粒度 → offset 回到 0
              setState(() => _periodPickerOpen = false);
              _applyPeriod(period: k, offset: 0);
            }
          },
        ),
        ),
        // 实例选择条 — 点当前粒度 tab 展开 —— 横滑选具体哪一天/周/月/季/年
        // (自定义区间生效时不显示；区间在期间条第 6 格「区间」里选)
        if (_periodPickerOpen && !_isCustomRange) ...[
          const SizedBox(height: 4),
          SizedBox(
            // 两行文案 + 底边框 1.2，34 在部分 DPR 下会底溢出 0.5。
            height: 36,
            child: ListView.builder(
              scrollDirection: Axis.horizontal,
              padding: EdgeInsets.zero,
              itemCount: _periodInstanceCount(_period),
              itemBuilder: (ctx, i) => _periodInstanceChip(-i, onDark: onDark),
            ),
          ),
        ],
      ],
    );
  }

