  }

  Widget _buildComposeBar(_PeriodInfo p) {
    final compose = p.compose.where((c) => c.pct > 0).toList();
    if (compose.isEmpty) return const SizedBox.shrink();
    final leading = compose
        .take(2)
        .map((c) => '${c.name} ${c.pct.round()}%')
        .join(' · ');
    final label = compose.length > 2 ? '$leading · 其他' : leading;

    return Row(
      children: [
        Text(
          '渠道构成',
          style: LhTypography.sans(
            size: 8.8,
            color: DunesColors.resolve(context, LhColors.ink2),
            weight: FontWeight.w700,
            letterSpacing: 0.4,
            context: context,
          ),
        ),
        const SizedBox(width: 7),
        Expanded(
          child: ClipRRect(
            borderRadius: BorderRadius.circular(3),
            child: SizedBox(
              height: 5,
              child: Row(
                children: compose
                    .map(
                      (c) => Expanded(
                        flex: c.pct.round().clamp(1, 100),
                        child: Container(
                          color: DunesColors.resolveNullable(
                            context,
                            c.color,
                            role: DunesColorRole.surface,
                          ),
                        ),
                      ),
                    )
                    .toList(),
              ),
            ),
          ),
        ),
        const SizedBox(width: 7),
        Text(
          label,
          style: LhTypography.mono(
            size: 8,
            color: DunesColors.resolve(context, LhColors.mute),
            weight: FontWeight.w600,
            letterSpacing: 0.1,
            context: context,
          ),
        ),
      ],
    );
  }

  /// HUN 占比条（U / N / H 三色），与 _buildComposeBar 视觉对齐。
  /// 用当前 rows 的成本拆分汇总（带 hun 过滤后的实际可见 rows）。
  Widget _buildHunComposeBar(List<Map<String, dynamic>> rows) {
    double sumU = 0, sumN = 0, sumH = 0;
    int countU = 0, countN = 0, countMixed = 0;
    for (final r in rows) {
      final h = _hunOf(r);
      sumU += h.u;
      sumN += h.n;
      sumH += h.h;
      switch (h.primary) {
        case 'U':
          countU++;
          break;
        case 'N':
          countN++;
          break;
        case 'mixed':
          countMixed++;
          break;
      }
    }
    final total = sumU + sumN + sumH;
    if (total <= 0) return const SizedBox.shrink();

    final uPct = (sumU / total * 100);
    final nPct = (sumN / total * 100);
    final hPct = (sumH / total * 100);

    String segLabel(String token, double pct, int count) {
      if (pct < 0.5) return '';
      return '${_hunBadgeFor(token)} ${pct.round()}%';
    }

    final partsBuf = <String>[];
    final uTxt = segLabel('U', uPct, countU);
    final nTxt = segLabel('N', nPct, countN);
    final hTxt = segLabel('H', hPct, 0);
    if (uTxt.isNotEmpty) partsBuf.add(uTxt);
    if (nTxt.isNotEmpty) partsBuf.add(nTxt);
    if (hTxt.isNotEmpty) partsBuf.add(hTxt);
    if (countMixed > 0) partsBuf.add('${_hunLabelFor('mixed')} $countMixed');
    final label = partsBuf.join(' · ');

    return Row(
      children: [
        Text(
          '${_hunBarTitle()} 占比',
          style: LhTypography.sans(
            size: 8.8,
            color: DunesColors.resolve(context, LhColors.mute),
            weight: FontWeight.w600,
            letterSpacing: 0.4,
            context: context,
          ),
        ),
        const SizedBox(width: 7),
        Expanded(
          child: ClipRRect(
            borderRadius: BorderRadius.circular(3),
            child: SizedBox(
              height: 5,
              child: Row(
                children: [
                  if (uPct > 0.5)
                    Expanded(
                      flex: uPct.round().clamp(1, 100),
                      child: Container(
                        color: DunesColors.resolveNullable(
                          context,
                          _hunColorFor('U'),
                          role: DunesColorRole.surface,
                        ),
                      ),
                    ),
                  if (nPct > 0.5)
                    Expanded(
                      flex: nPct.round().clamp(1, 100),
                      child: Container(
                        color: DunesColors.resolveNullable(
                          context,
                          _hunColorFor('N'),
                          role: DunesColorRole.surface,
                        ),
                      ),
                    ),
                  if (hPct > 0.5)
                    Expanded(
                      flex: hPct.round().clamp(1, 100),
                      child: Container(
                        color: DunesColors.resolveNullable(
                          context,
                          _hunColorFor('H'),
                          role: DunesColorRole.surface,
                        ),
                      ),
                    ),
                  if (uPct < 0.5 && nPct < 0.5 && hPct < 0.5)
                    Expanded(
                      child: Container(
                        color: DunesColors.resolve(
                          context,
                          LhColors.line2,
                          role: DunesColorRole.surface,
                        ),
                      ),
                    ),
                ],
              ),
            ),
          ),
        ),
        const SizedBox(width: 7),
        Text(
          label.isEmpty ? '—' : label,
          style: LhTypography.mono(
            size: 8,
            color: DunesColors.resolve(context, LhColors.mute2),
            weight: FontWeight.w500,
            letterSpacing: 0.1,
            context: context,
          ),
        ),
      ],
    );
  }

  // ═══════════════════════════════════════════════════════════════════════
  // Loss-Profit Flow —— 损益推演流 (替换原并列 hero grid)
  //   会议原话: "所有锚点全部锚点与这个规模... 收入 − 成本 = 利润"
  //   设计: 5 个节点 + 4 座运算符桥, 从核销规模一步步走到效率, 让公式关系
  //         直接体现在 UI 上, 而不是 6 个并列格子看不到因果.
  //         每个节点可点 → 弹折线图 sheet.
  // ═══════════════════════════════════════════════════════════════════════

  Widget _buildLossProfitFlow(Map<String, double> totals, bool isEstimated) {
    final anchor = totals['verifiedSales'] ?? 0;
    final revenue = totals['revenue'] ?? 0;
    final cost = totals['cost'] ?? 0; // 经营成本 (= 业务成本)
    final tax = totals['tax'] ?? 0;
    final profit = totals['profit'] ?? 0;
    final rate = totals['rate'] ?? 0;

    // 派生比率 —— 从数据反推, 让用户看到"实际的利差率是多少"
    final spreadRate = anchor > 0 ? revenue / anchor * 100 : 0.0;
    final costRate = anchor > 0 ? cost / anchor * 100 : 0.0;
    final taxRate = revenue > 0 ? tax / revenue * 100 : 0.0;

    return Column(
      crossAxisAlignment: CrossAxisAlignment.stretch,
      children: [
        _flowKicker(),
        const SizedBox(height: 8),
        // ── 节点 1: 核销规模 (锚点起点) ───────────────
        _flowNode(
          key: 'verifiedSales',
          label: '核销规模',
          subLabel: '锚点',
          value: anchor,
          isRate: false,
          role: _FlowRole.anchor,
          rightBadge: isEstimated ? '估' : null,
        ),
        _flowBridge('×  利差率  ${spreadRate.toStringAsFixed(2)}%'),
        // ── 节点 2: 收入 (核销 × 利差率) ─────────────
        _flowNode(
          key: 'revenue',
          label: '收入',
          subLabel: '利差毛收入',
          value: revenue,
          isRate: false,
          role: _FlowRole.intermediate,
        ),
        _flowBridge(
          '−  经营成本  ${_fmtMoney(cost)}${_unitMoney(cost)}   '
          '(核销 × ${costRate.toStringAsFixed(2)}%)',
        ),
        _flowBridge(
          '−  税务成本  ${_fmtMoney(tax)}${_unitMoney(tax)}   '
          '(收入 × ${taxRate.toStringAsFixed(1)}%)',
        ),
        // ── 节点 3: 利润 (库字段 gross_profit) ───────────
        _flowNode(
          key: 'profit',
          label: '利润',
          subLabel: '库字段 gross_profit',
          value: profit,
          isRate: false,
          role: _FlowRole.intermediate,
        ),
        _flowBridge(
          '÷  成本合计  ${_fmtMoney(totals['totalCost'] ?? 0)}'
          '${_unitMoney(totals['totalCost'] ?? 0)}',
        ),
        // ── 节点 4: ROI (终点；毛利率另为 利润÷核销额) ───────────
        _flowNode(
          key: 'rate',
          label: 'ROI',
          subLabel: '利润 ÷ 成本合计',
          value: rate,
          isRate: true,
          role: _FlowRole.result,
        ),
      ],
    );
  }

  // ═════════════════════════════════════════════════════════════════════
  // ─── P&L 按钮网格 (v4 案例更新, 替换原 _buildLossProfitFlow) ────────
  //
  // 会议规则回顾:
  //   • 毛利率 = 利润 ÷ 核销额
  //   • ROI = 利润 ÷ 成本合计
  //   • 每格数字可点弹折线 (会议原话:"点那个数字就能看到日的")
  //
  // 布局:
  //   ┌─────────┐ ┌─────────┐ ┌─────────┐   Row 1: 利差 · 收入 · 销售 (紫)
  //   │ 利差率  │ │ 收入    │ │ 销售额  │
  //   └─────────┘ └─────────┘ └─────────┘
  //                                            ← whitespace 承担分行 (22px)
  //   ┌─────────┐ ┌─────────┐ ┌─────────┐   Row 2: 经营 · 合计 · 效率 (★)
  //   │ 经营成本│ │  成本   │ │ 效率 ★ │
  //   └─────────┘ └─────────┘ └─────────┘
  //
  // v9 编辑体 float: 全部撤掉 divider (列 hairline / 行 hairline),
  //                  分栏分行都靠 whitespace + typography. 简单 + 高级.
  //   • 保留 3×2 语义结构 (income-side / cost-side ★efficiency)
  //   • Row 2 加回「经营成本」(用户反馈: 拆细还是要看)
  //   • 「成本」直读 totalCost（= SUM(total_cost)），与经营成本并排
  //   • 利润口径 = 库字段 gross_profit；毛利率 = 利润 ÷ 核销额
  // ═════════════════════════════════════════════════════════════════════
  // ═════════════════════════════════════════════════════════════════════
  // Hero stat rail (v12 · swipeable 2-page) —— 4 col × 2 page
  //   · Page 1 · REVENUE 收入面: 核销规模 / 效率★ / 利差率 / 收入
  //   · Page 2 · COST    成本面: 销售规模 / 利差 / 成本合计
  // 手指左右滑切换; 底下小圆点指示 + 顶部小 kicker 显示当前 page label.
  // 展开 trend 时把 keyId 记进 _expandedTrendKey, 下方 InlineTrendPanel
  // 从任何一页都能触发/收起, 逻辑与原 PnL grid 一致.
  // ═════════════════════════════════════════════════════════════════════
  // ═══════════════════════════════════════════════════════════════════════
  // Hero stat rail —— 收入面 + 成本面「常驻双段」
  //
  //   v13 · 从 PageView 横滑改成两段上下常驻。
  //     Hero 的职责是「不做任何操作就知道现在什么情况」，把 50% 的核心口径
  //     藏在「← 滑动看收入」手势后面是自相矛盾的。翻页指示器、滑动提示、
  //     两个圆点一并删除 —— 那些 chrome 本身也是为了补偿信息被藏起来。
  //
  //   v13 · 标签去英文。GROSS / OP COST / TOTAL 是纯装饰（没人需要
  //     "OP COST" 才能理解"经营成本"），却让标签总高度超过数字本身。
  //     单语中文标签 + mono 规格，跟账本表头是同一套。
  //
  //   v13 · 全部左对齐。原来大数字左对齐、成本格各自居中，中间那格永远和
  //     上面任何东西都对不齐 —— 这是「看着不清晰」的几何来源。
  // ═══════════════════════════════════════════════════════════════════════
  // ───── 经营成本（银行流水口径）──────────────────────────────────────────
  // 主 Hero「成本」第四格。跟成本合计不是一个口径（账单 vs 银行流水），
  // 所以只挂在成本栏尾、虚线隔开、带「银行流水」标签，不进成本合计。
  // 数据是公司级流水，权限跟净TA 走；选了分类（能源 / 中石油…）时 Hero 是
  // 分类口径，公司级的数放上去会被当成那个分类的，所以不挂。
  String get _opCostRequestKey =>
      '$_period|$_periodOffset|${_customStart?.toIso8601String() ?? ''}|${_customEnd?.toIso8601String() ?? ''}';

  bool get _opCostEligible =>
      lighthouseHeroShowsOperatingCost &&
      _hasNetTaAccess &&
      _tab != 'netTa' &&
      _detailKey == null &&
      _groupFilter == '全部';

  bool get _opCostFresh => _opCostKey == _opCostRequestKey && _opCost != null;

  void _ensureOpCostLoaded() {
    final key = _opCostRequestKey;
    if (_opCostKey == key && (_opCost != null || _opCostLoading)) return;
    _opCostKey = key;
    _opCost = null;
    _opCostLoading = true;
    unawaited(
      _service
          .fetchOperatingCost(
            period: _period,
            offset: _periodOffset,
            startDate: _customStart,
            endDate: _customEnd,
          )
          .then(
            (data) {
              if (!mounted || _opCostKey != key) return;
              setState(() {
                _opCost = data;
                _opCostLoading = false;
              });
            },
            onError: (Object _) {
              if (!mounted || _opCostKey != key) return;
              setState(() {
                _opCost = const <String, dynamic>{'available': false};
                _opCostLoading = false;
              });
            },
          ),
    );
  }

  double _opNum(Object? v) => v is num ? v.toDouble() : 0;

  List<Map<String, dynamic>> _opCostRows() {
    final raw = _opCost?['secondaries'];
    if (raw is! List) return const <Map<String, dynamic>>[];
    return [
      for (final e in raw)
        if (e is Map) Map<String, dynamic>.from(e),
    ];
  }

  /// 金额 → (数字, 单位)。经营成本一律按绝对值显示，不带「-」「+」：
  /// 流出 / 流入已经由所在的分组说清楚了。[plus] 保留参数位，不再加号。
  ({String number, String unit}) _opCostAmount(double v, {bool plus = false}) {
    return (number: _fmt(v.abs()), unit: _unit(v.abs()));
  }

  /// 成本栏第四格。
  Widget _buildOpCostCell() {
    final fresh = _opCostFresh;
    final available = fresh && _opCost?['available'] == true;
    final open = _opCostOpen;
    final net = _opNum(_opCost?['net']);
    final plum = DunesColors.resolve(context, _LhPlum.primary);
    final deep = DunesColors.resolve(context, _LhPlum.deep);
    final amount = _opCostAmount(net);
    final valueText = !fresh ? '…' : (available ? amount.number : '—');
    final unitText = available ? amount.unit : '';
    final dir = _opCost?['deltaDir']?.toString();
    final pct = _opCost?['deltaPct'];
    String? deltaText;
    var deltaColor = DunesColors.resolve(context, LhColors.mute2);
    if (available && pct is num && (dir == 'up' || dir == 'down')) {
      // 后端按带符号的净额算方向；这里显示的是支出金额（正数），
      // 净额为负时方向要翻过来：净额更负 = 支出变多 = ↑。
      final costUp = net < 0 ? dir == 'down' : dir == 'up';
      // 本期 ≈ 0（显示 0.00万）还挂「↑100%」自相矛盾 —— 不写环比。
      if (!(costUp && net.abs() < 50) &&
          lighthouseDeltaPctShown(pct.toDouble())) {
        deltaText =
            '${costUp ? '↑' : '↓'}${pct.toStringAsFixed(pct.abs() >= 10 ? 0 : 1)}%';
        // 跟上面几格同一条规矩：越过 ±20% 才上红绿。
        deltaColor = lighthouseHeroDeltaIsLoud('opCost', pct.toDouble())
            ? DunesColors.resolve(context, costUp ? LhColors.neg : LhColors.pos)
            : DunesColors.resolve(context, LhColors.mute);
      }
    }
    return Semantics(
      button: true,
      expanded: open,
      label: open ? '收起经营成本明细' : '展开经营成本明细',
      child: GestureDetector(
        behavior: HitTestBehavior.opaque,
        onTap: () {
          LighthouseFeedback.instance.play(
            open
                ? LighthouseFeedbackKind.collapse
                : LighthouseFeedbackKind.expand,
          );
          setState(() => _opCostOpen = !open);
        },
        child: Padding(
          padding: const EdgeInsets.only(top: lighthouseCompactHeroMetricGap),
          child: Column(
            crossAxisAlignment: CrossAxisAlignment.stretch,
            mainAxisSize: MainAxisSize.min,
            children: [
              // 跟上面三格之间同一根内缩实线发丝（原来是虚线，格子对不上）。
              Container(
                height: 0.6,
                margin: const EdgeInsets.symmetric(horizontal: 4, vertical: 1),
                color: DunesColors.resolve(
                  context,
                  LhColors.line2,
                  role: DunesColorRole.surface,
                ),
              ),
              AnimatedContainer(
                duration: const Duration(milliseconds: 160),
                curve: Curves.easeOut,
                // 内边距跟指标格一致（4 / 3 / 2 / 3），标签左沿和上面对齐。
                margin: const EdgeInsets.only(top: 1),
                padding: const EdgeInsets.fromLTRB(4, 3, 2, 3),
                decoration: BoxDecoration(
                  color: open
                      ? DunesColors.resolve(
                          context,
                          Colors.white,
                          role: DunesColorRole.surface,
                        )
                      : Colors.transparent,
                  borderRadius: BorderRadius.circular(9),
                  border: Border.all(
                    color: open ? plum.withAlpha(60) : Colors.transparent,
                    width: 0.8,
                  ),
                  boxShadow: open
                      ? [
                          BoxShadow(
                            color: _LhPlum.deep.withAlpha(30),
                            blurRadius: 6,
                            offset: const Offset(0, 1.5),
                          ),
                        ]
                      : null,
                ),
                child: Column(
                  crossAxisAlignment: CrossAxisAlignment.start,
                  mainAxisSize: MainAxisSize.min,
                  children: [
                    Row(
                      children: [
                        Expanded(
                          child: Row(
                            mainAxisSize: MainAxisSize.min,
                            children: [
                              Flexible(
                                child: Text(
                                  '经营成本',
                                  maxLines: 1,
                                  overflow: TextOverflow.ellipsis,
                                  style: LhTypography.sans(
                                    size: lighthouseHeroCellLabelFontSize,
                                    color: open
                                        ? deep
                                        : DunesColors.resolve(
                                            context,
                                            LhColors.mute,
                                          ),
                                    weight: open
                                        ? FontWeight.w700
                                        : FontWeight.w500,
                                    height: 1.1,
                                    context: context,
                                  ),
                                ),
                              ),
                            ],
                          ),
                        ),
                        Icon(
                          open
                              ? Icons.keyboard_arrow_down_rounded
                              : Icons.chevron_right_rounded,
                          size: 13,
                          color: DunesColors.resolve(context, LhColors.mute2),
                        ),
                      ],
                    ),
                    const SizedBox(height: 3),
                    Column(
                      crossAxisAlignment: CrossAxisAlignment.start,
                      mainAxisSize: MainAxisSize.min,
                      children: [
                        Flexible(
                          flex: 0,
                          child: Text.rich(
                            TextSpan(
                              children: [
                                TextSpan(
                                  text: valueText,
                                  style:
                                      LhTypography.number(
                                        size: lighthouseHeroMetricValueFontSize,
                                        color: DunesColors.resolve(
                                          context,
                                          available
                                              ? LhColors.ink
                                              : LhColors.mute2,
                                        ),
                                        context: context,
                                      ).copyWith(
                                        fontWeight: FontWeight.w700,
                                        height: 1.0,
                                      ),
                                ),
                                if (unitText.isNotEmpty)
                                  TextSpan(
                                    text: unitText,
                                    style: LhTypography.sans(
                                      size: lighthouseLedgerSummaryUnitFontSize,
                                      color: DunesColors.resolve(
                                        context,
                                        LhColors.mute,
                                      ),
                                      weight: FontWeight.w500,
                                      height: 1.0,
                                      context: context,
                                    ),
                                  ),
                              ],
                            ),
                            maxLines: 1,
                            overflow: TextOverflow.ellipsis,
                          ),
                        ),
                        ...[
                          const SizedBox(height: 3),
                          Text(
                            deltaText ?? '—',
                            maxLines: 1,
                            softWrap: false,
                            style: _tabular(
                              LhTypography.mono(
                                size: lighthouseHeroCellDeltaFontSize,
                                color: deltaColor,
                                weight: FontWeight.w600,
                                height: 1.0,
                                context: context,
                              ),
                            ),
                          ),
                        ],
                      ],
                    ),
                  ],
                ),
              ),
            ],
          ),
        ),
      ),
    );
  }

  Widget _withOpCostCell(bool show, Widget grid) => show
      ? Column(
          crossAxisAlignment: CrossAxisAlignment.stretch,
          mainAxisSize: MainAxisSize.min,
          children: [grid, _buildOpCostCell()],
        )
      : grid;

  /// 点开后的面板：跟账本同一套「格子」。合计三格（净额是结果格），
  /// 下面一格一个二级分类，右上角是占比，淡紫底按占比铺。
  Widget _buildOpCostPanel() {
    final fresh = _opCostFresh;
    final data = fresh ? _opCost : null;
    final available = data?['available'] == true;
    final plum = DunesColors.resolve(context, _LhPlum.primary);
    final deep = DunesColors.resolve(context, _LhPlum.deep);
    final ink = DunesColors.resolve(context, LhColors.ink);
    final ink2 = DunesColors.resolve(context, LhColors.ink2);
    final mute = DunesColors.resolve(context, LhColors.mute);
    final mute2 = DunesColors.resolve(context, LhColors.mute2);
    final cellBg = DunesColors.resolve(
      context,
      const Color(0xFFF1F5FA),
      role: DunesColorRole.surface,
    );
    final resultBg = DunesColors.resolve(
      context,
      const Color(0xFFF3EEFC),
      role: DunesColorRole.surface,
    );

    final window = (data?['window'] ?? '').toString().trim();
    final days = data?['activeDays'];
    final meta = [
      if (window.isNotEmpty) window,
      if (days is num && days > 0) '${days.toInt()} 天有流水',
    ].join(' · ');

    Widget amountText(double v, {double size = 13, bool plus = false}) {
      final a = _opCostAmount(v, plus: plus);
      return Text.rich(
        TextSpan(
          children: [
            TextSpan(
              text: a.number,
              style: LhTypography.number(
                size: size,
                color: ink,
                context: context,
              ).copyWith(fontWeight: FontWeight.w700, height: 1.0),
            ),
            TextSpan(
              text: a.unit,
              style: LhTypography.sans(
                size: 8.5,
                color: mute,
                weight: FontWeight.w500,
                height: 1.0,
                context: context,
              ),
            ),
          ],
        ),
        maxLines: 1,
        overflow: TextOverflow.ellipsis,
      );
    }

    Widget header() => Row(
      children: [
        Container(
          width: 6,
          height: 6,
          decoration: BoxDecoration(
            color: plum,
            borderRadius: BorderRadius.circular(2),
          ),
        ),
        const SizedBox(width: 6),
        Text(
          '经营成本',
          style: LhTypography.sans(
            size: 12.5,
            color: deep,
            weight: FontWeight.w700,
            height: 1.1,
            context: context,
          ),
        ),
        const SizedBox(width: 6),
        Expanded(
          child: Text(
            meta,
            maxLines: 1,
            overflow: TextOverflow.ellipsis,
            style: _tabular(
              LhTypography.mono(
                size: 10,
                color: mute2,
                weight: FontWeight.w500,
                height: 1.1,
                context: context,
              ),
            ),
          ),
        ),
        GestureDetector(
          behavior: HitTestBehavior.opaque,
          onTap: () {
            LighthouseFeedback.instance.play(LighthouseFeedbackKind.collapse);
            setState(() => _opCostOpen = false);
          },
          child: Padding(
            padding: const EdgeInsets.symmetric(horizontal: 4, vertical: 4),
            child: Row(
              mainAxisSize: MainAxisSize.min,
              children: [
                Text(
                  '收起',
                  style: LhTypography.sans(
                    size: 10.5,
                    color: plum,
                    weight: FontWeight.w600,
                    height: 1.0,
                    context: context,
                  ),
                ),
                const SizedBox(width: 2),
                Icon(Icons.keyboard_arrow_up_rounded, size: 13, color: plum),
              ],
            ),
          ),
        ),
      ],
    );

    Widget totalCell(
      String label,
      double v, {
      bool result = false,
      bool plus = false,
    }) => Container(
      padding: const EdgeInsets.fromLTRB(10, 8, 10, 8),
      decoration: BoxDecoration(
        color: result ? resultBg : cellBg,
        borderRadius: BorderRadius.circular(10),
      ),
      child: Column(
        crossAxisAlignment: CrossAxisAlignment.start,
        mainAxisSize: MainAxisSize.min,
        children: [
          Text(
            label,
            style: LhTypography.sans(
              size: 10,
              color: result ? deep : ink2,
              weight: FontWeight.w700,
              height: 1.0,
              context: context,
            ),
          ),
          const SizedBox(height: 6),
          amountText(v, size: result ? 16 : 13, plus: plus),
        ],
      ),
    );

    Widget groupTitle(String title, String note) => Row(
      children: [
        Text(
          title,
          style: LhTypography.sans(
            size: 10.5,
            color: ink2,
            weight: FontWeight.w700,
            height: 1.0,
            context: context,
          ),
        ),
        const SizedBox(width: 6),
        Flexible(
          child: Text(
            note,
            maxLines: 1,
            overflow: TextOverflow.ellipsis,
            style: LhTypography.sans(
              size: 9.5,
              color: mute2,
              height: 1.0,
              context: context,
            ),
          ),
        ),
      ],
    );

    String pctText(double share) {
      final p = share * 100;
      if (p >= 10) return '${p.toStringAsFixed(1)}%';
      if (p >= 1) return '${p.toStringAsFixed(1)}%';
      return '${p.toStringAsFixed(2)}%';
    }

    Widget secCell(Map<String, dynamic> r, double total, {bool top = false}) {
      final v = _opNum(r['net']);
      final share = total > 0 ? (v.abs() / total).clamp(0.0, 1.0) : 0.0;
      final d = _opNum(r['days']).toInt();
      final o = _opNum(r['outDays']).toInt();
      final i = _opNum(r['inDays']).toInt();
      return ClipRRect(
        borderRadius: BorderRadius.circular(10),
        child: ColoredBox(
          color: cellBg,
          child: Stack(
            children: [
              Positioned.fill(
                child: Align(
                  alignment: Alignment.centerLeft,
                  child: FractionallySizedBox(
                    widthFactor: math.max(share, 0.015),
                    heightFactor: 1,
                    child: ColoredBox(color: plum.withAlpha(22)),
                  ),
                ),
              ),
              Padding(
                padding: const EdgeInsets.fromLTRB(10, 8, 10, 7),
                child: Column(
                  crossAxisAlignment: CrossAxisAlignment.start,
                  mainAxisSize: MainAxisSize.min,
                  children: [
                    Row(
                      children: [
                        Expanded(
                          child: Text(
                            (r['name'] ?? '').toString(),
                            maxLines: 1,
                            overflow: TextOverflow.ellipsis,
                            style: LhTypography.sans(
                              size: 10,
                              color: ink2,
                              weight: FontWeight.w700,
                              height: 1.0,
                              context: context,
                            ),
                          ),
                        ),
                        Text(
                          pctText(share),
                          style: _tabular(
                            LhTypography.mono(
                              size: 9,
                              color: top ? deep : mute,
                              weight: FontWeight.w600,
                              height: 1.0,
                              context: context,
                            ),
                          ),
                        ),
                      ],
                    ),
                    const SizedBox(height: 6),
                    amountText(v, plus: v > 0),
                    const SizedBox(height: 5),
                    Text(
                      '$d 天 · 出 $o / 入 $i',
                      maxLines: 1,
                      overflow: TextOverflow.ellipsis,
                      style: _tabular(
                        LhTypography.sans(
                          size: 9,
                          color: mute2,
                          height: 1.0,
                          context: context,
                        ),
                      ),
                    ),
                  ],
                ),
              ),
            ],
          ),
        ),
      );
    }

    Widget body;
    if (!fresh) {
      body = Padding(
        padding: const EdgeInsets.symmetric(vertical: 18),
        child: Center(
          child: Text(
            '经营成本加载中…',
            style: LhTypography.sans(size: 11, color: mute2, context: context),
          ),
        ),
      );
    } else if (!available) {
      body = Padding(
        padding: const EdgeInsets.symmetric(vertical: 18),
        child: Center(
          child: Text(
            '暂时拿不到经营成本（银行流水日报未接通）',
            textAlign: TextAlign.center,
            style: LhTypography.sans(size: 11, color: mute2, context: context),
          ),
        ),
      );
    } else {
      final rows = _opCostRows();
      final outs = [
        for (final r in rows)
          if (_opNum(r['net']) < 0) r,
      ];
      final ins = [
        for (final r in rows)
          if (_opNum(r['net']) >= 0) r,
      ];
      final outTotal = outs.fold<double>(
        0,
        (s, r) => s + _opNum(r['net']).abs(),
      );
      final inTotal = ins.fold<double>(0, (s, r) => s + _opNum(r['net']));
      // 不用 LayoutBuilder：Hero 外层若有量固有尺寸的祖先会直接报错。
      // 列数按屏宽定，格子用 Row + Expanded 排，哪种父布局都能算。
      final screenW =
          MediaQuery.sizeOf(context).width / _uiZoom.clamp(0.5, 2.0);
      final cols = screenW >= 1000 ? 5 : (screenW >= 640 ? 3 : 2);
      const gap = 6.0;
      Widget grid(List<Widget> cells) {
        final lines = <Widget>[];
        for (var start = 0; start < cells.length; start += cols) {
          if (start > 0) lines.add(const SizedBox(height: gap));
          lines.add(
            Row(
              crossAxisAlignment: CrossAxisAlignment.start,
              children: [
                for (var k = 0; k < cols; k++) ...[
                  if (k > 0) const SizedBox(width: gap),
                  Expanded(
                    child: start + k < cells.length
                        ? cells[start + k]
                        : const SizedBox.shrink(),
                  ),
                ],
              ],
            ),
          );
        }
        return Column(
          crossAxisAlignment: CrossAxisAlignment.stretch,
          mainAxisSize: MainAxisSize.min,
          children: lines,
        );
      }

      body = Builder(
        builder: (context) {
          return Column(
            crossAxisAlignment: CrossAxisAlignment.stretch,
            mainAxisSize: MainAxisSize.min,
            children: [
              Row(
                children: [
                  Expanded(
                    flex: 13,
                    child: totalCell(
                      _opNum(data?['net']) > 0 ? '净流入' : '净支出',
                      _opNum(data?['net']),
                      result: true,
                    ),
                  ),
                  const SizedBox(width: gap),
                  Expanded(
                    flex: 10,
                    child: totalCell('流出', _opNum(data?['outflow'])),
                  ),
                  const SizedBox(width: gap),
                  Expanded(
                    flex: 10,
                    child: totalCell('流入', _opNum(data?['inflow']), plus: true),
                  ),
                ],
              ),
              if (outs.isNotEmpty) ...[
                const SizedBox(height: 12),
                groupTitle('流出', '${outs.length} 类 · 右上角是占流出'),
                const SizedBox(height: 6),
                grid([
                  for (var k = 0; k < outs.length; k++)
                    secCell(outs[k], outTotal, top: k < 2),
                ]),
              ],
              // 没有流水的二级分类（字典里有、这段时间 0 笔）不显示。
              if (ins.isNotEmpty) ...[
                const SizedBox(height: 12),
                groupTitle('流入', '${ins.length} 类 · 右上角是占流入'),
                const SizedBox(height: 6),
                grid([for (final r in ins) secCell(r, inTotal)]),
              ],
            ],
          );
        },
      );
    }

    return Container(
      margin: const EdgeInsets.only(top: lighthouseHeroCardGap),
      padding: const EdgeInsets.fromLTRB(12, 10, 12, 12),
      decoration: BoxDecoration(
        color: DunesColors.resolve(
          context,
          Colors.white,
          role: DunesColorRole.surface,
        ),
        border: Border.all(color: plum.withAlpha(70), width: 0.8),
        borderRadius: BorderRadius.circular(
          lighthouseLedgerSummaryPanelRadius + 2,
        ),
        boxShadow: [
          BoxShadow(
            color: _LhPlum.deep.withAlpha(24),
            blurRadius: 14,
            spreadRadius: -6,
            offset: const Offset(0, 6),
          ),
        ],
      ),
      child: Column(
        crossAxisAlignment: CrossAxisAlignment.stretch,
        mainAxisSize: MainAxisSize.min,
        children: [header(), const SizedBox(height: 10), body],
      ),
    );
  }

  Widget _buildHeroStatRail(
    Map<String, double> totals, {
    bool whiteBackground = false,
    Map<String, dynamic>? entityRow,
    bool interactive = true,
    String? focusKey,
    String? traceKey,
    void Function(({String? focus, String? trace}))? onMetricActivate,
    String? sectionOnly,
  }) {
    final sales = totals['sales'] ?? 0;
    final verified = totals['verifiedSales'] ?? 0;
    final gmv = totals['gmv'] ?? 0;
    final prepaid = totals['prepaid'] ?? 0;
    final revenue = totals['revenue'] ?? 0;
    final spread = totals['spread'] ?? 0;
    final profit = totals['profit'] ?? 0;
    final netProfit = totals['netProfit'] ?? 0;
    final totalCost = totals['totalCost'] ?? totals['costTotal'] ?? 0;
    final projectCost = totals['projectCost'] ?? 0;
    final businessCost = totals['cost'] ?? totals['businessCost'] ?? 0;
    final grossMargin = totals['grossMargin'] ?? 0;
    final rate = totals['rate'] ?? 0;

    // 拍平版：分区不再是四张带色卡，而是「浅灰栏头 + 竖线分栏」的表格排布。
    // 账本行展开体（whiteBackground）保持卡片版 —— 它嵌在列表里，需要边框收口。
    final flat =
        lighthouseHeroUsesFlatLayout && !whiteBackground && sectionOnly == null;
    Widget? selectedStrip;

    // 经营成本：只在一级主 Hero、全部分类时挂（见 _opCostEligible）。
    final showOpCost =
        interactive &&
        entityRow == null &&
        !whiteBackground &&
        sectionOnly == null &&
        _opCostEligible;
    if (showOpCost && _opCostKey != _opCostRequestKey) {
      WidgetsBinding.instance.addPostFrameCallback((_) {
        if (mounted) _ensureOpCostLoaded();
      });
    }

    Widget metric(
      String key,
      String label,
      double value, {
      bool isRate = false,
    }) {
      return _statCell(
        keyId: key,
        label: label,
        value: value,
        isRate: isRate,
        entityRow: entityRow,
        interactive: interactive,
        focusKey: focusKey,
        traceKey: traceKey,
        onMetricActivate: onMetricActivate,
      );
    }

    Widget metricGrid(
      List<({String key, String label, double value, bool isRate})> items, {
      required int columns,
      Color? divider,
    }) {
      final rows = <Widget>[];
      for (var start = 0; start < items.length; start += columns) {
        final rowItems = items.skip(start).take(columns).toList();
        rows.add(
          Row(
            crossAxisAlignment: CrossAxisAlignment.start,
            children: [
              for (var index = 0; index < columns; index++) ...[
                if (index > 0) const SizedBox(width: 4),
                Expanded(
                  child: index < rowItems.length
                      ? metric(
                          rowItems[index].key,
                          rowItems[index].label,
                          rowItems[index].value,
                          isRate: rowItems[index].isRate,
                        )
                      : const SizedBox.shrink(),
                ),
              ],
            ],
          ),
        );
        if (start + columns < items.length) {
          rows.add(const SizedBox(height: lighthouseCompactHeroMetricGap));
          // v23 · 面板内行分隔：和账本卡同一根内缩发丝线。
          if (divider != null) {
            rows.add(
              Container(
                height: 0.6,
                margin: const EdgeInsets.symmetric(horizontal: 4, vertical: 1),
                color: DunesColors.resolveNullable(
                  context,
                  divider,
                  role: DunesColorRole.surface,
                ),
              ),
            );
          }
        }
      }
      return Column(
        crossAxisAlignment: CrossAxisAlignment.stretch,
        mainAxisSize: MainAxisSize.min,
        children: rows,
      );
    }

    // v23.2 · 利润 / 经营性净现金流坐在蓝色「结果」面板上，标题胶囊跟着换蓝色系：
    // 原来玫红 / 绿图标压在蓝底上，两套配色在同一块里打架。
    bool blueSection(String key) =>
        lighthouseHeroMatchesLedgerCard && (key == 'profit' || key == 'cash');
    Color sectionAccent(String key) => blueSection(key)
        ? DunesColors.resolve(
            context,
            const Color(lighthouseLedgerResultBlockAccentValue),
          )
        : DunesColors.resolve(
            context,
            Color(lighthouseHeroSectionAccentValues[key]!),
          );
    Color sectionChip(String key) => blueSection(key)
        ? DunesColors.resolve(
            context,
            const Color(lighthouseHeroResultSectionChipValue),
          )
        : DunesColors.resolve(
            context,
            Color(lighthouseHeroSectionChipValues[key]!),
          );
    Color sectionTitleColor(String key) => blueSection(key)
        ? DunesColors.resolve(
            context,
            const Color(lighthouseHeroResultSectionTitleValue),
          )
        : DunesColors.resolve(
            context,
            Color(lighthouseHeroSectionTitleValues[key]!),
          );

    IconData sectionIcon(String key) {
      return switch (lighthouseHeroSectionIconKeys[key]) {
        'monitoring' => Icons.show_chart_rounded,
        'receipt' => Icons.receipt_long_rounded,
        'wallet' => Icons.account_balance_wallet_outlined,
        _ => Icons.trending_up_rounded,
      };
    }

    Widget sectionHeader(String key, String title) {
      final accent = sectionAccent(key);
      // v23.3 · 方案 A：标题做「轻」。
      // 旧胶囊一颗三层色（实心色片 + 同色胶囊底 + 彩色字），三颗并排像贴纸，
      // 琥珀那颗在紫 / 灰 / 蓝的页面里最跳，眼睛先落在标签上而不是数字上。
      // 现在：线条图标 + 深灰字，无底色；颜色只留在图标上 ——
      // 规模 / 成本中性灰紫，利润 / 现金流用结果蓝，跟蓝面板对上。
      if (lighthouseHeroMatchesLedgerCard &&
          lighthouseHeroSectionUsesQuietTitle) {
        final iconColor = blueSection(key)
            ? DunesColors.resolve(
                context,
                const Color(lighthouseLedgerResultBlockAccentValue),
              )
            : DunesColors.resolve(
                context,
                const Color(lighthouseHeroQuietSectionIconValue),
              );
        final icon = switch (lighthouseHeroSectionIconKeys[key]) {
          'monitoring' => Icons.show_chart_rounded,
          'receipt' => Icons.receipt_long_outlined,
          'wallet' => Icons.account_balance_wallet_outlined,
          _ => Icons.trending_up_rounded,
        };
        return SizedBox(
          // 和旧胶囊同高，换样式时下面的数字不跳。
          height: lighthouseHeroSectionIconSize + 6,
          child: Row(
            children: [
              Icon(
                icon,
                size: 14,
                color: DunesColors.resolveNullable(context, iconColor),
              ),
              const SizedBox(width: 5),
              Flexible(
                child: LhScrollText(
                  title,
                  maxLines: 1,
                  overflow: TextOverflow.ellipsis,
                  // 2026-10-21 · 分区标题加粗、改深墨色（原型：12 / w700 / ink）。
                  style: LhTypography.sans(
                    size: lighthouseHeroGroupTitleFontSize + 2,
                    color: DunesColors.resolve(context, LhColors.ink),
                    weight: FontWeight.w700,
                    letterSpacing: 0.2,
                    height: 1.3,
                    context: context,
                  ),
                ),
              ),
            ],
          ),
        );
      }
      if (lighthouseHeroSectionUsesHeroSurface) {
        // 和大数卡「2026.07」标签同一个胶囊形状；卡面统一白紫纸，
        // 分组感收进这颗胶囊：胶囊吃分区淡色、图标片实心分区色。
        // 三张白卡长得一样时，扫一眼找「利润」靠的就是这块颜色。
        return Align(
          alignment: Alignment.centerLeft,
          child: Container(
            padding: const EdgeInsets.fromLTRB(3, 3, 7, 3),
            decoration: BoxDecoration(
              color: DunesColors.resolveNullable(
                context,
                sectionChip(key),
                role: DunesColorRole.surface,
              ),
              borderRadius: BorderRadius.circular(
                lighthouseHeroMastheadLabelRadius,
              ),
            ),
            child: Row(
              mainAxisSize: MainAxisSize.min,
              children: [
                Container(
                  width: lighthouseHeroSectionIconSize,
                  height: lighthouseHeroSectionIconSize,
                  decoration: BoxDecoration(
                    color: DunesColors.resolveNullable(
                      context,
                      accent,
                      role: DunesColorRole.surface,
                    ),
                    borderRadius: BorderRadius.circular(5),
                  ),
                  child: Icon(
                    sectionIcon(key),
                    size: 11,
                    color: DunesColors.resolve(context, LhColors.paper),
                  ),
                ),
                const SizedBox(width: 5),
                Flexible(
                  child: LhScrollText(
                    title,
                    maxLines: 1,
                    overflow: TextOverflow.ellipsis,
                    style: LhTypography.sans(
                      size: lighthouseHeroGroupTitleFontSize + 1,
                      color: sectionTitleColor(key),
                      weight: FontWeight.w600,
                      letterSpacing: 0.1,
                      height: 1.0,
                      context: context,
                    ),
                  ),
                ),
              ],
            ),
          ),
        );
      }
      return Row(
        children: [
          Container(
            width: lighthouseHeroSectionIconSize,
            height: lighthouseHeroSectionIconSize,
            decoration: BoxDecoration(
              // chip 底已经带色，图标片走实心 + 白图标，chip 里才有个焦点。
              color: DunesColors.resolveNullable(
                context,
                accent,
                role: DunesColorRole.surface,
              ),
              borderRadius: BorderRadius.circular(5),
            ),
            child: Icon(
              sectionIcon(key),
              size: 10.5,
              color: DunesColors.resolve(context, LhColors.paper),
            ),
          ),
          const SizedBox(width: 5),
          Flexible(
            child: LhScrollText(
              title,
              maxLines: 1,
              overflow: TextOverflow.ellipsis,
              style: LhTypography.sans(
                size: lighthouseHeroGroupTitleFontSize,
                color: sectionTitleColor(key),
                weight: FontWeight.w700,
                height: 1.1,
                context: context,
              ),
            ),
          ),
          if (lighthouseHeroShowsSectionAccentDash) ...[
            const SizedBox(width: 5),
            Container(
              width: 12,
              height: 2,
              decoration: BoxDecoration(
                color: DunesColors.resolveNullable(
                  context,
                  accent.withAlpha(155),
                  role: DunesColorRole.surface,
                ),
                borderRadius: BorderRadius.circular(2),
              ),
            ),
          ],
        ],
      );
    }

    // 分区靠整张卡的淡色底区分。查表取固定值，不用 accent.withAlpha ——
    // 透明度叠色压在白底上掉彩度，四张卡会一起发灰。
    // Hero 框架版：和大数卡 / 走势卡同一张白紫纸、同一根轻紫边。
    final heroSurface = whiteBackground || lighthouseHeroSectionUsesHeroSurface;
    // v23 · 与账本卡同一套面板：规模 / 成本灰，利润 / 现金流蓝。
    // v23.1 · 面板补回一圈浅边 —— 灰面板压在白壳上只差 3% 明度，
    // 没有边时三块的边界是「猜」出来的，读起来像一片糊在一起的灰。
    final ledgerPanels = lighthouseHeroMatchesLedgerCard;
    // 主 Hero（上面有蓝底「本日利润」大数卡）里利润栏不再铺蓝，免得一屏两块
    // 蓝抢重点；账本行展开体没有大数卡，利润栏照旧是蓝的结果块。
    final heroHasOwnShare =
        entityRow == null && !whiteBackground && sectionOnly == null;
    bool isResultSection(String key) =>
        (key == 'profit' && !heroHasOwnShare) || key == 'cash';
    Color sectionTint(String key) => ledgerPanels
        ? (isResultSection(key)
              ? DunesColors.resolve(
                  context,
                  const Color(lighthouseLedgerResultBlockAccentValue),
                ).withAlpha(lighthouseLedgerSummaryResultPanelAlpha)
              : DunesColors.resolve(
                  context,
                  const Color(lighthouseLedgerSummaryNeutralPanelValue),
                ))
        : heroSurface
        ? DunesColors.resolve(context, const Color(0xFFFFFDFF))
        : DunesColors.resolve(
            context,
            Color(lighthouseHeroSectionTintValues[key]!),
          );
    Color sectionEdge(String key) => ledgerPanels
        ? (isResultSection(key)
              ? DunesColors.resolve(
                  context,
                  const Color(lighthouseLedgerResultBlockAccentValue),
                ).withAlpha(lighthouseHeroPanelResultEdgeAlpha)
              : DunesColors.resolve(
                  context,
                  const Color(lighthouseHeroPanelNeutralEdgeValue),
                ))
        : heroSurface
        ? DunesColors.resolve(context, _LhPlum.heroEdge)
        : DunesColors.resolve(
            context,
            Color(lighthouseHeroSectionEdgeValues[key]!),
          );
    final sectionEdgeWidth = ledgerPanels
        ? lighthouseHeroPanelEdgeWidth
        : (heroSurface ? 0.7 : 0.8);
    Color sectionDivider(String key) => isResultSection(key)
        ? DunesColors.resolve(
            context,
            const Color(lighthouseLedgerResultBlockAccentValue),
          ).withAlpha(46)
        : DunesColors.resolve(context, LhColors.line2);

    Widget strip({
      required String sectionKey,
      required String title,
      required Widget child,
      Widget? footer,
    }) {
      final card = LighthouseShareableCard(
        session: widget.session,
        title:
            '${entityRow?['name'] ?? (_detailKey?.split('::').first ?? _l1SummaryTitle)} · $title',
        rangeLabel: _selectedRangeLabel,
        compact: true,
        data: () => _sharedCardData(
          kind: 'panel',
          title:
              '${entityRow?['name'] ?? (_detailKey?.split('::').first ?? _l1SummaryTitle)} · $title',
          totals: totals,
          entityRow: entityRow,
          section: sectionKey,
          panelWhite: whiteBackground,
        ),
        previewBuilder: _sharedCardPreview,
        builder: (shareIcon) => Container(
          padding: const EdgeInsets.all(lighthouseHeroCardPadding),
          decoration: BoxDecoration(
            color: DunesColors.resolveNullable(
              context,
              sectionTint(sectionKey),
              role: DunesColorRole.surface,
            ),
            border: Border.all(
              color: sectionEdge(sectionKey),
              width: sectionEdgeWidth,
            ),
            borderRadius: BorderRadius.circular(
              ledgerPanels
                  ? lighthouseLedgerSummaryPanelRadius
                  : lighthouseHeroCardRadius,
            ),
            boxShadow: lighthouseHeroUsesCardShadow
                ? [
                    BoxShadow(
                      color: Colors.black.withAlpha(9),
                      blurRadius: 8,
                      offset: const Offset(0, 2),
                    ),
                  ]
                : null,
          ),
          child: Column(
            crossAxisAlignment: CrossAxisAlignment.stretch,
            children: [
              Row(
                children: [
                  Expanded(child: sectionHeader(sectionKey, title)),
                  // 主 Hero 标题行已经有一个转发（整张汇总卡），三栏不再各挂一个；
                  // 账本行展开体 / 单栏视图没有那个总入口，照旧留着。
                  if (!heroHasOwnShare) shareIcon,
                ],
              ),
              // 胶囊比裸标题高 6，间距收 2，正文起点基本不动。
              SizedBox(height: lighthouseHeroSectionUsesHeroSurface ? 6 : 8),
              child,
              if (footer != null) ...[
                const Spacer(),
                const SizedBox(height: 10),
                footer,
              ],
            ],
          ),
        ),
      );
      if (sectionOnly == sectionKey) selectedStrip = card;
      return card;
    }

    // 账本展开体没有上方的大数卡，保留现金流通栏，避免丢失这项指标。
    Widget cashBanner() {
      final card = LighthouseShareableCard(
        session: widget.session,
        title: '${entityRow?['name'] ?? _l1SummaryTitle} · 经营性净现金流',
        rangeLabel: _selectedRangeLabel,
        compact: true,
        data: () => _sharedCardData(
          kind: 'panel',
          title: '${entityRow?['name'] ?? _l1SummaryTitle} · 经营性净现金流',
          totals: totals,
          entityRow: entityRow,
          section: 'cash',
          panelWhite: whiteBackground,
        ),
        previewBuilder: _sharedCardPreview,
        builder: (shareIcon) => Container(
          padding: const EdgeInsets.fromLTRB(
            lighthouseHeroCardPadding + 3,
            6,
            lighthouseHeroCardPadding + 3,
            7,
          ),
          decoration: BoxDecoration(
            color: DunesColors.resolveNullable(
              context,
              sectionTint('cash'),
              role: DunesColorRole.surface,
            ),
            border: Border.all(
              color: sectionEdge('cash'),
              width: sectionEdgeWidth,
            ),
            borderRadius: BorderRadius.circular(
              ledgerPanels
                  ? lighthouseLedgerSummaryPanelRadius
                  : lighthouseHeroCardRadius,
            ),
            boxShadow: lighthouseHeroUsesCardShadow
                ? [
                    BoxShadow(
                      color: Colors.black.withAlpha(9),
                      blurRadius: 8,
                      offset: const Offset(0, 2),
                    ),
                  ]
                : null,
          ),
          child: Row(
            crossAxisAlignment: CrossAxisAlignment.center,
            children: [
              // sectionHeader 内部是 Row + Flexible，得给它一个有界宽度，
              // 不然它会把整条都吃掉。
              Expanded(child: sectionHeader('cash', '经营性净现金流')),
              const SizedBox(width: 12),
              SizedBox(
                width: 112,
                child: metric('prepaid', '预收净增', prepaid.toDouble()),
              ),
              const SizedBox(width: 4),
              shareIcon,
            ],
          ),
        ),
      );
      if (sectionOnly == 'cash') selectedStrip = card;
      return card;
    }

    // ═══ 拍平版 ═══════════════════════════════════════════════════
    // 参照原型：一条通栏浅灰表头（三个标题在同一条带子里，靠竖线分栏）+
    // 三栏正文，栏内一行一个指标、行间发丝线。全页只剩涨红跌绿两种色。
    if (flat) {
      // 一行一个指标：标签在上，数字和环比同一行。
      // 原来一格是三行（标签/数字/环比），压回两行，抵掉「一行一个」多出的高度。
      Widget cell(
        String key,
        String label,
        double value, {
        bool isRate = false,
        bool last = false,
      }) => _statCell(
        keyId: key,
        label: label,
        value: value,
        isRate: isRate,
        flat: true,
        flatLast: last,
        entityRow: entityRow,
        interactive: interactive,
        focusKey: focusKey,
        traceKey: traceKey,
        onMetricActivate: onMetricActivate,
      );

      // 栏内缩进：第一栏贴左沿（和标题、大数共用整屏那条基准线），
      // 后两栏在竖线右边让开 10。表头和正文用同一套缩进，才对得上。
      Widget inset(Widget child, {required bool first}) => Padding(
        padding: EdgeInsets.only(left: first ? 0 : 10, right: 6),
        child: child,
      );

      Widget tri(Widget a, Widget b, Widget c, {required Color sep}) => Row(
        crossAxisAlignment: CrossAxisAlignment.stretch,
        children: [
          Expanded(flex: lighthouseHeroScaleColumnFlex, child: a),
          Container(
            width: 0.7,
            color: DunesColors.resolveNullable(
              context,
              sep,
              role: DunesColorRole.surface,
            ),
          ),
          Expanded(flex: lighthouseHeroCostColumnFlex, child: b),
          Container(
            width: 0.7,
            color: DunesColors.resolveNullable(
              context,
              sep,
              role: DunesColorRole.surface,
            ),
          ),
          Expanded(flex: lighthouseHeroResultColumnFlex, child: c),
        ],
      );

      Widget bandCell(String title, {required bool first}) => inset(
        Align(
          alignment: Alignment.centerLeft,
          child: LhScrollText(
            title,
            maxLines: 1,
            overflow: TextOverflow.ellipsis,
            style: LhTypography.sans(
              size: lighthouseHeroGroupTitleFontSize,
              color: DunesColors.resolve(context, LhColors.ink2),
              weight: FontWeight.w700,
              letterSpacing: 0.2,
              height: 1.1,
              context: context,
            ),
          ),
        ),
        first: first,
      );

      Widget band(String a, String b, String c) => Container(
        height: lighthouseHeroFlatBandHeight,
        decoration: BoxDecoration(
          color: DunesColors.resolve(
            context,
            LhColors.ink,
            role: DunesColorRole.surface,
          ).withAlpha(lighthouseHeroFlatBandAlpha),
          border: Border(
            bottom: BorderSide(
              color: DunesColors.resolve(
                context,
                LhColors.line,
                role: DunesColorRole.border,
              ),
              width: 0.7,
            ),
          ),
        ),
        child: tri(
          bandCell(a, first: true),
          bandCell(b, first: false),
          bandCell(c, first: false),
          sep: DunesColors.resolve(context, LhColors.line),
        ),
      );

      Widget col(List<Widget> rows, {required bool first}) => inset(
        Column(
          crossAxisAlignment: CrossAxisAlignment.stretch,
          mainAxisSize: MainAxisSize.min,
          children: rows,
        ),
        first: first,
      );

      // IntrinsicHeight：三栏行数不同（利润最长），竖线要拉到最长那栏的底。
      Widget grid(List<Widget> a, List<Widget> b, List<Widget> c) =>
          IntrinsicHeight(
            child: tri(
              col(a, first: true),
              col(b, first: false),
              col(c, first: false),
              sep: DunesColors.resolve(context, LhColors.line2),
            ),
          );

      if (_tab == 'netTa' && entityRow == null) {
        double nt(String key) => totals[key] ?? 0;
        return Column(
          crossAxisAlignment: CrossAxisAlignment.stretch,
          children: [
            band('资金流入', '资金流出', '五类净额'),
            grid(
              [
                cell('netTaInflow', '流入合计', nt('netTaInflow')),
                cell(
                  'netTaOperatingInflow',
                  '经营活动流入',
                  nt('netTaOperatingInflow'),
                ),
                cell(
                  'netTaOtherInflow',
                  '其他流入',
                  nt('netTaOtherInflow'),
                  last: true,
                ),
              ],
              [
                cell('netTaOutflow', '流出合计', nt('netTaOutflow')),
                cell(
                  'netTaOperatingOutflow',
                  '经营性流出',
                  nt('netTaOperatingOutflow'),
                ),
                cell(
                  'netTaFinancingOutflow',
                  '筹资流出',
                  nt('netTaFinancingOutflow'),
                ),
                cell(
                  'netTaCostOutflow',
                  '项目+业务成本',
                  nt('netTaCostOutflow'),
                  last: true,
                ),
              ],
              [
                cell('netTaOperating', '经营活动', nt('netTaOperating')),
                cell('netTaFinancing', '筹资活动', nt('netTaFinancing')),
                cell('netTaOpCost', '经营成本', nt('netTaOpCost')),
                cell('netTaProjectCost', '项目成本', nt('netTaProjectCost')),
                cell('netTaBizCost', '业务成本', nt('netTaBizCost'), last: true),
              ],
            ),
          ],
        );
      }

      return Column(
        crossAxisAlignment: CrossAxisAlignment.stretch,
        children: [
          band('规模', '成本', '利润'),
          grid(
            [
              cell('sales', '销售额', sales.toDouble()),
              cell('verifiedSales', '核销额', verified.toDouble()),
              cell('gmv', 'GMV', gmv.toDouble(), last: true),
            ],
            [
              cell('totalCost', '成本合计', totalCost.toDouble()),
              cell('projectCost', '项目成本', projectCost.toDouble()),
              cell(
                'cost',
                '业务成本',
                businessCost.toDouble(),
                last: !_showOperatingCashFlow(row: entityRow),
              ),
              // 预收净增挂在成本栏尾：它是「钱进来了没」，和成本同属现金侧。
              if (_showOperatingCashFlow(row: entityRow))
                cell('prepaid', '经营性净现金流', prepaid.toDouble(), last: true),
            ],
            [
              cell('profit', '利润', profit.toDouble()),
              cell('netProfit', '净利润', netProfit.toDouble()),
              cell('revenue', '收入', revenue.toDouble()),
              cell('spread', '利差', spread.toDouble()),
              cell('grossMargin', '毛利率', grossMargin.toDouble(), isRate: true),
              cell('rate', 'ROI', rate.toDouble(), isRate: true, last: true),
            ],
          ),
          if (interactive && lighthouseHeroShowsFormulaBar)
            _buildHeroFormulaBar(
              {
                'sales': sales.toDouble(),
                'verifiedSales': verified.toDouble(),
                'gmv': gmv.toDouble(),
                'totalCost': totalCost.toDouble(),
                'projectCost': projectCost.toDouble(),
                'cost': businessCost.toDouble(),
                'prepaid': prepaid.toDouble(),
                'profit': profit.toDouble(),
                'netProfit': netProfit.toDouble(),
                'revenue': revenue.toDouble(),
                'spread': spread.toDouble(),
                'grossMargin': grossMargin.toDouble(),
                'rate': rate.toDouble(),
