      );
    }

    // 净TA：公司级银行流水，没有规模 / 成本 / 利润，换成
    // 资金流入 → 资金流出 → 五类净额，三列 flex 与产品 hero 一致。
    // 这里只做总览：净TA 总额已经是 hero 大数，不再重复；未映射走列表顶部提示条；
    // 五个桶的二级分类在列表里点开看，不占 Hero。
    if (_tab == 'netTa' && entityRow == null) {
      double nt(String key) => totals[key] ?? 0;
      ({String key, String label, double value, bool isRate}) cell(
        String key,
        String label,
      ) => (key: key, label: label, value: nt(key), isRate: false);
      final netTaRail = IntrinsicHeight(
        child: Row(
          crossAxisAlignment: CrossAxisAlignment.stretch,
          children: [
            Expanded(
              flex: lighthouseHeroScaleColumnFlex,
              child: strip(
                sectionKey: 'scale',
                title: '资金流入',
                child: metricGrid([
                  cell('netTaInflow', '流入合计'),
                  cell('netTaOperatingInflow', '经营活动流入'),
                  cell('netTaOtherInflow', '其他流入'),
                ], columns: 1),
              ),
            ),
            const SizedBox(width: lighthouseHeroCardGap),
            Expanded(
              flex: lighthouseHeroCostColumnFlex,
              child: strip(
                sectionKey: 'cost',
                title: '资金流出',
                child: metricGrid([
                  cell('netTaOutflow', '流出合计'),
                  cell('netTaOperatingOutflow', '经营性流出'),
                  cell('netTaFinancingOutflow', '筹资流出'),
                  cell('netTaCostOutflow', '项目+业务成本'),
                ], columns: 2),
              ),
            ),
            const SizedBox(width: lighthouseHeroCardGap),
            Expanded(
              flex: lighthouseHeroResultColumnFlex,
              child: strip(
                sectionKey: 'profit',
                title: '五类净额',
                child: metricGrid([
                  cell('netTaOperating', '经营活动'),
                  cell('netTaFinancing', '筹资活动'),
                  cell('netTaOpCost', '经营成本'),
                  cell('netTaProjectCost', '项目成本'),
                  cell('netTaBizCost', '业务成本'),
                ], columns: 2),
              ),
            ),
          ],
        ),
      );
      return sectionOnly == null
          ? netTaRail
          : (selectedStrip ?? const SizedBox.shrink());
    }

    final rail = Column(
      crossAxisAlignment: CrossAxisAlignment.stretch,
      children: [
        IntrinsicHeight(
          child: Row(
            crossAxisAlignment: CrossAxisAlignment.stretch,
            children: [
              Expanded(
                flex: lighthouseHeroScaleColumnFlex,
                child: strip(
                  sectionKey: 'scale',
                  title: '规模',
                  child: metricGrid(
                    [
                      (key: 'sales', label: '销售额', value: sales, isRate: false),
                      (
                        key: 'verifiedSales',
                        label: '核销额',
                        value: verified,
                        isRate: false,
                      ),
                      (key: 'gmv', label: 'GMV', value: gmv, isRate: false),
                      // 2026-10-30 · 主 Hero：总的经营性净现金流放在规模最后一行。
                      if (heroHasOwnShare &&
                          _showOperatingCashFlow(row: entityRow))
                        (
                          key: 'prepaid',
                          label: '经营性净现金流',
                          value: prepaid,
                          isRate: false,
                        ),
                    ],
                    columns: 1,
                    divider: ledgerPanels ? sectionDivider('scale') : null,
                  ),
                ),
              ),
              const SizedBox(width: lighthouseHeroCardGap),
              Expanded(
                // 成本列不再是「2 列 + 底下垫一张现金流卡」，改成和规模列
                // 一样的一列三行 —— 三列同密度，谁也不用给谁补高度。
                // 列宽跟着从 14 收到和规模一样的 10：一列排就不需要那份额外宽度，
                // 省下来的给利润列（它是唯一真的两列的）。
                flex: lighthouseHeroScaleColumnFlex,
                child: strip(
                  sectionKey: 'cost',
                  title: '成本',
                  child: _withOpCostCell(
                    showOpCost,
                    metricGrid(
                      [
                        (
                          key: 'totalCost',
                          label: '成本合计',
                          value: totalCost,
                          isRate: false,
                        ),
                        (
                          key: 'projectCost',
                          label: '项目成本',
                          value: projectCost,
                          isRate: false,
                        ),
                        (
                          key: 'cost',
                          label: '业务成本',
                          value: businessCost,
                          isRate: false,
                        ),
                      ],
                      columns: 1,
                      divider: ledgerPanels ? sectionDivider('cost') : null,
                    ),
                  ),
                ),
              ),
              const SizedBox(width: lighthouseHeroCardGap),
              Expanded(
                flex: lighthouseHeroResultColumnFlex,
                child: strip(
                  sectionKey: 'profit',
                  title: '利润',
                  child: metricGrid(
                    [
                      (
                        key: 'profit',
                        label: '利润',
                        value: profit,
                        isRate: false,
                      ),
                      (
                        key: 'netProfit',
                        label: '净利润',
                        value: netProfit,
                        isRate: false,
                      ),
                      (
                        key: 'revenue',
                        label: '收入',
                        value: revenue,
                        isRate: false,
                      ),
                      (
                        key: 'spread',
                        label: '利差',
                        value: spread,
                        isRate: false,
                      ),
                      (
                        key: 'grossMargin',
                        label: '毛利率',
                        value: grossMargin,
                        isRate: true,
                      ),
                      (key: 'rate', label: 'ROI', value: rate, isRate: true),
                    ],
                    columns: 2,
                    divider: ledgerPanels ? sectionDivider('profit') : null,
                  ),
                ),
              ),
            ],
          ),
        ),
        // 经营成本点开：就地展开在三块下面，跟账本行点开走势同一种动作。
        if (showOpCost && _opCostOpen) _buildOpCostPanel(),
        // 主 Hero 的经营性净现金流在「规模」里；账本行展开没有大数卡，保留横条。
        if ((whiteBackground || sectionOnly == 'cash') &&
            _showOperatingCashFlow(row: entityRow)) ...[
          const SizedBox(height: lighthouseHeroCardGap),
          cashBanner(),
        ],
        if (interactive && lighthouseHeroShowsFormulaBar)
          _buildHeroFormulaBar(
            {
              'sales': sales.toDouble(),
              'verifiedSales': verified.toDouble(),
              'gmv': gmv.toDouble(),
              'totalCost': totalCost.toDouble(),
              'projectCost': projectCost.toDouble(),
              'cost': businessCost.toDouble(),
              'prepaid': prepaid.toDouble(),
              'profit': profit.toDouble(),
              'netProfit': netProfit.toDouble(),
              'revenue': revenue.toDouble(),
              'spread': spread.toDouble(),
              'grossMargin': grossMargin.toDouble(),
              'rate': rate.toDouble(),
            },
            entityRow: entityRow,
            traceKey: focusKey,
          ),
      ],
    );
    return sectionOnly == null
        ? rail
        : (selectedStrip ?? const SizedBox.shrink());
  }

  /// Hero 底部的口径行 —— 只在追溯时出现一行。
  ///
  /// 右边把数代进去（`140.5 ÷ 113.2 = 124.1%`）比抽象的
  /// 「利润 ÷ 成本合计」有用得多：用户能直接对上眼前的格子，也顺手验了没算错。
  /// 利润那条 substitutes=false，代进去会和格子里的数打架。
  Widget _buildHeroFormulaBar(
    Map<String, double> resolved, {
    Map<String, dynamic>? entityRow,
    String? traceKey,
  }) {
    final traced = entityRow == null ? _heroTraceKey : traceKey;
    if (traced == null) return const SizedBox.shrink();
    final formula = entityRow == null
        ? _heroFormula(traced)
        : _rowHeroFormula(entityRow, traced);
    if (formula == null) return const SizedBox.shrink();

    bool isRateKey(String key) => key == 'grossMargin' || key == 'rate';
    String show(String key) {
      final raw = resolved[key] ?? 0;
      if (isRateKey(key)) return '${raw.toStringAsFixed(2)}%';
      final v = lighthouseHeroMetricDisplayAmount(key, raw);
      return '${_fmtMoney(v)}${_unitMoney(v)}';
    }

    String? substituted;
    if (formula.substitutes && formula.sources.length == 2) {
      final op = switch (formula.sources[1].role) {
        LighthouseHeroFormulaRole.minus => '−',
        LighthouseHeroFormulaRole.denominator => '÷',
        _ => '+',
      };
      substituted =
          '${show(formula.sources[0].key)} $op '
          '${show(formula.sources[1].key)} = ${show(formula.resultKey)}';
    }

    final spans = <InlineSpan>[
      TextSpan(
        text: formula.result,
        style: LhTypography.mono(
          size: 9.5,
          color: DunesColors.resolve(context, _LhPlum.deep),
          weight: FontWeight.w700,
          height: 1.0,
          context: context,
        ),
      ),
      TextSpan(
        text: ' = ',
        style: LhTypography.mono(
          size: 9.5,
          color: DunesColors.resolve(context, _LhPlum.primary),
          weight: FontWeight.w700,
          height: 1.0,
          context: context,
        ),
      ),
    ];
    final tokens = formula.expression.split(' ');
    for (var i = 0; i < tokens.length; i++) {
      final t = tokens[i];
      if (t.isEmpty) continue;
      final op = t.length == 1 && '+−×÷'.contains(t);
      spans.add(
        TextSpan(
          text: t,
          style: LhTypography.mono(
            size: 9.5,
            color: op
                ? DunesColors.resolve(context, _LhPlum.primary)
                : DunesColors.resolve(context, LhColors.ink2),
            weight: op ? FontWeight.w700 : FontWeight.w500,
            height: 1.0,
            context: context,
          ),
        ),
      );
      if (i < tokens.length - 1) spans.add(const TextSpan(text: ' '));
    }

    return Padding(
      padding: const EdgeInsets.only(top: lighthouseHeroCardGap),
      child: Container(
        padding: const EdgeInsets.symmetric(horizontal: 9, vertical: 7),
        decoration: BoxDecoration(
          color: DunesColors.resolve(
            context,
            _LhPlum.mist,
            role: DunesColorRole.surface,
          ),
          border: Border.all(
            color: DunesColors.resolve(
              context,
              _LhPlum.soft,
              role: DunesColorRole.border,
            ).withAlpha(120),
            width: 0.8,
          ),
          borderRadius: BorderRadius.circular(lighthouseHeroCardRadius - 3),
        ),
        child: Row(
          children: [
            Flexible(
              child: LhScrollRichText(
                text: TextSpan(children: spans),
                maxLines: 1,
                overflow: TextOverflow.ellipsis,
              ),
            ),
            const SizedBox(width: 10),
            Text(
              substituted ?? '口径式 · 不代数',
              maxLines: 1,
              overflow: TextOverflow.ellipsis,
              style: _tabular(
                LhTypography.mono(
                  size: 9.5,
                  color: DunesColors.resolve(context, LhColors.mute2),
                  weight: FontWeight.w500,
                  height: 1.0,
                  context: context,
                ),
              ),
            ),
          ],
        ),
      ),
    );
  }

  /// Stat cell —— 左对齐 · 单语标签 · 墨色数字 · 环比收尾。
  /// 点整格：顶部走势切到这一项，同时打开口径式（有公式的格子带 →）。
  /// 迷你 sparkline 只在有数据时渲染，无数据不占位 —— 旧版恒占 14px，
  /// 满屏空白小图正是「看着不清晰」的来源之一。
  /// 利润那一组（利润 / 净利润 / 收入 / 利差 / 毛利率 / ROI）统一：正数红、负数绿
  /// （2026-10-26，原来只有「利润」一格这样上色）。
  static const Set<String> _kProfitToneKeys = {
    'profit',
    'netProfit',
    'revenue',
    'spread',
    'grossMargin',
    'rate',
  };

  Color _grossProfitValueColor(String key, double value, Color fallback) {
    if (!_kProfitToneKeys.contains(key)) return fallback;
    if (value > 0) return DunesColors.resolve(context, LhColors.neg);
    if (value < 0) return DunesColors.resolve(context, LhColors.pos);
    return fallback;
  }

  Widget _statCell({
    required String keyId,
    required String label,
    required double value,
    required bool isRate,
    bool flat = false,
    bool flatLast = false,
    Map<String, dynamic>? entityRow,
    bool interactive = true,
    String? focusKey,
    String? traceKey,
    void Function(({String? focus, String? trace}))? onMetricActivate,
  }) {
    if (keyId == 'prepaid' && !_showOperatingCashFlow(row: entityRow)) {
      return const SizedBox.shrink();
    }
    final activeKey = focusKey ?? _expandedTrendKey;
    final isActive =
        interactive &&
        activeKey != null &&
        lighthouseLedgerMetricKeysMatch(activeKey, keyId);
    // 算式追溯：这一格是被点的结果格 / 它的来源格 / 无关格。
    // 账本行传入 onMetricActivate 时不要去动主 Hero 的 _heroTraceKey。
    final traced = interactive
        ? (onMetricActivate != null ? traceKey : (traceKey ?? _heroTraceKey))
        : null;
    final isTraceOpen = traced != null && traced == keyId;
    final traceRole = lighthouseHeroTraceRole(
      traced,
      keyId,
      group: _grossMarginContextGroup,
      product: entityRow == null
          ? _grossMarginContextProduct
          : _rowMarginProduct(entityRow),
      basis: entityRow == null
          ? _grossMarginContextBasis
          : entityRow['grossMarginBasis']?.toString(),
    );
    final isTraceSource = traceRole != null;
    final isTraceDimmed = lighthouseHeroTraceDims(
      traced,
      keyId,
      group: _grossMarginContextGroup,
      product: entityRow == null
          ? _grossMarginContextProduct
          : _rowMarginProduct(entityRow),
      basis: entityRow == null
          ? _grossMarginContextBasis
          : entityRow['grossMarginBasis']?.toString(),
    );
    // 点选某一期时，七格环比也切到该点对前一点，不再挂整段 vs 上月。
    final rawDelta = entityRow == null
        ? (_heroPointIndex != null
              ? _deltaAtHeroPoint(keyId)
              : _deltaForMetric(keyId))
        : _deltaFromEntityRow(entityRow, keyId);
    // 本期显示出来是 0（金额 < 50 元 → 0.00万），却挂着「↑」—— 那是
    // 上期为 0 时后端兜底的 100%，读起来自相矛盾，直接写「—」。
    final nearZero =
        !isRate &&
        (lighthouseHeroMetricPlainNumber(keyId, value) != null
            ? value.abs() < 0.5
            : value.abs() < 50);
    final uncapped = rawDelta != null && rawDelta.isUp && nearZero
        ? null
        : rawDelta;
    // 超过 500% 默认不画环比。基数太小放大出来的几千，跟真涨跌挤在一起。
    final delta =
        uncapped != null &&
            lighthouseDeltaPctShown(uncapped.pct, isRate: isRate)
        ? uncapped
        : null;
    // v15 · 和走势图同一条规则：选中一个指标时，其余格子不消失也不换色，
    //   只降到统一的淡化度（lighthouseHeroContextOpacity）。
    //   图上「非焦点 = 中性淡线」，格子上「非焦点 = 同色淡一档」，
    //   两处是同一种语言，读者不用为每个区域重学一遍。
    final isFocusDimmed =
        interactive && activeKey != null && !isActive && !isTraceSource;
    // 底板是浅的（玻璃压在雾紫星空上），字色一律走墨色那套 ——
    // 白字在这里没有底可压。
    final numberColor = _grossProfitValueColor(
      keyId,
      value,
      DunesColors.resolve(context, LhColors.ink),
    );
    final labelColor = isTraceOpen || isTraceSource
        ? DunesColors.resolve(context, _LhPlum.deep)
        : (isActive
              ? DunesColors.resolve(context, LhColors.ink2)
              : DunesColors.resolve(context, LhColors.mute));
    final unitColor = DunesColors.resolve(context, LhColors.mute);
    // 涨红跌绿只留给越过门槛的那几个，其余走灰 —— 见
    // lighthouseDeltaLoudThreshold：满屏都上色等于谁都没上色。
    // 预收净增的涨跌没有天然的好坏方向；避免负现金流扩大时用绿色暗示改善。
    final deltaColor = keyId == 'prepaid'
        ? DunesColors.resolve(context, LhColors.mute)
        : delta == null
        ? DunesColors.resolve(context, LhColors.mute2)
        : (lighthouseHeroDeltaIsLoud(keyId, delta.pct)
              ? (delta.isUp
                    ? DunesColors.resolve(context, LhColors.neg)
                    : DunesColors.resolve(context, LhColors.pos))
              : DunesColors.resolve(context, LhColors.mute));
    final displayValue = isRate
        ? value
        : lighthouseHeroMetricDisplayAmount(keyId, value);

    // 经营性净现金流覆盖情况：一级读汇总 metrics，账本行读自己那一行。
    // 不用 `cond ? map?['k'] : null`：`?[` 会被解析成另一层三元运算。
    String? prepaidStatus;
    if (keyId == 'prepaid') {
      final src = entityRow ?? _bundle?.metrics;
      prepaidStatus = src?['prepaidStatus']?.toString();
    }
    final prepaidNone = prepaidStatus == 'none';

    Widget plainLabel(String text) => LhScrollText(
      text,
      maxLines: 1,
      overflow: TextOverflow.ellipsis,
      style: lighthouseHeroMetricUsesSansLabel
          ? LhTypography.sans(
              size: lighthouseHeroCellLabelFontSize,
              color: labelColor,
              weight: FontWeight.w500,
              letterSpacing: 0,
              height: 1.1,
              context: context,
            )
          : LhTypography.mono(
              size: lighthouseHeroCellLabelFontSize,
              color: labelColor,
              weight: FontWeight.w600,
              letterSpacing: 0.2,
              height: 1.0,
              context: context,
            ),
    );

    final labelText = keyId == 'grossMargin'
        ? LighthouseGrossMarginLabel(
            formula: _grossMarginFormula(entityRow),
            labelStyle: LhTypography.sans(
              size: lighthouseHeroCellLabelFontSize,
              color: labelColor,
              weight: FontWeight.w500,
              context: context,
            ),
          )
        : LhScrollText(
            label,
            maxLines: 1,
            overflow: TextOverflow.ellipsis,
            style: lighthouseHeroMetricUsesSansLabel
                ? LhTypography.sans(
                    size: lighthouseHeroCellLabelFontSize,
                    color: labelColor,
                    weight: FontWeight.w500,
                    letterSpacing: 0,
                    height: 1.1,
                    context: context,
                  )
                : LhTypography.mono(
                    size: lighthouseHeroCellLabelFontSize,
                    color: labelColor,
                    weight: FontWeight.w600,
                    letterSpacing: 0.2,
                    height: 1.0,
                    context: context,
                  ),
          );

    // 不要 SizedBox(width: infinity)：拍平版三栏包在 IntrinsicHeight 里，
    // 无穷宽会让 intrinsic 算崩，Hero 整段 layout 失败，只剩顶栏白屏。
    // 热区在外层 GestureDetector；栏本身 stretch，标签行会跟着撑满。
    final traceBadge = <Widget>[
        if (traceRole != null) ...[
          const SizedBox(width: 3),
          Container(
            padding: const EdgeInsets.symmetric(horizontal: 3, vertical: 0.5),
            decoration: BoxDecoration(
              color: DunesColors.resolve(
                context,
                _LhPlum.primary,
                role: DunesColorRole.surface,
              ),
              borderRadius: BorderRadius.circular(3),
            ),
            child: Text(
              lighthouseHeroFormulaRoleBadge(traceRole),
              style: LhTypography.mono(
                size: 7,
                color: DunesColors.resolve(context, LhColors.paper),
                weight: FontWeight.w700,
                height: 1.0,
                context: context,
              ),
            ),
          ),
        ],
    ];
    final labelRow = Row(
      children: [
        Flexible(child: labelText),
        // 2026-10 去杂：标签后的「→」撤掉 —— 整格本来就是热区，点开后
        //   这一行铺淡紫、来源格挂角标，「能点 / 点开了」不再靠箭头说。
        ...traceBadge,
      ],
    );

    final numberBlock = _LhAnimatedNumber(
      value: displayValue,
      duration: const Duration(milliseconds: 700),
      // 在走势图上拖着选点时数字要跟着手指走：700ms 的 tween 会变成
      // 一串永远在追赶的中间值，读不到任何一天的真实数。
      immediate: _heroPointIndex != null,
      builder: (context, v) => LhScrollRichText(
        maxLines: 1,
        overflow: TextOverflow.ellipsis,
        text: TextSpan(
          children: [
            TextSpan(
              text: isRate
                  ? v.toStringAsFixed(2)
                  : (lighthouseHeroMetricPlainNumber(keyId, v) ?? _fmtMoney(v)),
              style: LhTypography.number(
                size: lighthouseHeroMetricValueFontSize,
                color: numberColor,
                context: context,
              ),
            ),
            TextSpan(
              text: isRate
                  ? '%'
                  : (lighthouseHeroMetricPlainUnit(keyId) ?? _unitMoney(v)),
              // v23 · 单位与账本摘要格同一档。
              style: LhTypography.sans(
                size: lighthouseLedgerSummaryUnitFontSize,
                color: unitColor,
                weight: FontWeight.w500,
                context: context,
              ),
            ),
          ],
        ),
      ),
    );

    // 资管没算：不显示 0.00万（会被读成真的 0），写「资管未算」；点这格弹原因。
    final Widget valueBlock = prepaidNone
        ? Text(
            '资管未算',
            maxLines: 1,
            softWrap: false,
            style: LhTypography.sans(
              size: lighthouseHeroMetricValueFontSize * 0.62,
              color: DunesColors.resolve(context, LhColors.mute2),
              weight: FontWeight.w700,
              height: 1.25,
              context: context,
            ),
          )
        : numberBlock;

    final deltaText = Text(
      delta == null
          ? '—'
          : '${delta.isUp ? '↑' : '↓'}'
                '${delta.pct.abs().toStringAsFixed(delta.pct.abs() >= 10 ? 0 : 1)}'
                '${isRate ? 'pp' : '%'}',
      style: _tabular(
        LhTypography.mono(
          size: lighthouseHeroCellDeltaFontSize,
          color: deltaColor,
          weight: FontWeight.w600,
          height: 1.0,
          letterSpacing: 0.2,
          context: context,
        ),
      ),
    );

    // 拍平版：两行 —— 标签一行，数字和环比同一行（原型里的 .fc）。
    // 卡片版：三行 —— 格子有边框兜着，纵向铺开更好读。
    final cellBody = flat
        ? Padding(
            padding: const EdgeInsets.only(right: 2),
            child: Column(
              crossAxisAlignment: CrossAxisAlignment.start,
              mainAxisSize: MainAxisSize.min,
              children: [
                labelRow,
                const SizedBox(height: 2),
                LighthouseHeroFlatValueDeltaRow(
                  value: valueBlock,
                  delta: deltaText,
                ),
              ],
            ),
          )
        // 卡片版（2026-10-26）：两行 —— 环比挪到标签行最右，一列格子的涨跌
        //   上下对齐成一竖排，扫一眼就能比；每格省一行，整块矮约四分之一。
        //   放不下时先省略标签，环比保持完整（它才是这一行的信息）。
        //   毛利率的分母（利润 ÷ 核销额 / 销售额）随口径变，必须常显：
        //   挪到数字下面一行，数字仍和同排 ROI 的数字对齐。
        : Padding(
            padding: const EdgeInsets.only(right: 2),
            child: Column(
              crossAxisAlignment: CrossAxisAlignment.stretch,
              mainAxisSize: MainAxisSize.min,
              children: [
                Row(
                  crossAxisAlignment: CrossAxisAlignment.center,
                  children: [
                    Expanded(
                      child: Row(
                        children: [
                          Flexible(
                            child: keyId == 'grossMargin'
                                ? plainLabel('毛利率')
                                : labelText,
                          ),
                          ...traceBadge,
                        ],
                      ),
                    ),
                    const SizedBox(width: 4),
                    deltaText,
                  ],
                ),
                const SizedBox(height: 4),
                Align(alignment: Alignment.centerLeft, child: valueBlock),
                if (keyId == 'grossMargin') ...[
                  const SizedBox(height: 2),
                  Text(
                    _grossMarginFormula(entityRow),
                    maxLines: 1,
                    overflow: TextOverflow.ellipsis,
                    style: LhTypography.sans(
                      size: 9,
                      color: DunesColors.resolve(context, LhColors.mute2),
                      weight: FontWeight.w500,
                      height: 1.1,
                      letterSpacing: 0,
                      context: context,
                    ),
                  ),
                ],
              ],
            ),
          );

    // 拍平版：格子没有边框可点亮，选中就整行铺淡紫 —— 表格里高亮一行的写法。
    // 行与行之间一条发丝线，最后一行不画（栏尾靠留白收）。
    Widget framed = flat
        ? AnimatedContainer(
            duration: const Duration(milliseconds: 140),
            padding: const EdgeInsets.fromLTRB(0, 7, 4, 7),
            decoration: BoxDecoration(
              color: isTraceOpen || isActive
                  ? DunesColors.resolve(
                      context,
                      _LhPlum.mist,
                      role: DunesColorRole.surface,
                    )
                  : Colors.transparent,
              border: Border(
                bottom: BorderSide(
                  color: flatLast
                      ? Colors.transparent
                      : DunesColors.resolve(
                          context,
                          LhColors.line2,
                          role: DunesColorRole.border,
                        ),
                  width: 0.7,
                ),
              ),
            ),
            child: interactive ? IgnorePointer(child: cellBody) : cellBody,
          )
        // 追溯态：来源格描边点亮并挂角标，其余压暗。
        // 被点的格子与下方列表账本格同一套「浮起」：白底 + 淡紫细边 + 轻投影，
        // 不再铺淡紫 + 实心紫边。
        // 内边距常驻，只切边框、底色和投影，点亮时格子不会跳。
        : AnimatedContainer(
            duration: const Duration(milliseconds: 160),
            curve: Curves.easeOut,
            // 上下 3、格间距 0：视觉行距仍是 6，但两格之间不再有 2px 点不中的缝，
            // 每格热区上下各多 1px。
            padding: const EdgeInsets.fromLTRB(4, 3, 2, 3),
            decoration: BoxDecoration(
              color: isTraceOpen || isActive
                  ? DunesColors.resolve(
                      context,
                      Colors.white,
                      role: DunesColorRole.surface,
                    )
                  : (isTraceSource
                        ? DunesColors.resolve(
                            context,
                            LhColors.paper,
                            role: DunesColorRole.surface,
                          )
                        : Colors.transparent),
              border: Border.all(
                color: isTraceOpen || isActive
                    ? DunesColors.resolve(
                        context,
                        _LhPlum.primary,
                        role: DunesColorRole.border,
                      ).withAlpha(46)
                    : (isTraceSource
                          ? DunesColors.resolve(
                              context,
                              _LhPlum.primary,
                              role: DunesColorRole.border,
                            )
                          : Colors.transparent),
                // 宽度常驻 1：边框会挤内容，切粗细格子会跳半像素。
                width: 1,
              ),
              borderRadius: BorderRadius.circular(8),
              boxShadow: isTraceOpen || isActive
                  ? [
                      BoxShadow(
                        color: _LhPlum.deep.withAlpha(28),
                        blurRadius: 6,
                        offset: const Offset(0, 1.5),
                      ),
                    ]
                  : null,
            ),
            // 格子里的标签/数字是会横向滚的（LhScrollText 自带横拖手势）。
            // 一格就那么点宽，手指按下时横向蹭出 slop，横拖就赢了手势竞技场，
            // 外层的 onTap 被取消 —— 表现正是「点了没反应」。
            // 可点态下让内容整体不吃指针：整格只有一个热区，交给外层 GestureDetector。
            child: interactive ? IgnorePointer(child: cellBody) : cellBody,
          );
    if (isTraceDimmed || isFocusDimmed) {
      framed = AnimatedOpacity(
        duration: const Duration(milliseconds: 180),
        opacity: lighthouseHeroContextOpacity,
        child: framed,
      );
    }

    final tile = GestureDetector(
      behavior: HitTestBehavior.opaque,
      onTap: interactive
          ? () {
              LighthouseFeedback.instance.play(LighthouseFeedbackKind.select);
              final next = lighthouseHeroMetricActivateAfterTap(
                activeKey,
                keyId,
              );
              if (onMetricActivate != null) {
                onMetricActivate(next);
                return;
              }
              setState(() {
                _expandedTrendKey = next.focus;
                _heroTraceKey = next.trace;
              });
            }
          : null,
      child: framed,
    );
    return tile;
  }

  Widget _buildPnlButtonGrid(Map<String, double> totals) {
    final verified = totals['verifiedSales'] ?? 0;
    final sales = totals['sales'] ?? 0;
    final anchorValue = _anchor == _LhAnchor.verified && verified > 0
        ? verified
        : sales;
    final anchorLabel = _anchor == _LhAnchor.verified ? '核销规模' : '销售规模';
    final revenue = totals['revenue'] ?? 0;
    final cost = totals['cost'] ?? 0;
    final tax = totals['tax'] ?? 0;
    final totalCost = totals['totalCost'] ?? 0;
    final rate = totals['rate'] ?? 0;

    final spreadRate =
        totals['spreadRate'] ??
        (anchorValue > 0 ? revenue / anchorValue * 100 : 0.0);

    return Column(
      crossAxisAlignment: CrossAxisAlignment.stretch,
      children: [
        // ── Row 1: 利差率 · 收入 · 销售额 ─────────────────────
        IntrinsicHeight(
          child: Row(
            crossAxisAlignment: CrossAxisAlignment.stretch,
            children: [
              Expanded(
                child: _pnlButton(
                  keyId: 'spreadRate',
                  label: '利差率',
                  subLabel: '收入 ÷ $anchorLabel',
                  value: spreadRate,
                  isRate: true,
                  accent: DunesColors.resolve(context, _LhPlum.primary),
                ),
              ),
              Expanded(
                child: _pnlButton(
                  keyId: 'revenue',
                  label: '收入',
                  subLabel: '已核销利差',
                  value: revenue,
                  isRate: false,
                  accent: DunesColors.resolve(context, _LhPlum.primary),
                ),
              ),
              Expanded(
                child: _pnlButton(
                  keyId: 'sales',
                  label: '销售额',
                  subLabel: '销售规模',
                  value: totals['sales'] ?? 0,
                  isRate: false,
                  accent: DunesColors.resolve(context, _LhPlum.primary),
                ),
              ),
            ],
          ),
        ),
        // v9: 22px 呼吸带 (原横 hairline 已弃) —— whitespace 分行
        const SizedBox(height: 22),
        // ── Row 2: 经营成本 · 成本(合计) · 效率(★) ────────────
        IntrinsicHeight(
          child: Row(
            crossAxisAlignment: CrossAxisAlignment.stretch,
            children: [
              Expanded(
                child: _pnlButton(
                  keyId: 'cost',
                  label: '经营成本',
                  subLabel: '业务成本',
                  value: cost,
                  isRate: false,
                  accent: DunesColors.resolve(context, LhColors.pos),
                ),
              ),
              Expanded(
                child: _pnlButton(
                  keyId: 'totalCost',
                  label: '成本',
                  subLabel: '成本合计',
                  value: totalCost,
                  isRate: false,
                  accent: DunesColors.resolve(context, LhColors.pos),
                ),
              ),
              Expanded(
                child: _pnlButton(
                  keyId: 'rate',
                  label: 'ROI ★',
                  subLabel: '利润 ÷ 成本合计',
                  value: rate,
                  isRate: true,
                  accent: DunesColors.resolve(context, _LhPlum.primary),
                ),
              ),
            ],
          ),
        ),
        // v7 内嵌折线图 — 会议原话"点那个数字就能看到日的"
        //   点 pnl button → 下方展开该指标的走势 (不再弹 sheet)
        //   Period 联动: 日/周/月/季/年 单线走势（后端下发，无环比对比线）
        AnimatedSize(
          duration: const Duration(milliseconds: 220),
          curve: Curves.easeOutCubic,
          alignment: Alignment.topCenter,
          child: _expandedTrendKey == null
              ? const SizedBox.shrink()
              : Padding(
                  padding: const EdgeInsets.only(top: 14),
                  child: _buildInlineTrendPanel(_expandedTrendKey!, totals),
                ),
        ),
      ],
    );
  }

  /// Hero 每条指标一张图，视觉与账本总图 `_TrendChart` 同一套。
  /// 项目/业务成本合计之后，再画资管账单三级每一类的走势。
  Widget _buildHeroAllMetricTrendGallery(Map<String, double> totals) {
    final keys = [
      ...lighthouseHeroMetricTrendKeys(),
      if (_detailKey == null)
        ...lighthouseHeroCostBillTrendKeys(_bundle?.metrics?['costBillTypes']),
    ];
    return Column(
      crossAxisAlignment: CrossAxisAlignment.stretch,
      children: [
        for (var i = 0; i < keys.length; i++) ...[
          if (i > 0) const SizedBox(height: 10),
          _buildInlineTrendPanel(keys[i], totals),
        ],
      ],
    );
  }

  /// 内嵌折线图面板。公式 / 恒等式条已关掉。
  Widget _buildInlineTrendPanel(String keyId, Map<String, double> totals) {
    if (lighthouseHeroShowsMetricFormulas) {
      return Column(
        crossAxisAlignment: CrossAxisAlignment.stretch,
        children: [
          if (_LhPnl.isIdentityKey(keyId)) ...[
            _buildPnlIdentityStrip(keyId, totals),
            const SizedBox(height: 10),
          ],
          _buildFormulaPanel(keyId, totals),
          const SizedBox(height: 10),
          _buildInlineTrendChart(keyId, totals),
        ],
      );
    }
    return _buildInlineTrendChart(keyId, totals);
  }

  /// 取值 —— 兼容同一口径的多个 key 名；返回 null = 后端没传这一项。
  double? _formulaValueOf(Map<String, double> totals, String key) {
    switch (key) {
      case 'totalCost':
        return totals['totalCost'] ?? totals['costTotal'];
      case 'cost':
        return totals['cost'] ?? totals['businessCost'];
      default:
        return totals[key];
    }
  }

  bool _isRateKey(String k) => k == 'rate' || k == 'grossMargin';

  String _fmtFormulaValue(String key, double v) =>
      _isRateKey(key) ? '${v.toStringAsFixed(2)}%' : _fmtAmountWithUnit(v);

  /// 利润恒等式条 —— 收入 = 成本合计 + 净利润
  ///
  ///   用加法形式而不是 `净利润 = 收入 − 成本合计`：加法在视觉上是「一块拆成
  ///   两块」，减法是「一块少掉一块」，前者才对得上这三个数的实际关系。
  ///   两种写法等价，减法形式放在脚注里。
  ///
  ///   三格都可点，直接切 _expandedTrendKey，不用退出再点。
  ///   当前展开的那格描边加粗到 1.2px。
  Widget _buildPnlIdentityStrip(String keyId, Map<String, double> totals) {
    final revenueV = _formulaValueOf(totals, 'revenue');
    final costV = _formulaValueOf(totals, 'totalCost');
    final netV = _formulaValueOf(totals, 'netProfit');

    Widget cell({
      required String id,
      required String label,
      required double? value,
      required _LhPnlAccent accent,
      required Color fill,
      required Color edge,
    }) {
      final isActive =
          keyId == id || (id == 'totalCost' && keyId == 'costTotal');
      return Expanded(
        child: GestureDetector(
          behavior: HitTestBehavior.opaque,
          onTap: () => setState(() => _expandedTrendKey = id),
          child: Container(
            padding: const EdgeInsets.fromLTRB(10, 9, 10, 10),
            decoration: BoxDecoration(
              color: DunesColors.resolveNullable(
                context,
                fill,
                role: DunesColorRole.surface,
              ),
              border: Border.all(
                color: isActive ? accent.bar : edge,
                width: isActive ? 1.2 : 0.8,
              ),
            ),
            child: Column(
              crossAxisAlignment: CrossAxisAlignment.start,
              mainAxisSize: MainAxisSize.min,
              children: [
                Container(
                  height: 2,
                  width: 14,
                  color: DunesColors.resolveNullable(
                    context,
                    accent.bar,
                    role: DunesColorRole.surface,
                  ),
                ),
                const SizedBox(height: 6),
                LhScrollText(
                  label,
                  maxLines: 1,
                  overflow: TextOverflow.ellipsis,
                  style: LhTypography.mono(
                    size: 11,
                    color: accent.label,
                    weight: FontWeight.w600,
                    height: 1.0,
                    context: context,
                  ),
                ),
                const SizedBox(height: 5),
                LhScrollRichText(
                  maxLines: 1,
                  overflow: TextOverflow.ellipsis,
                  text: TextSpan(
                    children: [
                      TextSpan(
                        text: value == null ? '—' : _fmtMoney(value),
                        style: LhTypography.number(
                          size: 15,
                          color: accent.number,
                          context: context,
                        ),
                      ),
                      TextSpan(
                        text: value == null ? '' : _unitMoney(value),
                        style: LhTypography.sans(
                          size: 10,
                          color: accent.label,
                          weight: FontWeight.w500,
                          context: context,
                        ),
                      ),
                    ],
                  ),
                ),
              ],
            ),
          ),
        ),
      );
    }

    // IntrinsicHeight + stretch 下，运算符要 Center 包一层才会垂直居中，
    // 否则会被拉到顶端，跟旁边的数字对不齐。
    Widget op(String s) => Padding(
      padding: const EdgeInsets.symmetric(horizontal: 8),
      child: Center(
        child: Text(
          s,
          style: LhTypography.mono(
            size: 15,
            color: DunesColors.resolve(context, LhColors.mute),
            weight: FontWeight.w700,
            context: context,
          ),
        ),
      ),
    );

    return Container(
      padding: const EdgeInsets.fromLTRB(14, 12, 14, 12),
      decoration: BoxDecoration(
        color: DunesColors.resolve(
          context,
          LhColors.paper,
          role: DunesColorRole.surface,
        ),
        border: Border.all(
          color: DunesColors.resolve(
            context,
            LhColors.line,
            role: DunesColorRole.border,
          ),
          width: 0.8,
        ),
      ),
      child: Column(
        crossAxisAlignment: CrossAxisAlignment.start,
        children: [
          Text(
            '利润恒等式',
            style: LhTypography.mono(
              size: 10,
              color: DunesColors.resolve(context, LhColors.mute2),
              weight: FontWeight.w700,
              letterSpacing: 0.6,
              context: context,
            ),
          ),
          const SizedBox(height: 10),
          IntrinsicHeight(
            child: Row(
              crossAxisAlignment: CrossAxisAlignment.stretch,
              children: [
                cell(
                  id: 'revenue',
                  label: '收入',
                  value: revenueV,
                  accent: _LhPnl.revenue,
                  fill: DunesColors.resolve(context, _LhPnl.revenueFill),
                  edge: DunesColors.resolve(context, _LhPnl.revenueEdge),
                ),
                op('='),
                cell(
                  id: 'totalCost',
                  label: '成本合计',
                  value: costV,
                  accent: _LhPnl.cost,
                  fill: DunesColors.resolve(context, _LhPnl.costFill),
                  edge: DunesColors.resolve(context, _LhPnl.costEdge),
                ),
                op('+'),
                cell(
                  id: 'netProfit',
                  label: '净利润',
                  value: netV,
                  accent: _LhPnl.net,
                  fill: DunesColors.resolve(context, _LhPnl.netFill),
                  edge: DunesColors.resolve(context, _LhPnl.netEdge),
