    );
  }

  Widget _buildFormulaPanel(String keyId, Map<String, double> totals) {
    final label = _kHeroMetricLabel[keyId] ?? keyId;
    final def = _kHeroFormula[keyId];
    final shown = _formulaValueOf(totals, keyId);

    // 代入实数算一遍，用于校验。任一项缺数就不校验（算不出来 ≠ 算错）。
    double? expected;
    if (def != null) {
      final vals = <double>[];
      var complete = true;
      for (final t in def.terms) {
        final v =
            _kHeroFormula.containsKey(t) || _kHeroMetricLabel.containsKey(t)
            ? _formulaValueOf(totals, t)
            : null;
        if (v == null) {
          complete = false;
          break;
        }
        vals.add(v);
      }
      if (complete && vals.isNotEmpty) {
        switch (def.op) {
          case '+':
            expected = vals.reduce((a, b) => a + b);
          case '−':
            expected = vals.reduce((a, b) => a - b);
          case '÷':
            expected = vals[1] == 0 ? null : vals[0] / vals[1] * 100;
        }
      }
    }

    // 容差 = 展示精度的一半。金额显示到 0.01万 → 50 元；比率显示到 0.01% → 0.005pp。
    // 不设容差的话，浮点和四舍五入会让整屏都是黄条。
    final tol = _isRateKey(keyId) ? 0.005 : _kRoiAnchorMinYuan;
    final mismatch =
        expected != null && shown != null && (expected - shown).abs() > tol;

    Widget termRow(String t) {
      final isMetric = _kHeroMetricLabel.containsKey(t);
      final v = isMetric ? _formulaValueOf(totals, t) : null;
      final name = isMetric ? (_kHeroMetricLabel[t] ?? t) : t;
      final row = Padding(
        padding: const EdgeInsets.symmetric(vertical: 5),
        child: Row(
          children: [
            Text(
              name,
              style:
                  LhTypography.mono(
                    size: 11.5,
                    color: isMetric
                        ? DunesColors.resolve(context, _LhPlum.primary)
                        : DunesColors.resolve(context, LhColors.ink2),
                    weight: FontWeight.w600,
                    context: context,
                  ).copyWith(
                    // 虚线下划线 = 可再点进去；纯文本项没有下钻
                    decoration: isMetric ? TextDecoration.underline : null,
                    decorationStyle: TextDecorationStyle.dashed,
                    decorationColor: DunesColors.resolve(
                      context,
                      _LhPlum.primary,
                    ).withAlpha(110),
                  ),
            ),
            const Spacer(),
            Text(
              v == null ? '待接入' : _fmtFormulaValue(t, v),
              style: LhTypography.mono(
                size: 11.5,
                color: v == null
                    ? DunesColors.resolve(context, LhColors.mute2)
                    : DunesColors.resolve(context, LhColors.ink),
                weight: FontWeight.w600,
                context: context,
              ),
            ),
          ],
        ),
      );
      if (!isMetric) return row;
      return GestureDetector(
        behavior: HitTestBehavior.opaque,
        onTap: () => setState(() => _expandedTrendKey = t),
        child: row,
      );
    }

    final usedBy = _kHeroUsedBy[keyId] ?? const <String>[];

    return Container(
      padding: const EdgeInsets.fromLTRB(14, 12, 14, 12),
      decoration: BoxDecoration(
        color: DunesColors.resolve(
          context,
          LhColors.paper,
          role: DunesColorRole.surface,
        ),
        border: Border.all(
          color: DunesColors.resolve(
            context,
            LhColors.line,
            role: DunesColorRole.border,
          ),
          width: 0.8,
        ),
      ),
      child: Column(
        crossAxisAlignment: CrossAxisAlignment.start,
        children: [
          Row(
            children: [
              Text(
                'FORMULA',
                style: LhTypography.mono(
                  size: 8.5,
                  color: DunesColors.resolve(context, LhColors.copper),
                  weight: FontWeight.w800,
                  letterSpacing: 1.4,
                  context: context,
                ),
              ),
              const Spacer(),
              Text(
                label,
                style: LhTypography.mono(
                  size: 8.5,
                  color: DunesColors.resolve(context, LhColors.mute2),
                  weight: FontWeight.w700,
                  letterSpacing: 0.6,
                  context: context,
                ),
              ),
            ],
          ),
          const SizedBox(height: 10),
          if (def == null)
            Text(
              '后端直接传，没有推导公式。',
              style: LhTypography.mono(
                size: 11.5,
                color: DunesColors.resolve(context, LhColors.mute),
                weight: FontWeight.w600,
                context: context,
              ),
            )
          else ...[
            // 符号式，一眼看清结构
            Text(
              def.terms
                  .map((t) => _kHeroMetricLabel[t] ?? t)
                  .join('  ${def.op}  '),
              style: LhTypography.mono(
                size: 12,
                color: DunesColors.resolve(context, LhColors.ink2),
                weight: FontWeight.w700,
                letterSpacing: 0.3,
                context: context,
              ),
            ),
            const SizedBox(height: 8),
            Container(
              height: 0.8,
              color: DunesColors.resolve(
                context,
                LhColors.line,
                role: DunesColorRole.surface,
              ),
            ),
            for (final t in def.terms) termRow(t),
            if (mismatch) ...[
              Container(
                height: 0.8,
                color: DunesColors.resolve(
                  context,
                  LhColors.line,
                  role: DunesColorRole.surface,
                ),
              ),
              Padding(
                padding: const EdgeInsets.only(top: 9),
                child: Row(
                  crossAxisAlignment: CrossAxisAlignment.start,
                  children: [
                    Icon(
                      Icons.error_outline_rounded,
                      size: 13,
                      color: DunesColors.resolve(context, LhColors.copper),
                    ),
                    const SizedBox(width: 6),
                    Expanded(
                      child: Text(
                        '按公式应为 ${_fmtFormulaValue(keyId, expected)}，'
                        '当前显示 ${_fmtFormulaValue(keyId, shown!)}，对不上。',
                        style: LhTypography.mono(
                          size: 10.5,
                          color: DunesColors.resolve(context, LhColors.copper),
                          weight: FontWeight.w600,
                          height: 1.5,
                          context: context,
                        ),
                      ),
                    ),
                  ],
                ),
              ),
            ],
          ],
          if (usedBy.isNotEmpty) ...[
            const SizedBox(height: 10),
            Container(
              height: 0.8,
              color: DunesColors.resolve(
                context,
                LhColors.line,
                role: DunesColorRole.surface,
              ),
            ),
            Padding(
              padding: const EdgeInsets.only(top: 9),
              child: Row(
                children: [
                  Text(
                    '谁在用它',
                    style: LhTypography.mono(
                      size: 10,
                      color: DunesColors.resolve(context, LhColors.mute2),
                      weight: FontWeight.w700,
                      letterSpacing: 0.6,
                      context: context,
                    ),
                  ),
                  const SizedBox(width: 10),
                  for (final u in usedBy)
                    GestureDetector(
                      behavior: HitTestBehavior.opaque,
                      onTap: () => setState(() => _expandedTrendKey = u),
                      child: Container(
                        margin: const EdgeInsets.only(right: 6),
                        padding: const EdgeInsets.symmetric(
                          horizontal: 8,
                          vertical: 3,
                        ),
                        decoration: BoxDecoration(
                          border: Border.all(
                            color: DunesColors.resolve(
                              context,
                              LhColors.line,
                              role: DunesColorRole.border,
                            ),
                            width: 0.8,
                          ),
                        ),
                        child: Text(
                          _kHeroMetricLabel[u] ?? u,
                          style: LhTypography.mono(
                            size: 10.5,
                            color: DunesColors.resolve(
                              context,
                              _LhPlum.primary,
                            ),
                            weight: FontWeight.w600,
                            context: context,
                          ),
                        ),
                      ),
                    ),
                ],
              ),
            ),
          ],
        ],
      ),
    );
  }

