  _TrendChart? _heroMetricSoloTrendChart(
    String metricKey,
    Map<String, double> totals, {
    bool fitHeight = false,
    double chartHeight = 76,
    bool showHeader = false,
    bool showScrubHint = true,
  }) {
    // 银行余额：主 Hero 总览图里已是 stock 槽。单指标展开也走同一条序列/标签，
    // 不要落到默认 scale 槽——那会画成流量线，和左侧迷你走势不是一回事。
    if (metricKey == 'netTaBankBalance') {
      final bankValues = _normalizeTrendSeriesForChart(
        _netTABankBalanceSeries(),
      );
      if (bankValues.length < 2) return null;
      final bankLabels = _netTABankBalanceSeriesLabels();
      final labels = bankLabels.length == bankValues.length
          ? bankLabels
          : _heroTrendLabels(bankValues.length);
      final period =
          totals['netTaBankBalance'] ??
          (_bundle?.metrics['netTaBankBalance'] as num?)?.toDouble() ??
          bankValues.last;
      final bankChange = _netTABankBalanceChange();
      return _TrendChart(
        key: const ValueKey('hero-swap-netTaBankBalance'),
        onSelectedIndexChanged: _onHeroPointSelected,
        lastPointIsPeriod: _heroLastPointIsPeriod,
        selectedIndex: _heroPointIndex,
        suppressPointMom: lighthouseHeroSuppressPointMom,
        labels: labels,
        revenue: const <double>[],
        cost: const <double>[],
        profit: const <double>[],
        stock: bankValues,
        stockLabel: '银行余额',
        periodStock: period,
        periodStockDeltaPct: bankChange?.pct,
        unsignedSlots: const {'stock'},
        partialPeriod: _periodInProgress,
        rangeLabel: _heroTrendRangeLabel(labels),
        title: _heroTrendTitle(),
        showHeader: showHeader,
        showScrubHint: showScrubHint,
        fitHeight: fitHeight,
        chartHeight: chartHeight,
        soloKey: 'stock',
      );
    }
    var series = _normalizeTrendSeriesForChart(_seriesForMetric(metricKey));
    if (metricKey == 'projectCost' && _detailKey == null) {
      final lines = lighthouseCostBillChartLines(
        typesRaw: _bundle?.metrics?['costBillTypes'],
        seriesRaw: _heroSeriesMetrics['costBillTypeSeries'],
        category: 'PROJECT_COST',
      );
      if (lines.isNotEmpty) {
        return _heroCostBillTrendChart(
          lines,
          fitHeight: fitHeight,
          chartHeight: chartHeight,
          showHeader: showHeader,
          showScrubHint: showScrubHint,
        );
      }
    }
    if (series.length < 2) return null;
    final labels = _heroTrendLabels(series.length);
    final period = totals[metricKey] ?? series.last;
    final delta = _deltaForMetric(metricKey)?.pct;
    final isRate = lighthouseHeroTrendChartIsRate(metricKey);
    final label = _heroTrendMetricLabel(metricKey);
    final slot = lighthouseHeroTrendChartSlot(metricKey);
    const empty = <double>[];
    final paceForecast = isRate
        ? null
        : _monthPaceForecast(metricKey, series.last);

    // v15 · 单指标展开也把其余基线留在图上，降成中性上下文线。
    //
    //   这张图本来就不是同一根纵轴（每条序列各自归一化），所以并排画的是
    //   「形状」而不是「高低」—— 正因如此，多留几条参照线不会误导，反而
    //   补回了「这个拐点是它自己的还是全盘的」这个判断。
    //   焦点指标占住它的槽位，剩下三个槽填真实的收入 / 成本合计 / 净利 /
    //   规模；soloKey 交给焦点槽，所以强调色仍然只有一个。
    //
    //   比率指标（ROI / 毛利率）不并线：valueIsRate 是整张图的格式开关，
    //   金额上下文线会被一起按 % 排版，图例读出来是错的。
    final ctxScaleKey = _anchor == _LhAnchor.verified
        ? 'verifiedSales'
        : 'sales';
    List<double> ctx(String slotName, String ctxMetric) {
      if (isRate || slot == slotName) return empty;
      final s = _normalizeTrendSeriesForChart(_seriesForMetric(ctxMetric));
      if (s.length != series.length) return empty;
      for (final v in s) {
        if (v.abs() > 1e-9) return s;
      }
      return empty;
    }

    final ctxRevenue = ctx('revenue', 'revenue');
    final ctxCost = ctx('cost', 'totalCost');
    final ctxProfit = ctx('profit', 'profit');
    final ctxScale = ctx('scale', ctxScaleKey);
    final ctxScaleName = ctxScaleKey == 'verifiedSales' ? '核销规模' : '销售规模';

    return _TrendChart(
      key: ValueKey('hero-swap-$metricKey'),
      grossMarginFormula: metricKey == 'grossMargin'
          ? _grossMarginFormula()
          : null,
      viewportCount: _heroViewportCount,
      initialViewEnd: widget.sharedCard?.viewEnd,
      onViewEndChanged: (value) => _heroViewEnd = value,
      historyCount: _heroHistoryCount,
      historyLoading: _heroHistoryLoading,
      historyHasMore: _heroHistoryHasMore,
      onNeedHistory: _loadHeroHistory,
      onSelectedIndexChanged: _onHeroPointSelected,
      lastPointIsPeriod: _heroLastPointIsPeriod,
      selectedIndex: _heroPointIndex,
      suppressPointMom: lighthouseHeroSuppressPointMom,
      labels: labels,
      revenue: slot == 'revenue' ? series : ctxRevenue,
      cost: slot == 'cost' ? series : ctxCost,
      profit: slot == 'profit' ? series : ctxProfit,
      scale: slot == 'scale' ? series : ctxScale,
      scaleLabel: slot == 'scale' ? label : ctxScaleName,
      revenueLabel: slot == 'revenue' ? label : '收入',
      costLabel: slot == 'cost' ? label : '成本合计',
      profitLabel: slot == 'profit' ? label : '净利润',
      soloKey: slot,
      periodRevenue: slot == 'revenue' ? period : null,
      periodCost: slot == 'cost' ? period : null,
      periodProfit: slot == 'profit' ? period : null,
      periodScale: slot == 'scale' ? period : null,
      periodRevenueDeltaPct: slot == 'revenue' ? delta : null,
      periodCostDeltaPct: slot == 'cost' ? delta : null,
      periodProfitDeltaPct: slot == 'profit' ? delta : null,
      periodScaleDeltaPct: slot == 'scale' ? delta : null,
      scaleForecast: slot == 'scale' ? paceForecast : null,
      paceDays: isRate ? null : _monthPaceDays,
      valueIsRate: isRate,
      partialPeriod: _periodInProgress,
      rangeLabel: _heroTrendRangeLabel(labels),
      title: _heroTrendTitle(),
      showHeader: showHeader,
      showScrubHint: showScrubHint,
      fitHeight: fitHeight,
      chartHeight: chartHeight,
      formulaExpression: lighthouseHeroShowsFormulaBar
          ? _heroFormula(metricKey)?.expression
          : null,
    );
  }

  /// 项目成本拆成资管账单三级：成本 / 规模 / 规模副轴 / 收入 / 利润 五个槽位最多五条。
  _TrendChart? _heroCostBillTrendChart(
    List<LighthouseCostBillChartLine> lines, {
    required bool fitHeight,
    required double chartHeight,
    required bool showHeader,
    required bool showScrubHint,
  }) {
    List<double> at(int i) {
      if (i >= lines.length) return const <double>[];
      return _normalizeTrendSeriesForChart(lines[i].values);
    }

    String lab(int i) => i < lines.length ? lines[i].label : '';
    double? periodOf(int i) {
      if (i >= lines.length || lines[i].values.isEmpty) return null;
      return lines[i].values.last;
    }

    final n = [
      for (final line in lines) line.values.length,
    ].fold<int>(0, (a, b) => a > b ? a : b);
    if (n < 2) return null;
    final labels = _heroTrendLabels(n);
    return _TrendChart(
      key: const ValueKey('hero-swap-projectCost-l3'),
      viewportCount: _heroViewportCount,
      initialViewEnd: widget.sharedCard?.viewEnd,
      onViewEndChanged: (value) => _heroViewEnd = value,
      historyCount: _heroHistoryCount,
      historyLoading: _heroHistoryLoading,
      historyHasMore: _heroHistoryHasMore,
      onNeedHistory: _loadHeroHistory,
      onSelectedIndexChanged: _onHeroPointSelected,
      lastPointIsPeriod: _heroLastPointIsPeriod,
      selectedIndex: _heroPointIndex,
      suppressPointMom: lighthouseHeroSuppressPointMom,
      labels: labels,
      cost: at(0),
      costLabel: lab(0),
      periodCost: periodOf(0),
      scale: at(1),
      scaleLabel: lab(1),
      periodScale: periodOf(1),
      scaleAlt: at(2),
      scaleAltLabel: lab(2),
      periodScaleAlt: periodOf(2),
      revenue: at(3),
      revenueLabel: lab(3),
      periodRevenue: periodOf(3),
      profit: at(4),
      profitLabel: lab(4),
      periodProfit: periodOf(4),
      periodRevenueDeltaPct: null,
      periodCostDeltaPct: null,
      periodProfitDeltaPct: null,
      periodScaleDeltaPct: null,
      scaleForecast: null,
      valueIsRate: false,
      partialPeriod: _periodInProgress,
      rangeLabel: _heroTrendRangeLabel(labels),
      title: _heroTrendTitle(),
      showHeader: showHeader,
      showScrubHint: showScrubHint,
      fitHeight: fitHeight,
      chartHeight: chartHeight,
    );
  }

  Future<void> _retryCurrentHeroTrend() async {
    final type = _detailType;
    final key = _detailKey;
    if (type != null && key != null) {
      _detailLoadedFor.remove('$type:$key');
      await _loadDetail(type, key);
      return;
    }
    await _reloadHeroSummary();
  }

  /// 单个 P&L 单元 — v2.5 编辑体简洁大气版
  ///   老版: paper 底 + 左侧 accent bar + 4 边 hairline，78px 固定高度，形似 6 个方格
  ///   新版: 无 chrome，纯 typography。方格 chrome 靠外层 hairline table (垂直/水平 hairline) 承担
  ///        展开态用 4px 深紫圆点标数字前，accent 参数继续接收供未来语义扩展但不驱动填色
  static const double _pnlCellHeight = 78;

  // ═════════════════════════════════════════════════════════════════════
  // _pnlButton — v9「editorial float」
  //
  // 设计目标:「简单又高级」——
  //   ✕ 掉: 列/行 hairline divider (spreadsheet 感)
  //   ✕ 掉: 数字 + 环比同行挤 (信息密度过高)
  //   ✕ 掉: FittedBox 缩放 (相邻格数字大小抖动, 破坏节奏)
  //   ✕ 掉: 展开态 4px 紫圆点 chrome (装饰性 tell)
  //
  //   ✓ 用: 三行编辑体堆叠
  //          [Label]   ← mono w700, 展开态从 mute2 → primary
  //          [Number Unit]  ← sans w700 固定 15px, 全格一致
  //          [Δ %]     ← mono w600, 独占一行, 更好扫
  //   ✓ 用: 生 whitespace 承担分栏/分行 (Expanded + SizedBox)
  //   ✓ 用: label 颜色变化承担 expanded state (无额外 chrome)
  //
  // 保留:
  //   - 点整格 → 切 _expandedTrendKey (下方折线面板联动)
  //   - _LhAnimatedNumber 数字过渡
  //   - badge 徽标位 (供后续 supply/channel P&L 复用)
  // ═════════════════════════════════════════════════════════════════════
  Widget _pnlButton({
    required String keyId,
    required String label,
    required String subLabel,
    required double value,
    required bool isRate,
    required Color accent,
    Color? valueColor,
    String? badge,
  }) {
    final fg = valueColor ?? DunesColors.resolve(context, LhColors.ink);
    final unitColor = isRate && valueColor != null
        ? valueColor!
        : DunesColors.resolve(context, LhColors.ink2);
    final rawDelta = _deltaForMetric(keyId);
    final deltaUnit = lighthouseHeroMetricIsRate(keyId) ? 'pp' : '%';
    final delta =
        rawDelta != null &&
            lighthouseDeltaPctShown(rawDelta.pct, isRate: deltaUnit == 'pp')
        ? rawDelta
        : null;
    final isExpanded = _expandedTrendKey == keyId;
    final momCompact = delta == null
        ? '—'
        : _fmtSignedMomPct(delta.pct, unit: deltaUnit, digits: 1);
    final momColor = delta == null
        ? DunesColors.resolve(context, LhColors.mute2)
        : (delta.isUp
              ? DunesColors.resolve(context, LhColors.neg)
              : DunesColors.resolve(context, LhColors.pos));

    // v9: label 颜色承担 expanded state 提示 (mute2 → primary)
    final labelColor = isExpanded
        ? DunesColors.resolve(context, _LhPlum.primary)
        : DunesColors.resolve(context, LhColors.ink2);

    return GestureDetector(
      behavior: HitTestBehavior.opaque,
      onTap: () {
        setState(() {
          final next = lighthouseHeroMetricActivateAfterTap(
            _expandedTrendKey,
            keyId,
          );
          _expandedTrendKey = next.focus;
          _heroTraceKey = next.trace;
        });
      },
      child: Padding(
        // v10: 内边距水平/垂直各 4px, 内容整格居中 (crossAxis center)
        padding: const EdgeInsets.symmetric(horizontal: 4, vertical: 4),
        child: Column(
          crossAxisAlignment: CrossAxisAlignment.center,
          mainAxisSize: MainAxisSize.min,
          children: [
            // ── ① Label (居中) ──────────────────────────────────
            Row(
              mainAxisSize: MainAxisSize.min,
              mainAxisAlignment: MainAxisAlignment.center,
              crossAxisAlignment: CrossAxisAlignment.center,
              children: [
                _heroSemanticText(
                  label,
                  baseColor: labelColor,
                  size: 11,
                  baseWeight: FontWeight.w700,
                  termWeight: FontWeight.w700,
                  letterSpacing: 0.4,
                ),
                if (badge != null && badge.isNotEmpty) ...[
                  const SizedBox(width: 4),
                  Container(
                    padding: const EdgeInsets.symmetric(
                      horizontal: 4,
                      vertical: 1,
                    ),
                    decoration: BoxDecoration(
                      color: DunesColors.resolveNullable(
                        context,
                        accent.withAlpha(30),
                        role: DunesColorRole.surface,
                      ),
                      borderRadius: BorderRadius.circular(2),
                    ),
                    child: Text(
                      badge,
                      style: LhTypography.mono(
                        size: 7,
                        color: accent,
                        weight: FontWeight.w700,
                        letterSpacing: 0.4,
                        context: context,
                      ),
                    ),
                  ),
                ],
              ],
            ),
            const SizedBox(height: 10),
            // ── ② 大数字 + 单位 (居中, 15px 固定) ──
            _LhAnimatedNumber(
              value: value,
              builder: (ctx, v) => Row(
                mainAxisSize: MainAxisSize.min,
                mainAxisAlignment: MainAxisAlignment.center,
                crossAxisAlignment: CrossAxisAlignment.baseline,
                textBaseline: TextBaseline.alphabetic,
                children: [
                  Text(
                    isRate ? v.toStringAsFixed(2) : _fmtMoney(v),
                    style: LhTypography.number(
                      size: 15,
                      color: fg,
                      context: ctx,
                    ),
                    maxLines: 1,
                  ),
                  const SizedBox(width: 2),
                  Text(
                    isRate ? '%' : _unitMoney(v),
                    style: LhTypography.sans(
                      size: 9,
                      color: unitColor,
                      weight: FontWeight.w500,
                      context: ctx,
                    ),
                  ),
                ],
              ),
            ),
            const SizedBox(height: 6),
            // ── ③ 环比 (居中) ──────────────────────────────────
            LhScrollText(
              momCompact,
              textAlign: TextAlign.center,
              style: LhTypography.mono(
                size: 9.5,
                color: momColor,
                weight: FontWeight.w600,
                letterSpacing: 0.15,
                context: context,
              ),
              maxLines: 1,
              overflow: TextOverflow.ellipsis,
            ),
          ],
        ),
      ),
    );
  }

