  /// 运算符桥: 节点之间的 " × 利差率 X%" / " − 经营成本 Y" 等
  Widget _flowBridge(String s) {
    // 首字符若为运算符 (×/÷/−/+/=), 拆成 kbd 高亮; 剩余保持 mute mono.
    // 让"这一步在做什么"视觉更强 —— 老板看一眼就知道是乘/除/加/减.
    final trimmed = s.trimLeft();
    String? op;
    String rest = trimmed;
    for (final o in const ['×', '÷', '−', '+', '=']) {
      if (trimmed.startsWith(o)) {
        op = o;
        rest = trimmed.substring(o.length).trimLeft();
        break;
      }
    }
    return Padding(
      padding: const EdgeInsets.fromLTRB(14, 5, 0, 5),
      child: Row(
        children: [
          // 渐弱竖线段 (3 节, 从深到浅) — 视觉传达"从上一节点流下来"
          Column(
            mainAxisSize: MainAxisSize.min,
            children: [
              Container(
                width: 2,
                height: 5,
                color: DunesColors.resolve(
                  context,
                  _LhPlum.primary,
                  role: DunesColorRole.surface,
                ).withAlpha(160),
              ),
              const SizedBox(height: 1),
              Container(
                width: 2,
                height: 4,
                color: DunesColors.resolve(
                  context,
                  _LhPlum.primary,
                  role: DunesColorRole.surface,
                ).withAlpha(96),
              ),
              const SizedBox(height: 1),
              Container(
                width: 2,
                height: 3,
                color: DunesColors.resolve(
                  context,
                  _LhPlum.primary,
                  role: DunesColorRole.surface,
                ).withAlpha(40),
              ),
            ],
          ),
          const SizedBox(width: 10),
          if (op != null) ...[
            // 运算符 kbd 徽章
            Container(
              padding: const EdgeInsets.symmetric(
                horizontal: 4.5,
                vertical: 0.5,
              ),
              decoration: BoxDecoration(
                color: DunesColors.resolve(
                  context,
                  _LhPlum.soft,
                  role: DunesColorRole.surface,
                ),
                border: Border.all(
                  color: DunesColors.resolve(
                    context,
                    _LhPlum.primary,
                    role: DunesColorRole.border,
                  ).withAlpha(90),
                  width: 0.6,
                ),
                borderRadius: BorderRadius.circular(2.5),
              ),
              child: Text(
                op,
                style: LhTypography.mono(
                  size: 10.5,
                  color: DunesColors.resolve(context, _LhPlum.primary),
                  weight: FontWeight.w800,
                  context: context,
                ),
              ),
            ),
            const SizedBox(width: 7),
          ],
          Expanded(
            child: LhScrollText(
              rest,
              style: LhTypography.mono(
                size: 10,
                color: DunesColors.resolve(context, LhColors.mute),
                weight: FontWeight.w500,
                letterSpacing: 0.3,
                context: context,
              ),
              maxLines: 1,
              overflow: TextOverflow.ellipsis,
            ),
          ),
        ],
      ),
    );
  }

  /// 节点卡片: label + subLabel 左侧, 大数字 + 单位/徽标 右侧, 点击弹折线图
  Widget _flowNode({
    required String key,
    required String label,
    required double value,
    required bool isRate,
    required _FlowRole role,
    String? subLabel,
    String? rightBadge,
  }) {
    // ── 视觉规则 (v2: 三种角色视觉真正拉开层次) ──────
    late final Color leftAccent;
    late final Color bg;
    late final double leftWidth;
    switch (role) {
      case _FlowRole.anchor:
        // 起点: 极淡纸色底 + ink 深色 2px 左边框 —— 沉稳、"这是源头"
        leftAccent = DunesColors.resolve(context, LhColors.ink);
        bg = DunesColors.resolve(
          context,
          LhColors.paper,
          role: DunesColorRole.surface,
        ).withAlpha(140);
        leftWidth = 2;
        break;
      case _FlowRole.intermediate:
        // 中间态: copperSoft 底 + copper 2px 左边框 —— 温暖、"派生态"
        leftAccent = DunesColors.resolve(
          context,
          _LhPlum.primary,
        ).withAlpha(160);
        bg = DunesColors.resolve(
          context,
          _LhPlum.soft,
          role: DunesColorRole.surface,
        ).withAlpha(80);
        leftWidth = 2;
        break;
      case _FlowRole.result:
        leftAccent = DunesColors.resolve(context, LhColors.ink);
        bg = DunesColors.resolve(
          context,
          Colors.white,
          role: DunesColorRole.surface,
        );
        leftWidth = 3;
        break;
    }

    // ── 数字文本 ──────────────────────────────
    final numText = isRate ? '${value.toStringAsFixed(2)}%' : _fmtMoney(value);
    final unitText = isRate ? '' : _unitMoney(value);

    return GestureDetector(
      behavior: HitTestBehavior.opaque,
      onTap: () => _showTrendForKey(key, label, isRate),
      child: Container(
        margin: const EdgeInsets.symmetric(vertical: 1),
        padding: const EdgeInsets.fromLTRB(12, 10, 10, 10),
        decoration: BoxDecoration(
          color: DunesColors.resolveNullable(
            context,
            bg,
            role: DunesColorRole.surface,
          ),
          border: Border(
            left: BorderSide(
              color: DunesColors.resolve(
                context,
                leftAccent,
                role: DunesColorRole.border,
              ),
              width: leftWidth,
            ),
            top: BorderSide(
              color: DunesColors.resolve(
                context,
                LhColors.line2,
                role: DunesColorRole.border,
              ),
              width: 0.5,
            ),
            right: BorderSide(
              color: DunesColors.resolve(
                context,
                LhColors.line2,
                role: DunesColorRole.border,
              ),
              width: 0.5,
            ),
            bottom: BorderSide(
              color: DunesColors.resolve(
                context,
                LhColors.line2,
                role: DunesColorRole.border,
              ),
              width: 0.5,
            ),
          ),
        ),
        child: Row(
          crossAxisAlignment: CrossAxisAlignment.center,
          children: [
            // ── 左侧: label + subLabel ──
            Expanded(
              child: Column(
                crossAxisAlignment: CrossAxisAlignment.start,
                mainAxisSize: MainAxisSize.min,
                children: [
                  Row(
                    crossAxisAlignment: CrossAxisAlignment.baseline,
                    textBaseline: TextBaseline.alphabetic,
                    children: [
                      Text(
                        label,
                        style: LhTypography.sans(
                          size: role == _FlowRole.result ? 12 : 11.5,
                          color: DunesColors.resolve(context, LhColors.ink),
                          weight: FontWeight.w700,
                          context: context,
                        ),
                      ),
                      if (subLabel != null) ...[
                        const SizedBox(width: 5),
                        Text(
                          '· $subLabel',
                          style: LhTypography.sans(
                            size: 9,
                            color: DunesColors.resolve(context, LhColors.mute2),
                            weight: FontWeight.w500,
                            context: context,
                          ),
                        ),
                      ],
                    ],
                  ),
                ],
              ),
            ),
            // ── 右侧: 大数字 + 单位 + 估角标 + 展开箭头 ──
            Row(
              mainAxisSize: MainAxisSize.min,
              crossAxisAlignment: CrossAxisAlignment.baseline,
              textBaseline: TextBaseline.alphabetic,
              children: [
                Text(
                  numText,
                  style: LhTypography.number(
                    size: role == _FlowRole.result ? 22 : 20,
                    color: DunesColors.resolve(context, LhColors.ink),
                    context: context,
                  ),
                ),
                if (unitText.isNotEmpty) ...[
                  const SizedBox(width: 2),
                  Text(
                    unitText,
                    style: LhTypography.sans(
                      size: 10,
                      color: DunesColors.resolve(context, LhColors.mute),
                      weight: FontWeight.w500,
                      context: context,
                    ),
                  ),
                ],
              ],
            ),
            if (rightBadge != null) ...[
              const SizedBox(width: 5),
              _estimatedBadge(),
            ],
            const SizedBox(width: 4),
            Icon(
              Icons.chevron_right_rounded,
              size: 13,
              color: DunesColors.resolve(context, LhColors.mute2),
            ),
          ],
        ),
      ),
    );
  }

  /// 核销规模：直读行内 verifiedSales（后端 = verify_amount / woa）。
  /// 兼容旧字段名 `woa`；**禁止**回退到 `sales`，避免与销售额串字段。
  double _verifiedSalesOf(Map<String, dynamic> row) =>
      _metricNum(row, 'verifiedSales') ?? _metricNum(row, 'woa') ?? 0.0;

  /// 中文单位后缀: "" / "万元" / "亿元" —— 复用现有 _unit() 但保证"元"后缀
  String _unitCn(double v) {
    final u = _unit(v);
    return u.endsWith('元') ? u : '${u}元';
  }

  /// 从 key 生成一个临时 _HeroMetric, 弹出折线图 sheet
  /// (会议原话: "点那个数字就能看到日的")
  void _showTrendForKey(String key, String label, bool isRate) {
    // Compute totals from rows (与 _buildHero 保持一致的口径)
    final rows = _currentRows;
    final metrics = _bundle?.metrics ?? const <String, dynamic>{};
    double sumSales = 0,
        sumVerifiedSales = 0,
        sumCost = 0,
        sumProjectCost = 0,
        sumTotalCost = 0,
        sumProfit = 0,
        sumRevenue = 0;
    for (final r in rows) {
      final s = (r['sales'] as num?)?.toDouble() ?? 0;
      final v = _verifiedSalesOf(r);
      sumSales += s;
      sumVerifiedSales += v;
      sumCost += (r['cost'] as num?)?.toDouble() ?? 0;
      sumProjectCost += (r['projectCost'] as num?)?.toDouble() ?? 0;
      sumTotalCost += _rowCostTotal(r);
      sumProfit += (r['profit'] as num?)?.toDouble() ?? 0;
      sumRevenue += (r['revenue'] as num?)?.toDouble() ?? 0;
    }
    final useRowAmounts = lighthouseHeroUseRowAmounts(
      filterActive: _heroFilterActive,
      hasRows: rows.isNotEmpty,
    );
    final metricsMatch = _heroSummaryMatchesGroup;
    final heroSales = _heroAmountFrom(
      metrics: metrics,
      useRowAmounts: useRowAmounts,
      metricsMatch: metricsMatch,
      keys: const ['sales'],
      rowSum: sumSales,
    );
    final heroVerified = _heroAmountFrom(
      metrics: metrics,
      useRowAmounts: useRowAmounts,
      metricsMatch: metricsMatch,
      keys: const ['verifiedSales'],
      rowSum: sumVerifiedSales,
    );
    final heroProfit = _heroAmountFrom(
      metrics: metrics,
      useRowAmounts: useRowAmounts,
      metricsMatch: metricsMatch,
      keys: const ['profit'],
      rowSum: sumProfit,
    );
    final heroRevenue = _heroAmountFrom(
      metrics: metrics,
      useRowAmounts: useRowAmounts,
      metricsMatch: metricsMatch,
      keys: const ['revenue'],
      rowSum: sumRevenue,
    );
    final heroProjectCost = _heroAmountFrom(
      metrics: metrics,
      useRowAmounts: useRowAmounts,
      metricsMatch: metricsMatch,
      keys: const ['projectCost'],
      rowSum: sumProjectCost,
    );
    final heroTotalCost = _heroAmountFrom(
      metrics: metrics,
      useRowAmounts: useRowAmounts,
      metricsMatch: metricsMatch,
      keys: const ['totalCost', 'costTotal'],
      rowSum: sumTotalCost,
    );
    final heroCost = _heroAmountFrom(
      metrics: metrics,
      useRowAmounts: useRowAmounts,
      metricsMatch: metricsMatch,
      keys: const ['cost', 'operatingCost'],
      rowSum: sumCost,
    );
    final anchorTotal = _anchor == _LhAnchor.verified && heroVerified > 0
        ? heroVerified
        : heroSales;
    final roiBase = lighthouseValidRateBase(
      heroTotalCost,
      minimumBase: _kRoiAnchorMinYuan,
    );
    final sumRate = roiBase > 0 ? heroProfit / roiBase * 100 : 0.0;
    final gmKey = lighthouseGrossMarginDenominatorKey(
      product: _grossMarginContextProduct,
      group: _grossMarginContextGroup,
      basis: _grossMarginContextBasis,
    );
    final gmRaw = gmKey == 'gmv'
        ? _heroAmountFrom(
            metrics: metrics,
            useRowAmounts: useRowAmounts,
            metricsMatch: metricsMatch,
            keys: const ['gmv'],
            rowSum: rows.fold<double>(
              0,
              (sum, row) => sum + (_metricNum(row, 'gmv') ?? 0),
            ),
          )
        : gmKey == 'sales'
        ? heroSales
        : heroVerified;
    final grossMarginBase = lighthouseValidRateBase(
      gmRaw,
      minimumBase: _kRoiAnchorMinYuan,
    );
    final grossMargin = grossMarginBase > 0
        ? heroProfit / grossMarginBase * 100
        : 0.0;
    final spreadRate = anchorTotal > 0 ? heroRevenue / anchorTotal * 100 : 0.0;
    final totals = <String, double>{
      'sales': heroSales,
      'verifiedSales': heroVerified,
      'cost': heroCost,
      'projectCost': heroProjectCost,
      'totalCost': heroTotalCost,
      'costTotal': heroTotalCost,
      'businessCost': heroCost,
      'profit': heroProfit,
      'revenue': heroRevenue,
      'grossMargin': grossMargin,
      'spreadRate': spreadRate,
      'rate': sumRate,
    };
    if (!totals.containsKey(key)) {
      totals[key] = rows.isNotEmpty
          ? rows.fold<double>(0, (sum, row) => sum + _rowMetricValue(row, key))
          : ((metrics[key] as num?)?.toDouble() ?? 0.0);
    }
    // 构造临时 _HeroMetric 传给 sheet
    final metric = _HeroMetric(
      key: key,
      label: label,
      isRate: isRate,
      cellColor: DunesColors.resolve(context, _LhPlum.primary),
    );
    _showMetricTrendSheet(metric, totals);
  }

  // ─── 死代码 (已被 _buildLossProfitFlow 替代, 保留供以后参考) ───
  // ignore: unused_element
  Widget _buildHeroGrid(
    List<_HeroMetric> metrics,
    Map<String, double> totals,
    bool filterActive,
  ) {
    return LayoutBuilder(
      builder: (context, constraints) {
        final availW = constraints.maxWidth;
        const cols = 3;
        const colGap = 9.0;
        final cw = (availW - colGap * (cols - 1)) / cols;

        // 把 metrics 按 cols 一组分行
        final rows = <List<_HeroMetric>>[];
        for (int i = 0; i < metrics.length; i += cols) {
          rows.add(metrics.skip(i).take(cols).toList());
        }

        final widgets = <Widget>[];
        for (int r = 0; r < rows.length; r++) {
          final rowMetrics = rows[r];
          final rowCells = <Widget>[];
          for (int c = 0; c < cols; c++) {
            if (c < rowMetrics.length) {
              rowCells.add(
                _buildHeroCell(rowMetrics[c], totals, filterActive, cw),
              );
            } else {
              rowCells.add(SizedBox(width: cw)); // 空位占位，保持列对齐
            }
            if (c < cols - 1) rowCells.add(const SizedBox(width: colGap));
          }
          widgets.add(
            IntrinsicHeight(
              child: Row(
                crossAxisAlignment: CrossAxisAlignment.stretch,
                children: rowCells,
              ),
            ),
          );
          // Hairline divider between rows (editorial 杂志感)
          if (r < rows.length - 1) {
            widgets.add(
              Container(
                height: 1,
                margin: const EdgeInsets.symmetric(vertical: 8),
                color: DunesColors.resolve(
                  context,
                  LhColors.line2,
                  role: DunesColorRole.surface,
                ),
              ),
            );
          }
        }

        return Column(
          crossAxisAlignment: CrossAxisAlignment.start,
          children: widgets,
        );
      },
    );
  }

  /// Hero 小格：未筛选时读 metrics.*V/*U（含 revenue/cost/tax）；筛选后读当前可见行汇总。
  Widget _buildHeroCell(
    _HeroMetric m,
    Map<String, double> totals,
    bool filterActive,
    double width,
  ) {
    final mtr = _bundle?.metrics ?? const <String, dynamic>{};
    final Widget valueRow;

    if (!filterActive && m.key == 'rate') {
      final rate = (mtr['rate'] as num?)?.toDouble();
      valueRow = rate == null
          ? Text(
              '—',
              style: LhTypography.sans(
                size: 16,
                weight: FontWeight.w700,
                color: DunesColors.resolve(context, LhColors.mute2),
                context: context,
              ),
            )
          : _heroRateText(rate);
    } else if (!filterActive && mtr.containsKey('${m.key}V')) {
      final raw = (mtr['${m.key}V'] as num?)?.toDouble() ?? 0;
      final unit = mtr['${m.key}U']?.toString() ?? '';
      valueRow = _heroMetricsAmountText(m.key, raw, unit);
    } else {
      final raw = totals[m.key] ?? 0;
      if (m.isRate) {
        valueRow = raw == 0
            ? Text(
                '—',
                style: LhTypography.sans(
                  size: 16,
                  weight: FontWeight.w700,
                  color: DunesColors.resolve(context, LhColors.mute2),
                  context: context,
                ),
              )
            : _heroRateText(raw);
      } else if (raw == 0 && filterActive) {
        valueRow = Text(
          '—',
          style: LhTypography.sans(
            size: 16,
            weight: FontWeight.w700,
            color: DunesColors.resolve(context, LhColors.mute2),
            context: context,
          ),
        );
      } else {
        valueRow = _heroRowAmountText(m.key, raw);
      }
    }

    // ── 环比 tag（有后端数据才展示） ─────────────────────────────────────────
    final deltaUnit = m.isRate ? 'pp' : '%';
    final rawMom = _deltaForMetric(m.key);
    final d =
        rawMom != null &&
            lighthouseDeltaPctShown(rawMom.pct, isRate: deltaUnit == 'pp')
        ? rawMom
        : null;

    return SizedBox(
      width: width,
      child: _LhScrollSafeTap(
