  List<double> _readMetricSeries(String seriesKey) {
    final mtr = _heroSeriesMetrics;
    final raw = mtr[seriesKey];
    if (raw is! List || raw.isEmpty) return const <double>[];
    return raw
        .map((e) => (e is num) ? e.toDouble() : 0.0)
        .toList(growable: false);
  }

  List<double> _mergeMetricSeries(List<double> a, List<double> b) {
    if (a.isEmpty && b.isEmpty) return const <double>[];
    final n = a.length > b.length ? a.length : b.length;
    return List<double>.generate(n, (i) {
      final left = i < a.length ? a[i] : 0.0;
      final right = i < b.length ? b[i] : 0.0;
      return left + right;
    }, growable: false);
  }

  LhAggregatedRowTrend? _filteredSupplyTrend() {
    if (!_supplyTradeTypeFilterActive || _detailKey != null) return null;
    return lighthouseAggregateRowTrends(
      _currentRows.map(_rowWithResolvedTrend),
    );
  }

  List<double> _anchorMetricSeries() {
    final verified = _readMetricSeries('verifiedSalesSeries');
    final sales = _readMetricSeries('salesSeries');
    final n = verified.isNotEmpty ? verified.length : sales.length;
    if (n == 0) return const <double>[];
    return List<double>.generate(n, (i) {
      final v = i < verified.length ? verified[i] : 0.0;
      if (_anchor == _LhAnchor.verified) return v;
      return i < sales.length ? sales[i] : v;
    }, growable: false);
  }

  /// Hero 走势序列: 从 bundle.metrics 读取后端真实序列；缺则返回空列表。
  /// 二级/三级：只使用当前实体 trend；缺失时留空，禁止跨层串档。
  /// L1：仅当 summary.filterGroup 与当前分类一致时才用序列，避免串档。
  List<double> _seriesForMetric(String key) {
    if (_tab == 'netTa' && _detailKey == null) {
      return switch (key) {
        'netTa' => _readMetricSeries('netTaSeries'),
        'netTaOperating' => _readMetricSeries('netTaOperatingSeries'),
        'netTaFinancing' => _readMetricSeries('netTaFinancingSeries'),
        'netTaOpCost' => _readMetricSeries('netTaOpCostSeries'),
        'netTaProjectCost' => _readMetricSeries('netTaProjectCostSeries'),
        'netTaBizCost' => _readMetricSeries('netTaBizCostSeries'),
        'netTaProjectBiz' => _readMetricSeries('netTaProjectBizSeries'),
        'netTaBankBalance' => _netTABankBalanceSeries(),
        _ => _readMetricSeries('${key}Series'),
      };
    }
    if (_detailKey != null) {
      final detail = _currentDetailSummaryForTrend();
      if (detail != null) {
        final t = _resolvedDetailTrend(detail);
        if (t != null) {
          final fromEntity = _seriesFromTrendMap(
            t,
            key,
            group: detail['group']?.toString(),
          );
          if (fromEntity.isNotEmpty) return fromEntity;
        }
      }
      // L2/L3：没有实体走势就空，不要串一级全量序列。
      return const <double>[];
    }
    if (_supplyTradeTypeFilterActive) {
      final filtered = _filteredSupplyTrend();
      if (filtered != null) {
        final trend = <String, dynamic>{
          'labels': filtered.labels,
          ...filtered.series,
        };
        return _seriesFromTrendMap(trend, key, group: _grossMarginContextGroup);
      }
      // 旧数据若没有行级 trend，保留原总走势作只读兜底，不能让 Hero 空白。
    } else if (_heroLocalOnlyFilterActive) {
      return const <double>[];
    }
    if (!_heroSummaryMatchesGroup) {
      return const <double>[];
    }
    if (key.endsWith('Prev') || key.endsWith('_prev')) {
      final base = key.endsWith('Prev')
          ? key.substring(0, key.length - 4)
          : key.substring(0, key.length - 5);
      final prev = _readMetricSeries('${base}SeriesPrev');
      if (prev.isNotEmpty) return prev;
    }
    if (lighthouseIsCostBillMetric(key)) {
      return lighthouseCostBillTypeSeries(
        _heroSeriesMetrics['costBillTypeSeries'],
        key,
      );
    }
    switch (key) {
      case 'cost':
      case 'businessCost':
        return _readMetricSeries('operatingCostSeries');
      case 'totalCost':
      case 'costTotal':
        return _readMetricSeries('totalCostSeries');
      case 'projectCost':
        return _readMetricSeries('projectCostSeries');
      case 'spreadRate':
        final direct = _readMetricSeries('spreadRateSeries');
        if (direct.isNotEmpty) return direct;
        final revenue = _readMetricSeries('revenueSeries');
        final anchor = _anchorMetricSeries();
        final n = revenue.length < anchor.length
            ? revenue.length
            : anchor.length;
        if (n > 0) {
          return List<double>.generate(n, (i) {
            final a = anchor[i];
            return a > 0 ? revenue[i] / a * 100 : 0.0;
          }, growable: false);
        }
        return const <double>[];
      case 'grossMargin':
        final direct = _readMetricSeries('grossMarginSeries');
        final denominator = lighthouseGrossMarginDenominatorKey(
          product: _grossMarginContextProduct,
          basis: _grossMarginContextBasis,
          group: _grossMarginContextGroup,
        );
        if (direct.isNotEmpty && denominator != 'gmv') return direct;
        final profit = _readMetricSeries('profitSeries');
        return lighthouseGrossMarginSeries(
          profit: profit,
          verifiedSales: _readMetricSeries('verifiedSalesSeries'),
          sales: _readMetricSeries('salesSeries'),
          gmv: _readMetricSeries('gmvSeries'),
          product: _grossMarginContextProduct,
          basis: _grossMarginContextBasis,
          group: _grossMarginContextGroup,
          minimumBase: _kRoiAnchorMinYuan,
        );
      case 'rate':
        final direct = _readMetricSeries('rateSeries');
        // Hero/列表口径：ROI = 利润 ÷ 成本合计；忽略后端旧「÷核销」序列。
        final profit = _readMetricSeries('profitSeries');
        final totalCost = _readMetricSeries('totalCostSeries');
        final n = profit.length < totalCost.length
            ? profit.length
            : totalCost.length;
        if (n > 0) {
          return List<double>.generate(n, (i) {
            final base = totalCost[i];
            final validBase = lighthouseValidRateBase(
              base,
              minimumBase: _kRoiAnchorMinYuan,
            );
            return validBase > 0 ? profit[i] / validBase * 100 : 0.0;
          }, growable: false);
        }
        if (direct.isNotEmpty) return direct;
        return const <double>[];
      case 'netProfit':
        return _readMetricSeries('netProfitSeries');
      default:
        return _readMetricSeries('${key}Series');
    }
  }

  // ═══════════════════════════════════════════════════════════════════════
  // 指标分析页（per-metric drill-down）—— 保留原逻辑做备份, 现在 hero cell
  // 已改为直接弹折线图 sheet, 这个页面暂无入口, 可作为深度分析二级页
  // ═══════════════════════════════════════════════════════════════════════

  /// 指标 → 中文标签
  String _metricPageLabel(String key) => lighthouseHeroMetricLabel(key);

  /// 指标 → 该维度强调色
  Color _metricPageAccent(String key) {
    switch (key) {
      case 'sales':
        return DunesColors.resolve(context, LhColors.ink2);
      case 'profit':
      case 'netProfit':
        return DunesColors.resolve(context, LhColors.neg);
      case 'rate':
        return DunesColors.resolve(context, _LhPlum.primary);
      case 'gmv':
        return DunesColors.resolve(context, LhColors.product);
      case 'revenue':
        return DunesColors.resolve(context, LhColors.cnpc);
      case 'cost':
      case 'projectCost':
      case 'totalCost':
      case 'tax':
        return DunesColors.resolve(context, LhColors.pos);
      default:
        return DunesColors.resolve(context, LhColors.ink);
    }
  }

  /// Hero 数字 — 与外部主 hero (_buildHero) 同 size：LhTypography.number 25pt。
  /// 单位 sans 12pt mute。正负色由数字自身承担（'-' 前缀 + neg 色）。
  Widget _metricPageHeroNumber(String key) {
    final mtr = _bundle?.metrics ?? const <String, dynamic>{};
    const numSize = 25.0;
    const unitSize = 12.0;
    if (key == 'rate') {
      final rate = (mtr['rate'] as num?)?.toDouble();
      if (rate == null) {
        return Text(
          '—',
          style: LhTypography.number(
            size: numSize,
            color: DunesColors.resolve(context, LhColors.mute2),
            context: context,
          ),
        );
      }
      final isNeg = rate < 0;
      return RichText(
        text: TextSpan(
          children: [
            if (isNeg)
              TextSpan(
                text: '-',
                style: LhTypography.number(
                  size: numSize,
                  color: DunesColors.resolve(context, LhColors.pos),
                  context: context,
                ),
              ),
            TextSpan(
              text: rate.abs().toStringAsFixed(2),
              style: LhTypography.number(
                size: numSize,
                color: isNeg
                    ? DunesColors.resolve(context, LhColors.pos)
                    : DunesColors.resolve(context, LhColors.ink),
                context: context,
              ),
            ),
            TextSpan(
              text: ' %',
              style: LhTypography.sans(
                size: unitSize,
                color: DunesColors.resolve(context, LhColors.mute),
                weight: FontWeight.w500,
                context: context,
              ),
            ),
          ],
        ),
      );
    }
    if (mtr.containsKey('${key}V')) {
      final raw = (mtr['${key}V'] as num?)?.toDouble() ?? 0;
      final unit = mtr['${key}U']?.toString() ?? '';
      final isNeg = raw < 0;
      final v = raw.abs().toString().replaceAll(RegExp(r'\.0$'), '');
      return RichText(
        text: TextSpan(
          children: [
            if (isNeg)
              TextSpan(
                text: '-',
                style: LhTypography.number(
                  size: numSize,
                  color: DunesColors.resolve(context, LhColors.pos),
                  context: context,
                ),
              ),
            TextSpan(
              text: v,
              style: LhTypography.number(
                size: numSize,
                color: _grossProfitValueColor(
                  key,
                  raw,
                  isNeg
                      ? DunesColors.resolve(context, LhColors.pos)
                      : DunesColors.resolve(context, LhColors.ink),
                ),
                context: context,
              ),
            ),
            if (unit.isNotEmpty)
              TextSpan(
                text: ' $unit',
                style: LhTypography.sans(
                  size: unitSize,
                  color: DunesColors.resolve(context, LhColors.mute),
                  weight: FontWeight.w500,
                  context: context,
                ),
              ),
          ],
        ),
      );
    }
    // 后端没给 metricV/U → 用前端各行汇总
    double sum = 0;
    for (final r in _bundle?.rowsOf(_tab) ?? const []) {
      sum += (r[key] as num?)?.toDouble() ?? 0;
    }
    final isNeg = sum < 0;
    return RichText(
      text: TextSpan(
        children: [
          if (isNeg)
            TextSpan(
              text: '-',
              style: LhTypography.number(
                size: numSize,
                color: DunesColors.resolve(context, LhColors.pos),
                context: context,
              ),
            ),
          TextSpan(
            text: _fmt(sum.abs()),
            style: LhTypography.number(
              size: numSize,
              color: _grossProfitValueColor(
                key,
                sum,
                isNeg
                    ? DunesColors.resolve(context, LhColors.pos)
                    : DunesColors.resolve(context, LhColors.ink),
              ),
              context: context,
            ),
          ),
          TextSpan(
            text: ' ${_unit(sum.abs())}元',
            style: LhTypography.sans(
              size: unitSize,
              color: DunesColors.resolve(context, LhColors.mute),
              weight: FontWeight.w500,
              context: context,
            ),
          ),
        ],
      ),
    );
  }

  /// 指标 → 英文全大写副名（用于 kicker '利润 · PROFIT'）。
  /// 成本合计等已定中文主名的指标不再挂英文副名。
  String _metricPageLabelEn(String key) {
    switch (_canonicalMetricKey(key)) {
      case 'costTotal':
      case 'projectCost':
      case 'cost':
        return '';
    }
    const en = {
      'sales': 'GROSS SALES',
      'profit': 'PROFIT',
      'netProfit': 'NET PROFIT',
      'gmv': 'TRAFFIC GMV',
      'rate': 'EFFICIENCY ROI',
      'revenue': 'REVENUE',
      'tax': 'TAX COST',
    };
    return en[key] ?? '';
  }

  /// 每个指标在 hero secondary row 里对应的"相关指标"下钻链接（最多 2 个）。
  /// 用户在指标页 hero 卡里点击相关指标 → 横向切换到该指标的 drill-down 页。
  List<String> _metricPageRelatedKeys(String key) {
    const rel = {
      'sales': ['profit', 'rate'],
      'profit': ['netProfit', 'rate'],
      'netProfit': ['profit', 'sales'],
      'rate': ['profit', 'sales'],
      'gmv': ['sales', 'profit'],
      'revenue': ['sales', 'profit'],
      'cost': ['sales', 'profit'],
      'projectCost': ['totalCost', 'sales'],
      'totalCost': ['sales', 'profit'],
      'tax': ['revenue', 'sales'],
    };
    return rel[key] ?? const [];
  }

  /// 某一行在该指标上的值 — 对于 rate 等需要派生的指标做兜底。
  ///
  /// 字段契约（产品 / 供给 / 渠道三端相同，禁止串读）：
  ///   · `sales`         → 只读 `sales`（后端 sales_amount → member_sales）
  ///   · `verifiedSales` → 只读 `verifiedSales` / `woa`（后端 verify_amount）
  ///   · 绝不用 sales 冒充核销，也绝不用 woa 冒充销售
  /// 取值，区分「值为 0」和「压根没这个字段」。
  ///
  /// 返回 null = 该行没有这个口径的数据源，列表上显示「—」而不是 0.00万。
  double? _rowMetricValueOrNull(Map<String, dynamic> r, String key) {
    switch (key) {
      case lighthouseTotalAssetsSortKey:
        return (r[lighthouseTotalAssetsSortKey] as num?)?.toDouble() ??
            (_supplyAssetsHiddenByGroup
                ? null
                : lighthouseFundPoolForRow(r, _fundPoolByProvince)?.totalAssets);
      case 'rate':
        return _roiAnchor(r) == 0
            ? null
            : lighthouseDisplayRatePct(_rowRoiPct(r));
      case 'grossMargin':
        return lighthouseGrossMarginDisplayPct(
          profit: _metricNum(r, 'profit') ?? 0,
          verifiedSales: _verifiedSalesOf(r),
          sales: _salesOf(r),
          gmv: _metricNum(r, 'gmv') ?? 0,
          product: _rowMarginProduct(r),
          basis: r['grossMarginBasis']?.toString(),
          group: r['group']?.toString(),
          minimumVerified: _kRoiAnchorMinYuan,
        );
      case 'costTotal':
        return _rowCostTotal(r);
      case 'sales':
        return (r['sales'] as num?)?.toDouble() ?? 0;
      case 'verifiedSales':
        return _verifiedSalesOf(r);
      case 'prepaid':
        // 资管一行都没算（后端 prepaidStatus = none）：不是 0，是没有数 → 按缺数处理。
        if (r['prepaidStatus']?.toString() == 'none') return null;
        final prepaid = (r['prepaid'] as num?)?.toDouble();
        if (prepaid != null) return prepaid;
        return null;
      case 'netTa':
        return (r['netTa'] as num?)?.toDouble();
      case 'inflow':
      case 'outflow':
        final flow = (r[key] as num?)?.toDouble();
        if (flow == null || flow.abs() < 1e-9) return null;
        return flow;
      case 'sharePct':
        return (r['sharePct'] as num?)?.toDouble();
      case lighthouseLedgerSummaryBlankKey:
        return null;
      default:
        // discount 等字段是 Map，不能按 num 强转
        final raw = r[key];
        if (raw is num) return raw.toDouble();
        return null;
    }
  }

  /// 排序 / 聚合用 —— 缺数当 0，否则排序会崩。展示一律走 OrNull。
  double _rowMetricValue(Map<String, dynamic> r, String key) =>
      _rowMetricValueOrNull(r, key) ?? 0;

  /// 某行的"权重值" — rate 页用 profit 做排序权重（避免低销量小行被高 rate 排前）
  double _rowWeightForMetric(Map<String, dynamic> r, String key) {
    if (key == 'rate') return (r['profit'] as num?)?.toDouble() ?? 0;
    return _rowMetricValue(r, key).abs();
  }

  // ── 每个 dim 下 pager 里显示哪 5 个指标 ─────────────────────────
  List<String> _pagerKeysForDim(String dim) {
    switch (dim) {
      case 'supply':
        return const ['sales', 'profit', 'rate', 'cost', 'spread'];
      case 'channel':
        return const ['sales', 'profit', 'rate', 'gmv', 'cost'];
      case 'people':
      case 'product':
      default:
        return const ['sales', 'profit', 'rate', 'gmv', 'cost'];
    }
  }

  // ── dim → 顶部条 3px 强调色 ─────────────────────────────────────
  Color _dimAccent(String dim) {
    switch (dim) {
      case 'supply':
        return DunesColors.resolve(context, LhColors.sinopec);
      case 'channel':
        return DunesColors.resolve(context, LhColors.carrier);
      case 'people':
        return DunesColors.resolve(context, _LhPlum.primary);
      case 'product':
      default:
        return DunesColors.resolve(context, LhColors.product);
    }
  }

  // ── dim → 顶部条中文标题 ────────────────────────────────────────
  String _dimLabel(String dim) {
    switch (dim) {
      case 'supply':
        return '供给方分析';
      case 'channel':
        return '渠道分析';
      case 'people':
        return '人效分析';
      case 'product':
      default:
        return '产品分析';
    }
  }

  // ── dim → 列表头 kicker 英文名 ──────────────────────────────────
  String _dimLabelEn(String dim) {
    switch (dim) {
      case 'supply':
        return 'SUPPLY';
      case 'channel':
        return 'CHANNEL';
      case 'people':
        return 'PEOPLE';
      case 'product':
      default:
        return 'PRODUCT';
    }
  }

  /// 指标分析页 — 横向 PageView 骨架
  ///   顶部：dim 标题条（静态）
  ///   中间：指标 pager (TabBar 5 tab · 铜色 2px underline)
  ///   底部：TabBarView，每屏一个指标的全量列表
  Widget _buildMetricAnalysisPage(String key) {
    final dim = _isNonLedgerTab ? 'product' : _tab;
    final pagerKeys = _pagerKeysForDim(dim);
    final initialIdx = pagerKeys.indexOf(key).clamp(0, pagerKeys.length - 1);
    final dimAccent = _dimAccent(dim);
    final dimLabel = _dimLabel(dim);
    final dimLabelEn = _dimLabelEn(dim);
    final rowsCount = _bundle?.rowsOf(dim).length ?? 0;

    return DefaultTabController(
      length: pagerKeys.length,
      initialIndex: initialIdx,
      child: ColoredBox(
        color: DunesColors.resolve(
          context,
          Colors.white,
          role: DunesColorRole.surface,
        ),
        child: SafeArea(
          bottom: false,
          child: Column(
            children: [
              _metricPageTopBar(dimLabel, dimAccent),
              _metricPageStrip(pagerKeys),
              Expanded(
                child: TabBarView(
                  physics: const BouncingScrollPhysics(),
                  children: [
                    for (final k in pagerKeys)
                      _metricPageBody(k, dim, dimLabelEn, rowsCount),
                  ],
                ),
              ),
            ],
          ),
        ),
      ),
    );
  }

  /// 顶部条 — dim label + 期间；不随 pager 切页变化
  Widget _metricPageTopBar(String dimLabel, Color dimAccent) {
    return Container(
      padding: const EdgeInsets.fromLTRB(12, 8, 14, 10),
      decoration: BoxDecoration(
        color: DunesColors.resolve(
          context,
          LhColors.paper,
          role: DunesColorRole.surface,
        ),
        border: Border(
          bottom: BorderSide(
            color: DunesColors.resolve(
              context,
              LhColors.line2,
              role: DunesColorRole.border,
            ),
            width: 1,
          ),
        ),
      ),
      child: Row(
        children: [
          _buildEditorialBackButton(onTap: () => setState(_popMetricPage)),
          const SizedBox(width: 8),
          Container(
            width: 3,
            height: 14,
            color: DunesColors.resolveNullable(
              context,
              dimAccent,
              role: DunesColorRole.surface,
            ),
          ),
          const SizedBox(width: 8),
          Text(
            dimLabel,
            style: LhTypography.sans(
              size: 16,
              color: DunesColors.resolve(context, LhColors.ink),
              weight: FontWeight.w700,
              letterSpacing: 0.3,
              context: context,
            ),
          ),
          const SizedBox(width: 8),
          Text(
            _periodInstanceLabel(_period, _periodOffset),
            style: LhTypography.mono(
              size: 10,
              color: DunesColors.resolve(context, LhColors.mute),
              weight: FontWeight.w600,
              letterSpacing: 0.4,
              context: context,
            ),
          ),
          const Spacer(),
          _buildPill(),
        ],
      ),
    );
  }

  /// 指标 pager 条 — 财报级 stat 比较条：每个 tab 展示 label + 数字 + 环比，
  /// 都是真实数据、真实颜色（pos/neg）。选中态靠 2px 铜色 underline，
  /// 不再用"灰色文字 vs 黑色文字"表达选中——避免整条看起来像"底下一排灰指标名"。
  Widget _metricPageStrip(List<String> pagerKeys) {
    return Container(
      color: DunesColors.resolve(
        context,
        LhColors.paper,
        role: DunesColorRole.surface,
      ),
      child: TabBar(
        isScrollable: true,
        tabAlignment: TabAlignment.start,
        padding: const EdgeInsets.symmetric(horizontal: 6),
        labelPadding: const EdgeInsets.symmetric(horizontal: 12),
        indicator: UnderlineTabIndicator(
          borderSide: BorderSide(
            color: DunesColors.resolve(
              context,
              _LhPlum.primary,
              role: DunesColorRole.border,
            ),
            width: 2,
          ),
          insets: const EdgeInsets.symmetric(horizontal: 8),
        ),
        indicatorSize: TabBarIndicatorSize.label,
        dividerColor: DunesColors.resolve(context, LhColors.line2),
        dividerHeight: 1,
        splashFactory: NoSplash.splashFactory,
        overlayColor: WidgetStateProperty.all(Colors.transparent),
        tabs: [
          for (final k in pagerKeys)
            Tab(height: 72, child: _metricPageStripTabContent(k)),
        ],
      ),
    );
  }

  /// 单个 tab 的内容（label 上、数字中、环比下——三行左对齐 stacked）
  Widget _metricPageStripTabContent(String key) {
    final label = _metricPageLabel(key);
    final deltaUnit = lighthouseHeroMetricIsRate(key) ? 'pp' : '%';
    final rawMom = _deltaForMetric(key);
    final delta =
        rawMom != null &&
            lighthouseDeltaPctShown(rawMom.pct, isRate: deltaUnit == 'pp')
        ? rawMom
        : null;

    return Column(
      mainAxisAlignment: MainAxisAlignment.center,
      crossAxisAlignment: CrossAxisAlignment.start,
      mainAxisSize: MainAxisSize.min,
      children: [
        LhScrollText(
          label,
          maxLines: 1,
          overflow: TextOverflow.ellipsis,
          style: LhTypography.sans(
            size: 10,
            height: 1.0,
            color: DunesColors.resolve(
              context,
              LhColors.ink2,
            ), // 不再用 mute2；ink2 = 主文字副色，够黑
            weight: FontWeight.w600,
            letterSpacing: 0.2,
            context: context,
          ),
        ),
        const SizedBox(height: 3),
        _metricPageStripValue(key),
        const SizedBox(height: 2),
        LhScrollText(
          _momText(delta, unit: deltaUnit, prefix: false, up: '▲', down: '▼'),
          maxLines: 1,
          overflow: TextOverflow.ellipsis,
          style: LhTypography.mono(
            size: 8.8,
            height: 1.0,
            color: delta == null
                ? DunesColors.resolve(context, LhColors.mute2)
                : (delta.isUp
                      ? DunesColors.resolve(context, LhColors.neg)
                      : DunesColors.resolve(context, LhColors.pos)),
            weight: FontWeight.w700,
            letterSpacing: 0.2,
            context: context,
          ),
        ),
      ],
    );
  }

  /// tab 里的数字——比 hero masthead 的 25pt 小一档，给 strip 用 14pt。
  /// 直接读 mtr['${key}V']/['${key}U']，跟 _metricPageHeroNumber 同源。
  Widget _metricPageStripValue(String key) {
    final mtr = _bundle?.metrics ?? const <String, dynamic>{};
    const numSize = 14.0;
    const unitSize = 8.5;
    TextStyle numStyle(Color color) => LhTypography.number(
      size: numSize,
      color: color,
      context: context,
    ).copyWith(height: 1.0);
    TextStyle unitStyle() => LhTypography.sans(
      size: unitSize,
      color: DunesColors.resolve(context, LhColors.mute),
      weight: FontWeight.w500,
      context: context,
    ).copyWith(height: 1.0);
    Widget stripRich(List<InlineSpan> spans) => SizedBox(
      height: numSize,
      child: Align(
        alignment: Alignment.centerLeft,
        child: LhScrollRichText(
          maxLines: 1,
          overflow: TextOverflow.ellipsis,
          text: TextSpan(children: spans),
        ),
      ),
    );

    if (key == 'rate') {
      final rate = (mtr['rate'] as num?)?.toDouble();
      if (rate == null) {
        return Text(
          '—',
          style: numStyle(DunesColors.resolve(context, LhColors.mute2)),
        );
      }
      final isNeg = rate < 0;
      return stripRich([
        if (isNeg)
          TextSpan(
            text: '-',
            style: numStyle(DunesColors.resolve(context, LhColors.pos)),
          ),
        TextSpan(
          text: rate.abs().toStringAsFixed(2),
          style: numStyle(
            isNeg
                ? DunesColors.resolve(context, LhColors.pos)
                : DunesColors.resolve(context, LhColors.ink),
          ),
        ),
        TextSpan(text: ' %', style: unitStyle()),
      ]);
    }
    if (mtr.containsKey('${key}V')) {
      final raw = (mtr['${key}V'] as num?)?.toDouble() ?? 0;
      final unit = mtr['${key}U']?.toString() ?? '';
      final isNeg = raw < 0;
      final v = raw.abs().toString().replaceAll(RegExp(r'\.0$'), '');
      return stripRich([
        if (isNeg)
          TextSpan(
            text: '-',
            style: numStyle(DunesColors.resolve(context, LhColors.pos)),
          ),
        TextSpan(
          text: v,
          style: numStyle(
            _grossProfitValueColor(
              key,
              raw,
              isNeg
                  ? DunesColors.resolve(context, LhColors.pos)
                  : DunesColors.resolve(context, LhColors.ink),
            ),
          ),
        ),
        if (unit.isNotEmpty) TextSpan(text: ' $unit', style: unitStyle()),
      ]);
    }
    // fallback：从当前 tab 的 rows 汇总
    double sum = 0;
    for (final r
        in _bundle?.rowsOf(_isNonLedgerTab ? 'product' : _tab) ?? const []) {
      sum += (r[key] as num?)?.toDouble() ?? 0;
    }
    final isNeg = sum < 0;
    return stripRich([
      if (isNeg)
        TextSpan(
          text: '-',
          style: numStyle(DunesColors.resolve(context, LhColors.pos)),
        ),
      TextSpan(
        text: _fmt(sum.abs()),
        style: numStyle(
          _grossProfitValueColor(
            key,
            sum,
            isNeg
                ? DunesColors.resolve(context, LhColors.pos)
                : DunesColors.resolve(context, LhColors.ink),
          ),
        ),
      ),
      TextSpan(text: ' ${_unit(sum.abs())}元', style: unitStyle()),
    ]);
  }

  /// 单个指标页面主体 — ListView (compact masthead + list header + rows)
  Widget _metricPageBody(
    String key,
    String dim,
    String dimLabelEn,
    int rowsCount,
  ) {
    final accent = _metricPageAccent(key);
    final deltaUnit = lighthouseHeroMetricIsRate(key) ? 'pp' : '%';
    final rawMom = _deltaForMetric(key);
    final delta =
        rawMom != null &&
            lighthouseDeltaPctShown(rawMom.pct, isRate: deltaUnit == 'pp')
        ? rawMom
        : null;
    return ListView(
      padding: EdgeInsets.only(bottom: _bottomNavScrollPadding(context)),
      children: [
        _metricPageMasthead(key, accent, delta, deltaUnit),
        Container(
          margin: const EdgeInsets.fromLTRB(14, 0, 14, 18),
          decoration: BoxDecoration(
            color: DunesColors.resolve(
              context,
              Colors.white,
              role: DunesColorRole.surface,
            ),
            border: Border.all(
              color: DunesColors.resolve(
                context,
                LhColors.line2,
                role: DunesColorRole.border,
              ),
              width: 0.5,
            ),
            borderRadius: BorderRadius.circular(14),
            boxShadow: [
              BoxShadow(
                color: LhColors.ink.withAlpha(10),
                blurRadius: 10,
                spreadRadius: -4,
                offset: const Offset(0, 3),
              ),
            ],
          ),
          clipBehavior: Clip.antiAlias,
          child: Column(
            crossAxisAlignment: CrossAxisAlignment.stretch,
            children: [
              _metricPageListHeader(key, dimLabelEn, rowsCount),
              _metricPageFullList(key, dim, accent),
            ],
          ),
        ),
        const SizedBox(height: 32),
      ],
    );
  }

