  /// 全量列表 — 每一行 Direction A 三层结构（主 + 副 + 条形）
  Widget _metricPageFullList(String key, String dim, Color accent) {
    final rows = _bundle?.rowsOf(dim) ?? const [];
    if (rows.isEmpty) {
      return Padding(
        padding: const EdgeInsets.fromLTRB(20, 10, 20, 20),
        child: Text(
          '无数据',
          style: LhTypography.sans(
            size: 11,
            color: DunesColors.resolve(context, LhColors.mute2),
            context: context,
          ),
        ),
      );
    }
    final sorted = List<Map<String, dynamic>>.from(rows)
      ..sort(
        (a, b) =>
            _rowWeightForMetric(b, key).compareTo(_rowWeightForMetric(a, key)),
      );

    // 条形宽度参考：取全量行的 weight 之和；rate 页保留 profit 权重（rate 不能相加）
    double sumWeight = 0;
    for (final r in sorted) {
      sumWeight += _rowWeightForMetric(r, key).abs();
    }
    if (sumWeight == 0) sumWeight = 1;

    return Padding(
      padding: const EdgeInsets.fromLTRB(20, 4, 20, 8),
      child: Column(
        crossAxisAlignment: CrossAxisAlignment.start,
        children: [
          for (int i = 0; i < sorted.length; i++) ...[
            if (i > 0)
              Padding(
                padding: const EdgeInsets.only(left: 30),
                child: Container(
                  height: 1,
                  color: DunesColors.resolve(
                    context,
                    LhColors.line2,
                    role: DunesColorRole.surface,
                  ).withAlpha(90),
                ),
              ),
            _metricPageRow(sorted[i], key, i + 1, sumWeight, accent),
          ],
        ],
      ),
    );
  }

  /// 单行 Direction A 三层：
  ///   主行：排名 (14pt accent) · 名字 (14pt w500) · dot + group · 主数值 (20pt w500)
  ///   副行：关联指标 x2  ·  右端 占/权重 %
  ///   条形：3px flat · 宽度 = 该行 weight / sumWeight
  Widget _metricPageRow(
    Map<String, dynamic> r,
    String key,
    int rank,
    double sumWeight,
    Color accent,
  ) {
    final name = r['name']?.toString() ?? '—';
    final group = r['group']?.toString() ?? '';
    final v = _rowMetricValue(r, key);
    final isRate = key == 'rate';
    final isNeg = v < 0;
    final ratio = (_rowWeightForMetric(r, key).abs() / sumWeight).clamp(
      0.0,
      1.0,
    );
    final groupColor = group.isEmpty
        ? DunesColors.resolve(context, LhColors.mute2)
        : lhGroupColor(group);
    final relatedKeys = _metricPageRelatedKeys(key);
    final sharePct = (ratio * 100).round();
    final shareLabel = isRate ? '权重 $sharePct%' : '占 $sharePct%';

    return Padding(
      padding: const EdgeInsets.symmetric(vertical: 10),
      child: Column(
        crossAxisAlignment: CrossAxisAlignment.start,
        children: [
          // 主行
          Row(
            crossAxisAlignment: CrossAxisAlignment.baseline,
            textBaseline: TextBaseline.alphabetic,
            children: [
              SizedBox(
                width: 22,
                child: Text(
                  rank.toString().padLeft(2, '0'),
                  style: LhTypography.mono(
                    size: 14,
                    color: accent,
                    weight: FontWeight.w500,
                    letterSpacing: 0.2,
                    context: context,
                  ),
                ),
              ),
              const SizedBox(width: 8),
              Flexible(
                child: LhScrollText(
                  name,
                  style: LhTypography.sans(
                    size: 14,
                    color: DunesColors.resolve(context, LhColors.ink),
                    weight: FontWeight.w500,
                    letterSpacing: 0.1,
                    context: context,
                  ),
                  overflow: TextOverflow.ellipsis,
                ),
              ),
              if (group.isNotEmpty) ...[
                const SizedBox(width: 8),
                Container(
                  width: 4,
                  height: 4,
                  decoration: BoxDecoration(
                    color: DunesColors.resolveNullable(
                      context,
                      groupColor,
                      role: DunesColorRole.surface,
                    ),
                    shape: BoxShape.circle,
                  ),
                ),
                const SizedBox(width: 4),
                Text(
                  group,
                  style: LhTypography.mono(
                    size: 11,
                    color: DunesColors.resolve(context, LhColors.mute),
                    weight: FontWeight.w500,
                    letterSpacing: 0.4,
                    context: context,
                  ),
                ),
              ],
              const Spacer(),
              _metricPageRowValue(key, v, isNeg, isRate),
            ],
          ),
          // 副行 — 关联指标 + 右端占/权重 %
          Padding(
            padding: const EdgeInsets.only(left: 30, top: 6),
            child: Row(
              crossAxisAlignment: CrossAxisAlignment.baseline,
              textBaseline: TextBaseline.alphabetic,
              children: [
                if (relatedKeys.isNotEmpty)
                  Flexible(child: _metricPageRelatedRow(r, relatedKeys)),
                const Spacer(),
                Text(
                  shareLabel,
                  style: LhTypography.mono(
                    size: 11,
                    color: DunesColors.resolve(context, LhColors.mute),
                    weight: FontWeight.w500,
                    letterSpacing: 0.2,
                    context: context,
                  ),
                ),
              ],
            ),
          ),
          // 条形 — 3px flat，无 alpha 无圆角
          Padding(
            padding: const EdgeInsets.only(left: 30, top: 7),
            child: Row(
              children: [
                Expanded(
                  flex: (ratio * 1000).round().clamp(1, 1000),
                  child: Container(
                    height: 3,
                    color: isNeg
                        ? DunesColors.resolve(
                            context,
                            LhColors.pos,
                            role: DunesColorRole.surface,
                          )
                        : accent,
                  ),
                ),
                Expanded(
                  flex: (1000 - (ratio * 1000).round()).clamp(0, 1000),
                  child: Container(
                    height: 3,
                    color: DunesColors.resolve(
                      context,
                      LhColors.line2,
                      role: DunesColorRole.surface,
                    ),
                  ),
                ),
              ],
            ),
          ),
        ],
      ),
    );
  }

  /// 主数值：20pt w500 + 11pt mute 单位；rate 页显示 %
  Widget _metricPageRowValue(String key, double v, bool isNeg, bool isRate) {
    if (isRate) {
      return RichText(
        text: TextSpan(
          children: [
            if (isNeg)
              TextSpan(
                text: '-',
                style: LhTypography.number(
                  size: 20,
                  color: DunesColors.resolve(context, LhColors.pos),
                  context: context,
                ),
              ),
            TextSpan(
              text: v.abs().toStringAsFixed(2),
              style: LhTypography.number(
                size: 20,
                color: _grossProfitValueColor(
                  key,
                  v,
                  isNeg
                      ? DunesColors.resolve(context, LhColors.pos)
                      : DunesColors.resolve(context, LhColors.ink),
                ),
                context: context,
              ),
            ),
            TextSpan(
              text: ' %',
              style: LhTypography.sans(
                size: 11,
                color: DunesColors.resolve(context, LhColors.mute),
                weight: FontWeight.w500,
                context: context,
              ),
            ),
          ],
        ),
      );
    }
    return RichText(
      text: TextSpan(
        children: [
          if (isNeg)
            TextSpan(
              text: '-',
              style: LhTypography.number(
                size: 20,
                color: DunesColors.resolve(context, LhColors.pos),
                context: context,
              ),
            ),
          TextSpan(
            text: _fmt(v.abs()),
            style: LhTypography.number(
              size: 20,
              color: _grossProfitValueColor(
                key,
                v,
                isNeg
                    ? DunesColors.resolve(context, LhColors.pos)
                    : DunesColors.resolve(context, LhColors.ink),
              ),
              context: context,
            ),
          ),
          TextSpan(
            text: _unit(v.abs()),
            style: LhTypography.sans(
              size: 11,
              color: DunesColors.resolve(context, LhColors.mute),
              weight: FontWeight.w500,
              context: context,
            ),
          ),
        ],
      ),
    );
  }

  /// 副行 — 关联指标 x2：标签 (11pt mute mono) + 值 (11pt ink w500 number)
  Widget _metricPageRelatedRow(
    Map<String, dynamic> r,
    List<String> relatedKeys,
  ) {
    final spans = <InlineSpan>[];
    for (int i = 0; i < relatedKeys.length; i++) {
      if (i > 0) {
        spans.add(
          TextSpan(
            text: '  ·  ',
            style: LhTypography.mono(
              size: 11,
              color: DunesColors.resolve(context, LhColors.line),
              weight: FontWeight.w500,
              context: context,
            ),
          ),
        );
      }
      final k = relatedKeys[i];
      final label = _metricPageLabel(k);
      final val = _rowMetricValue(r, k);
      final isNeg = val < 0;
      spans.add(
        TextSpan(
          text: '$label ',
          style: LhTypography.mono(
            size: 11,
            color: DunesColors.resolve(context, LhColors.mute),
            weight: FontWeight.w500,
            letterSpacing: 0.2,
            context: context,
          ),
        ),
      );
      if (k == 'rate') {
        if (isNeg) {
          spans.add(
            TextSpan(
              text: '-',
              style: LhTypography.number(
                size: 11,
                color: DunesColors.resolve(context, LhColors.pos),
                context: context,
              ),
            ),
          );
        }
        spans.add(
          TextSpan(
            text: '${val.abs().toStringAsFixed(1)}%',
            style: LhTypography.number(
              size: 11,
              color: isNeg
                  ? DunesColors.resolve(context, LhColors.pos)
                  : DunesColors.resolve(context, LhColors.ink),
              context: context,
            ),
          ),
        );
      } else {
        // 金额保留正负号，不再 abs 后再拼
        spans.add(
          TextSpan(
            text: _fmtAmountWithUnit(val),
            style: LhTypography.number(
              size: 11,
              color: isNeg
                  ? DunesColors.resolve(context, LhColors.pos)
                  : DunesColors.resolve(context, LhColors.ink),
              context: context,
            ),
          ),
        );
      }
    }
    return LhScrollRichText(
      text: TextSpan(children: spans),
      overflow: TextOverflow.ellipsis,
      maxLines: 1,
    );
  }

