    return Padding(
      padding: const EdgeInsets.fromLTRB(14, 12, 12, 4),
      child: Row(
        children: [
          Container(
            width: 22,
            height: 22,
            alignment: Alignment.center,
            decoration: BoxDecoration(
              color: DunesColors.resolve(
                context,
                _LhPlum.primary,
                role: DunesColorRole.surface,
              ),
              borderRadius: BorderRadius.circular(7),
            ),
            child: const Icon(
              Icons.view_list_rounded,
              size: 14,
              color: Colors.white,
            ),
          ),
          const SizedBox(width: 8),
          Text(
            '$label明细',
            style: LhTypography.sans(
              size: 16,
              color: DunesColors.resolve(context, LhColors.ink),
              weight: FontWeight.w700,
              letterSpacing: 0.3,
              height: 1.1,
              context: context,
            ),
          ),
          const SizedBox(width: 8),
          Expanded(
            child: Text(
              n > 0 ? '$n 个 · 按$sortLabel排' : '',
              maxLines: 1,
              overflow: TextOverflow.ellipsis,
              style: LhTypography.sans(
                size: 11,
                color: DunesColors.resolve(context, LhColors.mute2),
                context: context,
              ),
            ),
          ),
          const SizedBox(width: 8),
          Text(
            _selectedRangeLabel,
            style: _tabular(mono(DunesColors.resolve(context, LhColors.mute2))),
          ),
          if (_isCustomRange)
            GestureDetector(
              behavior: HitTestBehavior.opaque,
              onTap: _clearCustomRange,
              child: Padding(
                padding: const EdgeInsets.fromLTRB(8, 4, 0, 4),
                child: Text(
                  '清除',
                  style: mono(DunesColors.resolve(context, _LhPlum.primary)),
                ),
              ),
            )
          else if (_periodOffset != 0)
            GestureDetector(
              behavior: HitTestBehavior.opaque,
              onTap: () => _applyPeriod(offset: 0),
              child: Padding(
                padding: const EdgeInsets.fromLTRB(8, 4, 0, 4),
                child: Text(
                  '回到当前',
                  style: mono(DunesColors.resolve(context, _LhPlum.primary)),
