  }

  Widget _buildTabSegment({bool sticky = false}) {
    // 2026-10-30 · 净TA 归财务侧；业务侧只剩账本维度。
    final bfOk = _bf != null && _bf!.access.value != false;
    final dims = _isFinanceLedger
        ? [
            if (bfOk) {'key': 'bfSubject', 'label': '主体'},
            if (_hasNetTaAccess && !_inTopic) {'key': 'netTa', 'label': '净TA'},
          ]
        : [
            {'key': 'product', 'label': '产品'},
            {'key': 'supply', 'label': '供给方'},
            {'key': 'channel', 'label': '渠道'},
            if (_showsPeopleTab) {'key': 'people', 'label': '人效'},
            if (lighthouseLedgerShowsAnalysisTab)
              {'key': 'analysis', 'label': '分析'},
          ];
    // 供给默认选中中石油；渠道下拉里平安仅置顶，默认仍是「全部」。
    final groups = _categoryOptions(_tab).toList();
    final showGroups =
        !_isFinanceLedger &&
        _tabBarShowsGroups &&
        lighthouseLedgerTabShowsCategoryChips(_tab);
    final showHun = showGroups && (_tab == 'supply' || _tab == 'channel');
    final showTradeType = showGroups && _tab == 'supply';

    // ── ROW 1 · 维度锚点 (biggest) ─────────────────────────────────────
    final dimCells = dims.map((t) {
      final key = t['key']!;
      final label = t['label']!;
      final isOn = key == 'bfSubject' ? _bfSubjectView : _tab == key;
      final canExpand =
          key != 'bfSubject' && lighthouseLedgerTabShowsCategoryChips(key);
      final IconData? trailing;
      if (!isOn) {
        trailing = null;
      } else if (!canExpand) {
        trailing = null;
      } else {
        trailing = showGroups
            ? Icons.expand_less_rounded
            : Icons.expand_more_rounded;
      }
      return _dimTab(
        label: label,
        isOn: isOn,
        trailing: trailing,
        onTap: () {
          if (key == 'bfSubject') {
            if (_tab == 'netTa') {
              setState(() => _financeLedger = true);
              _enterLedgerTab(_bfReturnTab);
            }
            return;
          }
          if (key == 'analysis') {
            if (key == _tab) return;
            _closeDropdown();
            final hadGroup = _groupFilter != '全部';
            setState(() {
              _tab = key;
              _groupFilter = '全部';
              _heroPointIndex = null;
              _tabBarShowsGroups = false;
              _hunFilter = '全部';
              _tradeTypeFilter = '全部';
              if (_sortField == 'netTa') _sortField = 'profit';
              _listLimit = _listPageSize;
              _rowsCacheKey = '';
              _rowsCache = null;
              _closeMetricPage();
              _restoreSharedHeroMetrics();
            });
            if (hadGroup) unawaited(_reloadHeroSummary());
            _loadAnalysisCube();
            return;
          }
          if (key == 'netTa') {
            if (!_hasNetTaAccess) return;
            if (key == _tab) return;
            _closeDropdown();
            setState(() {
              _bfReturnTab = _tab == 'analysis' ? 'product' : _tab;
              _financeLedger = true;
              _tab = key;
              _groupFilter = '全部';
              _heroPointIndex = null;
              _tabBarShowsGroups = false;
              _hunFilter = '全部';
              _tradeTypeFilter = '全部';
              _anomalyFilter = '全部';
              _sortField = 'netTa';
              _listLimit = _listPageSize;
              _rowsCacheKey = '';
              _rowsCache = null;
              _netTaBalanceOpen = false;
              _closeMetricPage();
              _invalidateAiSummary();
              _restoreSharedHeroMetrics();
            });
            unawaited(_loadTab('netTa'));
            return;
          }
          _closeDropdown();
          if (key == _tab) {
            final prevGroup = _groupFilter;
            setState(() {
              if (_tabBarShowsGroups) {
                _tabBarShowsGroups = false;
                _groupFilter = '全部';
                _hunFilter = '全部';
                _tradeTypeFilter = '全部';
              } else {
                _tabBarShowsGroups = true;
                _ensureDefaultGroupFilter();
              }
              _listLimit = _listPageSize;
              _rowsCacheKey = '';
              _rowsCache = null;
              if (_groupFilter == '全部') _restoreSharedHeroMetrics();
              if (prevGroup != _groupFilter) _heroPointIndex = null;
            });
            if (prevGroup != _groupFilter) {
              unawaited(_reloadHeroSummary());
            }
            return;
          }
          final prevGroup = _groupFilter;
          final leavingNetTa = _tab == 'netTa';
          final leavingPeople = _tab == 'people';
          setState(() {
            _tab = key;
            _heroPointIndex = null;
            _tabBarShowsGroups = true; // 切维仍默认展开分类
            if (_sortField == 'netTa') _sortField = 'profit';
            // 标签二默认按总资产排省份；离开供给就回到利润。
            if (key == 'supply' && !_inTopic) {
              _sortField = lighthouseTotalAssetsSortKey;
              _sortDesc = true;
            } else if (_sortField == lighthouseTotalAssetsSortKey) {
              _sortField = 'profit';
            }
            _groupFilter = lighthouseGroupAfterTabSwitch(
              currentGroup: prevGroup,
              nextTabOptions: _categoryOptions(key),
            );
            _ensureDefaultGroupFilter();
            if (key != 'supply' && key != 'channel') _hunFilter = '全部';
            if (key != 'supply') _tradeTypeFilter = '全部';
            _listLimit = _listPageSize;
            _rowsCacheKey = '';
            _rowsCache = null;
            _closeMetricPage();
            _invalidateAiSummary();
            _clearNetTAHeroTransientState();
            if (leavingPeople) {
              _expandedTrendKey = null;
              _heroTraceKey = null;
            }
            // 从净TA回来时 metrics 里主要是 netTa*，必须先换回全量 Hero 快照，
            // 否则 profitSeries 空窗期主图会整块消失。
            if (_groupFilter == '全部' || leavingNetTa) {
              _restoreSharedHeroMetrics();
            }
          });
          unawaited(_reloadHeroSummary());
          _loadTab(key);
        },
      );
    }).toList();

    // ── ROW 2 / ROW 3 · 筛选行 ────────────────────────────────────────
    //   旧版用 Expanded 均分 —— 「能源」和「(未分类)」拿一样宽，宽度不承载
    //   任何信息，而下面的账本恰恰是「列宽由内容最坏情况决定」。这里改成
    //   左对齐 + 内容宽度 + 横滑，跟账本指标区同一种滚动行为。
    //   左侧 mono kicker 是必需的：旧版两行光秃秃排着，用户看不出哪行是
    //   「分类」哪行是「HUN」。kicker 规格 = 账本表头（mono 9 / ls 0.6 / mute2）。
    final hunOpts = _hunOptions
        .map((o) => o['value']?.toString() ?? '')
        .where((v) => v.isNotEmpty && v != '全部')
        .toList();

    // 供给页：HUN / 类型默认收起，「分类」行最右一个小箭头开合。
    // 收起时若 HUN / 类型里选了非「全部」，箭头旁亮一个紫点 —— 筛选还在生效。
    final supplyFoldable =
        _tab == 'supply' &&
        showGroups &&
        groups.isNotEmpty &&
        ((showHun && hunOpts.isNotEmpty) || showTradeType);
    final supplyFolded = supplyFoldable && !_supplyMoreFiltersOpen;
    final supplyHiddenActive = _hunFilter != '全部' || _tradeTypeFilter != '全部';
    Widget moreFiltersToggle() {
      final open = _supplyMoreFiltersOpen;
      return Semantics(
        button: true,
        expanded: open,
        label: open ? '收起 HUN / 类型筛选' : '展开 HUN / 类型筛选',
        child: GestureDetector(
          behavior: HitTestBehavior.opaque,
          onTap: () {
            LighthouseFeedback.instance.play(
              open
                  ? LighthouseFeedbackKind.collapse
                  : LighthouseFeedbackKind.expand,
            );
            setState(() => _supplyMoreFiltersOpen = !open);
          },
          child: SizedBox(
            width: 28,
            height: 24,
            child: Stack(
              alignment: Alignment.center,
              children: [
                AnimatedRotation(
                  turns: open ? 0.5 : 0.0,
                  duration: const Duration(milliseconds: 180),
                  curve: Curves.easeOutCubic,
                  child: Icon(
                    Icons.keyboard_arrow_down_rounded,
                    size: 18,
                    color: DunesColors.resolve(
                      context,
                      open || supplyHiddenActive
                          ? _LhPlum.deep
                          : LhColors.mute2,
                    ),
                  ),
                ),
                if (!open && supplyHiddenActive)
                  Positioned(
                    top: 4,
                    right: 4,
                    child: Container(
                      width: 5,
                      height: 5,
                      decoration: BoxDecoration(
                        color: DunesColors.resolve(
                          context,
                          _LhPlum.primary,
                          role: DunesColorRole.surface,
                        ),
                        shape: BoxShape.circle,
                      ),
                    ),
                  ),
              ],
            ),
          ),
        ),
      );
    }

    Widget filterRow({
      required String kicker,
      required List<Widget> cells,
      required bool divider,
      Widget? trailing,
    }) {
      return Container(
        height: lighthouseLedgerFilterRowHeight,
        decoration: BoxDecoration(
          border: divider
              ? Border(
                  bottom: BorderSide(
                    color: DunesColors.resolve(
                      context,
                      LhColors.line2,
                      role: DunesColorRole.border,
                    ),
                    width: 0.5,
                  ),
                )
              : null,
        ),
        padding: const EdgeInsets.fromLTRB(12, 2, 12, 2),
        child: Row(
          children: [
            // 行名：小一号的灰字 + 一道竖发丝线，跟胶囊分开。
            // kicker 为空 = 不要行名（分类行：胶囊本身就说明了是分类）。
            if (kicker.isNotEmpty) ...[
              SizedBox(
                width: lighthouseLedgerFilterKickerWidth - 6,
                child: Text(
                  kicker,
                  textAlign: TextAlign.left,
                  maxLines: 1,
                  softWrap: false,
                  style: LhTypography.sans(
                    size: 10,
                    color: DunesColors.resolve(context, LhColors.mute2),
                    weight: FontWeight.w600,
                    letterSpacing: 0.6,
                    height: 1.0,
                    context: context,
                  ),
                ),
              ),
              Container(
                width: 0.8,
                height: 14,
                color: DunesColors.resolve(
                  context,
                  LhColors.line2,
                  role: DunesColorRole.surface,
                ),
              ),
              const SizedBox(width: 9),
            ],
            Expanded(
              // 右沿淡出：胶囊放不下时看得出「还能往右滑」。
              child: ShaderMask(
                blendMode: BlendMode.dstIn,
                shaderCallback: (rect) => const LinearGradient(
                  colors: [Colors.black, Colors.black, Colors.transparent],
                  stops: [0.0, 0.92, 1.0],
                ).createShader(rect),
                child: ListView.separated(
                  scrollDirection: Axis.horizontal,
                  padding: const EdgeInsets.only(right: 18),
                  physics: const ClampingScrollPhysics(),
                  itemCount: cells.length,
                  separatorBuilder: (_, __) => const SizedBox(width: 6),
                  itemBuilder: (_, i) => Center(child: cells[i]),
                ),
              ),
            ),
            if (trailing != null) ...[const SizedBox(width: 4), trailing],
          ],
        ),
      );
    }

    // ── 收尾：一块连续表面，行间 0.5px hairline ────────────────────────
    //   旧版是三张各自带圆角和描边的白卡上下漂着 —— 底下的账本是连续 hairline、
    //   零圆角，两套语言。合成一张卡后，筛选区读起来就是账本表头往上长的一截，
    //   而不是悬在它上面的另一个控件。
    //
    //   四个主入口等分，分类 / HUN 共用固定宽度的左侧标签栏。
    return Container(
      color: DunesColors.resolve(
        context,
        Colors.white,
        role: DunesColorRole.surface,
      ),
      child: Column(
        crossAxisAlignment: CrossAxisAlignment.stretch,
        children: [
          Container(
            decoration: BoxDecoration(
              border: Border(
                bottom: BorderSide(
                  color: DunesColors.resolve(
                    context,
                    LhColors.line2,
                    role: DunesColorRole.border,
                  ),
                  width: 0.5,
                ),
              ),
            ),
            height: lighthouseLedgerPrimaryTabHeight,
            padding: const EdgeInsets.symmetric(horizontal: 8),
            child: Row(
              children: [
                for (int i = 0; i < dimCells.length; i++) ...[
                  if (i == dimCells.length - 1 &&
                      lighthouseLedgerSeparatesAnalysisTab)
                    Container(
                      width: 0.5,
                      height: 18,
                      color: DunesColors.resolve(
                        context,
                        LhColors.line2,
                        role: DunesColorRole.surface,
                      ),
                    ),
                  Expanded(child: dimCells[i]),
                ],
              ],
            ),
          ),
          if (showGroups && groups.isNotEmpty)
            filterRow(
              kicker: '',
              divider: true,
              // 最右：PK 篮（账本卡片上点「PK」加进来的都在这）。
              trailing: Row(
                mainAxisSize: MainAxisSize.min,
                children: [
                  if (supplyFoldable) moreFiltersToggle(),
                  // PK 暂不上线（kLighthousePkEnabled）。
                  if (kLighthousePkEnabled) LhPkBasketButton(onTap: _openPk),
                  // 原来单独一行的「🔍 · 指标」并到这里。
                  ..._buildLedgerFilterTools(sticky: sticky),
                  // 左右对比 PK（只在一级）。
                  if (_tab == 'product' ||
                      _tab == 'supply' ||
                      _tab == 'channel' ||
                      _tab == 'people') ...[
                    const SizedBox(width: 4),
                    _buildPkEntryPill(),
                  ],
                ],
              ),
              cells: groups
                  .map(
                    (g) => _filterPill(
                      label: g,
                      isOn: _groupFilter == g,
                      onTap: () => _setGroupFilter(g),
                    ),
                  )
                  .toList(),
            ),
          if (showHun && hunOpts.isNotEmpty && !supplyFolded)
            filterRow(
              kicker: 'HUN',
              divider: true,
              cells: hunOpts
                  .map(
                    (v) => _filterPill(
                      label: _hunLabelFor(v),
                      isOn: _hunFilter == v,
                      strong: false,
                      onTap: () => setState(() {
                        _heroPointIndex = null;
                        _hunFilter = _hunFilter == v ? '全部' : v;
                        _listLimit = _listPageSize;
                      }),
                    ),
                  )
                  .toList(),
            ),
          if (showTradeType && !supplyFolded)
            filterRow(
              kicker: '类型',
              divider: true,
              cells: const ['全部', '普通交易', '权益交易', '权益收入']
                  .map(
                    (value) => _filterPill(
                      label: value,
                      isOn: _tradeTypeFilter == value,
                      strong: false,
                      onTap: () => setState(() {
                        _heroPointIndex = null;
                        _tradeTypeFilter = value;
                        _listLimit = _listPageSize;
                        _rowsCacheKey = '';
                        _rowsCache = null;
                      }),
                    ),
                  )
                  .toList(),
            ),
        ],
      ),
    );
  }

  Color _panelGroupAccent(String group) {
    switch (group) {
      // 2026-10-27 · 绿 → 靛蓝（绿只留给负数）。
      case '能源':
        return DunesColors.resolve(context, const Color(0xFF5C6FB5));
      case '能源积分返费':
        return DunesColors.resolve(context, const Color(0xFF4A5A9A));
      case '公共出行':
      case '出行':
        return DunesColors.resolve(context, LhColors.product);
      case '运营商':
        return DunesColors.resolve(context, _LhPlum.primary);
      case '民营':
        return DunesColors.resolve(context, LhColors.private);
      case '多渠道':
        return DunesColors.resolve(context, LhColors.multi);
      case '平安':
        return DunesColors.resolve(context, LhColors.pingan);
      case '移动':
      case '电信':
      case '广电':
      case '运营商':
        return DunesColors.resolve(context, LhColors.carrier);
      case '银联':
        return DunesColors.resolve(context, LhColors.copper);
      case '星和动力':
        return DunesColors.resolve(context, _LhPlum.primary);
      case 'Fintech':
        return DunesColors.resolve(context, LhColors.copper);
      default:
        return DunesColors.resolve(context, _LhPlum.primary);
    }
  }

  IconData _categoryFallbackIcon(String label) {
    if (label == '全部') return Icons.apps_rounded;
    if (label.contains('未分类')) return Icons.help_outline_rounded;
    if (label.contains('能源')) return Icons.bolt_rounded;
    if (label.contains('出行')) return Icons.directions_bus_rounded;
    if (label.contains('民营')) return Icons.storefront_outlined;
    if (label.contains('运营商')) return Icons.cell_tower_rounded;
    if (label.contains('多渠道')) return Icons.hub_outlined;
    return Icons.category_outlined;
  }

  Widget _categoryLeadingIcon(
    String label, {
    required double size,
    required bool selected,
  }) {
    final asset = lighthouseCategoryBrandAsset(label);
    if (asset != null) {
      return SizedBox.square(
        dimension: size,
        child: SvgPicture.asset(asset, fit: BoxFit.contain),
      );
    }
    return Icon(
      _categoryFallbackIcon(label),
      size: size,
      color: selected
          ? DunesColors.resolve(context, _LhPlum.primary)
          : DunesColors.resolve(context, LhColors.mute2),
    );
  }

  // ───── v16 · 维度 Tab / 筛选胶囊 ─────────────────────────────────────────
  //   旧版三层（维度 / 分类 / HUN）用的是同一套「淡紫底 + 描边的圆角框」，
  //   只差一点大小，选中态也都是淡紫 —— 分不出层级，框线一多就乱。
  //   现在每层只用一种语言：
  //     维度 —— 纯文字 + 底部紫色指示条（最高层级，最安静）；
  //     分类 —— 实心胶囊：未选浅灰底、选中深紫底白字（对比最强，一眼找到当前筛选）；
  //     HUN  —— 描边小胶囊，比分类再轻一档。
  //   通用的 Material 图标（闪电 / 九宫格 / 问号 / 信号塔）全部去掉，它们不带
  //   信息只添噪；只保留真品牌 logo（中石油 / 平安 / 移动…），那是认得出的。
  Widget _dimTab({
    required String label,
    required bool isOn,
    required VoidCallback onTap,
    IconData? trailing,
  }) {
    return GestureDetector(
      onTap: onTap,
      behavior: HitTestBehavior.opaque,
      child: Column(
        children: [
          Expanded(
            child: Center(
              child: Row(
                mainAxisSize: MainAxisSize.min,
                children: [
                  Flexible(
                    // v23 · 不用 LhScrollText + height 1.0：那条单行可横拖的渲染
                    // 路径按 1.0 行高裁切，汉字底部横笔（品 / 道 / 方）被切掉一截，
                    // 看起来像少帧、显示不全。四五个字的 tab 名不需要横拖。
                    child: Text(
                      label,
                      maxLines: 1,
                      softWrap: false,
                      overflow: TextOverflow.ellipsis,
                      textAlign: TextAlign.center,
                      style: LhTypography.sans(
                        size: 13,
                        color: isOn
                            ? DunesColors.resolve(context, _LhPlum.deep)
                            : DunesColors.resolve(context, LhColors.mute),
                        weight: isOn ? FontWeight.w700 : FontWeight.w500,
                        letterSpacing: isOn ? 0.4 : 0.3,
                        height: 1.3,
                        context: context,
                      ),
                    ),
                  ),
                  if (trailing != null) ...[
                    const SizedBox(width: 3),
                    Icon(
                      trailing,
                      size: 12,
                      color: DunesColors.resolve(
                        context,
                        _LhPlum.primary,
                      ).withAlpha(150),
                    ),
                  ],
                ],
              ),
            ),
          ),
          AnimatedContainer(
            duration: const Duration(milliseconds: lighthousePeriodAnimationMs),
            curve: Curves.easeOutCubic,
            margin: const EdgeInsets.only(bottom: 4),
            width: isOn ? 18 : 0,
            height: 2.5,
            decoration: BoxDecoration(
              gradient: LinearGradient(
                colors: [
                  DunesColors.resolve(
                    context,
                    _LhPlum.primary,
                    role: DunesColorRole.surface,
                  ),
                  DunesColors.resolve(
                    context,
                    _LhPlum.deep,
                    role: DunesColorRole.surface,
                  ),
                ],
              ),
              borderRadius: BorderRadius.circular(1.25),
              boxShadow: isOn
                  ? [
                      BoxShadow(
                        color: _LhPlum.primary.withAlpha(70),
                        blurRadius: 5,
                        offset: const Offset(0, 1),
                      ),
                    ]
                  : null,
            ),
          ),
        ],
      ),
    );
  }

  /// [strong] = 分类行（实心胶囊）；false = HUN 行（描边小胶囊）。
  Widget _filterPill({
    required String label,
    required bool isOn,
    required VoidCallback onTap,
    bool strong = true,
  }) {
    // 「(未分类)」这类括号是后端值的写法，展示时去掉 —— 胶囊本身已经是边界。
    final m = RegExp(r'^[(（](.+)[)）]$').firstMatch(label.trim());
    final display = m?.group(1) ?? label;
    final asset = lighthouseCategoryBrandAsset(label);
    final height = strong ? 28.0 : 26.0;
    final softOn = lighthouseLedgerMatchesHeroStyle;
    final bg = strong
        ? (isOn
              ? DunesColors.resolve(
                  context,
                  softOn ? _LhPlum.lavender : _LhPlum.deep,
                  role: DunesColorRole.surface,
                )
              : DunesColors.resolve(
                  context,
                  const Color(0xFFFBFAFD),
                  role: DunesColorRole.surface,
                ))
        : (isOn
              ? DunesColors.resolve(
                  context,
                  _LhPlum.primary,
                  role: DunesColorRole.surface,
                ).withAlpha(22)
              : Colors.transparent);
    final fg = strong
        ? (isOn
              ? DunesColors.resolve(
                  context,
                  softOn ? _LhPlum.deep : Colors.white,
                )
              : DunesColors.resolve(context, LhColors.ink2))
        : (isOn
              ? DunesColors.resolve(context, _LhPlum.deep)
              : DunesColors.resolve(context, LhColors.mute));
    return Semantics(
      button: true,
      selected: isOn,
      label: display,
      child: GestureDetector(
        onTap: onTap,
        behavior: HitTestBehavior.opaque,
        child: ConstrainedBox(
          constraints: const BoxConstraints(
            minWidth: lighthouseLedgerTouchTargetSize,
            minHeight: lighthouseLedgerTouchTargetSize,
          ),
          child: Center(
            child: AnimatedContainer(
              duration: const Duration(milliseconds: 160),
              curve: Curves.easeOut,
              height: height,
              padding: EdgeInsets.only(left: asset != null ? 5 : 12, right: 12),
              decoration: BoxDecoration(
                color: DunesColors.resolveNullable(
                  context,
                  bg,
                  role: DunesColorRole.surface,
                ),
                borderRadius: BorderRadius.circular(6), // 2026-10-26 · 分类筛选改圆角方块，不再是胶囊
                boxShadow: strong && isOn && !softOn
                    ? [
                        BoxShadow(
                          color: _LhPlum.deep.withAlpha(48),
                          blurRadius: 8,
                          spreadRadius: -2,
                          offset: const Offset(0, 2),
                        ),
                      ]
                    : null,
                border: strong
                    ? Border.all(
                        color: isOn
                            ? (softOn
                                  ? DunesColors.resolve(
                                      context,
                                      _LhPlum.primary,
                                      role: DunesColorRole.border,
                                    ).withAlpha(60)
                                  : DunesColors.resolve(
                                      context,
                                      _LhPlum.deep,
                                      role: DunesColorRole.border,
                                    ))
                            : DunesColors.resolve(
                                context,
                                const Color(0xFFE6E2EE),
                                role: DunesColorRole.border,
                              ),
                        width: 0.8,
                      )
                    : Border.all(
                        color: isOn
                            ? DunesColors.resolve(
                                context,
                                _LhPlum.primary,
                                role: DunesColorRole.border,
                              ).withAlpha(120)
                            : DunesColors.resolve(
                                context,
                                LhColors.line2,
                                role: DunesColorRole.border,
                              ),
                        width: 0.8,
                      ),
              ),
              child: Row(
                mainAxisSize: MainAxisSize.min,
                children: [
                  if (asset != null) ...[
                    // 品牌 logo 垫一个白圆：选中后底色变深紫，logo 原色不会被吃掉。
                    Container(
                      width: height - 8,
                      height: height - 8,
                      padding: const EdgeInsets.all(2.5),
                      decoration: BoxDecoration(
                        color: DunesColors.resolve(
                          context,
                          Colors.white,
                          role: DunesColorRole.surface,
                        ),
                        shape: BoxShape.circle,
                      ),
                      child: SvgPicture.asset(asset, fit: BoxFit.contain),
                    ),
                    const SizedBox(width: 5),
                  ],
                  Text(
                    display,
                    maxLines: 1,
                    softWrap: false,
                    style: LhTypography.sans(
                      size: strong ? 12 : 11.5,
                      color: fg,
                      weight: isOn ? FontWeight.w600 : FontWeight.w500,
                      letterSpacing: 0.1,
                      height: 1.0,
                      context: context,
                    ),
                  ),
                ],
              ),
            ),
          ),
        ),
      ),
    );
  }

  /// 三级导航：主维度与日周月季年同一套圆角选中框，分类用胶囊，HUN 用轻量分段。
  Widget _segmentCell({
    required String label,
    required bool isOn,
    required VoidCallback onTap,
    _SegmentTone tone = _SegmentTone.dim,
    _SegmentSize size = _SegmentSize.large,
    Color? accent,
    IconData? trailing,
    Widget? leading,
  }) {
    final a = accent ?? DunesColors.resolve(context, _LhPlum.primary);
    final isLarge = size == _SegmentSize.large;
    final isPrimary = tone == _SegmentTone.dim && isLarge;
    final isSubgroup = tone == _SegmentTone.subgroup;

    return GestureDetector(
      onTap: onTap,
      behavior: HitTestBehavior.opaque,
      child: isPrimary
          ? Padding(
              padding: const EdgeInsets.symmetric(horizontal: 2, vertical: 4),
              child: AnimatedContainer(
                width: double.infinity,
                height: double.infinity,
                duration: const Duration(
                  milliseconds: lighthousePeriodAnimationMs,
                ),
                curve: Curves.easeOutCubic,
                decoration: BoxDecoration(
                  color: isOn
                      ? DunesColors.resolve(
                          context,
                          LhColors.purpleSoft,
                          role: DunesColorRole.surface,
                        )
                      : Colors.transparent,
                  borderRadius: BorderRadius.circular(
                    lighthousePeriodSelectedRadius,
                  ),
                  border: Border.all(
                    color: isOn
                        ? DunesColors.resolve(
                            context,
                            _LhPlum.primary,
                            role: DunesColorRole.border,
                          ).withAlpha(55)
                        : Colors.transparent,
                    width: 0.7,
                  ),
                ),
                child: Row(
                  mainAxisAlignment: MainAxisAlignment.center,
                  children: [
                    if (isOn) ...[
                      Container(
                        width: lighthousePeriodStatusDotSize,
                        height: lighthousePeriodStatusDotSize,
                        decoration: BoxDecoration(
                          color: DunesColors.resolve(
                            context,
                            _LhPlum.primary,
                            role: DunesColorRole.surface,
                          ),
                          shape: BoxShape.circle,
                        ),
                      ),
                      const SizedBox(width: 5),
                    ],
                    if (leading != null) ...[leading, const SizedBox(width: 5)],
                    Flexible(
                      child: LhScrollText(
                        label,
                        maxLines: 1,
                        overflow: TextOverflow.ellipsis,
                        style: LhTypography.sans(
                          size: 12,
                          color: isOn
                              ? DunesColors.resolve(context, _LhPlum.deep)
                              : DunesColors.resolve(context, LhColors.ink2),
                          weight: isOn ? FontWeight.w600 : FontWeight.w500,
                          letterSpacing: 0.3,
                          height: 1.0,
                          context: context,
                        ),
                      ),
                    ),
                    if (trailing != null) ...[
                      const SizedBox(width: 2),
                      Icon(
                        trailing,
                        size: 13,
                        color: isOn
                            ? DunesColors.resolve(context, _LhPlum.primary)
                            : DunesColors.resolve(context, LhColors.mute2),
                      ),
                    ],
                  ],
                ),
              ),
            )
          : AnimatedContainer(
              duration: const Duration(milliseconds: 160),
              curve: Curves.easeOut,
              constraints: const BoxConstraints.tightFor(height: 30),
              padding: const EdgeInsets.symmetric(horizontal: 10),
              decoration: BoxDecoration(
                color: isSubgroup
                    ? (isOn
                          ? DunesColors.resolve(
                              context,
                              LhColors.paper,
                              role: DunesColorRole.surface,
                            )
                          : DunesColors.resolve(
                              context,
                              LhColors.mist,
                              role: DunesColorRole.surface,
                            ))
                    : (isOn
                          ? DunesColors.resolve(
                              context,
                              LhColors.purpleSoft,
                              role: DunesColorRole.surface,
                            )
                          : DunesColors.resolve(
                              context,
                              const Color(0xFFFFFDFF),
                              role: DunesColorRole.surface,
                            )),
                borderRadius: BorderRadius.circular(
                  lighthouseLedgerFilterChipRadius,
                ),
                border: Border.all(
                  color: isSubgroup
                      ? (isOn
                            ? DunesColors.resolve(
                                context,
                                LhColors.line,
                                role: DunesColorRole.border,
                              )
                            : DunesColors.resolve(
                                context,
                                LhColors.line2,
                                role: DunesColorRole.border,
                              ).withAlpha(150))
                      : (isOn
                            ? DunesColors.resolve(
                                context,
                                _LhPlum.primary,
                                role: DunesColorRole.border,
                              ).withAlpha(70)
                            : DunesColors.resolve(
                                context,
                                LhColors.line2,
                                role: DunesColorRole.border,
                              ).withAlpha(150)),
                  width: 0.7,
                ),
              ),
              child: Row(
                mainAxisSize: MainAxisSize.min,
                mainAxisAlignment: MainAxisAlignment.center,
                children: [
                  if (leading != null) ...[leading, const SizedBox(width: 5)],
                  LhScrollText(
                    label,
                    maxLines: 1,
                    overflow: TextOverflow.ellipsis,
                    style: LhTypography.sans(
                      size: isSubgroup ? 11 : 11.5,
                      color: isOn
                          ? (isSubgroup
                                ? DunesColors.resolve(context, LhColors.ink)
                                : DunesColors.resolve(context, _LhPlum.deep))
                          : DunesColors.resolve(context, LhColors.mute),
                      weight: isOn ? FontWeight.w600 : FontWeight.w500,
                      letterSpacing: 0.1,
                      height: 1.0,
                      context: context,
                    ),
                  ),
                  if (trailing != null) ...[
                    const SizedBox(width: 2),
                    Icon(
                      trailing,
                      size: 12,
                      color: isOn
                          ? a
                          : DunesColors.resolve(context, LhColors.mute2),
                    ),
                  ],
                ],
              ),
            ),
    );
  }

  // ───── Sort Bar (v4 重设计) ────────────────────────────────────────────────
  //   v3 前: dropdown 按钮 + 5 个 chip 挤成两行, 视觉紧凑, 没有分组喘息
  //   v4:    拆成两段
  //          【异常筛选段】kicker + 4 张卡片 (每卡: 图标 + 数字大字 + label)
  //          【视角控制段】kicker + dropdown 按钮 (原样保留, 只是加了 kicker 分组)
  //          "全部" chip 拿掉, 变成右上角"复位/显示全部"文字
  Widget _buildSortbar({String anchorScope = 'main'}) {
    return Container(
      // 「09.14 选区间 · 指标 12」是账本的表头行，不是又一块白面板 ——
      // 给它一层极浅的底，上面的维度条和下面的表体就各自站住了，
      // 三条白面孔连在一起时那种「不知道哪块管哪块」也就没了。
      color: DunesColors.resolve(
        context,
        LhColors.mist,
        role: DunesColorRole.surface,
      ),
      padding: const EdgeInsets.fromLTRB(12, 8, 12, 8),
      child: _buildViewControlsBar(anchorScope: anchorScope),
    );
  }

  /// v4 异常筛选段: kicker + 4 张卡片
  Widget _buildAnomalyFilterSection() {
    final baseRows = _rowsBeforeAnomalyFilter();
    if (baseRows.isEmpty) return const SizedBox.shrink();
    const filters = ['亏损', 'ROI低于目标', '成本异常', '利差倒挂'];
    final counts = <String, int>{
      for (final f in filters)
        f: baseRows.where((r) => _rowMatchesAnomaly(r, f)).length,
    };
    final isFiltered = _anomalyFilter != '全部';

    return Column(
      crossAxisAlignment: CrossAxisAlignment.stretch,
      children: [
        // v5: 清除按钮拿掉 —— 点击已选中卡片即取消选中
        // ── 4 张卡片一行 ────────────────────────────
        Row(
          children: [
            for (int i = 0; i < filters.length; i++) ...[
              if (i > 0) const SizedBox(width: 7),
              Expanded(
                child: _anomalyCard(filters[i], counts[filters[i]] ?? 0),
              ),
            ],
          ],
        ),
      ],
    );
  }

  /// v4 单张异常卡片: 图标 + 数字大字 + label 小字
  /// v6 单张异常卡 — editorial 中性设计, 去除花花绿绿
  ///   · 无图标 (4 张不同色图标是"花"的来源)
  ///   · 无背景 tint (原 neg/copper 淡填)
  ///   · Active 用 paper 底 + 左侧 2px ink 竖条 (editorial 高级感)
  ///   · label 用 ink2, count 用 neg (仅数字表达"这里有问题")
  Widget _anomalyCard(String label, int count) {
    final active = _anomalyFilter == label;
    final muted = count == 0;

    // 简短化 label
    String short;
    switch (label) {
      case '亏损':
        short = '亏损';
        break;
      case 'ROI低于目标':
        short = 'ROI 低';
        break;
      case '成本异常':
        short = '成本异常';
        break;
      case '利差倒挂':
        short = '利差倒挂';
        break;
      default:
        short = label;
    }

    final labelColor = muted
        ? DunesColors.resolve(context, LhColors.mute2)
        : (active
              ? DunesColors.resolve(context, LhColors.ink)
              : DunesColors.resolve(context, LhColors.ink2));
    final countColor = muted
        ? DunesColors.resolve(context, LhColors.mute2)
        : DunesColors.resolve(
            context,
            LhColors.pos,
          ).withAlpha(active ? 255 : 210);

    return Opacity(
      opacity: muted ? 0.42 : 1.0,
      child: GestureDetector(
        behavior: HitTestBehavior.opaque,
        onTap: muted
            ? null
            : () {
                setState(() {
                  // 二次点击同一张 → 取消; 首次 → 应用
                  _anomalyFilter = active ? '全部' : label;
                  _listLimit = _listPageSize;
                });
              },
        child: AnimatedContainer(
          duration: const Duration(milliseconds: 140),
          padding: const EdgeInsets.symmetric(vertical: 6, horizontal: 7),
          decoration: BoxDecoration(
            color: active
                ? DunesColors.resolve(
                    context,
                    LhColors.paper,
                    role: DunesColorRole.surface,
                  ).withAlpha(180)
                : DunesColors.resolve(
                    context,
                    Colors.white,
                    role: DunesColorRole.surface,
                  ),
            border: Border(
              left: BorderSide(
                color: active
                    ? DunesColors.resolve(
                        context,
                        LhColors.ink,
                        role: DunesColorRole.border,
                      )
                    : DunesColors.resolve(
                        context,
                        LhColors.line2,
                        role: DunesColorRole.border,
                      ),
                width: active ? 2 : 0.5,
              ),
              top: BorderSide(
                color: DunesColors.resolve(
                  context,
                  LhColors.line2,
                  role: DunesColorRole.border,
                ),
                width: 0.5,
              ),
              right: BorderSide(
                color: DunesColors.resolve(
                  context,
                  LhColors.line2,
                  role: DunesColorRole.border,
                ),
