  /// 板块筛选已并入主 Tab 分段条，不再单独挂载。

  // ── BI 视图 ────────────────────────────────────────────────────────────
  //   「选区间」右边的大按钮。点开是一整页数据科学风格的分析图：
  //   构成环形 + 数据表。
  //   数据全部来自当前已加载的 bundle，不额外发请求，所以区间/分类怎么筛，
  //   BI 视图就跟着怎么算。

  /// BI 顶部五个视角并排，标签一律两字 —— 375 宽下「供给方」会把格子撑破。
  static String _biDimLabel(String dim) => switch (dim) {
    'supply' => '供给',
    'channel' => '渠道',
    'people' => '人效',
    'netTa' => '净TA',
    _ => '产品',
  };

  /// BI 视图可选指标 —— 直接读该维度的 UI schema，避免与列表口径漂移。
  List<LhBiMetric> _biMetricsFor(String dim) {
    // 净TA 的行是资金流五类映射，没有销售额/成本这些账本字段，
    // 拿账本指标去套只会得到一排 0。它自己的口径就三个。
    if (dim == 'netTa') {
      return const <LhBiMetric>[
        LhBiMetric(key: 'netTa', label: '净额'),
        LhBiMetric(key: 'inflow', label: '流入'),
        LhBiMetric(key: 'outflow', label: '流出'),
      ];
    }
    const skip = <String>{'trend', 'share', 'discount', 'name', 'group'};
    final out = <LhBiMetric>[];
    for (final d in _uiMetricDefs(dim)) {
      final key = d['key']?.toString() ?? '';
      if (key.isEmpty || skip.contains(key)) continue;
      if (key.startsWith(lighthouseCostBillMetricPrefix)) continue;
      final label = (d['short'] ?? d['label'] ?? key).toString();
      out.add(LhBiMetric(key: key, label: label, isRate: d['isRate'] == true));
      if (out.length >= 10) break;
    }
    if (out.isEmpty) {
      return const <LhBiMetric>[
        LhBiMetric(key: 'sales', label: '销售额'),
        LhBiMetric(key: 'profit', label: '净利润'),
        LhBiMetric(key: 'revenue', label: '收入'),
        LhBiMetric(key: 'gmv', label: 'GMV'),
        LhBiMetric(key: 'costTotal', label: '成本合计'),
        LhBiMetric(key: 'grossMargin', label: '毛利率', isRate: true),
      ];
    }
    return out;
  }

  static const List<String> _kBiDims = <String>[
    'product',
    'supply',
    'channel',
    'people',
    'netTa',
  ];

  String _biInitialDim() {
    final dims = _biDims();
    return dims.contains(_tab) ? _tab : 'product';
  }

  bool get _biDimLoading {
    final dim = lighthouseBiDimToLoad(biDim: _biDim, fallback: _biInitialDim());
    if (_tabErrors.containsKey(dim)) return false;
    return _loading || _loadingTabs.contains(dim) || !_loadedTabs.contains(dim);
  }

  /// 顶部出哪几个视角 —— 按权限裁。没有净TA权限的人不该在 BI 里看见净TA，
  /// 否则点进去是一页空图，比没有这个入口更糟。
  List<String> _biDims() => [
    for (final d in _kBiDims)
      if ((d != 'people' || _showsPeopleTab) &&
          (d != 'netTa' || _hasNetTaAccess))
        d,
  ];

  /// BI 的分类条与主列表同一份来源，避免两处各算各的。
  /// 净TA 例外：它的 group 就是行名本身，出一排「每类只有一行」的筛选毫无意义。
  List<String> _biCategoriesFor(String dim) =>
      dim == 'netTa' ? const <String>[] : _categoryOptions(dim);

  /// 一级行的 detail key —— 与主列表开详情、withTrends 用的是同一套
  /// （name 或 name::group），不然取回来的 detail 挂不到同一个实体上。
  String? _biRowKey(String dim, String name) {
    final rows = _bundle?.rowsOf(dim) ?? const <Map<String, dynamic>>[];
    for (final r in rows) {
      if ((r['name']?.toString().trim() ?? '') == name) {
        return _dimensionRowKey(r);
      }
    }
    return null;
  }

  /// BI 构成图的下钻：按交叉维取（产品/供给/渠道/人效互相拆另外三维）。
  ///
  /// 先读 detail 列表，再读 *_drill map。不做估算。
  ({String label, List<Map<String, dynamic>> rows}) _biBreakdownFor(
    String dim,
    String name,
    String breakKey,
  ) {
    const empty = <Map<String, dynamic>>[];
    final label = switch (breakKey) {
      'supply' => '供给',
      'channel' => '渠道',
      'people' => '人效',
      'province' => '省份',
      'project' => '项目',
      _ => '产品',
    };
    final key = _biRowKey(dim, name) ?? name;
    final detail = _detailEntityMap(dim, key);
    if (detail == null) return (label: label, rows: empty);

    List<Map<String, dynamic>> listOf(dynamic raw) {
      if (raw is! List) return empty;
      return raw
          .whereType<Map>()
          .map((e) => Map<String, dynamic>.from(e))
          .toList();
    }

    for (final k in [breakKey, '${breakKey}s', '${breakKey}_list']) {
      final rows = listOf(detail[k]);
      if (rows.isNotEmpty) return (label: label, rows: rows);
    }

    final field = _detailDrillMapField(breakKey);
    if (field.isNotEmpty) {
      final drill = detail[field];
      if (drill is Map && drill.isNotEmpty) {
        final rows = <Map<String, dynamic>>[];
        drill.forEach((k, v) {
          if (v is! Map) return;
          final m = Map<String, dynamic>.from(v);
          final rawName = m['name']?.toString().trim() ?? '';
          final fallback = k.toString();
          m['name'] = rawName.isNotEmpty
              ? rawName
              : (fallback.contains('::')
                    ? fallback.split('::').first
                    : fallback);
          rows.add(m);
        });
        if (rows.isNotEmpty) return (label: label, rows: rows);
      }
    }
    return (label: label, rows: empty);
  }

  /// BI 走势图的序列。
  ///
  ///   产品 / 供给 / 渠道：行上带 trend，BI 自己逐位相加就够了，这里返回 null。
  ///   人效：行上没有 trend（走势按实体名下推 SQL，「人」在库里没有这一列），
  ///        但人是账本的一种分组 —— 全体人加总就是公司总量，
  ///        所以直接给 Hero 用的那条公司级序列，口径完全一致。
  ///   净TA：序列在 metrics 里，本来就不在行上。
  ({List<double> values, List<String> labels})? _biSeriesFor(
    String dim,
    String key,
  ) {
    List<double> values;
    List<String> labels;
    if (dim == 'netTa') {
      // 后端只下发一条净额序列（流入/流出没有各自的时间序列），
      // 三个指标共用它，BI 那边会把标题标成「净额」。
      values = _readMetricSeries('netTaSeries');
      labels = _biSeriesLabels('netTaSeriesLabels');
    } else if (dim == 'people') {
      values = _biLedgerSeries(key);
      labels = _biSeriesLabels('heroSeriesLabels');
    } else {
      return null;
    }
    if (values.length < 2) return null;
    return (values: values, labels: labels);
  }

  List<String> _biSeriesLabels(String metricsKey) {
    // 与 _readMetricSeries 同一份视图，否则拼了历史的序列和标签长度对不上。
    final raw = _heroSeriesMetrics[metricsKey];
    if (raw is! List || raw.isEmpty) return const <String>[];
    return raw.map((e) => e.toString()).toList(growable: false);
  }

  /// 账本口径的公司级序列 —— 键名映射与 [_seriesForMetric] 的一级分支同一套。
  List<double> _biLedgerSeries(String key) => switch (key) {
    'cost' || 'businessCost' => _readMetricSeries('operatingCostSeries'),
    'totalCost' || 'costTotal' => _readMetricSeries('totalCostSeries'),
    'projectCost' => _readMetricSeries('projectCostSeries'),
    'netProfit' => _readMetricSeries('netProfitSeries'),
    _ => _readMetricSeries('${key}Series'),
  };

  // ── BI 卡片报告 ─────────────────────────────────────────────────────────
  //
  //   报告在这一层缓存，不在 BI 视图里 —— BI 视图是叠层，关掉再打开会重建，
  //   缓存跟着它走的话每次打开都要重新生成一份，token 白烧、人还要等。
  //   缓存键带 periodLabel：切日/周/月/季/年就是换了一种报，各存各的。
  final Map<String, LhBiReport> _biReports = <String, LhBiReport>{};
  final Set<String> _biReportBusy = <String>{};

  String _biReportKey(String dim, String entity) =>
      lhBiReportKey(dim, entity, _periodLabelFor(_period));

  LhBiReport? _biReportFor(String dim, String entity) =>
      _biReports[_biReportKey(dim, entity)];

  bool _biReportBusyFor(String dim, String entity) =>
      _biReportBusy.contains(_biReportKey(dim, entity));

  Future<void> _biRequestReport(String dim, String entity, bool force) async {
    if (!_kBiDims.contains(dim)) return;
    final key = _biReportKey(dim, entity);
    // 已经有了而且不是用户主动刷新 —— 直接用缓存，不打后端。
    if (!force && _biReports.containsKey(key)) return;
    if (_biReportBusy.contains(key)) return;
    setState(() => _biReportBusy.add(key));
    try {
      final data = await _service.fetchReport(
        tab: dim,
        period: _period,
        offset: _periodOffset,
        startDate: _isCustomRange ? _customStart : null,
        endDate: _isCustomRange ? _customEnd : null,
        group: _groupFilter,
        anchor: _anchor == _LhAnchor.verified ? 'verified' : 'sales',
        hun: _hunFilter,
        anomaly: _anomalyFilter,
        entity: entity,
        refresh: force,
      );
      final rep = LhBiReport.fromJson(data);
      if (!mounted) return;
      setState(() {
        _biReportBusy.remove(key);
        if (rep != null) _biReports[key] = rep;
      });
    } catch (_) {
      // 报告拿不到不该挡住整页 —— 卡片自己会显示「点右下角生成」。
      if (!mounted) return;
      setState(() => _biReportBusy.remove(key));
    }
  }

  Future<void> _biRequestBreakdown(String dim, String name) async {
    // 净TA 不参与联动（资金流与业务三维不同源），其余四维都能拆。
    if (dim == 'netTa' || !_kBiDims.contains(dim)) return;
    final key = _biRowKey(dim, name);
    if (key == null) return;
    await _loadDetail(dim, key);
  }

  // ── BI 渲染诊断 ─────────────────────────────────────────────────────
  //
  //   build 期的异常会被 ErrorWidget 接走（屏幕上还能看见点东西）；
  //   layout / paint 期的异常不会 —— 框架只是把错误报给 FlutterError.onError，
  //   那块视口就此画不出来，屏幕上是一块干净的白板，没有任何提示。
  //   BI 这一页两条路都接住：第一条错误直接印在页面顶部，别再靠猜。
  //   （BI 稳定之后整块删掉。）
  ErrorWidgetBuilder? _prevErrorWidgetBuilder;
  FlutterExceptionHandler? _prevOnError;
  String? _biError;

  void _installBiErrorProbe() {
    _biError = null;
    _prevErrorWidgetBuilder ??= ErrorWidget.builder;
    ErrorWidget.builder = (FlutterErrorDetails details) {
      _recordBiError(details);
      return const SizedBox.shrink();
    };
    _prevOnError ??= FlutterError.onError;
    FlutterError.onError = (FlutterErrorDetails details) {
      _recordBiError(details);
      _prevOnError?.call(details);
    };
  }

  void _recordBiError(FlutterErrorDetails details) {
    if (_biError != null) return;
    final stack = '${details.stack}'
        .split('\n')
        .where((l) => l.trim().isNotEmpty)
        .take(14)
        .join('\n');
    _biError = '${details.exception}\n\n$stack';
    // 错误多半在 build/layout 中途抛出，此时不能同步 setState。
    WidgetsBinding.instance.addPostFrameCallback((_) {
      if (mounted && _biViewOpen) setState(() {});
    });
  }

  void _restoreErrorProbe() {
    final prevWidget = _prevErrorWidgetBuilder;
    if (prevWidget != null) {
      ErrorWidget.builder = prevWidget;
      _prevErrorWidgetBuilder = null;
    }
    if (_prevOnError != null) {
      FlutterError.onError = _prevOnError;
      _prevOnError = null;
    }
    _biError = null;
  }

  Widget _buildBiErrorBanner() {
    return Material(
      color: DunesColors.resolve(
        context,
        const Color(0xFFFFF1F0),
        role: DunesColorRole.surface,
      ),
      child: SafeArea(
        bottom: false,
        child: Container(
          constraints: const BoxConstraints(maxHeight: 320),
          padding: const EdgeInsets.fromLTRB(14, 12, 14, 14),
          child: SingleChildScrollView(
            child: Column(
              crossAxisAlignment: CrossAxisAlignment.start,
              mainAxisSize: MainAxisSize.min,
              children: [
                Row(
                  children: [
                    Expanded(
                      child: Text(
                        'BI 渲染异常（临时诊断）',
                        style: TextStyle(
                          fontSize: 12.5,
                          fontWeight: FontWeight.w700,
                          color: DunesColors.resolveNullable(
                            context,
                            Color(0xFFB3261E),
                          ),
                        ),
                      ),
                    ),
                    GestureDetector(
                      behavior: HitTestBehavior.opaque,
                      onTap: () => setState(() => _biError = null),
                      child: const Icon(Icons.close_rounded, size: 16),
                    ),
                  ],
                ),
                const SizedBox(height: 8),
                SelectableText(
                  _biError ?? '',
                  style: TextStyle(
                    fontSize: 9.5,
                    height: 1.4,
                    color: DunesColors.resolveNullable(
                      context,
                      Color(0xFF3A2A2A),
                    ),
                  ),
                ),
              ],
            ),
          ),
        ),
      ),
    );
  }

  void _openBiView() {
    LighthouseFeedback.instance.play(LighthouseFeedbackKind.select);
    _closeDropdown();
    _installBiErrorProbe();
    setState(() {
      _closeMetricPage();
      _biViewOpen = true;
      _biDim = _biInitialDim();
    });
    unawaited(_ensureBiLedgerDims());
  }

  /// 进 BI / 切日周月：只拉「现在正在看的那一维」。
  ///
  /// 原来 `_biInitialDim()` 跟主列表 `_tab` 走。人已经在 BI 里切到渠道 / 人效 /
  /// 净TA 后再改粒度，主列表可能还停在产品，于是只重拉产品，当前视角空着。
  Future<void> _ensureBiLedgerDims() async {
    final dim = lighthouseBiDimToLoad(biDim: _biDim, fallback: _biInitialDim());
    await _loadTab(dim);
    unawaited(_loadBiWindowRows(dim));
  }

  List<Map<String, dynamic>>? _biWindowRowsFor(String dim, String window) =>
      _biWindowRows['$dim|$window'];

  List<Map<String, dynamic>> _dimensionRowsFromPayload(
    Map<String, dynamic> data,
  ) {
    return (data['rows'] as List? ?? const [])
        .whereType<Map>()
        .map((e) => Map<String, dynamic>.from(e))
        .toList();
  }

  List<Map<String, dynamic>> _netTaRowsFromPayload(Map<String, dynamic> data) {
    final cats = (data['categories'] as List? ?? const [])
        .whereType<Map>()
        .map((e) => Map<String, dynamic>.from(e))
        .toList();
    return lighthousePrepareNetTARows(cats);
  }

  /// 构成图例的本日/本月新增：永远取日历今天、本月，不跟当前日周月粒度走。
  Future<void> _loadBiWindowRows(String dim) async {
    if (dim.isEmpty) return;
    final dayKey = '$dim|day';
    final monthKey = '$dim|month';
    if (_biWindowRows.containsKey(dayKey) &&
        _biWindowRows.containsKey(monthKey)) {
      return;
    }
    if (_biWindowLoading.contains(dim)) return;
    _biWindowLoading.add(dim);
    final gen = _biWindowGen;

    List<Map<String, dynamic>>? reuse(String period) {
      if (_period != period ||
          _periodOffset != 0 ||
          _customStart != null ||
          !_loadedTabs.contains(dim)) {
        return null;
      }
      final rows = _bundle?.rowsOf(dim);
      if (rows == null || rows.isEmpty) return null;
      return [for (final r in rows) Map<String, dynamic>.from(r)];
    }

    try {
      var dayRows = _biWindowRows[dayKey] ?? reuse('day');
      var monthRows = _biWindowRows[monthKey] ?? reuse('month');
      if (dayRows == null || monthRows == null) {
        if (dim == 'netTa') {
          final fetched = await Future.wait([
            if (dayRows == null)
              _service.fetchNetTA(period: 'day', offset: 0)
            else
              Future<Map<String, dynamic>?>.value(null),
            if (monthRows == null)
              _service.fetchNetTA(period: 'month', offset: 0)
            else
              Future<Map<String, dynamic>?>.value(null),
          ]);
          dayRows ??= fetched[0] == null
              ? null
              : _netTaRowsFromPayload(fetched[0]!);
          monthRows ??= fetched[1] == null
              ? null
              : _netTaRowsFromPayload(fetched[1]!);
        } else {
          final fetched = await Future.wait([
            if (dayRows == null)
              _service.fetchDimension(tab: dim, period: 'day', offset: 0)
            else
              Future<Map<String, dynamic>?>.value(null),
            if (monthRows == null)
              _service.fetchDimension(tab: dim, period: 'month', offset: 0)
            else
              Future<Map<String, dynamic>?>.value(null),
          ]);
          dayRows ??= fetched[0] == null
              ? null
              : _dimensionRowsFromPayload(fetched[0]!);
          monthRows ??= fetched[1] == null
              ? null
              : _dimensionRowsFromPayload(fetched[1]!);
        }
      }
      if (!mounted || gen != _biWindowGen) return;
      setState(() {
        if (dayRows != null) _biWindowRows[dayKey] = dayRows;
        if (monthRows != null) _biWindowRows[monthKey] = monthRows;
      });
    } catch (_) {
      // 本日/本月是附加读数，失败就显示 —，不挡构成图。
    } finally {
      if (gen == _biWindowGen) _biWindowLoading.remove(dim);
    }
  }

  void _closeBiView() {
    if (!_biViewOpen) return;
    _restoreErrorProbe();
    setState(() => _biViewOpen = false);
  }

  /// 与 L2 同款：‹ 退出 + 灯塔 + 缩放/刷新。切日周月在 periodBar。
  Widget _buildBiTopChrome() {
    return Padding(
      padding: const EdgeInsets.fromLTRB(lhBiChromePad, 10, lhBiChromePad, 8),
      child: Row(
        crossAxisAlignment: CrossAxisAlignment.center,
        children: [
          _buildEditorialBackButton(label: '退出', onTap: _closeBiView),
          const SizedBox(width: 10),
          Text(
            '灯塔',
            style: LhTypography.sans(
              size: 19,
              weight: FontWeight.w500,
              color: DunesColors.resolve(context, const Color(0xFF7C5CE6)),
              letterSpacing: -0.2,
              context: context,
            ),
          ),
          const Spacer(),
          _buildAppBarToolbar(),
        ],
      ),
    );
  }

  /// BI 视图入口 —— 主数卡的底座。
  ///
  /// 位置逻辑：BI 不是一个并列的功能入口，是这个大数的延伸 ——「2.60 万，
  /// 那它由谁构成、谁在头部、走势如何、哪里在亏」。所以它跟着数走。
  ///
  /// 视觉逻辑：上一版是一颗淡紫描边的钮浮在卡的留白里 —— 描边和卡自己的
  /// 描边打架，颜色又淡到不像能点，看起来像块占位。这一版改成**通栏底座**：
  /// 贴住卡的两边和底边，深紫→亮紫横向渐变，白字白箭头。
  ///   · 通栏 → 它是这张卡的一部分，不是掉进来的一个控件
  ///   · 实色 → 全卡唯一一块饱和面，「可点」不需要再解释
  ///   · 压在底部 → 给上面那个大数一个基座，整张卡才立得住
  /// 面积只有卡的六分之一，抢不走 30pt 大数的中心地位。
  Widget _buildHeroBiButton() {
    // 拍平版没有卡，也就没有「卡的底边」可以通栏 —— 实色渐变条会变成一块
    // 无处可贴的色块。改成文字入口：紫字 + 箭头，跟在环比行下面，
    // 靠颜色和箭头说明可点，不靠一块面。
    if (lighthouseHeroUsesFlatLayout) {
      return _LhScrollSafeTap(
        onTap: _openBiView,
        child: Padding(
          padding: const EdgeInsets.only(top: 12, bottom: 2, right: 8),
          child: Row(
            mainAxisSize: MainAxisSize.min,
            children: [
              Icon(
                Icons.insights_rounded,
                size: 13,
                color: DunesColors.resolve(context, _LhPlum.primary),
              ),
              const SizedBox(width: 5),
              Text(
                'BI 视图',
                style: LhTypography.sans(
                  size: 11,
                  color: DunesColors.resolve(context, _LhPlum.primary),
                  weight: FontWeight.w700,
                  letterSpacing: 0.1,
                  height: 1.0,
                  context: context,
                ),
              ),
              const SizedBox(width: 3),
              Icon(
                Icons.arrow_forward_rounded,
                size: 12,
                color: DunesColors.resolve(context, _LhPlum.primary),
              ),
            ],
          ),
        ),
      );
    }
    // 底边跟着卡的圆角走，否则会在两个下角戳出方角。
    // 深色顶栏上线后整页的重色只留在最上面：这里改成淡紫底 + 深紫字，
    // 大数才是这张卡的焦点。
    const radius = Radius.circular(lighthouseHeroCardRadius - 1);
    return _LhScrollSafeTap(
      onTap: _openBiView,
      child: Container(
        height: lighthouseHeroBiButtonHeight,
        padding: const EdgeInsets.symmetric(horizontal: 9),
        decoration: BoxDecoration(
          gradient: LinearGradient(
            begin: Alignment.centerLeft,
            end: Alignment.centerRight,
            colors: [
              DunesColors.resolve(
                context,
                const Color(0xFFF6F2FD),
                role: DunesColorRole.surface,
              ),
              DunesColors.resolve(
                context,
                const Color(0xFFEEE7FB),
                role: DunesColorRole.surface,
              ),
            ],
          ),
          border: Border(
            top: BorderSide(
              color: DunesColors.resolve(
                context,
                _LhPlum.line,
                role: DunesColorRole.border,
              ),
              width: 0.8,
            ),
          ),
          borderRadius: BorderRadius.only(
            bottomLeft: radius,
            bottomRight: radius,
          ),
        ),
        child: Row(
          children: [
            Icon(
              Icons.insights_rounded,
              size: 13,
              color: DunesColors.resolve(context, _LhPlum.primary),
            ),
            const SizedBox(width: 6),
            Expanded(
              child: LhScrollText(
                'BI 视图',
                maxLines: 1,
                overflow: TextOverflow.ellipsis,
                style: LhTypography.sans(
                  size: 11.5,
                  color: DunesColors.resolve(context, _LhPlum.deep),
                  weight: FontWeight.w700,
                  letterSpacing: 0.3,
                  height: 1.0,
                  context: context,
                ),
              ),
            ),
            const SizedBox(width: 4),
            Container(
              width: 17,
              height: 17,
              alignment: Alignment.center,
              decoration: BoxDecoration(
                color: DunesColors.resolve(
                  context,
                  _LhPlum.primary,
                  role: DunesColorRole.surface,
                ).withAlpha(30),
                shape: BoxShape.circle,
              ),
              child: Icon(
                Icons.arrow_forward_rounded,
                size: 10.5,
                color: DunesColors.resolve(context, _LhPlum.deep),
              ),
            ),
          ],
        ),
