    );
  }

  /// 视角控制段：左选区间 · 中放大镜 · 右指标
  /// （分类改由上方分类条筛选，不再挂重复下拉）
  Widget _buildViewControlsBar({String anchorScope = 'main'}) {
    // 输入态直接顶掉整条 —— 查找的时候「选区间 / 指标」都不是当下要做的事，
    // 让它们留在旁边只会把输入框挤成一条缝。
    if (_ledgerSearchOpen && _detailKey == null) {
      return _buildLedgerSearchField();
    }
    return Row(
      crossAxisAlignment: CrossAxisAlignment.center,
      children: [
        Flexible(child: _buildDateRangeControl()),
        const SizedBox(width: 8),
        if (_detailKey == null) ...[
          Semantics(
            button: true,
            label: '查找',
            child: GestureDetector(
              behavior: HitTestBehavior.opaque,
              onTap: () => setState(() {
                _ledgerSearchOpen = true;
                _ledgerSearchTab = _tab;
              }),
              child: Container(
                width: 26,
                height: 26,
                alignment: Alignment.center,
                decoration: BoxDecoration(
                  color: DunesColors.resolve(
                    context,
                    _LhPlum.primary,
                    role: DunesColorRole.surface,
                  ).withAlpha(16),
                  borderRadius: BorderRadius.circular(8),
                  border: Border.all(
                    color: DunesColors.resolve(
                      context,
                      _LhPlum.primary,
                      role: DunesColorRole.border,
                    ).withAlpha(30),
                    width: 0.7,
                  ),
                ),
                child: Icon(
                  Icons.search_rounded,
                  size: 15,
                  color: DunesColors.resolve(context, _LhPlum.primary),
                ),
              ),
            ),
          ),
          const SizedBox(width: 8),
        ],
        _buildDropdownActions(
          showCategory: false,
          showMetric: true,
          anchorScope: anchorScope,
        ),
      ],
    );
  }

  Widget _buildLedgerSearchField() {
    final all = _currentRows;
    final matched = _ledgerSearchFiltered(all).length;
    final typing = _ledgerSearch.trim().isNotEmpty;
    return Row(
      crossAxisAlignment: CrossAxisAlignment.center,
      children: [
        Icon(
          Icons.search_rounded,
          size: 15,
          color: DunesColors.resolve(context, _LhPlum.primary),
        ),
        const SizedBox(width: 7),
        Expanded(
          child: TextField(
            controller: _ledgerSearchCtl,
            focusNode: _ledgerSearchFocus,
            autofocus: true,
            textInputAction: TextInputAction.search,
            cursorColor: DunesColors.resolve(context, _LhPlum.primary),
            cursorWidth: 1.4,
            style: LhTypography.sans(
              size: 12.5,
              color: DunesColors.resolve(context, LhColors.ink),
              weight: FontWeight.w600,
              context: context,
            ),
            decoration: InputDecoration(
              isDense: true,
              contentPadding: EdgeInsets.zero,
              border: InputBorder.none,
              enabledBorder: InputBorder.none,
              focusedBorder: InputBorder.none,
              hintText: _ledgerSearchHint,
              hintStyle: LhTypography.sans(
                size: 12.5,
                color: DunesColors.resolve(context, LhColors.mute2),
                weight: FontWeight.w500,
                context: context,
              ),
            ),
            onChanged: (v) => setState(() {
              _ledgerSearch = v;
              _ledgerSearchTab = _tab;
              // 命中变少了还停在上一次的分页位置，会看起来像「搜出来是空的」。
              _listLimit = _listPageSize;
            }),
          ),
        ),
        if (typing) ...[
          Text(
            '$matched / ${all.length}',
            style: _tabular(
              LhTypography.mono(
                size: 10,
                color: matched == 0
                    ? DunesColors.resolve(context, LhColors.neg)
                    : DunesColors.resolve(context, LhColors.mute2),
                weight: FontWeight.w700,
                letterSpacing: 0.2,
                context: context,
              ),
            ),
          ),
          const SizedBox(width: 9),
        ],
        GestureDetector(
          behavior: HitTestBehavior.opaque,
          onTap: _closeLedgerSearch,
          child: Padding(
            padding: EdgeInsets.symmetric(horizontal: 2, vertical: 4),
            child: Icon(
              Icons.close_rounded,
              size: 15,
              color: DunesColors.resolve(context, LhColors.mute2),
            ),
          ),
        ),
      ],
    );
  }

  /// L2/L3 维度段 —— 与一级 `_buildTabSegment` 顶行同款下划线格式。
  /// 无「分类」行；右侧保留条数，便于扫明细体量。
  Widget _buildDetailSubTabSegment({
    required List<_SubTabInfo> subTabList,
    required Map<String, dynamic> viewDict,
    required List<Map<String, dynamic>> activeSubRows,
  }) {
    return Container(
      decoration: BoxDecoration(
        border: Border(
          bottom: BorderSide(
            color: DunesColors.resolve(
              context,
              LhColors.line2,
              role: DunesColorRole.border,
            ),
            width: 0.5,
          ),
        ),
      ),
      padding: const EdgeInsets.fromLTRB(8, 4, 8, 4),
      child: SingleChildScrollView(
        scrollDirection: Axis.horizontal,
        physics: const ClampingScrollPhysics(),
        child: Row(
          children: [
            for (var i = 0; i < subTabList.length; i++) ...[
              if (i > 0) const SizedBox(width: 4),
              Builder(
                builder: (_) {
                  final t = subTabList[i];
                  final isOn = t.key == _detailSubTab;
                  final count = isOn
                      ? activeSubRows.length
                      : ((viewDict[t.key] is List)
                            ? (viewDict[t.key] as List).length
                            : 0);
                  return _segmentCell(
                    label: '${t.label} $count',
                    isOn: isOn,
                    tone: _SegmentTone.dim,
                    size: _SegmentSize.medium,
                    leading: t.icon == null
                        ? null
                        : Icon(
                            t.icon,
                            size: 13,
                            color: isOn
                                ? DunesColors.resolve(context, t.color)
                                : DunesColors.resolve(context, LhColors.mute2),
                          ),
                    onTap: () => setState(() {
                      _clearEquityFocus();
                      _detailSubTab = t.key;
                      _detailPage = 1;
                      if (t.key != 'productName') {
                        _resetDetailSkuSearch();
                      }
                      if (t.key != 'people') {
                        _ensureTrendLoaded(t.key);
                      }
                    }),
                  );
                },
              ),
            ],
          ],
        ),
      ),
    );
  }

  Widget _buildAnomalyFilterChips() {
    final baseRows = _rowsBeforeAnomalyFilter();
    if (baseRows.isEmpty) return const SizedBox.shrink();
    const filters = ['亏损', 'ROI低于目标', '成本异常', '利差倒挂'];
    final counts = <String, int>{
      for (final f in filters)
        f: baseRows.where((r) => _rowMatchesAnomaly(r, f)).length,
    };
    if (counts.values.every((n) => n == 0) && _anomalyFilter == '全部') {
      return const SizedBox.shrink();
    }

    return Padding(
      padding: const EdgeInsets.only(top: 8),
      child: SingleChildScrollView(
        scrollDirection: Axis.horizontal,
        child: Row(
          children: [
            _anomalyChip('全部', baseRows.length),
            for (final f in filters) ...[
              const SizedBox(width: 6),
              _anomalyChip(f, counts[f] ?? 0),
            ],
          ],
        ),
      ),
    );
  }

  Widget _anomalyChip(String label, int count) {
    final active = _anomalyFilter == label;
    final muted = label != '全部' && count == 0;
    final color = label == '亏损' || label == '成本异常' || label == '利差倒挂'
        ? DunesColors.resolve(context, LhColors.pos)
        : DunesColors.resolve(context, _LhPlum.primary);
    final fg = active
        ? color
        : (muted
              ? DunesColors.resolve(context, LhColors.mute2)
              : DunesColors.resolve(context, LhColors.mute));
    return GestureDetector(
      behavior: HitTestBehavior.opaque,
      onTap: muted
          ? null
          : () {
              setState(() {
                _anomalyFilter = label;
                _listLimit = _listPageSize;
              });
            },
      child: AnimatedContainer(
        duration: const Duration(milliseconds: 140),
        padding: const EdgeInsets.symmetric(horizontal: 8, vertical: 4),
        decoration: BoxDecoration(
          color: DunesColors.resolveNullable(
            context,
            active ? color.withAlpha(18) : Colors.transparent,
            role: DunesColorRole.surface,
          ),
          border: Border.all(
            color: active
                ? color.withAlpha(110)
                : DunesColors.resolve(
                    context,
                    LhColors.line2,
                    role: DunesColorRole.border,
                  ),
            width: 0.7,
          ),
          borderRadius: BorderRadius.circular(999),
        ),
        child: Row(
          mainAxisSize: MainAxisSize.min,
          children: [
            Text(
              label,
              style: LhTypography.sans(
                size: 10,
                color: fg,
                weight: active ? FontWeight.w700 : FontWeight.w600,
                letterSpacing: 0.1,
                context: context,
              ),
            ),
            const SizedBox(width: 4),
            Text(
              '$count',
              style: LhTypography.mono(
                size: 9,
                color: active
                    ? color
                    : DunesColors.resolve(context, LhColors.mute2),
                weight: FontWeight.w700,
                letterSpacing: 0.2,
                context: context,
              ),
            ),
          ],
        ),
      ),
    );
  }

  /// HTML `.sortbar .actions` — buttons + dropdown anchor (position:absolute; right:0)
  Widget _buildDropdownActions({
    required bool showCategory,
    required bool showMetric,
    String anchorScope = 'main',
  }) {
    // Main stays Offstage while L2/L3 (and outgoing animated routes) are alive.
    // Each route needs its own anchor; using one GlobalKey for all crashes navigation.
    final metricButtonKey = anchorScope == 'main'
        ? _btnKeyMetric
        : _detailMetricButtonKeys.putIfAbsent(anchorScope, () => GlobalKey());
    final tab = _metricsTab;
    final catActive = _groupFilter != '全部';
    final selectedMetrics = _metrics[tab] ?? [];
    final fullCount = _liveMetrics(tab).length;
    final metricActive = selectedMetrics.length != fullCount;
    final ddOn = _ddMode != _DdMode.none;

    return Row(
      mainAxisSize: MainAxisSize.min,
      children: [
        if (showCategory) ...[
          KeyedSubtree(
            key: _btnKeyCategory,
            child: _buildSortBtn(
              icon: Icons.grid_view_rounded,
              // 未筛选时也显示「全部」，避免用户找不到分类下拉入口。
              label: _groupFilter,
              active: catActive || (_ddMode == _DdMode.category),
              onTap: () => _toggleDropdown(_DdMode.category),
            ),
          ),
          const SizedBox(width: 6),
        ],
        if (showMetric) ...[
          KeyedSubtree(
            key: metricButtonKey,
            child: _buildSortBtn(
              icon: Icons.bar_chart_rounded,
              label: '指标',
              active: metricActive || ddOn && _ddMode == _DdMode.metric,
              badge: '${selectedMetrics.length}',
              onTap: () {
                _activeMetricButtonKey = metricButtonKey;
                _toggleDropdown(_DdMode.metric);
              },
            ),
          ),
        ],
      ],
    );
  }

  Widget _buildSortBtn({
    required IconData icon,
    required String label,
    required bool active,
    String? badge,
    required VoidCallback onTap,
  }) {
    // v3.7: 从 SaaS chip (border + fill + copper 填色 badge pill) → editorial text-only
    //   之前的 copper 圆 pill + 白字 badge 跟"01 02 03 铜条"是同一族 chrome, 用户已明确否定。
    //   现在: 无 border 无 fill, icon+label 直接, active = copper 全线;
    //   badge = 中点分隔的 inline mono 数字 (指标 · 3), 无 pill 无填。
    //   跟 _CubeChipButton v3.7 完全同款。
    final fg = active
        ? DunesColors.resolve(context, _LhPlum.primary)
        : DunesColors.resolve(context, LhColors.mute);
    return GestureDetector(
      onTap: onTap,
      behavior: HitTestBehavior.opaque,
      child: Padding(
        padding: const EdgeInsets.symmetric(horizontal: 6, vertical: 2),
        child: Row(
          mainAxisSize: MainAxisSize.min,
          crossAxisAlignment: CrossAxisAlignment.center,
          children: [
            Icon(
              icon,
              size: 13,
              color: DunesColors.resolveNullable(context, fg),
            ),
            const SizedBox(width: 4),
            Text(
              label,
              style: LhTypography.sans(
                size: 10.5,
                color: fg,
                weight: active ? FontWeight.w700 : FontWeight.w600,
                letterSpacing: 0.2,
                context: context,
              ),
            ),
            if (badge != null) ...[
              const SizedBox(width: 3),
              Text(
                '·',
                style: LhTypography.mono(
                  size: 9,
                  color: DunesColors.resolve(context, LhColors.mute2),
                  weight: FontWeight.w600,
                  context: context,
                ),
              ),
              const SizedBox(width: 3),
              Text(
                badge,
                style: LhTypography.mono(
                  size: 9.5,
                  color: DunesColors.resolve(context, _LhPlum.primary),
                  weight: FontWeight.w700,
                  letterSpacing: 0.2,
                  context: context,
                ),
              ),
            ],
          ],
        ),
      ),
    );
  }

  // ───── Discount Section (supply only) ────────────────────────────────────
  // 列表下方「折扣与返点」整块已用 lighthouseLedgerShowsDiscountBoard 关掉。
  // 冻结列毛利率下的折扣条仍走 _buildLedgerDiscountStrip，不要误删。
  Widget _buildDiscountSection() {
    final allRows = _discountRowsFromBundle();
    if (allRows.isEmpty) return const SizedBox.shrink();

    final sorted = allRows.toList()
      ..sort((a, b) => b.rebate.compareTo(a.rebate));
    final excessCount = allRows.where((r) => r.isExcessProgressive).length;
    final fullCount = allRows.where((r) => r.isFullProgressive).length;
    final otherCount = allRows.length - excessCount - fullCount;
    final remaining = sorted.length - _discountPreviewCount;
    final showAll = _discountExpanded || sorted.length <= _discountPreviewCount;
    final visible = showAll
        ? sorted
        : sorted.take(_discountPreviewCount).toList();

    return Container(
      margin: const EdgeInsets.fromLTRB(
        lighthouseHeroShellMarginH,
        12,
        lighthouseHeroShellMarginH,
        4,
      ),
      padding: const EdgeInsets.fromLTRB(14, 14, 14, 10),
      decoration: BoxDecoration(
        color: DunesColors.resolve(
          context,
          LhColors.paper,
          role: DunesColorRole.surface,
        ),
        border: Border.all(
          color: DunesColors.resolve(
            context,
            LhColors.line2,
            role: DunesColorRole.border,
          ),
          width: 1,
        ),
        borderRadius: BorderRadius.circular(12),
        boxShadow: const [
          BoxShadow(
            color: Color(0x05140A00),
            blurRadius: 2,
            offset: Offset(0, 1),
          ),
          BoxShadow(
            color: Color(0x0F140A00),
            blurRadius: 14,
            spreadRadius: -8,
            offset: Offset(0, 4),
          ),
        ],
      ),
      child: Column(
        crossAxisAlignment: CrossAxisAlignment.start,
        children: [
          Row(
            mainAxisAlignment: MainAxisAlignment.spaceBetween,
            crossAxisAlignment: CrossAxisAlignment.center,
            children: [
              Column(
                crossAxisAlignment: CrossAxisAlignment.start,
                children: [
                  Text(
                    '折扣与返点',
                    style: LhTypography.mono(
                      size: 9.5,
                      color: DunesColors.resolve(context, LhColors.mute),
                      weight: FontWeight.w600,
                      letterSpacing: 1.2,
                      context: context,
                    ),
                  ),
                  const SizedBox(height: 2),
                  Text(
                    showAll
                        ? '${sorted.length} 家 · 按返点排序'
                        : 'TOP $_discountPreviewCount · 共 ${sorted.length} 家',
                    style: LhTypography.mono(
                      size: 9,
                      color: DunesColors.resolve(context, LhColors.mute2),
                      weight: FontWeight.w500,
                      letterSpacing: 0.3,
                      context: context,
                    ),
                  ),
                ],
              ),
              if (remaining > 0)
                GestureDetector(
                  behavior: HitTestBehavior.opaque,
                  onTap: () =>
                      setState(() => _discountExpanded = !_discountExpanded),
                  child: Row(
                    mainAxisSize: MainAxisSize.min,
                    children: [
                      Text(
                        _discountExpanded ? '收起' : '展开全部',
                        style: LhTypography.sans(
                          size: 10,
                          color: DunesColors.resolve(context, _LhPlum.primary),
                          weight: FontWeight.w500,
                          context: context,
                        ),
                      ),
                      AnimatedRotation(
                        turns: _discountExpanded ? 0.5 : 0,
                        duration: const Duration(milliseconds: 200),
                        child: Icon(
                          Icons.keyboard_arrow_down_rounded,
                          size: 16,
                          color: DunesColors.resolve(context, _LhPlum.primary),
                        ),
                      ),
                    ],
                  ),
                ),
            ],
          ),
          const SizedBox(height: 4),
          Text(
            'calc_record · stat_amount × discount_rate = rebate_amount',
            style: LhTypography.sans(
              size: 9,
              color: DunesColors.resolve(context, LhColors.mute2),
              letterSpacing: 0.2,
              context: context,
            ),
          ),
          const SizedBox(height: 6),
          Wrap(
            spacing: 8,
            runSpacing: 4,
            children: [
              _buildDiscountLegendChip(
                '全额累进',
                DunesColors.resolve(context, _LhPlum.primary),
                fullCount,
              ),
              _buildDiscountLegendChip(
                '超额累进',
                DunesColors.resolve(context, LhColors.cnpc),
                excessCount,
              ),
              if (otherCount > 0)
                _buildDiscountLegendChip(
                  '其他',
                  DunesColors.resolve(context, LhColors.mute),
                  otherCount,
                ),
            ],
          ),
          const SizedBox(height: 10),
          for (int i = 0; i < visible.length; i++)
            Container(
              padding: const EdgeInsets.symmetric(vertical: 9),
              decoration: BoxDecoration(
                border: Border(
                  top: i == 0
                      ? BorderSide.none
                      : BorderSide(
                          color: DunesColors.resolve(
                            context,
                            LhColors.line2,
                            role: DunesColorRole.border,
                          ),
                          width: 0.5,
                        ),
                ),
              ),
              child: _buildDiscountRow(visible[i]),
            ),
          if (remaining > 0)
            GestureDetector(
              behavior: HitTestBehavior.opaque,
              onTap: () =>
                  setState(() => _discountExpanded = !_discountExpanded),
              child: Container(
                padding: const EdgeInsets.symmetric(vertical: 10),
                margin: const EdgeInsets.only(top: 4),
                decoration: BoxDecoration(
                  border: Border(
                    top: BorderSide(
                      color: DunesColors.resolve(
                        context,
                        LhColors.line2,
                        role: DunesColorRole.border,
                      ),
                      width: 0.5,
                    ),
                  ),
                ),
                alignment: Alignment.center,
                child: Row(
                  mainAxisAlignment: MainAxisAlignment.center,
                  mainAxisSize: MainAxisSize.min,
                  children: [
                    Text(
                      _discountExpanded ? '收起' : '展开剩余 $remaining 家',
                      style: LhTypography.sans(
                        size: 10.5,
                        color: DunesColors.resolve(context, _LhPlum.primary),
                        weight: FontWeight.w500,
                        letterSpacing: 0.3,
                        context: context,
                      ),
                    ),
                    if (_discountExpanded) ...[
                      const SizedBox(width: 2),
                      AnimatedRotation(
                        turns: 0.5,
                        duration: const Duration(milliseconds: 200),
                        child: Icon(
                          Icons.keyboard_arrow_down_rounded,
                          size: 14,
                          color: DunesColors.resolve(context, _LhPlum.primary),
                        ),
                      ),
                    ],
                  ],
                ),
              ),
            ),
        ],
      ),
    );
  }

  Widget _buildDiscountLegendChip(String label, Color color, int count) {
    return Container(
      padding: const EdgeInsets.symmetric(horizontal: 6, vertical: 2),
      decoration: BoxDecoration(
        color: DunesColors.resolveNullable(
          context,
          color.withAlpha(20),
          role: DunesColorRole.surface,
        ),
        borderRadius: BorderRadius.circular(4),
        border: Border.all(color: color.withAlpha(80), width: 0.5),
      ),
      child: Text(
        '$label $count',
        style: LhTypography.mono(
          size: 8.5,
          color: color,
          weight: FontWeight.w600,
          letterSpacing: 0.2,
          context: context,
        ),
      ),
    );
  }

  /// 折扣返点行：类型标签 + 档位 + 底表金额 + 合约/实收 ‰ + 阶梯进度
  /// 「过档多赚 8.6万 · 全额累进整笔重算」。算不出来返回 null —— 超额累进
  /// 缺速度、或后端没给下一档费率时，宁可不显示，也不拿门槛金额冒充收益。
  String? _discountGainLabel(_DiscountRow r) {
    final gain = _discountStripOf(r).gain;
    if (gain == null || gain <= 0) return null;
    final how = r.isExcessProgressive ? '超额累进只算超出部分' : '全额累进整笔重算';
    return '过档多赚 ${lighthouseDiscountCompactWan(gain)} · $how';
  }

  Widget _buildDiscountRow(_DiscountRow r) {
