    final modeLabel = r.mode ?? r.ruleType ?? '无规则';
    final baseHint = r.base != null ? ' · 基数${r.base}' : '';

    return Column(
      crossAxisAlignment: CrossAxisAlignment.start,
      children: [
        Row(
          crossAxisAlignment: CrossAxisAlignment.start,
          children: [
            SizedBox(
              width: 60,
              child: Text(
                r.province,
                style: LhTypography.sans(
                  size: 13,
                  color: DunesColors.resolve(context, LhColors.ink2),
                  weight: FontWeight.w600,
                  letterSpacing: 0.1,
                  context: context,
                ),
              ),
            ),
            Expanded(
              child: Wrap(
                spacing: 5,
                runSpacing: 3,
                crossAxisAlignment: WrapCrossAlignment.center,
                children: [
                  Container(
                    padding: const EdgeInsets.symmetric(
                      horizontal: 5,
                      vertical: 1,
                    ),
                    decoration: BoxDecoration(
                      color: DunesColors.resolveNullable(
                        context,
                        typeColor.withAlpha(18),
                        role: DunesColorRole.surface,
                      ),
                      borderRadius: BorderRadius.circular(3),
                      border: Border.all(
                        color: typeColor.withAlpha(100),
                        width: 0.5,
                      ),
                    ),
                    child: Text(
                      modeLabel,
                      style: LhTypography.mono(
                        size: 10,
                        color: typeColor,
                        weight: FontWeight.w600,
                        letterSpacing: 0.2,
                        context: context,
                      ),
                    ),
                  ),
                  if (r.tierLabel != null)
                    Text(
                      r.tierLabel!,
                      style: LhTypography.mono(
                        size: 10,
                        color: DunesColors.resolve(context, LhColors.mute2),
                        weight: FontWeight.w500,
                        context: context,
                      ),
                    ),
                  if (r.tierCount != null && r.tierCount! > 1)
                    Text(
                      '共${r.tierCount}档',
                      style: LhTypography.mono(
                        size: 9.5,
                        color: DunesColors.resolve(context, LhColors.mute2),
                        context: context,
                      ),
                    ),
                ],
              ),
            ),
            Column(
              crossAxisAlignment: CrossAxisAlignment.end,
              children: [
                Text(
                  '累计 ${(r.cur / 10000).toStringAsFixed(1)} 万$baseHint',
                  style: LhTypography.sans(
                    size: 11,
                    color: DunesColors.resolve(context, LhColors.mute),
                    letterSpacing: 0.1,
                    context: context,
                  ),
                ),
                RichText(
                  text: TextSpan(
                    children: [
                      TextSpan(
                        text: '返 ',
                        style: LhTypography.sans(
                          size: 10.5,
                          color: DunesColors.resolve(context, LhColors.mute2),
                          context: context,
                        ),
                      ),
                      TextSpan(
                        text: (r.rebate / 10000).toStringAsFixed(
                          r.rebate >= 1e5 ? 1 : 2,
                        ),
                        style: LhTypography.sans(
                          size: 10,
                          color: DunesColors.resolve(context, LhColors.neg),
                          weight: FontWeight.w700,
                          context: context,
                        ),
                      ),
                      TextSpan(
                        text: ' 万',
                        style: LhTypography.mono(
                          size: 10,
                          color: DunesColors.resolve(context, LhColors.mute),
                          context: context,
                        ),
                      ),
                    ],
                  ),
                ),
              ],
            ),
          ],
        ),
        const SizedBox(height: 6),
        Padding(
          // 与上方省份槽同宽，第二行才对得齐
          padding: const EdgeInsets.only(left: 60),
          child: Column(
            crossAxisAlignment: CrossAxisAlignment.start,
            children: [
              Text(
                _discountRateLine(r),
                style: LhTypography.mono(
                  size: 10,
                  color: DunesColors.resolve(context, LhColors.mute2),
                  weight: FontWeight.w600,
                  letterSpacing: 0.2,
                  context: context,
                ),
              ),
              if (r.dateRange != null) ...[
                const SizedBox(height: 3),
                Text(
                  '账期 ${r.dateRange} · 业务侧透传',
                  style: LhTypography.mono(
                    size: 9,
                    color: DunesColors.resolve(context, LhColors.mute2),
                    letterSpacing: 0.2,
                    context: context,
                  ),
                ),
              ],
              if (r.hasNext) ...[
                const SizedBox(height: 6),
                ClipRRect(
                  borderRadius: BorderRadius.circular(2),
                  child: LinearProgressIndicator(
                    value: (r.progress ?? 0).clamp(0.0, 1.0),
                    minHeight: 5,
