  // ───── List ───────────────────────────────────────────────────────────────

  Widget _buildList({bool embedded = false}) {
    // 软刷新时保留旧行（外层已压淡），列表不塌成 240 高的空白，页面不跳。
    if (_loading && !_softReloading) {
      return const SizedBox(height: 240);
    }
    if (_loadError != null) {
      if (_isNoPermissionError(_loadError)) {
        return _buildNoAccessView();
      }
      return Padding(
        padding: EdgeInsets.symmetric(
          horizontal: embedded ? 16 : 22,
          vertical: 40,
        ),
        child: Column(
          children: [
            Text(
              '数据加载失败',
              style: LhTypography.sans(
                size: 14,
                color: DunesColors.resolve(context, LhColors.ink),
                weight: FontWeight.w600,
                context: context,
              ),
            ),
            const SizedBox(height: 8),
            Text(
              _loadError!,
              textAlign: TextAlign.center,
              style: LhTypography.sans(
                size: 11,
                color: DunesColors.resolve(context, LhColors.mute),
                context: context,
              ),
            ),
            const SizedBox(height: 16),
            GestureDetector(
              onTap: () {
                setState(() {
                  _loading = true;
                  _loadError = null;
                });
                _load();
              },
              child: Container(
                padding: const EdgeInsets.symmetric(
                  horizontal: 14,
                  vertical: 8,
                ),
                decoration: BoxDecoration(
                  color: DunesColors.resolve(
                    context,
                    _LhPlum.soft,
                    role: DunesColorRole.surface,
                  ),
                  border: Border.all(
                    color: DunesColors.resolve(
                      context,
                      _LhPlum.primary,
                      role: DunesColorRole.border,
                    ),
                  ),
                  borderRadius: BorderRadius.circular(6),
                ),
                child: Text(
                  '重试',
                  style: LhTypography.sans(
                    size: 12,
                    color: DunesColors.resolve(context, _LhPlum.primary),
                    weight: FontWeight.w600,
                    context: context,
                  ),
                ),
              ),
            ),
          ],
        ),
      );
    }
    if (_loadingTabs.contains(_activeListTab) && _currentRows.isEmpty) {
      return const SizedBox(height: 240);
    }
    final tabError = _tabErrors[_activeListTab];
    if (tabError != null && _currentRows.isEmpty) {
      return Padding(
        padding: EdgeInsets.symmetric(
          horizontal: embedded ? 16 : 22,
          vertical: 40,
        ),
        child: Column(
          children: [
            Text(
              '当前列表加载失败',
              style: LhTypography.sans(
                size: 14,
                color: DunesColors.resolve(context, LhColors.ink),
                weight: FontWeight.w600,
                context: context,
              ),
            ),
            const SizedBox(height: 8),
            Text(
              tabError,
              textAlign: TextAlign.center,
              style: LhTypography.sans(
                size: 11,
                color: DunesColors.resolve(context, LhColors.mute),
                context: context,
              ),
            ),
            const SizedBox(height: 16),
            GestureDetector(
              onTap: () => _loadTab(_activeListTab, force: true),
              child: Container(
                padding: const EdgeInsets.symmetric(
                  horizontal: 14,
                  vertical: 8,
                ),
                decoration: BoxDecoration(
                  color: DunesColors.resolve(
                    context,
                    _LhPlum.soft,
                    role: DunesColorRole.surface,
                  ),
                  border: Border.all(
                    color: DunesColors.resolve(
                      context,
                      _LhPlum.primary,
                      role: DunesColorRole.border,
                    ),
                  ),
                  borderRadius: BorderRadius.circular(6),
                ),
                child: Text(
                  '重试当前分类',
                  style: LhTypography.sans(
                    size: 12,
                    color: DunesColors.resolve(context, _LhPlum.primary),
                    weight: FontWeight.w600,
                    context: context,
                  ),
                ),
              ),
            ),
          ],
        ),
      );
    }
    final rows = _ledgerSearchFiltered(_currentRows);
    if (rows.isEmpty) {
      // 空列表要说清楚是「没有数据」还是「筛没了」—— 后者用户自己能修。
      return Padding(
        padding: const EdgeInsets.symmetric(vertical: 40),
        child: Center(
          child: _ledgerSearchActive
              ? Column(
                  mainAxisSize: MainAxisSize.min,
                  children: [
                    Text(
                      '没有匹配「${_ledgerSearch.trim()}」的行',
                      style: LhTypography.sans(
                        size: 12,
                        color: DunesColors.resolve(context, LhColors.mute),
                        context: context,
                      ),
                    ),
                    const SizedBox(height: 10),
                    GestureDetector(
                      behavior: HitTestBehavior.opaque,
                      onTap: _closeLedgerSearch,
                      child: Text(
                        '清除查找',
                        style: LhTypography.sans(
                          size: 12,
                          color: DunesColors.resolve(context, _LhPlum.primary),
                          weight: FontWeight.w600,
                          context: context,
                        ),
                      ),
                    ),
                  ],
                )
              : Text(
                  '暂无数据',
                  style: LhTypography.sans(
                    size: 12,
                    color: DunesColors.resolve(context, LhColors.mute),
                    context: context,
                  ),
                ),
        ),
      );
    }
    final limit = _listLimit.clamp(0, rows.length);
    final visible = rows.take(limit).toList();
    final hasMore = limit < rows.length;

    // 2026-10 · 资产走势挪进主 Hero（大数卡底部「总资产」点开），供给页不再重复一块。
    final Widget? assetOverview =
        lighthouseSupplyListShowsAssetOverview &&
            _supplyProvinceViewActive &&
            !_ledgerSearchActive
        ? _buildSupplyAssetOverview(rows)
        : null;
    final listBody = Column(
      children: [
        _buildLedger(
          visible,
          shareRows: rows,
          showRowChevron: _tab != 'netTa',
          allowDefaultDetailOpen: _tab != 'netTa',
        ),
        if (hasMore)
          Padding(
            padding: const EdgeInsets.symmetric(vertical: 14),
            child: Text(
              _listLoadingMore
                  ? '加载中…'
                  : '下滑加载更多 · 已显示 $limit / ${rows.length}',
              textAlign: TextAlign.center,
              style: LhTypography.mono(
                size: 10,
                color: DunesColors.resolve(context, LhColors.mute2),
                weight: FontWeight.w500,
                context: context,
              ),
            ),
          )
        else if (rows.length > _listPageSize)
          Padding(
            padding: const EdgeInsets.symmetric(vertical: 12),
            child: Text(
              '已全部加载 · ${rows.length} 条',
              textAlign: TextAlign.center,
              style: LhTypography.mono(
                size: 10,
                color: DunesColors.resolve(context, LhColors.mute2),
                weight: FontWeight.w500,
                context: context,
              ),
            ),
          ),
      ],
    );

    if (embedded) {
      return Column(
        children: [
          if (assetOverview != null) ...[
            assetOverview,
            const SizedBox(height: 20),
          ],
          listBody,
          const SizedBox(height: 8),
        ],
      );
    }

    return Padding(
      padding: const EdgeInsets.fromLTRB(
        lighthouseHeroShellMarginH,
        4,
        lighthouseHeroShellMarginH,
        0,
      ),
      child: Column(
        children: [
          if (assetOverview != null) ...[
            assetOverview,
            // 总览是雾紫纸，省份列表是白卡：中间留足呼吸，不像被塞进同一张卡。
            const SizedBox(height: 20),
          ],
          Container(
            decoration: BoxDecoration(
              color: DunesColors.resolve(
                context,
                Colors.white,
                role: DunesColorRole.surface,
              ),
              borderRadius: BorderRadius.circular(12),
              border: Border.all(
                color: DunesColors.resolve(
                  context,
                  _LhPlum.lavender,
                  role: DunesColorRole.border,
                ),
                width: 1,
              ),
              boxShadow: [
                BoxShadow(
                  color: _LhPlum.deep.withAlpha(12),
                  blurRadius: 10,
                  spreadRadius: -4,
                  offset: const Offset(0, 3),
                ),
              ],
            ),
            clipBehavior: Clip.antiAlias,
            child: listBody,
          ),
        ],
      ),
    );
  }

