            ),
            Container(
              height: 0.6,
              color: DunesColors.resolve(
                context,
                LhColors.line2,
                role: DunesColorRole.surface,
              ),
            ),
            toggleRow(
              icon: Icons.straighten_rounded,
              label: '产品轴',
              hint: 'X 轴「产品」轴名',
              value: _cubeShowAxisNames,
              onChanged: (v) => setState(() => _cubeShowAxisNames = v),
            ),
            Container(
              height: 0.6,
              color: DunesColors.resolve(
                context,
                LhColors.line2,
                role: DunesColorRole.surface,
              ).withAlpha(120),
            ),
            toggleRow(
              icon: Icons.label_outline_rounded,
              label: '产品名',
              hint: '每条 X 轴的产品标签',
              value: _cubeShowProductTicks,
              onChanged: (v) => setState(() => _cubeShowProductTicks = v),
            ),
            Container(
              height: 0.6,
              color: DunesColors.resolve(
                context,
                LhColors.line2,
                role: DunesColorRole.surface,
              ).withAlpha(120),
            ),
            toggleRow(
              icon: Icons.apartment_rounded,
              label: '供给',
              hint: 'Y 轴轴名 + 供给方标签',
              value: _cubeShowSupplyLabels,
              onChanged: (v) => setState(() => _cubeShowSupplyLabels = v),
            ),
            Container(
              height: 0.6,
              color: DunesColors.resolve(
                context,
                LhColors.line2,
                role: DunesColorRole.surface,
              ).withAlpha(120),
            ),
            toggleRow(
              icon: Icons.hub_outlined,
              label: '渠道',
              hint: 'Z 轴轴名 + 渠道标签',
              value: _cubeShowChannelLabels,
              onChanged: (v) => setState(() => _cubeShowChannelLabels = v),
            ),
            Container(
              height: 0.6,
              color: DunesColors.resolve(
                context,
                LhColors.line2,
                role: DunesColorRole.surface,
              ).withAlpha(120),
