  // ── 冻结列第四行：折扣进度（供给一级） ──────────────────────────────
  //   口径取自资管透传的 am_price_rule_calc_record：
  //     · 后端给了下一档门槛（next_threshold / salesToNextTier）→ 真进度条 +「还差 X 万」
  //     · 只给了已达档位 → 退回档位刻度「第 2/4 档」+「返 X 万」
  //   两种形态高度一致（28pt 热区），所以同一屏里省与省之间不会参差。
  //   条子可点：打开同一行的折扣档位卡。圆钮仍只负责展开/收起整行。

  /// 折扣条组装。冻结列和折扣与返点区块共用这一份，口径不会两处漂移。
  /// 费率统一换算成 ‰：calc_record 的 discountRate 是小数（0.0023），
  /// 老规则表的 contractRatePermille 已经是 ‰，两边在这里对齐。
  LighthouseDiscountStrip _discountStripOf(
    _DiscountRow d, {
    bool preferGain = false,
  }) {
    return lighthouseDiscountStripFor(
      isFixed: d.isFixed,
      isCapped: d.isCapped,
      cur: d.cur,
      reached: d.isReached,
      nextThreshold: d.nextThreshold,
      gapToNext: d.gapToNextAmount,
      tierLevel: d.tierLevel,
      tierLabel: d.tierLabel,
      periodStart: d.periodStartTime ?? d.segmentStartTime,
      periodEnd: d.periodEndTime ?? d.segmentEndTime,
      calcMode: d.calcMode,
      currentPermille: d.discountRate != null
          ? d.discountRate! * 1000
          : d.contractRate,
      nextPermille: d.nextRate,
      gainFromApi: d.profitGain,
      preferGain: preferGain,
    );
  }

  // ═══════════════════════════════════════════════════════════════════════
  // 展开区 · 折扣档位卡
  //
  //   冻结列那条小条子回答「这一档怎么样了」，一句话；这张卡回答
  //   「一共几档、每档多少、我卡在哪、过档多赚多少」，一张图。
  //
  //   阶梯与进度轨是两层，不是一条：
  //     · 档位是序数（第几档）—— 上层等宽格，宽度不承载金额
  //     · 门槛是基数（多少钱）—— 下层连续轨，按金额线性，刻度落在各档门槛
  //   挤成一条的话：等宽就骗了金额，按金额等比又会把窄档压成看不见的一截。
  //
  //   浅色预测段够到下一条刻度 = 这个周期能过档，与走势图「实线已发生 /
  //   虚线预测」同一套语义，不用再学一遍。
  // ═══════════════════════════════════════════════════════════════════════
  Widget? _buildDiscountTierCard(
    Map<String, dynamic> r, {
    required String trendKey,
  }) {
    if (!lighthouseLedgerShowsDiscountUi) return null;
    if (_tab != 'supply' || _detailKey != null || r['isChild'] == true) {
      return null;
    }
    final name = r['name']?.toString().trim() ?? '';
    if (name.isEmpty) return null;
    final d = _discountRecordFor(r, name);
    if (d == null) return null;

    Widget focusShell({required Widget child}) {
      final focused = _discountFocusKey == trendKey;
      return AnimatedContainer(
        key: focused ? _discountCardKey : null,
        duration: const Duration(milliseconds: 400),
        padding: const EdgeInsets.fromLTRB(13, 12, 13, 11),
        decoration: BoxDecoration(
          color: DunesColors.resolve(
            context,
            LhColors.paper,
            role: DunesColorRole.surface,
          ),
          borderRadius: BorderRadius.circular(12),
          border: Border.all(
            color: focused
                ? DunesColors.resolve(
                    context,
                    _LhPlum.primary,
                    role: DunesColorRole.border,
                  ).withAlpha(120)
                : DunesColors.resolve(
                    context,
                    LhColors.line2,
                    role: DunesColorRole.border,
                  ),
            width: focused ? 1.2 : 1,
          ),
          boxShadow: focused
              ? [
                  BoxShadow(
                    color: _LhPlum.primary.withAlpha(36),
                    blurRadius: 0,
                    spreadRadius: 3,
                  ),
                ]
              : null,
        ),
        child: child,
      );
    }

    if (d.isFixed) {
      return focusShell(
        child: Text(
          '固定折扣，没有档位阶梯',
          style: LhTypography.sans(
            size: 12.5,
            color: DunesColors.resolve(context, LhColors.ink2),
            height: 1.4,
            context: context,
          ),
        ),
      );
    }

    final ladder =
        d.ladder ??
        LighthouseDiscountLadder.minimal(
          currentLevel: d.tierLevel ?? 1,
          currentPermille: d.discountRate != null
              ? d.discountRate! * 1000
              : d.contractRate,
          nextPermille: d.nextRate,
          nextThreshold: d.nextThreshold,
        );
    if (ladder == null || ladder.isEmpty) {
      return focusShell(
        child: Text(
          '暂无档位阶梯',
          style: LhTypography.sans(
            size: 12.5,
            color: DunesColors.resolve(context, LhColors.ink2),
            height: 1.4,
            context: context,
          ),
        ),
      );
    }

    final color = _discountTypeColor(d);
    final focused = _discountFocusKey == trendKey;
    final pace = lighthouseDiscountPace(
      startRaw: d.periodStartTime ?? d.segmentStartTime,
      endRaw: d.periodEndTime ?? d.segmentEndTime,
    );
    final projected = lighthouseDiscountProjected(cur: d.cur, pace: pace);
    final next = ladder.next;
    final isFull = d.calcMode == 2;

    // 「过档多赚」两个来源不是一个数，所以文案也不能一样：
    //   后端 profitGain = 下一档门槛 × 费率差（确定值）→「至少多赚」
    //   本地 = 按当前速度到期末的量 × 费率差（估计值）→「按当前速度多赚」
    // 旧版把两者混在一个词里，同一行能差出十几倍。
    final apiGain = d.profitGain;
    final localGain = lighthouseDiscountGainAtNextTier(
      calcMode: d.calcMode,
      target: d.nextThreshold,
      currentPermille: d.discountRate != null
          ? d.discountRate! * 1000
          : d.contractRate,
      nextPermille: d.nextRate,
      projected: projected,
    );

    TextStyle metaStyle() => LhTypography.mono(
      size: 9,
      color: DunesColors.resolve(context, LhColors.mute),
      weight: FontWeight.w500,
      height: 1.3,
      context: context,
    );

    // ── 阶梯：N 个等宽格 ────────────────────────────────────────────
    Widget tierCell(LighthouseDiscountTier t) {
      final isCur = t.level == ladder.currentLevel;
      return Expanded(
        child: Container(
          padding: const EdgeInsets.fromLTRB(4, 6, 4, 7),
          color: isCur
              ? DunesColors.resolve(
                  context,
                  LhColors.purpleSoft,
                  role: DunesColorRole.surface,
                )
              : (t.reached
                    ? DunesColors.resolve(
                        context,
                        LhColors.pos,
                        role: DunesColorRole.surface,
                      ).withAlpha(16)
                    : DunesColors.resolve(
                        context,
                        LhColors.paper,
                        role: DunesColorRole.surface,
                      )),
          child: Column(
            mainAxisSize: MainAxisSize.min,
            children: [
              Row(
                mainAxisAlignment: MainAxisAlignment.center,
                children: [
                  if (t.reached && !isCur) ...[
                    Icon(
                      Icons.check_rounded,
                      size: 8,
                      color: DunesColors.resolve(context, LhColors.pos),
                    ),
                    const SizedBox(width: 2),
                  ] else if (isCur) ...[
                    Container(
                      width: 4,
                      height: 4,
                      decoration: BoxDecoration(
                        color: DunesColors.resolve(
                          context,
                          _LhPlum.primary,
                          role: DunesColorRole.surface,
                        ),
                        shape: BoxShape.circle,
                      ),
                    ),
                    const SizedBox(width: 3),
                  ],
                  Flexible(
                    child: LhScrollText(
                      t.label,
                      style: LhTypography.mono(
                        size: 9,
                        color: isCur
                            ? DunesColors.resolve(context, _LhPlum.deep)
                            : (t.reached
                                  ? DunesColors.resolve(context, LhColors.pos)
                                  : DunesColors.resolve(
                                      context,
                                      LhColors.mute,
                                    )),
                        weight: isCur ? FontWeight.w700 : FontWeight.w500,
                        letterSpacing: 0.3,
                        height: 1.0,
                        context: context,
                      ),
                    ),
                  ),
                ],
              ),
              const SizedBox(height: 3),
              // 占位格一律画「—」。阶梯几乎都是不等距的，按等差猜门槛
              // 猜出来的数会被业务当成真的 —— 宁可空着。
              Text.rich(
                TextSpan(
                  children: t.isPlaceholder
                      ? [
                          TextSpan(
                            text: '—',
                            style: LhTypography.mono(
                              size: 13,
                              color: DunesColors.resolve(
                                context,
                                LhColors.mute2,
                              ),
                              weight: FontWeight.w500,
                              height: 1.0,
                              context: context,
                            ),
                          ),
                        ]
                      : [
                          TextSpan(
                            text: _lhTrimZero(t.permille),
                            style: _tabular(
                              LhTypography.mono(
                                size: 13,
                                color: isCur
                                    ? DunesColors.resolve(context, _LhPlum.deep)
                                    : DunesColors.resolve(
                                        context,
                                        LhColors.ink2,
                                      ),
                                weight: FontWeight.w700,
                                height: 1.0,
                                context: context,
                              ),
                            ),
                          ),
                          TextSpan(
                            text: '‰',
                            style: LhTypography.mono(
                              size: 8.5,
                              color: DunesColors.resolve(
                                context,
                                LhColors.mute,
                              ),
                              height: 1.0,
                              context: context,
                            ),
                          ),
                        ],
                ),
                maxLines: 1,
              ),
              const SizedBox(height: 3),
              LhScrollText(
                t.isPlaceholder
                    ? '—'
                    : (t.minValue <= 0
                          ? '0 起'
                          : '${lighthouseDiscountCompactWan(t.minValue)} 起'),
                style: _tabular(
                  LhTypography.mono(
                    size: 8.5,
                    color: DunesColors.resolve(context, LhColors.mute2),
                    height: 1.0,
                    context: context,
                  ),
                ),
              ),
            ],
          ),
        ),
      );
    }

    // ── 进度轨：按金额线性，刻度落在各档门槛 ────────────────────────
    Widget track() {
      final fill = ladder.fracOf(d.cur);
      final fore = projected == null ? null : ladder.fracOf(projected);
      return LayoutBuilder(
        builder: (context, c) {
          final w = c.maxWidth;
          return Column(
            crossAxisAlignment: CrossAxisAlignment.start,
            children: [
              SizedBox(
                height: 13,
                child: Stack(
                  clipBehavior: Clip.none,
                  children: [
                    Positioned(
                      left: (w * fill - 24).clamp(0.0, w - 48),
                      width: 48,
                      child: Text(
                        lighthouseDiscountCompactWan(d.cur),
                        textAlign: TextAlign.center,
                        style: _tabular(
                          LhTypography.mono(
                            size: 8.5,
                            color: DunesColors.resolve(context, LhColors.ink),
                            weight: FontWeight.w700,
                            height: 1.0,
                            context: context,
                          ),
                        ),
                      ),
                    ),
                  ],
                ),
              ),
              SizedBox(
                height: 7,
                child: Stack(
                  clipBehavior: Clip.none,
                  children: [
                    Container(
                      width: w,
                      height: 7,
                      decoration: BoxDecoration(
                        color: DunesColors.resolve(
                          context,
                          LhColors.line2,
                          role: DunesColorRole.surface,
                        ),
                        borderRadius: BorderRadius.circular(4),
                      ),
                    ),
                    if (fore != null && fore > fill)
                      Container(
                        width: w * fore,
                        height: 7,
                        decoration: BoxDecoration(
                          color: DunesColors.resolveNullable(
                            context,
                            color.withAlpha(70),
                            role: DunesColorRole.surface,
                          ),
                          borderRadius: BorderRadius.circular(4),
                        ),
                      ),
                    Container(
                      width: w * fill,
                      height: 7,
                      decoration: BoxDecoration(
                        color: DunesColors.resolveNullable(
                          context,
                          color,
                          role: DunesColorRole.surface,
                        ),
                        borderRadius: BorderRadius.circular(4),
                      ),
                    ),
                    // 刻度：各档门槛。压在填充之上，用纸色画才看得见。
                    for (final t in ladder.tiers)
                      if (!t.isPlaceholder && t.minValue > 0)
                        Positioned(
                          left: (w * ladder.fracOf(t.minValue)).clamp(
                            0.0,
                            w - 1,
                          ),
                          top: 0,
                          bottom: 0,
                          width: 1,
                          child: Container(
                            color: DunesColors.resolve(
                              context,
                              LhColors.paper,
                              role: DunesColorRole.surface,
                            ).withAlpha(200),
                          ),
                        ),
                    // 当前位置指针
                    Positioned(
                      left: (w * fill).clamp(0.0, w - 1.5),
                      top: -2,
                      bottom: -2,
                      width: 1.5,
                      child: Container(
                        color: DunesColors.resolve(
                          context,
                          LhColors.ink,
                          role: DunesColorRole.surface,
                        ),
                      ),
                    ),
                  ],
                ),
              ),
              const SizedBox(height: 5),
              SizedBox(
                height: 11,
                child: Stack(
                  children: [
                    Positioned(left: 0, child: Text('0', style: metaStyle())),
                    for (final t in ladder.tiers)
                      if (!t.isPlaceholder && t.minValue > 0)
                        Positioned(
                          left: (w * ladder.fracOf(t.minValue) - 20).clamp(
                            0.0,
                            w - 40,
                          ),
                          width: 40,
                          child: Text(
                            lighthouseDiscountCompactWan(t.minValue),
                            textAlign: TextAlign.center,
                            style: _tabular(metaStyle()),
                          ),
                        ),
                    if (!ladder.hasFullLadder)
                      Positioned(
                        right: 0,
                        child: Text('—', style: metaStyle()),
                      ),
                  ],
                ),
              ),
            ],
          );
        },
      );
    }

    // ── 结论行 ──────────────────────────────────────────────────────
    Widget verdict(String key, List<InlineSpan> spans) {
      return Padding(
        padding: const EdgeInsets.only(bottom: 6),
        child: Row(
          crossAxisAlignment: CrossAxisAlignment.start,
          children: [
            SizedBox(
              width: 40,
              child: Text(
                key,
                style: LhTypography.mono(
                  size: 9,
                  color: DunesColors.resolve(context, LhColors.mute2),
                  letterSpacing: 0.4,
                  height: 1.5,
                  context: context,
                ),
              ),
            ),
            const SizedBox(width: 6),
            Expanded(
              child: Text.rich(
                TextSpan(
                  children: spans,
                  style: LhTypography.sans(
                    size: 11,
                    color: DunesColors.resolve(context, LhColors.ink2),
                    height: 1.5,
                    context: context,
                  ),
                ),
              ),
            ),
          ],
        ),
      );
    }

    TextSpan strong(String text, {Color? c}) => TextSpan(
      text: text,
      style: _tabular(
        LhTypography.mono(
          size: 11,
          color: c ?? DunesColors.resolve(context, LhColors.ink),
          weight: FontWeight.w700,
          height: 1.5,
          context: context,
        ),
      ),
    );

    final reachDay = next == null || next.isPlaceholder
        ? null
        : lighthouseDiscountReachDay(
            cur: d.cur,
            threshold: next.minValue,
            pace: pace,
          );

    final verdicts = <Widget>[];
    if (next != null && d.gapToNextAmount != null && d.gapToNextAmount! > 0) {
      verdicts.add(
        verdict('还差', [
          strong(lighthouseDiscountCompactWan(d.gapToNextAmount!), c: color),
          TextSpan(text: ' 到${next.label}'),
          if (!next.isPlaceholder && d.contractRate != null) ...[
            const TextSpan(text: '，费率 '),
            strong(
              '${_lhTrimZero(d.contractRate!)}‰ → ${_lhTrimZero(next.permille)}‰',
            ),
          ],
        ]),
      );
    }
    if (pace != null) {
      verdicts.add(
        verdict('按速度', [
          if (projected != null) ...[
            const TextSpan(text: '日均 '),
            strong(lighthouseDiscountCompactWan(d.cur / pace.elapsedDays)),
            const TextSpan(text: '，'),
          ],
          if (reachDay != null) ...[
            strong(
              '${reachDay.month.toString().padLeft(2, '0')}.'
              '${reachDay.day.toString().padLeft(2, '0')}',
            ),
            TextSpan(text: ' 过${next?.label ?? '下一档'}；'),
          ] else if (next != null)
            const TextSpan(text: '这个周期到不了下一档；'),
          if (projected != null) ...[
            const TextSpan(text: '期末停在 '),
            strong(lighthouseDiscountCompactWan(projected)),
          ],
        ]),
      );
    }
    if (apiGain != null && apiGain > 0) {
      verdicts.add(
        verdict('至少赚', [
          strong(
            '+${lighthouseDiscountCompactWan(apiGain)}',
            c: DunesColors.resolve(context, LhColors.pos),
          ),
          const TextSpan(text: ' 返点（按下一档门槛算）'),
        ]),
      );
    } else if (localGain != null && localGain > 0) {
      verdicts.add(
        verdict('估计赚', [
          strong(
            '+${lighthouseDiscountCompactWan(localGain)}',
            c: DunesColors.resolve(context, LhColors.pos),
          ),
          const TextSpan(text: ' 返点（按当前速度到期末算）'),
        ]),
      );
    }

    final ruleMeta = [
      if (d.ruleType != null && d.ruleType!.isNotEmpty) d.ruleType!,
      if (d.base != null && d.base!.isNotEmpty) d.base!,
    ].join(' · ');

    final periodLabel = lighthouseDiscountDateRange(
      d.periodStartTime ?? d.segmentStartTime,
      d.periodEndTime ?? d.segmentEndTime,
    );

    return AnimatedContainer(
      key: focused ? _discountCardKey : null,
      duration: const Duration(milliseconds: 400),
      padding: const EdgeInsets.fromLTRB(13, 12, 13, 11),
      decoration: BoxDecoration(
        color: DunesColors.resolve(
          context,
          LhColors.paper,
          role: DunesColorRole.surface,
        ),
        borderRadius: BorderRadius.circular(12),
        border: Border.all(
          color: focused
              ? DunesColors.resolve(
                  context,
                  _LhPlum.primary,
                  role: DunesColorRole.border,
                ).withAlpha(120)
              : DunesColors.resolve(
                  context,
                  LhColors.line2,
                  role: DunesColorRole.border,
                ),
          width: focused ? 1.2 : 1,
        ),
        boxShadow: focused
            ? [
                BoxShadow(
                  color: _LhPlum.primary.withAlpha(36),
                  blurRadius: 0,
                  spreadRadius: 3,
                ),
              ]
            : null,
      ),
      child: Column(
        crossAxisAlignment: CrossAxisAlignment.start,
        children: [
          Row(
            children: [
              Flexible(
                child: LhScrollText(
                  d.isCapped
                      ? '共 ${ladder.tiers.length} 档，已封顶'
                      : '共 ${ladder.tiers.length} 档，当前第 ${ladder.currentLevel} 档',
                  style: LhTypography.sans(
                    size: 12.5,
                    color: DunesColors.resolve(context, LhColors.ink),
                    weight: FontWeight.w600,
                    letterSpacing: -0.1,
                    context: context,
                  ),
                ),
              ),
              const SizedBox(width: 7),
              Container(
                padding: const EdgeInsets.symmetric(horizontal: 5, vertical: 2),
                decoration: BoxDecoration(
                  color: DunesColors.resolveNullable(
                    context,
                    color.withAlpha(30),
                    role: DunesColorRole.surface,
                  ),
                  borderRadius: BorderRadius.circular(4),
                ),
                child: Text(
                  isFull ? '全额累进' : '超额累进',
                  style: LhTypography.mono(
                    size: 8.5,
                    color: color,
                    weight: FontWeight.w700,
                    letterSpacing: 0.4,
                    height: 1.0,
                    context: context,
                  ),
                ),
              ),
              const Spacer(),
              if (ruleMeta.isNotEmpty) Text(ruleMeta, style: metaStyle()),
            ],
          ),
          if (periodLabel != null || pace != null) ...[
            const SizedBox(height: 3),
            Text(
              [
                if (periodLabel != null) '周期 $periodLabel',
                if (pace != null) '已过 ${pace.elapsedDays} 天',
                if (pace != null) '剩 ${pace.remainDays} 天',
              ].join(' · '),
              style: _tabular(metaStyle()),
            ),
          ],
          const SizedBox(height: 11),
          ClipRRect(
            borderRadius: BorderRadius.circular(8),
            child: Container(
              decoration: BoxDecoration(
                border: Border.all(
                  color: DunesColors.resolve(
                    context,
                    LhColors.line2,
                    role: DunesColorRole.border,
                  ),
                  width: 1,
                ),
                borderRadius: BorderRadius.circular(8),
              ),
              child: Row(
                crossAxisAlignment: CrossAxisAlignment.stretch,
                children: [
                  for (var i = 0; i < ladder.tiers.length; i++) ...[
                    if (i > 0)
                      Container(
                        width: 1,
                        color: DunesColors.resolve(
                          context,
                          LhColors.line2,
                          role: DunesColorRole.surface,
                        ),
                      ),
                    tierCell(ladder.tiers[i]),
                  ],
                ],
              ),
            ),
          ),
          if (ladder.axisMax > 0) ...[const SizedBox(height: 9), track()],
          if (verdicts.isNotEmpty) ...[
            const SizedBox(height: 11),
            Container(
              height: 0.5,
              color: DunesColors.resolve(
                context,
                LhColors.line2,
                role: DunesColorRole.surface,
              ),
            ),
            const SizedBox(height: 10),
            ...verdicts,
          ],
          const SizedBox(height: 3),
          Container(
            padding: const EdgeInsets.fromLTRB(9, 7, 9, 8),
            decoration: BoxDecoration(
              color: DunesColors.resolve(
                context,
                LhColors.mist,
                role: DunesColorRole.surface,
              ),
              borderRadius: BorderRadius.circular(8),
            ),
            child: Text.rich(
              TextSpan(
                children: [
                  TextSpan(
                    text: isFull ? '全额累进' : '超额累进',
                    style: LhTypography.sans(
                      size: 10,
                      color: DunesColors.resolve(context, LhColors.ink),
                      weight: FontWeight.w700,
                      height: 1.55,
                      context: context,
                    ),
                  ),
                  TextSpan(
                    text: isFull
                        ? '：过线那一刻整个累计基数按新费率重算，收益是一次性跳变。'
                        : '：只有超出门槛的部分享新费率，过线本身不多赚，收益取决于过线之后还能做多少。',
                  ),
                ],
                style: LhTypography.sans(
                  size: 10,
                  color: DunesColors.resolve(context, LhColors.ink2),
                  height: 1.55,
                  context: context,
                ),
              ),
            ),
          ),
          if (!ladder.hasFullLadder) ...[
            const SizedBox(height: 8),
            Container(
              padding: const EdgeInsets.fromLTRB(9, 7, 9, 8),
              decoration: BoxDecoration(
                color: DunesColors.resolve(
                  context,
                  LhColors.copperSoft,
                  role: DunesColorRole.surface,
                ),
                border: Border.all(
                  color: DunesColors.resolve(
                    context,
                    LhColors.copper,
                    role: DunesColorRole.border,
                  ).withAlpha(70),
                  width: 0.7,
                ),
                borderRadius: BorderRadius.circular(8),
              ),
              child: Text(
                '这条规则的完整阶梯后端还没下发，只有当前档与下一档是真数，'
                '其余档位的门槛与费率画「—」。等 /lighthouse/discounts 补上 tiers 字段。',
                style: LhTypography.sans(
                  size: 10,
                  color: DunesColors.resolve(context, LhColors.ink2),
                  height: 1.55,
