          opColor: accent,
          label: '期末预付',
          note: prepaymentNote,
          badge: prepaidTag(),
          sharedPrepayment: true,
          linkFromLeft: true,
          amount: pre,
          lit: linked,
          onTap: canLink ? toggleLink : null,
        ),
        line(
          op: '−',
          opColor: ink2,
          label: '可动用额度',
          hint: '资金池',
          amount: v('fundPoolBalance'),
        ),
        line(
          op: '−',
          opColor: ink2,
          label: '券资产',
          amount: v('stockAndSyncVouchers'),
          parts: [
            ('在手券', v('inventoryVoucherBalance')),
            ('＋ 同步在途', v('contractVoucherBalance')),
