    return Column(
      crossAxisAlignment: CrossAxisAlignment.stretch,
      mainAxisSize: MainAxisSize.min,
      children: [
        pair(assetsCard, reconCard),
        SizedBox(height: _fs(8)),
        profitStrip,
        SizedBox(height: _fs(6)),
      ],
