  Widget _fundPoolSectionCard(
    LighthouseFundPoolSectionSpec spec,
    LighthouseFundPoolAmounts? amounts,
    Widget Function({
      required String title,
      required IconData icon,
      required Color accent,
      required Color tint,
      required Color edge,
      required Color titleColor,
      required List<Widget> items,
      int columns,
      int? flowStart,
    })
    section, {
    required Map<String, double?> externals,
    required String? traced,
    required ValueChanged<String> onTraceTap,
  }) {
    // 跟账本指标格同款：标签深一档、半粗，数字最深。
    Widget metricLabel(String label) => LhScrollText(
      label,
      maxLines: 1,
      overflow: TextOverflow.ellipsis,
      style: LhTypography.sans(
        size: _fs(9.5),
        color: DunesColors.resolve(context, LhColors.ink2),
        weight: FontWeight.w600,
        height: 1.0,
        context: context,
      ),
    );

    Widget amountItem(LighthouseFundPoolMetricSpec metric) {
      if (metric.key == 'invoiceOriginals') {
        return Padding(
          padding: EdgeInsets.all(_fs(3)),
          child: _fundPoolInvoiceOriginals(
            metricLabel,
            amounts?.invoiceOriginals ?? const [],
          ),
        );
      }
      return _fundPoolMetricAmount(
        metricLabel,
        metric.label,
        // 当月 / 当日利润不在 /fund-pool 里，走外部喂进来的值。
        lighthouseFundPoolExternalMetricKeys.contains(metric.key)
            ? externals[metric.key]
            : lighthouseFundPoolAmountByKey(amounts, metric.key),
        metricKey: metric.key,
        traced: traced,
        onTraceTap: onTraceTap,
      );
    }

    final (icon, accent, tint, edge, titleColor) = _fundPoolSectionPalette(
      spec.kind,
    );
    return section(
      title: spec.title,
      icon: icon,
      accent: accent,
      tint: tint,
      edge: edge,
      titleColor: titleColor,
      columns: spec.kind == LighthouseFundPoolSectionKind.invoice
          ? 1
          : (spec.metrics.length >= 3 ? 2 : 1),
      flowStart: spec.flowStartIndex,
      items: [for (final metric in spec.metrics) amountItem(metric)],
    );
  }

  /// 展开面板底部的口径条 —— 八个数里只有两个是算出来的，把来源写出来。
  ///
  /// 不塞进卡片：卡片是半宽的（≈160dp），这两条放进去只能滚动，没人读滚动的
  /// 公式。也不给它自己套一层卡：它是脚注不是内容，第五张卡会跟上面四张抢位置。
  /// 就两行小字贴在面板底部，去掉括号把减号分配开，一行放得下。
  Widget _fundPoolFormulaBar(String panel, {String? traced}) {
    final formulas = lighthouseFundPoolPanelFormulas(panel);
    if (formulas.isEmpty) return const SizedBox.shrink();
    return Padding(
      padding: EdgeInsets.fromLTRB(_fs(2), _fs(9), _fs(2), 0),
      child: Column(
        crossAxisAlignment: CrossAxisAlignment.stretch,
        mainAxisSize: MainAxisSize.min,
        children: [
          for (var i = 0; i < formulas.length; i++) ...[
            if (i > 0) SizedBox(height: _fs(5)),
            _fundPoolFormulaLine(
              formulas[i],
              active: traced == null || traced == formulas[i].resultKey,
            ),
          ],
        ],
      ),
    );
  }

  /// 一条算式。沿用指标详情页 `≡` 公式条的 token 分色：
  /// 运算符吃结果所在卡的主色，术语保持中性墨色。
  Widget _fundPoolFormulaLine(
    LighthouseFundPoolFormula formula, {
    bool active = true,
  }) {
    final (_, accent, _, _, titleColor) = _fundPoolSectionPalette(formula.kind);
    bool isOperator(String t) => t.length == 1 && '+−×÷=()'.contains(t);
    final spans = <InlineSpan>[
      TextSpan(
        text: formula.result,
        style: LhTypography.mono(
          size: _fs(9),
          color: active ? titleColor : titleColor.withAlpha(80),
          weight: FontWeight.w700,
          letterSpacing: 0.2,
          height: 1.0,
          context: context,
        ),
      ),
      TextSpan(
        text: ' = ',
        style: LhTypography.mono(
          size: _fs(9),
          color: active ? accent : accent.withAlpha(70),
          weight: FontWeight.w700,
          height: 1.0,
          context: context,
        ),
      ),
    ];
    final tokens = formula.expression.split(' ');
    for (var i = 0; i < tokens.length; i++) {
      final t = tokens[i];
      if (t.isEmpty) continue;
      final op = isOperator(t);
      spans.add(
        TextSpan(
          text: t,
          style: LhTypography.mono(
            size: _fs(9),
            color: op
                ? (active ? accent : accent.withAlpha(70))
                : (active
                      ? DunesColors.resolve(context, LhColors.mute2)
                      : DunesColors.resolve(
                          context,
                          LhColors.mute2,
                        ).withAlpha(90)),
            weight: op ? FontWeight.w700 : FontWeight.w500,
            letterSpacing: 0.2,
            height: 1.0,
            context: context,
          ),
        ),
      );
      if (i < tokens.length - 1) spans.add(const TextSpan(text: ' '));
    }
    return LhScrollRichText(
      text: TextSpan(children: spans),
      maxLines: 1,
      overflow: TextOverflow.ellipsis,
    );
  }

  /// 资金池分区四色板 —— (图标, 主色, 卡底, 描边, 标题色)。
  ///
  /// 主色四个跑过色盲分离校验：紫 / 琥珀 / 品红 / 绿。原来的对账蓝 #4A6FA5
  /// 和资产绿 #2C8A7A 正常视力下只差 ΔE 12.3（门槛 15），彩度也低于下限，
  /// 铺成整块色底会直接糊在一起，所以对账换成品红。
  /// 紫和蓝不能同时出现：色盲模式下这两个色的分离度只有 ΔE 1.8。
  (IconData, Color, Color, Color, Color) _fundPoolSectionPalette(
    LighthouseFundPoolSectionKind kind,
  ) => switch (kind) {
    // 票税是独立面板，不与上面四张卡同屏，沿用蓝不冲突。
    LighthouseFundPoolSectionKind.invoice => (
      Icons.receipt_long_rounded,
      DunesColors.resolve(context, const Color(0xFF2F6FD0)),
      DunesColors.resolve(context, const Color(0xFFEFF4FD)),
      DunesColors.resolve(context, const Color(0xFFCFDDF7)),
      DunesColors.resolve(context, const Color(0xFF1F55A8)),
    ),
    LighthouseFundPoolSectionKind.assets => (
      Icons.show_chart_rounded,
      DunesColors.resolve(context, const Color(0xFF1E9E72)),
      DunesColors.resolve(context, const Color(0xFFEDF8F3)),
      DunesColors.resolve(context, const Color(0xFFC6E7D9)),
      DunesColors.resolve(context, const Color(0xFF146B4E)),
    ),
    LighthouseFundPoolSectionKind.funds => (
      Icons.account_balance_wallet_rounded,
      DunesColors.resolve(context, const Color(0xFF7B5CD8)),
      DunesColors.resolve(context, const Color(0xFFF6F3FD)),
      DunesColors.resolve(context, const Color(0xFFDCD1F5)),
      DunesColors.resolve(context, const Color(0xFF5B3FB0)),
    ),
    LighthouseFundPoolSectionKind.vouchers => (
      Icons.confirmation_number_rounded,
      DunesColors.resolve(context, const Color(0xFFC4791C)),
      DunesColors.resolve(context, const Color(0xFFFCF6EC)),
      DunesColors.resolve(context, const Color(0xFFEDDCC2)),
      DunesColors.resolve(context, const Color(0xFF8F550F)),
    ),
    LighthouseFundPoolSectionKind.recon => (
      Icons.balance_rounded,
      DunesColors.resolve(context, const Color(0xFFB8478F)),
      DunesColors.resolve(context, const Color(0xFFFBF1F7)),
      DunesColors.resolve(context, const Color(0xFFEFD2E4)),
      DunesColors.resolve(context, const Color(0xFF8E3169)),
    ),
  };

  /// 资产四宫格里每一格的底色 —— 跟账本指标格同一块浅紫灰。
  Color _fundPoolTileColor() => DunesColors.resolve(
    context,
    const Color(0xFFF3F1F7),
    role: DunesColorRole.surface,
  );

  Widget _fundPoolMetricAmount(
    Widget Function(String) metricLabel,
    String label,
    double? amount, {
    String metricKey = '',
    String? traced,
    ValueChanged<String>? onTraceTap,
  }) {
    final parts = lighthouseFormatFundPoolWanParts(amount);
    final missing = parts.number == '—';
    // 增量格：数字前挂 ↑ / ↓，正负吃涨跌色（涨红跌绿，与列表环比同一套）。
    final isGrowth =
        !missing && lighthouseFundPoolGrowthMetricKeys.contains(metricKey);
    final growthUp = isGrowth && (amount ?? 0) >= 0;
    final growthColor = growthUp
        ? DunesColors.resolve(context, LhColors.neg)
        : DunesColors.resolve(context, LhColors.pos);
    // 这一格是结果格（挂箭头），还是当前被追溯的加数格（点亮）？
    final ownFormula = lighthouseFundPoolFormulaForKey(metricKey);
    final isTraceOpen = traced != null && traced == metricKey;
    final isSource = lighthouseFundPoolMetricIsTraced(traced, metricKey);
    // 点亮色跟着「被追溯的那条式子」走，不跟着格子所在的卡走 ——
    // 这样一眼看出这三格属于资产合计、那四格属于系统差异。
    final tracedFormula = traced == null
        ? null
        : lighthouseFundPoolFormulaForKey(traced);
    final traceAccent = tracedFormula == null
        ? DunesColors.resolve(context, LhColors.ink2)
        : _fundPoolSectionPalette(tracedFormula.kind).$2;
    final ownAccent = ownFormula == null
        ? DunesColors.resolve(context, LhColors.ink2)
        : _fundPoolSectionPalette(ownFormula.kind).$2;

    // 会变的两格：右上角一个小字说状态，格子本身不变（跟账本「利润 ↓ ↑360%」
    // 那个位置一样）。期末预付：正 = 我方预付、负 = 欠供应商；
    // 对账差额：0 = 已对平、非 0 = 待核查。
    final (String, Color)? status = missing
        ? null
        : switch (metricKey) {
            'endingPrepaymentBalance' when (amount ?? 0) > 0 => (
              '我方预付',
              DunesColors.resolve(context, _LhPlum.deep),
            ),
            'endingPrepaymentBalance' when (amount ?? 0) < 0 => (
              '欠供应商',
              DunesColors.resolve(context, const Color(0xFFB06E12)),
            ),
            'systemDifference' when (amount ?? 0).abs() < 50 => (
              '✓ 已对平',
              DunesColors.resolve(context, const Color(0xFF0E9A57)),
            ),
            'systemDifference' => (
              '有差额',
              DunesColors.resolve(context, LhColors.mute2),
            ),
            _ => null,
          };
    // 差额不为 0 不一定是错（记账时间差、口径不同、公式没包含的项），
    // 所以不再把数字染红。
    const diffAlarm = false;
    Widget? statusTag() => status == null
        ? null
        : Padding(
            padding: EdgeInsets.only(left: _fs(4)),
            child: Text(
              status.$1,
              maxLines: 1,
              style: LhTypography.sans(
                size: _fs(8.5),
                color: status.$2,
                weight: FontWeight.w700,
                height: 1.0,
                context: context,
              ),
            ),
          );

    final body = Column(
      crossAxisAlignment: CrossAxisAlignment.start,
      mainAxisSize: MainAxisSize.min,
      children: [
        if (ownFormula != null && onTraceTap != null)
          // 结果格：标签后跟一个箭头。箭头只是提示，点击区是整格 ——
          // 12dp 的小圆在手机上点不中。
          Row(
            children: [
              Flexible(child: metricLabel(label)),
              SizedBox(width: _fs(3)),
              Container(
                padding: EdgeInsets.all(_fs(1.5)),
                decoration: BoxDecoration(
                  color: DunesColors.resolveNullable(
                    context,
                    isTraceOpen ? ownAccent : Colors.transparent,
                    role: DunesColorRole.surface,
                  ),
                  shape: BoxShape.circle,
                ),
                child: Icon(
                  isTraceOpen
                      ? Icons.arrow_back_rounded
                      : Icons.arrow_forward_rounded,
                  size: _fs(9.5),
                  color: isTraceOpen
                      ? DunesColors.resolve(context, LhColors.paper)
                      : ownAccent,
                ),
              ),
              if (status != null) ...[const Spacer(), statusTag()!],
            ],
          )
        else if (status != null)
          Row(
            children: [
              Flexible(child: metricLabel(label)),
              const Spacer(),
              statusTag()!,
            ],
          )
        else
          metricLabel(label),
        SizedBox(height: _fs(3)),
        LhScrollRichText(
          text: TextSpan(
            children: [
              if (isGrowth)
                TextSpan(
                  text: growthUp ? '↑' : '↓',
                  style: _tabular(
                    LhTypography.mono(
                      size: _fs(lighthouseLedgerValueFontSize - 2),
                      color: growthColor,
                      weight: FontWeight.w700,
                      height: 1.0,
                      context: context,
                    ),
                  ),
                ),
              TextSpan(
                text: isGrowth
                    ? parts.number.replaceFirst('-', '')
                    : parts.number,
                style: _tabular(
                  LhTypography.mono(
                    size: _fs(lighthouseLedgerValueFontSize),
                    color: missing
                        ? DunesColors.resolve(context, LhColors.mute2)
                        : (isGrowth
                              ? growthColor
                              : (diffAlarm
                                    ? DunesColors.resolve(context, LhColors.neg)
                                    : DunesColors.resolve(
                                        context,
                                        LhColors.ink,
                                      ))),
                    weight: missing ? FontWeight.w500 : FontWeight.w700,
                    height: 1.0,
                    context: context,
                  ),
                ),
              ),
              if (parts.unit.isNotEmpty)
                TextSpan(
                  text: parts.unit,
                  style: LhTypography.mono(
                    size: _fs(lighthouseLedgerUnitFontSize),
                    color: isGrowth
                        ? growthColor.withAlpha(190)
                        : DunesColors.resolve(context, LhColors.mute),
                    weight: FontWeight.w500,
                    height: 1.0,
                    letterSpacing: 0.2,
                    context: context,
                  ),
                ),
            ],
          ),
          maxLines: 1,
          overflow: TextOverflow.ellipsis,
        ),
      ],
    );

    // 内边距常驻、只切边框和底色：点亮的时候格子不会跳一下。
    // 点亮用白底 + 主色描边 —— 卡底本身是淡色的，再叠一层淡色反而看不出来。
    final cell = AnimatedContainer(
      duration: const Duration(milliseconds: 140),
      padding: EdgeInsets.fromLTRB(_fs(7), _fs(6), _fs(6), _fs(6)),
      decoration: BoxDecoration(
        // 平时是一块浅紫灰底（账本指标格同款）；被追溯时换白底 + 主色描边。
        color: isSource
            ? DunesColors.resolve(
                context,
                LhColors.paper,
                role: DunesColorRole.surface,
              )
            : _fundPoolTileColor(),
        border: Border.all(
          color: isSource ? traceAccent : Colors.transparent,
          width: 1,
        ),
        borderRadius: BorderRadius.circular(7),
      ),
      child: body,
    );
    if (ownFormula == null || onTraceTap == null) return cell;
    return Semantics(
      button: true,
      label: isTraceOpen ? '收起$label的构成' : '看$label由哪几项相加',
      child: Material(
        color: Colors.transparent,
        borderRadius: BorderRadius.circular(7),
        child: InkWell(
          onTap: () => onTraceTap(metricKey),
          borderRadius: BorderRadius.circular(7),
          child: cell,
        ),
      ),
    );
  }

  Widget _fundPoolInvoiceOriginals(
    Widget Function(String) metricLabel,
    List<String> urls,
  ) {
    return Column(
      crossAxisAlignment: CrossAxisAlignment.start,
      mainAxisSize: MainAxisSize.min,
      children: [
        metricLabel('发票原件'),
        SizedBox(height: _fs(3)),
        if (urls.isEmpty)
          Text(
            '—',
            style: _tabular(
              LhTypography.mono(
                size: _fs(lighthouseLedgerValueFontSize),
                color: DunesColors.resolve(context, LhColors.mute2),
                weight: FontWeight.w500,
                height: 1.0,
                context: context,
              ),
            ),
          )
        else
          Wrap(
            spacing: _fs(4),
            runSpacing: _fs(4),
            children: [
              for (final url in urls)
                GestureDetector(
                  onTap: () => _openFundPoolInvoicePhoto(url),
                  child: ClipRRect(
                    borderRadius: BorderRadius.circular(4),
                    child: Image.network(
                      url,
                      width: _fs(44),
                      height: _fs(44),
                      fit: BoxFit.cover,
                      errorBuilder: (context, error, stack) => Container(
                        width: _fs(44),
                        height: _fs(44),
                        color: DunesColors.resolve(
                          context,
                          LhColors.line2,
                          role: DunesColorRole.surface,
                        ),
                        alignment: Alignment.center,
                        child: Icon(
                          Icons.photo_outlined,
                          size: _fs(14),
                          color: DunesColors.resolve(context, LhColors.mute),
                        ),
                      ),
                    ),
                  ),
                ),
            ],
          ),
      ],
    );
  }

  void _openFundPoolInvoicePhoto(String url) {
    showDialog<void>(
      context: context,
      builder: (ctx) => Dialog(
        backgroundColor: DunesColors.resolve(
          ctx,
          Colors.black,
          role: DunesColorRole.surface,
        ),
        insetPadding: const EdgeInsets.all(24),
        child: GestureDetector(
          onTap: () => Navigator.of(ctx).pop(),
          child: InteractiveViewer(
            child: Image.network(
              url,
              fit: BoxFit.contain,
              errorBuilder: (context, error, stack) => Padding(
                padding: EdgeInsets.all(24),
                child: Icon(
                  Icons.broken_image_outlined,
                  color: DunesColors.resolve(context, Colors.white70),
                ),
              ),
            ),
          ),
        ),
      ),
    );
  }

  // ── 主入口 ────────────────────────────────────────────────────────────────
  /// [visible] 当前页要画的行；[shareRows] 占比分母（默认 = visible 全量由调用方传入）。
  /// 二级详情传 [onRowTap] / [trendKeyPrefix] / [metricsTab]，一级保持默认即可。
  Widget _buildLedger(
    List<Map<String, dynamic>> visible, {
    List<Map<String, dynamic>>? shareRows,
    String? metricsTab,
    String? trendKeyPrefix,
    void Function(Map<String, dynamic> row)? onRowTap,
    bool showRowChevron = true,
    bool allowDefaultDetailOpen = true,
    int indexOffset = 0,
  }) {
    final tab = metricsTab ?? _tab;
    final share = shareRows ?? visible;
    _recomputeLedgerShareTotal(share);
    // 宽度取 LayoutBuilder 的真实可用宽，不是 MediaQuery 屏宽 ——
    // 二级/三级外层包了 padding + 描边，按屏宽算冻结列会凭空多吃 40+px，
    // 这是二级/三级看起来比一级更窄的直接原因。
    return LayoutBuilder(
      builder: (ctx, cons) {
        final w = cons.maxWidth;
        _ledgerScale = _lhLedgerScale(w);
        final pinnedW = _ledgerPinnedW(w, tab: tab);
        final cols = _ledgerSummaryCols(w, tab);
        final summaryCellH = _ledgerSummaryCellH(tab);
        // 供给维在四项经营指标下增加一行资金摘要：两格与 KPI 格等高，
        // 冻结列只需按多出的一行网格补高，不再额外加高度。
        // 总资产 / 票税那一行已撤掉：总资产入口移到省名旁，票税不再展示。
        final summaryMetricCount = cols.length;
        final rowH = _ledgerSummaryRowH(
          summaryMetricCount,
          cellHeight: summaryCellH,
        );

        return Column(
          crossAxisAlignment: CrossAxisAlignment.stretch,
          children: [
            for (int i = 0; i < visible.length; i++)
              ..._buildLedgerRowGroup(
                visible[i],
                i + indexOffset,
                cols,
                pinnedW,
                rowH,
                summaryCellH: summaryCellH,
                metricsTab: tab,
                trendKeyPrefix: trendKeyPrefix,
                onRowTap: onRowTap,
                showRowChevron: showRowChevron,
                allowDefaultDetailOpen: allowDefaultDetailOpen,
              ),
          ],
        );
      },
    );
  }

  /// 一行 = 账本行 (+ 展开态)。展开体全宽渲染。
  // ── PK 对比 ─────────────────────────────────────────────────────────
  String _pkKeyFor(String tab, String name, String group) =>
      '$tab::$name::$group';

  /// 给账本这一行拍一张 PK 快照：只收卡片上真的展示的指标（核销额卡不收 GMV），
  /// 再加利润和毛利率。
  LhPkEntry _pkEntryFor(
    Map<String, dynamic> r,
    String tab,
    String name,
    String group,
  ) {
    final shown = <String>{
      for (final row in lighthouseLedgerSummaryMetricRowsForEntity(
        tab: tab,
        product: name,
        basis: _rowMarginBasis(r),
      ))
        ...row,
      'profit',
      'grossMargin',
    };
    return LhPkEntry(
      key: _pkKeyFor(tab, name, group),
      name: name,
      tab: tab,
      group: group,
      rangeLabel: _selectedRangeLabel,
      metrics: <String, double?>{
        for (final m in lhPkMetrics)
          m.key: shown.contains(m.key)
              ? _pkFinite(_rowMetricValueOrNull(r, m.key))
              : null,
      },
      marginFormula: _grossMarginFormula(r),
    );
  }

  double? _pkFinite(double? v) => v != null && v.isFinite ? v : null;

  /// 分享图标左边挂一颗「＋PK」。
  Widget _withPkButton(
    Map<String, dynamic> r,
    String tab,
    String name,
    String group,
    Widget? shareIcon,
  ) {
    // PK 暂不上线：只留分享图标。
    if (!kLighthousePkEnabled) return shareIcon ?? const SizedBox.shrink();
    return Row(
      mainAxisSize: MainAxisSize.min,
      children: [
        LhPkAddButton(
          entryKey: _pkKeyFor(tab, name, group),
          onTap: (btnCtx) =>
              _togglePk(_pkEntryFor(r, tab, name, group), btnCtx),
        ),
        if (shareIcon != null) shareIcon,
      ],
    );
  }

