  }

  /// 跳资管后台。失败只提示，不抛 —— 对账入口挂了不该把列表页带崩。
  Future<void> _openReconBackend(
    LighthouseReconStatus status,
    String rowName,
  ) async {
    final uri = Uri.tryParse(status.deepLink.trim());
    if (uri == null) return;
    var ok = false;
    try {
      ok = await launchUrl(uri, mode: LaunchMode.externalApplication);
    } catch (_) {
      ok = false;
    }
    if (!ok && mounted) {
      ScaffoldMessenger.of(
        context,
      ).showSnackBar(SnackBar(content: Text('打不开资管对账页：$rowName')));
    }
  }

  /// 日度余额序列。后端没上 `series` 之前恒为空，界面上那条曲线整段不渲染。
  List<double> _netTABankBalanceSeries() {
    final raw = _bundle?.metrics['netTaBankBalanceSeries'];
    if (raw is! List) return const [];
    return [
      for (final e in raw)
        if (e is num) e.toDouble(),
    ];
  }

  List<String> _netTABankBalanceSeriesDates() {
    final raw = _bundle?.metrics['netTaBankBalanceSeriesDates'];
    if (raw is! List) return const [];
    return [for (final e in raw) e?.toString() ?? ''];
  }

  List<String> _netTABankBalanceSeriesLabels() {
    final raw = _bundle?.metrics['netTaBankBalanceSeriesLabels'];
    if (raw is List && raw.isNotEmpty) {
      return [for (final e in raw) e?.toString() ?? ''];
    }
    return [
      for (final d in _netTABankBalanceSeriesDates())
        lighthouseBankBalanceSeriesLabel(d),
    ];
  }

  LighthouseBankBalanceChange? _netTABankBalanceChange() {
    final amount = (_bundle?.metrics['netTaBankBalanceChange'] as num?)
        ?.toDouble();
    final vs = _bundle?.metrics['netTaBankBalanceChangeVs']?.toString().trim();
    if (amount == null || vs == null || vs.isEmpty) return null;
    final pct = (_bundle?.metrics['netTaBankBalanceChangePct'] as num?)
        ?.toDouble();
    return LighthouseBankBalanceChange(amount: amount, vs: vs, pct: pct);
  }

  bool get _netTABankBalanceCanOpen => _netTABankBalanceRows().isNotEmpty;

  /// 按公司的余额行。资管这支接口到公司一层就停了 —— 没有账号、没有开户行，
  /// 也没有业务日期，所以这里能给的就是「哪家公司账上多少」。
  List<Map<String, dynamic>> _netTABankBalanceRows() {
    return lighthouseNetTABankBalanceCompanies(
      _bundle?.metrics['netTaBankBalanceList'],
    );
  }

  /// 点开银行余额后只列按公司清单，走势已经画在本月净TA 那张图上。
  ///
  /// 每家公司一行：名称在左、金额在右、占比在最右，**进度条是这一行的底色**。
  /// 上一版把条单独占一行，名字下面空一截，38 家排下来全是空白；
  /// 做成行底填充之后，同样的信息量少一半高度，条也不再是"多出来的一条线"。
  Widget _buildNetTABankBalancePanel() {
    final rows = _netTABankBalanceRows();
    final accent = DunesColors.resolve(
      context,
      Color(lighthouseHeroSectionAccentValues['cash']!),
    );
    final total =
        (_bundle?.metrics['netTaBankBalance'] as num?)?.toDouble() ?? 0;
    final count =
        (_bundle?.metrics['netTaBankBalanceCount'] as num?)?.toInt() ??
        rows.length;
    var sumAbs = 0.0;
    var maxAbs = 0.0;
    for (final r in rows) {
      final a = (r['balance'] as double).abs();
      sumAbs += a;
      if (a > maxAbs) maxAbs = a;
    }

    Widget tile(Map<String, dynamic> r) {
      final v = r['balance'] as double;
      final share = sumAbs <= 0 ? 0.0 : v.abs() / sumAbs * 100;
      // 条长按「相对最大那家」：占比里第一名 84%、其余全是个位数，
      // 按占比画后面 37 家会缩成看不见的一截，相对最大值至少能比出彼此。
      final frac = maxAbs <= 0 ? 0.0 : (v.abs() / maxAbs).clamp(0.0, 1.0);
      final company = r['company'] as String;
      final accounts = (r['accounts'] as List?) ?? const [];
      final hasAccounts = accounts.isNotEmpty;
      final isOpen = hasAccounts && _netTaBalanceOpenCompany == company;
      final card = Padding(
        padding: const EdgeInsets.only(bottom: 6),
        child: ClipRRect(
          borderRadius: BorderRadius.circular(7),
          child: Stack(
            children: [
              Positioned.fill(
                child: Container(
                  color: DunesColors.resolve(
                    context,
                    LhColors.mist,
                    role: DunesColorRole.surface,
                  ),
                ),
              ),
              Positioned.fill(
                child: FractionallySizedBox(
                  alignment: Alignment.centerLeft,
                  widthFactor: frac < 0.02 ? 0.02 : frac,
                  child: Container(
                    color: DunesColors.resolveNullable(
                      context,
                      accent.withAlpha(v < 0 ? 22 : 38),
                      role: DunesColorRole.surface,
                    ),
                  ),
                ),
              ),
              Padding(
                padding: const EdgeInsets.fromLTRB(9, 7, 9, 7),
                child: Row(
                  children: [
                    if (hasAccounts) ...[
                      Icon(
                        isOpen
                            ? Icons.keyboard_arrow_down_rounded
                            : Icons.keyboard_arrow_right_rounded,
                        size: 12,
                        color: isOpen
                            ? accent
                            : DunesColors.resolve(context, LhColors.mute2),
                      ),
                      const SizedBox(width: 2),
                    ],
                    Flexible(
                      child: LhScrollText(
                        r['company'] as String,
                        maxLines: 1,
                        overflow: TextOverflow.ellipsis,
                        style: LhTypography.sans(
                          size: 11,
                          color: DunesColors.resolve(context, LhColors.ink),
                          weight: isOpen ? FontWeight.w700 : FontWeight.w500,
                          context: context,
                        ),
                      ),
                    ),
                    const SizedBox(width: 8),
                    LhScrollRichText(
                      maxLines: 1,
                      overflow: TextOverflow.ellipsis,
                      text: TextSpan(
                        children: [
                          TextSpan(
                            text: _fmtMoney(v),
                            style: LhTypography.number(
                              size: 12.5,
                              color: v < 0
                                  ? DunesColors.resolve(context, LhColors.neg)
                                  : DunesColors.resolve(context, LhColors.ink),
                              context: context,
                            ),
                          ),
                          TextSpan(
                            text: _unitMoney(v),
                            style: LhTypography.sans(
                              size: 9,
                              color: DunesColors.resolve(
                                context,
                                LhColors.mute,
                              ),
                              weight: FontWeight.w600,
                              context: context,
                            ),
                          ),
                        ],
                      ),
                    ),
                    const SizedBox(width: 7),
                    SizedBox(
                      width: 32,
                      child: Text(
                        share < 0.05 ? '—' : '${share.toStringAsFixed(1)}%',
                        textAlign: TextAlign.right,
                        style: LhTypography.mono(
                          size: 9,
                          color: DunesColors.resolve(context, LhColors.mute2),
                          weight: FontWeight.w600,
                          context: context,
                        ),
                      ),
                    ),
                  ],
                ),
              ),
            ],
          ),
        ),
      );
      if (!hasAccounts) return card;
      return GestureDetector(
        behavior: HitTestBehavior.opaque,
        onTap: () =>
            setState(() => _netTaBalanceOpenCompany = isOpen ? null : company),
        child: card,
      );
    }

    /// 某家公司的账户条。整幅宽度插在所在网格行下面 ——
    /// 面板是两列网格，把子行塞进格子里会把网格撑得高低不齐。
    Widget accountStrip(Map<String, dynamic> r) {
      final accounts = (r['accounts'] as List?) ?? const [];
      if (accounts.isEmpty) return const SizedBox.shrink();
      var maxA = 0.0;
      for (final a in accounts.whereType<Map>()) {
        final av = ((a['balance'] as num?)?.toDouble() ?? 0).abs();
        if (av > maxA) maxA = av;
      }
      return Container(
        margin: const EdgeInsets.only(bottom: 6),
        padding: const EdgeInsets.fromLTRB(9, 7, 9, 4),
        decoration: BoxDecoration(
          color: DunesColors.resolveNullable(
            context,
            accent.withAlpha(12),
            role: DunesColorRole.surface,
          ),
          borderRadius: BorderRadius.circular(7),
          border: Border.all(color: accent.withAlpha(45), width: 0.7),
        ),
        child: Column(
          crossAxisAlignment: CrossAxisAlignment.stretch,
          mainAxisSize: MainAxisSize.min,
          children: [
            Text(
              '${r['company']} · ${accounts.length} 个账户',
              maxLines: 1,
              overflow: TextOverflow.ellipsis,
              style: LhTypography.sans(
                size: 9.5,
                color: accent,
                weight: FontWeight.w700,
                letterSpacing: 0.2,
                context: context,
              ),
            ),
            const SizedBox(height: 5),
            for (final a in accounts.whereType<Map>()) ...[
              Builder(
                builder: (_) {
                  final av = (a['balance'] as num?)?.toDouble() ?? 0;
                  final f = maxA <= 0 ? 0.0 : (av.abs() / maxA).clamp(0.0, 1.0);
                  return Padding(
                    padding: const EdgeInsets.only(bottom: 3),
                    child: ClipRRect(
                      borderRadius: BorderRadius.circular(5),
                      child: Stack(
                        children: [
                          Positioned.fill(
                            child: Container(
                              color: DunesColors.resolve(
                                context,
                                LhColors.paper,
                                role: DunesColorRole.surface,
                              ),
                            ),
                          ),
                          Positioned.fill(
                            child: FractionallySizedBox(
                              alignment: Alignment.centerLeft,
                              widthFactor: f < 0.02 ? 0.02 : f,
                              child: Container(
                                color: DunesColors.resolveNullable(
                                  context,
                                  accent.withAlpha(24),
                                  role: DunesColorRole.surface,
                                ),
                              ),
                            ),
                          ),
                          Padding(
                            padding: const EdgeInsets.fromLTRB(7, 5, 7, 5),
                            child: Row(
                              children: [
                                Flexible(
                                  child: LhScrollText(
                                    a['account']?.toString() ?? '',
                                    maxLines: 1,
                                    overflow: TextOverflow.ellipsis,
                                    style: LhTypography.mono(
                                      size: 9.5,
                                      color: DunesColors.resolve(
                                        context,
                                        LhColors.ink2,
                                      ),
                                      weight: FontWeight.w500,
                                      context: context,
                                    ),
                                  ),
                                ),
                                const SizedBox(width: 8),
                                LhScrollRichText(
                                  maxLines: 1,
                                  overflow: TextOverflow.ellipsis,
                                  text: TextSpan(
                                    children: [
                                      TextSpan(
                                        text: _fmtMoney(av),
                                        style: LhTypography.number(
                                          size: 11,
                                          color: av < 0
                                              ? DunesColors.resolve(
                                                  context,
                                                  LhColors.neg,
                                                )
                                              : DunesColors.resolve(
                                                  context,
                                                  LhColors.ink,
                                                ),
                                          context: context,
                                        ),
                                      ),
                                      TextSpan(
                                        text: _unitMoney(av),
                                        style: LhTypography.sans(
                                          size: 8.5,
                                          color: DunesColors.resolve(
                                            context,
                                            LhColors.mute,
                                          ),
                                          weight: FontWeight.w600,
                                          context: context,
                                        ),
                                      ),
                                    ],
                                  ),
                                ),
                              ],
                            ),
                          ),
                        ],
                      ),
                    ),
                  );
                },
              ),
            ],
          ],
        ),
      );
    }

    return LayoutBuilder(
      builder: (context, box) {
        final columns = box.maxWidth >= 360 ? 2 : 1;
        final grid = <Widget>[];
        for (var start = 0; start < rows.length; start += columns) {
          final rowItems = rows.skip(start).take(columns).toList();
          grid.add(
            Row(
              crossAxisAlignment: CrossAxisAlignment.start,
              children: [
                for (var c = 0; c < columns; c++) ...[
                  if (c > 0) const SizedBox(width: 8),
                  Expanded(
                    child: c < rowItems.length
                        ? tile(rowItems[c])
                        : const SizedBox.shrink(),
                  ),
                ],
              ],
            ),
          );
          // 展开的那家公司，账户条整幅插在它所在的网格行下面。
          // 不塞进格子里 —— 两列网格会被撑得高低不齐。
          for (final item in rowItems) {
            if (_netTaBalanceOpenCompany == item['company']) {
              grid.add(accountStrip(item));
            }
          }
        }
        return Column(
          crossAxisAlignment: CrossAxisAlignment.stretch,
          mainAxisSize: MainAxisSize.min,
          children: [
            Row(
              children: [
                Container(
                  width: 15,
                  height: 15,
                  decoration: BoxDecoration(
                    color: DunesColors.resolveNullable(
                      context,
                      accent.withAlpha(24),
                      role: DunesColorRole.surface,
                    ),
                    borderRadius: BorderRadius.circular(4),
                  ),
                  child: Icon(
                    Icons.account_balance_rounded,
                    size: 9,
                    color: DunesColors.resolveNullable(context, accent),
                  ),
                ),
                const SizedBox(width: 6),
                Text(
                  '银行余额 · 按公司',
                  style: LhTypography.sans(
                    size: 11,
                    color: DunesColors.resolve(context, LhColors.ink2),
                    weight: FontWeight.w600,
                    context: context,
                  ),
                ),
                const Spacer(),
                Flexible(
                  child: Text(
                    '$count 家',
                    maxLines: 1,
                    overflow: TextOverflow.ellipsis,
                    textAlign: TextAlign.right,
                    style: LhTypography.sans(
                      size: 10,
                      color: DunesColors.resolve(context, LhColors.mute),
                      context: context,
                    ),
                  ),
                ),
                const SizedBox(width: 8),
                Text(
                  _fmtAmountWithUnit(total),
                  style: LhTypography.number(
                    size: 13,
                    color: DunesColors.resolve(context, LhColors.ink),
                    context: context,
                  ),
                ),
                GestureDetector(
                  behavior: HitTestBehavior.opaque,
                  onTap: () => setState(() => _netTaBalanceOpen = false),
                  child: Padding(
                    padding: EdgeInsets.only(left: 8),
                    child: Icon(
                      Icons.close_rounded,
                      size: 14,
                      color: DunesColors.resolve(context, LhColors.mute2),
                    ),
                  ),
                ),
              ],
            ),
            const SizedBox(height: 8),
            Container(
              height: 0.7,
              color: DunesColors.resolve(
                context,
                _LhPlum.line,
                role: DunesColorRole.surface,
              ),
            ),
            if (rows.isNotEmpty) ...[
              const SizedBox(height: 8),
              // 排不下就滚动，不截断 —— 截断会让人以为公司只有这么多家。
              Flexible(
                child: SingleChildScrollView(
                  child: Column(
                    crossAxisAlignment: CrossAxisAlignment.stretch,
                    mainAxisSize: MainAxisSize.min,
                    children: grid,
                  ),
                ),
              ),
            ],
          ],
        );
      },
    );
  }

  /// 行展开体。版式对齐产品 Tab 展开里的 规模 / 成本 / 利润 那三张卡：
  /// 白底圆角卡 + 小图标标题 + 两列指标格，而不是把格子裸贴在展开区里。
  Widget _buildNetTAExpanded(Map<String, dynamic> r) {
    final secondaries = (r['secondaries'] as List? ?? const [])
        .whereType<Map>()
        .map((e) => Map<String, dynamic>.from(e))
        .where((e) => (e['name']?.toString() ?? '').isNotEmpty)
        .toList();
    final isBill = r['secondaryCaliber']?.toString() == 'bill';
    final bucket = r['name']?.toString() ?? '';
    final accent = bucket == '经营活动'
        ? DunesColors.resolve(context, LhColors.pos)
        : (bucket == '筹资活动'
              ? DunesColors.resolve(context, LhColors.copper)
              : DunesColors.resolve(context, LhColors.neg));
    var sumAbs = 0.0;
    for (final e in secondaries) {
      sumAbs += ((e['netTa'] as num?)?.toDouble() ?? 0).abs();
    }
    final inflow = (r['inflow'] as num?)?.toDouble();
    final outflow = (r['outflow'] as num?)?.toDouble();

    Widget card() => Container(
      padding: const EdgeInsets.fromLTRB(11, 9, 11, 11),
      decoration: BoxDecoration(
        color: DunesColors.resolve(
          context,
          const Color(0xFFFFFDFF),
          role: DunesColorRole.surface,
        ),
        border: Border.all(
          color: DunesColors.resolve(
            context,
            _LhPlum.heroEdge,
            role: DunesColorRole.border,
          ),
          width: 0.7,
        ),
        borderRadius: BorderRadius.circular(lighthouseHeroCardRadius),
        boxShadow: [
          BoxShadow(
            color: Colors.black.withAlpha(8),
            blurRadius: 8,
            offset: const Offset(0, 2),
          ),
        ],
      ),
      child: Column(
        crossAxisAlignment: CrossAxisAlignment.stretch,
        mainAxisSize: MainAxisSize.min,
        children: [
          Row(
            children: [
              Container(
                width: 15,
                height: 15,
                decoration: BoxDecoration(
                  color: DunesColors.resolveNullable(
                    context,
                    accent.withAlpha(24),
                    role: DunesColorRole.surface,
                  ),
                  borderRadius: BorderRadius.circular(4),
                ),
                child: Icon(
                  isBill
                      ? Icons.receipt_long_rounded
                      : Icons.account_tree_rounded,
                  size: 9,
                  color: DunesColors.resolveNullable(context, accent),
                ),
              ),
              const SizedBox(width: 6),
              Text(
                isBill ? '账单三级' : '二级分类',
                style: LhTypography.sans(
                  size: 11,
                  color: DunesColors.resolve(context, LhColors.ink2),
                  weight: FontWeight.w600,
                  context: context,
                ),
              ),
              const SizedBox(width: 5),
              Text(
                '${secondaries.length} 项',
                style: LhTypography.sans(
                  size: 10,
                  color: DunesColors.resolve(context, LhColors.mute),
                  context: context,
                ),
              ),
              const Spacer(),
              if (inflow != null && outflow != null)
                Flexible(
                  child: LhScrollText(
                    '流入 ${_fmtAmountWithUnit(inflow)} · 流出 ${_fmtAmountWithUnit(outflow)}',
                    maxLines: 1,
                    overflow: TextOverflow.ellipsis,
                    style: LhTypography.sans(
                      size: 9.5,
                      color: DunesColors.resolve(context, LhColors.mute2),
                      context: context,
                    ),
                  ),
                ),
            ],
          ),
          const SizedBox(height: 9),
          Container(
            height: 0.5,
            color: DunesColors.resolve(
              context,
              LhColors.line2,
              role: DunesColorRole.surface,
            ),
          ),
          const SizedBox(height: 10),
          _buildNetTAMetricGrid(
            secondaries,
            inflowBadge: bucket == '经营成本',
            shareBase: sumAbs,
          ),
        ],
      ),
    );

    return AnimatedSize(
      duration: const Duration(milliseconds: 220),
      child: Container(
        width: double.infinity,
        color: DunesColors.resolve(
          context,
          Colors.white,
          role: DunesColorRole.surface,
        ),
        child: Column(
          crossAxisAlignment: CrossAxisAlignment.start,
          children: [
            Container(
              height: 0.5,
              color: DunesColors.resolve(
                context,
                _LhPlum.line,
                role: DunesColorRole.surface,
              ),
            ),
            Padding(
              padding: const EdgeInsets.fromLTRB(12, 10, 12, 12),
              child: secondaries.isEmpty
                  ? Text(
                      '无下级分类',
                      style: LhTypography.sans(
                        size: 10.5,
                        color: DunesColors.resolve(context, LhColors.mute),
                        context: context,
                      ),
                    )
                  : card(),
            ),
          ],
        ),
      ),
    );
  }

  /// 账本行点指标格 / 图例：总图五条只高亮；再点同一项回到总图。
  void _setLedgerRowTrendFocus(String trendKey, String? next) {
    setState(() {
      if (next == null || !lighthouseLedgerMetricOpensSoloTrend(next)) {
        _expandedLedgerSolo.remove(trendKey);
        _expandedTrends.add(trendKey);
        return;
      }
      _expandedLedgerSolo[trendKey] = next;
      _expandedTrends.remove(trendKey);
    });
  }

  String _rowTrendHistoryRequestKey(
    String trendKey,
    String tab,
    Map<String, dynamic> row,
  ) =>
      '$trendKey|$tab|$_period|$_periodOffset|${row['name'] ?? ''}|${row['group'] ?? ''}';

  Future<void> _loadRowTrendHistory(
    Map<String, dynamic> row, {
    required String tab,
    required String trendKey,
  }) async {
    if (widget.sharedCard != null ||
        (tab != 'product' && tab != 'supply' && tab != 'channel')) {
      return;
    }
    final trend = _resolvedRowTrend(row);
    if (trend == null) return;
    final baseKeys = (trend['keys'] as List? ?? const [])
        .map((e) => e.toString())
        .where((e) => e.isNotEmpty)
        .toList();
    final requestKey = _rowTrendHistoryRequestKey(trendKey, tab, row);
    var history = _rowTrendHistories[trendKey];
    if (history == null || history.requestKey != requestKey) {
      history = LighthouseRowTrendHistory(requestKey: requestKey);
    }
    if (history.loading || !history.hasMore) return;
    final before = history.keys.isNotEmpty
        ? history.keys.first
        : (baseKeys.isEmpty ? '' : baseKeys.first);
    if (before.isEmpty) return;
    setState(() {
      _rowTrendHistories[trendKey] = history!.copyWith(loading: true);
    });
    try {
      final page = await _service.fetchRowTrendHistory(
        tab: tab,
        name: row['name']?.toString() ?? '',
        group: row['group']?.toString(),
        before: before,
        period: _period,
        offset: _periodOffset,
      );
      if (!mounted ||
          requestKey != _rowTrendHistoryRequestKey(trendKey, tab, row)) {
        return;
      }
      setState(() {
        final current = _rowTrendHistories[trendKey];
        if (current == null || current.requestKey != requestKey) return;
        _rowTrendHistories[trendKey] = current.prependPage(page);
      });
    } catch (error) {
      if (!mounted) return;
      setState(() {
        final current = _rowTrendHistories[trendKey];
        if (current == null || current.requestKey != requestKey) return;
        _rowTrendHistories[trendKey] = LighthouseRowTrendHistory(
          requestKey: current.requestKey,
          keys: current.keys,
          labels: current.labels,
          series: current.series,
          hasMore: current.hasMore,
          error: error.toString().replaceFirst('Exception: ', ''),
          version: current.version,
        );
      });
    }
  }

  Widget _buildInlineExpanded(
    Map<String, dynamic> r, {
    String? soloMetricKey,
    required String trendKey,
    required String metricsTab,
    bool allowHistory = false,
  }) {
    if (_tab == 'netTa' && soloMetricKey == null) {
      return _buildNetTAExpanded(r);
    }
    final focus =
        soloMetricKey != null &&
            lighthouseLedgerMetricOpensSoloTrend(soloMetricKey)
        ? soloMetricKey
        : null;
    final requestKey = _rowTrendHistoryRequestKey(trendKey, metricsTab, r);
    final cachedHistory = _rowTrendHistories[trendKey];
    final history = cachedHistory?.requestKey == requestKey
        ? cachedHistory
        : null;
    final baseTrend = _resolvedRowTrend(r);
    final mergedTrend = baseTrend == null || history == null
        ? baseTrend
        : lighthouseMergeRowTrendHistory(baseTrend, history);
    final chartRow = mergedTrend == null
        ? r
        : (Map<String, dynamic>.from(r)..['trend'] = mergedTrend);

    // 现金流点开时：走势图点哪一格，上面的现金流拆解就换成那一格的数。
    final cashFlowPicking = focus == 'prepaid';
    final cashFlowPoint = cashFlowPicking
        ? _cashFlowPointByTrendKey[trendKey]
        : null;

    // 线色跟着上面那格：规模紫、结果蓝。视窗参数与主 Hero 完全复用。
    final trendChart = _trendChartFor(
      chartRow,
      showHeader: false,
      soloMetricKey: focus,
      onSoloOverlayChanged: (next) => _setLedgerRowTrendFocus(trendKey, next),
      selectedIndex: cashFlowPoint,
      onSelectedIndexChanged: cashFlowPicking
          ? (i) => setState(() {
              if (i == null) {
                _cashFlowPointByTrendKey.remove(trendKey);
              } else {
                _cashFlowPointByTrendKey[trendKey] = i;
              }
            })
          : null,
      viewportCount: 7,
      historyCount: history?.length ?? 0,
      historyLoading: history?.loading ?? false,
      historyHasMore:
          allowHistory &&
          (history?.hasMore ??
              ((baseTrend?['keys'] as List?)?.isNotEmpty == true)),
      onNeedHistory: allowHistory
          ? () => unawaited(
              _loadRowTrendHistory(r, tab: metricsTab, trendKey: trendKey),
            )
          : null,
    );
    final trendTab = _trendLookupTabForListRow();
    final trendFailed = trendTab != null && _trendErrors.containsKey(trendTab);

    // v14.2 · section 头统一成一个形态：2px 色条 + mono 10 UPPER + hairline
    //   + 右端元数据。和 hero stat rail 的 group() 逐参数一致 ——
    //   原来「走势」用紫色填充胶囊、「全指标」用 3px 色条，同一个面板里
    //   两套 section 语言，而填色胶囊正是 v13 在 hero 里拆掉的那族 chrome。
    Widget sec(String title, Color accent, {String trailing = ''}) {
      return Row(
        children: [
          Container(
            width: 2,
            height: 9,
            color: DunesColors.resolveNullable(
              context,
              accent,
              role: DunesColorRole.surface,
            ),
          ),
          const SizedBox(width: 6),
          Text(
            title,
            style: LhTypography.mono(
              size: 9,
              color: DunesColors.resolve(context, LhColors.mute),
              weight: FontWeight.w700,
              letterSpacing: 1.0,
              height: 1.0,
              context: context,
            ),
          ),
          const SizedBox(width: 10),
          Expanded(
            child: Container(
              height: 0.5,
              color: DunesColors.resolve(
                context,
                _LhPlum.line,
                role: DunesColorRole.surface,
              ),
            ),
          ),
          if (trailing.isNotEmpty) ...[
            const SizedBox(width: 10),
            Text(
              trailing,
              style: _tabular(
                LhTypography.mono(
                  size: 8.5,
                  color: DunesColors.resolve(context, LhColors.ink2),
                  weight: FontWeight.w600,
                  letterSpacing: 0.3,
                  height: 1.0,
                  context: context,
                ),
              ),
            ),
          ],
        ],
      );
    }

    final discountCard = lighthouseLedgerShowsDiscountUi
        ? _buildDiscountTierCard(r, trendKey: trendKey)
        : null;
    final discountMeta = discountCard == null
        ? ''
        : (() {
            final name = r['name']?.toString().trim() ?? '';
            final d = _discountRecordFor(r, name);
            final id = d?.province ?? '';
            return id.isEmpty ? 'calc_record' : '$id · calc_record';
          })();

    // 列表行展开与 L1/L2/L3 主 Hero 使用完全相同的四分类版式；
    // 数值与环比来自当前实体行，折线仍由上方 trendChart 独立承载。
    final expandedTotals = _heroTotalsFromRow(r);

    // 2026-10-26 · 点开「经营性净现金流」：读数 + 现金怎么来的 + 利润→现金桥图，
    // 走势接在后面，不再套「本期合计 / 近 7 天」标题条；下面的规模 / 成本 / 利润三栏不再出。
    // 资管没算现金流（prepaidStatus = none）就照旧走单指标走势。
    final cashFlowValue = focus == 'prepaid' && _showOperatingCashFlow(row: r)
        ? _rowMetricValueOrNull(r, 'prepaid')
        : null;
    Widget? cashFlowPanel;
    if (cashFlowValue != null) {
      // 走势上点了某一格：全部换成那一格的数（走势序列里带着拆解要用的五条），
      // 环比和前一格比；没点 = 本期合计。
      final pointTrend = _resolvedRowTrend(chartRow);
      final pointLabels =
          ((pointTrend?['labels'] ?? pointTrend?['xLabels']) as List?) ??
          const [];
      final pi = cashFlowPoint ?? -1;
      final usePoint =
          pointTrend != null && pi >= 0 && pi < pointLabels.length;
      double at(String key, int i) {
        final list = pointTrend?[key];
        if (list is! List || i < 0 || i >= list.length) return 0;
        final v = list[i];
        return v is num ? v.toDouble() : 0;
      }

      double num0(String key) => usePoint
          ? at(key, pi)
          : ((r[key] as num?)?.toDouble() ?? 0);
      final cf = usePoint ? at('prepaid', pi) : cashFlowValue;
      final profit = usePoint ? at('profit', pi) : (_metricNum(r, 'profit') ?? 0);
      final cost = usePoint
          ? (pointTrend?['totalCost'] is List
                ? at('totalCost', pi)
                : at('cost', pi))
          : num0('totalCost');
      double? delta;
      if (usePoint) {
        final prev = pi > 0 ? at('prepaid', pi - 1) : null;
        if (prev != null && prev.abs() > 1e-9) {
          delta = (cf - prev) / prev.abs() * 100;
        }
      } else {
        delta = _ledgerDelta(r, 'prepaid');
      }
      cashFlowPanel = LighthouseCashFlowPanel(
        cashFlow: cf,
        profit: profit,
        pointLabel: usePoint ? pointLabels[pi].toString() : null,
        deltaPct: delta != null && lighthouseDeltaPctShown(delta, isRate: false)
            ? delta
            : null,
        compareLabel: _heroCompareLabel,
        breakdown: lighthouseCashFlowBreakdown(
          cashFlow: cf,
          profit: profit,
          cost: cost,
          sales: usePoint ? at('sales', pi) : _salesOf(r),
          verified: usePoint ? at('verifiedSales', pi) : _verifiedSalesOf(r),
          syncIssue: num0('syncCouponIssue'),
          couponPurchase: num0('couponPurchase'),
          couponSales: num0('couponSales'),
          travelGoldIncome: num0('travelGoldIncome'),
          travelGoldPurchase: num0('travelGoldPurchase'),
        ),
      );
    }

    return AnimatedSize(
      duration: const Duration(milliseconds: 220),
      child: Container(
        width: double.infinity,
        // v14.3 · 展开体底色回中性白。淡紫做面在这里没有收益：
        //   展开体是全宽的，面积比 hero 卡还大，一铺色整页的紫就从
        //   「一处焦点」退化成「到处都是」。层级完全交给上下两条
        //   hairline + 左侧 2px 色条承担，边界比色块更省视觉预算。
        color: DunesColors.resolve(
          context,
          Colors.white,
          role: DunesColorRole.surface,
        ),
        child: Column(
          crossAxisAlignment: CrossAxisAlignment.start,
          children: [
            // 顶边 hairline —— 让展开体从上方账本行「陷下去」一档，
            // 层级靠边界而不是靠加深底色。
            Container(
              height: 0.5,
              color: DunesColors.resolve(
                context,
                _LhPlum.line,
                role: DunesColorRole.surface,
              ),
            ),
            Padding(
              padding: const EdgeInsets.fromLTRB(14, 12, 14, 4),
              child: Column(
                crossAxisAlignment: CrossAxisAlignment.start,
                children: [
                  // ── § 折扣档位 —— 排在走势之前 ──────────────────────
                  //   用户是从冻结列那条折扣条点进来的，第一眼必须看到它；
                  //   而且「这个省怎么定价」本来就是读下面规模/成本/利润的前提。
                  //   非供给维、或这一行没有折扣规则时整段不出现，不留空槽。
                  if (discountCard != null) ...[
                    sec(
                      '折扣档位',
                      DunesColors.resolve(context, _LhPlum.deep),
                      trailing: discountMeta,
                    ),
                    const SizedBox(height: 12),
                    discountCard,
                    const SizedBox(height: 18),
                  ],

                  if (cashFlowPanel != null) ...[
                    cashFlowPanel,
                    const SizedBox(height: 18),
                  ],
                  if (cashFlowPanel == null) ...[
                    sec(
                      focus == null
                          ? '整行走势'
                          : '单指标走势 · ${_ledgerSummaryMetricLabel(focus)}',
                      focus == null
                          ? DunesColors.resolve(context, _LhPlum.primary)
                          : lighthouseLedgerTrendEmphasisColor(focus),
                      trailing: focus == null ? '名称列打开' : '数字格打开',
                    ),
                    const SizedBox(height: 10),
                  ],

                  if (trendChart != null)
                    trendChart
                  else
                    GestureDetector(
                      behavior: HitTestBehavior.opaque,
                      onTap: trendFailed
                          ? () => unawaited(_loadTrend(trendTab, force: true))
                          : null,
                      child: Padding(
                        padding: const EdgeInsets.symmetric(vertical: 18),
                        child: Center(
                          child: Text(
                            trendFailed ? '趋势加载失败，点击重试' : '暂无趋势数据',
                            style: LhTypography.sans(
                              size: 10,
                              color: trendFailed
                                  ? DunesColors.resolve(
                                      context,
                                      _LhPlum.primary,
                                    )
                                  : DunesColors.resolve(context, LhColors.mute),
                              weight: trendFailed
                                  ? FontWeight.w600
                                  : FontWeight.normal,
                              context: context,
                            ),
                          ),
                        ),
                      ),
                    ),

                  // 只在用户点开卡片后构建；全部数值不再二次折叠。
                  // 现金流拆解打开时不出这三栏（原型：点开现金流只看现金流）。
                  if (cashFlowPanel == null) ...[
                    const SizedBox(height: 18),
                    _buildHeroStatRail(
                      expandedTotals,
                      whiteBackground: true,
                      entityRow: r,
                      interactive: true,
                      focusKey: soloMetricKey,
                      onMetricActivate: (next) =>
                          _setLedgerRowTrendFocus(trendKey, next.focus),
                    ),
                  ],
                  const SizedBox(height: 8),
                ],
              ),
            ),
            // 底边 hairline —— 底色改白后，展开体和下一条账本行之间
            // 没有色差可依，收口交给这条线。
            Container(
              height: 0.5,
              color: DunesColors.resolve(
                context,
                _LhPlum.line,
                role: DunesColorRole.surface,
              ),
            ),
          ],
        ),
      ),
    );
  }

  Widget _buildFooter() {
    return Padding(
      padding: const EdgeInsets.symmetric(
        vertical: 22,
        horizontal: lighthouseHeroShellMarginH,
      ),
      child: Row(
        mainAxisAlignment: MainAxisAlignment.center,
        children: [
          Container(
            width: 28,
            height: 0.5,
            color: DunesColors.resolve(
              context,
              _LhPlum.primary,
              role: DunesColorRole.surface,
            ).withAlpha(140),
          ),
          Padding(
            padding: const EdgeInsets.symmetric(horizontal: 10),
            child: Text(
              '· FIN ·',
              style: LhTypography.mono(
                size: 9,
                color: DunesColors.resolve(context, LhColors.mute2),
                weight: FontWeight.w500,
                letterSpacing: 2,
                context: context,
              ),
            ),
          ),
          Container(
            width: 28,
            height: 0.5,
            color: DunesColors.resolve(
              context,
              _LhPlum.primary,
              role: DunesColorRole.surface,
            ).withAlpha(140),
          ),
        ],
      ),
    );
  }

  // ───── Detail View ────────────────────────────────────────────────────────

  // Sub-tab config per detail type (mirrors DETAIL_CONFIG in HTML)
  //
  // v11 · 用户反馈：删除所有"分类" sub-tab (供给分类/渠道分类/产品分类)
  // v12 · 用户反馈：删除二级页 产品码 / 公司主体；SKU 保留
  // v13 · 用户反馈：二级页去掉 SKU（三级交叉维仍可保留）
  //
  //   统一 pattern：
  //     · product tab : 供给·渠道·项目·人效
  //     · supply  tab : 产品·渠道·项目·人效
  //     · channel tab : 产品·供给·项目·人效
  //     · people  tab : 产品·供给·渠道（人的身份是名字，子列表仍是账本）
  //
  //   L3 (drill)：全集交叉维去掉当前维 —— 见 _drillSubTabsFor.
  static const _kPeopleSubTab = _SubTabInfo(
    key: 'people',
    label: '人效',
    color: _LhPlum.deep,
  );
  static const _kDetailSubTabs = {
    'product': [
      // 只在该二级下有真正的三级时出现（见 _buildDetailView 的过滤）。
      _SubTabInfo(
        key: lighthouseProductL3SubTab,
        label: '细分',
        color: LhColors.product,
      ),
      _SubTabInfo(key: 'supply', label: '供给', color: LhColors.sinopec),
      _SubTabInfo(key: 'channel', label: '渠道', color: LhColors.carrier),
      _SubTabInfo(key: 'project', label: '项目', color: _LhPlum.primary),
      _kPeopleSubTab,
    ],
    'supply': [
      _SubTabInfo(key: 'product', label: '产品', color: LhColors.product),
      _SubTabInfo(key: 'channel', label: '渠道', color: LhColors.carrier),
      _SubTabInfo(key: 'project', label: '项目', color: _LhPlum.primary),
      _kPeopleSubTab,
    ],
    'channel': [
      _SubTabInfo(key: 'product', label: '产品', color: LhColors.product),
      _SubTabInfo(key: 'supply', label: '供给', color: LhColors.sinopec),
      _SubTabInfo(key: 'project', label: '项目', color: _LhPlum.primary),
      _kPeopleSubTab,
    ],
    'people': [
      _SubTabInfo(key: 'product', label: '产品', color: LhColors.product),
      _SubTabInfo(key: 'supply', label: '供给', color: LhColors.sinopec),
      _SubTabInfo(key: 'channel', label: '渠道', color: LhColors.carrier),
    ],
  };

  // Level-3：全集交叉维，去掉当前钻取维本身（产品/供给/渠道/项目/SKU）。
  static const _kAllCrossSubTabs = [
    _SubTabInfo(key: 'product', label: '产品', color: LhColors.product),
    _SubTabInfo(key: 'supply', label: '供给', color: LhColors.sinopec),
    _SubTabInfo(key: 'channel', label: '渠道', color: LhColors.carrier),
    _SubTabInfo(key: 'project', label: '项目', color: _LhPlum.primary),
    _SubTabInfo(key: 'productName', label: 'SKU', color: LhColors.product),
  ];

  static List<_SubTabInfo> _drillSubTabsFor(String dim) {
    return [
      for (final t in _kAllCrossSubTabs)
        if (t.key != dim) t,
    ];
  }

  /// v3.7: 统一返回键 —— editorial mono chevron + 小 sans '返回'
  ///   之前 3 处各不相同:
  ///     · metric page: Icons.arrow_back_rounded size 20 ink (chunky app-bar)
  ///     · detail L2:   Icons.chevron_left size 18 mute + sans 11 mute (SaaS)
  ///     · supplier L4: 同 detail
  ///   现在: 全用 mono chevron ‹ 15 mute w600 + sans 10.5 '返回' mute w600
  ///   跟 rank 从 badge → 纯 mono 数字的思路一致 —— chrome 减法, typography 承担导航
  Widget _buildEditorialBackButton({
    required VoidCallback onTap,
    String label = '返回',
    bool onDark = false,
  }) {
    return GestureDetector(
      behavior: HitTestBehavior.opaque,
      onTap: onTap,
      child: Padding(
        padding: const EdgeInsets.symmetric(vertical: 6, horizontal: 2),
        child: Row(
          mainAxisSize: MainAxisSize.min,
          crossAxisAlignment: CrossAxisAlignment.center,
          children: [
            Text(
              '‹',
              style: LhTypography.mono(
                size: 15,
                color: onDark
                    ? _kLhBandInk
                    : DunesColors.resolve(context, LhColors.mute),
                weight: FontWeight.w600,
                height: 1.0,
                context: context,
              ),
            ),
            const SizedBox(width: 5),
            Text(
              label,
              style: LhTypography.sans(
                size: 10.5,
                color: onDark
                    ? _kLhBandInk
                    : DunesColors.resolve(context, LhColors.mute),
                weight: FontWeight.w600,
                context: context,
              ),
            ),
          ],
        ),
      ),
    );
  }

  void _returnToLighthouseRootFromBreadcrumb() {
    _closeDropdown();
    setState(() {
      _detailReturnStack.clear();
      _detailKey = null;
      _detailType = null;
      _resetDetailSkuSearch();
      _resetDetailDrill();
      _resetCodeDrill();
      _closeMetricPage();
    });
    _restoreMainListScroll();
  }

  void _returnToDetailLevel2FromBreadcrumb() {
    if (_drillKey == null && _codeDrillKey == null) return;
    _closeDropdown();
    setState(() {
      _resetCodeDrill();
      _resetDetailDrill();
      _detailPage = 1;
      _resetDetailSkuSearch();
    });
  }

  /// L2/L3 顶部层级轨迹：逐级写清业务对象，前级可直接返回。
  Widget _buildDetailBreadcrumb({
    required String type,
    required String rootDisplayName,
    required String rootGroupLabel,
    required bool isDrill,
  }) {
    // 层级路径必须跟随“实际点击行”，不能读取 L1 的列表筛选条件。
    // 用户可能在「全部」筛选下点击某个具体产品；此时来源仍是该产品，不是「全部」。
    final rootDimension = _detailRootLabel(type);
    final productL3 = type == 'product'
        ? lighthouseParseProductL3Key(_detailKey ?? '')
        : null;
    final level1Parts = <String>[
      '$rootDimension列表',
      rootDisplayName,
      if (rootGroupLabel.isNotEmpty) rootGroupLabel,
    ];
    final level1Label = level1Parts.join(' · ');
    final level2Label = isDrill
        ? '$rootDisplayName详情 · ${_detailDimLabel(_drillDim!)}列表'
        : '$rootDisplayName详情';
    final level3Label = isDrill
        ? '${_detailDimLabel(_drillDim!)}详情 · $_drillDisplayName'
              '${_drillGroup.isNotEmpty ? ' · $_drillGroup' : ''}'
        : '';

    Widget step({
      required String level,
      required String label,
      required bool isCurrent,
      VoidCallback? onTap,
    }) {
      final content = Container(
        constraints: const BoxConstraints(minHeight: 48),
        padding: const EdgeInsets.fromLTRB(7, 5, 7, 5),
        decoration: BoxDecoration(
          border: Border(
            bottom: BorderSide(
              color: isCurrent
                  ? DunesColors.resolve(
                      context,
                      _LhPlum.primary,
                      role: DunesColorRole.border,
                    )
                  : Colors.transparent,
              width: isCurrent ? 2 : 0,
            ),
          ),
        ),
        child: Column(
          mainAxisAlignment: MainAxisAlignment.center,
          crossAxisAlignment: CrossAxisAlignment.start,
          children: [
            Text(
              level,
              style: LhTypography.mono(
                size: 7.5,
                color: isCurrent
                    ? DunesColors.resolve(context, _LhPlum.primary)
                    : DunesColors.resolve(context, LhColors.mute2),
                weight: FontWeight.w700,
                letterSpacing: 0.7,
                height: 1.0,
                context: context,
              ),
            ),
            const SizedBox(height: 4),
            LhScrollText(
              label,
              maxLines: 2,
              overflow: TextOverflow.ellipsis,
              style: LhTypography.sans(
                size: 9.5,
                color: isCurrent
                    ? DunesColors.resolve(context, _LhPlum.deep)
                    : DunesColors.resolve(context, LhColors.ink2),
                weight: isCurrent ? FontWeight.w700 : FontWeight.w600,
                height: 1.15,
                context: context,
              ),
            ),
          ],
        ),
      );
      return Expanded(
        child: onTap == null
            ? content
            : Semantics(
                button: true,
                label: '返回$level：$label',
                child: GestureDetector(
                  behavior: HitTestBehavior.opaque,
                  onTap: onTap,
                  child: content,
                ),
              ),
      );
    }

    Widget divider() => Padding(
      padding: const EdgeInsets.symmetric(horizontal: 1),
      child: Icon(
        Icons.chevron_right_rounded,
        size: 14,
        color: DunesColors.resolve(context, LhColors.mute2),
      ),
    );

    return Container(
      width: double.infinity,
      padding: const EdgeInsets.symmetric(horizontal: 5),
      decoration: BoxDecoration(
        color: DunesColors.resolve(
          context,
          const Color(0xFFFAF9FD),
          role: DunesColorRole.surface,
        ),
        borderRadius: BorderRadius.circular(10),
        border: Border.all(
          color: DunesColors.resolve(
            context,
            _LhPlum.line,
            role: DunesColorRole.border,
          ),
          width: 0.6,
        ),
      ),
      child: Row(
        crossAxisAlignment: CrossAxisAlignment.center,
        children: productL3 != null
            ? [
                // 三级详情：一级列表 → 二级（可点回）→ 三级 [→ 交叉维]。
                step(
                  level: '一级 · L1',
                  label: [
                    '产品列表',
                    if (productL3.l1.isNotEmpty) productL3.l1,
                  ].join(' · '),
                  isCurrent: false,
                  onTap: _returnToLighthouseRootFromBreadcrumb,
                ),
                divider(),
                step(
                  level: '二级 · L2',
                  label: '${productL3.l2}详情',
                  isCurrent: false,
                  onTap: () => _returnToProductL2FromBreadcrumb(
                    productL3.l2,
                    productL3.l1,
                  ),
                ),
                divider(),
                step(
                  level: '三级 · L3',
                  label: '${productL3.l3}详情',
                  isCurrent: !isDrill,
                  onTap: isDrill ? _returnToDetailLevel2FromBreadcrumb : null,
                ),
                if (isDrill) ...[
                  divider(),
                  step(
                    level: '四级 · L4',
                    label:
                        '${_detailDimLabel(_drillDim!)} · $_drillDisplayName',
                    isCurrent: true,
                  ),
                ],
              ]
            : [
                step(
                  level: '一级 · L1',
                  label: level1Label,
                  isCurrent: false,
                  onTap: _returnToLighthouseRootFromBreadcrumb,
                ),
                divider(),
                step(
                  level: '二级 · L2',
                  label: level2Label,
                  isCurrent: !isDrill,
                  onTap: isDrill ? _returnToDetailLevel2FromBreadcrumb : null,
                ),
                if (isDrill) ...[
                  divider(),
                  step(level: '三级 · L3', label: level3Label, isCurrent: true),
                ],
              ],
      ),
    );
  }

  /// 二级详情首次载入 —— 与一级切 tab 同一套品牌 loader 遮罩特效。
  Widget _buildDetailLoadingSkeleton({String? error, VoidCallback? onRetry}) {
    return ColoredBox(
      color: DunesColors.resolve(
        context,
        Colors.white,
        role: DunesColorRole.surface,
      ).withAlpha(210),
      child: Center(
        child: error == null
            ? _buildBrandBusyContent(label: '数据同步中')
            : Column(
                mainAxisSize: MainAxisSize.min,
                children: [
                  Text(
                    '详情加载失败',
                    style: LhTypography.sans(
                      size: 13,
                      color: DunesColors.resolve(context, LhColors.ink),
                      weight: FontWeight.w700,
                      context: context,
                    ),
                  ),
                  const SizedBox(height: 8),
                  Text(
                    error,
                    textAlign: TextAlign.center,
                    style: LhTypography.sans(
                      size: 10,
                      color: DunesColors.resolve(context, LhColors.mute),
                      context: context,
                    ),
                  ),
                  const SizedBox(height: 12),
                  TextButton(onPressed: onRetry, child: const Text('点击重试')),
                ],
              ),
      ),
    );
  }

  // ═══════════════════════════════════════════════════════════════════════
  // ── L2 客户端聚合 helper —— 分类/供应商产品码 sub-tabs 兜底 ─────────────
  // ═══════════════════════════════════════════════════════════════════════
  //
  //   viewDict 是后端返回的 detail 字典。对已有 tab (product/supply/channel/
  //   project/productName)，viewDict[key] 直接是 rows 列表。
  //
  //   新加的 4 个 tab：
  //     · productCategory : 按 product 的 group 桶排 (能源/公共出行/民营…)
  //     · supplyCategory  : 按 supply  的 group 桶排 (中石油/中石化/出行/民营…)
  //     · channelCategory : 按 channel 的 group 桶排 (平安/多渠道/广电/电信…)
  //     · supplierCode    : 展平 supplier_code_drill Map<sku, rows>
  //
  //   如果后端将来直接返回 viewDict[categoryKey]，我们优先用后端结果，
  //   不做客户端覆盖。（Nova 沙盘约定：数据契约以后端为准。）
  List<Map<String, dynamic>> _aggregateSubRowsForKey(
    Map<String, dynamic> viewDict,
    Map<String, dynamic> detailDict,
    String subTabKey,
  ) {
    // 后端已下发 → 直接使用
    final raw = viewDict[subTabKey];
    if (raw is List && raw.isNotEmpty) {
      return raw
          .whereType<Map>()
          .map((e) => Map<String, dynamic>.from(e))
          .toList();
    }

    // 供应商产品码 —— 展平 supplier_code_drill
    if (subTabKey == 'supplierCode') {
      final drill = detailDict['supplier_code_drill'];
      if (drill is Map) {
        // 按 supplierProductCode 桶排（同一码可能挂在多个 SKU 下）
        final agg = <String, Map<String, dynamic>>{};
        drill.forEach((skuKey, rows) {
          if (rows is! List) return;
          for (final r in rows.whereType<Map>()) {
            final code =
                r['supplierProductCode']?.toString().trim() ??
                r['supplier_product_code']?.toString().trim() ??
                '';
            if (code.isEmpty) continue;
            final displayName = code;
            final groupLabel = skuKey.toString();
            final k = '$displayName::$groupLabel';
            if (!agg.containsKey(k)) {
              agg[k] = {'name': displayName, 'group': groupLabel};
            }
            final a = agg[k]!;
            for (final field in r.keys) {
              if (field == 'name' ||
                  field == 'group' ||
                  field == 'supplierProductCode' ||
                  field == 'supplier_product_code') {
                continue;
              }
              final v = r[field];
              if (v is num) {
                a[field] = ((a[field] as num?)?.toDouble() ?? 0) + v.toDouble();
              } else if (!a.containsKey(field)) {
                a[field] = v;
              }
            }
          }
        });
        final list = agg.values.toList();
        list.sort((a, b) {
          final pa = (a['profit'] as num?)?.toDouble() ?? 0;
          final pb = (b['profit'] as num?)?.toDouble() ?? 0;
          return pb.compareTo(pa);
        });
        return list;
      }
      return const [];
    }

    // 分类 sub-tabs → 从对应 base rows 按 group 聚合
    final baseKey = switch (subTabKey) {
      'productCategory' => 'product',
      'supplyCategory' => 'supply',
      'channelCategory' => 'channel',
      _ => '',
    };
    if (baseKey.isEmpty) return const [];

    final baseRaw = viewDict[baseKey];
    if (baseRaw is! List) return const [];

    // 按 group 桶排 —— group 就是"能源/中石油/平安…"这类一级分类标签
    final agg = <String, Map<String, dynamic>>{};
    for (final r in baseRaw.whereType<Map>()) {
      final group = r['group']?.toString().trim() ?? '';
      final bucketKey = group.isEmpty ? '未分类' : group;
      if (!agg.containsKey(bucketKey)) {
        // v10: 分类桶的展示名 = group 本身，group tag 留空避免"能源 · 能源"重复
        agg[bucketKey] = {'name': bucketKey, 'group': ''};
      }
      final a = agg[bucketKey]!;
      for (final field in r.keys) {
        if (field == 'name' || field == 'group') continue;
        final v = r[field];
        if (v is num) {
          a[field] = ((a[field] as num?)?.toDouble() ?? 0) + v.toDouble();
        } else if (!a.containsKey(field)) {
          a[field] = v;
        }
      }
    }
    final list = agg.values.toList();
    list.sort((a, b) {
      final pa = (a['profit'] as num?)?.toDouble() ?? 0;
      final pb = (b['profit'] as num?)?.toDouble() ?? 0;
      return pb.compareTo(pa);
    });
    return list;
  }

  Widget _buildDetailView() {
    final key = _detailKey ?? '';
    final type = _detailType ?? 'product';
    final detailKeyStr = '$type:$key';
    final currentPeriodKey = _detailPeriodCacheKey;
    final autoLoadKey = '$detailKeyStr|$currentPeriodKey';

    // Retrieve the detail dict for this entity
    Map<String, dynamic>? detailDict = _detailEntityMap(type, key);

    // 过期 / 未水合检测：
    // · overview 内嵌的 detail 没有走 /detail，不含 L3 过滤走势；
    // · 或外面改了 period 但内存 detail 仍是旧周期。
    // 继续渲染现有数据，后台拉 /detail 补齐（含 drill.trend），避免白屏闪烁。
    if (detailDict != null) {
      final loadedFor = _detailLoadedFor[detailKeyStr];
      if (loadedFor != currentPeriodKey &&
          _autoDetailAttempts.add(autoLoadKey)) {
        WidgetsBinding.instance.addPostFrameCallback((_) {
          if (mounted &&
              _detailKey == key &&
              _detailType == type &&
              _detailPeriodCacheKey == currentPeriodKey) {
            unawaited(_loadDetail(type, key));
          }
        });
      }
    }

    if (detailDict == null) {
      // 首次进入 detail —— 触发一次 load (幂等: 内部有 _loadingDetails 去重)
      if (_autoDetailAttempts.add(autoLoadKey)) {
        WidgetsBinding.instance.addPostFrameCallback((_) {
          if (mounted &&
              _detailKey == key &&
              _detailType == type &&
              _detailPeriodCacheKey == currentPeriodKey) {
            unawaited(_loadDetail(type, key));
          }
        });
      }
      return _buildDetailLoadingSkeleton(
        error: _detailErrors[autoLoadKey],
        onRetry: () {
          setState(() => _detailErrors.remove(autoLoadKey));
          unawaited(_loadDetail(type, key));
        },
      );
    }

    final pendingEquityProject = _equityPendingProject;
    if (pendingEquityProject != null &&
        pendingEquityProject.key == key &&
        type == 'product') {
      if (pendingEquityProject.period == currentPeriodKey &&
          _detailLoadedFor[detailKeyStr] == currentPeriodKey) {
        WidgetsBinding.instance.addPostFrameCallback((_) {
          _resolveEquityProjectDrill(pendingEquityProject);
        });
      }
      return _buildDetailLoadingSkeleton(
        error: _detailErrors[autoLoadKey],
        onRetry: () => unawaited(_loadDetail(type, key)),
      );
    }

    final isDrill = _drillKey != null && _drillDim != null;

    if (!isDrill &&
        !_detailHasDrillMaps(detailDict) &&
        !_detailDrillReloadAttempted &&
        !_detailDrillRefreshPending &&
        !_loading) {
      _detailDrillReloadAttempted = true;
      WidgetsBinding.instance.addPostFrameCallback((_) {
        _ensureDetailDrillData();
      });
    }

    Map<String, dynamic> viewDict = detailDict;
    if (isDrill) {
      final drillRoot = _detailDrillRoot(detailDict, _drillDim!);
      final drillPayload = drillRoot?[_drillKey!];
      if (drillPayload is Map) {
        viewDict = Map<String, dynamic>.from(drillPayload);
      } else {
        WidgetsBinding.instance.addPostFrameCallback((_) {
          setState(() {
            _resetDetailDrill();
            _detailPage = 1;
            _resetDetailSkuSearch();
          });
        });
        return const SizedBox();
      }
    }

    final rootDisplayName = key.contains('::') ? key.split('::').first : key;
    final rootGroupLabel = key.contains('::')
        ? key.substring(key.indexOf('::') + 2)
        : '';

    final isCodeDrill = _codeDrillKey != null;
    if (isCodeDrill) {
      return _buildSupplierCodeDrillView(
        type: type,
        detailDict: detailDict,
        viewDict: viewDict,
        rootDisplayName: rootDisplayName,
        rootGroupLabel: rootGroupLabel,
        isDrill: isDrill,
      );
    }

    // 二级汇总：一律直读详情接口 payload（L2/L3），禁止回退列表行拼凑。
    final summaryEntity = Map<String, dynamic>.from(viewDict);

    final rawProductL3 = detailDict[lighthouseProductL3SubTab];
    final hasProductL3 =
        type == 'product' && rawProductL3 is List && rawProductL3.isNotEmpty;
    final productL3Key = type == 'product'
        ? lighthouseParseProductL3Key(key)
        : null;
    final subTabList = isDrill
        ? _drillSubTabsFor(_drillDim!)
        : [
            for (final t
                in (_kDetailSubTabs[type] ?? _kDetailSubTabs['product']!))
              if (t.key != lighthouseProductL3SubTab || hasProductL3) t,
          ];
    // Ensure _detailSubTab is valid for this type
    if (!subTabList.any((t) => t.key == _detailSubTab)) {
      _detailSubTab = subTabList.first.key;
    }
    // 预拉当前维 + 根维 trend，供 Hero / 行展开回填（幂等）
    WidgetsBinding.instance.addPostFrameCallback((_) {
      if (!mounted || _detailKey == null) return;
      _ensureTrendLoaded(type);
      if (type != 'people' && _detailSubTab != 'people') {
        _ensureTrendLoaded(_detailSubTab);
        if (_drillDim != null && _drillDim != 'people') {
          _ensureTrendLoaded(_drillDim!);
        }
      }
    });

    // Same metrics source as main list (HTML: state.metrics[type])

    // Sub-tab rows (aggregated by name, sorted by profit desc)
    //
    // v11 · 分类 tab 已从 UI 移除 (see _kDetailSubTabs)，但客户端聚合路径
    //       保留 —— 后端将来若下发 view_dict[productCategory] 等键，
    //       走同一入口不需要改。当前 UI 里只会用到 supplierCode 分支。
    // v12 · L2/L3 子列表按 name 合并，不再用 name::group 拆行。
    //       一级分类筛选只在 L1 有意义；二级再挂「中石化/(未分类)」会把同省拆成双行。
    final subRows = <Map<String, dynamic>>[];
    const aggregatedSubTabs = {
      'supplierCode',
      'productCategory',
      'supplyCategory',
      'channelCategory',
    };

    if (aggregatedSubTabs.contains(_detailSubTab)) {
      subRows.addAll(
        _aggregateSubRowsForKey(viewDict, detailDict, _detailSubTab),
      );
    } else {
      final rawSubRows = viewDict[_detailSubTab];
      if (rawSubRows is List) {
        // Aggregate by name only（兼容旧网关仍下发带 group 的拆行）。
        // group 仅在同名行分类一致时保留，供 product_drill / sku_drill 进 L3。
        final agg = <String, Map<String, dynamic>>{};
        for (final r in rawSubRows.cast<Map<String, dynamic>>()) {
          final name = r['name']?.toString() ?? '';
          if (name.isEmpty) continue;
          if (!agg.containsKey(name)) {
            agg[name] = {'name': name, 'group': r['group']?.toString() ?? ''};
          } else {
            final a = agg[name]!;
            a['group'] = lighthouseMergedSubRowGroup(
              a['group']?.toString(),
              r['group']?.toString(),
            );
          }
          final a = agg[name]!;
          for (final field in r.keys) {
            if (field == 'name' || field == 'group') continue;
            final raw = r[field];
            if (raw is num) {
              final v = raw.toDouble();
              a[field] = ((a[field] as num?)?.toDouble() ?? 0) + v;
            } else if (!a.containsKey(field)) {
              a[field] = raw;
            }
          }
        }
        subRows.addAll(agg.values);
        subRows.sort((a, b) {
          final pa = (a['profit'] as num?)?.toDouble() ?? 0;
          final pb = (b['profit'] as num?)?.toDouble() ?? 0;
          return pb.compareTo(pa);
        });
      }
    }

    final isSkuTab = _detailSubTab == 'productName';
    final filteredSubRows = isSkuTab && _detailSkuQuery.trim().isNotEmpty
        ? subRows.where((r) => _skuRowMatchesQuery(r, _detailSkuQuery)).toList()
        : subRows;

    // 路径条回答“从哪来”；这行带业务 Logo 的小标题回答“当前在哪”。
    // 维度放在开头，保证产品/供给/渠道能命中对应图标。
    final heroTitle = isDrill
        ? '${_detailDimLabel(_drillDim!)} · $rootDisplayName · $_drillDisplayName详情'
              '${_drillGroup.isNotEmpty ? ' · $_drillGroup' : ''}'
        : productL3Key != null
        ? '产品三级 · ${productL3Key.l2} › ${productL3Key.l3}详情'
        : '${_detailRootLabel(type)} · $rootDisplayName详情'
              '${rootGroupLabel.isNotEmpty ? ' · $rootGroupLabel' : ''}';

    return Column(
      children: [
        // ── Sticky header：仅保留返回、品牌与工具；层级路径移入 Hero 标题。
        _lhBand(
          shadow: true,
          padding: const EdgeInsets.fromLTRB(
            lighthouseHeroShellMarginH,
            10,
            8,
            8,
          ),
          child: Column(
            children: [
              Row(
                crossAxisAlignment: CrossAxisAlignment.center,
                children: [
                  _buildEditorialBackButton(
                    onDark: lighthouseTopBandDark,
                    onTap: () {
                      _handleInternalBack();
                    },
                  ),
                  const SizedBox(width: 10),
                  Text(
                    '灯塔',
                    style: LhTypography.sans(
                      size: 19,
                      weight: FontWeight.w500,
                      color: lighthouseTopBandDark
                          ? _kLhBandInkStrong
                          : DunesColors.resolve(
                              context,
                              const Color(0xFF7C5CE6),
                            ),
                      letterSpacing: -0.2,
                      context: context,
                    ),
                  ),
                  const SizedBox(width: 10),
                  Expanded(child: _buildTopIslands()),
                ],
              ),
            ],
          ),
        ),
        // 日 / 周 / 月 / 季 / 年 与一级一样钉在滚动区外面。
        // 二级、三级、产品三级共用这一页，往下看账本时日期不跟着走。
        _buildPinnedPeriodBar(),

        Expanded(
          child: _softReloadDim(
            _LhPinnedScrollShade(
              child: ListView(
                padding: EdgeInsets.only(
                  bottom: _bottomNavScrollPadding(context),
                ),
                children: [
                  // ── Hero：与一级同壳同版式；数值取详情 payload ──────────────
                  _buildHeroShell(
                    child: _buildHero(
                      totalsOverride: _heroTotalsFromRow(summaryEntity),
                      profitDeltaOverride: _profitDeltaFromRow(summaryEntity),
                      profitSeriesOverride: _profitSeriesFromRow(summaryEntity),
                      profitLabelsOverride: _trendLabelsFromRow(summaryEntity),
                      summaryTitle: heroTitle,
                      summaryTitleWidget: _buildDetailBreadcrumb(
                        type: type,
                        rootDisplayName: rootDisplayName,
                        rootGroupLabel: rootGroupLabel,
                        isDrill: isDrill,
                      ),
                      showFilters: false,
                    ),
                  ),

                  const SizedBox(height: 10),

                  // ── 供给二级（省）：本省总资产 + 资产走势，跟一级那张同一块卡 ──
                  if (type == 'supply' && !isDrill && productL3Key == null)
                    Builder(
                      builder: (context) {
                        final lines = _provinceAssetLines(rootDisplayName);
                        if (lines.isEmpty) return const SizedBox.shrink();
                        return Padding(
                          padding: const EdgeInsets.fromLTRB(
                            lighthouseHeroShellMarginH,
                            0,
                            lighthouseHeroShellMarginH,
                            12,
                          ),
                          child: _buildSupplyAssetOverview(
                            const <Map<String, dynamic>>[],
                            provinceLines: lines,
                            provinceTitle: rootDisplayName,
                          ),
                        );
                      },
                    ),

                  // ── 与一级同款白卡：维度段（无分类）· 选区间/指标 · 账本 ──
                  Container(
                    margin: const EdgeInsets.fromLTRB(
                      lighthouseHeroShellMarginH,
                      0,
                      lighthouseHeroShellMarginH,
                      18,
                    ),
                    decoration: BoxDecoration(
                      color: DunesColors.resolve(
                        context,
                        Colors.white,
                        role: DunesColorRole.surface,
                      ),
                      border: Border.all(
                        color: DunesColors.resolve(
                          context,
                          _LhPlum.line,
                          role: DunesColorRole.border,
                        ),
                        width: 0.5,
                      ),
                      borderRadius: BorderRadius.circular(14),
                      boxShadow: [
                        BoxShadow(
                          color: LhColors.ink.withAlpha(10),
                          blurRadius: 10,
                          spreadRadius: -4,
                          offset: const Offset(0, 3),
                        ),
                      ],
                    ),
                    clipBehavior: Clip.antiAlias,
                    child: Column(
                      crossAxisAlignment: CrossAxisAlignment.stretch,
                      children: [
                        _buildDetailSubTabSegment(
                          subTabList: subTabList,
                          viewDict: viewDict,
                          activeSubRows: subRows,
                        ),
                        if (isSkuTab) _buildDetailSkuSearchBar(),
                        _buildSortbar(anchorScope: _detailRouteKey()),
                        Container(
                          height: 1,
                          color: DunesColors.resolve(
                            context,
                            _LhPlum.line,
                            role: DunesColorRole.surface,
                          ),
                        ),
                        if (filteredSubRows.isEmpty)
                          Padding(
                            padding: const EdgeInsets.symmetric(vertical: 40),
                            child: Center(
                              child: Text(
                                isSkuTab && _detailSkuQuery.trim().isNotEmpty
                                    ? '无匹配 SKU'
                                    : '暂无数据',
                                style: LhTypography.sans(
                                  size: 12,
                                  color: DunesColors.resolve(
                                    context,
                                    LhColors.mute,
                                  ),
                                  context: context,
                                ),
                              ),
                            ),
                          )
                        else
                          Builder(
                            builder: (context) {
                              final metricsTab = type;
                              final sorted =
                                  List<Map<String, dynamic>>.from(
                                    filteredSubRows,
                                  )..sort((a, b) {
                                    final pa = _rowMetricValue(a, _sortField);
                                    final pb = _rowMetricValue(b, _sortField);
                                    return _sortDesc
                                        ? pb.compareTo(pa)
                                        : pa.compareTo(pb);
                                  });
                              final totalPages = _totalPages(sorted.length);
                              // 权益落点可能不在第一页 —— 翻到它那页，只翻一次。
                              _maybePageToEquityFocus(sorted, totalPages);
                              final page = _detailPage.clamp(1, totalPages);
                              final start = (page - 1) * _pageSize;
                              final end = (start + _pageSize).clamp(
                                0,
                                sorted.length,
                              );
                              final visible = sorted
                                  .sublist(start, end)
                                  .map(_rowWithResolvedTrend)
                                  .toList();
                              final isSupplierCodeSubTab =
                                  _detailSubTab == 'supplierCode';
                              final isProductL3SubTab =
                                  _detailSubTab == lighthouseProductL3SubTab;
                              final canDrill =
                                  !(isDrill || isSupplierCodeSubTab);
                              final trendPrefix =
                                  'detail:$type:$key:${_detailSubTab}:${isDrill ? _drillKey : ''}';

                              return Column(
                                children: [
                                  _buildLedger(
                                    visible,
                                    shareRows: sorted,
                                    metricsTab: metricsTab,
                                    trendKeyPrefix: trendPrefix,
                                    showRowChevron: canDrill,
                                    allowDefaultDetailOpen: false,
                                    onRowTap: !canDrill
                                        ? null
                                        : isProductL3SubTab
                                        // 三级行进的是整页三级详情，不是交叉维 drill。
                                        ? (row) => _openProductL3Detail(
                                            l3: row['name']?.toString() ?? '',
                                            l1:
                                                (detailDict['group']
                                                            ?.toString() ??
                                                        '')
                                                    .isNotEmpty
                                                ? detailDict['group'].toString()
                                                : rootGroupLabel,
                                            l2: rootDisplayName,
                                          )
                                        : (row) => _openDetailDrill(
                                            detailDict: detailDict,
                                            dim: _detailSubTab,
                                            row: row,
                                          ),
                                  ),
                                  if (totalPages > 1)
                                    Padding(
                                      padding: const EdgeInsets.fromLTRB(
                                        14,
                                        8,
                                        14,
                                        12,
                                      ),
                                      child: _buildPageBar(
                                        currentPage: page,
                                        totalPages: totalPages,
                                        onPageSelected: (p) => setState(() {
                                          _clearEquityFocus();
                                          _detailPage = p;
                                        }),
                                      ),
                                    ),
                                ],
                              );
                            },
                          ),
                      ],
                    ),
                  ),

                  _buildFooter(),
                ],
              ),
            ),
          ),
        ),
      ],
    );
  }

  // ───── Level-4: supplier_product_code drill-down ──────────────────────────
  Widget _buildSupplierCodeDrillView({
    required String type,
    required Map<String, dynamic> detailDict,
    required Map<String, dynamic> viewDict,
    required String rootDisplayName,
    required String rootGroupLabel,
    required bool isDrill,
  }) {
    final rows = _supplierCodeDrillRows(viewDict, _codeDrillKey!);
    final sortedRows = List<Map<String, dynamic>>.from(rows)
      ..sort((a, b) {
        final pa = (a['profit'] as num?)?.toDouble() ?? 0;
        final pb = (b['profit'] as num?)?.toDouble() ?? 0;
        return pb.compareTo(pa);
      });

    double sumSales = 0, sumProfit = 0;
    for (final r in sortedRows) {
      sumSales += (r['sales'] as num?)?.toDouble() ?? 0;
      sumProfit += (r['profit'] as num?)?.toDouble() ?? 0;
    }

    final eyebrow = '四级明细 · SUPPLIER PRODUCT CODE';

    return Column(
      children: [
        // ── Sticky header — 对齐一级 AppBar 布局 ──────────────────────────
        _lhBand(
          shadow: true,
          padding: const EdgeInsets.fromLTRB(
            lighthouseHeroShellMarginH,
            10,
            8,
            6,
          ),
          child: Row(
            crossAxisAlignment: CrossAxisAlignment.center,
            children: [
              _buildEditorialBackButton(
                onDark: lighthouseTopBandDark,
                onTap: () {
                  _closeDropdown();
                  setState(() {
                    _resetCodeDrill();
                    _detailPage = 1;
