  // ── B. 成本结构条 ──────────────────────────────────────────────────────
  Widget _buildAnalysisCostStack(Map<String, dynamic> r, String type) {
    final sales = (r['sales'] as num?)?.toDouble() ?? 0;
    if (sales <= 0) return const SizedBox.shrink();

    final cost = ((r['cost'] as num?)?.toDouble() ?? 0).clamp(
      0.0,
      double.infinity,
    );
    final tax = ((r['tax'] as num?)?.toDouble() ?? 0).clamp(
      0.0,
      double.infinity,
    );
    final saas = ((r['saasFee'] as num?)?.toDouble() ?? 0).clamp(
      0.0,
      double.infinity,
    );
    final profit = ((r['profit'] as num?)?.toDouble() ?? 0).clamp(
      0.0,
      double.infinity,
    );

    // 4 段：业务 / 税 / SaaS / 利润；占比统一以销售额为分母
    final segments = <({String label, double value, Color color})>[
      (
        label: '业务',
        value: cost,
        color: DunesColors.resolve(context, const Color(0xFFD05568)),
      ),
      (
        label: '税务',
        value: tax,
        color: DunesColors.resolve(context, const Color(0xFF8A6FE0)),
      ),
      if (saas > 0)
        (
          label: 'SaaS',
          value: saas,
          color: DunesColors.resolve(context, const Color(0xFFC9842A)),
        ),
      (
        label: '利润',
        value: profit,
        color: DunesColors.resolve(context, LhColors.pos),
      ),
    ];
    final barTotal = segments.fold<double>(0, (s, x) => s + x.value);
    if (barTotal <= 0) return const SizedBox.shrink();

    return Column(
      crossAxisAlignment: CrossAxisAlignment.start,
      children: [
        Row(
          children: [
            Text(
              '成本结构',
              style: LhTypography.sans(
                size: 11,
                color: DunesColors.resolve(context, LhColors.ink2),
                weight: FontWeight.w600,
                letterSpacing: 0.2,
                context: context,
              ),
            ),
            const Spacer(),
            Text(
              '销售 ¥${_fmt(sales)}${_unit(sales)}',
              style: LhTypography.mono(
                size: 9.5,
                color: DunesColors.resolve(context, LhColors.mute),
                weight: FontWeight.w500,
                letterSpacing: 0.3,
                context: context,
              ),
            ),
          ],
        ),
        const SizedBox(height: 8),
        ClipRRect(
          borderRadius: BorderRadius.circular(2),
          child: SizedBox(
            height: 14,
            child: Row(
              children: [
                for (final s in segments)
                  Expanded(
                    flex: ((s.value / barTotal) * 10000).round().clamp(
                      1,
                      10000,
                    ),
                    child: Container(
                      color: DunesColors.resolveNullable(
                        context,
                        s.color,
                        role: DunesColorRole.surface,
                      ),
                    ),
                  ),
              ],
            ),
          ),
        ),
        const SizedBox(height: 9),
        Wrap(
          spacing: 11,
          runSpacing: 5,
          children: [
            for (final s in segments)
              Row(
                mainAxisSize: MainAxisSize.min,
                children: [
                  Container(
                    width: 7,
                    height: 7,
                    decoration: BoxDecoration(
                      color: DunesColors.resolveNullable(
                        context,
                        s.color,
                        role: DunesColorRole.surface,
                      ),
                      borderRadius: BorderRadius.circular(1),
                    ),
                  ),
                  const SizedBox(width: 5),
                  Text(
                    s.label,
                    style: LhTypography.sans(
                      size: 9.5,
                      color: DunesColors.resolve(context, LhColors.ink2),
                      weight: FontWeight.w500,
                      context: context,
                    ),
                  ),
                  const SizedBox(width: 4),
                  Text(
                    '${(s.value / sales * 100).toStringAsFixed(0)}%',
                    style: LhTypography.mono(
                      size: 9,
                      color: s.label == '利润'
                          ? DunesColors.resolve(context, LhColors.neg)
                          : DunesColors.resolve(context, LhColors.mute),
                      weight: FontWeight.w700,
                      letterSpacing: 0.2,
                      context: context,
                    ),
                  ),
                ],
              ),
          ],
        ),
      ],
    );
  }

  // ── C. 健康度 5 维 bars ────────────────────────────────────────────────
  Widget _buildAnalysisHealthBars(Map<String, dynamic> r, String type) {
    final h = _calcHealthScores(r, type);

    Color scoreColor(int s) {
      if (s >= 70) return DunesColors.resolve(context, LhColors.neg);
      if (s >= 40) return DunesColors.resolve(context, _LhPlum.primary);
      return DunesColors.resolve(context, LhColors.pos);
    }

    Widget bar(String label, int score) {
      final c = scoreColor(score);
      return Padding(
        padding: const EdgeInsets.symmetric(vertical: 3),
        child: Row(
          children: [
            SizedBox(
              width: 60,
              child: Text(
                label,
                style: LhTypography.sans(
                  size: 10,
                  color: DunesColors.resolve(context, LhColors.ink2),
                  weight: FontWeight.w500,
                  context: context,
                ),
              ),
            ),
            Expanded(
              child: Stack(
                children: [
                  Container(
                    height: 5,
                    decoration: BoxDecoration(
                      color: DunesColors.resolve(
                        context,
                        LhColors.line2,
                        role: DunesColorRole.surface,
                      ),
                      borderRadius: BorderRadius.circular(2.5),
                    ),
                  ),
                  FractionallySizedBox(
                    widthFactor: (score / 100).clamp(0.0, 1.0),
                    child: Container(
                      height: 5,
                      decoration: BoxDecoration(
                        color: DunesColors.resolveNullable(
                          context,
                          c,
                          role: DunesColorRole.surface,
                        ),
                        borderRadius: BorderRadius.circular(2.5),
                      ),
                    ),
                  ),
                ],
              ),
            ),
            const SizedBox(width: 8),
            SizedBox(
              width: 22,
              child: Text(
                '$score',
                textAlign: TextAlign.right,
                style: LhTypography.mono(
                  size: 10,
                  color: c,
                  weight: FontWeight.w700,
                  letterSpacing: 0.3,
                  context: context,
                ),
              ),
            ),
          ],
        ),
      );
    }

    return Column(
      crossAxisAlignment: CrossAxisAlignment.start,
      children: [
        Row(
          crossAxisAlignment: CrossAxisAlignment.baseline,
          textBaseline: TextBaseline.alphabetic,
          children: [
            Text(
              '健康度',
              style: LhTypography.sans(
                size: 11,
                color: DunesColors.resolve(context, LhColors.ink2),
                weight: FontWeight.w600,
                letterSpacing: 0.2,
                context: context,
              ),
            ),
            const Spacer(),
            Text(
              '${h.score}',
              style: LhTypography.sans(
                size: 14,
                color: scoreColor(h.score),
                weight: FontWeight.w700,
                letterSpacing: -0.3,
                context: context,
              ),
            ),
            const SizedBox(width: 1),
            Text(
              '/100',
              style: LhTypography.mono(
                size: 9,
                color: DunesColors.resolve(context, LhColors.mute),
                weight: FontWeight.w500,
                letterSpacing: 0.3,
                context: context,
              ),
            ),
          ],
        ),
        const SizedBox(height: 6),
        bar('盈利能力', h.profit),
        bar('增长性', h.growth),
        bar('成本控制', h.cost),
        bar('运营效率', h.efficiency),
        bar('规模实力', h.scale),
      ],
    );
  }

  // ── D. 同组排名直方图 ──────────────────────────────────────────────────
  Widget _buildAnalysisRanking(Map<String, dynamic> r, String type) {
    final ranking = _calcGroupRanking(r, type);
    if (ranking.total == 0) return const SizedBox.shrink();

    final groupName = r['group']?.toString() ?? '';
    final rois = ranking.peers.map((p) => p.roi).toList();
    final maxRoi = rois.fold<double>(0, (m, v) => v > m ? v : m);
    final minRoi = rois.fold<double>(double.infinity, (m, v) => v < m ? v : m);
    final span = (maxRoi - minRoi).abs() < 0.001 ? 1.0 : (maxRoi - minRoi);

    return Column(
      crossAxisAlignment: CrossAxisAlignment.start,
      children: [
        Row(
          crossAxisAlignment: CrossAxisAlignment.baseline,
          textBaseline: TextBaseline.alphabetic,
          children: [
            Text(
              '同组对比',
              style: LhTypography.sans(
                size: 11,
                color: DunesColors.resolve(context, LhColors.ink2),
                weight: FontWeight.w600,
                letterSpacing: 0.2,
                context: context,
              ),
            ),
            const SizedBox(width: 6),
            Text(
              '· $groupName ${ranking.total} 家',
              style: LhTypography.mono(
                size: 9,
                color: DunesColors.resolve(context, LhColors.mute),
                weight: FontWeight.w500,
                letterSpacing: 0.3,
                context: context,
              ),
            ),
            const Spacer(),
            Text(
              '第 ${ranking.rank}/${ranking.total} · 前 ${ranking.percentile.toStringAsFixed(0)}%',
              style: LhTypography.mono(
                size: 10,
                color: DunesColors.resolve(context, _LhPlum.primary),
                weight: FontWeight.w700,
                letterSpacing: 0.3,
                context: context,
              ),
            ),
          ],
        ),
        const SizedBox(height: 10),
        SizedBox(
          height: 44,
          child: Row(
            crossAxisAlignment: CrossAxisAlignment.end,
            children: [
              for (final p in ranking.peers)
                Expanded(
                  child: Padding(
                    padding: const EdgeInsets.symmetric(horizontal: 1.5),
                    child: Column(
                      mainAxisAlignment: MainAxisAlignment.end,
                      crossAxisAlignment: CrossAxisAlignment.center,
                      children: [
                        Container(
                          height: ((p.roi - minRoi) / span * 32 + 4).clamp(
                            4.0,
                            36.0,
                          ),
                          decoration: BoxDecoration(
                            color: p.isMe
                                ? DunesColors.resolve(
                                    context,
                                    _LhPlum.primary,
                                    role: DunesColorRole.surface,
                                  )
                                : DunesColors.resolve(
                                    context,
                                    LhColors.mute2,
                                    role: DunesColorRole.surface,
                                  ).withAlpha(70),
                            borderRadius: const BorderRadius.vertical(
                              top: Radius.circular(1.5),
                            ),
                          ),
                        ),
                        const SizedBox(height: 3),
                        if (p.isMe)
                          Container(
                            width: 7,
                            height: 2,
                            decoration: BoxDecoration(
                              color: DunesColors.resolve(
                                context,
                                _LhPlum.primary,
                                role: DunesColorRole.surface,
                              ),
                              borderRadius: BorderRadius.circular(1),
                            ),
                          )
                        else
                          const SizedBox(height: 2),
                      ],
                    ),
                  ),
                ),
            ],
          ),
        ),
      ],
    );
  }

  // L2 详情 hero —— P&L 按钮网格 (跟 L1 主 hero 同款视觉)
  //
  // v9 编辑体 float —— L1 hero 同步版本
  //   • 3×2 语义结构 (income-side / cost-side ★efficiency)
  //   • 全撤 divider, whitespace 承担分栏分行
  //   • Row 2: 核销规模 · 成本(合计) · 效率(★)
  //   • 每格 accent 色编码语义 (紫=收入/核销侧 · 绿=成本 · 效率终点用主紫 ★)
  //
  // 数据源: 二级详情 payload 直读（禁止列表行 / 跨字段兜底）
  //   核销规模 → verifiedSales
  //   收入     → revenue
  //   销售额   → sales
  //   成本     → totalCost（= SUM(total_cost)）
  //   利润     → profit（效率分母随锚点开关）
  //   deltas 从 entity['deltas'][key] 直读
  // ═════════════════════════════════════════════════════════════════════════
  Widget _buildDetailPnlButtonGrid(Map<String, dynamic> entity) {
    final verified = (entity['verifiedSales'] as num?)?.toDouble() ?? 0.0;
    final sales = (entity['sales'] as num?)?.toDouble() ?? 0.0;
    final revenue = (entity['revenue'] as num?)?.toDouble() ?? 0.0;
    final totalCost = (entity['totalCost'] as num?)?.toDouble() ?? 0.0;
    final profit = (entity['profit'] as num?)?.toDouble() ?? 0.0;
    final anchor = _anchor == _LhAnchor.verified ? verified : sales;
    final anchorLabel = _anchor == _LhAnchor.verified ? '核销规模' : '销售规模';
    final spreadRate = anchor > 0 ? revenue / anchor * 100 : 0.0;
    final roiBase = lighthouseValidRateBase(
      totalCost,
      minimumBase: _kRoiAnchorMinYuan,
    );
    final rate = roiBase > 0 ? profit / roiBase * 100 : 0.0;

    // 从 entity 读环比 deltas (L2 侧后端下发结构)
    final deltas =
        (entity['deltas'] as Map?)?.cast<String, dynamic>() ?? const {};
    ({double pct, bool isUp})? deltaFor(String k) {
      final v = (deltas[k] as num?)?.toDouble();
      if (v == null || v.abs() < 1e-9) return null;
      // 与列表一致：保留后端带符号环比，禁止取绝对值
      return (pct: v, isUp: v >= 0);
    }

    return Column(
      crossAxisAlignment: CrossAxisAlignment.stretch,
      children: [
        // ─── Row 1: 利差率 · 收入 · 销售额 ───────────────────────
        IntrinsicHeight(
          child: Row(
            crossAxisAlignment: CrossAxisAlignment.stretch,
            children: [
              Expanded(
                child: _detailPnlButton(
                  label: '利差率',
                  subLabel: '收入 ÷ $anchorLabel',
                  value: spreadRate,
                  isRate: true,
                  accent: DunesColors.resolve(context, _LhPlum.primary),
                  delta: deltaFor('spreadRate'),
                  deltaUnit: 'pp',
                ),
              ),
              Expanded(
                child: _detailPnlButton(
                  label: '收入',
                  subLabel: '已核销利差',
                  value: revenue,
                  isRate: false,
                  accent: DunesColors.resolve(context, _LhPlum.primary),
                  delta: deltaFor('revenue'),
                  deltaUnit: '%',
                ),
              ),
              Expanded(
                child: _detailPnlButton(
                  label: '销售额',
                  subLabel: '销售规模',
                  value: sales,
                  isRate: false,
                  accent: DunesColors.resolve(context, _LhPlum.primary),
                  delta: deltaFor('sales'),
                  deltaUnit: '%',
                ),
              ),
            ],
          ),
        ),
        // v9: 22px whitespace 承担分行 (原 hairline 已撤)
        const SizedBox(height: 22),
        // ─── Row 2: 核销规模 · 成本(合计) · 效率(★) ────────────
        IntrinsicHeight(
          child: Row(
            crossAxisAlignment: CrossAxisAlignment.stretch,
            children: [
              Expanded(
                child: _detailPnlButton(
                  label: '核销规模',
                  subLabel: '核销额',
                  value: verified,
                  isRate: false,
                  accent: DunesColors.resolve(context, _LhPlum.primary),
                  delta: deltaFor('verifiedSales'),
                  deltaUnit: '%',
                ),
              ),
              Expanded(
                child: _detailPnlButton(
                  label: '成本',
                  subLabel: '成本合计',
                  value: totalCost,
                  isRate: false,
                  accent: DunesColors.resolve(context, LhColors.pos),
                  delta: deltaFor('totalCost'),
                  deltaUnit: '%',
                ),
              ),
              Expanded(
                child: _detailPnlButton(
                  label: 'ROI ★',
                  subLabel: '利润 ÷ 成本合计',
                  value: rate,
                  isRate: true,
                  accent: DunesColors.resolve(context, _LhPlum.primary),
                  delta: deltaFor('rate'),
                  deltaUnit: 'pp',
                ),
              ),
            ],
          ),
        ),
      ],
    );
  }

  /// L2 详情用 P&L 单元 —— _pnlButton v9 视觉复刻 (无 expand-trend state)
  ///   编辑体三行堆叠: Label / Number+Unit / Δ%
  ///   无 chrome, 无 FittedBox, 15px 固定数字大小 —— 全格节奏一致
  Widget _detailPnlButton({
    required String label,
    required String subLabel,
    required double value,
    required bool isRate,
    required Color accent,
    Color? valueColor,
    ({double pct, bool isUp})? delta,
    String deltaUnit = '%',
  }) {
    final fg = valueColor ?? DunesColors.resolve(context, LhColors.ink);
    final unitColor = isRate && valueColor != null
        ? valueColor
        : DunesColors.resolve(context, LhColors.ink2);
    final shownDelta =
        delta != null &&
            lighthouseDeltaPctShown(delta.pct, isRate: deltaUnit == 'pp')
        ? delta
        : null;
    final momCompact = shownDelta == null
        ? '—'
        : _fmtSignedMomPct(shownDelta.pct, unit: deltaUnit, digits: 1);
    final momColor = shownDelta == null
        ? DunesColors.resolve(context, LhColors.mute2)
        : (shownDelta.isUp
              ? DunesColors.resolve(context, LhColors.neg)
              : DunesColors.resolve(context, LhColors.pos));
    return Padding(
      // v10: 内边距 + 内容居中 (crossAxis center), 跟 L1 完全对齐
      padding: const EdgeInsets.symmetric(horizontal: 4, vertical: 4),
      child: Column(
        crossAxisAlignment: CrossAxisAlignment.center,
        mainAxisSize: MainAxisSize.min,
        children: [
          // ── ① Label (居中) ──
          _heroSemanticText(
            label,
            baseColor: DunesColors.resolve(context, LhColors.ink2),
            size: 11,
            baseWeight: FontWeight.w700,
            termWeight: FontWeight.w700,
            letterSpacing: 0.4,
          ),
          const SizedBox(height: 10),
          // ── ② 数字 + 单位 (居中) ──
          Row(
            mainAxisSize: MainAxisSize.min,
            mainAxisAlignment: MainAxisAlignment.center,
            crossAxisAlignment: CrossAxisAlignment.baseline,
            textBaseline: TextBaseline.alphabetic,
            children: [
              Text(
                isRate ? value.toStringAsFixed(2) : _fmtMoney(value),
                style: LhTypography.number(
                  size: 15,
                  color: fg,
                  context: context,
                ),
                maxLines: 1,
              ),
              const SizedBox(width: 2),
              Text(
                isRate ? '%' : _unitMoney(value),
                style: LhTypography.sans(
                  size: 9,
                  color: unitColor,
                  weight: FontWeight.w500,
                  context: context,
                ),
              ),
            ],
          ),
          const SizedBox(height: 6),
          // ── ③ 环比 (居中) ──
          LhScrollText(
            momCompact,
            textAlign: TextAlign.center,
            style: LhTypography.mono(
              size: 9.5,
              color: momColor,
              weight: FontWeight.w600,
              letterSpacing: 0.15,
              context: context,
            ),
            maxLines: 1,
            overflow: TextOverflow.ellipsis,
          ),
        ],
      ),
    );
  }

  Widget _buildDetailMiniGrid(
    List<_HeroMetric> metrics,
    Map<String, double> totals,
  ) {
    final n = metrics.length;
    // n=4 用 2 列 (2x2 更对称); n=3/6/其他 用 3 列
    final cols = (n == 4) ? 2 : 3;
    return LayoutBuilder(
      builder: (context, constraints) {
        final availW = constraints.maxWidth;
        const colGap = 12.0;
        final cw = (availW - colGap * (cols - 1)) / cols;

        final rows = <List<_HeroMetric>>[];
        for (int i = 0; i < n; i += cols) {
          rows.add(metrics.skip(i).take(cols).toList());
        }

        final widgets = <Widget>[];
        for (int r = 0; r < rows.length; r++) {
          final rowMetrics = rows[r];
          final rowCells = <Widget>[];
          for (int c = 0; c < cols; c++) {
            if (c < rowMetrics.length) {
              rowCells.add(_buildHeroCell(rowMetrics[c], totals, true, cw));
            } else {
              rowCells.add(SizedBox(width: cw));
            }
            if (c < cols - 1) rowCells.add(const SizedBox(width: colGap));
          }
          widgets.add(
            IntrinsicHeight(
              child: Row(
                crossAxisAlignment: CrossAxisAlignment.stretch,
                children: rowCells,
              ),
            ),
          );
          if (r < rows.length - 1) {
            widgets.add(
              Container(
                height: 1,
                margin: const EdgeInsets.symmetric(vertical: 11),
                color: DunesColors.resolve(
                  context,
                  LhColors.line2,
                  role: DunesColorRole.surface,
                ),
              ),
            );
          }
        }

        return Column(
          crossAxisAlignment: CrossAxisAlignment.start,
          children: widgets,
        );
      },
    );
  }

  Widget _buildDetailListItem(
    Map<String, dynamic> r,
    int idx,
    String type, {
    bool showSupplierCode = false,
    VoidCallback? onDrillTap,
  }) {
    final name = r['name']?.toString() ?? '';
    final group = r['group']?.toString() ?? '';
    final profit = (r['profit'] as num?)?.toDouble() ?? 0;
    final isNeg = profit < 0;
    final rank = (idx + 1).toString().padLeft(2, '0');
    final groupColor = lhGroupColor(group);

    // ROI = 利润 ÷ 成本合计；成本合计≈0 的行不出数（显示「—」）
    final roiAnchor = _roiAnchor(r);
    final hasRate = roiAnchor != 0;
    final rateValue = hasRate ? _rowRoiPct(r) : 0.0;

    // Meta row — v12 · 跟一级页面 (_buildLedger) 完全对齐：排除 discount+profit。
    //   之前只排除 discount, 结果利润在右栏和 meta 条里各出现一次;
    //   用户明确要求"底下显示的字段要跟一级页面统一", 一律以 L1 filter 为准。
    final metaItems = <_MetaItem>[];
    for (final k in (_metrics[type] ?? []).where(
      (key) => key != 'discount' && key != 'profit',
    )) {
      final v = _rowMetricValue(r, k);
      metaItems.add(
        _MetaItem(k, _metricShort(k, tab: type), _fmtAmountWithUnit(v)),
      );
    }

    final tagColors = _groupTagColors(group);
    final tagBg = tagColors.bg;
    final tagFg = tagColors.fg;
    final supplierCode = (r['supplierProductCode'] as String?)?.trim() ?? '';

    return Material(
      color: Colors.transparent,
      child: InkWell(
        onTap: onDrillTap,
        borderRadius: BorderRadius.circular(7),
        child: Container(
          margin: const EdgeInsets.only(bottom: 8),
          padding: const EdgeInsets.fromLTRB(11, 9, 11, 9),
          decoration: BoxDecoration(
            // v3.7: 二级页面卡片跟主列表 v3.6 完全同族（旧版记录）
            // v2 淡紫改造：跟主列表 v2 一致（旧版记录）
            // v2.1 气泡感：白→_LhPlum.mist 极轻 2-stop 竖向渐变 + 加深深紫墨影
            gradient: LinearGradient(
              begin: Alignment.topCenter,
              end: Alignment.bottomCenter,
              colors: [
                DunesColors.resolve(
                  context,
                  Colors.white,
                  role: DunesColorRole.surface,
                ),
                DunesColors.resolve(
                  context,
                  _LhPlum.mist,
                  role: DunesColorRole.surface,
                ),
              ],
              stops: const [0.0, 1.0],
            ),
            border: Border.all(
              color: DunesColors.resolve(
                context,
                _LhPlum.lavender,
                role: DunesColorRole.border,
              ),
              width: 1,
            ),
            borderRadius: BorderRadius.circular(14),
            boxShadow: [
              BoxShadow(
                color: _LhPlum.deep.withAlpha(20),
                blurRadius: 14,
                spreadRadius: -4,
                offset: const Offset(0, 4),
              ),
            ],
          ),
          child: Row(
            crossAxisAlignment: CrossAxisAlignment.start,
            children: [
              // Rank — 复用主列表的 v3.6 rank helper (pure mono typography)
              _buildListRankBadge(rank, index: idx),
              const SizedBox(width: 9),
              // Main
              Expanded(
                child: Column(
                  crossAxisAlignment: CrossAxisAlignment.start,
                  children: [
                    Wrap(
                      crossAxisAlignment: WrapCrossAlignment.center,
                      spacing: 6,
                      runSpacing: 4,
                      children: [
                        LhScrollRichText(
                          text: TextSpan(
                            children: [
                              TextSpan(
                                text: name,
                                style: LhTypography.sans(
                                  size: 11.2,
                                  weight: FontWeight.w700,
                                  color: DunesColors.resolve(
                                    context,
                                    LhColors.ink,
                                  ),
                                  height: 1.2,
                                  letterSpacing: -0.1,
                                  context: context,
