}

/// Owner 聚合统计（用于 owner strip 显示）
class _OwnerStat {
  int count = 0;
  double totalValue = 0;
}

/// 按「产品组（sync_source 映射）」把坐标派生到负责人（mock）：
///   能源 / 能源积分返费 → 王一凡
///   运营商 → 石淼 / 徐峥（按供给方名稳定二分）
///   其他   → ""（未分配）
String _deriveCubeOwner(String productGroup, String supplyName) {
  switch (productGroup) {
    case '能源':
    case '能源积分返费':
      return '王一凡';
    case '运营商':
      return supplyName.isEmpty || supplyName.hashCode.isEven ? '石淼' : '徐峥';
    default:
      return '';
  }
}

